-- Empty, explicitly acknowledged STAGING database only.
-- Schema-only snapshot; contains no business/user/credential/Vault rows.
-- Source: verified local database, 2026-10-01. No historical migration ledger is fabricated.
begin;
do $$ begin
 if current_setting('vibe.environment',true) is distinct from 'staging' then
  raise exception 'Explicit staging database acknowledgement required';
 end if;
 if to_regclass('public.profiles') is not null or to_regclass('public.tuition_reminders') is not null then
  raise exception 'Bootstrap requires an EMPTY application database';
 end if;
end $$;
create schema if not exists extensions;
