CREATE OR REPLACE FUNCTION "finance_private"."allocate_refund_to_payment_allocation"("p_refund_id" "uuid", "p_payment_allocation_id" "uuid", "p_amount" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_refund public.refunds%rowtype;

  v_payment_allocation public.payment_allocations%rowtype;

  v_refund_allocated numeric(14,2);

  v_payment_allocation_refunded numeric(14,2);

  v_refund_allocation_id uuid :=
    gen_random_uuid();
begin



  if p_refund_id is null
    or p_payment_allocation_id is null
  then
    raise exception
      'Refund id and payment allocation id are required';
  end if;


  if p_amount is null
    or p_amount <= 0
  then
    raise exception
      'Refund allocation amount must be greater than zero';
  end if;


  select *
  into v_refund
  from public.refunds
  where id = p_refund_id
  for update;


  if not found then
    raise exception
      'Refund not found';
  end if;


  if v_refund.status <>
    'POSTED'
  then
    raise exception
      'Only posted refunds can be allocated';
  end if;


  select *
  into v_payment_allocation
  from public.payment_allocations
  where id =
    p_payment_allocation_id;


  if not found then
    raise exception
      'Payment allocation not found';
  end if;


  if v_payment_allocation.payment_id <>
    v_refund.payment_id
  then
    raise exception
      'Refund must be allocated against its original payment';
  end if;


  if exists (
    select 1
    from public.refund_allocations
    where refund_id =
      p_refund_id
      and payment_allocation_id =
        p_payment_allocation_id
  )
  then
    raise exception
      'This refund is already allocated to this payment allocation';
  end if;


  select coalesce(
    sum(allocation.amount),
    0
  )
  into v_refund_allocated
  from public.refund_allocations
    as allocation
  where allocation.refund_id =
    p_refund_id;


  if v_refund_allocated
      + p_amount
      > v_refund.amount
  then
    raise exception
      'Refund allocation exceeds the refund amount';
  end if;


  select coalesce(
    sum(refund_allocation.amount),
    0
  )
  into v_payment_allocation_refunded
  from public.refund_allocations
    as refund_allocation

  join public.refunds
    as refund
    on refund.id =
      refund_allocation.refund_id

  where refund_allocation.payment_allocation_id =
    p_payment_allocation_id

    and refund.status =
      'POSTED';


  if v_payment_allocation_refunded
      + p_amount
      > v_payment_allocation.amount
  then
    raise exception
      'Refund exceeds the original payment allocation amount';
  end if;


  insert into public.refund_allocations (
    id,
    refund_id,
    payment_allocation_id,
    amount
  )
  values (
    v_refund_allocation_id,
    p_refund_id,
    p_payment_allocation_id,
    p_amount
  );


  return v_refund_allocation_id;
end;
$$;


ALTER FUNCTION "finance_private"."allocate_refund_to_payment_allocation"("p_refund_id" "uuid", "p_payment_allocation_id" "uuid", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "finance_private"."cancel_invoice"("p_invoice_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_status text;
begin



  if p_invoice_id is null then
    raise exception
      'Invoice id is required';
  end if;


  if p_reason is null
    or btrim(p_reason) = ''
  then
    raise exception
      'Invoice cancellation reason is required';
  end if;


  select invoice.status
  into v_status
  from public.invoices as invoice
  where invoice.id =
    p_invoice_id
  for update;


  if not found then
    raise exception
      'Invoice not found';
  end if;


  if v_status not in (
    'DRAFT',
    'ISSUED'
  ) then
    raise exception
      'Only draft or issued invoices can be cancelled';
  end if;


  update public.invoices
  set
    status = 'CANCELLED',
    cancelled_at = now(),
    cancelled_by = auth.uid(),
    cancel_reason =
      btrim(p_reason)
  where id =
    p_invoice_id;
end;
$$;


ALTER FUNCTION "finance_private"."cancel_invoice"("p_invoice_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "finance_private"."create_refund"("p_payment_id" "uuid", "p_amount" numeric, "p_refunded_at" timestamp with time zone, "p_reason" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_payment public.payments%rowtype;

  v_existing_refunds numeric(14,2);

  v_refund_id uuid :=
    gen_random_uuid();

  v_refund_number text;
begin



  if p_payment_id is null then
    raise exception
      'Payment id is required';
  end if;


  if p_amount is null
    or p_amount <= 0
  then
    raise exception
      'Refund amount must be greater than zero';
  end if;


  if p_refunded_at is null then
    raise exception
      'Refund date is required';
  end if;


  if p_reason is null
    or btrim(p_reason) = ''
  then
    raise exception
      'Refund reason is required';
  end if;


  select *
  into v_payment
  from public.payments
  where id = p_payment_id
  for update;


  if not found then
    raise exception
      'Payment not found';
  end if;


  if v_payment.status <>
    'POSTED'
  then
    raise exception
      'Only posted payments can be refunded';
  end if;


  select coalesce(
    sum(refund.amount),
    0
  )
  into v_existing_refunds
  from public.refunds
    as refund
  where refund.payment_id =
    p_payment_id
    and refund.status =
      'POSTED';


  if v_existing_refunds
      + p_amount
      > v_payment.amount
  then
    raise exception
      'Refund exceeds the remaining refundable payment amount';
  end if;


  v_refund_number :=
    'REF-'
    || to_char(
      timezone(
        'Asia/Ho_Chi_Minh',
        now()
      ),
      'YYYY'
    )
    || '-'
    || lpad(
      nextval(
        'public.refund_number_seq'
      )::text,
      6,
      '0'
    );


  insert into public.refunds (
    id,
    refund_number,
    payment_id,
    student_id_snapshot,
    branch_id_snapshot,
    branch_code_snapshot,
    branch_name_snapshot,
    amount,
    currency,
    refunded_at,
    reason,
    notes,
    status
  )
  values (
    v_refund_id,
    v_refund_number,
    v_payment.id,
    v_payment.student_id_snapshot,
    v_payment.branch_id_snapshot,
    v_payment.branch_code_snapshot,
    v_payment.branch_name_snapshot,
    p_amount,
    v_payment.currency,
    p_refunded_at,
    btrim(p_reason),
    nullif(
      btrim(
        coalesce(
          p_notes,
          ''
        )
      ),
      ''
    ),
    'POSTED'
  );


  return v_refund_id;
end;
$$;


ALTER FUNCTION "finance_private"."create_refund"("p_payment_id" "uuid", "p_amount" numeric, "p_refunded_at" timestamp with time zone, "p_reason" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "finance_private"."guard_approval_history"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
 if tg_table_name<>'financial_approval_requests' or tg_op='DELETE' then raise exception 'Financial approval history is immutable'; end if;
 if (to_jsonb(new)-array['status','approver_user_id','approved_at','posted_at','result_id']) is distinct from
 (to_jsonb(old)-array['status','approver_user_id','approved_at','posted_at','result_id'])
 or not ((old.status='PENDING_APPROVAL' and new.status in ('APPROVED','CANCELLED')) or (old.status='APPROVED' and new.status='POSTED'))
 then raise exception 'Financial approval history is immutable'; end if;
 return new;
end $$;


ALTER FUNCTION "finance_private"."guard_approval_history"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "finance_private"."guard_credit_refund"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare reserved numeric; refunded numeric;
begin
 select coalesce(sum(remaining_credit),0) into reserved from public.customer_credit_balances where payment_id=new.payment_id;
 select coalesce(sum(amount),0) into refunded from public.refunds where payment_id=new.payment_id and status='POSTED';
 if new.amount>(select amount from public.payments where id=new.payment_id)-refunded-reserved then
  if not exists(select 1 from public.financial_approval_requests r where r.operation='REFUND_CUSTOMER_CREDIT' and r.status='APPROVED'
   and r.approver_user_id=auth.uid() and (r.source_snapshot->'credit'->>'payment_id')::uuid=new.payment_id and (r.details->>'amount')::numeric=new.amount
   and not exists(select 1 from public.customer_credit_uses u where u.id=r.id)) then raise exception 'Use approved customer credit refund'; end if;
 end if;
 return new;
end $$;


ALTER FUNCTION "finance_private"."guard_credit_refund"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "finance_private"."guard_credit_refund_allocation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare used numeric; available numeric;
begin
 if exists(select 1 from public.customer_credit_uses where refund_id=new.refund_id) then raise exception 'Credit refund cannot be allocated again'; end if;
 select effective_amount into available from public.payment_allocation_effective where id=new.payment_allocation_id;
 select coalesce(sum(a.amount),0) into used from public.refund_allocations a join public.refunds r on r.id=a.refund_id and r.status='POSTED' where a.payment_allocation_id=new.payment_allocation_id;
 if used+new.amount>available then raise exception 'Refund exceeds effective allocation'; end if;
 return new;
end $$;


ALTER FUNCTION "finance_private"."guard_credit_refund_allocation"() OWNER TO "postgres";


