CREATE OR REPLACE FUNCTION "finance_private"."guard_opening_refund_void"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare target uuid; correction uuid; cause uuid;
begin
 if new.status='VOIDED' and old.status='POSTED' then
  for target in select distinct a.opening_receivable_id from public.refund_allocations r join public.payment_allocations a on a.id=r.payment_allocation_id where r.refund_id=new.id and a.opening_receivable_id is not null order by a.opening_receivable_id loop
   perform 1 from public.opening_receivables where id=target for update;
   if (select outstanding_balance from public.opening_receivable_balances where id=target)<0 then
    select id into correction from public.opening_receivable_corrections where opening_receivable_id=target order by posted_at desc,id desc limit 1;
    select id into cause from public.financial_approval_requests where operation='VOID_REFUND' and target_id=new.id and status='APPROVED';
    if cause is null then raise exception 'Approved refund reversal required'; end if;
    perform finance_private.release_opening_credit(correction,cause);
   end if;
  end loop;
 end if;
 return new;
end $$;


ALTER FUNCTION "finance_private"."guard_opening_refund_void"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "finance_private"."guard_opening_rollback"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
 if exists(select 1 from public.opening_receivable_corrections where opening_receivable_id=new.receivable_id)
 or exists(select 1 from public.payment_allocations where opening_receivable_id=new.receivable_id) then raise exception 'Opening activity requires correction, not migration rollback'; end if;
 return new;
end $$;


ALTER FUNCTION "finance_private"."guard_opening_rollback"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "finance_private"."operation_permission"("p_operation" "text", "p_action" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select case p_operation when 'REFUND' then 'finance.refund.' when 'VOID_PAYMENT' then 'finance.payment_void.'
 when 'VOID_REFUND' then 'finance.refund_void.' when 'ALLOCATE_REFUND' then 'finance.refund_allocation.'
 when 'PAYROLL_CORRECTION' then 'payroll.correction.' when 'CANCEL_INVOICE' then 'finance.invoice_cancel.'
 when 'APPLY_CUSTOMER_CREDIT' then 'finance.credit.' when 'REFUND_CUSTOMER_CREDIT' then 'finance.credit.'
 when 'OPENING_RECEIVABLE_CORRECTION' then 'finance.opening_correction.' end || p_action
$$;


ALTER FUNCTION "finance_private"."operation_permission"("p_operation" "text", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "finance_private"."release_opening_credit"("p_correction" "uuid", "p_cause" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare corr public.opening_receivable_corrections; o public.opening_receivables; excess numeric; a record; released numeric; sid uuid;
begin
 select * into corr from public.opening_receivable_corrections where id=p_correction;
 select * into o from public.opening_receivables where id=corr.opening_receivable_id;
 select greatest(0,-outstanding_balance) into excess from public.opening_receivable_balances where id=o.id;
 if excess=0 then return; end if;
 for a in select pa.*,p.paid_at,coalesce(r.amount,0) as refunded from public.payment_allocation_effective pa
 join public.payments p on p.id=pa.payment_id and p.status='POSTED'
 left join lateral(select sum(ra.amount) as amount from public.refund_allocations ra join public.refunds f on f.id=ra.refund_id and f.status='POSTED' where ra.payment_allocation_id=pa.id)r on true
 where pa.opening_receivable_id=o.id and pa.effective_amount>coalesce(r.amount,0) order by p.paid_at desc,pa.id loop
  exit when excess=0;
  -- A normal refund must be attributed before releasing its original allocation as credit.
  if exists(select 1 from public.refunds f where f.payment_id=a.payment_id and f.status='POSTED'
   and f.amount>(select coalesce(sum(ra.amount),0) from public.refund_allocations ra where ra.refund_id=f.id)
                +(select coalesce(sum(u.amount),0) from public.customer_credit_uses u where u.refund_id=f.id)) then raise exception 'Attribute pending refunds before releasing credit'; end if;
  released:=least(excess,a.effective_amount-a.refunded);
  insert into public.customer_credits(student_id,branch_id,currency,payment_id,source_allocation_id,opening_receivable_id,correction_id,cause_request_id,amount)
   values(o.student_id,o.branch_id,o.currency,a.payment_id,a.id,o.id,corr.id,coalesce(p_cause,corr.id),released);
  excess:=excess-released;
 end loop;
 if excess>0 then
  select id into sid from public.opening_settlements where receivable_id=o.id;
  if sid is null then raise exception 'Credit reconciliation failed'; end if;
  -- Historical settlement has no invented cash/payment; retain credit pending source review.
  insert into public.customer_credits(student_id,branch_id,currency,settlement_id,opening_receivable_id,correction_id,cause_request_id,amount)
   values(o.student_id,o.branch_id,o.currency,sid,o.id,corr.id,coalesce(p_cause,corr.id),excess);
 end if;
 if (select outstanding_balance from public.opening_receivable_balances where id=o.id)<>0 then raise exception 'Credit reconciliation failed'; end if;
end $$;


ALTER FUNCTION "finance_private"."release_opening_credit"("p_correction" "uuid", "p_cause" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "finance_private"."validate_before_customer_credit"("p_operation" "text", "p_target" "uuid", "p_details" "jsonb", "p_permission" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare o public.opening_receivables; b public.opening_receivable_balances; row public.migration_batch_rows; target numeric;
begin
 if p_operation<>'OPENING_RECEIVABLE_CORRECTION' then return finance_private.validate_pre_opening_request(p_operation,p_target,p_details,p_permission); end if;
 select * into o from public.opening_receivables where id=p_target and public.finance_action_allowed(p_permission,branch_id);
 if not found then raise exception 'Unauthorized'; end if;
 if p_details is null or jsonb_typeof(p_details)<>'object' or (p_details-array['corrected_amount'])<>'{}' then raise exception 'Unexpected request field'; end if;
 target:=(p_details->>'corrected_amount')::numeric;
 if target is null or target<0 or target>=1000000000000 or target<>round(target,2) or (o.currency='VND' and target<>trunc(target)) then raise exception 'Invalid corrected amount'; end if;
 select * into b from public.opening_receivable_balances where id=o.id;
 if b.reversed then raise exception 'Opening receivable was reversed'; end if;
 if target=o.amount+b.correction_amount then raise exception 'Correction has no remaining delta'; end if;
 if b.outstanding_balance+target-o.amount-b.correction_amount<0 then raise exception 'Correction would create an unapproved customer credit'; end if;
 select * into row from public.migration_batch_rows where id=o.migration_row_id;
 return jsonb_build_object('branch_id',o.branch_id,'source',jsonb_build_object('opening',to_jsonb(o),'currency',o.currency,
 'migration_batch_id',row.batch_id,'source_reference',row.source_reference,'original_amount',o.amount,
 'old_amount',o.amount+b.correction_amount,'corrected_amount',target,'delta',target-o.amount-b.correction_amount,
 'outstanding_balance',b.outstanding_balance));
end $$;


ALTER FUNCTION "finance_private"."validate_before_customer_credit"("p_operation" "text", "p_target" "uuid", "p_details" "jsonb", "p_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "finance_private"."validate_ledger_request"("p_operation" "text", "p_target" "uuid", "p_details" "jsonb", "p_permission" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
 b uuid; snapshot jsonb; pay public.payments; refund public.refunds; payroll public.teacher_payrolls;
 source_period public.payroll_periods; destination public.payroll_periods;
 amount numeric; original numeric; previous_delta numeric; line_id uuid; adjustment_id uuid; allocation_id uuid;
 allowed_keys text[]; original_payment uuid; allocated numeric; consumed numeric;
begin
 if p_details is null or jsonb_typeof(p_details)<>'object' then raise exception 'Invalid request details'; end if;
 if p_operation in ('REFUND','VOID_PAYMENT') then
   select * into pay from public.payments p where p.id=p_target and public.finance_action_allowed(p_permission,p.branch_id_snapshot);
   if not found then raise exception 'Unauthorized'; end if;
   b:=pay.branch_id_snapshot;snapshot:=to_jsonb(pay);original_payment:=pay.id;
   if pay.status<>'POSTED' then raise exception 'Only posted payments can be changed by approval'; end if;
 elsif p_operation in ('VOID_REFUND','ALLOCATE_REFUND') then
   select * into refund from public.refunds r where r.id=p_target and public.finance_action_allowed(p_permission,r.branch_id_snapshot);
   if not found then raise exception 'Unauthorized'; end if;
   b:=refund.branch_id_snapshot;snapshot:=to_jsonb(refund);original_payment:=refund.payment_id;
   if refund.status<>'POSTED' then raise exception 'Only posted refunds can be changed by approval'; end if;
 elsif p_operation='PAYROLL_CORRECTION' then
   select * into payroll from public.teacher_payrolls t where t.id=p_target and public.finance_action_allowed(p_permission,t.branch_id);
   if not found then raise exception 'Unauthorized'; end if;
   select * into source_period from public.payroll_periods where id=payroll.period_id;
   if source_period.status<>'FINALIZED' then raise exception 'Correction source must be FINALIZED'; end if;
   b:=payroll.branch_id;
 else raise exception 'Unsupported financial operation';
 end if;
 allowed_keys:=case p_operation when 'REFUND' then array['amount','refunded_at','notes']
 when 'ALLOCATE_REFUND' then array['amount','payment_allocation_id']
 when 'PAYROLL_CORRECTION' then array['corrected_amount','earning_id','adjustment_id','run_type'] else array[]::text[] end;
 if exists(select 1 from jsonb_object_keys(p_details) k where not(k=any(allowed_keys))) then raise exception 'Unexpected request field'; end if;
 if p_operation in ('REFUND','ALLOCATE_REFUND') then
   amount:=(p_details->>'amount')::numeric;
   if amount is null or amount<=0 or amount>=10000000000000 or amount<>round(amount,2) then raise exception 'Invalid financial amount'; end if;
 end if;
 if p_operation='REFUND' then
   if p_details->>'refunded_at' is null or (p_details->>'refunded_at') !~ '(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'Refund timestamp must include timezone'; end if;
   perform (p_details->>'refunded_at')::timestamptz;
   if length(coalesce(p_details->>'notes',''))>2000 then raise exception 'Notes too long'; end if;
   select coalesce(sum(f.amount),0) into consumed from public.refunds f where f.payment_id=p_target and status='POSTED';
   if consumed+amount>pay.amount then raise exception 'Refund exceeds the remaining refundable payment amount'; end if;
 elsif p_operation='VOID_PAYMENT' then
   if exists(select 1 from public.refunds where payment_id=p_target and status='POSTED') then raise exception 'Reverse posted refunds before voiding payment'; end if;
 elsif p_operation='ALLOCATE_REFUND' then
   if not exists(select 1 from public.payments where id=refund.payment_id and status='POSTED') then raise exception 'Original payment must remain POSTED'; end if;
   allocation_id:=(p_details->>'payment_allocation_id')::uuid;
   select a.amount into allocated from public.payment_allocations a where a.id=allocation_id and a.payment_id=refund.payment_id;
   if not found then raise exception 'Refund must be allocated against its original payment'; end if;
   if exists(select 1 from public.refund_allocations where refund_id=refund.id and payment_allocation_id=allocation_id) then raise exception 'This refund is already allocated to this payment allocation'; end if;
   select coalesce(sum(a.amount),0) into consumed from public.refund_allocations a where a.refund_id=refund.id;
   if consumed+amount>refund.amount then raise exception 'Refund allocation exceeds the refund amount'; end if;
   select coalesce(sum(a.amount),0) into consumed from public.refund_allocations a join public.refunds r on r.id=a.refund_id where a.payment_allocation_id=allocation_id and r.status='POSTED';
   if consumed+amount>allocated then raise exception 'Refund exceeds the original payment allocation amount'; end if;
 elsif p_operation='PAYROLL_CORRECTION' then
   amount:=(p_details->>'corrected_amount')::numeric;
   if amount is null or abs(amount)>=10000000000000 or amount<>round(amount,2) then raise exception 'Invalid corrected amount'; end if;
   line_id:=nullif(p_details->>'earning_id','')::uuid;adjustment_id:=nullif(p_details->>'adjustment_id','')::uuid;
   if line_id is not null and adjustment_id is not null then raise exception 'Choose one original line'; end if;
   if line_id is not null then
     select l.amount into original from public.payroll_earning_lines l where l.id=line_id and l.payroll_id=payroll.id;
   elsif adjustment_id is not null then
     select a.amount into original from public.payroll_adjustments a where a.id=adjustment_id and a.payroll_id=payroll.id;
   else
     if exists(select 1 from public.payroll_earning_lines where payroll_id=payroll.id) or exists(select 1 from public.payroll_adjustments where payroll_id=payroll.id) then raise exception 'Original earning or adjustment line required'; end if;
     original:=payroll.gross_amount;
   end if;
   if original is null then raise exception 'Original line does not belong to payroll'; end if;
   select coalesce(sum(c.delta),0) into previous_delta from public.payroll_corrections c where c.original_payroll_id=payroll.id
     and c.original_earning_id is not distinct from line_id and c.original_adjustment_id is not distinct from adjustment_id;
   if amount=original+previous_delta then raise exception 'Correction has no remaining delta'; end if;
   if p_details->>'run_type'='NEXT_OPEN_PERIOD' then
     select * into destination from public.payroll_periods p where p.branch_id=b and p.starts_on>source_period.ends_on
       and p.status in ('DRAFT','GENERATED','REVIEW') order by p.starts_on,p.id limit 1;
     if not found then raise exception 'Create next open payroll period first'; end if;
     if destination.status='DRAFT' then raise exception 'Generate next open period before posting correction'; end if;
     if exists(select 1 from public.teacher_payrolls t where t.period_id=destination.id and ((payroll.employee_id is not null and t.employee_id=payroll.employee_id) or (payroll.employee_id is null and t.teacher_id=payroll.teacher_id)) and t.currency<>payroll.currency) then raise exception 'Correction currency must match destination payroll'; end if;
   elsif p_details->>'run_type' is distinct from 'OFF_CYCLE_CORRECTION' then raise exception 'Invalid correction run type'; end if;
   snapshot:=jsonb_build_object('payroll',to_jsonb(payroll),'source_period',to_jsonb(source_period),
     'earning_id',line_id,'adjustment_id',adjustment_id,'original_amount',original,'previous_delta',previous_delta,
     'corrected_amount',amount,'delta',amount-original-previous_delta,'target_period',case when destination.id is not null then to_jsonb(destination) else 'null'::jsonb end);
 end if;
 return jsonb_build_object('branch_id',b,'source',snapshot,'payment_id',original_payment);
end $_$;


ALTER FUNCTION "finance_private"."validate_ledger_request"("p_operation" "text", "p_target" "uuid", "p_details" "jsonb", "p_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "finance_private"."validate_pre_opening_request"("p_operation" "text", "p_target" "uuid", "p_details" "jsonb", "p_permission" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare i public.invoices; validated jsonb;
begin
 if p_operation<>'CANCEL_INVOICE' then
   validated:=finance_private.validate_ledger_request(p_operation,p_target,p_details,p_permission);
   if p_operation='PAYROLL_CORRECTION' and exists(select 1 from public.payroll_corrections where posted_adjustment_id=nullif(p_details->>'adjustment_id','')::uuid) then
     raise exception 'Correct the original source line, not a posted correction line';
   end if;
   return validated;
 end if;
 select * into i from public.invoices where id=p_target and public.finance_action_allowed(p_permission,branch_id_snapshot);
 if not found then raise exception 'Unauthorized'; end if;
 if p_details is distinct from '{}'::jsonb then raise exception 'Unexpected request field'; end if;
 if i.status<>'ISSUED' then raise exception 'Cancellation approval requires ISSUED invoice'; end if;
 return jsonb_build_object('branch_id',i.branch_id_snapshot,'source',to_jsonb(i));
end $$;


ALTER FUNCTION "finance_private"."validate_pre_opening_request"("p_operation" "text", "p_target" "uuid", "p_details" "jsonb", "p_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "finance_private"."validate_request"("p_operation" "text", "p_target" "uuid", "p_details" "jsonb", "p_permission" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare c public.customer_credit_balances; o public.opening_receivables; b public.opening_receivable_balances;
 row public.migration_batch_rows; target numeric; obligation jsonb; target_id uuid; balance numeric;
begin
 if p_operation not in ('APPLY_CUSTOMER_CREDIT','REFUND_CUSTOMER_CREDIT','OPENING_RECEIVABLE_CORRECTION') then
  return finance_private.validate_before_customer_credit(p_operation,p_target,p_details,p_permission);
 end if;
 if p_operation='OPENING_RECEIVABLE_CORRECTION' then
  select * into o from public.opening_receivables where id=p_target and public.finance_action_allowed(p_permission,branch_id);
  if not found then raise exception 'Unauthorized'; end if;
  if p_details is null or jsonb_typeof(p_details)<>'object' or (p_details-array['corrected_amount'])<>'{}' then raise exception 'Unexpected request field'; end if;
  target:=(p_details->>'corrected_amount')::numeric;
  if target is null or target<0 or target>=1000000000000 or target<>round(target,2) or (o.currency='VND' and target<>trunc(target)) then raise exception 'Invalid corrected amount'; end if;
  select * into b from public.opening_receivable_balances where id=o.id;
  if b.reversed then raise exception 'Opening receivable was reversed'; end if;
  if target=o.amount+b.correction_amount then raise exception 'Correction has no remaining delta'; end if;
  select * into row from public.migration_batch_rows where id=o.migration_row_id;
  return jsonb_build_object('branch_id',o.branch_id,'source',jsonb_build_object('opening',to_jsonb(o),'currency',o.currency,
   'migration_batch_id',row.batch_id,'source_reference',row.source_reference,'original_amount',o.amount,
   'old_amount',o.amount+b.correction_amount,'corrected_amount',target,'delta',target-o.amount-b.correction_amount,'outstanding_balance',b.outstanding_balance));
 end if;
 select * into c from public.customer_credit_balances where id=p_target and public.finance_action_allowed(p_permission,branch_id);
 if not found then raise exception 'Unauthorized'; end if;
 if c.payment_id is null then raise exception 'Legacy settlement credit requires source payment review'; end if;
 if p_details is null or jsonb_typeof(p_details)<>'object' then raise exception 'Invalid request details'; end if;
 target:=(p_details->>'amount')::numeric;
 if target is null or target<=0 or target>=1000000000000 or target<>round(target,2) or(c.currency='VND' and target<>trunc(target)) then raise exception 'Invalid credit amount'; end if;
 if target>c.remaining_credit then raise exception 'Credit amount exceeds remaining credit'; end if;
 if p_operation='APPLY_CUSTOMER_CREDIT' then
  if (p_details-array['amount','invoice_id','opening_receivable_id'])<>'{}' then raise exception 'Unexpected request field'; end if;
  if num_nonnulls(p_details->>'invoice_id',p_details->>'opening_receivable_id')<>1 then raise exception 'Exactly one obligation required'; end if;
  if p_details->>'invoice_id' is not null then
   target_id:=(p_details->>'invoice_id')::uuid;
   select to_jsonb(i),i.outstanding_balance into obligation,balance from public.invoice_receivables i
   where i.invoice_id=target_id and i.invoice_status='ISSUED' and i.student_id_snapshot=c.student_id and i.branch_id_snapshot=c.branch_id and i.currency=c.currency;
  else
   target_id:=(p_details->>'opening_receivable_id')::uuid;
   select to_jsonb(ob),ob.outstanding_balance into obligation,balance from public.opening_receivable_balances ob
   where ob.id=target_id and not ob.reversed and ob.student_id=c.student_id and ob.branch_id=c.branch_id and ob.currency=c.currency;
  end if;
  if obligation is null then raise exception 'Credit obligation scope or status mismatch'; end if;
  if target>balance then raise exception 'Credit exceeds obligation balance'; end if;
 else
  if (p_details-array['amount','refunded_at'])<>'{}' then raise exception 'Unexpected request field'; end if;
  if (p_details->>'refunded_at')::timestamptz is null or (p_details->>'refunded_at')::timestamptz>now() then raise exception 'Actual refund time required'; end if;
  if (p_details->>'refunded_at')::timestamptz<(select paid_at from public.payments where id=c.payment_id) then raise exception 'Refund cannot precede receipt'; end if;
 end if;
 return jsonb_build_object('branch_id',c.branch_id,'source',jsonb_build_object('credit',to_jsonb(c),'currency',c.currency,'amount',target,'obligation',obligation));
end $$;


ALTER FUNCTION "finance_private"."validate_request"("p_operation" "text", "p_target" "uuid", "p_details" "jsonb", "p_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "finance_private"."void_payment"("p_payment_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_status text;
begin



  if p_payment_id is null then
    raise exception
      'Payment id is required';
  end if;


  if p_reason is null
    or btrim(p_reason) = ''
  then
    raise exception
      'Payment void reason is required';
  end if;


  select payment.status
  into v_status
  from public.payments
    as payment
  where payment.id =
    p_payment_id
  for update;


  if not found then
    raise exception
      'Payment not found';
  end if;


  if v_status <> 'POSTED' then
    raise exception
      'Only posted payments can be voided';
  end if;


  update public.payments
  set
    status = 'VOIDED',
    voided_at = now(),
    voided_by = auth.uid(),
    void_reason =
      btrim(p_reason)
  where id =
    p_payment_id;
end;
$$;


