CREATE OR REPLACE FUNCTION "finance_private"."void_refund"("p_refund_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_status text;
begin



  if p_refund_id is null then
    raise exception
      'Refund id is required';
  end if;


  if p_reason is null
    or btrim(p_reason) = ''
  then
    raise exception
      'Refund void reason is required';
  end if;


  select refund.status
  into v_status
  from public.refunds
    as refund
  where refund.id =
    p_refund_id
  for update;


  if not found then
    raise exception
      'Refund not found';
  end if;


  if v_status <> 'POSTED' then
    raise exception
      'Only posted refunds can be voided';
  end if;


  update public.refunds
  set
    status = 'VOIDED',
    voided_at = now(),
    voided_by = auth.uid(),
    void_reason =
      btrim(p_reason)
  where id =
    p_refund_id;
end;
$$;


