CREATE TABLE IF NOT EXISTS "public"."employee_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "version" integer NOT NULL,
    "effective_on" "date" NOT NULL,
    "full_name" "text" NOT NULL,
    "unit_code" "text" NOT NULL,
    "employee_group" "text" NOT NULL,
    "employment_status" "text" NOT NULL,
    "end_date" "date",
    "pay_type" "text" NOT NULL,
    "operational_role_id" "uuid",
    "reason" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid" NOT NULL,
    CONSTRAINT "employee_versions_check" CHECK ((("employment_status" = 'TERMINATED'::"text") = ("end_date" IS NOT NULL))),
    CONSTRAINT "employee_versions_check1" CHECK ((("end_date" IS NULL) OR ("end_date" = "effective_on"))),
    CONSTRAINT "employee_versions_employee_group_check" CHECK ((("length"("btrim"("employee_group")) >= 1) AND ("length"("btrim"("employee_group")) <= 100))),
    CONSTRAINT "employee_versions_employment_status_check" CHECK (("employment_status" = ANY (ARRAY['ACTIVE'::"text", 'ON_LEAVE'::"text", 'TERMINATED'::"text"]))),
    CONSTRAINT "employee_versions_full_name_check" CHECK ((("length"("btrim"("full_name")) >= 1) AND ("length"("btrim"("full_name")) <= 200))),
    CONSTRAINT "employee_versions_pay_type_check" CHECK (("pay_type" = ANY (ARRAY['MONTHLY'::"text", 'PER_SESSION'::"text", 'HOURLY'::"text"]))),
    CONSTRAINT "employee_versions_reason_check" CHECK ((("length"("btrim"("reason")) >= 1) AND ("length"("btrim"("reason")) <= 2000))),
    CONSTRAINT "employee_versions_version_check" CHECK (("version" > 0))
);


