CREATE OR REPLACE FUNCTION "hr_private"."monthly_payroll_evidence"("p_employee" "uuid", "p_from" "date", "p_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  s record;
  a public.employee_attendance_entries;

  required_minutes integer:=0;
  payable_minutes integer:=0;
  shift_payable integer;

  sources jsonb:='[]'::jsonb;
  qr_verification jsonb;
begin
  if not public.has_role('SUPER_ADMIN') then
    raise exception 'Payroll preparation denied';
  end if;

  for s in
    select *
    from public.employee_schedule(
      p_employee,
      p_from,
      p_to
    )
    order by work_date,shift_code
  loop

    select *
    into a
    from public.employee_attendance_entries e
    where e.employee_id=p_employee
      and e.work_date=s.work_date
      and e.shift_code=s.shift_code
    order by e.revision desc
    limit 1;

    qr_verification:=null;

    if a.id is not null then
      select to_jsonb(v)
      into qr_verification
      from public.employee_attendance_qr_verifications v
      where v.attendance_entry_id=a.id
        and v.verification_status='VERIFIED'
      limit 1;
    end if;

    shift_payable:=0;

    if s.scheduled_minutes>0 then

      if a.id is null
         or (
           a.checker is null
           and qr_verification is null
         )
      then
        raise exception
          'Approved attendance required for every required shift';
      end if;

      if a.status in (
        'WORKED',
        'BUSINESS_TRIP',
        'LATE',
        'EARLY_LEAVE'
      )
      then
        shift_payable:=s.scheduled_minutes;

      elsif a.status='PAID_LEAVE' then

        if a.leave_policy_id is null
           or (
             a.paid_leave_minutes
             + a.unpaid_leave_minutes
           ) <> s.scheduled_minutes
        then
          raise exception
            'Paid leave evidence does not reconcile';
        end if;

        shift_payable:=a.paid_leave_minutes;

      elsif a.status not in (
        'UNPAID_LEAVE',
        'UNAUTHORIZED_ABSENCE'
      )
      then
        raise exception
          'Attendance conflicts with required schedule';
      end if;

    elsif a.id is not null
      and a.status<>'SCHEDULED_OFF'
    then
      raise exception
        'Attendance conflicts with scheduled rest';
    end if;

    required_minutes :=
      required_minutes
      + s.scheduled_minutes;

    payable_minutes :=
      payable_minutes
      + shift_payable;

    sources :=
      sources
      ||
      jsonb_build_array(
        jsonb_build_object(
          'schedule',
            to_jsonb(s),

          'attendance',
            case
              when a.id is not null
              then to_jsonb(a)
              else null
            end,

          'verification',
            qr_verification,

          'payable_minutes',
            shift_payable
        )
      );

  end loop;

  if required_minutes=0 then
    raise exception
      'No required minutes; manual payroll review required';
  end if;

  if payable_minutes<0
     or payable_minutes>required_minutes
  then
    raise exception
      'Payroll minutes do not reconcile';
  end if;

  return jsonb_build_object(
    'calculation_version',
      'SCHEDULED_MINUTES_V1',

    'employee_id',
      p_employee,

    'starts_on',
      p_from,

    'ends_on',
      p_to,

    'required_minutes',
      required_minutes,

    'payable_minutes',
      payable_minutes,

    'unpaid_minutes',
      required_minutes-payable_minutes,

    'late_early_policy',
      'RECORD_ONLY',

    'sources',
      sources
  );
end;
$$;


ALTER FUNCTION "hr_private"."monthly_payroll_evidence"("p_employee" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "hr_private"."normalize_employee_address"("p_address" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  value text;
begin
  value := btrim(coalesce(p_address, ''));

  if char_length(value) not between 5 and 500 then
    raise exception
      'EMPLOYEE_PRIVATE_INVALID_ADDRESS';
  end if;

  return value;
end;
$$;


ALTER FUNCTION "hr_private"."normalize_employee_address"("p_address" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "hr_private"."normalize_employee_citizen_id"("p_citizen_id" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $_$
declare
  value text;
begin
  value := btrim(coalesce(p_citizen_id, ''));

  if value !~ '^[0-9]{12}$' then
    raise exception
      'EMPLOYEE_PRIVATE_INVALID_CITIZEN_ID';
  end if;

  return value;
end;
$_$;


ALTER FUNCTION "hr_private"."normalize_employee_citizen_id"("p_citizen_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "hr_private"."normalize_employee_email"("p_email" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $_$
declare
  value text;
begin
  value := lower(btrim(coalesce(p_email, '')));

  if char_length(value) not between 3 and 254
     or value !~
        '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
  then
    raise exception
      'EMPLOYEE_PRIVATE_INVALID_EMAIL';
  end if;

  return value;
end;
$_$;


ALTER FUNCTION "hr_private"."normalize_employee_email"("p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "hr_private"."normalize_employee_phone"("p_phone" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $_$
declare
  value text;
begin
  value := regexp_replace(
    btrim(coalesce(p_phone, '')),
    '[[:space:]().-]',
    '',
    'g'
  );

  if value ~ '^0[35789][0-9]{8}$' then
    return '+84' || substr(value, 2);
  end if;

  if value ~ '^\+84[35789][0-9]{8}$' then
    return value;
  end if;

  raise exception
    'EMPLOYEE_PRIVATE_INVALID_PHONE';
end;
$_$;


ALTER FUNCTION "hr_private"."normalize_employee_phone"("p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "hr_private"."payroll_identity_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$begin
 if new.employee_id is distinct from old.employee_id then raise exception 'Payroll identity is immutable';end if;
 return new;end$$;


ALTER FUNCTION "hr_private"."payroll_identity_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "notification_private"."active_zalo_links"("p_registration" "uuid", "p_parent" "uuid", "p_student" "uuid") RETURNS TABLE("id" "uuid", "subject_type" "text", "subject_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select picked.id, picked.subject_type, picked.subject_id
  from (
    select distinct on (channel.provider_user_id)
      channel.id,
      case
        when channel.registration_application_id is not null then 'REGISTRATION'
        when channel.parent_id is not null then 'PARENT'
        else 'STUDENT'
      end as subject_type,
      coalesce(channel.registration_application_id, channel.parent_id, channel.student_id) as subject_id
    from public.customer_channel_links channel
    where channel.provider = 'ZALO'
      and channel.status = 'ACTIVE'
      and channel.provider_user_id is not null
      and (
        (p_registration is not null and channel.registration_application_id = p_registration)
        or (p_parent is not null and channel.parent_id = p_parent)
        or (p_student is not null and channel.student_id = p_student)
      )
    order by channel.provider_user_id, channel.created_at
  ) picked
$$;


ALTER FUNCTION "notification_private"."active_zalo_links"("p_registration" "uuid", "p_parent" "uuid", "p_student" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "notification_private"."domain_notice_source"("p_event" "text", "p_entity" "uuid") RETURNS TABLE("student_id" "uuid", "parent_id" "uuid", "registration_id" "uuid", "branch_id" "uuid", "template_key" "text", "title" "text", "href" "text", "parameters" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if p_event = 'PAYMENT_CONFIRMED' then
    return query
    select
      payment.student_id_snapshot,
      (
        select relation.parent_id
        from public.student_parents relation
        where relation.student_id = payment.student_id_snapshot
          and relation.is_active
        order by relation.is_primary desc
        limit 1
      ),
      null::uuid,
      payment.branch_id_snapshot,
      'ZALO_PAYMENT_CONFIRMED'::text,
      'Thanh toán đã được xác nhận'::text,
      '/my-learning'::text,
      jsonb_build_object(
        'student_display_name', left(coalesce(student.full_name, 'Học viên'), 80),
        'amount_display', trim(to_char(payment.amount, 'FM999999999990')) || ' VND',
        'payment_reference', left(payment.payment_number, 40),
        'portal_url', '/my-learning'
      )
    from public.payments payment
    join public.students student on student.id = payment.student_id_snapshot
    where payment.id = p_entity
      and payment.status = 'POSTED'
      and exists (
        select 1
        from public.payment_allocations allocation
        join public.invoice_receivables receivable on receivable.invoice_id = allocation.invoice_id
        where allocation.payment_id = payment.id
          and receivable.invoice_status = 'ISSUED'
          and receivable.receivable_status = 'PAID'
      );
  elsif p_event = 'REGISTRATION_COMPLETED' then
    return query
    select
      app.linked_student_id,
      app.linked_parent_id,
      app.id,
      app.branch_id,
      'ZALO_REGISTRATION_CONFIRMED'::text,
      'Xác nhận đăng ký tại VIBE Academy'::text,
      '/my-learning'::text,
      jsonb_build_object(
        'customer_name', left(coalesce(app.parent_name, 'Phụ huynh'), 80),
        'registration_code', app.application_code,
        'student_name', left(coalesce(app.student_name, 'Học viên'), 80),
        'program_name', left(coalesce(curriculum.name, app.program_interest, 'Chương trình đã đăng ký'), 80),
        'branch_name', left(branch.name, 80),
        'order_code', app.application_code,
        'payment_status', 'Đã nhận thanh toán 50%'
      )
    from public.registration_applications app
    join public.branches branch on branch.id = app.branch_id
    left join public.curriculums curriculum on curriculum.id = app.curriculum_id
    where app.id = p_entity
      and app.status = 'COMPLETED'
      and app.deposit_confirmed_at is not null;
  elsif p_event = 'CLASS_ASSIGNED' then
    return query
    select
      placement.student_id,
      app.linked_parent_id,
      app.id,
      placement.branch_id,
      'ZALO_CLASS_ASSIGNED'::text,
      'Học viên đã được xếp lớp'::text,
      '/my-learning'::text,
      jsonb_build_object(
        'student_display_name', left(coalesce(student.full_name, 'Học viên'), 80),
        'class_name', left(class_row.name, 80),
        'teacher_display_name', left(coalesce(teacher.full_name, 'Sẽ thông báo'), 80),
        'start_date', to_char(placement.scheduled_start_date, 'YYYY-MM-DD'),
        'schedule_display', left(coalesce(nullif(btrim(placement.preferred_schedule), ''), 'Xem lịch trên cổng học viên'), 120),
        'portal_url', '/my-learning'
      )
    from public.student_placement_events event
    join public.student_placement_cases placement on placement.id = event.placement_id
    join public.registration_applications app on app.id = placement.registration_application_id
    join public.classes class_row on class_row.id = placement.assigned_class_id
    join public.students student on student.id = placement.student_id
    left join public.teachers teacher on teacher.id = placement.assigned_teacher_id
    where event.id = p_entity
      and event.event_type = 'CLASS_ASSIGNED'
      and placement.status = 'SCHEDULED';
  elsif p_event in ('LEARNING_REPORT_PUBLISHED', 'END_OF_COURSE_REPORT_PUBLISHED') then
    return query
    select
      report.student_id,
      (
        select relation.parent_id
        from public.student_parents relation
        where relation.student_id = report.student_id
          and relation.is_active
        order by relation.is_primary desc
        limit 1
      ),
      null::uuid,
      report.branch_id,
      'ZALO_LEARNING_REPORT_PUBLISHED'::text,
      'Báo cáo học tập đã phát hành'::text,
      '/my-learning'::text,
      jsonb_build_object(
        'student_display_name', left(coalesce(student.full_name, 'Học viên'), 80),
        'report_period', to_char(report.period_start, 'YYYY-MM-DD') || ' - ' || to_char(report.period_end, 'YYYY-MM-DD'),
        'secure_report_url', '/my-learning'
      )
    from public.learning_reports report
    join public.students student on student.id = report.student_id
    where report.id = p_entity
      and report.status = 'PUBLISHED'
      and report.approved_at is not null
      and report.approved_by is not null
      and (
        (p_event = 'LEARNING_REPORT_PUBLISHED' and report.report_type = 'MONTHLY')
        or (p_event = 'END_OF_COURSE_REPORT_PUBLISHED' and report.report_type = 'END_OF_COURSE')
      );
  end if;
end $$;


ALTER FUNCTION "notification_private"."domain_notice_source"("p_event" "text", "p_entity" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "notification_private"."emit_domain_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  event_name text;
  entity uuid;
begin
  if tg_table_name = 'payment_allocations' then
    event_name := 'PAYMENT_CONFIRMED';
    entity := new.payment_id;
  elsif tg_table_name = 'registration_applications' then
    if tg_op <> 'UPDATE' or new.status is distinct from 'COMPLETED' or old.status = 'COMPLETED' then
      return null;
    end if;
    event_name := 'REGISTRATION_COMPLETED';
    entity := new.id;
  elsif tg_table_name = 'student_placement_events' then
    if new.event_type is distinct from 'CLASS_ASSIGNED' then
      return null;
    end if;
    event_name := 'CLASS_ASSIGNED';
    entity := new.id;
  elsif tg_table_name = 'learning_reports' then
    if tg_op <> 'UPDATE' or new.status is distinct from 'PUBLISHED' or old.status = 'PUBLISHED' then
      return null;
    end if;
    event_name := case
      when new.report_type = 'END_OF_COURSE' then 'END_OF_COURSE_REPORT_PUBLISHED'
      else 'LEARNING_REPORT_PUBLISHED'
    end;
    entity := new.id;
  else
    return null;
  end if;
  begin
    perform public.enqueue_domain_notification(event_name, entity);
  exception
    when others then
      return null;
  end;
  return null;
end $$;


ALTER FUNCTION "notification_private"."emit_domain_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "notification_private"."emit_tuition_payment_received"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'INSERT' and new.status = 'POSTED' then
    begin
      perform public.enqueue_tuition_payment_received(new.id);
    exception
      when others then
        null;
    end;
  elsif tg_op = 'UPDATE' and new.status = 'POSTED' and old.status is distinct from 'POSTED' then
    begin
      perform public.enqueue_tuition_payment_received(new.id);
    exception
      when others then
        null;
    end;
  end if;
  return null;
end $$;


