CREATE OR REPLACE FUNCTION "notification_private"."guard_delivery"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.status in ('PROCESSING', 'SENT') and new.status is distinct from old.status then
    if new.channel = 'ZALO' and new.entity_type = 'TUITION_PAYMENT_RECEIVED' then
      if not exists (
        select 1 from public.payments payment
        where payment.id = new.entity_id and payment.status = 'POSTED'
      ) then
        raise exception 'Notification source no longer eligible';
      end if;
      if new.channel_link_id is not null and not exists (
        select 1 from public.customer_channel_links channel
        where channel.id = new.channel_link_id
          and channel.provider = 'ZALO'
          and channel.status = 'ACTIVE'
          and channel.provider_user_id is not null
      ) then
        raise exception 'Notification recipient no longer eligible';
      end if;
    else
      if new.recipient_id is not null
        and not notification_private.recipient_allowed(new.recipient_id, new.student_id, new.branch_id, new.template_key) then
        raise exception 'Notification recipient no longer eligible';
      end if;
    end if;
    if new.template_key = 'TUITION_REMINDER' and not exists (
      select 1
      from tuition_reminders reminder
      join enrollment_tuition term on term.id = reminder.enrollment_tuition_id
      join enrollments enrollment on enrollment.id = term.enrollment_id
      where reminder.id = new.entity_id
        and reminder.status = 'PENDING'
        and term.status in ('ACTIVE', 'SCHEDULED')
        and enrollment.status = 'ACTIVE'
        and term.effective_ends_on >= (now() at time zone 'Asia/Ho_Chi_Minh')::date
    ) then
      raise exception 'Notification source no longer eligible';
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION "notification_private"."guard_delivery"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "notification_private"."guard_phone_attempt"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
 if old.channel='ZALO' and old.payload->'delivery'->>'channel'='PHONE' then
  if old.status in('SENT','DELIVERED','ACCEPTANCE_UNKNOWN') and new.status is distinct from old.status and not(old.status='SENT' and new.status='DELIVERED') then raise exception 'PHONE_RECONCILIATION_REQUIRED'; end if;
  if new.status is distinct from old.status and new.status in('PENDING','QUEUED','RETRYING','PROCESSING','SKIPPED_NO_CHANNEL','SENT','FAILED','ACCEPTANCE_UNKNOWN') and current_setting('zalo.durable_write',true) is distinct from 'on' then raise exception 'USE_DURABLE_PHONE_DISPATCH'; end if;
 end if;
 return new;
end $$;


ALTER FUNCTION "notification_private"."guard_phone_attempt"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "notification_private"."normalize_vn_phone"("p_phone" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
declare
  digits text := regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g');
begin
  if digits ~ '^84[0-9]{9}$' then
    return digits;
  end if;
  if digits ~ '^0[0-9]{9}$' then
    return '84' || substring(digits from 2);
  end if;
  return null;
end $_$;


ALTER FUNCTION "notification_private"."normalize_vn_phone"("p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "notification_private"."recipient_allowed"("p_user" "uuid", "p_student" "uuid", "p_branch" "uuid", "p_template" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select exists(select 1 from profiles where id=p_user and status='ACTIVE') and exists(
 select 1 from user_roles ur join roles r on r.id=ur.role_id
 where ur.user_id=p_user and ur.is_active and (ur.valid_from is null or ur.valid_from<=now())
 and (ur.valid_until is null or ur.valid_until>now()) and (r.code<>'SUPER_ADMIN' or ur.branch_id is null)
 and (p_template='ONBOARDING' or ur.branch_id is null or ur.branch_id=p_branch)
 and (p_template='ONBOARDING' or (
 exists(select 1 from role_permissions rp join permissions p on p.id=rp.permission_id where rp.role_id=r.id
 and p.code=(case when p_template='TUITION_REMINDER' then 'tuition' when p_template in('MONTHLY_REPORT','END_OF_COURSE') then 'learning_reports' else 'attendance' end)||case r.code when 'STUDENT' then '.view_own' when 'PARENT' then '.view_related' else '.unsupported' end)
 and ((r.code='STUDENT' and exists(select 1 from students s where s.id=p_student and s.user_id=p_user and s.status in('ACTIVE','PAUSED','GRADUATED')))
 or (r.code='PARENT' and exists(select 1 from parents p join student_parents sp on sp.parent_id=p.id where p.user_id=p_user and p.status='ACTIVE' and sp.student_id=p_student and sp.is_active
 and (sp.valid_from is null or sp.valid_from<=now()) and (sp.valid_until is null or sp.valid_until>now()) and (p_template<>'TUITION_REMINDER' or sp.can_view_finance is true)))))))
$$;


ALTER FUNCTION "notification_private"."recipient_allowed"("p_user" "uuid", "p_student" "uuid", "p_branch" "uuid", "p_template" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "notification_private"."refresh_zalo_job"("p_job" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  job public.notification_jobs;
  src record;
  link record;
begin
  select * into job from public.notification_jobs where id = p_job for update;
  if not found or job.channel is distinct from 'ZALO' then
    raise exception 'Invalid notification transition';
  end if;
  if job.status = 'FAILED' and coalesce(job.error_code, '') in (
    'ZALO_OUTBOUND_NOT_CONFIGURED', 'TEMPLATE_NOT_APPROVED', 'PROVIDER_NOT_CONFIGURED', 'RECIPIENT_INELIGIBLE'
  ) then
    raise exception 'Invalid notification transition';
  end if;
  if job.attempts >= 5 or job.status not in ('FAILED', 'SKIPPED_NO_CHANNEL', 'RETRYING') then
    raise exception 'Invalid notification transition';
  end if;
  select * into src from notification_private.domain_notice_source(job.entity_type, job.entity_id);
  if not found then
    update public.notification_jobs
    set status = 'FAILED', error_code = 'RECIPIENT_INELIGIBLE', next_attempt_at = null, updated_at = now()
    where id = job.id;
    return;
  end if;
  select * into link
  from notification_private.active_zalo_links(src.registration_id, src.parent_id, src.student_id)
  limit 1;
  if not found then
    update public.notification_jobs
    set status = 'SKIPPED_NO_CHANNEL', error_code = 'SKIPPED_NO_CHANNEL', channel_link_id = null,
      next_attempt_at = null, updated_at = now()
    where id = job.id;
    return;
  end if;
  update public.notification_jobs
  set status = 'QUEUED', error_code = null, channel_link_id = link.id,
    recipient_subject_type = link.subject_type, recipient_subject_id = link.subject_id,
    next_attempt_at = null, sent_at = null, provider_receipt = null, provider_message_id = null,
    updated_at = now()
  where id = job.id;
end $$;


ALTER FUNCTION "notification_private"."refresh_zalo_job"("p_job" "uuid") OWNER TO "postgres";


