CREATE OR REPLACE FUNCTION "notification_private"."zalo_encrypt"("v" "text") RETURNS "text"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select case when v is null then null else 'enc:v1:'||encode(extensions.pgp_sym_encrypt(v,(select decrypted_secret from vault.decrypted_secrets where name='vibe_zalo_credentials_v1'),'cipher-algo=aes256'),'base64') end
$$;


ALTER FUNCTION "notification_private"."zalo_encrypt"("v" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "notification_private"."zalo_payment_ready"("p_template" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.notification_templates template
    where template.template_key = p_template
      and template.provider = 'ZALO'
      and coalesce(template.event_type, '') = 'TUITION_PAYMENT_RECEIVED'
      and template.status = 'APPROVED'
      and template.enabled = true
      and nullif(btrim(coalesce(template.provider_template_id, '')), '') is not null
      and jsonb_typeof(template.payload_schema) = 'object'
      and template.payload_schema <> '{}'::jsonb
  )
$$;


