CREATE OR REPLACE FUNCTION "notification_private"."zalo_retry_eligible"("p_job" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select j.status='FAILED' and j.attempts<5 and j.sent_at is null and j.delivered_at is null
 and j.provider_message_id is null and j.payload->'delivery'->>'channel'='PHONE'
 and j.entity_type='REGISTRATION_COMPLETED' and j.channel='ZALO'
 and (
   exists(select 1 from zalo_notification_attempts a where a.job_id=j.id and a.attempt_number=j.attempts and a.state='REJECTED')
   -- Legacy evidence is narrow and explicit: the saved, definitive -124 response.
   -- A generic FAILED job or absent message ID is not evidence of rejection.
   or (j.attempts=1 and not exists(select 1 from zalo_notification_attempts a where a.job_id=j.id)
     and (select e.details->>'provider_error' from notification_events e where e.job_id=j.id order by e.created_at desc,e.id desc limit 1)='-124'
     and j.error_code='ZALO_TOKEN_INVALID')
 ) from notification_jobs j where j.id=p_job
$$;


ALTER FUNCTION "notification_private"."zalo_retry_eligible"("p_job" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "payroll_disbursement_private"."guard_history"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'PAYROLL_DISBURSEMENT_HISTORY_IMMUTABLE';
  end if;

  if old.status <> 'ACTIVE' or new.status <> 'CANCELLED' then
    raise exception 'PAYROLL_DISBURSEMENT_HISTORY_IMMUTABLE';
  end if;

  if new.id is distinct from old.id
    or new.payroll_id is distinct from old.payroll_id
    or new.period_id is distinct from old.period_id
    or new.employee_id is distinct from old.employee_id
    or new.branch_id is distinct from old.branch_id
    or new.amount is distinct from old.amount
    or new.currency is distinct from old.currency
    or new.paid_on is distinct from old.paid_on
    or new.payment_method is distinct from old.payment_method
    or new.reference is distinct from old.reference
    or new.note is distinct from old.note
    or new.request_key is distinct from old.request_key
    or new.request_payload is distinct from old.request_payload
    or new.request_result is distinct from old.request_result
    or new.created_by is distinct from old.created_by
    or new.created_at is distinct from old.created_at
    or new.cancelled_by is null
    or new.cancelled_at is null
    or new.cancel_reason is null
    or new.cancel_request_key is null
    or new.cancel_request_payload is null
    or new.cancel_request_result is null
  then
    raise exception 'PAYROLL_DISBURSEMENT_HISTORY_IMMUTABLE';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "payroll_disbursement_private"."guard_history"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."teacher_payrolls" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "period_id" "uuid" NOT NULL,
    "teacher_id" "uuid",
    "branch_id" "uuid" NOT NULL,
    "teacher_name" "text" NOT NULL,
    "pay_type" "text" NOT NULL,
    "currency" "text" NOT NULL,
    "base_salary" numeric(16,2) DEFAULT 0 NOT NULL,
    "teaching_hours" numeric(16,6) DEFAULT 0 NOT NULL,
    "hourly_earnings" numeric(16,2) DEFAULT 0 NOT NULL,
    "adjustment_amount" numeric(16,2) DEFAULT 0 NOT NULL,
    "gross_amount" numeric(16,2) DEFAULT 0 NOT NULL,
    "employee_id" "uuid",
    "v2_earnings_amount" numeric(16,2) DEFAULT 0 NOT NULL,
    "v2_reimbursement_amount" numeric(16,2) DEFAULT 0 NOT NULL,
    "v2_deduction_amount" numeric(16,2) DEFAULT 0 NOT NULL,
    "v2_net_amount" numeric(16,2) DEFAULT 0 NOT NULL,
    "calculation_version" "text",
    CONSTRAINT "payroll_recipient_required" CHECK ((("teacher_id" IS NOT NULL) OR ("employee_id" IS NOT NULL))),
    CONSTRAINT "teacher_payrolls_v2_deduction_nonnegative" CHECK ((("v2_deduction_amount" >= (0)::numeric) AND ("v2_deduction_amount" <> 'NaN'::numeric))),
    CONSTRAINT "teacher_payrolls_v2_earnings_nonnegative" CHECK ((("v2_earnings_amount" >= (0)::numeric) AND ("v2_earnings_amount" <> 'NaN'::numeric))),
    CONSTRAINT "teacher_payrolls_v2_net_not_nan" CHECK (("v2_net_amount" <> 'NaN'::numeric)),
    CONSTRAINT "teacher_payrolls_v2_reimbursement_nonnegative" CHECK ((("v2_reimbursement_amount" >= (0)::numeric) AND ("v2_reimbursement_amount" <> 'NaN'::numeric)))
);


