COMMENT ON COLUMN "public"."teacher_payrolls"."calculation_version" IS 'Compatibility header marker. PAYROLL_V2_1 rows use payroll_component_lines_v2 as component source of truth.';



CREATE OR REPLACE FUNCTION "payroll_disbursement_private"."payable_amount"("pay" "public"."teacher_payrolls") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case when coalesce(pay.calculation_version like 'PAYROLL_V2%',false)
    then pay.v2_net_amount else pay.gross_amount end
$$;


ALTER FUNCTION "payroll_disbursement_private"."payable_amount"("pay" "public"."teacher_payrolls") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."academic_grade_is_sealed"("p_progress_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from public.student_level_progress p
    join public.student_curriculum_enrollments e on e.id = p.enrollment_id
    join public.curriculum_levels l on l.id = p.level_id
    where p.id = p_progress_id and p.status = 'COMPLETED'
      and (e.status = 'COMPLETED' or exists (
        select 1 from public.student_level_progress later
        join public.curriculum_levels ll on ll.id = later.level_id
        where later.enrollment_id = p.enrollment_id
          and ll.curriculum_id = l.curriculum_id and ll.sequence_no > l.sequence_no
          and later.status in ('AVAILABLE', 'IN_PROGRESS', 'COMPLETED')
      ))
  );
$$;


ALTER FUNCTION "public"."academic_grade_is_sealed"("p_progress_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."academic_operation_actor"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null and session_user not in ('postgres', 'supabase_admin') then
    raise exception 'Không xác định được người thao tác' using errcode = 'P0001';
  end if;
  if not public.academic_ops_may_manage() then
    raise exception 'Không có quyền bảo lưu và học bù. Cần vai trò Quản trị hoặc Quản lý đào tạo.' using errcode = 'P0001';
  end if;
  return auth.uid();
end;
$$;


ALTER FUNCTION "public"."academic_operation_actor"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."academic_ops_may_manage"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(public.has_role('SUPER_ADMIN'), false)
    or coalesce(public.has_role('ACADEMIC_MANAGER'), false)
    or (auth.uid() is null and session_user in ('postgres', 'supabase_admin'))
$$;


ALTER FUNCTION "public"."academic_ops_may_manage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."account_is_active"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select auth.uid() is not null and exists(select 1 from public.profiles p where p.id=auth.uid() and p.status='ACTIVE')
$$;


