CREATE OR REPLACE FUNCTION "public"."activate_registration_momo_order"("p_order_id" "text", "p_partner_code" "text", "p_amount" bigint, "p_pay_url" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare ord public.registration_momo_orders%rowtype;
  app public.registration_applications%rowtype;
begin
  if not coalesce(public.momo_service_request(), false) then
    raise exception 'MOMO_SERVER_ONLY';
  end if;
  select * into ord from public.registration_momo_orders where order_id = p_order_id;
  if not found then raise exception 'MOMO_CHECKOUT_MISMATCH'; end if;
  select * into app from public.registration_applications where id = ord.application_id for update;
  select * into ord from public.registration_momo_orders where order_id = p_order_id for update;
  if not found or ord.amount is distinct from p_amount or nullif(p_partner_code, '') is null
     or p_pay_url is null or p_pay_url !~ '^https://(test-payment|payment)[.]momo[.]vn/' then
    raise exception 'MOMO_CHECKOUT_MISMATCH';
  end if;
  if ord.state = 'READY' and ord.partner_code = p_partner_code and ord.pay_url = p_pay_url then
    return ord.id;
  end if;
  if ord.state <> 'RESERVED' then raise exception 'MOMO_ORDER_STATE_CONFLICT'; end if;
  update public.registration_momo_orders set partner_code = p_partner_code,
    pay_url = p_pay_url, state = 'READY' where id = ord.id;
  perform set_config('registration.write', 'on', true);
  update public.registration_applications set status = 'PAYMENT_PENDING', version = version + 1,
    updated_at = clock_timestamp() where id = ord.application_id and status = 'VERIFIED';
  perform set_config('registration.write', 'off', true);
  return ord.id;
end $$;


ALTER FUNCTION "public"."activate_registration_momo_order"("p_order_id" "text", "p_partner_code" "text", "p_amount" bigint, "p_pay_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."activate_registration_payos_order"("p_order_code" bigint, "p_amount" bigint, "p_payment_link_id" "text", "p_checkout_url" "text", "p_qr_code" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare ord public.registration_payos_orders%rowtype;
begin
  if not coalesce(public.momo_service_request(), false) then raise exception 'PAYOS_SERVER_ONLY'; end if;
  select * into ord from public.registration_payos_orders where order_code = p_order_code for update;
  if not found or ord.amount is distinct from p_amount or nullif(p_payment_link_id, '') is null
     or p_checkout_url is null or p_checkout_url !~ '^https://pay[.]payos[.]vn/' then
    raise exception 'PAYOS_CHECKOUT_MISMATCH';
  end if;
  if ord.state = 'PENDING' and ord.payment_link_id = p_payment_link_id and ord.checkout_url = p_checkout_url then
    return ord.id;
  end if;
  if ord.state <> 'RESERVED' then raise exception 'PAYOS_ORDER_STATE_CONFLICT'; end if;
  update public.registration_payos_orders
  set payment_link_id = p_payment_link_id, checkout_url = p_checkout_url,
      qr_code = nullif(p_qr_code, ''), state = 'PENDING', activated_at = clock_timestamp()
  where id = ord.id;
  perform set_config('registration.write', 'on', true);
  update public.registration_applications set status = 'PAYMENT_PENDING', version = version + 1,
    updated_at = clock_timestamp() where id = ord.application_id and status = 'VERIFIED';
  perform set_config('registration.write', 'off', true);
  return ord.id;
end $$;


ALTER FUNCTION "public"."activate_registration_payos_order"("p_order_code" bigint, "p_amount" bigint, "p_payment_link_id" "text", "p_checkout_url" "text", "p_qr_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_compensation_rule"("p_teacher" "uuid", "p_branch" "uuid", "p_type" "text", "p_rate" numeric, "p_currency" "text", "p_from" "date", "p_to" "date" DEFAULT NULL::"date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare result uuid;
begin
 if not coalesce(has_role('SUPER_ADMIN'),false) then raise exception 'Unauthorized'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_teacher::text||p_branch::text,0));
 if not exists(select 1 from teachers t join teacher_branches b on b.teacher_id=t.id where t.id=p_teacher and t.status='ACTIVE' and b.branch_id=p_branch) then raise exception 'Invalid teacher branch'; end if;
 if exists(select 1 from teacher_compensation_rules where teacher_id=p_teacher and branch_id=p_branch and status='ACTIVE' and daterange(effective_from,effective_to,'[]') && daterange(p_from,p_to,'[]')) then raise exception 'Compensation dates overlap'; end if;
 insert into teacher_compensation_rules(teacher_id,branch_id,pay_type,rate,currency,effective_from,effective_to,created_by) values(p_teacher,p_branch,p_type,p_rate,p_currency,p_from,p_to,auth.uid()) returning id into result;
 return result;
end $$;


ALTER FUNCTION "public"."add_compensation_rule"("p_teacher" "uuid", "p_branch" "uuid", "p_type" "text", "p_rate" numeric, "p_currency" "text", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_crm_lead_note"("p_request" "uuid", "p_lead" "uuid", "p_version" integer, "p_note" "text", "p_channel" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  row public.crm_leads%rowtype;
  actor uuid := auth.uid();
  note text := public.crm_text(p_note, 4000);
  channel text := public.crm_channel(p_channel);
begin
  if actor is null or not coalesce(public.account_is_active(), false) then
    raise exception 'CRM_LEAD_UNAUTHORIZED';
  end if;
  if note is null then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  if public.crm_lead_replay(p_request, p_lead, 'NOTE_ADDED', actor, note, channel, '{}'::jsonb, 'crm.lead.update') then
    return p_lead;
  end if;
  row := public.crm_lead_lock(p_lead, p_version, 'crm.lead.update');
  perform set_config('crm.lead_write', 'on', true);
  update public.crm_leads set
    first_contact_at = coalesce(first_contact_at, clock_timestamp()),
    last_contact_at = clock_timestamp(),
    version = version + 1,
    updated_at = clock_timestamp()
  where id = row.id;
  insert into public.crm_lead_events(id, lead_id, event_type, from_status, to_status, actor_id, channel, note)
  values (p_request, row.id, 'NOTE_ADDED', row.status, row.status, actor, channel, note);
  perform set_config('crm.lead_write', 'off', true);
  return row.id;
end $$;


ALTER FUNCTION "public"."add_crm_lead_note"("p_request" "uuid", "p_lead" "uuid", "p_version" integer, "p_note" "text", "p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_employee_compensation_rule"("p_employee" "uuid", "p_branch" "uuid", "p_rate" numeric, "p_currency" "text", "p_from" "date", "p_to" "date" DEFAULT NULL::"date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$declare result uuid;begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Unauthorized';end if;
 perform 1 from public.employees where id=p_employee for update;
 if not found then raise exception 'Employee not found';end if;
 if not exists(select 1 from public.organization_units u cross join lateral hr_private.employee_at(p_employee,p_from) v where u.code=v.unit_code and u.branch_id=p_branch and v.pay_type='MONTHLY' and v.employment_status='ACTIVE') then raise exception 'Explicit active employee branch mapping required';end if;
 if exists(select 1 from public.teacher_compensation_rules r where r.employee_id=p_employee and r.status='ACTIVE' and daterange(r.effective_from,r.effective_to,'[]') && daterange(p_from,p_to,'[]')) then raise exception 'Compensation dates overlap';end if;
 if exists(select 1 from public.teacher_compensation_rules r join public.employees e on e.teacher_id=r.teacher_id where e.id=p_employee and r.status='ACTIVE' and daterange(r.effective_from,r.effective_to,'[]') && daterange(p_from,p_to,'[]')) then raise exception 'Resolve existing teacher compensation before employee compensation';end if;
 insert into public.teacher_compensation_rules(employee_id,branch_id,pay_type,rate,currency,effective_from,effective_to,created_by)
 values(p_employee,p_branch,'MONTHLY',p_rate,p_currency,p_from,p_to,auth.uid()) returning id into result;return result;
end$$;


ALTER FUNCTION "public"."add_employee_compensation_rule"("p_employee" "uuid", "p_branch" "uuid", "p_rate" numeric, "p_currency" "text", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_instrument_customer_followup"("p_request" "uuid", "p_sale" "uuid", "p_channel" "text", "p_outcome" "text", "p_note" "text", "p_next_on" "date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
#variable_conflict use_variable
declare
  sale public.instrument_events%rowtype;
  next_outcome text := nullif(upper(btrim(coalesce(p_outcome, ''))), '');
  actor uuid := auth.uid();
begin
  if p_request is null or next_outcome is null or next_outcome not in (
    'KEEP_IN_TOUCH', 'INTERESTED_IN_ACCESSORY', 'UPGRADE_OPPORTUNITY', 'SERVICE_REQUIRED',
    'REPURCHASE_INTEREST', 'REPURCHASED', 'NOT_INTERESTED'
  ) then
    raise exception 'INSTRUMENT_CUSTOMER_INVALID';
  end if;
  select * into sale from public.instrument_events where movement_id = p_sale and kind = 'SALE';
  if not found or not coalesce(public.crm_can('instrument_customer.manage', sale.branch_id), false) then
    raise exception 'INSTRUMENT_CUSTOMER_UNAUTHORIZED';
  end if;
  if exists (
    select 1 from public.instrument_customer_followups
    where id = p_request and (sale_event_id is distinct from p_sale or outcome is distinct from next_outcome)
  ) then
    raise exception 'INSTRUMENT_CUSTOMER_REQUEST_MISMATCH';
  end if;
  if exists (select 1 from public.instrument_customer_followups where id = p_request) then
    return p_request;
  end if;
  perform set_config('instrument.customer_write', 'on', true);
  insert into public.instrument_customer_followups(
    id, sale_event_id, channel, owner_user_id, outcome, note, next_follow_up_on, created_by
  ) values (
    p_request, p_sale, public.crm_text(p_channel, 40), actor, next_outcome, public.crm_text(p_note, 2000), p_next_on, actor
  );
  perform set_config('instrument.customer_write', 'off', true);
  return p_request;
end $$;


ALTER FUNCTION "public"."add_instrument_customer_followup"("p_request" "uuid", "p_sale" "uuid", "p_channel" "text", "p_outcome" "text", "p_note" "text", "p_next_on" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_payroll_adjustment"("p_payroll" "uuid", "p_kind" "text", "p_amount" numeric, "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare pid uuid; state text;
begin
 if not coalesce(has_role('SUPER_ADMIN'),false) then raise exception 'Unauthorized'; end if;
 if p_kind='TRAVEL_ALLOWANCE' or (p_kind='DEDUCTION' and exists(select 1 from public.teacher_payrolls where id=p_payroll and employee_id is not null)) then raise exception 'Use evidence-linked adjustment';end if;
 select period_id into pid from teacher_payrolls where id=p_payroll;
 select status into state from payroll_periods where id=pid for update;
 if state is null or state not in ('GENERATED','REVIEW') then raise exception 'Adjustment requires generated or review payroll'; end if;
 insert into payroll_adjustments(payroll_id,kind,amount,reason,created_by) values(p_payroll,p_kind,p_amount,btrim(p_reason),auth.uid());
 update teacher_payrolls set adjustment_amount=adjustment_amount+p_amount,gross_amount=gross_amount+p_amount where id=p_payroll;
 update payroll_periods set version=version+1 where id=pid;
 insert into payroll_events(period_id,status,note,actor_id) values(pid,state,'Adjustment: '||btrim(p_reason),auth.uid());
end$$;


ALTER FUNCTION "public"."add_payroll_adjustment"("p_payroll" "uuid", "p_kind" "text", "p_amount" numeric, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_payroll_evidence_adjustment"("p_payroll" "uuid", "p_kind" "text", "p_amount" numeric, "p_reason" "text", "p_attendance" "uuid", "p_trip" "uuid", "p_key" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare pay public.teacher_payrolls; period public.payroll_periods; a public.employee_attendance_entries; t public.employee_trips; result uuid; prior public.payroll_adjustments; source jsonb;
begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Unauthorized';end if;
 if p_key is null then raise exception 'Idempotency key required';end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_key::text,0));
 select * into prior from public.payroll_adjustments where created_by=auth.uid() and idempotency_key=p_key;
 if found then
  if prior.payroll_id is distinct from p_payroll or prior.kind is distinct from p_kind or prior.amount is distinct from p_amount or prior.reason is distinct from btrim(p_reason) or prior.attendance_id is distinct from p_attendance or prior.trip_id is distinct from p_trip then raise exception 'Idempotency key already used';end if;
  return prior.id;
 end if;
 select * into pay from public.teacher_payrolls where id=p_payroll;
 select * into period from public.payroll_periods where id=pay.period_id for update;
 if period.id is null or period.status not in ('GENERATED','REVIEW') then raise exception 'Adjustment requires generated or review payroll';end if;
 if p_kind='DEDUCTION' then
  select * into a from public.employee_attendance_entries where id=p_attendance and employee_id=pay.employee_id and status in ('LATE','EARLY_LEAVE') and checker is not null and work_date between period.starts_on and period.ends_on;
  if not found then raise exception 'Deduction requires payable late or early evidence from this payroll';end if;
  if not exists(select 1 from public.payroll_earning_lines l cross join lateral jsonb_array_elements(coalesce(l.calculation_snapshot->'sources','[]'::jsonb)) x where l.payroll_id=pay.id and x->'attendance'->>'id'=a.id::text and (x->>'payable_minutes')::integer>0) then raise exception 'Deduction evidence must match generated payable snapshot';end if;
  if p_trip is not null then raise exception 'Unexpected trip evidence';end if;
  source:=to_jsonb(a);
 elsif p_kind='TRAVEL_ALLOWANCE' then
  select x.* into t from public.employee_trips x join public.employee_trip_reviews r on r.trip_id=x.id and r.decision='APPROVED' where x.id=p_trip and x.employee_id=pay.employee_id;
  if not found then raise exception 'Approved trip for payroll employee required';end if;
  if p_attendance is not null then raise exception 'Unexpected attendance evidence';end if;
  source:=to_jsonb(t);
 elsif p_kind in ('BONUS','ADJUSTMENT','CORRECTION') then
  if p_attendance is not null or p_trip is not null then raise exception 'Unexpected evidence';end if;
 else raise exception 'Invalid adjustment kind';end if;
 insert into public.payroll_adjustments(payroll_id,kind,amount,reason,created_by,attendance_id,trip_id,source_snapshot,idempotency_key)
 values(pay.id,p_kind,p_amount,btrim(p_reason),auth.uid(),p_attendance,p_trip,source,p_key) returning id into result;
 if p_kind='DEDUCTION' then insert into hr_private.payroll_deducted_shifts values(pay.employee_id,a.work_date,a.shift_code,result);end if;
 update public.teacher_payrolls set adjustment_amount=adjustment_amount+p_amount,gross_amount=gross_amount+p_amount where id=pay.id;
 update public.payroll_periods set version=version+1 where id=period.id;
 insert into public.payroll_events(period_id,status,note,actor_id,event_type,after_snapshot) values(period.id,period.status,btrim(p_reason),auth.uid(),'EVIDENCE_ADJUSTMENT',jsonb_build_object('adjustment_id',result,'source',source));
 return result;
end$$;


ALTER FUNCTION "public"."add_payroll_evidence_adjustment"("p_payroll" "uuid", "p_kind" "text", "p_amount" numeric, "p_reason" "text", "p_attendance" "uuid", "p_trip" "uuid", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_payroll_trip_costs"("p_payroll" "uuid", "p_trip" "uuid", "p_allowance" numeric, "p_transport" numeric, "p_lodging" numeric, "p_reason" "text", "p_key" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare result uuid; prior public.payroll_trip_cost_breakdowns; state text;
begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Unauthorized';end if;
 if p_allowance is null or p_transport is null or p_lodging is null or least(p_allowance,p_transport,p_lodging)<0 or p_allowance<>round(p_allowance,2) or p_transport<>round(p_transport,2) or p_lodging<>round(p_lodging,2) then raise exception 'Invalid trip cost breakdown';end if;
 result:=public.add_payroll_evidence_adjustment(p_payroll,'TRAVEL_ALLOWANCE',p_allowance+p_transport+p_lodging,p_reason,null,p_trip,p_key);
 select * into prior from public.payroll_trip_cost_breakdowns where adjustment_id=result;
 if found then
  if prior.allowance<>p_allowance or prior.transport<>p_transport or prior.lodging<>p_lodging then raise exception 'Idempotency key already used';end if;
  return result;
 end if;
 select p.status into state from public.payroll_periods p join public.teacher_payrolls t on t.period_id=p.id where t.id=p_payroll for update of p;
 if state is null or state not in ('GENERATED','REVIEW') then raise exception 'Approved payroll is immutable';end if;
 insert into public.payroll_trip_cost_breakdowns values(result,p_allowance,p_transport,p_lodging);
 return result;
end$$;


ALTER FUNCTION "public"."add_payroll_trip_costs"("p_payroll" "uuid", "p_trip" "uuid", "p_allowance" numeric, "p_transport" numeric, "p_lodging" numeric, "p_reason" "text", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_payroll_v2_bonus"("p_period" "uuid", "p_version" integer, "p_employee" "uuid", "p_amount" numeric, "p_currency" "text", "p_reason" "text", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  period_row public.payroll_periods%rowtype;
  payroll_row public.teacher_payrolls%rowtype;
  prior public.payroll_period_actions_v2%rowtype;
  inserted public.payroll_period_actions_v2%rowtype;
  payload jsonb;
  before_state jsonb;
  after_state jsonb;
  normalized_currency text;
begin
  if auth.uid() is null
     or not coalesce(public.account_is_active(),false)
  then
    raise exception 'PAYROLL_V2_ACTION_UNAUTHORIZED';
  end if;

  select p.*
    into period_row
  from public.payroll_periods p
  where p.id=p_period
    and public.has_permission('payroll.prepare',p.branch_id)
    and (
      public.is_global_super_admin()
      or public.has_role_permission(
        'FINANCE',
        'payroll.prepare',
        p.branch_id
      )
    )
  for update;

  if not found then
    raise exception 'PAYROLL_V2_ACTION_UNAUTHORIZED';
  end if;

  normalized_currency :=
    upper(btrim(coalesce(p_currency,'')));

  if p_key is null then
    raise exception 'PAYROLL_V2_ACTION_KEY_REQUIRED';
  end if;

  if p_amount is null
     or p_amount <= 0
     or p_amount > 999999999999.99
     or p_amount <> round(p_amount,2)
     or p_amount='NaN'::numeric
  then
    raise exception 'PAYROLL_V2_BONUS_INVALID_AMOUNT';
  end if;

  if normalized_currency !~ '^[A-Z]{3}$' then
    raise exception 'PAYROLL_V2_ACTION_INVALID_CURRENCY';
  end if;

  if p_reason is null
     or char_length(btrim(p_reason)) not between 1 and 2000
  then
    raise exception 'PAYROLL_V2_ACTION_REASON_REQUIRED';
  end if;

  payload:=jsonb_build_object(
    'action','ADD_BONUS',
    'period_id',p_period,
    'period_version',p_version,
    'employee_id',p_employee,
    'amount',p_amount,
    'currency',normalized_currency,
    'reason',btrim(p_reason)
  );

  select *
    into prior
  from public.payroll_period_actions_v2 a
  where a.created_by=auth.uid()
    and a.request_key=p_key;

  if found then
    if prior.request_payload is distinct from payload then
      raise exception 'PAYROLL_V2_ACTION_KEY_ALREADY_USED';
    end if;

    return jsonb_build_object(
      'status',
        case
          when prior.status='ACTIVE' then 'ALREADY_ADDED'
          else 'ALREADY_CANCELLED'
        end,
      'action_id',prior.id,
      'period_id',prior.period_id,
      'employee_id',prior.employee_id,
      'component_code',prior.component_code,
      'amount',prior.amount,
      'currency',prior.currency
    );
  end if;

  if period_row.version is distinct from p_version then
    raise exception 'PAYROLL_V2_PERIOD_CHANGED_RELOAD';
  end if;

  if period_row.status not in ('GENERATED','REVIEW') then
    raise exception 'PAYROLL_V2_ACTION_REQUIRES_GENERATED_OR_REVIEW';
  end if;

  select t.*
    into payroll_row
  from public.teacher_payrolls t
  where t.period_id=period_row.id
    and t.employee_id=p_employee
    and t.calculation_version like 'PAYROLL_V2%'
  for update;

  if not found then
    raise exception 'PAYROLL_V2_HEADER_REQUIRED';
  end if;

  if payroll_row.currency is distinct from normalized_currency then
    raise exception 'PAYROLL_V2_ACTION_CURRENCY_MISMATCH';
  end if;

  before_state:=public.payroll_approval_snapshot(period_row.id);

  insert into public.payroll_period_actions_v2(
    period_id,
    employee_id,
    component_code,
    category,
    source_type,
    source_expense_claim_id,
    amount,
    currency,
    reason,
    request_key,
    request_payload,
    source_snapshot,
    created_by
  )
  values(
    period_row.id,
    p_employee,
    'BONUS',
    'EARNING',
    'MANUAL_BONUS',
    null,
    p_amount,
    normalized_currency,
    btrim(p_reason),
    p_key,
    payload,
    jsonb_build_object(
      'calculation_version','PAYROLL_V2_PERIOD_ACTIONS_V1',
      'entered_manually',true
    ),
    auth.uid()
  )
  returning * into inserted;

  perform public.refresh_staff_payroll_v2_totals(
    period_row.id,
    p_employee
  );

  update public.payroll_periods
  set version=version+1
  where id=period_row.id;

  after_state:=public.payroll_approval_snapshot(period_row.id);

  insert into public.payroll_events(
    period_id,
    status,
    note,
    actor_id,
    event_type,
    before_snapshot,
    after_snapshot
  )
  values(
    period_row.id,
    period_row.status,
    btrim(p_reason),
    auth.uid(),
    'V2_PERIOD_ACTION',
    before_state,
    after_state
  );

  return jsonb_build_object(
    'status','ADDED',
    'action_id',inserted.id,
    'period_id',inserted.period_id,
    'employee_id',inserted.employee_id,
    'component_code',inserted.component_code,
    'amount',inserted.amount,
    'currency',inserted.currency
  );
end;
$_$;


ALTER FUNCTION "public"."add_payroll_v2_bonus"("p_period" "uuid", "p_version" integer, "p_employee" "uuid", "p_amount" numeric, "p_currency" "text", "p_reason" "text", "p_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_payroll_v2_bonus"("p_period" "uuid", "p_version" integer, "p_employee" "uuid", "p_amount" numeric, "p_currency" "text", "p_reason" "text", "p_key" "uuid") IS 'Adds a non-recurring BONUS to one Staff payroll period with optimistic period version and idempotency key.';



CREATE OR REPLACE FUNCTION "public"."add_session_compensation_rule"("p_teacher" "uuid", "p_branch" "uuid", "p_class_type" "text", "p_rate" numeric, "p_currency" "text", "p_from" "date", "p_to" "date" DEFAULT NULL::"date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$declare result uuid;begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Unauthorized';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_teacher::text||p_branch::text,0));
 if not exists(select 1 from public.teachers t join public.teacher_branches b on b.teacher_id=t.id where t.id=p_teacher and t.status='ACTIVE' and b.branch_id=p_branch) then raise exception 'Invalid teacher branch';end if;
 if exists(select 1 from public.teacher_compensation_rules r where r.teacher_id=p_teacher and r.branch_id=p_branch and r.status='ACTIVE' and (r.class_type is null or r.class_type=p_class_type or r.pay_type<>'PER_SESSION' or r.currency<>p_currency) and daterange(r.effective_from,r.effective_to,'[]') && daterange(p_from,p_to,'[]')) then raise exception 'Compensation dates overlap';end if;
 if exists(select 1 from public.employees e join public.teacher_compensation_rules r on r.employee_id=e.id where e.teacher_id=p_teacher and r.status='ACTIVE' and daterange(r.effective_from,r.effective_to,'[]') && daterange(p_from,p_to,'[]')) then raise exception 'Resolve existing employee compensation before teacher compensation';end if;
 insert into public.teacher_compensation_rules(teacher_id,branch_id,pay_type,class_type,rate,currency,effective_from,effective_to,created_by)
 values(p_teacher,p_branch,'PER_SESSION',p_class_type,p_rate,p_currency,p_from,p_to,auth.uid()) returning id into result;return result;
end$$;


ALTER FUNCTION "public"."add_session_compensation_rule"("p_teacher" "uuid", "p_branch" "uuid", "p_class_type" "text", "p_rate" numeric, "p_currency" "text", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adopt_teacher_as_staff"("p_teacher" "uuid", "p_home" "text", "p_hire_date" "date", "p_legacy_pay_type" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  t public.teachers%rowtype;
  existing_employee public.employees%rowtype;
  eid uuid;
  bid uuid;
  n bigint;
  employee_code_value text;
  full_name_value text;
  primary_branch boolean;
begin
  if auth.uid() is null
     or not coalesce(public.account_is_active(),false)
     or not coalesce(public.has_role('SUPER_ADMIN'),false)
  then
    raise exception 'STAFF_ADOPT_UNAUTHORIZED';
  end if;

  if p_teacher is null then raise exception 'STAFF_ADOPT_TEACHER_REQUIRED'; end if;
  if p_home is null or char_length(btrim(p_home)) not between 1 and 50 then
    raise exception 'STAFF_ADOPT_HOME_REQUIRED';
  end if;
  if p_hire_date is null or not isfinite(p_hire_date) then
    raise exception 'STAFF_ADOPT_INVALID_HIRE_DATE';
  end if;
  if p_legacy_pay_type not in ('MONTHLY','PER_SESSION','HOURLY') then
    raise exception 'STAFF_ADOPT_INVALID_LEGACY_PAY_TYPE';
  end if;
  if p_reason is null or char_length(btrim(p_reason)) not between 1 and 2000 then
    raise exception 'STAFF_ADOPT_REASON_REQUIRED';
  end if;

  select * into t
  from public.teachers
  where id = p_teacher
  for update;

  if not found then raise exception 'STAFF_ADOPT_TEACHER_NOT_FOUND'; end if;
  if t.status <> 'ACTIVE' then raise exception 'STAFF_ADOPT_ACTIVE_TEACHER_REQUIRED'; end if;

  select * into existing_employee
  from public.employees
  where teacher_id = t.id;

  if found then
    return jsonb_build_object(
      'status','ALREADY_STAFF',
      'employee_id',existing_employee.id,
      'employee_code',existing_employee.employee_code,
      'teacher_id',t.id
    );
  end if;

  select u.branch_id into bid
  from public.organization_units u
  join public.branches b on b.id = u.branch_id and b.status = 'ACTIVE'
  where u.code = btrim(p_home);

  if bid is null then
    raise exception 'STAFF_ADOPT_ACTIVE_HOME_BRANCH_REQUIRED';
  end if;

  perform hr_private.check_links(t.user_id,t.id);

  insert into hr_private.employee_counters(unit_code,last_number)
  values(btrim(p_home),1)
  on conflict(unit_code)
  do update set last_number = hr_private.employee_counters.last_number + 1
  returning last_number into n;

  employee_code_value :=
    'VIBE-' || btrim(p_home) || '-' ||
    lpad(n::text,greatest(4,length(n::text)),'0');

  full_name_value := coalesce(nullif(btrim(t.full_name),''), t.teacher_code);

  insert into public.employees(
    employee_code,home_unit,hire_date,profile_id,teacher_id,created_by
  )
  values(
    employee_code_value,btrim(p_home),p_hire_date,t.user_id,t.id,auth.uid()
  )
  returning id into eid;

  insert into public.employee_audit(
    employee_id,action,after_data,reason,actor
  )
  select eid,'IDENTITY_CREATED',to_jsonb(e),btrim(p_reason),auth.uid()
  from public.employees e
  where e.id = eid;

  perform public.set_employee_version(
    eid,0,p_hire_date,full_name_value,btrim(p_home),
    'STAFF','ACTIVE',p_legacy_pay_type,null,btrim(p_reason)
  );

  insert into public.staff_role_assignments(
    employee_id,role_code,branch_id,effective_from,is_primary,status,reason,created_by
  )
  values(
    eid,'TEACHER',bid,p_hire_date,true,'ACTIVE',btrim(p_reason),auth.uid()
  );

  primary_branch := not exists(
    select 1 from public.teacher_branches tb
    where tb.teacher_id = t.id and tb.is_primary
  );

  insert into public.teacher_branches(teacher_id,branch_id,is_primary)
  values(t.id,bid,primary_branch)
  on conflict(teacher_id,branch_id) do nothing;

  return jsonb_build_object(
    'status','ADOPTED',
    'employee_id',eid,
    'employee_code',employee_code_value,
    'teacher_id',t.id,
    'role_code','TEACHER',
    'branch_id',bid,
    'home_unit',btrim(p_home),
    'hire_date',p_hire_date,
    'legacy_pay_type',p_legacy_pay_type,
    'payroll_v2_integration','NOT_ENABLED_IN_STAFF_FOUNDATION_V1'
  );
end;
$$;


ALTER FUNCTION "public"."adopt_teacher_as_staff"("p_teacher" "uuid", "p_home" "text", "p_hire_date" "date", "p_legacy_pay_type" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aggregate_student_learning_observations"("p_student" "uuid", "p_from" "date", "p_to" "date") RETURNS TABLE("dimension" "text", "observation_code" "text", "development_level" "text", "signal" "text", "observation_count" integer, "first_observed_on" "date", "latest_observed_on" "date", "curriculum_context" "text", "next_focus_code" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select option.dimension, option.code, option.development_level, option.signal,
    count(*)::integer,
    min(occurrence.occurrence_date),
    max(occurrence.occurrence_date),
    (array_agg(journal.curriculum_context order by occurrence.occurrence_date desc))[1],
    (array_agg(entry.next_focus_code order by occurrence.occurrence_date desc))[1]
  from public.student_journal_observation_selections selection
  join public.student_learning_journal_entries entry on entry.id = selection.entry_id
  join public.session_learning_journals journal on journal.id = entry.session_journal_id
  join public.attendance_records attendance on attendance.id = entry.attendance_record_id
  join public.enrollments enrollment on enrollment.id = attendance.enrollment_id
  join public.session_occurrences occurrence on occurrence.id = attendance.session_occurrence_id
  join public.learning_observation_options option on option.code = selection.option_code
  where enrollment.student_id = p_student
    and journal.status = 'SUBMITTED'
    and public.can_read_session_journal(occurrence.id)
    and (p_from is null or occurrence.occurrence_date >= p_from)
    and (p_to is null or occurrence.occurrence_date <= p_to)
  group by option.dimension, option.code, option.development_level, option.signal
  order by count(*) desc, option.code
$$;


ALTER FUNCTION "public"."aggregate_student_learning_observations"("p_student" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."allocate_payment_to_invoice"("p_payment_id" "uuid", "p_invoice_id" "uuid", "p_amount" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_payment public.payments%rowtype;

  v_invoice public.invoices%rowtype;

  v_payment_allocated numeric(14,2);

  v_invoice_allocated numeric(14,2);

  v_allocation_id uuid :=
    gen_random_uuid();
begin
  if not public.has_role(
    'SUPER_ADMIN'
  ) then
    raise exception
      'SUPER_ADMIN role required';
  end if;


  if p_payment_id is null
    or p_invoice_id is null
  then
    raise exception
      'Payment id and invoice id are required';
  end if;


  if p_amount is null
    or p_amount <= 0
  then
    raise exception
      'Allocation amount must be greater than zero';
  end if;


  select *
  into v_payment
  from public.payments
  where id = p_payment_id
  for update;


  if not found then
    raise exception
      'Payment not found';
  end if;


  if v_payment.status <>
    'POSTED'
  then
    raise exception
      'Only posted payments can be allocated';
  end if;


  select *
  into v_invoice
  from public.invoices
  where id = p_invoice_id
  for update;


  if not found then
    raise exception
      'Invoice not found';
  end if;


  if v_invoice.status <>
    'ISSUED'
  then
    raise exception
      'Payments can only be allocated to issued invoices';
  end if;


  if v_payment.student_id_snapshot <>
    v_invoice.student_id_snapshot
  then
    raise exception
      'Payment and invoice must belong to the same student';
  end if;


  if v_payment.currency <>
    v_invoice.currency
  then
    raise exception
      'Payment and invoice currencies must match';
  end if;


  if exists (
    select 1
    from public.payment_allocations
    where payment_id =
      p_payment_id
      and invoice_id =
        p_invoice_id
  ) then
    raise exception
      'This payment is already allocated to this invoice';
  end if;


  select coalesce(
    sum(allocation.amount),
    0
  )
  into v_payment_allocated
  from public.payment_allocations
    as allocation
  where allocation.payment_id =
    p_payment_id;


  if v_payment_allocated
      + p_amount
      > v_payment.amount
  then
    raise exception
      'Allocation exceeds the remaining payment amount';
  end if;


  select coalesce(
    sum(allocation.amount),
    0
  )
  into v_invoice_allocated
  from public.payment_allocations
    as allocation
  join public.payments
    as payment
    on payment.id =
      allocation.payment_id
  where allocation.invoice_id =
    p_invoice_id
    and payment.status =
      'POSTED';


  if v_invoice_allocated
      + p_amount
      > v_invoice.total_amount
  then
    raise exception
      'Allocation exceeds the remaining invoice balance';
  end if;


  insert into public.payment_allocations (
    id,
    payment_id,
    invoice_id,
    amount
  )
  values (
    v_allocation_id,
    p_payment_id,
    p_invoice_id,
    p_amount
  );


  return v_allocation_id;
end;
$$;


ALTER FUNCTION "public"."allocate_payment_to_invoice"("p_payment_id" "uuid", "p_invoice_id" "uuid", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."allocate_payment_to_opening"("p_payment_id" "uuid", "p_opening_receivable_id" "uuid", "p_amount" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare p public.payments; o public.opening_receivables; a public.payment_allocations; available numeric; balance numeric; result uuid;
begin
 if not public.is_global_super_admin() then raise exception 'Unauthorized'; end if;
 if p_amount is null or p_amount<=0 or p_amount>=1000000000000 or p_amount<>round(p_amount,2) then raise exception 'Invalid allocation amount'; end if;
 select * into p from public.payments where id=p_payment_id for update;
 select * into o from public.opening_receivables where id=p_opening_receivable_id for update;
 if p.id is null or o.id is null then raise exception 'Payment or opening receivable not found'; end if;
 if p.status<>'POSTED' then raise exception 'Only posted payments can be allocated'; end if;
 if p.student_id_snapshot<>o.student_id or p.branch_id_snapshot<>o.branch_id or p.currency<>o.currency then raise exception 'Payment and opening scope must match'; end if;
 if o.currency='VND' and p_amount<>trunc(p_amount) then raise exception 'VND amount must be integral'; end if;
 if (p.paid_at at time zone 'Asia/Ho_Chi_Minh')::date<o.opening_as_of_date or p.paid_at>now() then raise exception 'Opening collection must have an actual post-cutover receipt date'; end if;
 if exists(select 1 from public.opening_reversals where receivable_id=o.id) then raise exception 'Opening receivable was reversed'; end if;
 select * into a from public.payment_allocations where payment_id=p.id and opening_receivable_id=o.id;
 if found then
  if a.amount<>p_amount then raise exception 'Existing allocation amount differs'; end if;
  return a.id;
 end if;
 select p.amount-coalesce(sum(amount),0) into available from public.payment_allocations where payment_id=p.id;
 if p_amount>available then raise exception 'Allocation exceeds the remaining payment amount'; end if;
 -- Do not repurpose already-refunded cash as a new opening collection.
 if exists(select 1 from public.refunds where payment_id=p.id and status='POSTED') then raise exception 'Allocate before refunding payment'; end if;
 select outstanding_balance into balance from public.opening_receivable_balances where id=o.id;
 if p_amount>balance then raise exception 'Allocation exceeds the remaining opening balance'; end if;
 insert into public.payment_allocations(payment_id,opening_receivable_id,amount) values(p.id,o.id,p_amount) returning id into result;
 return result;
end $$;


ALTER FUNCTION "public"."allocate_payment_to_opening"("p_payment_id" "uuid", "p_opening_receivable_id" "uuid", "p_amount" numeric) OWNER TO "postgres";


