CREATE OR REPLACE FUNCTION "public"."allocate_registration_deposits_to_invoice"("p_application" "uuid", "p_invoice" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  app public.registration_applications%rowtype;
  invoice public.invoices%rowtype;
  receipt record;
  outstanding numeric;
  allocated integer := 0;
begin
  if auth.uid() is null or not public.has_role('SUPER_ADMIN') then
    raise exception 'REGISTRATION_UNAUTHORIZED';
  end if;
  if p_application is null or p_invoice is null then
    raise exception 'REGISTRATION_INVALID';
  end if;
  select * into app from public.registration_applications where id = p_application for update;
  if not found or app.status <> 'COMPLETED' or app.linked_student_id is null then
    raise exception 'REGISTRATION_ALLOCATION_DENIED';
  end if;
  select * into invoice from public.invoices where id = p_invoice for update;
  if not found or invoice.status <> 'ISSUED'
     or invoice.student_id_snapshot <> app.linked_student_id
     or invoice.branch_id_snapshot <> app.branch_id then
    raise exception 'REGISTRATION_INVOICE_MISMATCH';
  end if;
  for receipt in
    select payment.id, payment.amount
    from public.payments payment
    where payment.status = 'POSTED'
      and payment.id in (
        select momo.finance_payment_id
        from public.registration_momo_orders momo
        where momo.application_id = app.id
          and momo.state = 'PAID'
          and momo.finance_payment_id is not null
        union
        select payos.finance_payment_id
        from public.registration_payos_orders payos
        where payos.application_id = app.id
          and payos.state = 'PAID'
          and payos.finance_payment_id is not null
      )
    order by payment.paid_at, payment.id
    for update of payment
  loop
    if exists (
      select 1 from public.payment_allocations allocation
      where allocation.payment_id = receipt.id and allocation.invoice_id = invoice.id
    ) then
      continue;
    end if;
    select outstanding_balance into outstanding
    from public.invoice_receivables where invoice_id = invoice.id;
    if coalesce(outstanding, 0) <= 0 then
      exit;
    end if;
    perform public.allocate_payment_to_invoice(
      receipt.id, invoice.id, least(receipt.amount, outstanding));
    allocated := allocated + 1;
  end loop;
  if app.invoice_id is null then
    perform set_config('registration.write', 'on', true);
    update public.registration_applications
    set invoice_id = invoice.id, updated_at = clock_timestamp()
    where id = app.id and invoice_id is null;
    perform set_config('registration.write', 'off', true);
  end if;
  return allocated;
end $$;


ALTER FUNCTION "public"."allocate_registration_deposits_to_invoice"("p_application" "uuid", "p_invoice" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_shared_journal_practice"("p_session" "uuid", "p_homework" "text", "p_focus" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  updated_count integer;
begin
  if not public.can_write_session_journal(p_session) then raise exception 'JOURNAL_UNAUTHORIZED'; end if;
  if p_focus is not null and not exists(select 1 from public.learning_focus_options focus where focus.code = p_focus and focus.active) then
    raise exception 'JOURNAL_FOCUS_DENIED';
  end if;
  perform public.ensure_session_learning_journal(p_session);
  perform set_config('journal.taxonomy_write', 'on', true);
  insert into public.student_learning_journal_entries(session_journal_id, attendance_record_id, individual_homework, next_focus_code)
  select journal.id, attendance.id, coalesce(p_homework, ''), p_focus
  from public.session_learning_journals journal
  join public.attendance_records attendance on attendance.session_occurrence_id = journal.session_occurrence_id
  where journal.session_occurrence_id = p_session
    and attendance.status in ('PRESENT','LATE')
    and not exists(select 1 from public.student_learning_journal_entries existing where existing.attendance_record_id = attendance.id);
  update public.student_learning_journal_entries entry set
    individual_homework = coalesce(p_homework, entry.individual_homework),
    next_focus_code = coalesce(p_focus, entry.next_focus_code),
    version = entry.version + 1,
    updated_at = clock_timestamp()
  from public.attendance_records attendance, public.session_learning_journals journal
  where entry.attendance_record_id = attendance.id
    and entry.session_journal_id = journal.id
    and journal.session_occurrence_id = p_session
    and attendance.status in ('PRESENT','LATE')
    and not entry.homework_custom;
  get diagnostics updated_count = row_count;
  perform set_config('journal.taxonomy_write', 'off', true);
  return updated_count;
end $$;


ALTER FUNCTION "public"."apply_shared_journal_practice"("p_session" "uuid", "p_homework" "text", "p_focus" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_tuition_zalo_response"("p_payload" "jsonb", "p_oa_id" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare message jsonb; candidate public.tuition_zalo_sends; outcome text;
begin
  if p_payload is null or jsonb_typeof(p_payload)<>'object' then return 'invalid_payload'; end if;
  if p_payload->>'event_name' is distinct from 'user_click_response_button' then return 'ignored'; end if;
  if p_oa_id is null or p_payload->>'oa_id' is distinct from p_oa_id then return 'oa_mismatch'; end if;
  if coalesce(p_payload->>'app_id','') !~ '^[0-9]{8,32}$' then return 'app_mismatch'; end if;
  if coalesce(p_payload->>'timestamp','') !~ '^[0-9]{10,16}$' then return 'invalid_time'; end if;
  message:=p_payload->'message';
  if jsonb_typeof(message) is distinct from 'object' then return 'invalid_message'; end if;
  if message->>'button_type' is distinct from 'response' then return 'invalid_button'; end if;
  select * into candidate from tuition_zalo_sends where tracking_id=message->>'tracking_id';
  if found and candidate.context_captured_at is not null then
    if candidate.app_id is distinct from p_payload->>'app_id' then return 'app_mismatch'; end if;
    if candidate.oa_id is distinct from p_oa_id then return 'oa_mismatch'; end if;
    if candidate.provider_template_id is distinct from '643118' then return 'template_mismatch'; end if;
  end if;
  outcome:=public.record_tuition_zalo_reply('Zalo ZBS',message->>'tracking_id',p_payload->>'msg_id',message->>'data',message->>'submit_time',p_oa_id);
  return case when outcome='conflict' then 'recorded' else outcome end;
end $_$;


ALTER FUNCTION "public"."apply_tuition_zalo_response"("p_payload" "jsonb", "p_oa_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_zalo_interaction_event"("p_payload" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  event_name text := p_payload->>'event_name';
  event_data jsonb := p_payload->'data';
  zalo_user_id text := event_data->>'user_id';
  external_key text := event_data->>'user_external_id';
  event_timestamp text := p_payload->>'timestamp';
  event_consent timestamptz;
  link public.customer_channel_links;
  conflict public.customer_channel_links;
  failure_reason text;
begin
  if event_name is null
    or event_name not in ('widget_interaction_accepted', 'widget_failed_to_sync_user_external_id') then
    return 'ignored';
  end if;
  if external_key is null or external_key !~ '^[A-Za-z0-9_-]{6,80}$' then
    return 'missing';
  end if;
  if zalo_user_id is null or zalo_user_id !~ '^[0-9]{8,32}$' then
    return 'missing';
  end if;

  select * into link
  from public.customer_channel_links
  where provider = 'ZALO'
    and external_link_key = external_key
    and registration_application_id is not null
    and status <> 'REVOKED';
  if not found then
    return 'missing';
  end if;

  if event_name = 'widget_failed_to_sync_user_external_id' then
    if link.status in ('REVIEW', 'ACTIVE') then
      return 'idempotent';
    end if;
    failure_reason := case event_data->>'message'
      when 'user already has user_external_id' then 'external_id_already_set'
      when 'user_externa_id already belongs to another user' then 'external_id_owned_elsewhere'
      when 'user_external_id already belongs to another user' then 'external_id_owned_elsewhere'
      else 'external_id_sync_failed'
    end;
    update public.customer_channel_links
    set status = 'REVIEW'
    where id = link.id
      and status = 'PENDING';
    perform set_config('registration.write', 'on', true);
    insert into public.registration_application_events(
      id, application_id, event_type, actor_id, metadata
    ) values (
      gen_random_uuid(), link.registration_application_id, 'ZALO_LINK_FAILED', null,
      jsonb_build_object('reason', failure_reason)
    );
    return 'review';
  end if;

  if link.status = 'ACTIVE' and link.provider_user_id = zalo_user_id then
    update public.customer_channel_links
    set last_verified_at = clock_timestamp()
    where id = link.id;
    return 'idempotent';
  end if;
  if link.status = 'ACTIVE' then
    return 'review';
  end if;

  select * into conflict
  from public.customer_channel_links
  where provider = 'ZALO'
    and provider_user_id = zalo_user_id
    and status <> 'REVOKED'
    and id <> link.id;
  if found then
    if link.status = 'REVIEW' then
      return 'idempotent';
    end if;
    update public.customer_channel_links
    set status = 'REVIEW'
    where id = link.id
      and status = 'PENDING';
    perform set_config('registration.write', 'on', true);
    insert into public.registration_application_events(
      id, application_id, event_type, actor_id, metadata
    ) values (
      gen_random_uuid(), link.registration_application_id, 'ZALO_LINK_FAILED', null,
      jsonb_build_object('reason', 'provider_user_conflict')
    );
    return 'review';
  end if;

  if event_timestamp ~ '^\d{10,16}$' then
    event_consent := to_timestamp(event_timestamp::numeric / 1000.0);
  else
    event_consent := clock_timestamp();
  end if;

  update public.customer_channel_links
  set provider_user_id = zalo_user_id,
      status = 'ACTIVE',
      consent_at = event_consent,
      linked_at = clock_timestamp(),
      last_verified_at = clock_timestamp()
  where id = link.id
    and status in ('PENDING', 'REVIEW');
  if not found then
    return 'idempotent';
  end if;

  perform set_config('registration.write', 'on', true);
  insert into public.registration_application_events(
    id, application_id, event_type, actor_id, metadata
  ) values (
    gen_random_uuid(), link.registration_application_id, 'ZALO_LINK_CONFIRMED', null, '{}'::jsonb
  );
  return 'activated';
exception
  when unique_violation then
    update public.customer_channel_links
    set status = 'REVIEW',
        provider_user_id = null,
        linked_at = null,
        consent_at = null
    where id = link.id
      and status in ('PENDING', 'REVIEW');
    return 'review';
end;
$_$;


ALTER FUNCTION "public"."apply_zalo_interaction_event"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_financial_action"("p_request_id" "uuid", "p_note" "text", "p_override_type" "text" DEFAULT NULL::"text", "p_override_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r public.financial_approval_requests; validated jsonb; payment_id uuid; result uuid; emergency boolean;
 source public.teacher_payrolls; dest public.payroll_periods; dest_payroll uuid; adjustment uuid;
 snapshot jsonb; before_state jsonb; after_state jsonb; delta numeric; source_earning uuid;source_adjustment uuid;
begin
 select * into r from public.financial_approval_requests q where q.id=p_request_id
 and public.finance_action_allowed(finance_private.operation_permission(q.operation,'approve'),q.branch_id) for update;
 if not found then raise exception 'Unauthorized'; end if;
 if r.status='POSTED' then return r.result_id; end if;
 if r.status<>'PENDING_APPROVAL' then raise exception 'Request is not pending approval'; end if;
 if p_note is null or char_length(btrim(p_note)) not between 1 and 2000 then raise exception 'Approval note required'; end if;
 emergency:=p_override_type is not null or p_override_reason is not null;
 if emergency then
   if not public.is_global_super_admin() or p_override_type is distinct from 'MAKER_CHECKER_EMERGENCY'
     or p_override_reason is null or char_length(btrim(p_override_reason)) not between 1 and 2000 then
     raise exception 'Valid SUPER_ADMIN emergency override reason and type required'; end if;
 elsif r.maker_user_id=auth.uid() then raise exception 'Maker cannot approve own financial request';
 end if;
 if r.operation='PAYROLL_CORRECTION' then
   perform pg_advisory_xact_lock(hashtextextended('payroll-correction:'||r.target_id::text,0));
   select * into source from public.teacher_payrolls where id=r.target_id;
   perform 1 from public.payroll_periods where id=source.period_id for update;
   if r.details->>'run_type'='NEXT_OPEN_PERIOD' then
     select * into dest from public.payroll_periods where id=(r.source_snapshot->'target_period'->>'id')::uuid for update;
   end if;
 elsif r.operation in ('APPLY_CUSTOMER_CREDIT','REFUND_CUSTOMER_CREDIT') then
   select c.payment_id into payment_id from public.customer_credits c where c.id=r.target_id;
   perform 1 from public.payments where id=payment_id for update;
   perform 1 from public.customer_credits where id=r.target_id for update;
   if r.details->>'invoice_id' is not null then perform 1 from public.invoices where id=(r.details->>'invoice_id')::uuid for update; end if;
   if r.details->>'opening_receivable_id' is not null then perform 1 from public.opening_receivables where id=(r.details->>'opening_receivable_id')::uuid for update; end if;
 elsif r.operation='OPENING_RECEIVABLE_CORRECTION' then
   perform 1 from public.payments p where p.id in(select a.payment_id from public.payment_allocations a where a.opening_receivable_id=r.target_id) order by p.id for update;
   perform 1 from public.opening_receivables where id=r.target_id for update;
 elsif r.operation='CANCEL_INVOICE' then
   perform 1 from public.invoices where id=r.target_id for update;
 else
   if r.operation in ('REFUND','VOID_PAYMENT') then payment_id:=r.target_id;
   else select f.payment_id into payment_id from public.refunds f where f.id=r.target_id; end if;
   -- Serialize refund amount checks, allocations and payment/refund reversals per original payment.
   perform 1 from public.payments where id=payment_id for update;
   if r.operation in ('VOID_REFUND','ALLOCATE_REFUND') then perform 1 from public.refunds where id=r.target_id for update; end if;
 end if;
 validated:=finance_private.validate_request(r.operation,r.target_id,r.details,finance_private.operation_permission(r.operation,'approve'));
 if validated->'source' is distinct from r.source_snapshot then raise exception 'Source changed; cancel and create a new request'; end if;
 before_state:=to_jsonb(r);
 update public.financial_approval_requests set status='APPROVED',approver_user_id=auth.uid(),approved_at=now() where id=r.id;
 insert into public.financial_approval_events(request_id,event,performed_by,reason,override_type,before_snapshot,after_snapshot)
 values(r.id,case when emergency then 'EMERGENCY_OVERRIDE' else 'APPROVED' end,auth.uid(),
 case when emergency then btrim(p_override_reason) else btrim(p_note) end,case when emergency then p_override_type end,
 before_state,jsonb_build_object('status','APPROVED','source',r.source_snapshot,'details',r.details));
 if r.operation in ('APPLY_CUSTOMER_CREDIT','REFUND_CUSTOMER_CREDIT') then
   if r.operation='APPLY_CUSTOMER_CREDIT' then
    result:=gen_random_uuid();
    insert into public.customer_credit_uses(id,credit_id,kind,amount,payment_allocation_id) values(r.id,r.target_id,'APPLY',(r.details->>'amount')::numeric,result);
    insert into public.payment_allocations(id,payment_id,invoice_id,opening_receivable_id,amount,credit_use_id)
     values(result,payment_id,(r.details->>'invoice_id')::uuid,(r.details->>'opening_receivable_id')::uuid,(r.details->>'amount')::numeric,r.id);
   else
    result:=finance_private.create_refund(payment_id,(r.details->>'amount')::numeric,(r.details->>'refunded_at')::timestamptz,r.reason,'Customer credit refund');
    insert into public.customer_credit_uses(id,credit_id,kind,amount,refund_id) values(r.id,r.target_id,'REFUND',(r.details->>'amount')::numeric,result);
   end if;
   select to_jsonb(c) into after_state from public.customer_credit_balances c where id=r.target_id;
 elsif r.operation='OPENING_RECEIVABLE_CORRECTION' then
   snapshot:=validated->'source';
   insert into public.opening_receivable_corrections(id,opening_receivable_id,migration_batch_id,migration_row_id,source_reference,original_amount,old_amount,corrected_amount,delta,currency,reason,maker_user_id,checker_user_id,created_at,approved_at)
   values(r.id,r.target_id,(snapshot->>'migration_batch_id')::uuid,(snapshot->'opening'->>'migration_row_id')::uuid,snapshot->>'source_reference',(snapshot->>'original_amount')::numeric,(snapshot->>'old_amount')::numeric,(snapshot->>'corrected_amount')::numeric,(snapshot->>'delta')::numeric,snapshot->>'currency',r.reason,r.maker_user_id,auth.uid(),r.created_at,now());
   perform finance_private.release_opening_credit(r.id);
   result:=r.id; select to_jsonb(c) into after_state from public.opening_receivable_corrections c where id=result;
 elsif r.operation='REFUND' then
   result:=finance_private.create_refund(r.target_id,(r.details->>'amount')::numeric,(r.details->>'refunded_at')::timestamptz,r.reason,r.details->>'notes');
   select to_jsonb(f) into after_state from public.refunds f where f.id=result;
 elsif r.operation='VOID_PAYMENT' then
   perform finance_private.void_payment(r.target_id,r.reason);result:=r.target_id;
   select to_jsonb(p) into after_state from public.payments p where p.id=result;
 elsif r.operation='VOID_REFUND' then
   perform finance_private.void_refund(r.target_id,r.reason);result:=r.target_id;
   select to_jsonb(f) into after_state from public.refunds f where f.id=result;
 elsif r.operation='CANCEL_INVOICE' then
   perform finance_private.cancel_invoice(r.target_id,r.reason);result:=r.target_id;
   select to_jsonb(i) into after_state from public.invoices i where i.id=result;
 elsif r.operation='ALLOCATE_REFUND' then
   result:=finance_private.allocate_refund_to_payment_allocation(r.target_id,(r.details->>'payment_allocation_id')::uuid,(r.details->>'amount')::numeric);
   select to_jsonb(a) into after_state from public.refund_allocations a where a.id=result;
 else
   snapshot:=validated->'source'; delta:=(snapshot->>'delta')::numeric;
   source_earning:=(snapshot->>'earning_id')::uuid;source_adjustment:=(snapshot->>'adjustment_id')::uuid;
   if r.details->>'run_type'='NEXT_OPEN_PERIOD' then
     select id into dest_payroll from public.teacher_payrolls where period_id=dest.id and ((source.employee_id is not null and employee_id=source.employee_id) or (source.employee_id is null and teacher_id=source.teacher_id));
     if not found then
       insert into public.teacher_payrolls(period_id,teacher_id,employee_id,branch_id,teacher_name,pay_type,currency)
       values(dest.id,source.teacher_id,source.employee_id,source.branch_id,source.teacher_name,source.pay_type,source.currency) returning id into dest_payroll;
     end if;
     insert into public.payroll_adjustments(payroll_id,kind,amount,reason,created_by)
       values(dest_payroll,'CORRECTION',delta,r.reason,r.maker_user_id) returning id into adjustment;
     update public.teacher_payrolls set adjustment_amount=adjustment_amount+delta,gross_amount=gross_amount+delta where id=dest_payroll;
     update public.payroll_periods set version=version+1 where id=dest.id;
     insert into public.payroll_events(period_id,status,note,actor_id,event_type,before_snapshot,after_snapshot)
       values(dest.id,dest.status,'Correction from finalized payroll: '||r.target_id::text||' — '||r.reason,auth.uid(),'CORRECTION_POSTED',
         snapshot,jsonb_build_object('request_id',r.id,'adjustment_id',adjustment,'delta',delta));
   end if;
   insert into public.payroll_corrections(id,original_payroll_id,original_earning_id,original_adjustment_id,original_amount,corrected_amount,delta,
     currency,reason,target_period_id,posted_adjustment_id,run_type,maker_user_id,checker_user_id,created_at,approved_at)
   values(r.id,source.id,source_earning,source_adjustment,(snapshot->>'original_amount')::numeric,(snapshot->>'corrected_amount')::numeric,delta,
     source.currency,r.reason,dest.id,adjustment,r.details->>'run_type',r.maker_user_id,auth.uid(),r.created_at,now());
   result:=r.id;
   select to_jsonb(c) into after_state from public.payroll_corrections c where c.id=result;
 end if;
 update public.financial_approval_requests set status='POSTED',posted_at=now(),result_id=result where id=r.id;
 insert into public.financial_approval_events(request_id,event,performed_by,reason,before_snapshot,after_snapshot)
 values(r.id,'POSTED',auth.uid(),btrim(p_note),r.source_snapshot,after_state);
 return result;
end $$;


ALTER FUNCTION "public"."approve_financial_action"("p_request_id" "uuid", "p_note" "text", "p_override_type" "text", "p_override_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_learning_assessment"("p_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$declare p public.learning_assessments;begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Unauthorized'; end if;
 if p_reason is null or length(trim(p_reason)) not between 1 and 2000 then raise exception 'Review reason required'; end if;
 select * into p from public.learning_assessments where id=p_id for update;
 if not found or p.state<>'DRAFT' then raise exception 'Assessment is not draft'; end if;
 if p.author_id=auth.uid() then raise exception 'Independent content reviewer required'; end if;
 update public.learning_assessments set state='APPROVED',reviewer_id=auth.uid(),review_note=trim(p_reason) where id=p_id;
 insert into public.learning_audit(entity_id,event,actor,reason) values(p_id,'ASSESSMENT_APPROVED',auth.uid(),trim(p_reason));
end$$;


ALTER FUNCTION "public"."approve_learning_assessment"("p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_payroll_retroactive_claim"("p_claim" "uuid", "p_version" integer, "p_target_period" "uuid", "p_note" "text", "p_override_type" "text", "p_override_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  c public.payroll_retroactive_claims%rowtype;
  target_row public.payroll_periods%rowtype;
  source_row public.payroll_periods%rowtype;
  emergency boolean;
begin
  select r.*
  into c
  from public.payroll_retroactive_claims r
  where r.id = p_claim
    and public.has_permission(
      'payroll.approve',
      r.branch_id
    )
    and (
      public.is_global_super_admin()
      or public.has_role_permission(
        'FINANCE',
        'payroll.approve',
        r.branch_id
      )
    )
  for update;

  if not found then
    raise exception 'RETROACTIVE_UNAUTHORIZED';
  end if;

  if c.version is distinct from p_version then
    raise exception
      'RETROACTIVE_CHANGED_RELOAD';
  end if;

  if c.status <> 'REVIEW' then
    raise exception
      'RETROACTIVE_REQUIRES_REVIEW';
  end if;

  if p_note is null
     or char_length(btrim(p_note))
        not between 1 and 2000
  then
    raise exception
      'RETROACTIVE_APPROVAL_NOTE_REQUIRED';
  end if;

  select *
  into source_row
  from public.payroll_periods
  where id = c.source_period_id;

  select *
  into target_row
  from public.payroll_periods
  where id = p_target_period
  for update;

  if not found
     or target_row.branch_id
        is distinct from c.branch_id
     or target_row.starts_on
        <= source_row.starts_on
     or target_row.status
        not in ('DRAFT','GENERATED','REVIEW')
  then
    raise exception
      'RETROACTIVE_INVALID_TARGET_PERIOD';
  end if;

  emergency :=
    p_override_type is not null
    or p_override_reason is not null;

  if emergency then
    if not public.is_global_super_admin()
       or p_override_type
          is distinct from
          'MAKER_CHECKER_EMERGENCY'
       or p_override_reason is null
       or char_length(
            btrim(p_override_reason)
          ) not between 1 and 2000
    then
      raise exception
        'RETROACTIVE_INVALID_OVERRIDE';
    end if;
  end if;

  if c.created_by = auth.uid()
     and not emergency
  then
    raise exception
      'RETROACTIVE_MAKER_CANNOT_APPROVE';
  end if;

  update public.payroll_retroactive_claims
  set
    target_period_id = target_row.id,
    status = 'APPROVED',
    version = version + 1,
    approved_by = auth.uid(),
    approved_at = clock_timestamp(),
    approval_note = btrim(p_note),
    override_type =
      case when emergency
        then p_override_type
      end,
    override_reason =
      case when emergency
        then btrim(p_override_reason)
      end
  where id = c.id;

  return jsonb_build_object(
    'status','APPROVED',
    'claim_id',c.id,
    'target_period_id',target_row.id
  );
end;
$$;


ALTER FUNCTION "public"."approve_payroll_retroactive_claim"("p_claim" "uuid", "p_version" integer, "p_target_period" "uuid", "p_note" "text", "p_override_type" "text", "p_override_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_required_active_lessons"("p_component_id" "uuid", "p_lesson_id" "uuid", "p_status" "text", "p_is_required" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_rule text;
  v_keeps_gate boolean;
begin
  select completion_rule into v_rule
  from public.curriculum_subject_components
  where id = p_component_id;

  if v_rule is distinct from 'ALL_REQUIRED_ITEMS' then
    return;
  end if;

  v_keeps_gate := p_status = 'ACTIVE' and p_is_required;
  if v_keeps_gate then
    return;
  end if;

  if not exists (
    select 1
    from public.curriculum_component_items item
    where item.component_id = p_component_id
      and item.id is distinct from p_lesson_id
      and item.status = 'ACTIVE'
      and item.is_required
  ) then
    raise exception 'Nhóm đánh giá hoàn thành từ Lesson bắt buộc cần ít nhất một Lesson bắt buộc đang hoạt động.'
      using errcode = 'P0001';
  end if;
end;
$$;


ALTER FUNCTION "public"."assert_required_active_lessons"("p_component_id" "uuid", "p_lesson_id" "uuid", "p_status" "text", "p_is_required" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_crm_lead"("p_request" "uuid", "p_lead" "uuid", "p_version" integer, "p_owner" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  row public.crm_leads%rowtype;
  actor uuid := auth.uid();
  reason text := public.crm_text(p_reason, 2000);
  existing public.crm_lead_events%rowtype;
  branch uuid;
  meta jsonb;
begin
  if actor is null or not coalesce(public.account_is_active(), false) then
    raise exception 'CRM_LEAD_UNAUTHORIZED';
  end if;
  if p_request is null or p_owner is null or reason is null
     or not exists(select 1 from public.profiles where id = p_owner and status = 'ACTIVE')
  then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('crm-lead-request:' || p_request::text, 0));
  select * into existing from public.crm_lead_events where id = p_request;
  if found then
    select lead.branch_id into branch from public.crm_leads lead where lead.id = existing.lead_id;
    if branch is null then
      raise exception 'CRM_LEAD_UNAUTHORIZED';
    end if;
    perform public.crm_actor('crm.lead.assign', branch);
    if existing.lead_id is distinct from p_lead
       or existing.event_type is distinct from 'ASSIGNED'
       or existing.actor_id is distinct from actor
       or existing.note is distinct from reason
       or existing.metadata->>'to_owner' is distinct from p_owner::text
    then
      raise exception 'CRM_LEAD_REQUEST_MISMATCH';
    end if;
    return p_lead;
  end if;
  row := public.crm_lead_lock(p_lead, p_version, 'crm.lead.assign');
  meta := jsonb_build_object('from_owner', row.owner_user_id, 'to_owner', p_owner);
  perform set_config('crm.lead_write', 'on', true);
  update public.crm_leads set
    owner_user_id = p_owner, version = version + 1, updated_at = clock_timestamp()
  where id = row.id;
  insert into public.crm_lead_events(id, lead_id, event_type, from_status, to_status, actor_id, note, metadata)
  values (p_request, row.id, 'ASSIGNED', row.status, row.status, actor, reason, meta);
  perform set_config('crm.lead_write', 'off', true);
  return row.id;
end $$;


ALTER FUNCTION "public"."assign_crm_lead"("p_request" "uuid", "p_lead" "uuid", "p_version" integer, "p_owner" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_staff_position"("p_employee" "uuid", "p_code" "text", "p_effective_from" "date", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  result uuid;
begin
  if not coalesce(public.has_role('SUPER_ADMIN'), false) then
    raise exception 'STAFF_PROFILE_UNAUTHORIZED';
  end if;
  if nullif(btrim(p_reason), '') is null then
    raise exception 'STAFF_ASSIGNMENT_REASON_REQUIRED';
  end if;
  if p_code not in ('VAS', 'VAM', 'VAH') then
    raise exception 'STAFF_POSITION_UNKNOWN';
  end if;
  if p_effective_from is null or not isfinite(p_effective_from) then
    raise exception 'STAFF_ASSIGNMENT_DATE_INVALID';
  end if;
  if not exists(select 1 from public.employees where id = p_employee) then
    raise exception 'STAFF_EMPLOYEE_NOT_FOUND';
  end if;
  perform 1 from public.employees where id = p_employee for update;
  if exists (
    select 1 from public.staff_position_assignments a
    where a.employee_id = p_employee
      and a.position_code = p_code
      and a.status = 'ACTIVE'
      and daterange(a.effective_from, coalesce(a.effective_to, 'infinity'::date), '[]')
          && daterange(p_effective_from, 'infinity'::date, '[]')
  ) then
    raise exception 'STAFF_POSITION_OVERLAP';
  end if;
  insert into public.staff_position_assignments(
    employee_id, position_code, effective_from, reason, created_by
  ) values (
    p_employee, p_code, p_effective_from, btrim(p_reason), auth.uid()
  ) returning id into result;
  insert into public.employee_audit(employee_id, action, after_data, reason, actor)
  select p_employee, 'POSITION_ASSIGNED', to_jsonb(a), btrim(p_reason), auth.uid()
  from public.staff_position_assignments a where a.id = result;
  return result;
end;
$$;


ALTER FUNCTION "public"."assign_staff_position"("p_employee" "uuid", "p_code" "text", "p_effective_from" "date", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_staff_teaching"("p_employee" "uuid", "p_subject" "uuid", "p_capacity" "text", "p_effective_from" "date", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  result uuid;
begin
  if not coalesce(public.has_role('SUPER_ADMIN'), false) then
    raise exception 'STAFF_PROFILE_UNAUTHORIZED';
  end if;
  if nullif(btrim(p_reason), '') is null then
    raise exception 'STAFF_ASSIGNMENT_REASON_REQUIRED';
  end if;
  if p_capacity not in ('TEACHER', 'ASSISTANT') then
    raise exception 'STAFF_TEACHING_CAPACITY_UNKNOWN';
  end if;
  if p_effective_from is null or not isfinite(p_effective_from) then
    raise exception 'STAFF_ASSIGNMENT_DATE_INVALID';
  end if;
  if not exists(select 1 from public.employees where id = p_employee) then
    raise exception 'STAFF_EMPLOYEE_NOT_FOUND';
  end if;
  if not exists(select 1 from public.curriculums where id = p_subject and status = 'ACTIVE') then
    raise exception 'STAFF_SUBJECT_NOT_ACTIVE';
  end if;
  perform 1 from public.employees where id = p_employee for update;
  if exists (
    select 1 from public.staff_teaching_assignments a
    where a.employee_id = p_employee
      and a.curriculum_id = p_subject
      and a.capacity = p_capacity
      and a.status = 'ACTIVE'
      and daterange(a.effective_from, coalesce(a.effective_to, 'infinity'::date), '[]')
          && daterange(p_effective_from, 'infinity'::date, '[]')
  ) then
    raise exception 'STAFF_TEACHING_OVERLAP';
  end if;
  insert into public.staff_teaching_assignments(
    employee_id, curriculum_id, capacity, effective_from, reason, created_by
  ) values (
    p_employee, p_subject, p_capacity, p_effective_from, btrim(p_reason), auth.uid()
  ) returning id into result;
  insert into public.employee_audit(employee_id, action, after_data, reason, actor)
  select p_employee, 'TEACHING_ASSIGNED', to_jsonb(a), btrim(p_reason), auth.uid()
  from public.staff_teaching_assignments a where a.id = result;
  return result;
end;
$$;


ALTER FUNCTION "public"."assign_staff_teaching"("p_employee" "uuid", "p_subject" "uuid", "p_capacity" "text", "p_effective_from" "date", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_student_academic_program"("p_student_id" "uuid", "p_curriculum_id" "uuid", "p_level_id" "uuid", "p_started_at" "date", "p_is_primary" boolean DEFAULT true) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_enrollment_id uuid;
  v_level_progress_id uuid;
begin

  if auth.uid() is not null
     and not public.has_role('SUPER_ADMIN')
     and coalesce(current_setting('registration.academic_seed', true), '') is distinct from 'on'
  then
    raise exception
      'Only SUPER_ADMIN can assign an academic program';
  end if;


  if p_student_id is null
     or p_curriculum_id is null
     or p_level_id is null
     or p_started_at is null
  then
    raise exception
      'Student, curriculum, level and start date are required';
  end if;


  -- Serialize assignment / primary changes for this student.
  perform 1
  from public.students
  where id = p_student_id
  for update;

  if not found then
    raise exception 'Student does not exist';
  end if;


  if not exists (
    select 1
    from public.curriculums
    where id = p_curriculum_id
      and status = 'ACTIVE'
  ) then
    raise exception
      'Curriculum does not exist or is inactive';
  end if;


  if not exists (
    select 1
    from public.curriculum_levels
    where id = p_level_id
      and curriculum_id = p_curriculum_id
      and status = 'ACTIVE'
  ) then
    raise exception
      'Level does not belong to this curriculum or is inactive';
  end if;


  if exists (
    select 1
    from public.student_curriculum_enrollments
    where student_id = p_student_id
      and curriculum_id = p_curriculum_id
      and status in ('ACTIVE', 'PAUSED')
  ) then
    raise exception
      'Student already has an active enrollment in this curriculum';
  end if;


  if not exists (
    select 1
    from public.curriculum_subjects
    where level_id = p_level_id
      and status = 'ACTIVE'
  ) then
    raise exception
      'Selected level has no active subjects';
  end if;


  if exists (
    select 1
    from public.curriculum_subjects s
    where s.level_id = p_level_id
      and s.status = 'ACTIVE'
      and s.is_required = true
      and s.completion_rule = 'ALL_REQUIRED_COMPONENTS'
      and not exists (
        select 1
        from public.curriculum_subject_components c
        where c.subject_id = s.id
          and c.is_required = true
          and c.status = 'ACTIVE'
      )
  ) then
    raise exception
      'A required subject has no required active components';
  end if;


  if p_is_primary then
    update public.student_curriculum_enrollments
    set
      is_primary = false,
      updated_at = now()
    where student_id = p_student_id
      and is_primary = true
      and status in ('ACTIVE', 'PAUSED');
  end if;


  insert into public.student_curriculum_enrollments (
    student_id,
    curriculum_id,
    current_level_id,
    is_primary,
    status,
    started_at
  )
  values (
    p_student_id,
    p_curriculum_id,
    p_level_id,
    p_is_primary,
    'ACTIVE',
    p_started_at
  )
  returning id
  into v_enrollment_id;


  insert into public.student_level_progress (
    enrollment_id,
    level_id,
    status,
    unlocked_at,
    started_at
  )
  values (
    v_enrollment_id,
    p_level_id,
    'IN_PROGRESS',
    now(),
    p_started_at::timestamp
      at time zone 'Asia/Ho_Chi_Minh'
  )
  returning id
  into v_level_progress_id;


  with inserted_subjects as (

    insert into public.student_subject_progress (
      level_progress_id,
      subject_id,
      status
    )

    select
      v_level_progress_id,
      s.id,
      'NOT_STARTED'

    from public.curriculum_subjects s

    where s.level_id = p_level_id
      and s.status = 'ACTIVE'

    order by s.sort_order

    returning
      id,
      subject_id
  )

  insert into public.student_component_progress (
    subject_progress_id,
    component_id,
    status
  )

  select
    isp.id,
    c.id,
    'NOT_STARTED'

  from inserted_subjects isp

  join public.curriculum_subject_components c
    on c.subject_id = isp.subject_id
   and c.status = 'ACTIVE'

  order by
    isp.subject_id,
    c.sort_order;


  return v_enrollment_id;

end;
$$;


ALTER FUNCTION "public"."assign_student_academic_program"("p_student_id" "uuid", "p_curriculum_id" "uuid", "p_level_id" "uuid", "p_started_at" "date", "p_is_primary" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assign_student_academic_program"("p_student_id" "uuid", "p_curriculum_id" "uuid", "p_level_id" "uuid", "p_started_at" "date", "p_is_primary" boolean) IS 'Atomically assigns a Vibe Academy student to a curriculum and current level, creating level, subject and component progress.';



CREATE OR REPLACE FUNCTION "public"."assign_student_code"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
begin
  -- Blank values and the old registration UUID shorthand use the shared counter.
  -- Preserve explicit historical/import identifiers during data migration.
  if nullif(btrim(coalesce(new.student_code, '')), '') is null
     or new.student_code ~ '^HV-[0-9a-f]{8}$' then
    new.student_code := 'VIBE-' || lpad(nextval('public.student_code_number_seq')::text, 6, '0');
  end if;
  return new;
end $_$;


ALTER FUNCTION "public"."assign_student_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_student_placement"("p_request" "uuid", "p_placement" "uuid", "p_version" integer, "p_class" "uuid", "p_start" "date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor uuid := auth.uid();
  row public.student_placement_cases%rowtype;
  class_row public.classes%rowtype;
  app public.registration_applications%rowtype;
  occupied integer;
  v_enrollment uuid;
  teacher_id uuid;
  scope_code text;
begin
  if actor is null or p_request is null or p_class is null or p_start is null then raise exception 'PLACEMENT_INVALID'; end if;
  select * into row from public.student_placement_cases where id = p_placement for update;
  if not found or not public.registration_can('student_placement.manage', row.branch_id) then raise exception 'PLACEMENT_UNAUTHORIZED'; end if;
  if exists(select 1 from public.student_placement_events where id = p_request) then
    if exists(select 1 from public.student_placement_events where id = p_request and placement_id = p_placement
      and actor_id = actor and event_type = 'CLASS_ASSIGNED' and metadata->>'class_id' = p_class::text
      and metadata->>'start' = p_start::text) then return p_placement; end if;
    raise exception 'PLACEMENT_REQUEST_REUSED';
  end if;
  if row.version is distinct from p_version then raise exception 'PLACEMENT_STALE'; end if;
  if row.status not in ('UNASSIGNED', 'MATCHING') or row.enrollment_id is not null then raise exception 'PLACEMENT_TRANSITION_DENIED'; end if;
  select * into class_row from public.classes where id = p_class for update;
  if not found or class_row.branch_id <> row.branch_id or class_row.status <> 'ACTIVE' then
    raise exception 'PLACEMENT_CLASS_DENIED';
  end if;
  select * into app from public.registration_applications where id = row.registration_application_id;
  if app.course_id is not null and app.course_id is distinct from class_row.course_id then
    raise exception 'PLACEMENT_PROGRAM_DENIED';
  end if;
  if app.course_id is null and not exists (
    select 1 from public.courses course
    where course.id = class_row.course_id and course.curriculum_id = app.curriculum_id
  ) then
    raise exception 'PLACEMENT_PROGRAM_DENIED';
  end if;
  scope_code := public.class_enrollment_compatibility(class_row.id, row.student_id);
  if scope_code is distinct from 'IN_SCOPE' then raise exception 'PLACEMENT_LEVEL_DENIED'; end if;
  if class_row.start_date is not null and p_start < class_row.start_date then raise exception 'PLACEMENT_START_DENIED'; end if;
  if class_row.end_date is not null and p_start > class_row.end_date then raise exception 'PLACEMENT_START_DENIED'; end if;
  select count(*) into occupied from public.enrollments
  where class_id = class_row.id and status in ('ACTIVE', 'PAUSED');
  if occupied >= class_row.capacity then raise exception 'PLACEMENT_CLASS_FULL'; end if;
  if exists(
    select 1 from public.enrollments
    where student_id = row.student_id and class_id = class_row.id and status in ('ACTIVE', 'PAUSED')
  ) then
    raise exception 'PLACEMENT_ALREADY_ENROLLED';
  end if;
  select (array_agg(ct.teacher_id))[1] into teacher_id
  from public.class_teachers ct
  where ct.class_id = class_row.id and ct.teacher_role = 'PRIMARY'
    and (ct.is_active or ct.ended_at is not null)
    and ct.assigned_at <= p_start and (ct.ended_at is null or ct.ended_at >= p_start)
  having count(*) = 1;
  if teacher_id is null then raise exception 'PLACEMENT_TEACHER_REQUIRED'; end if;
  if not exists(
    select 1 from public.schedules schedule
    where schedule.class_id = class_row.id and schedule.status = 'ACTIVE'
  ) then
    raise exception 'PLACEMENT_SCHEDULE_REQUIRED';
  end if;
  v_enrollment := gen_random_uuid();
  perform set_config('registration.write', 'on', true);
  insert into public.enrollments(id, student_id, class_id, enrolled_at, started_at, status)
  values (v_enrollment, row.student_id, class_row.id, public.registration_vietnam_today(), p_start, 'ACTIVE');
  update public.student_placement_cases set
    status = 'SCHEDULED',
    enrollment_id = v_enrollment,
    assigned_class_id = class_row.id,
    assigned_teacher_id = teacher_id,
    scheduled_start_date = p_start,
    scheduled_at = clock_timestamp(),
    version = version + 1,
    updated_at = clock_timestamp()
  where id = row.id;
  update public.registration_applications set linked_enrollment_id = v_enrollment, updated_at = clock_timestamp()
  where id = row.registration_application_id;
  insert into public.student_placement_events(id, placement_id, event_type, actor_id, metadata)
  values (p_request, row.id, 'CLASS_ASSIGNED', actor, jsonb_build_object('class_id', class_row.id, 'start', p_start, 'enrollment_id', v_enrollment));
  insert into public.registration_application_events(id, application_id, event_type, actor_id, metadata)
  values (gen_random_uuid(), row.registration_application_id, 'ENROLLMENT_CREATED', actor, jsonb_build_object('enrollment_id', v_enrollment));
  perform set_config('registration.write', 'off', true);
  return row.id;
end;
$$;


ALTER FUNCTION "public"."assign_student_placement"("p_request" "uuid", "p_placement" "uuid", "p_version" integer, "p_class" "uuid", "p_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attach_registration_invoice"("p_request" "uuid", "p_application" "uuid", "p_version" integer, "p_invoice" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor uuid := auth.uid();
  row public.registration_applications%rowtype;
  settled boolean;
  next_status text;
begin
  if actor is null or p_request is null or p_invoice is null then raise exception 'REGISTRATION_INVALID'; end if;
  if exists(select 1 from public.registration_application_events where id = p_request) then return p_application; end if;
  row := public.registration_lock(p_application, p_version, 'registration.update');
  if row.status not in ('VERIFIED', 'PAYMENT_PENDING', 'PAID') then raise exception 'REGISTRATION_TRANSITION_DENIED'; end if;
  if not exists(select 1 from public.invoices where id = p_invoice and branch_id_snapshot = row.branch_id) then
    raise exception 'REGISTRATION_PAYMENT_DENIED';
  end if;
  settled := public.registration_invoice_settled(p_invoice);
  next_status := case when settled then 'PAID' else 'PAYMENT_PENDING' end;
  perform set_config('registration.write', 'on', true);
  update public.registration_applications set
    invoice_id = p_invoice,
    status = next_status,
    payment_confirmed_at = case when settled then clock_timestamp() else null end,
    version = version + 1,
    updated_at = clock_timestamp()
  where id = row.id;
  if settled then
    insert into public.registration_application_events(id, application_id, event_type, from_status, to_status, actor_id, metadata)
    values (p_request, row.id, 'PAYMENT_CONFIRMED', row.status, next_status, actor, jsonb_build_object('invoice_id', p_invoice));
  else
    insert into public.registration_application_events(id, application_id, event_type, from_status, to_status, actor_id, metadata)
    values (p_request, row.id, 'VERIFIED', row.status, next_status, actor, jsonb_build_object('invoice_id', p_invoice, 'settled', false));
  end if;
  perform set_config('registration.write', 'off', true);
  return row.id;
end $$;


ALTER FUNCTION "public"."attach_registration_invoice"("p_request" "uuid", "p_application" "uuid", "p_version" integer, "p_invoice" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attendance_retention_signals_v1"("p_branch" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("student_id" "uuid", "enrollment_id" "uuid", "branch_id" "uuid", "class_id" "uuid", "first_signal_on" "date", "last_signal_on" "date", "latest_status" "text", "prior_status" "text", "consecutive_absence_count" integer, "evidence_snapshot" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
with history as (
  select
    e.student_id,
    e.id as enrollment_id,
    c.branch_id,
    c.id as class_id,
    so.id as session_id,
    so.occurrence_date,
    so.starts_at,
    ar.status as attendance_status,
    row_number() over (
      partition by e.id
      order by so.occurrence_date desc, so.starts_at desc, so.id desc
    ) as rn
  from public.attendance_records ar
  join public.enrollments e
    on e.id=ar.enrollment_id
  join public.session_occurrences so
    on so.id=ar.session_occurrence_id
  join public.schedules s
    on s.id=so.schedule_id
  join public.classes c
    on c.id=s.class_id
   and c.id=e.class_id
  where so.status='COMPLETED'
    and so.occurrence_type='REGULAR'
    and (p_branch is null or c.branch_id=p_branch)
),
latest_two as (
  select
    h.student_id,
    h.enrollment_id,
    h.branch_id,
    h.class_id,
    max(h.occurrence_date) filter(where h.rn=1) as latest_on,
    max(h.occurrence_date) filter(where h.rn=2) as prior_on,
    max(h.attendance_status) filter(where h.rn=1) as latest_status,
    max(h.attendance_status) filter(where h.rn=2) as prior_status,
    (max(h.session_id::text) filter(where h.rn=1))::uuid as latest_session_id,
    (max(h.session_id::text) filter(where h.rn=2))::uuid as prior_session_id
  from history h
  where h.rn<=2
  group by
    h.student_id,
    h.enrollment_id,
    h.branch_id,
    h.class_id
)
select
  x.student_id,
  x.enrollment_id,
  x.branch_id,
  x.class_id,
  x.prior_on as first_signal_on,
  x.latest_on as last_signal_on,
  x.latest_status,
  x.prior_status,
  2::integer as consecutive_absence_count,
  jsonb_build_object(
    'rule_code','CONSECUTIVE_ABSENCE_2',
    'absence_statuses',jsonb_build_array('ABSENT','EXCUSED'),
    'latest',
      jsonb_build_object(
        'session_id',x.latest_session_id,
        'occurrence_date',x.latest_on,
        'attendance_status',x.latest_status
      ),
    'prior',
      jsonb_build_object(
        'session_id',x.prior_session_id,
        'occurrence_date',x.prior_on,
        'attendance_status',x.prior_status
      )
  ) as evidence_snapshot
from latest_two x
where x.latest_status in ('ABSENT','EXCUSED')
  and x.prior_status in ('ABSENT','EXCUSED')
  and x.latest_on is not null
  and x.prior_on is not null
$$;


ALTER FUNCTION "public"."attendance_retention_signals_v1"("p_branch" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attendance_roster_read"("p_session" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
 if auth.uid() is null or not coalesce(public.account_is_active(),false)
   or not (public.has_role('SUPER_ADMIN') or public.has_role('BRANCH_ADMIN'))
   or not coalesce(public.can_access_session(p_session),false) then
   raise exception 'ATTENDANCE_UNAUTHORIZED';
 end if;
 return coalesce((select jsonb_agg(jsonb_build_object(
   'enrollment_id',rr.enrollment_id,'student_id',rr.student_id,
   'student_code',st.student_code,'full_name',st.full_name,'preferred_name',st.preferred_name,
   'attendance_id',a.id,'status',a.status,'notes',a.notes
 ) order by st.full_name,rr.enrollment_id)
 from public.session_teaching_roster(p_session) rr
 join public.students st on st.id=rr.student_id
 left join public.attendance_records a on a.session_occurrence_id=p_session and a.enrollment_id=rr.enrollment_id),'[]'::jsonb);
end $$;


ALTER FUNCTION "public"."attendance_roster_read"("p_session" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attendance_session_search"("p_date" "date" DEFAULT (("now"() AT TIME ZONE 'Asia/Ho_Chi_Minh'::"text"))::"date", "p_branch" "uuid" DEFAULT NULL::"uuid", "p_class" "uuid" DEFAULT NULL::"uuid", "p_teacher" "uuid" DEFAULT NULL::"uuid", "p_student" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 with authorized as materialized (
  select v.*, c.name class_name, c.code class_code, b.name branch_name,
   t.full_name teacher_name, r.name room_name
  from public.session_actual_teachers v
  join public.classes c on c.id=v.class_id join public.branches b on b.id=v.branch_id
  left join public.teachers t on t.id=v.teacher_id left join public.rooms r on r.id=v.room_id
  where v.occurrence_date=p_date and v.status<>'CANCELLED'
   and auth.uid() is not null and coalesce(public.account_is_active(),false)
   and public.can_access_session(v.session_id)
 ), counted as (
  select v.*, rr.total, rr.marked, rr.absent, rr.student_names, rr.student_attendance, rr.matched,
   case when rr.total>0 and rr.marked=rr.total then 'COMPLETE'
        when rr.marked>0 then 'IN_PROGRESS' else 'UNMARKED' end attendance_state
  from authorized v
  cross join lateral (
   select count(*) total, count(a.id) marked,
    count(*) filter(where a.status in ('ABSENT','EXCUSED')) absent,
    string_agg(coalesce(st.preferred_name,st.full_name,st.student_code), ', ' order by st.full_name)
      filter(where nullif(btrim(p_student),'') is null or st.id::text=p_student
       or st.full_name ilike '%'||btrim(p_student)||'%' or st.preferred_name ilike '%'||btrim(p_student)||'%'
       or st.student_code ilike '%'||btrim(p_student)||'%') student_names,
    string_agg(coalesce(st.preferred_name,st.full_name,st.student_code)||': '||
      case a.status when 'PRESENT' then 'Có mặt' when 'LATE' then 'Đi muộn'
       when 'ABSENT' then 'Vắng' when 'EXCUSED' then 'Có phép' else 'Chưa điểm danh' end, ', ' order by st.full_name)
      filter(where nullif(btrim(p_student),'') is not null and (st.id::text=p_student
       or st.full_name ilike '%'||btrim(p_student)||'%' or st.preferred_name ilike '%'||btrim(p_student)||'%'
       or st.student_code ilike '%'||btrim(p_student)||'%')) student_attendance,
    bool_or(st.id::text=p_student or st.full_name ilike '%'||btrim(p_student)||'%'
      or st.preferred_name ilike '%'||btrim(p_student)||'%' or st.student_code ilike '%'||btrim(p_student)||'%') matched
   from public.session_teaching_roster(v.session_id) rr join public.students st on st.id=rr.student_id
   left join public.attendance_records a on a.session_occurrence_id=v.session_id and a.enrollment_id=rr.enrollment_id
  ) rr
  where (p_branch is null or v.branch_id=p_branch) and (p_class is null or v.class_id=p_class)
   and (p_teacher is null or v.teacher_id=p_teacher)
 ), filtered as (
  select *, case when total>0 and marked=total then 3
    when starts_at<=now() and ends_at>now() then 0
    when starts_at>now() then 1 when marked<total or total=0 then 2 else 3 end priority
  from counted where (nullif(btrim(p_student),'') is null or matched)
   and (nullif(p_status,'') is null or p_status=attendance_state or (p_status='ABSENT' and absent>0))
 ), page as (
  select * from filtered order by priority,starts_at,session_id limit 25 offset greatest(0,least(coalesce(p_offset,0),100000))
 )
 select jsonb_build_object('rows',coalesce((select jsonb_agg(to_jsonb(page) order by priority,starts_at,session_id) from page),'[]'::jsonb),
  'total',(select count(*) from filtered),
  'branches',coalesce((select jsonb_agg(x order by name) from (select distinct branch_id id,branch_name name from authorized) x),'[]'::jsonb),
  'classes',coalesce((select jsonb_agg(x order by name) from (select distinct class_id id,class_name name from authorized where p_branch is null or branch_id=p_branch) x),'[]'::jsonb),
  'teachers',coalesce((select jsonb_agg(x order by name) from (select distinct teacher_id id,teacher_name name from authorized where teacher_id is not null and (p_branch is null or branch_id=p_branch)) x),'[]'::jsonb))
$$;


ALTER FUNCTION "public"."attendance_session_search"("p_date" "date", "p_branch" "uuid", "p_class" "uuid", "p_teacher" "uuid", "p_student" "text", "p_status" "text", "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."authorize_zalo_registration_outbound"("p_attempt" "uuid", "p_manual" boolean) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare a zalo_notification_attempts; j notification_jobs;
begin
 select * into a from zalo_notification_attempts where id=p_attempt;
 if not found then return 'DENIED'; end if;
 select * into j from notification_jobs where id=a.job_id for update;
 select * into a from zalo_notification_attempts where id=p_attempt for update;
 if p_manual is null or a.state<>'REQUESTING' or j.status<>'PROCESSING' or j.lease_token is distinct from a.id
    or j.attempts<>(a.attempt_number-(case when p_manual then 1 else 0 end)) then return 'DENIED'; end if;
 if not exists(select 1 from public.notification_templates template
   where template.template_key=j.template_key and template.provider='ZALO'
     and template.provider_template_id='640377' and template.status='APPROVED' and template.enabled) then
   perform set_config('zalo.durable_write','on',true);
   update public.zalo_notification_attempts set state='REJECTED',completed_at=clock_timestamp(),error_code='ZALO_GATE_DISABLED' where id=a.id;
   update public.notification_jobs set status='SKIPPED_NO_CHANNEL',error_code='GATE_DISABLED',attempts=a.attempt_number-1,
     lease_token=null,lease_until=null,updated_at=clock_timestamp() where id=j.id;
   insert into public.notification_events(job_id,event,details) values(j.id,'FAILED',jsonb_build_object('source','TEMPLATE_OUTBOUND_GUARD','attempt_id',a.id,'request_sent',false));
   return 'GATE_DISABLED';
 end if;
 if not exists(select 1 from registration_zalo_phone_consents c where c.application_id=j.entity_id and c.revoked_at is null
   and c.id::text=j.payload->'delivery'->>'consent_id' and c.normalized_phone=j.payload->'delivery'->>'normalized_recipient') then
   perform set_config('zalo.durable_write','on',true);
   -- Definitively blocked locally; never invent a provider response or an unknown send.
   update zalo_notification_attempts set state='REJECTED',completed_at=clock_timestamp(),error_code='ZALO_CONSENT_WITHDRAWN' where id=a.id;
   update notification_jobs set status='SKIPPED_NO_CHANNEL',error_code='NO_CONSENT',attempts=a.attempt_number-1,
     lease_token=null,lease_until=null,updated_at=clock_timestamp() where id=j.id;
   insert into notification_events(job_id,event,details) values(j.id,'FAILED',jsonb_build_object('source','CONSENT_OUTBOUND_GUARD','attempt_id',a.id,'request_sent',false));
   return 'NO_CONSENT';
 end if;
 if p_manual then update notification_jobs set attempts=a.attempt_number where id=j.id; end if;
 return 'STARTED';
end $$;


ALTER FUNCTION "public"."authorize_zalo_registration_outbound"("p_attempt" "uuid", "p_manual" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."authorized_legacy_tuition_payload"("p_row" "uuid", "p_enrollment" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare payload jsonb;
begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Unauthorized legacy baseline'; end if;
 select r.normalized_payload into payload from public.migration_batch_rows r join public.enrollments e on e.id=r.target_enrollment_id
 where r.id=p_row and r.status='READY' and r.target_enrollment_id=p_enrollment and r.target_student_id=e.student_id
 and r.identity_reviewed_by is not null and r.academic_reviewed_by is not null and r.finance_reviewed_by is not null;
 if payload is null then raise exception 'Legacy baseline must be inside approved atomic import'; end if;
 return payload;
end $$;


