CREATE OR REPLACE FUNCTION "public"."begin_tuition_zalo_send"("p_reminder" "uuid", "p_parent" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  reminder public.tuition_reminders;
  student uuid;
  tuition uuid;
  tracking text;
  created uuid;
  today date := (clock_timestamp() at time zone 'Asia/Ho_Chi_Minh')::date;
begin
  if not coalesce(public.has_role('SUPER_ADMIN'), false) then
    raise exception 'SUPER_ADMIN role required';
  end if;
  select * into reminder from public.tuition_reminders where id = p_reminder;
  if not found or reminder.status <> 'PENDING' then
    raise exception 'Tuition reminder not found';
  end if;
  if reminder.window_start > today then
    raise exception 'Tuition Zalo window has not started';
  end if;
  select enrollment.student_id, tuition_row.id
    into student, tuition
  from public.enrollment_tuition tuition_row
  join public.enrollments enrollment on enrollment.id = tuition_row.enrollment_id
  join public.branches branch on branch.id = tuition_row.branch_id_snapshot
  where tuition_row.id = reminder.enrollment_tuition_id
    and enrollment.student_id is not null;
  if not found then
    raise exception 'Tuition reminder branch mismatch';
  end if;
  if not exists (
    select 1
    from public.student_parents link
    join public.parents parent on parent.id = link.parent_id and parent.status = 'ACTIVE'
    where link.student_id = student
      and link.parent_id = p_parent
      and link.can_view_finance
      and link.is_active
      and (link.valid_from is null or link.valid_from <= clock_timestamp())
      and (link.valid_until is null or link.valid_until > clock_timestamp())
  ) then
    raise exception 'Tuition recipient not found';
  end if;
  if not exists (
    select 1 from public.tuition_zalo_consents consent
    where consent.student_id = student
      and consent.parent_id = p_parent
      and consent.revoked_at is null
  ) then
    raise exception 'Tuition Zalo consent required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('tuition-zalo-send:' || p_reminder::text, 0));
  if exists (
    select 1 from public.tuition_zalo_sends send
    where send.reminder_id = reminder.id
      and send.send_status in ('PREPARED', 'SENT', 'DELIVERED')
  ) then
    raise exception 'Tuition Zalo already prepared';
  end if;
  tracking := replace(gen_random_uuid()::text, '-', '');
  insert into public.tuition_zalo_sends(
    tracking_id, reminder_id, student_id, parent_id, enrollment_tuition_id, template_key, send_status
  ) values (
    tracking, reminder.id, student, p_parent, tuition, 'ZALO_TUITION_REMINDER', 'PREPARED'
  ) returning id into created;
  return jsonb_build_object(
    'send_id', created,
    'tracking_id', tracking,
    'reminder_id', reminder.id,
    'student_id', student
  );
end $$;


ALTER FUNCTION "public"."begin_tuition_zalo_send"("p_reminder" "uuid", "p_parent" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."block_zalo_registration_job"("p_job" "uuid", "p_error" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
begin
 if p_error is null or p_error !~ '^ZALO_[A-Z_]{1,64}$' then return 'INVALID'; end if;
 update notification_jobs set error_code=p_error,updated_at=clock_timestamp() where id=p_job and status in('QUEUED','RETRYING') and channel='ZALO' and payload->'delivery'->>'channel'='PHONE' and error_code is distinct from p_error;
 if found then insert into notification_events(job_id,event,details) values(p_job,'BLOCKED',jsonb_build_object('error_code',p_error,'request_sent',false)); end if;
 return 'BLOCKED';
end $_$;


ALTER FUNCTION "public"."block_zalo_registration_job"("p_job" "uuid", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."book_makeup_seat"("p_credit_id" "uuid", "p_occurrence_id" "uuid", "p_acceptance_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_credit public.makeup_credits%rowtype;
  v_occurrence public.session_occurrences%rowtype;
  v_enrollment public.enrollments%rowtype;
  v_class_id uuid;
  v_capacity integer;
  v_taken integer;
  v_policy public.academic_operation_policies%rowtype;
  v_code text;
  v_source_class uuid;
begin
  v_actor := public.academic_operation_actor();
  if p_acceptance_note is null or char_length(btrim(p_acceptance_note)) < 8 then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Giáo vụ cần ghi bài học tương đương được chấp nhận, ít nhất 8 ký tự. Hệ thống không tự coi hai bài là tương đương.'));
  end if;
  select * into v_credit from public.makeup_credits where id = p_credit_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Không tìm thấy quyền học bù.'));
  end if;
  if v_credit.status <> 'AVAILABLE' then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Quyền này không còn dùng được. Trạng thái hiện tại: ' || v_credit.status || '.'));
  end if;
  select * into v_policy from public.current_academic_operation_policy();
  if v_policy.makeup_use_within_days is null then
    null;
  else
    if public.vietnam_today() > (
      select occurrence.occurrence_date + v_policy.makeup_use_within_days
      from public.session_occurrences occurrence where occurrence.id = v_credit.source_occurrence_id
    ) then
      return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Quyền đã quá hạn theo chính sách phiên bản ' || v_policy.version_no || '.'));
    end if;
  end if;
  if v_policy.max_open_makeup_credits is not null and (
    select count(*) from public.makeup_credits
    where enrollment_id = v_credit.enrollment_id and status in ('AVAILABLE', 'RESERVED')
  ) > v_policy.max_open_makeup_credits then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Số quyền đang mở vượt mức chính sách đã duyệt.'));
  end if;
  select * into v_occurrence from public.session_occurrences where id = p_occurrence_id for update;
  if not found or v_occurrence.occurrence_type <> 'MAKEUP' or v_occurrence.status <> 'SCHEDULED' then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Buổi đích phải là buổi học bù còn trong lịch.'));
  end if;
  select * into v_enrollment from public.enrollments where id = v_credit.enrollment_id;
  select schedule.class_id into v_class_id
  from public.schedules schedule where schedule.id = v_occurrence.schedule_id;
  select schedule.class_id into v_source_class
  from public.session_occurrences source
  join public.schedules schedule on schedule.id = source.schedule_id
  where source.id = v_credit.source_occurrence_id;
  if v_class_id is distinct from v_source_class then
    v_code := public.class_enrollment_compatibility(v_class_id, v_enrollment.student_id);
    if v_code <> 'IN_SCOPE' then
      return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Buổi bù khác ca gốc và chưa cùng chương trình, trình độ phù hợp: ' || v_code || '.'));
    end if;
  end if;
  if public.is_enrollment_paused_on(v_enrollment.id, v_occurrence.occurrence_date) then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Ngày buổi bù nằm trong thời gian bảo lưu. Không đặt lịch bù trong khoảng này.'));
  end if;
  if exists (
    select 1
    from public.session_occurrences other
    join public.schedules other_schedule on other_schedule.id = other.schedule_id
    join public.enrollments other_enrollment on other_enrollment.student_id = v_enrollment.student_id
    left join public.session_occurrence_participants participant
      on participant.session_occurrence_id = other.id and participant.enrollment_id = other_enrollment.id
    where other.status = 'SCHEDULED'
      and other.id <> v_occurrence.id
      and tstzrange(other.starts_at, other.ends_at, '[)') && tstzrange(v_occurrence.starts_at, v_occurrence.ends_at, '[)')
      and (
        (other.occurrence_type = 'REGULAR' and other_schedule.class_id = other_enrollment.class_id
          and other_enrollment.status = 'ACTIVE'
          and coalesce(other_enrollment.started_at, other_enrollment.enrolled_at) <= other.occurrence_date
          and (other_enrollment.ended_at is null or other_enrollment.ended_at >= other.occurrence_date)
          and not public.is_enrollment_paused_on(other_enrollment.id, other.occurrence_date))
        or participant.id is not null
      )
  ) then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Học viên đã có buổi khác trùng giờ.'));
  end if;
  select capacity into v_capacity from public.classes where id = v_class_id for update;
  select count(*) into v_taken from public.session_occurrence_participants where session_occurrence_id = v_occurrence.id;
  if v_taken >= v_capacity then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Buổi bù đã hết chỗ. Ghế cuối vừa được giữ bởi thao tác khác.'));
  end if;
  insert into public.academic_operation_exceptions (kind, enrollment_id, source_id, actor_id, note, payload)
  values ('MAKEUP_LESSON_ACCEPTED', v_enrollment.id, v_credit.id, v_actor, btrim(p_acceptance_note), jsonb_build_object('occurrence_id', v_occurrence.id));
  insert into public.session_occurrence_participants (session_occurrence_id, enrollment_id, makeup_credit_id)
  values (v_occurrence.id, v_enrollment.id, v_credit.id);
  return jsonb_build_object(
    'ok', true,
    'credit_id', v_credit.id,
    'occurrence_id', v_occurrence.id,
    'expiry', case when v_policy.makeup_use_within_days is null then 'Chưa có hạn dùng được duyệt.' else 'Theo chính sách phiên bản ' || v_policy.version_no end
  );
exception
  when unique_violation or raise_exception then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array(sqlerrm));
end;
$$;


ALTER FUNCTION "public"."book_makeup_seat"("p_credit_id" "uuid", "p_occurrence_id" "uuid", "p_acceptance_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_enrollment_tuition_effective_end"("p_tuition_id" "uuid") RETURNS "date"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_enrollment_id uuid;
  v_starts_on date;
  v_base_ends_on date;

  v_effective_ends_on date;
  v_next_effective_ends_on date;

  v_pause_days integer;
  v_iteration integer := 0;
begin
  if p_tuition_id is null then
    raise exception
      'Tuition term id is required';
  end if;


  select
    tuition.enrollment_id,
    tuition.starts_on,
    tuition.base_ends_on + tuition.legacy_extension_days
  into
    v_enrollment_id,
    v_starts_on,
    v_base_ends_on
  from public.enrollment_tuition as tuition
  where tuition.id = p_tuition_id;


  if not found then
    raise exception
      'Tuition term not found';
  end if;


  v_effective_ends_on :=
    v_base_ends_on;


  loop
    v_iteration :=
      v_iteration + 1;


    if v_iteration > 1000 then
      raise exception
        'Unable to calculate tuition effective end date';
    end if;


    select
      coalesce(
        sum(
          least(
            pause.ends_on,
            v_effective_ends_on
          )
          -
          greatest(
            pause.starts_on,
            v_starts_on
          )
          + 1
        ),
        0
      )::integer
    into v_pause_days
    from public.enrollment_pauses as pause
    where pause.enrollment_id =
        v_enrollment_id
      and pause.status = 'ACTIVE'
      and pause.starts_on <=
        v_effective_ends_on
      and pause.ends_on >=
        v_starts_on;


    v_next_effective_ends_on :=
      v_base_ends_on
      + v_pause_days;


    if v_next_effective_ends_on =
      v_effective_ends_on
    then
      exit;
    end if;


    v_effective_ends_on :=
      v_next_effective_ends_on;
  end loop;


  return v_effective_ends_on;
end;
$$;


ALTER FUNCTION "public"."calculate_enrollment_tuition_effective_end"("p_tuition_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_tuition_base_end"("p_starts_on" "date", "p_duration_months" integer) RETURNS "date"
    LANGUAGE "sql" IMMUTABLE STRICT
    AS $$
  select (
    p_starts_on
    + make_interval(months => p_duration_months)
    - interval '1 day'
  )::date;
$$;


ALTER FUNCTION "public"."calculate_tuition_base_end"("p_starts_on" "date", "p_duration_months" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_tuition_discount_amount"("p_list_price" numeric, "p_discount_type" "text", "p_discount_value" numeric) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_type text;
  v_value numeric;
begin

  if p_list_price is null
     or p_list_price < 0 then
    raise exception
      'Invalid tuition list price';
  end if;


  v_type :=
    upper(
      coalesce(
        nullif(
          btrim(p_discount_type),
          ''
        ),
        'NONE'
      )
    );


  v_value :=
    coalesce(
      p_discount_value,
      0
    );


  if v_value < 0 then
    raise exception
      'Discount value cannot be negative';
  end if;


  if v_type = 'NONE' then
    return 0;
  end if;


  if v_type = 'PERCENT' then

    if v_value > 100 then
      raise exception
        'Percentage discount cannot exceed 100';
    end if;

    return round(
      p_list_price
      * v_value
      / 100,
      2
    );

  end if;


  if v_type = 'FIXED' then

    if v_value > p_list_price then
      raise exception
        'Fixed discount cannot exceed tuition list price';
    end if;

    return round(
      v_value,
      2
    );

  end if;


  raise exception
    'Invalid tuition discount type: %',
    v_type;

end;
$$;


ALTER FUNCTION "public"."calculate_tuition_discount_amount"("p_list_price" numeric, "p_discount_type" "text", "p_discount_value" numeric) OWNER TO "postgres";


