CREATE OR REPLACE FUNCTION "public"."cancel_active_pause"("p_pause_id" "uuid", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_pause public.enrollment_pauses%rowtype;
begin
  v_actor := public.academic_operation_actor();
  if p_note is null or char_length(btrim(p_note)) not between 1 and 500 then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Nhập lý do kết thúc bảo lưu.'));
  end if;
  select * into v_pause from public.enrollment_pauses where id = p_pause_id for update;
  if not found or v_pause.status <> 'ACTIVE' then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Đợt bảo lưu không còn hiệu lực.'));
  end if;
  begin
    update public.enrollment_pauses
    set status = 'CANCELLED', cancelled_at = now(), cancelled_by = v_actor, cancel_reason = btrim(p_note)
    where id = v_pause.id and status = 'ACTIVE';
  exception
    when raise_exception then
      insert into public.academic_operation_exceptions (kind, enrollment_id, source_id, actor_id, note)
      values ('PAUSE_BLOCKED', v_pause.enrollment_id, v_pause.id, v_actor, sqlerrm);
      return jsonb_build_object('ok', false, 'blockers', jsonb_build_array(sqlerrm), 'exception_recorded', true);
  end;
  update public.enrollment_pause_requests
  set status = 'ENDED', ended_by = v_actor, ended_at = now(), end_note = btrim(p_note)
  where pause_id = v_pause.id and status = 'APPROVED';
  insert into public.enrollment_pause_events (request_id, enrollment_id, event_type, actor_id, note)
  select request.id, v_pause.enrollment_id, 'ENDED', v_actor, btrim(p_note)
  from public.enrollment_pause_requests request
  where request.pause_id = v_pause.id
  union all
  select null, v_pause.enrollment_id, 'ENDED', v_actor, btrim(p_note)
  where not exists (select 1 from public.enrollment_pause_requests request where request.pause_id = v_pause.id);
  return jsonb_build_object('ok', true, 'pause_id', v_pause.id);
end;
$$;


ALTER FUNCTION "public"."cancel_active_pause"("p_pause_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_employee_expense_claim"("p_claim" "uuid", "p_version" integer, "p_reason" "text", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare c public.employee_expense_claims; payload jsonb; prior jsonb; before_data jsonb;
begin
  select * into c from public.employee_expense_claims
    where id=p_claim and created_by=auth.uid()
      and vibe_expense_private.owns_employee(employee_id,branch_id) for update;
  if not found then raise exception 'EXPENSE_UNAUTHORIZED'; end if;
  if p_reason is null or char_length(btrim(p_reason)) not between 1 and 2000 then raise exception 'EXPENSE_CANCEL_REASON_REQUIRED'; end if;
  payload:=jsonb_build_object('action','CANCEL','claim_id',p_claim,'version',p_version,'reason',btrim(p_reason));
  prior:=vibe_expense_private.replay(p_key,payload); if prior is not null then return prior; end if;
  if c.version is distinct from p_version then raise exception 'EXPENSE_CHANGED_RELOAD'; end if;
  if c.status not in ('DRAFT','RETURNED') then raise exception 'EXPENSE_CANCEL_REQUIRES_EDITABLE_DRAFT'; end if;
  before_data:=vibe_expense_private.snapshot(p_claim);
  update public.employee_expense_claims set status='CANCELLED',version=version+1,updated_at=clock_timestamp(),review_reason=btrim(p_reason) where id=p_claim;
  update public.employee_expense_claim_lines set reservation_active=false where claim_id=p_claim;
  return vibe_expense_private.record_event(p_claim,p_key,payload,'CANCELLED',before_data);
end;
$$;


ALTER FUNCTION "public"."cancel_employee_expense_claim"("p_claim" "uuid", "p_version" integer, "p_reason" "text", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_financial_action"("p_request_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r public.financial_approval_requests;
begin
 select * into r from public.financial_approval_requests q where q.id=p_request_id and
 ((q.maker_user_id=auth.uid() and public.finance_action_allowed(finance_private.operation_permission(q.operation,'request'),q.branch_id))
 or public.finance_action_allowed(finance_private.operation_permission(q.operation,'approve'),q.branch_id)) for update;
 if not found then raise exception 'Unauthorized'; end if;
 if p_reason is null or char_length(btrim(p_reason)) not between 1 and 2000 then raise exception 'Cancellation reason required'; end if;
 if r.status='CANCELLED' then return; end if;
 if r.status<>'PENDING_APPROVAL' then raise exception 'Only pending requests can be cancelled'; end if;
 update public.financial_approval_requests set status='CANCELLED' where id=r.id;
 insert into public.financial_approval_events(request_id,event,performed_by,reason,before_snapshot,after_snapshot)
 values(r.id,'CANCELLED',auth.uid(),btrim(p_reason),to_jsonb(r),jsonb_build_object('status','CANCELLED'));
end $$;


ALTER FUNCTION "public"."cancel_financial_action"("p_request_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_future_student_placement"("p_request" "uuid", "p_placement" "uuid", "p_version" integer, "p_enrollment" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor uuid := auth.uid();
  row public.student_placement_cases%rowtype;
  enrollment public.enrollments%rowtype;
  reason text;
begin
  if actor is null or p_request is null or p_enrollment is null then raise exception 'PLACEMENT_INVALID'; end if;
  if exists(select 1 from public.student_placement_events where id = p_request) then return p_placement; end if;
  reason := public.placement_reason(p_reason);
  select * into row from public.student_placement_cases where id = p_placement for update;
  if not found or not public.registration_can('student_placement.manage', row.branch_id) then
    raise exception 'PLACEMENT_UNAUTHORIZED';
  end if;
  if row.enrollment_id is distinct from p_enrollment then raise exception 'PLACEMENT_UNAUTHORIZED'; end if;
  if row.version is distinct from p_version then raise exception 'PLACEMENT_STALE'; end if;
  if row.status <> 'SCHEDULED' then raise exception 'PLACEMENT_TRANSITION_DENIED'; end if;
  select * into enrollment from public.enrollments where id = row.enrollment_id for update;
  if not found or enrollment.student_id <> row.student_id or enrollment.status <> 'ACTIVE' then
    raise exception 'PLACEMENT_TRANSITION_DENIED';
  end if;
  if enrollment.started_at is null or enrollment.started_at <= public.registration_vietnam_today() then
    raise exception 'PLACEMENT_ALREADY_STARTED';
  end if;
  if public.placement_learning_history_exists(enrollment.id) then raise exception 'PLACEMENT_HISTORY_LOCKED'; end if;
  perform set_config('registration.write', 'on', true);
  update public.enrollments
  set status = 'WITHDRAWN', ended_at = started_at, updated_at = clock_timestamp()
  where id = enrollment.id;
  update public.student_placement_cases set
    status = 'UNASSIGNED',
    enrollment_id = null,
    assigned_class_id = null,
    assigned_teacher_id = null,
    scheduled_start_date = null,
    scheduled_at = null,
    version = version + 1,
    updated_at = clock_timestamp()
  where id = row.id;
  update public.registration_applications
  set linked_enrollment_id = null, updated_at = clock_timestamp()
  where id = row.registration_application_id;
  insert into public.student_placement_events(id, placement_id, event_type, actor_id, metadata)
  values (
    p_request, row.id, 'PLACEMENT_CANCELLED', actor,
    jsonb_build_object(
      'student_id', row.student_id,
      'enrollment_id', enrollment.id,
      'old_class_id', enrollment.class_id,
      'new_class_id', null,
      'old_start', enrollment.started_at,
      'reason', reason
    )
  );
  perform set_config('registration.write', 'off', true);
  return row.id;
end $$;


ALTER FUNCTION "public"."cancel_future_student_placement"("p_request" "uuid", "p_placement" "uuid", "p_version" integer, "p_enrollment" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_invoice"("p_invoice_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare state text;
begin
 if not public.is_global_super_admin() then raise exception 'SUPER_ADMIN role required'; end if;
 select status into state from public.invoices where id=p_invoice_id for update;
 if state is distinct from 'DRAFT' then raise exception 'Financial approval required'; end if;
 perform finance_private.cancel_invoice(p_invoice_id,p_reason);
end $$;


ALTER FUNCTION "public"."cancel_invoice"("p_invoice_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_makeup_booking"("p_credit_id" "uuid", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_credit public.makeup_credits%rowtype;
  v_starts timestamptz;
  v_status text;
  v_policy public.academic_operation_policies%rowtype;
begin
  v_actor := public.academic_operation_actor();
  if p_note is null or char_length(btrim(p_note)) not between 1 and 500 then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Nhập lý do hủy chỗ.'));
  end if;
  select * into v_credit from public.makeup_credits where id = p_credit_id for update;
  if not found or v_credit.status <> 'RESERVED' or v_credit.reserved_occurrence_id is null then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Chỉ hủy được chỗ của quyền đang ở trạng thái đã đặt.'));
  end if;
  select occurrence.starts_at, occurrence.status into v_starts, v_status
  from public.session_occurrences occurrence where occurrence.id = v_credit.reserved_occurrence_id for update;
  if v_status <> 'SCHEDULED' then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Buổi đích không còn trong lịch nên không hủy chỗ theo đường này.'));
  end if;
  select * into v_policy from public.current_academic_operation_policy();
  if v_policy.late_cancel_hours is not null and v_starts < now() + make_interval(hours => v_policy.late_cancel_hours) then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Đã vào cửa sổ hủy muộn của chính sách phiên bản ' || v_policy.version_no || '. Chưa có quy tắc trừ quyền được duyệt nên hệ thống không tự thu quyền và cũng không hủy chỗ.'));
  end if;
  delete from public.session_occurrence_participants
  where makeup_credit_id = v_credit.id and session_occurrence_id = v_credit.reserved_occurrence_id;
  insert into public.enrollment_pause_events (enrollment_id, event_type, actor_id, note, payload)
  values (v_credit.enrollment_id, 'MAKEUP_UNBOOKED', v_actor, btrim(p_note), jsonb_build_object('credit_id', v_credit.id));
  return jsonb_build_object('ok', true, 'credit_id', v_credit.id, 'status', 'AVAILABLE');
end;
$$;


ALTER FUNCTION "public"."cancel_makeup_booking"("p_credit_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_operating_expense"("p_record" "uuid", "p_version" integer, "p_reason" "text", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare rec public.operating_expense_records; payload jsonb; prior jsonb; before_data jsonb; result jsonb;
begin
  select * into rec from public.operating_expense_records where id=p_record for update;
  if not found then raise exception 'OPERATING_EXPENSE_RECORD_NOT_FOUND'; end if;
  if not vibe_operating_expense_private.can_manage(rec.branch_id) then raise exception 'OPERATING_EXPENSE_UNAUTHORIZED'; end if;
  if p_reason is null or char_length(btrim(p_reason)) not between 1 and 2000 then raise exception 'OPERATING_EXPENSE_CANCEL_REASON_REQUIRED'; end if;
  payload:=jsonb_build_object('operation','CANCELLED','record_id',p_record,'version',p_version,'reason',btrim(p_reason));
  prior:=vibe_operating_expense_private.replay(p_key,payload);
  if prior is not null then return prior; end if;
  if rec.status='CANCELLED' then raise exception 'OPERATING_EXPENSE_ALREADY_CANCELLED'; end if;
  if p_version is distinct from rec.version then raise exception 'OPERATING_EXPENSE_CHANGED_RELOAD'; end if;
  before_data:=vibe_operating_expense_private.record_view(p_record);
  update public.operating_expense_records set
    status='CANCELLED',cancelled_by=auth.uid(),cancelled_at=clock_timestamp(),cancel_reason=btrim(p_reason),
    version=version+1,updated_at=clock_timestamp()
  where id=p_record;
  result:=vibe_operating_expense_private.record_view(p_record)||jsonb_build_object('record_id',p_record,'status','CANCELLED');
  return vibe_operating_expense_private.write_event(rec.template_id,p_record,'CANCELLED',p_key,payload,before_data,result,result);
end;
$$;


ALTER FUNCTION "public"."cancel_operating_expense"("p_record" "uuid", "p_version" integer, "p_reason" "text", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_payroll_disbursement"("p_payment" "uuid", "p_reason" "text", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  target public.payroll_disbursements; pay public.teacher_payrolls; period public.payroll_periods; locked record;
  payroll_uuid uuid; payable numeric; paid numeric; remaining numeric; payload jsonb; prior public.payroll_disbursements; result jsonb;
begin
  if auth.uid() is null or not coalesce(public.account_is_active(),false) then raise exception 'PAYROLL_DISBURSEMENT_UNAUTHORIZED'; end if;
  if p_key is null then raise exception 'PAYROLL_DISBURSEMENT_REQUEST_KEY_REQUIRED'; end if;
  if p_reason is null or char_length(btrim(p_reason)) not between 1 and 2000 then raise exception 'PAYROLL_DISBURSEMENT_CANCEL_REASON_REQUIRED'; end if;
  payload:=jsonb_build_object('operation','CANCEL','payment_id',p_payment,'reason',btrim(p_reason));
  perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||':'||p_key::text,0));
  select * into prior from public.payroll_disbursements where cancelled_by=auth.uid() and cancel_request_key=p_key;
  if found then
    if prior.cancel_request_payload<>payload then raise exception 'PAYROLL_DISBURSEMENT_REQUEST_KEY_REUSED'; end if;
    return prior.cancel_request_result;
  end if;
  select payroll_id into payroll_uuid from public.payroll_disbursements where id=p_payment;
  if payroll_uuid is null then raise exception 'PAYROLL_DISBURSEMENT_PAYMENT_NOT_FOUND'; end if;
  select payrow pay,periodrow period into locked
  from public.teacher_payrolls payrow join public.payroll_periods periodrow on periodrow.id=payrow.period_id
  where payrow.id=payroll_uuid for update of payrow,periodrow;
  pay:=locked.pay; period:=locked.period;
  select * into target from public.payroll_disbursements where id=p_payment for update;
  if target.status<>'ACTIVE' then raise exception 'PAYROLL_DISBURSEMENT_ALREADY_CANCELLED'; end if;
  if not (public.is_global_super_admin() or public.has_role_permission('FINANCE','payroll.disburse',target.branch_id)) then raise exception 'PAYROLL_DISBURSEMENT_UNAUTHORIZED'; end if;
  payable:=payroll_disbursement_private.payable_amount(pay);
  select coalesce(sum(amount),0) into paid from public.payroll_disbursements where payroll_id=pay.id and status='ACTIVE' and id<>target.id;
  remaining:=payable-paid;
  result:=jsonb_build_object('payroll_id',pay.id,'payment_id',target.id,'cancelled_amount',target.amount,
    'paid_amount',paid,'remaining_amount',remaining,'payment_status',case when paid=0 then 'NOT_PAID' when paid<payable then 'PARTIALLY_PAID' else 'PAID' end);
  update public.payroll_disbursements set status='CANCELLED',cancelled_by=auth.uid(),cancelled_at=clock_timestamp(),
    cancel_reason=btrim(p_reason),cancel_request_key=p_key,cancel_request_payload=payload,cancel_request_result=result
  where id=target.id;
  return result;
end;
$$;


ALTER FUNCTION "public"."cancel_payroll_disbursement"("p_payment" "uuid", "p_reason" "text", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_payroll_retroactive_claim"("p_claim" "uuid", "p_version" integer, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  c public.payroll_retroactive_claims%rowtype;
begin
  select r.*
  into c
  from public.payroll_retroactive_claims r
  where r.id = p_claim
    and public.has_permission(
      'payroll.prepare',
      r.branch_id
    )
    and (
      public.is_global_super_admin()
      or public.has_role_permission(
        'FINANCE',
        'payroll.prepare',
        r.branch_id
      )
    )
  for update;

  if not found then
    raise exception 'RETROACTIVE_UNAUTHORIZED';
  end if;

  if c.version is distinct from p_version then
    raise exception
      'RETROACTIVE_CHANGED_RELOAD';
  end if;

  if c.status not in (
    'DRAFT','REVIEW','APPROVED'
  ) then
    raise exception
      'RETROACTIVE_CANNOT_CANCEL';
  end if;

  if p_reason is null
     or char_length(btrim(p_reason))
        not between 1 and 2000
  then
    raise exception
      'RETROACTIVE_CANCEL_REASON_REQUIRED';
  end if;

  update public.payroll_retroactive_claims
  set
    status = 'CANCELLED',
    version = version + 1,
    cancelled_by = auth.uid(),
    cancelled_at = clock_timestamp(),
    cancel_reason = btrim(p_reason)
  where id = c.id;

  return jsonb_build_object(
    'status','CANCELLED',
    'claim_id',c.id
  );
end;
$$;


ALTER FUNCTION "public"."cancel_payroll_retroactive_claim"("p_claim" "uuid", "p_version" integer, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_payroll_v2_period_action"("p_action" "uuid", "p_version" integer, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  action_row public.payroll_period_actions_v2%rowtype;
  period_row public.payroll_periods%rowtype;
  before_state jsonb;
  after_state jsonb;
begin
  if auth.uid() is null
     or not coalesce(public.account_is_active(),false)
  then
    raise exception 'PAYROLL_V2_ACTION_UNAUTHORIZED';
  end if;

  select a.*
    into action_row
  from public.payroll_period_actions_v2 a
  where a.id=p_action
  for update;

  if not found then
    raise exception 'PAYROLL_V2_ACTION_UNAVAILABLE';
  end if;

  select p.*
    into period_row
  from public.payroll_periods p
  where p.id=action_row.period_id
    and public.has_permission('payroll.prepare',p.branch_id)
    and (
      public.is_global_super_admin()
      or public.has_role_permission(
        'FINANCE',
        'payroll.prepare',
        p.branch_id
      )
    )
  for update;

  if not found then
    raise exception 'PAYROLL_V2_ACTION_UNAUTHORIZED';
  end if;

  if action_row.status='CANCELLED' then
    return jsonb_build_object(
      'status','ALREADY_CANCELLED',
      'action_id',action_row.id,
      'period_id',action_row.period_id,
      'employee_id',action_row.employee_id
    );
  end if;

  if period_row.version is distinct from p_version then
    raise exception 'PAYROLL_V2_PERIOD_CHANGED_RELOAD';
  end if;

  if period_row.status not in ('GENERATED','REVIEW') then
    raise exception 'PAYROLL_V2_ACTION_CANCEL_REQUIRES_GENERATED_OR_REVIEW';
  end if;

  if p_reason is null
     or char_length(btrim(p_reason)) not between 1 and 2000
  then
    raise exception 'PAYROLL_V2_ACTION_REASON_REQUIRED';
  end if;

  before_state:=public.payroll_approval_snapshot(period_row.id);

  update public.payroll_period_actions_v2
  set
    status='CANCELLED',
    cancelled_by=auth.uid(),
    cancelled_at=clock_timestamp(),
    cancel_reason=btrim(p_reason)
  where id=action_row.id;

  perform public.refresh_staff_payroll_v2_totals(
    period_row.id,
    action_row.employee_id
  );

  update public.payroll_periods
  set version=version+1
  where id=period_row.id;

  after_state:=public.payroll_approval_snapshot(period_row.id);

  insert into public.payroll_events(
    period_id,
    status,
    note,
    actor_id,
    event_type,
    before_snapshot,
    after_snapshot
  )
  values(
    period_row.id,
    period_row.status,
    btrim(p_reason),
    auth.uid(),
    'V2_PERIOD_ACTION_CANCELLED',
    before_state,
    after_state
  );

  return jsonb_build_object(
    'status','CANCELLED',
    'action_id',action_row.id,
    'period_id',action_row.period_id,
    'employee_id',action_row.employee_id
  );
end;
$$;


ALTER FUNCTION "public"."cancel_payroll_v2_period_action"("p_action" "uuid", "p_version" integer, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_payroll_v2_period_action"("p_action" "uuid", "p_version" integer, "p_reason" "text") IS 'Cancels an active Payroll V2 period action before approval. History remains and payroll totals are recalculated.';



CREATE OR REPLACE FUNCTION "public"."cancel_registration_payos_order"("p_application" "uuid", "p_order_code" bigint) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare app public.registration_applications%rowtype;
  ord public.registration_payos_orders%rowtype;
begin
  select * into app from public.registration_applications where id = p_application;
  if not public.registration_can('registration.update', app.branch_id) then
    raise exception 'PAYOS_ORDER_DENIED';
  end if;
  select * into ord from public.registration_payos_orders
    where application_id = p_application and order_code = p_order_code for update;
  if not found then raise exception 'PAYOS_ORDER_UNKNOWN'; end if;
  if ord.state = 'CANCELLED' then return 'ALREADY_CANCELLED'; end if;
  if ord.state <> 'PENDING' and ord.state <> 'RESERVED' then raise exception 'PAYOS_ORDER_STATE_CONFLICT'; end if;
  update public.registration_payos_orders
  set state = 'CANCELLED', cancelled_at = clock_timestamp() where id = ord.id;
  return 'CANCELLED';
end $$;


ALTER FUNCTION "public"."cancel_registration_payos_order"("p_application" "uuid", "p_order_code" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_session_teacher"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
 if new.status='COMPLETED' then
 insert into session_teacher_snapshots(session_id,teacher_id,assignment_type,assignment_id)
 select v.session_id,v.teacher_id,v.assignment_type,a.id from session_actual_teachers v
 left join session_teacher_assignments a on a.session_id=v.session_id and a.effective_status='ACTIVE'
 where v.session_id=new.id on conflict(session_id) do nothing;
 end if;
 return new;
end $$;


ALTER FUNCTION "public"."capture_session_teacher"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cashier_may_enter"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(public.account_is_active(), false)
    and exists (
      select 1
      from public.user_roles assignment
      join public.roles role on role.id = assignment.role_id
      join public.role_permissions grant_row on grant_row.role_id = role.id
      join public.permissions permission on permission.id = grant_row.permission_id
      where assignment.user_id = auth.uid()
        and assignment.is_active
        and assignment.branch_id is not null
        and (assignment.valid_from is null or assignment.valid_from <= now())
        and (assignment.valid_until is null or assignment.valid_until > now())
        and permission.code in ('finance.cash.record', 'finance.payment.record')
    )
$$;


ALTER FUNCTION "public"."cashier_may_enter"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."change_future_student_placement"("p_request" "uuid", "p_placement" "uuid", "p_version" integer, "p_enrollment" "uuid", "p_class" "uuid", "p_start" "date", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor uuid := auth.uid();
  row public.student_placement_cases%rowtype;
  enrollment public.enrollments%rowtype;
  class_row public.classes%rowtype;
  occupied integer;
  teacher_id uuid;
  program_id uuid;
  reason text;
begin
  if actor is null or p_request is null or p_enrollment is null or p_class is null or p_start is null then
    raise exception 'PLACEMENT_INVALID';
  end if;
  reason := public.placement_reason(p_reason);
  select * into row from public.student_placement_cases where id = p_placement for update;
  if not found or not public.registration_can('student_placement.manage', row.branch_id) then
    raise exception 'PLACEMENT_UNAUTHORIZED';
  end if;
  if row.enrollment_id is distinct from p_enrollment then raise exception 'PLACEMENT_UNAUTHORIZED'; end if;
  if exists(select 1 from public.student_placement_events where id = p_request) then
    if exists(select 1 from public.student_placement_events where id = p_request and placement_id=p_placement
      and actor_id=actor and event_type='PLACEMENT_CHANGED' and metadata->>'new_class_id'=p_class::text
      and metadata->>'new_start'=p_start::text) then return p_placement; end if;
    raise exception 'PLACEMENT_REQUEST_REUSED';
  end if;
  if row.version is distinct from p_version then raise exception 'PLACEMENT_STALE'; end if;
  if row.status <> 'SCHEDULED' then raise exception 'PLACEMENT_TRANSITION_DENIED'; end if;
  select * into enrollment from public.enrollments where id = row.enrollment_id for update;
  if not found or enrollment.student_id <> row.student_id or enrollment.status <> 'ACTIVE' then
    raise exception 'PLACEMENT_TRANSITION_DENIED';
  end if;
  if enrollment.started_at is null or enrollment.started_at <= public.registration_vietnam_today() then
    raise exception 'PLACEMENT_ALREADY_STARTED';
  end if;
  if public.placement_learning_history_exists(enrollment.id) then raise exception 'PLACEMENT_HISTORY_LOCKED'; end if;
  select * into class_row from public.classes where id = p_class for update;
  if not found or class_row.branch_id <> row.branch_id or class_row.status <> 'ACTIVE' then
    raise exception 'PLACEMENT_CLASS_DENIED';
  end if;
  select app.course_id into program_id from public.registration_applications app where app.id = row.registration_application_id;
  if program_id is not null and program_id is distinct from class_row.course_id then
    raise exception 'PLACEMENT_PROGRAM_DENIED';
  end if;
  if p_start <= public.registration_vietnam_today() then raise exception 'PLACEMENT_START_DENIED'; end if;
  if class_row.start_date is not null and p_start < class_row.start_date then raise exception 'PLACEMENT_START_DENIED'; end if;
  if class_row.end_date is not null and p_start > class_row.end_date then raise exception 'PLACEMENT_START_DENIED'; end if;
  if class_row.id = enrollment.class_id and p_start = enrollment.started_at then raise exception 'PLACEMENT_UNCHANGED'; end if;
  select count(*) into occupied from public.enrollments
  where class_id = class_row.id and status in ('ACTIVE', 'PAUSED') and id <> enrollment.id;
  if occupied >= class_row.capacity then raise exception 'PLACEMENT_CLASS_FULL'; end if;
  if exists(
    select 1 from public.enrollments
    where student_id = row.student_id and class_id = class_row.id and status in ('ACTIVE', 'PAUSED') and id <> enrollment.id
  ) then
    raise exception 'PLACEMENT_ALREADY_ENROLLED';
  end if;
  select (array_agg(ct.teacher_id))[1] into teacher_id
  from public.class_teachers ct
  where ct.class_id = class_row.id and ct.teacher_role = 'PRIMARY'
    and (ct.is_active or ct.ended_at is not null)
    and ct.assigned_at <= p_start and (ct.ended_at is null or ct.ended_at >= p_start)
  having count(*)=1;
  if teacher_id is null then raise exception 'PLACEMENT_TEACHER_REQUIRED'; end if;
  perform set_config('registration.write', 'on', true);
  update public.enrollments
  set class_id = class_row.id, started_at = p_start, updated_at = clock_timestamp()
  where id = enrollment.id;
  update public.student_placement_cases set
    assigned_class_id = class_row.id,
    assigned_teacher_id = teacher_id,
    scheduled_start_date = p_start,
    version = version + 1,
    updated_at = clock_timestamp()
  where id = row.id;
  insert into public.student_placement_events(id, placement_id, event_type, actor_id, metadata)
  values (
    p_request, row.id, 'PLACEMENT_CHANGED', actor,
    jsonb_build_object(
      'student_id', row.student_id,
      'enrollment_id', enrollment.id,
      'old_class_id', enrollment.class_id,
      'new_class_id', class_row.id,
      'old_start', enrollment.started_at,
      'new_start', p_start,
      'reason', reason
    )
  );
  perform set_config('registration.write', 'off', true);
  return row.id;
end $$;


ALTER FUNCTION "public"."change_future_student_placement"("p_request" "uuid", "p_placement" "uuid", "p_version" integer, "p_enrollment" "uuid", "p_class" "uuid", "p_start" "date", "p_reason" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."notification_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "recipient_id" "uuid",
    "student_id" "uuid",
    "branch_id" "uuid",
    "channel" "text" NOT NULL,
    "delivery_mode" "text" DEFAULT 'LIVE'::"text" NOT NULL,
    "template_key" "text" NOT NULL,
    "payload" "jsonb" NOT NULL,
    "entity_type" "text" NOT NULL,
    "entity_id" "uuid" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "status" "text" DEFAULT 'PENDING'::"text" NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "lease_token" "uuid",
    "lease_until" timestamp with time zone,
    "provider_receipt" "text",
    "error_code" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sent_at" timestamp with time zone,
    "channel_link_id" "uuid",
    "recipient_subject_type" "text",
    "recipient_subject_id" "uuid",
    "next_attempt_at" timestamp with time zone,
    "delivered_at" timestamp with time zone,
    "provider_message_id" "text",
    CONSTRAINT "notification_jobs_channel_check" CHECK (("channel" = ANY (ARRAY['EMAIL'::"text", 'ZALO'::"text", 'IN_APP'::"text"]))),
    CONSTRAINT "notification_jobs_check" CHECK ((("status" = ANY (ARRAY['SENT'::"text", 'DELIVERED'::"text"])) = ("sent_at" IS NOT NULL))),
    CONSTRAINT "notification_jobs_check1" CHECK ((("status" <> 'SENT'::"text") OR (NULLIF("provider_receipt", ''::"text") IS NOT NULL))),
    CONSTRAINT "notification_jobs_delivered_check" CHECK ((("status" <> 'DELIVERED'::"text") OR (("delivered_at" IS NOT NULL) AND ("sent_at" IS NOT NULL)))),
    CONSTRAINT "notification_jobs_delivery_mode_check" CHECK (("delivery_mode" = ANY (ARRAY['LIVE'::"text", 'MOCK'::"text"]))),
    CONSTRAINT "notification_jobs_provider_message_check" CHECK ((("provider_message_id" IS NULL) OR ("provider_message_id" ~ '^[A-Za-z0-9_-]{1,80}$'::"text"))),
    CONSTRAINT "notification_jobs_recipient_check" CHECK ((("recipient_id" IS NOT NULL) OR ("channel" = 'ZALO'::"text"))),
    CONSTRAINT "notification_jobs_retry_check" CHECK ((("status" <> 'RETRYING'::"text") OR ("next_attempt_at" IS NOT NULL))),
    CONSTRAINT "notification_jobs_status_check" CHECK (("status" = ANY (ARRAY['PENDING'::"text", 'PROCESSING'::"text", 'SENT'::"text", 'FAILED'::"text", 'CANCELLED'::"text", 'QUEUED'::"text", 'DELIVERED'::"text", 'RETRYING'::"text", 'SKIPPED_NO_CHANNEL'::"text", 'ACCEPTANCE_UNKNOWN'::"text"]))),
    CONSTRAINT "notification_jobs_subject_check" CHECK (((("recipient_subject_type" IS NULL) AND ("recipient_subject_id" IS NULL)) OR (("recipient_subject_type" = ANY (ARRAY['PROFILE'::"text", 'REGISTRATION'::"text", 'PARENT'::"text", 'STUDENT'::"text"])) AND ("recipient_subject_id" IS NOT NULL))))
);


ALTER TABLE "public"."notification_jobs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_notification"("p_job" "uuid") RETURNS SETOF "public"."notification_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  job public.notification_jobs;
begin
  select * into job from public.notification_jobs where id = p_job and status = 'PENDING' for update skip locked;
  if not found then
    return;
  end if;
  if job.channel = 'ZALO' and job.entity_type = 'TUITION_PAYMENT_RECEIVED' then
    if not exists (
      select 1 from public.payments payment
      where payment.id = job.entity_id and payment.status = 'POSTED'
    ) then
      update public.notification_jobs
      set status = 'CANCELLED', error_code = 'RECIPIENT_INELIGIBLE', updated_at = now()
      where id = job.id;
      insert into public.notification_events(job_id, event) values (job.id, 'RECIPIENT_INELIGIBLE');
      return;
    end if;
    if job.channel_link_id is null or not exists (
      select 1 from public.customer_channel_links channel
      where channel.id = job.channel_link_id
        and channel.provider = 'ZALO'
        and channel.status = 'ACTIVE'
        and channel.provider_user_id is not null
    ) then
      update public.notification_jobs
      set status = 'SKIPPED_NO_CHANNEL', error_code = 'ZALO_RECIPIENT_NOT_LINKED', updated_at = now()
      where id = job.id;
      insert into public.notification_events(job_id, event, details)
      values (job.id, 'SKIPPED_NO_CHANNEL', jsonb_build_object('error_code', 'ZALO_RECIPIENT_NOT_LINKED'));
      return;
    end if;
  elsif job.recipient_id is null
    or not notification_private.recipient_allowed(job.recipient_id, job.student_id, job.branch_id, job.template_key) then
    update public.notification_jobs
    set status = 'CANCELLED', error_code = 'RECIPIENT_INELIGIBLE', updated_at = now()
    where id = job.id;
    insert into public.notification_events(job_id, event) values (job.id, 'RECIPIENT_INELIGIBLE');
    return;
  end if;
  return query
    update public.notification_jobs
    set status = 'PROCESSING',
        attempts = attempts + 1,
        lease_token = gen_random_uuid(),
        lease_until = now() + interval '5 minutes',
        updated_at = now()
    where id = job.id
    returning *;
  insert into public.notification_events(job_id, event) values (job.id, 'CLAIMED');
end $$;


ALTER FUNCTION "public"."claim_notification"("p_job" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_zalo_phone_send"("p_job" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  job public.notification_jobs;
begin
  select * into job from public.notification_jobs where id = p_job for update;
  if not found or job.payload->'delivery'->>'channel' is distinct from 'PHONE' then
    return 'NOT_CLAIMED';
  end if;
  if job.status = 'ACCEPTANCE_UNKNOWN' then
    return 'AMBIGUOUS';
  end if;
  if job.status in ('SENT', 'DELIVERED') then
    return 'ALREADY_ACCEPTED';
  end if;
  if job.status not in ('QUEUED', 'RETRYING') then
    return 'NOT_CLAIMED';
  end if;
  update public.notification_jobs
  set status = 'PROCESSING', attempts = job.attempts + 1, lease_token = gen_random_uuid(),
    lease_until = clock_timestamp() + interval '2 minutes', updated_at = clock_timestamp()
  where id = job.id and status in ('QUEUED', 'RETRYING');
  if not found then
    return 'NOT_CLAIMED';
  end if;
  return 'CLAIMED';
end $$;


ALTER FUNCTION "public"."claim_zalo_phone_send"("p_job" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_zalo_registration_attempt"("p_order_code" bigint, "p_version" bigint, "p_app" "text", "p_oa" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare j notification_jobs; decision record; attempt uuid:=gen_random_uuid(); expected jsonb; src record; c notification_private.zalo_credentials;
begin
 select * into decision from preview_zalo_dispatch_decision(p_order_code);
 if decision.decision is distinct from 'SEND' then return jsonb_build_object('state',coalesce(decision.decision,'NOT_CLAIMED')); end if;
 select * into j from notification_jobs where id=decision.job_id for update;
 -- Locks hold current eligibility steady until the claim commits.
 perform 1 from registration_applications where id=j.entity_id for share;
 perform 1 from registration_deposit_terms where application_id=j.entity_id for share;
 perform 1 from registration_payos_orders where application_id=j.entity_id for share;
 perform 1 from registration_zalo_phone_consents where application_id=j.entity_id and revoked_at is null for share;
 perform 1 from notification_templates where template_key=j.template_key for share;
 select * into decision from preview_zalo_dispatch_decision(p_order_code);
 if decision.decision is distinct from 'SEND' or j.attempts>=5 then return jsonb_build_object('state','NOT_CLAIMED'); end if;
 if j.provider_message_id is not null or j.sent_at is not null or exists(select 1 from zalo_notification_attempts where job_id=j.id and state in ('REQUESTING','UNKNOWN','ACCEPTED')) then return jsonb_build_object('state','AMBIGUOUS'); end if;
 if j.payload->'delivery'->>'template_id' is distinct from '640377' or not exists(select 1 from notification_templates where template_key=j.template_key and provider='ZALO' and status='APPROVED' and provider_template_id='640377' and enabled) then return jsonb_build_object('state','PAYLOAD_REJECTED'); end if;
 select * into src from notification_private.domain_notice_source('REGISTRATION_COMPLETED',j.entity_id);
 expected:=src.parameters||jsonb_build_object('payment_status',notification_private.registration_phone_payment_status(j.entity_id));
 if expected is null or expected is distinct from j.payload->'parameters' then return jsonb_build_object('state','PAYLOAD_REJECTED'); end if;
 if not exists(select 1 from registration_zalo_phone_consents where id::text=j.payload->'delivery'->>'consent_id' and application_id=j.entity_id and revoked_at is null and normalized_phone=decision.provider_user_id) then return jsonb_build_object('state','NO_CONSENT'); end if;
 select * into c from notification_private.zalo_credentials where app_id=p_app and oa_id=p_oa for share;
 if c.version is distinct from p_version or c.state is distinct from 'READY' or c.refresh_token is null or c.expires_at is null or c.expires_at<=clock_timestamp()+interval '30 seconds' then return jsonb_build_object('state','ZALO_CREDENTIAL_CHANGED'); end if;
 perform set_config('zalo.durable_write','on',true);
 insert into zalo_notification_attempts(id,job_id,attempt_number,credential_version,state) values(attempt,j.id,j.attempts+1,p_version,'REQUESTING');
 update notification_jobs set status='PROCESSING',attempts=attempts+1,lease_token=attempt,lease_until=clock_timestamp()+interval '2 minutes',error_code=null,updated_at=clock_timestamp() where id=j.id;
 insert into notification_events(job_id,event,details) values(j.id,'CLAIMED',jsonb_build_object('attempt_id',attempt,'credential_version',p_version));
 return jsonb_build_object('state','CLAIMED','attemptId',attempt,'jobId',j.id,'phone',decision.provider_user_id,'parameters',decision.parameters);
end $$;


ALTER FUNCTION "public"."claim_zalo_registration_attempt"("p_order_code" bigint, "p_version" bigint, "p_app" "text", "p_oa" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_zalo_registration_recovery"("p_job" "uuid", "p_expected" integer, "p_order_code" bigint, "p_version" bigint, "p_app" "text", "p_oa" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare j notification_jobs; d record; claimed jsonb;
begin
 select * into j from notification_jobs where id=p_job for update;
 if j.id is null or p_expected is null or j.attempts<>p_expected then return jsonb_build_object('state','STALE_ACTION'); end if;
 select * into d from preview_zalo_dispatch_decision(p_order_code);
 if d.job_id is distinct from j.id then return jsonb_build_object('state','NOT_SENDABLE'); end if;
 claimed:=claim_zalo_registration_attempt(p_order_code,p_version,p_app,p_oa);
 if claimed->>'state'='CLAIMED' then
   -- Reserve first; the outbound boundary, not eligibility checks, counts a send.
   update notification_jobs set attempts=j.attempts where id=j.id;
 end if;
 return claimed;
end $$;


ALTER FUNCTION "public"."claim_zalo_registration_recovery"("p_job" "uuid", "p_expected" integer, "p_order_code" bigint, "p_version" bigint, "p_app" "text", "p_oa" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."class_enrollment_compatibility"("p_class" "uuid", "p_student" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_from uuid;
  v_to uuid;
  v_course uuid;
  v_curriculum uuid;
  v_prog record;
  v_from_seq integer;
  v_to_seq integer;
begin
  select class_row.accepted_from_level_id, class_row.accepted_to_level_id, class_row.course_id, course.curriculum_id
  into v_from, v_to, v_course, v_curriculum
  from public.classes class_row
  join public.courses course on course.id = class_row.course_id
  where class_row.id = p_class;

  if not found then
    raise exception 'Class not found' using errcode = 'P0001';
  end if;

  if v_from is null or v_to is null then
    return 'CLASS_SCOPE_UNCONFIGURED';
  end if;

  select * into v_prog
  from public.class_student_current_level(p_class, p_student);

  if not found then
    -- Distinguish wrong curriculum vs missing program: any active SCE for student?
    if exists (
      select 1 from public.student_curriculum_enrollments sce
      where sce.student_id = p_student and sce.status = 'ACTIVE'
    ) then
      return 'WRONG_PROGRAM';
    end if;
    return 'ACADEMIC_PROGRAM_MISSING';
  end if;

  if v_prog.current_level_id is null then
    return 'CURRENT_LEVEL_MISSING';
  end if;

  if v_prog.curriculum_id is distinct from v_curriculum then
    return 'WRONG_PROGRAM';
  end if;

  select sequence_no into v_from_seq from public.curriculum_levels where id = v_from;
  select sequence_no into v_to_seq from public.curriculum_levels where id = v_to;

  if v_prog.sequence_no is null then
    return 'CURRENT_LEVEL_MISSING';
  end if;

  if v_prog.sequence_no < v_from_seq or v_prog.sequence_no > v_to_seq then
    return 'OUTSIDE_SCOPE';
  end if;

  return 'IN_SCOPE';
end;
$$;


ALTER FUNCTION "public"."class_enrollment_compatibility"("p_class" "uuid", "p_student" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."class_student_current_level"("p_class" "uuid", "p_student" "uuid") RETURNS TABLE("student_curriculum_enrollment_id" "uuid", "current_level_id" "uuid", "level_name" "text", "sequence_no" integer, "curriculum_id" "uuid")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    sce.id,
    sce.current_level_id,
    level_row.name,
    level_row.sequence_no,
    course.curriculum_id
  from public.classes class_row
  join public.courses course on course.id = class_row.course_id
  join public.student_curriculum_enrollments sce
    on sce.student_id = p_student
   and sce.curriculum_id = course.curriculum_id
   and sce.status = 'ACTIVE'
  left join public.curriculum_levels level_row
    on level_row.id = sce.current_level_id
  where class_row.id = p_class
  order by sce.is_primary desc nulls last, sce.started_at desc nulls last, sce.id
  limit 1;
$$;


ALTER FUNCTION "public"."class_student_current_level"("p_class" "uuid", "p_student" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commit_tuition_zalo_response_window"("p_to_ms" bigint, "p_complete" boolean) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  row public.tuition_zalo_response_sync;
begin
  select * into row from public.tuition_zalo_response_sync where id for update;
  if row.activated_at is null then
    return 'inactive';
  end if;
  if p_complete is distinct from true or p_to_ms is null or p_to_ms <= 0 then
    return 'held';
  end if;
  update public.tuition_zalo_response_sync
  set checkpoint_ms = p_to_ms,
      last_success_at = clock_timestamp(),
      updated_at = clock_timestamp()
  where id;
  return 'advanced';
end $$;


ALTER FUNCTION "public"."commit_tuition_zalo_response_window"("p_to_ms" bigint, "p_complete" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_momo_deposit_registration"("p_application" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare app public.registration_applications%rowtype;
  student_id uuid; parent_id uuid; placement_id uuid; finance_id uuid;
  ord public.registration_momo_orders%rowtype; branch public.branches%rowtype;
begin
  if not coalesce(public.momo_service_request(), false) then
    raise exception 'MOMO_SERVER_ONLY';
  end if;
  select * into app from public.registration_applications where id = p_application for update;
  if app.status = 'COMPLETED' then return 'ALREADY_COMPLETED'; end if;
  if app.status <> 'PAID' or app.deposit_confirmed_at is null then
    raise exception 'REGISTRATION_PAYMENT_REQUIRED';
  end if;
  if nullif(btrim(coalesce(app.student_name, '')), '') is null or app.student_date_of_birth is null
     or (not coalesce(app.student_over_18, false) and nullif(btrim(coalesce(app.parent_name, '')), '') is null) then
    return 'REVIEW_INCOMPLETE_IDENTITY';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    lower(btrim(app.student_name)) || ':' || app.student_date_of_birth::text, 0));
  if exists(select 1 from public.students s where s.date_of_birth = app.student_date_of_birth
     and lower(btrim(coalesce(s.full_name, ''))) = lower(btrim(app.student_name))) then
    return 'REVIEW_POSSIBLE_DUPLICATE';
  end if;
  student_id := gen_random_uuid();
  parent_id := null;
  placement_id := gen_random_uuid();
  perform set_config('registration.write', 'on', true);
  insert into public.students(id, student_code, full_name, date_of_birth, default_branch_id, admission_date, status)
  values(student_id, null, btrim(app.student_name), app.student_date_of_birth,
    app.branch_id, public.registration_vietnam_today(), 'ACTIVE');
  if nullif(btrim(coalesce(app.parent_name, '')), '') is not null then
    parent_id := gen_random_uuid();
    insert into public.parents(id, parent_code, status)
    values(parent_id, 'PH-' || substr(replace(parent_id::text, '-', ''), 1, 8), 'ACTIVE');
    insert into public.student_parents(student_id, parent_id, relationship, is_primary)
    values(student_id, parent_id, 'GUARDIAN', true);
  end if;
  insert into public.student_placement_cases(id, student_id, registration_application_id,
    branch_id, status, desired_start_date, preferred_schedule)
  values(placement_id, student_id, app.id, app.branch_id, 'UNASSIGNED',
    app.desired_start_date, app.preferred_schedule);
  select * into branch from public.branches where id = app.branch_id;
  for ord in select * from public.registration_momo_orders
    where application_id = app.id and state = 'PAID' order by paid_at for update loop
    finance_id := gen_random_uuid();
    insert into public.payments(id, payment_number, student_id_snapshot, branch_id_snapshot,
      branch_code_snapshot, branch_name_snapshot, amount, currency, payment_method,
      paid_at, reference, notes, status)
    values(finance_id, 'PAY-' || to_char(timezone('Asia/Ho_Chi_Minh', now()), 'YYYY') || '-'
      || lpad(nextval('public.payment_number_seq')::text, 6, '0'), student_id,
      branch.id, branch.code, branch.name, ord.amount, 'VND', 'OTHER', ord.paid_at,
      'MOMO:' || ord.provider_transaction_id, 'Thanh toán hồ sơ ' || app.application_code, 'POSTED');
    update public.registration_momo_orders set finance_payment_id = finance_id where id = ord.id;
  end loop;
  update public.registration_applications set linked_student_id = student_id,
    linked_parent_id = parent_id, status = 'COMPLETED', completed_at = clock_timestamp(),
    version = version + 1, updated_at = clock_timestamp() where id = app.id;
  insert into public.registration_application_events(id, application_id, event_type,
    from_status, to_status, actor_id, metadata)
  values(gen_random_uuid(), app.id, 'REGISTRATION_COMPLETED', 'PAID', 'COMPLETED', null,
    jsonb_build_object('source', 'MOMO_DEPOSIT', 'student_id', student_id, 'parent_id', parent_id)),
    (gen_random_uuid(), app.id, 'PLACEMENT_OPENED', 'PAID', 'COMPLETED', null,
    jsonb_build_object('source', 'MOMO_DEPOSIT', 'placement_id', placement_id));
  insert into public.student_placement_events(id, placement_id, event_type, actor_id)
  values(gen_random_uuid(), placement_id, 'PLACEMENT_OPENED', null);
  perform set_config('registration.write', 'off', true);
  return 'COMPLETED';
end $$;


ALTER FUNCTION "public"."complete_momo_deposit_registration"("p_application" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_notification"("p_job" "uuid", "p_lease" "uuid", "p_receipt" "text" DEFAULT NULL::"text", "p_error" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  job public.notification_jobs;
begin
  select * into job from public.notification_jobs where id = p_job for update;
  if not found
    or job.status <> 'PROCESSING'
    or job.lease_token is distinct from p_lease
    or job.lease_until < now() then
    raise exception 'Stale delivery lease';
  end if;
  if p_error is null and (nullif(btrim(p_receipt), '') is null or length(p_receipt) > 500) then
    raise exception 'Provider confirmation required';
  end if;
  if p_error is not null and p_error not in (
    'PROVIDER_NOT_CONFIGURED',
    'PROVIDER_REJECTED',
    'PROVIDER_TIMEOUT',
    'RECIPIENT_INELIGIBLE',
    'ZALO_OUTBOUND_NOT_CONFIGURED',
    'ZALO_RECIPIENT_NOT_LINKED',
    'TEMPLATE_NOT_APPROVED'
  ) then
    raise exception 'Invalid provider error code';
  end if;
  if p_error is null and job.channel = 'ZALO' then
    if not notification_private.zalo_payment_ready(job.template_key) then
      raise exception 'Live Zalo send is disabled';
    end if;
  end if;
  if p_error is null and job.channel = 'IN_APP' and job.delivery_mode = 'LIVE' then
    insert into public.notification_inbox(job_id, recipient_id)
    values (job.id, job.recipient_id)
    on conflict do nothing;
  end if;
  update public.notification_jobs
  set status = case when p_error is null then 'SENT' else 'FAILED' end,
      provider_receipt = case when p_error is null then p_receipt end,
      error_code = p_error,
      sent_at = case when p_error is null then now() end,
      lease_token = null,
      lease_until = null,
      updated_at = now()
  where id = job.id;
  insert into public.notification_events(job_id, event, details)
  values (
    job.id,
    case when p_error is null then 'CONFIRMED' else 'FAILED' end,
    jsonb_build_object('mode', job.delivery_mode, 'error_code', p_error)
  );
end $$;


ALTER FUNCTION "public"."complete_notification"("p_job" "uuid", "p_lease" "uuid", "p_receipt" "text", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_payos_registration"("p_application" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare app public.registration_applications%rowtype;
  student_id uuid; parent_id uuid; placement_id uuid; finance_id uuid;
  ord public.registration_payos_orders%rowtype; branch public.branches%rowtype;
begin
  if not coalesce(public.momo_service_request(), false) then raise exception 'PAYOS_SERVER_ONLY'; end if;
  select * into app from public.registration_applications where id = p_application for update;
  if app.status = 'COMPLETED' then return 'ALREADY_COMPLETED'; end if;
  if app.status <> 'PAID' or app.deposit_confirmed_at is null then
    raise exception 'REGISTRATION_PAYMENT_REQUIRED';
  end if;
  if nullif(btrim(coalesce(app.student_name, '')), '') is null or app.student_date_of_birth is null
     or (not coalesce(app.student_over_18, false) and nullif(btrim(coalesce(app.parent_name, '')), '') is null) then
    return 'REVIEW_INCOMPLETE_IDENTITY';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    lower(btrim(app.student_name)) || ':' || app.student_date_of_birth::text, 0));
  if exists(select 1 from public.students s where s.date_of_birth = app.student_date_of_birth
     and lower(btrim(coalesce(s.full_name, ''))) = lower(btrim(app.student_name))) then
    return 'REVIEW_POSSIBLE_DUPLICATE';
  end if;
  student_id := gen_random_uuid();
  parent_id := null;
  placement_id := gen_random_uuid();
  perform set_config('registration.write', 'on', true);
  insert into public.students(id, student_code, full_name, date_of_birth, default_branch_id, admission_date, status)
  values(student_id, null, btrim(app.student_name), app.student_date_of_birth,
    app.branch_id, public.registration_vietnam_today(), 'ACTIVE');
  if nullif(btrim(coalesce(app.parent_name, '')), '') is not null then
    parent_id := gen_random_uuid();
    insert into public.parents(id, parent_code, status)
    values(parent_id, 'PH-' || substr(replace(parent_id::text, '-', ''), 1, 8), 'ACTIVE');
    insert into public.student_parents(student_id, parent_id, relationship, is_primary)
    values(student_id, parent_id, 'GUARDIAN', true);
  end if;
  insert into public.student_placement_cases(id, student_id, registration_application_id,
    branch_id, status, desired_start_date, preferred_schedule)
  values(placement_id, student_id, app.id, app.branch_id, 'UNASSIGNED',
    app.desired_start_date, app.preferred_schedule);
  select * into branch from public.branches where id = app.branch_id;
  for ord in select * from public.registration_payos_orders
    where application_id = app.id and state = 'PAID' and finance_payment_id is null
    order by paid_at for update loop
    finance_id := gen_random_uuid();
    insert into public.payments(id, payment_number, student_id_snapshot, branch_id_snapshot,
      branch_code_snapshot, branch_name_snapshot, amount, currency, payment_method,
      paid_at, reference, notes, status)
    values(finance_id, 'PAY-' || to_char(timezone('Asia/Ho_Chi_Minh', now()), 'YYYY') || '-'
      || lpad(nextval('public.payment_number_seq')::text, 6, '0'), student_id,
      branch.id, branch.code, branch.name, ord.attributed_amount, 'VND', 'OTHER', ord.paid_at,
      'PAYOS:' || ord.provider_reference, 'Hoc phi ho so ' || app.application_code, 'POSTED');
    update public.registration_payos_orders set finance_payment_id = finance_id where id = ord.id;
  end loop;
  update public.registration_applications set linked_student_id = student_id,
    linked_parent_id = parent_id, status = 'COMPLETED', completed_at = clock_timestamp(),
    version = version + 1, updated_at = clock_timestamp() where id = app.id;
  insert into public.registration_application_events(id, application_id, event_type,
    from_status, to_status, actor_id, metadata)
  values(gen_random_uuid(), app.id, 'REGISTRATION_COMPLETED', 'PAID', 'COMPLETED', null,
    jsonb_build_object('source', 'PAYOS', 'student_id', student_id, 'parent_id', parent_id)),
    (gen_random_uuid(), app.id, 'PLACEMENT_OPENED', 'PAID', 'COMPLETED', null,
    jsonb_build_object('source', 'PAYOS', 'placement_id', placement_id));
  insert into public.student_placement_events(id, placement_id, event_type, actor_id)
  values(gen_random_uuid(), placement_id, 'PLACEMENT_OPENED', null);
  perform set_config('registration.write', 'off', true);
  return 'COMPLETED';
end $$;


ALTER FUNCTION "public"."complete_payos_registration"("p_application" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_registration_application"("p_request" "uuid", "p_application" "uuid", "p_version" integer, "p_student" "uuid", "p_parent" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor uuid := auth.uid();
  row public.registration_applications%rowtype;
  v_student uuid := p_student;
  v_parent uuid := p_parent;
  matches integer;
  student_code text;
  parent_code text;
  placement_id uuid;
begin
  if actor is null or p_request is null then raise exception 'REGISTRATION_INVALID'; end if;
  if exists(select 1 from public.registration_application_events where id = p_request and event_type = 'REGISTRATION_COMPLETED') then
    return p_application;
  end if;
  if not public.registration_can('registration.complete', (select branch_id from public.registration_applications where id = p_application)) then
    raise exception 'REGISTRATION_UNAUTHORIZED';
  end if;
  select * into row from public.registration_applications where id = p_application for update;
  if not found then raise exception 'REGISTRATION_NOT_FOUND'; end if;
  if row.status = 'COMPLETED' then return row.id; end if;
  if row.version is distinct from p_version then raise exception 'REGISTRATION_STALE'; end if;
  if row.status not in ('VERIFIED', 'PAID', 'PAYMENT_PENDING') then raise exception 'REGISTRATION_TRANSITION_DENIED'; end if;
  if nullif(btrim(coalesce(row.student_name, '')), '') is null or row.student_date_of_birth is null
     or (not coalesce(row.student_over_18, false) and nullif(btrim(coalesce(row.parent_name, '')), '') is null) then
    raise exception 'REGISTRATION_INCOMPLETE';
  end if;
  if row.invoice_id is not null and not public.registration_invoice_settled(row.invoice_id) then
    raise exception 'REGISTRATION_PAYMENT_REQUIRED';
  end if;
  select count(*) into matches
  from public.students student
  where student.date_of_birth = row.student_date_of_birth
    and lower(btrim(coalesce(student.full_name, ''))) = lower(btrim(row.student_name));
  if v_student is null and matches > 0 then raise exception 'REGISTRATION_REVIEW_REQUIRED'; end if;
  if v_student is not null then
    if not exists(
      select 1 from public.students student
      where student.id = v_student and student.status = 'ACTIVE'
        and student.date_of_birth = row.student_date_of_birth
        and lower(btrim(coalesce(student.full_name, ''))) = lower(btrim(row.student_name))
    ) then
      raise exception 'REGISTRATION_MATCH_REJECTED';
    end if;
  end if;
  if nullif(btrim(coalesce(row.parent_name, '')), '') is null then
    v_parent := null;
  elsif v_parent is not null and not exists(select 1 from public.parents where id = v_parent and status = 'ACTIVE') then
    raise exception 'REGISTRATION_MATCH_REJECTED';
  end if;
  perform set_config('registration.write', 'on', true);
  if v_student is null then
    v_student := gen_random_uuid();
    student_code := 'HV-' || substr(replace(v_student::text, '-', ''), 1, 8);
    insert into public.students(id, student_code, full_name, date_of_birth, default_branch_id, admission_date, status)
    values (v_student, student_code, btrim(row.student_name), row.student_date_of_birth, row.branch_id, public.registration_vietnam_today(), 'ACTIVE');
  end if;
  if nullif(btrim(coalesce(row.parent_name, '')), '') is not null and v_parent is null then
    v_parent := gen_random_uuid();
    parent_code := 'PH-' || substr(replace(v_parent::text, '-', ''), 1, 8);
    insert into public.parents(id, parent_code, status) values (v_parent, parent_code, 'ACTIVE');
  end if;
  if v_parent is not null then
    insert into public.student_parents(student_id, parent_id, relationship, is_primary)
    values (v_student, v_parent, 'GUARDIAN', true)
    on conflict (student_id, parent_id) do nothing;
  end if;
  placement_id := gen_random_uuid();
  insert into public.student_placement_cases(
    id, student_id, registration_application_id, branch_id, status, desired_start_date, preferred_schedule, owner_user_id
  ) values (
    placement_id, v_student, row.id, row.branch_id, 'UNASSIGNED', row.desired_start_date, row.preferred_schedule, actor
  );
  update public.registration_applications set
    linked_student_id = v_student,
    linked_parent_id = v_parent,
    status = 'COMPLETED',
    payment_confirmed_at = case when invoice_id is not null then coalesce(payment_confirmed_at, clock_timestamp()) else payment_confirmed_at end,
    completed_at = clock_timestamp(),
    version = version + 1,
    updated_at = clock_timestamp()
  where id = row.id;
  insert into public.registration_application_events(id, application_id, event_type, from_status, to_status, actor_id, metadata)
  values
    (p_request, row.id, 'REGISTRATION_COMPLETED', row.status, 'COMPLETED', actor, jsonb_build_object('student_id', v_student, 'parent_id', v_parent)),
    (gen_random_uuid(), row.id, 'STUDENT_LINKED', row.status, 'COMPLETED', actor, jsonb_build_object('student_id', v_student)),
    (gen_random_uuid(), row.id, 'PLACEMENT_OPENED', row.status, 'COMPLETED', actor, jsonb_build_object('placement_id', placement_id));
  if v_parent is not null then
    insert into public.registration_application_events(id, application_id, event_type, from_status, to_status, actor_id, metadata)
    values (gen_random_uuid(), row.id, 'PARENT_LINKED', row.status, 'COMPLETED', actor, jsonb_build_object('parent_id', v_parent));
  end if;
  insert into public.student_placement_events(id, placement_id, event_type, actor_id)
  values (gen_random_uuid(), placement_id, 'PLACEMENT_OPENED', actor);
  perform set_config('registration.write', 'off', true);
  return row.id;
end $$;


ALTER FUNCTION "public"."complete_registration_application"("p_request" "uuid", "p_application" "uuid", "p_version" integer, "p_student" "uuid", "p_parent" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."configure_employee_compensation"("p_employee" "uuid", "p_branch" "uuid", "p_type" "text", "p_rate" numeric, "p_currency" "text", "p_from" "date", "p_to" "date", "p_class_type" "text", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare result uuid; teacher uuid;
begin
 if not coalesce(public.has_role('SUPER_ADMIN'),false) then raise exception 'Unauthorized';end if;
 if p_reason is null or char_length(btrim(p_reason)) not between 1 and 2000 then raise exception 'Compensation reason required';end if;
 select teacher_id into teacher from public.employees where id=p_employee;
 if not found then raise exception 'Employee not found';end if;
 if p_type='MONTHLY' then
  result:=public.add_employee_compensation_rule(p_employee,p_branch,p_rate,p_currency,p_from,p_to);
 elsif p_type='PER_SESSION' and teacher is not null then
  result:=public.add_session_compensation_rule(teacher,p_branch,p_class_type,p_rate,p_currency,p_from,p_to);
 elsif p_type='HOURLY' and teacher is not null then
  result:=public.add_compensation_rule(teacher,p_branch,p_type,p_rate,p_currency,p_from,p_to);
 else raise exception 'Linked teacher required for session or hourly compensation';end if;
 update public.teacher_compensation_rules set reason=btrim(p_reason) where id=result;
 return result;
end$$;


ALTER FUNCTION "public"."configure_employee_compensation"("p_employee" "uuid", "p_branch" "uuid", "p_type" "text", "p_rate" numeric, "p_currency" "text", "p_from" "date", "p_to" "date", "p_class_type" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."configure_employee_leave"("p_unit" "text", "p_group" "text", "p_employee" "uuid", "p_from" "date", "p_to" "date", "p_minutes" integer, "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$declare result uuid;begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Employee attendance denied';end if;
 if p_from is null or p_to is null or not isfinite(p_from) or not isfinite(p_to) or p_to<p_from then raise exception 'Invalid policy window';end if;
 perform pg_advisory_xact_lock(hashtextextended('employee_leave_policy',0));
 if exists(select 1 from public.employee_leave_policies where unit_code=p_unit and employee_group is not distinct from nullif(btrim(p_group),'') and employee_id is not distinct from p_employee and starts_on<=p_to and ends_on>=p_from) then raise exception 'Overlapping leave policy; use a new non-overlapping effective window';end if;
 insert into public.employee_leave_policies(unit_code,employee_group,employee_id,starts_on,ends_on,paid_minutes,reason,actor)
 values(p_unit,nullif(btrim(p_group),''),p_employee,p_from,p_to,p_minutes,btrim(p_reason),auth.uid()) returning id into result;return result;end$$;


ALTER FUNCTION "public"."configure_employee_leave"("p_unit" "text", "p_group" "text", "p_employee" "uuid", "p_from" "date", "p_to" "date", "p_minutes" integer, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."configure_employee_unit"("p_unit" "text", "p_branch" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$declare old_row jsonb;begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Employee administration denied'; end if;
 if nullif(btrim(p_reason),'') is null then raise exception 'Reason required'; end if;
 select to_jsonb(u) into old_row from public.organization_units u where code=p_unit for update;
 if old_row is null then raise exception 'Unknown unit'; end if;
 if p_branch is not null and not exists(select 1 from public.branches where id=p_branch and status='ACTIVE') then raise exception 'Active branch required'; end if;
 update public.organization_units set branch_id=p_branch where code=p_unit;
 insert into public.employee_audit(action,before_data,after_data,reason,actor) values('UNIT_MAPPING',old_row,jsonb_build_object('unit',p_unit,'branch_id',p_branch),p_reason,auth.uid());
end$$;


ALTER FUNCTION "public"."configure_employee_unit"("p_unit" "text", "p_branch" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."configure_staff_compensation_component"("p_employee" "uuid", "p_component_code" "text", "p_branch" "uuid", "p_amount" numeric, "p_rate" numeric, "p_percentage" numeric, "p_basis_component_code" "text", "p_currency" "text", "p_class_type" "text", "p_effective_from" "date", "p_effective_to" "date", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  e public.employees%rowtype;
  ev public.employee_versions%rowtype;
  catalog public.payroll_component_catalog%rowtype;
  existing public.staff_compensation_components%rowtype;
  inserted public.staff_compensation_components%rowtype;
  normalized_component text;
  normalized_basis text;
  normalized_currency text;
  normalized_class_type text;
begin
  if auth.uid() is null
     or not coalesce(public.account_is_active(),false)
     or not coalesce(public.has_role('SUPER_ADMIN'),false)
  then
    raise exception 'STAFF_COMPENSATION_UNAUTHORIZED';
  end if;

  if p_employee is null then
    raise exception 'STAFF_COMPENSATION_EMPLOYEE_REQUIRED';
  end if;

  normalized_component := upper(btrim(coalesce(p_component_code,'')));
  if normalized_component = '' then
    raise exception 'STAFF_COMPENSATION_COMPONENT_REQUIRED';
  end if;

  if p_branch is null then
    raise exception 'STAFF_COMPENSATION_BRANCH_REQUIRED';
  end if;

  if p_effective_from is null or not isfinite(p_effective_from) then
    raise exception 'STAFF_COMPENSATION_EFFECTIVE_FROM_REQUIRED';
  end if;

  if p_effective_to is not null
     and (not isfinite(p_effective_to) or p_effective_to < p_effective_from)
  then
    raise exception 'STAFF_COMPENSATION_INVALID_EFFECTIVE_RANGE';
  end if;

  if p_reason is null
     or char_length(btrim(p_reason)) not between 1 and 2000
  then
    raise exception 'STAFF_COMPENSATION_REASON_REQUIRED';
  end if;

  select *
    into e
  from public.employees
  where id = p_employee
  for update;

  if not found then
    raise exception 'STAFF_COMPENSATION_EMPLOYEE_NOT_FOUND';
  end if;

  if p_effective_from < e.hire_date then
    raise exception 'STAFF_COMPENSATION_BEFORE_HIRE_DATE';
  end if;

  select *
    into ev
  from public.employee_versions v
  where v.employee_id = e.id
    and v.effective_on <= p_effective_from
  order by v.effective_on desc, v.version desc
  limit 1;

  if not found or ev.employment_status <> 'ACTIVE' then
    raise exception 'STAFF_COMPENSATION_ACTIVE_EMPLOYMENT_REQUIRED';
  end if;

  if not exists(
    select 1
    from public.branches b
    where b.id = p_branch
      and b.status = 'ACTIVE'
  ) then
    raise exception 'STAFF_COMPENSATION_ACTIVE_BRANCH_REQUIRED';
  end if;

  select *
    into catalog
  from public.payroll_component_catalog c
  where c.code = normalized_component
    and c.status = 'ACTIVE';

  if not found then
    raise exception 'STAFF_COMPENSATION_COMPONENT_NOT_FOUND';
  end if;

  if not catalog.recurring_configurable
     or catalog.default_calculation_method = 'EVENT'
  then
    raise exception 'STAFF_COMPENSATION_EVENT_COMPONENT_NOT_CONFIGURABLE';
  end if;

  normalized_basis :=
    nullif(upper(btrim(coalesce(p_basis_component_code,''))), '');

  normalized_currency :=
    nullif(upper(btrim(coalesce(p_currency,''))), '');

  normalized_class_type :=
    nullif(upper(btrim(coalesce(p_class_type,''))), '');

  if normalized_class_type is not null
     and normalized_class_type not in ('ONE_ON_ONE','GROUP')
  then
    raise exception 'STAFF_COMPENSATION_INVALID_CLASS_TYPE';
  end if;

  if catalog.default_calculation_method = 'FIXED_AMOUNT' then
    if p_amount is null
       or p_amount <= 0
       or p_amount = 'NaN'::numeric
       or p_rate is not null
       or p_percentage is not null
       or normalized_basis is not null
       or normalized_class_type is not null
       or normalized_currency is null
       or normalized_currency !~ '^[A-Z]{3}$'
    then
      raise exception 'STAFF_COMPENSATION_INVALID_FIXED_AMOUNT_SHAPE';
    end if;

  elsif catalog.default_calculation_method in ('PER_SESSION','PER_HOUR') then
    if p_rate is null
       or p_rate <= 0
       or p_rate = 'NaN'::numeric
       or p_amount is not null
       or p_percentage is not null
       or normalized_basis is not null
       or normalized_currency is null
       or normalized_currency !~ '^[A-Z]{3}$'
    then
      raise exception 'STAFF_COMPENSATION_INVALID_RATE_SHAPE';
    end if;

    if catalog.default_calculation_method = 'PER_HOUR'
       and normalized_class_type is not null
    then
      raise exception 'STAFF_COMPENSATION_CLASS_TYPE_ONLY_FOR_SESSION_RATE';
    end if;

  elsif catalog.default_calculation_method = 'PERCENTAGE' then
    if p_percentage is null
       or p_percentage <= 0
       or p_percentage > 100
       or p_percentage = 'NaN'::numeric
       or p_amount is not null
       or p_rate is not null
       or normalized_currency is not null
       or normalized_class_type is not null
       or normalized_basis is null
       or normalized_basis = normalized_component
       or not exists(
         select 1
         from public.payroll_component_catalog basis
         where basis.code = normalized_basis
           and basis.status = 'ACTIVE'
       )
    then
      raise exception 'STAFF_COMPENSATION_INVALID_PERCENTAGE_SHAPE';
    end if;

  else
    raise exception 'STAFF_COMPENSATION_UNSUPPORTED_CALCULATION_METHOD';
  end if;

  if normalized_component = 'TEACHING_PER_SESSION' then
    if e.teacher_id is null then
      raise exception 'STAFF_COMPENSATION_TEACHER_PROFILE_REQUIRED';
    end if;

    if not exists(
      select 1
      from public.teachers t
      join public.teacher_branches tb
        on tb.teacher_id = t.id
       and tb.branch_id = p_branch
      where t.id = e.teacher_id
        and t.status = 'ACTIVE'
    ) then
      raise exception 'STAFF_COMPENSATION_ACTIVE_TEACHER_BRANCH_REQUIRED';
    end if;

    if not exists(
      select 1
      from public.staff_role_assignments sra
      where sra.employee_id = e.id
        and sra.role_code = 'TEACHER'
        and sra.branch_id = p_branch
        and sra.status = 'ACTIVE'
        and sra.effective_from <= p_effective_from
        and (
          (p_effective_to is null and sra.effective_to is null)
          or
          (p_effective_to is not null
            and (sra.effective_to is null or sra.effective_to >= p_effective_to))
        )
    ) then
      raise exception 'STAFF_COMPENSATION_ACTIVE_TEACHER_ROLE_REQUIRED';
    end if;
  end if;

  -- Idempotency for an exact same-start configuration.
  select *
    into existing
  from public.staff_compensation_components s
  where s.employee_id = e.id
    and s.component_code = normalized_component
    and s.branch_id = p_branch
    and s.effective_from = p_effective_from
    and s.class_type is not distinct from normalized_class_type
  limit 1;

  if found then
    if existing.calculation_method = catalog.default_calculation_method
       and existing.amount is not distinct from p_amount
       and existing.rate is not distinct from p_rate
       and existing.percentage is not distinct from p_percentage
       and existing.basis_component_code is not distinct from normalized_basis
       and existing.currency is not distinct from normalized_currency
       and existing.effective_to is not distinct from p_effective_to
       and existing.status = 'ACTIVE'
    then
      return jsonb_build_object(
        'status','ALREADY_CONFIGURED',
        'component_id',existing.id,
        'employee_id',existing.employee_id,
        'component_code',existing.component_code,
        'branch_id',existing.branch_id,
        'effective_from',existing.effective_from,
        'effective_to',existing.effective_to
      );
    end if;
  end if;

  -- Prevent ambiguous active ranges.
  if exists(
    select 1
    from public.staff_compensation_components s
    where s.employee_id = e.id
      and s.component_code = normalized_component
      and s.branch_id = p_branch
      and s.status = 'ACTIVE'
      and daterange(s.effective_from,s.effective_to,'[]')
          && daterange(p_effective_from,p_effective_to,'[]')
      and (
        catalog.default_calculation_method <> 'PER_SESSION'
        or s.class_type is null
        or normalized_class_type is null
        or s.class_type = normalized_class_type
      )
  ) then
    raise exception 'STAFF_COMPENSATION_OVERLAP';
  end if;

  insert into public.staff_compensation_components(
    employee_id,
    component_code,
    branch_id,
    calculation_method,
    amount,
    rate,
    percentage,
    basis_component_code,
    currency,
    class_type,
    effective_from,
    effective_to,
    status,
    reason,
    created_by
  )
  values(
    e.id,
    normalized_component,
    p_branch,
    catalog.default_calculation_method,
    p_amount,
    p_rate,
    p_percentage,
    normalized_basis,
    normalized_currency,
    normalized_class_type,
    p_effective_from,
    p_effective_to,
    'ACTIVE',
    btrim(p_reason),
    auth.uid()
  )
  returning * into inserted;

  insert into public.employee_audit(
    employee_id,
    action,
    after_data,
    reason,
    actor
  )
  values(
    e.id,
    'COMPENSATION_COMPONENT_CREATED',
    to_jsonb(inserted),
    btrim(p_reason),
    auth.uid()
  );

  return jsonb_build_object(
    'status','CONFIGURED',
    'component_id',inserted.id,
    'employee_id',inserted.employee_id,
    'component_code',inserted.component_code,
    'calculation_method',inserted.calculation_method,
    'amount',inserted.amount,
    'rate',inserted.rate,
    'percentage',inserted.percentage,
    'currency',inserted.currency,
    'class_type',inserted.class_type,
    'branch_id',inserted.branch_id,
    'effective_from',inserted.effective_from,
    'effective_to',inserted.effective_to
  );
end;
$_$;


ALTER FUNCTION "public"."configure_staff_compensation_component"("p_employee" "uuid", "p_component_code" "text", "p_branch" "uuid", "p_amount" numeric, "p_rate" numeric, "p_percentage" numeric, "p_basis_component_code" "text", "p_currency" "text", "p_class_type" "text", "p_effective_from" "date", "p_effective_to" "date", "p_reason" "text") OWNER TO "postgres";


