CREATE OR REPLACE FUNCTION "public"."create_crm_campaign"("p_request" "uuid", "p_name" "text", "p_platform" "text", "p_channel" "text", "p_branch" "uuid", "p_starts_on" "date", "p_ends_on" "date", "p_budget" numeric, "p_currency" "text", "p_utm_source" "text", "p_utm_medium" "text", "p_utm_campaign" "text", "p_utm_content" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor uuid;
  name text := public.crm_text(p_name, 200);
  platform text := nullif(upper(btrim(coalesce(p_platform, ''))), '');
  existing public.crm_campaigns%rowtype;
begin
  if p_request is null or name is null or platform is null or platform not in ('FACEBOOK', 'GOOGLE', 'TIKTOK', 'ZALO', 'WEBSITE', 'REFERRAL', 'WALK_IN', 'OTHER') then
    raise exception 'CRM_CAMPAIGN_INVALID';
  end if;
  if p_branch is null then
    if auth.uid() is null or not public.account_is_active() or not public.has_role('SUPER_ADMIN') then
      raise exception 'CRM_CAMPAIGN_UNAUTHORIZED';
    end if;
    actor := auth.uid();
  else
    actor := public.crm_actor('crm.campaign.manage', p_branch);
  end if;
  if (p_budget is null) <> (p_currency is null) or (p_budget is not null and p_budget < 0) then
    raise exception 'CRM_CAMPAIGN_INVALID';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('crm-campaign:' || p_request::text, 0));
  select * into existing from public.crm_campaigns where id = p_request;
  if found then
    if existing.created_by is distinct from actor or existing.name is distinct from name or existing.branch_id is distinct from p_branch then
      raise exception 'CRM_CAMPAIGN_REQUEST_MISMATCH';
    end if;
    return existing.id;
  end if;
  perform set_config('crm.lead_write', 'on', true);
  insert into public.crm_campaigns(id, name, platform, channel, branch_id, starts_on, ends_on, budget_amount, currency, utm_source, utm_medium, utm_campaign, utm_content, created_by)
  values (p_request, name, platform, public.crm_text(p_channel, 80), p_branch, p_starts_on, p_ends_on, p_budget, nullif(upper(btrim(coalesce(p_currency, ''))), ''), public.crm_text(p_utm_source, 120), public.crm_text(p_utm_medium, 120), public.crm_text(p_utm_campaign, 120), public.crm_text(p_utm_content, 120), actor);
  perform set_config('crm.lead_write', 'off', true);
  return p_request;
end $$;


ALTER FUNCTION "public"."create_crm_campaign"("p_request" "uuid", "p_name" "text", "p_platform" "text", "p_channel" "text", "p_branch" "uuid", "p_starts_on" "date", "p_ends_on" "date", "p_budget" numeric, "p_currency" "text", "p_utm_source" "text", "p_utm_medium" "text", "p_utm_campaign" "text", "p_utm_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_crm_lead"("p_request" "uuid", "p_branch" "uuid", "p_full_name" "text", "p_phone" "text", "p_email" "text", "p_parent_name" "text", "p_student_name" "text", "p_student_date_of_birth" "date", "p_program_interest" "text", "p_instrument_interest" "text", "p_source_type" "text", "p_owner" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  actor uuid;
  existing public.crm_leads%rowtype;
  source text := coalesce(nullif(upper(btrim(coalesce(p_source_type, ''))), ''), 'MANUAL');
  name text := public.crm_text(p_full_name, 200);
  phone text := public.crm_text(p_phone, 40);
  email text := public.crm_text(p_email, 200);
  parent_name text := public.crm_text(p_parent_name, 200);
  student_name text := public.crm_text(p_student_name, 200);
  program text := public.crm_text(p_program_interest, 200);
  instrument text := public.crm_text(p_instrument_interest, 200);
  phone_key text := public.crm_phone_key(phone);
  email_key text := public.crm_email_key(email);
  owner uuid := coalesce(p_owner, auth.uid());
begin
  if p_request is null or source not in ('MANUAL', 'WALK_IN', 'REFERRAL', 'WEBSITE', 'ZALO', 'PHONE', 'OTHER') then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  if p_student_date_of_birth is not null and not isfinite(p_student_date_of_birth) then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  if email_key is not null and email_key !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  if phone is not null and (phone_key is null or phone_key !~ '^[0-9]{6,20}$') then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  if name is null and phone_key is null and email_key is null and parent_name is null and student_name is null then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  actor := public.crm_actor('crm.lead.create', p_branch);
  if owner is distinct from actor then
    perform public.crm_actor('crm.lead.assign', p_branch);
  end if;
  if not exists(select 1 from public.profiles where id = owner and status = 'ACTIVE') then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('crm-lead-request:' || p_request::text, 0));
  select * into existing from public.crm_leads where id = p_request;
  if found then
    if existing.created_by is distinct from actor
       or existing.branch_id is distinct from p_branch
       or existing.full_name is distinct from name
       or existing.phone is distinct from phone
       or existing.email is distinct from email
       or existing.parent_name is distinct from parent_name
       or existing.student_name is distinct from student_name
       or existing.student_date_of_birth is distinct from p_student_date_of_birth
       or existing.program_interest is distinct from program
       or existing.instrument_interest is distinct from instrument
       or existing.source_type is distinct from source
       or existing.owner_user_id is distinct from owner
    then
      raise exception 'CRM_LEAD_REQUEST_MISMATCH';
    end if;
    return existing.id;
  end if;
  perform set_config('crm.lead_write', 'on', true);
  insert into public.crm_leads(
    id, branch_id, full_name, phone, email, phone_key, email_key, parent_name, student_name,
    student_date_of_birth, program_interest, instrument_interest, source_type, owner_user_id, created_by
  ) values (
    p_request, p_branch, name, phone, email, phone_key, email_key, parent_name, student_name,
    p_student_date_of_birth, program, instrument, source, owner, actor
  );
  insert into public.crm_lead_events(id, lead_id, event_type, to_status, actor_id, metadata)
  values (
    gen_random_uuid(), p_request, 'CREATED', 'NEW', actor,
    jsonb_build_object('owner_user_id', owner, 'source_type', source)
  );
  perform set_config('crm.lead_write', 'off', true);
  return p_request;
end $_$;


ALTER FUNCTION "public"."create_crm_lead"("p_request" "uuid", "p_branch" "uuid", "p_full_name" "text", "p_phone" "text", "p_email" "text", "p_parent_name" "text", "p_student_name" "text", "p_student_date_of_birth" "date", "p_program_interest" "text", "p_instrument_interest" "text", "p_source_type" "text", "p_owner" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_crm_lead_with_interest"("p_request" "uuid", "p_branch" "uuid", "p_full_name" "text", "p_phone" "text", "p_email" "text", "p_parent_name" "text", "p_student_name" "text", "p_student_date_of_birth" "date", "p_program_interest" "text", "p_instrument_interest" "text", "p_source_type" "text", "p_owner" "uuid", "p_interest_level" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_lead uuid;
  v_interest text := upper(btrim(coalesce(p_interest_level, '')));
  existing_interest text;
begin
  if v_interest not in ('REFERENCE', 'INTERESTED', 'POTENTIAL') then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  select interest_level into existing_interest from public.crm_leads where id = p_request;
  if existing_interest is not null and existing_interest <> v_interest then
    raise exception 'CRM_LEAD_REQUEST_MISMATCH';
  end if;
  v_lead := public.create_crm_lead(
    p_request, p_branch, p_full_name, p_phone, p_email, p_parent_name,
    p_student_name, p_student_date_of_birth, p_program_interest,
    p_instrument_interest, p_source_type, p_owner
  );
  if existing_interest is null and v_interest <> 'REFERENCE' then
    perform set_config('crm.lead_write', 'on', true);
    update public.crm_leads set interest_level = v_interest, version = version + 1,
      updated_at = clock_timestamp() where id = v_lead;
    insert into public.crm_lead_events(id, lead_id, event_type, from_status, to_status, actor_id, metadata)
    values (gen_random_uuid(), v_lead, 'INTEREST_LEVEL_SET', 'NEW', 'NEW', auth.uid(),
      jsonb_build_object('from', 'REFERENCE', 'to', v_interest));
    perform set_config('crm.lead_write', 'off', true);
  end if;
  return v_lead;
end $$;


