CREATE TABLE IF NOT EXISTS "public"."curriculum_component_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "component_id" "uuid" NOT NULL,
    "code" "text" NOT NULL,
    "name" "text" NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "is_required" boolean DEFAULT true NOT NULL,
    "status" "text" DEFAULT 'ACTIVE'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "curriculum_component_items_status_check" CHECK (("status" = ANY (ARRAY['ACTIVE'::"text", 'INACTIVE'::"text"])))
);


ALTER TABLE "public"."curriculum_component_items" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_curriculum_lesson"("p_curriculum_id" "uuid", "p_level_id" "uuid", "p_subject_id" "uuid", "p_component_id" "uuid", "p_code" "text", "p_name" "text", "p_is_required" boolean, "p_sort_order" integer, "p_status" "text") RETURNS "public"."curriculum_component_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_component uuid;
  v_code text;
  v_name text;
  v_order integer;
  v_row public.curriculum_component_items;
begin
  v_component := public.lesson_operator_component(p_curriculum_id, p_level_id, p_subject_id, p_component_id);
  v_code := upper(trim(coalesce(p_code, '')));
  v_name := trim(coalesce(p_name, ''));

  if v_code !~ '^[A-Z0-9_-]{2,50}$' then
    raise exception 'Invalid lesson code' using errcode = 'P0001';
  end if;
  if v_name = '' or char_length(v_name) > 200 then
    raise exception 'Lesson name is required' using errcode = 'P0001';
  end if;
  if p_status is distinct from 'ACTIVE' and p_status is distinct from 'INACTIVE' then
    raise exception 'Invalid lesson status' using errcode = 'P0001';
  end if;
  if p_sort_order is null or p_sort_order < 0 then
    raise exception 'Invalid sort order' using errcode = 'P0001';
  end if;
  if p_is_required is null then
    raise exception 'Invalid lesson requirement' using errcode = 'P0001';
  end if;

  v_order := p_sort_order;
  if v_order = 0 then
    select coalesce(max(sort_order), 0) + 1 into v_order
    from public.curriculum_component_items
    where component_id = v_component;
  end if;

  update public.curriculum_component_items
  set sort_order = sort_order + 1
  where component_id = v_component
    and sort_order >= v_order;

  insert into public.curriculum_component_items (
    component_id, code, name, sort_order, is_required, status
  ) values (
    v_component, v_code, v_name, v_order, p_is_required, p_status
  )
  returning * into v_row;

  perform public.normalize_lesson_order(v_component);

  select * into v_row
  from public.curriculum_component_items
  where id = v_row.id;

  return v_row;
exception
  when unique_violation then
    raise exception 'Lesson code already exists' using errcode = '23505';
end;
$_$;


ALTER FUNCTION "public"."create_curriculum_lesson"("p_curriculum_id" "uuid", "p_level_id" "uuid", "p_subject_id" "uuid", "p_component_id" "uuid", "p_code" "text", "p_name" "text", "p_is_required" boolean, "p_sort_order" integer, "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_employee"("p_home" "text", "p_hire_date" "date", "p_full_name" "text", "p_group" "text", "p_pay_type" "text", "p_role" "uuid", "p_profile" "uuid", "p_teacher" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$declare n bigint; eid uuid;begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Employee administration denied'; end if;
 perform hr_private.check_links(p_profile,p_teacher);
 insert into hr_private.employee_counters(unit_code,last_number) values(p_home,1) on conflict(unit_code) do update set last_number=employee_counters.last_number+1 returning last_number into n;
 insert into public.employees(employee_code,home_unit,hire_date,profile_id,teacher_id,created_by)
 values('VIBE-'||p_home||'-'||lpad(n::text,greatest(4,length(n::text)),'0'),p_home,p_hire_date,p_profile,p_teacher,auth.uid()) returning id into eid;
 perform public.set_employee_version(eid,0,p_hire_date,p_full_name,p_home,p_group,'ACTIVE',p_pay_type,p_role,p_reason);
 insert into public.employee_audit(employee_id,action,after_data,reason,actor) select eid,'IDENTITY_CREATED',to_jsonb(e),p_reason,auth.uid() from public.employees e where id=eid;
 return eid;end$$;


ALTER FUNCTION "public"."create_employee"("p_home" "text", "p_hire_date" "date", "p_full_name" "text", "p_group" "text", "p_pay_type" "text", "p_role" "uuid", "p_profile" "uuid", "p_teacher" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_employee_expense_claim"("p_month" "date", "p_title" "text", "p_currency" "text", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare eid uuid; bid uuid; cid uuid; payload jsonb; prior jsonb;
begin
  if not coalesce(public.account_is_active(),false) or auth.uid() is null then raise exception 'EXPENSE_UNAUTHORIZED'; end if;
  select e.id,u.branch_id into eid,bid from public.employees e
  cross join lateral (
    select v.unit_code,v.employment_status from public.employee_versions v
    where v.employee_id=e.id and v.effective_on<=(now() at time zone 'Asia/Ho_Chi_Minh')::date
    order by v.effective_on desc,v.version desc limit 1
  ) v
  join public.organization_units u on u.code=v.unit_code
  join public.branches b on b.id=u.branch_id and b.status='ACTIVE'
  where e.profile_id=auth.uid() and v.employment_status='ACTIVE';
  if eid is null or bid is null or not vibe_expense_private.owns_employee(eid,bid) then
    raise exception 'EXPENSE_ACTIVE_EMPLOYEE_LINK_AND_OWN_PERMISSION_REQUIRED';
  end if;
  if p_month is null or not isfinite(p_month) or extract(day from p_month)<>1 then raise exception 'EXPENSE_INVALID_MONTH'; end if;
  if p_title is null or char_length(btrim(p_title)) not between 1 and 200 then raise exception 'EXPENSE_TITLE_REQUIRED'; end if;
  if p_currency is null or p_currency !~ '^[A-Z]{3}$' then raise exception 'EXPENSE_INVALID_CURRENCY'; end if;
  payload:=jsonb_build_object('action','CREATE','employee_id',eid,'branch_id',bid,'month',p_month,'title',btrim(p_title),'currency',p_currency);
  prior:=vibe_expense_private.replay(p_key,payload); if prior is not null then return prior; end if;
  insert into public.employee_expense_claims(employee_id,branch_id,requested_month,currency,title,created_by)
  values(eid,bid,p_month,p_currency,btrim(p_title),auth.uid()) returning id into cid;
  return vibe_expense_private.record_event(cid,p_key,payload,'CREATED',null);
end;
$_$;


ALTER FUNCTION "public"."create_employee_expense_claim"("p_month" "date", "p_title" "text", "p_currency" "text", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_employee_expense_claim_v2"("p_trip" "uuid", "p_month" "date", "p_currency" "text", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare ctx record; trip_row public.employee_trips%rowtype; cid uuid; payload jsonb; prior jsonb;
begin
  select * into ctx from vibe_expense_private.current_employee_context();
  if ctx.employee_id is null then raise exception 'EXPENSE_ACTIVE_EMPLOYEE_LINK_AND_OWN_PERMISSION_REQUIRED'; end if;
  if p_trip is null then raise exception 'EXPENSE_APPROVED_OWN_TRIP_REQUIRED'; end if;
  perform pg_advisory_xact_lock(hashtextextended('vibe_expense_trip:'||p_trip::text,0));
  select t.* into trip_row from public.employee_trips t
  join public.employee_trip_reviews r on r.trip_id=t.id and r.decision='APPROVED'
  where t.id=p_trip and t.employee_id=ctx.employee_id;
  if not found then raise exception 'EXPENSE_APPROVED_OWN_TRIP_REQUIRED'; end if;
  if p_month is null or not isfinite(p_month) or extract(day from p_month)<>1 then raise exception 'EXPENSE_INVALID_MONTH'; end if;
  if p_currency is null or p_currency !~ '^[A-Z]{3}$' then raise exception 'EXPENSE_INVALID_CURRENCY'; end if;
  payload:=jsonb_build_object('action','CREATE_V2','employee_id',ctx.employee_id,'branch_id',ctx.branch_id,'trip_id',p_trip,'month',p_month,'currency',p_currency);
  prior:=vibe_expense_private.replay(p_key,payload); if prior is not null then return prior; end if;
  if exists(select 1 from public.employee_expense_claims c where c.trip_id=p_trip and c.claim_model='ITEMIZED_V2' and c.status not in ('REJECTED','CANCELLED'))
     or exists(select 1 from public.employee_expense_claim_lines l where l.trip_id=p_trip and l.reservation_active)
     or exists(select 1 from public.payroll_adjustments a where a.trip_id=p_trip and a.kind='TRAVEL_ALLOWANCE') then
    raise exception 'EXPENSE_TRIP_RESERVED_BY_ANOTHER_CLAIM';
  end if;
  insert into public.employee_expense_claims(employee_id,branch_id,trip_id,claim_model,requested_month,currency,title,created_by)
  values(ctx.employee_id,ctx.branch_id,p_trip,'ITEMIZED_V2',p_month,p_currency,btrim(trip_row.reason),auth.uid()) returning id into cid;
  return vibe_expense_private.record_event(cid,p_key,payload,'CREATED',null);
end;
$_$;


ALTER FUNCTION "public"."create_employee_expense_claim_v2"("p_trip" "uuid", "p_month" "date", "p_currency" "text", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_employee_with_private_profile"("p_home" "text", "p_hire_date" "date", "p_full_name" "text", "p_group" "text", "p_pay_type" "text", "p_role" "uuid", "p_profile" "uuid", "p_teacher" "uuid", "p_reason" "text", "p_email" "text", "p_phone" "text", "p_address" "text", "p_citizen_id" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  eid uuid;
  email_value text;
  phone_value text;
  address_value text;
  citizen_value text;
begin
  if auth.uid() is null
     or not coalesce(
       public.account_is_active(),
       false
     )
     or not coalesce(
       public.has_role('SUPER_ADMIN'),
       false
     )
  then
    raise exception
      'EMPLOYEE_PRIVATE_UNAUTHORIZED';
  end if;

  email_value :=
    hr_private.normalize_employee_email(
      p_email
    );

  phone_value :=
    hr_private.normalize_employee_phone(
      p_phone
    );

  address_value :=
    hr_private.normalize_employee_address(
      p_address
    );

  citizen_value :=
    hr_private.normalize_employee_citizen_id(
      p_citizen_id
    );

  eid := public.create_employee(
    p_home,
    p_hire_date,
    p_full_name,
    p_group,
    p_pay_type,
    p_role,
    p_profile,
    p_teacher,
    p_reason
  );

  insert into
    hr_private.employee_private_profiles (
      employee_id,
      email,
      phone,
      address,
      citizen_id,
      created_by,
      updated_by
    )
  values (
    eid,
    email_value,
    phone_value,
    address_value,
    citizen_value,
    auth.uid(),
    auth.uid()
  );

  insert into public.employee_audit (
    employee_id,
    action,
    after_data,
    reason,
    actor
  )
  values (
    eid,
    'PRIVATE_PROFILE_CREATED',
    jsonb_build_object(
      'email_present', true,
      'phone_last4',
        right(phone_value, 4),
      'address_present', true,
      'citizen_id_masked',
        '********' ||
        right(citizen_value, 4)
    ),
    btrim(p_reason),
    auth.uid()
  );

  return eid;
end;
$$;


