CREATE OR REPLACE FUNCTION "public"."create_makeup_session_occurrence"("p_source_occurrence_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_room_id" "uuid", "p_enrollment_ids" "uuid"[], "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_source_schedule_id uuid;
  v_source_status text;
  v_source_type text;

  v_class_id uuid;
  v_branch_id uuid;
  v_timezone text;

  v_makeup_date date;

  v_room_branch_id uuid;
  v_room_status text;

  v_participant_count integer;
  v_result uuid;
begin

  -- =======================================================
  -- BASIC INPUT VALIDATION
  -- =======================================================

  if p_starts_at is null or p_ends_at is null then
    raise exception
      'Session start and end time are required';
  end if;

  if p_ends_at <= p_starts_at then
    raise exception
      'End time must be after start time';
  end if;

  if nullif(btrim(p_reason), '') is null then
    raise exception
      'Makeup reason is required';
  end if;

  if coalesce(cardinality(p_enrollment_ids), 0) = 0 then
    raise exception
      'At least one makeup participant is required';
  end if;

  if exists (
    select 1
    from unnest(p_enrollment_ids)
      as participant(enrollment_id)
    where participant.enrollment_id is null
  ) then
    raise exception
      'Makeup participant is required';
  end if;


  select
    count(
      distinct participant.enrollment_id
    )::integer
  into v_participant_count
  from unnest(p_enrollment_ids)
    as participant(enrollment_id);


  if v_participant_count <>
    cardinality(p_enrollment_ids)
  then
    raise exception
      'Makeup participants must be unique';
  end if;


  -- =======================================================
  -- ANCHOR SESSION
  -- The anchor identifies the class.
  -- Individual credit lineage is stored per participant.
  -- =======================================================

  select
    occurrence.schedule_id,
    occurrence.status,
    occurrence.occurrence_type,
    schedule.class_id,
    class.branch_id,
    schedule.timezone
  into
    v_source_schedule_id,
    v_source_status,
    v_source_type,
    v_class_id,
    v_branch_id,
    v_timezone
  from public.session_occurrences
    as occurrence

  join public.schedules
    as schedule
    on schedule.id =
      occurrence.schedule_id

  join public.classes
    as class
    on class.id =
      schedule.class_id

  where occurrence.id =
    p_source_occurrence_id

  for update of occurrence;


  if v_source_schedule_id is null then
    raise exception
      'Source session not found';
  end if;


  if v_source_type <> 'REGULAR' then
    raise exception
      'A makeup session must reference a regular source occurrence';
  end if;


  if v_source_status not in (
    'COMPLETED',
    'CANCELLED'
  ) then
    raise exception
      'A makeup session requires a completed or cancelled source session';
  end if;


  -- =======================================================
  -- PARTICIPANTS
  -- They only need to belong to this class.
  --
  -- Their actual entitlement will be checked atomically by
  -- trg_zz_reserve_makeup_credit_for_participant.
  -- =======================================================

  if exists (
    select 1
    from unnest(p_enrollment_ids)
      as participant(enrollment_id)

    left join public.enrollments
      as enrollment
      on enrollment.id =
        participant.enrollment_id

    where enrollment.id is null
      or enrollment.class_id
        is distinct from v_class_id
  ) then
    raise exception
      'Every makeup participant must belong to the makeup class';
  end if;


  -- =======================================================
  -- ROOM
  -- =======================================================

  if p_room_id is not null then

    select
      room.branch_id,
      room.status
    into
      v_room_branch_id,
      v_room_status
    from public.rooms as room
    where room.id = p_room_id;


    if v_room_status is distinct from 'ACTIVE' then
      raise exception
        'Room is not available';
    end if;


    if v_room_branch_id
      is distinct from v_branch_id
    then
      raise exception
        'Room must belong to the same branch as the class';
    end if;

  end if;


  v_makeup_date :=
    (p_starts_at at time zone v_timezone)::date;


  -- =======================================================
  -- CLASS CONFLICT
  -- =======================================================

  if exists (
    select 1
    from public.session_occurrences
      as other_occurrence

    join public.schedules
      as other_schedule
      on other_schedule.id =
        other_occurrence.schedule_id

    where other_occurrence.status <>
        'CANCELLED'

      and other_schedule.class_id =
        v_class_id

      and other_occurrence.starts_at <
        p_ends_at

      and other_occurrence.ends_at >
        p_starts_at
  ) then
    raise exception
      'This class already has an overlapping session';
  end if;


  -- =======================================================
  -- ROOM CONFLICT
  -- =======================================================

  if
    p_room_id is not null
    and exists (
      select 1
      from public.session_occurrences
        as other_occurrence

      where other_occurrence.status <>
          'CANCELLED'

        and other_occurrence.room_id =
          p_room_id

        and other_occurrence.starts_at <
          p_ends_at

        and other_occurrence.ends_at >
          p_starts_at
    )
  then
    raise exception
      'This room is already occupied during that time';
  end if;


  -- =======================================================
  -- TEACHER CONFLICT
  -- =======================================================

  if exists (
    select 1

    from public.class_teachers
      as current_assignment

    join public.class_teachers
      as other_assignment
      on other_assignment.teacher_id =
        current_assignment.teacher_id

      and other_assignment.class_id <>
        current_assignment.class_id

    join public.schedules
      as other_schedule
      on other_schedule.class_id =
        other_assignment.class_id

    join public.session_occurrences
      as other_occurrence
      on other_occurrence.schedule_id =
        other_schedule.id

    where current_assignment.class_id =
        v_class_id

      and current_assignment.is_active =
        true

      and current_assignment.assigned_at <=
        v_makeup_date

      and (
        current_assignment.ended_at is null
        or current_assignment.ended_at >=
          v_makeup_date
      )

      and other_assignment.is_active =
        true

      and other_assignment.assigned_at <=
        v_makeup_date

      and (
        other_assignment.ended_at is null
        or other_assignment.ended_at >=
          v_makeup_date
      )

      and other_occurrence.status <>
        'CANCELLED'

      and other_occurrence.starts_at <
        p_ends_at

      and other_occurrence.ends_at >
        p_starts_at
  ) then
    raise exception
      'A teacher assigned to this class is already teaching another class at that time';
  end if;


  -- =======================================================
  -- CREATE MAKEUP SESSION
  -- =======================================================

  insert into public.session_occurrences (
    schedule_id,
    occurrence_date,
    starts_at,
    ends_at,
    room_id,
    status,
    notes,
    occurrence_type,
    source_occurrence_id
  )
  values (
    v_source_schedule_id,
    v_makeup_date,
    p_starts_at,
    p_ends_at,
    p_room_id,
    'SCHEDULED',
    btrim(p_reason),
    'MAKEUP',
    p_source_occurrence_id
  )
  returning id into v_result;


  -- Each INSERT below triggers credit reservation.
  --
  -- If even one student has no AVAILABLE credit,
  -- PostgreSQL rolls back the whole transaction.
  insert into
    public.session_occurrence_participants (
      session_occurrence_id,
      enrollment_id
    )
  select
    v_result,
    participant.enrollment_id
  from unnest(p_enrollment_ids)
    as participant(enrollment_id);


  return v_result;
end;
$$;


ALTER FUNCTION "public"."create_makeup_session_occurrence"("p_source_occurrence_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_room_id" "uuid", "p_enrollment_ids" "uuid"[], "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_operating_expense_template"("p_branch" "uuid", "p_category" "text", "p_custom_category_name" "text", "p_name" "text", "p_vendor" "text", "p_amount_mode" "text", "p_expected_amount" numeric, "p_currency" "text", "p_effective_from" "date", "p_effective_to" "date", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  payload jsonb; prior jsonb; template_id uuid:=gen_random_uuid(); custom_name text; vendor_name text; currency_code text;
  result jsonb;
begin
  if not vibe_operating_expense_private.can_manage(p_branch) then raise exception 'OPERATING_EXPENSE_UNAUTHORIZED'; end if;
  if not exists(select 1 from public.branches where id=p_branch and status='ACTIVE') then raise exception 'OPERATING_EXPENSE_BRANCH_REQUIRED'; end if;
  if p_category is null or p_category not in (
    'RENT','ELECTRICITY','WATER','INTERNET','FIXED_PHONE','SECURITY','CLEANING','SOFTWARE','MAINTENANCE','OTHER'
  ) then raise exception 'OPERATING_EXPENSE_INVALID_CATEGORY'; end if;
  custom_name:=nullif(btrim(coalesce(p_custom_category_name,'')),'');
  if p_category='OTHER' then
    if custom_name is null or char_length(custom_name)>100 then raise exception 'OPERATING_EXPENSE_CUSTOM_CATEGORY_REQUIRED'; end if;
  elsif custom_name is not null then
    raise exception 'OPERATING_EXPENSE_CUSTOM_CATEGORY_NOT_ALLOWED';
  end if;
  if p_name is null or char_length(btrim(p_name)) not between 1 and 200 then raise exception 'OPERATING_EXPENSE_NAME_REQUIRED'; end if;
  vendor_name:=nullif(btrim(coalesce(p_vendor,'')),'');
  if vendor_name is not null and char_length(vendor_name)>200 then raise exception 'OPERATING_EXPENSE_INVALID_VENDOR'; end if;
  if p_amount_mode not in ('FIXED','VARIABLE') then raise exception 'OPERATING_EXPENSE_INVALID_AMOUNT_MODE'; end if;
  currency_code:=upper(coalesce(p_currency,'VND'));
  if currency_code !~ '^[A-Z]{3}$' then raise exception 'OPERATING_EXPENSE_INVALID_CURRENCY'; end if;
  if p_expected_amount is not null and currency_code='VND' and p_expected_amount<>trunc(p_expected_amount) then
    raise exception 'OPERATING_EXPENSE_VND_REQUIRES_WHOLE_DONG';
  end if;
  if p_amount_mode='FIXED' then
    if not vibe_operating_expense_private.money_ok(p_expected_amount,currency_code,true) then raise exception 'OPERATING_EXPENSE_FIXED_AMOUNT_REQUIRED'; end if;
  elsif p_expected_amount is not null and not vibe_operating_expense_private.money_ok(p_expected_amount,currency_code,true) then
    raise exception 'OPERATING_EXPENSE_INVALID_AMOUNT';
  end if;
  if p_effective_from is null or not isfinite(p_effective_from) then raise exception 'OPERATING_EXPENSE_EFFECTIVE_FROM_REQUIRED'; end if;
  if p_effective_to is not null and (not isfinite(p_effective_to) or p_effective_to<p_effective_from) then raise exception 'OPERATING_EXPENSE_INVALID_EFFECTIVE_TO'; end if;

  payload:=jsonb_build_object(
    'operation','TEMPLATE_CREATED','branch_id',p_branch,'category',p_category,'custom_category_name',custom_name,
    'name',btrim(p_name),'vendor',vendor_name,'amount_mode',p_amount_mode,'expected_amount',p_expected_amount,
    'currency',currency_code,'effective_from',p_effective_from,'effective_to',p_effective_to
  );
  prior:=vibe_operating_expense_private.replay(p_key,payload);
  if prior is not null then return prior; end if;

  insert into public.operating_expense_templates(
    id,branch_id,category,custom_category_name,name,vendor,amount_mode,expected_amount,currency,effective_from,effective_to,created_by
  ) values(
    template_id,p_branch,p_category,custom_name,btrim(p_name),vendor_name,p_amount_mode,p_expected_amount,currency_code,
    p_effective_from,p_effective_to,auth.uid()
  );
  result:=jsonb_build_object('template_id',template_id,'status','ACTIVE');
  return vibe_operating_expense_private.write_event(template_id,null,'TEMPLATE_CREATED',p_key,payload,null,to_jsonb((select t from public.operating_expense_templates t where t.id=template_id)),result);
end;
$_$;


ALTER FUNCTION "public"."create_operating_expense_template"("p_branch" "uuid", "p_category" "text", "p_custom_category_name" "text", "p_name" "text", "p_vendor" "text", "p_amount_mode" "text", "p_expected_amount" numeric, "p_currency" "text", "p_effective_from" "date", "p_effective_to" "date", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_payment"("p_student_id" "uuid", "p_branch_id" "uuid", "p_amount" numeric, "p_currency" "text", "p_payment_method" "text", "p_paid_at" timestamp with time zone DEFAULT "now"(), "p_reference" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_branch public.branches%rowtype;
  v_payment_id uuid := gen_random_uuid();
  v_payment_number text;
  v_currency text;
  v_method text;
begin
  v_method := upper(btrim(coalesce(p_payment_method, '')));
  if not (
    (v_method = 'CASH' and coalesce(public.has_permission('finance.cash.record', p_branch_id), false))
    or (v_method <> 'CASH' and coalesce(public.has_permission('finance.payment.record', p_branch_id), false))
  ) then
    raise exception 'SUPER_ADMIN role required' using errcode = 'P0001';
  end if;
  if v_method = 'CASH'
    and coalesce(current_setting('vibe.cash_acknowledged', true), '') is distinct from 'yes'
    and not coalesce(public.has_role('SUPER_ADMIN'), false) then
    raise exception 'Cash receipt requires physical receipt acknowledgement' using errcode = 'P0001';
  end if;
  if p_student_id is null then raise exception 'Student id is required' using errcode = 'P0001'; end if;
  if not exists (select 1 from public.students where id = p_student_id) then
    raise exception 'Student not found' using errcode = 'P0001';
  end if;
  if p_branch_id is null then raise exception 'Branch id is required' using errcode = 'P0001'; end if;
  select * into v_branch from public.branches where id = p_branch_id;
  if not found then raise exception 'Branch not found' using errcode = 'P0001'; end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'Payment amount must be greater than zero' using errcode = 'P0001';
  end if;
  v_currency := upper(btrim(coalesce(p_currency, '')));
  if v_currency !~ '^[A-Z]{3}$' then
    raise exception 'Payment currency must be a three-letter ISO code' using errcode = 'P0001';
  end if;
  if v_method not in ('CASH', 'BANK_TRANSFER', 'CARD', 'OTHER') then
    raise exception 'Invalid payment method' using errcode = 'P0001';
  end if;
  if p_paid_at is null then raise exception 'Payment date is required' using errcode = 'P0001'; end if;
  v_payment_number := 'PAY-' || to_char(timezone('Asia/Ho_Chi_Minh', now()), 'YYYY') || '-' || lpad(nextval('public.payment_number_seq')::text, 6, '0');
  insert into public.payments (
    id, payment_number, student_id_snapshot, branch_id_snapshot, branch_code_snapshot, branch_name_snapshot,
    amount, currency, payment_method, paid_at, reference, notes, status
  ) values (
    v_payment_id, v_payment_number, p_student_id, p_branch_id, v_branch.code, v_branch.name,
    p_amount, v_currency, v_method, p_paid_at,
    nullif(btrim(coalesce(p_reference, '')), ''),
    nullif(btrim(coalesce(p_notes, '')), ''),
    'POSTED'
  );
  return v_payment_id;
end
$_$;


ALTER FUNCTION "public"."create_payment"("p_student_id" "uuid", "p_branch_id" "uuid", "p_amount" numeric, "p_currency" "text", "p_payment_method" "text", "p_paid_at" timestamp with time zone, "p_reference" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_payment_once"("p_idempotency_key" "uuid", "p_student_id" "uuid", "p_branch_id" "uuid", "p_amount" numeric, "p_currency" "text", "p_payment_method" "text", "p_paid_at" timestamp with time zone, "p_reference" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_cash_acknowledged" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  request public.payment_entry_requests;
  payload jsonb;
  payment uuid;
  method text := upper(trim(p_payment_method));
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = 'P0001';
  end if;
  if p_idempotency_key is null then
    raise exception 'Payment request key required' using errcode = 'P0001';
  end if;
  if method in ('PAYOS', 'MOMO') then
    raise exception 'Manual transfer verification is not allowed' using errcode = 'P0001';
  elsif method = 'CASH' then
    if p_cash_acknowledged is not true then
      raise exception 'Cash receipt requires physical receipt acknowledgement' using errcode = 'P0001';
    end if;
    if not coalesce(public.has_permission('finance.cash.record', p_branch_id), false) then
      raise exception 'Cash receipt permission required' using errcode = 'P0001';
    end if;
  elsif not coalesce(public.has_permission('finance.payment.record', p_branch_id), false) then
    raise exception 'Payment recording permission required' using errcode = 'P0001';
  end if;
  payload := jsonb_build_object(
    'student', p_student_id,
    'branch', p_branch_id,
    'amount', p_amount,
    'currency', upper(trim(p_currency)),
    'method', method,
    'paid_at', extract(epoch from p_paid_at),
    'reference', nullif(trim(p_reference), ''),
    'notes', nullif(trim(p_notes), ''),
    'cash_acknowledged', p_cash_acknowledged
  );
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text, 0));
  select * into request from public.payment_entry_requests where request_id = p_idempotency_key;
  if found then
    if request.created_by is distinct from auth.uid() or request.payload is distinct from payload then
      raise exception 'Payment request key reused with different input' using errcode = 'P0001';
    end if;
    return request.payment_id;
  end if;
  if method = 'CASH' then
    perform set_config('vibe.cash_acknowledged', 'yes', true);
  end if;
  payment := public.create_payment(p_student_id, p_branch_id, p_amount, p_currency, method, p_paid_at, p_reference, p_notes);
  insert into public.payment_entry_requests(request_id, created_by, payload, payment_id)
  values (p_idempotency_key, auth.uid(), payload, payment);
  return payment;
end
$$;


ALTER FUNCTION "public"."create_payment_once"("p_idempotency_key" "uuid", "p_student_id" "uuid", "p_branch_id" "uuid", "p_amount" numeric, "p_currency" "text", "p_payment_method" "text", "p_paid_at" timestamp with time zone, "p_reference" "text", "p_notes" "text", "p_cash_acknowledged" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_payroll_period"("p_branch" "uuid", "p_month" "date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  result uuid;
  existing_status text;
begin
  if not coalesce(
    public.has_role('SUPER_ADMIN'),
    false
  ) then
    raise exception 'Unauthorized';
  end if;

  if p_branch is null
     or p_month is null
     or not isfinite(p_month)
     or extract(day from p_month) <> 1
  then
    raise exception
      'PAYROLL_PERIOD_INVALID_INPUT';
  end if;

  /*
   * Resolve an existing authoritative period first.
   */
  select
    p.id,
    p.status
  into
    result,
    existing_status
  from public.payroll_periods p
  where p.branch_id = p_branch
    and p.starts_on = p_month
  for update;

  if found then
    if existing_status in (
      'APPROVED',
      'FINALIZED'
    ) then
      raise exception
        'PAYROLL_PERIOD_ALREADY_CLOSED';
    end if;

    /*
     * DRAFT / GENERATED / REVIEW:
     * resume the existing working period.
     */
    return result;
  end if;

  /*
   * No existing period: create one.
   */
  insert into public.payroll_periods (
    branch_id,
    starts_on,
    ends_on
  )
  values (
    p_branch,
    p_month,
    (
      p_month +
      interval '1 month - 1 day'
    )::date
  )
  on conflict (
    branch_id,
    starts_on
  )
  do nothing
  returning id
  into result;

  /*
   * Concurrency protection:
   * another request may have created it
   * between SELECT and INSERT.
   */
  if result is null then
    select
      p.id,
      p.status
    into
      result,
      existing_status
    from public.payroll_periods p
    where p.branch_id = p_branch
      and p.starts_on = p_month
    for update;

    if result is null then
      raise exception
        'PAYROLL_PERIOD_CREATE_RACE_RELOAD';
    end if;

    if existing_status in (
      'APPROVED',
      'FINALIZED'
    ) then
      raise exception
        'PAYROLL_PERIOD_ALREADY_CLOSED';
    end if;
  end if;

  return result;
end;
$$;


ALTER FUNCTION "public"."create_payroll_period"("p_branch" "uuid", "p_month" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_payroll_period"("p_branch" "uuid", "p_month" "date") IS 'Creates one payroll period per branch/month. Existing working periods are resumed; APPROVED/FINALIZED periods are immutable and rejected.';



CREATE OR REPLACE FUNCTION "public"."create_payroll_retroactive_claim"("p_source_period" "uuid", "p_employee" "uuid", "p_amount" numeric, "p_currency" "text", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $_$
declare
  source_row public.payroll_periods%rowtype;
  claim_id uuid;
  snapshot jsonb;
begin
  if auth.uid() is null
     or not coalesce(public.account_is_active(), false)
  then
    raise exception 'RETROACTIVE_UNAUTHORIZED';
  end if;

  select p.*
  into source_row
  from public.payroll_periods p
  where p.id = p_source_period
    and public.has_permission(
      'payroll.prepare',
      p.branch_id
    )
    and (
      public.is_global_super_admin()
      or public.has_role_permission(
        'FINANCE',
        'payroll.prepare',
        p.branch_id
      )
    )
  for update;

  if not found then
    raise exception 'RETROACTIVE_UNAUTHORIZED';
  end if;

  if source_row.status
     not in ('APPROVED','FINALIZED')
  then
    raise exception
      'RETROACTIVE_SOURCE_MUST_BE_CLOSED';
  end if;

  if not exists (
    select 1
    from public.employees e
    where e.id = p_employee
  ) then
    raise exception
      'RETROACTIVE_EMPLOYEE_NOT_FOUND';
  end if;

  if exists (
    select 1
    from public.teacher_payrolls t
    where t.period_id = source_row.id
      and t.employee_id = p_employee
  ) then
    raise exception
      'RETROACTIVE_SOURCE_PAYROLL_ALREADY_EXISTS';
  end if;

  if not exists (
    select 1
    from public.staff_compensation_components s
    where s.employee_id = p_employee
      and s.branch_id = source_row.branch_id
      and s.status = 'ACTIVE'
      and s.effective_from <= source_row.ends_on
      and (
        s.effective_to is null
        or s.effective_to >= source_row.starts_on
      )
  ) then
    raise exception
      'RETROACTIVE_SOURCE_COMPENSATION_REQUIRED';
  end if;

  if p_amount is null
     or p_amount <= 0
     or p_amount > 999999999999.99
     or p_amount <> round(p_amount, 2)
     or p_amount = 'NaN'::numeric
  then
    raise exception
      'RETROACTIVE_INVALID_AMOUNT';
  end if;

  if p_currency is null
     or upper(btrim(p_currency))
        !~ '^[A-Z]{3}$'
  then
    raise exception
      'RETROACTIVE_INVALID_CURRENCY';
  end if;

  if p_reason is null
     or char_length(btrim(p_reason))
        not between 1 and 2000
  then
    raise exception
      'RETROACTIVE_REASON_REQUIRED';
  end if;

  if exists (
    select 1
    from public.payroll_retroactive_claims r
    where r.source_period_id = source_row.id
      and r.employee_id = p_employee
      and r.status <> 'CANCELLED'
  ) then
    raise exception
      'RETROACTIVE_ALREADY_EXISTS';
  end if;

  select jsonb_build_object(
    'integration_version',
      'RETROACTIVE_PAY_V1',

    'source_period',
      to_jsonb(source_row),

    'employee',
      (
        select jsonb_build_object(
          'id', e.id,
          'employee_code', e.employee_code,
          'name',
            (
              select v.full_name
              from public.employee_versions v
              where v.employee_id = e.id
                and v.effective_on
                    <= source_row.ends_on
              order by
                v.effective_on desc,
                v.version desc
              limit 1
            )
        )
        from public.employees e
        where e.id = p_employee
      ),

    'compensation',
      coalesce(
        (
          select jsonb_agg(
            to_jsonb(s)
            order by
              s.component_code,
              s.effective_from,
              s.id
          )
          from public.staff_compensation_components s
          where s.employee_id = p_employee
            and s.branch_id = source_row.branch_id
            and s.status = 'ACTIVE'
            and s.effective_from
                <= source_row.ends_on
            and (
              s.effective_to is null
              or s.effective_to
                 >= source_row.starts_on
            )
        ),
        '[]'::jsonb
      )
  )
  into snapshot;

  insert into public.payroll_retroactive_claims(
    source_period_id,
    employee_id,
    branch_id,
    amount,
    currency,
    reason,
    source_snapshot,
    created_by
  )
  values(
    source_row.id,
    p_employee,
    source_row.branch_id,
    p_amount,
    upper(btrim(p_currency)),
    btrim(p_reason),
    snapshot,
    auth.uid()
  )
  returning id into claim_id;

  return claim_id;
end;
$_$;


