CREATE OR REPLACE FUNCTION "public"."create_registration_application"("p_request" "uuid", "p_branch" "uuid", "p_lead" "uuid", "p_student_name" "text", "p_student_date_of_birth" "date", "p_parent_name" "text", "p_parent_phone" "text", "p_program" "text", "p_instrument" "text", "p_desired_start" "date", "p_preferred_schedule" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor uuid := auth.uid();
  lead public.crm_leads%rowtype;
  code text;
begin
  if actor is null or not public.registration_can('registration.create', p_branch) then
    raise exception 'REGISTRATION_UNAUTHORIZED';
  end if;
  if p_request is null then raise exception 'REGISTRATION_INVALID'; end if;
  if exists(select 1 from public.registration_application_events where id = p_request) then
    return (select application_id from public.registration_application_events where id = p_request);
  end if;
  if p_lead is not null then
    select * into lead from public.crm_leads where id = p_lead;
    if not found or lead.branch_id <> p_branch or lead.status <> 'WON' then
      raise exception 'REGISTRATION_LEAD_DENIED';
    end if;
  end if;
  code := 'DK-' || to_char(public.registration_vietnam_today(), 'YYYYMMDD') || '-' || upper(substr(replace(p_request::text, '-', ''), 21, 12));
  perform set_config('registration.write', 'on', true);
  insert into public.registration_applications(
    id, application_code, crm_lead_id, branch_id, student_name, student_date_of_birth,
    parent_name, parent_phone, program_interest, instrument_interest, desired_start_date,
    preferred_schedule, created_by
  ) values (
    p_request, code, p_lead, p_branch,
    nullif(btrim(coalesce(p_student_name, case when p_lead is not null then lead.student_name end, case when p_lead is not null then lead.full_name end, '')), ''),
    coalesce(p_student_date_of_birth, case when p_lead is not null then lead.student_date_of_birth end),
    nullif(btrim(coalesce(p_parent_name, case when p_lead is not null then lead.parent_name end, case when p_lead is not null then lead.full_name end, '')), ''),
    nullif(btrim(coalesce(p_parent_phone, case when p_lead is not null then lead.phone end, '')), ''),
    nullif(btrim(coalesce(p_program, case when p_lead is not null then lead.program_interest end, '')), ''),
    nullif(btrim(coalesce(p_instrument, case when p_lead is not null then lead.instrument_interest end, '')), ''),
    p_desired_start,
    nullif(btrim(coalesce(p_preferred_schedule, '')), ''),
    actor
  );
  insert into public.registration_application_events(id, application_id, event_type, to_status, actor_id)
  values (p_request, p_request, 'CREATED', 'DRAFT', actor);
  perform set_config('registration.write', 'off', true);
  return p_request;
end $$;


ALTER FUNCTION "public"."create_registration_application"("p_request" "uuid", "p_branch" "uuid", "p_lead" "uuid", "p_student_name" "text", "p_student_date_of_birth" "date", "p_parent_name" "text", "p_parent_phone" "text", "p_program" "text", "p_instrument" "text", "p_desired_start" "date", "p_preferred_schedule" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_registration_application_with_academics"("p_request" "uuid", "p_branch" "uuid", "p_lead" "uuid", "p_student_name" "text", "p_student_date_of_birth" "date", "p_parent_name" "text", "p_parent_phone" "text", "p_curriculum" "uuid", "p_level" "uuid", "p_subject" "uuid", "p_desired_start" "date", "p_preferred_schedule" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid;
  v_program text;
  v_subject text;
begin
  if auth.uid() is null or not public.registration_can('registration.create', p_branch) then
    raise exception 'REGISTRATION_UNAUTHORIZED';
  end if;
  if p_curriculum is null or p_level is null
     or not exists (select 1 from public.curriculums where id = p_curriculum and status = 'ACTIVE')
     or not exists (select 1 from public.curriculum_levels where id = p_level and curriculum_id = p_curriculum and status = 'ACTIVE')
     or (p_subject is not null and not exists (
       select 1 from public.curriculum_subjects where id = p_subject and level_id = p_level and status = 'ACTIVE'
     )) then
    raise exception 'REGISTRATION_ACADEMIC_SELECTION_INVALID';
  end if;
  select name into v_program from public.curriculums where id = p_curriculum;
  select name into v_subject from public.curriculum_subjects where id = p_subject;
  v_id := public.create_registration_application(
    p_request, p_branch, p_lead, p_student_name, p_student_date_of_birth,
    p_parent_name, p_parent_phone, v_program, v_subject, p_desired_start, p_preferred_schedule
  );
  if not exists(select 1 from public.registration_applications where id = v_id and branch_id = p_branch and created_by = auth.uid()) then
    raise exception 'REGISTRATION_REQUEST_CONFLICT';
  end if;
  if exists(select 1 from public.registration_applications where id = v_id and curriculum_id is null) then
    perform set_config('registration.write', 'on', true);
    update public.registration_applications set curriculum_id = p_curriculum,
      level_id = p_level, subject_id = p_subject where id = v_id;
    perform set_config('registration.write', 'off', true);
  elsif not exists(select 1 from public.registration_applications where id = v_id
    and curriculum_id = p_curriculum and level_id = p_level and subject_id is not distinct from p_subject) then
    raise exception 'REGISTRATION_REQUEST_CONFLICT';
  end if;
  return v_id;
end $$;


ALTER FUNCTION "public"."create_registration_application_with_academics"("p_request" "uuid", "p_branch" "uuid", "p_lead" "uuid", "p_student_name" "text", "p_student_date_of_birth" "date", "p_parent_name" "text", "p_parent_phone" "text", "p_curriculum" "uuid", "p_level" "uuid", "p_subject" "uuid", "p_desired_start" "date", "p_preferred_schedule" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_registration_with_zalo_consent"("p_request" "uuid", "p_branch" "uuid", "p_lead" "uuid", "p_student_name" "text", "p_student_date_of_birth" "date", "p_parent_name" "text", "p_parent_phone" "text", "p_curriculum" "uuid", "p_level" "uuid", "p_subject" "uuid", "p_desired_start" "date", "p_preferred_schedule" "text", "p_consent" boolean, "p_consent_method" "text", "p_over_18" boolean DEFAULT false, "p_zalo_phone" "text" DEFAULT NULL::"text", "p_home_address" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  app_id uuid;
  prepared jsonb;
begin
  if p_request is null then raise exception 'REGISTRATION_INVALID'; end if;
  perform pg_advisory_xact_lock(hashtextextended('registration-intake:' || p_request::text, 0));
  if exists(select 1 from public.registration_application_events where id = p_request) then
    return (select application_id from public.registration_application_events where id = p_request);
  end if;
  prepared := public.registration_prepare_intake(
    p_student_date_of_birth, p_over_18, p_parent_name, p_parent_phone,
    p_zalo_phone, p_home_address, p_consent, p_consent_method
  );
  app_id := public.create_registration_application_with_academics(
    p_request, p_branch, p_lead, p_student_name, p_student_date_of_birth,
    prepared->>'parent_name', prepared->>'parent_phone', p_curriculum, p_level, p_subject,
    p_desired_start, p_preferred_schedule
  );
  perform set_config('registration.write', 'on', true);
  update public.registration_applications set
    student_over_18 = coalesce(p_over_18, false),
    zalo_phone = prepared->>'zalo',
    home_address = prepared->>'address'
  where id = app_id;
  perform set_config('registration.write', 'off', true);
  if p_consent is true then
    perform public.update_registration_zalo_consent(app_id, null, 'RECORD', prepared->>'zalo', true, p_consent_method, 'REGISTRATION_FORM');
  end if;
  return app_id;
end $$;


ALTER FUNCTION "public"."create_registration_with_zalo_consent"("p_request" "uuid", "p_branch" "uuid", "p_lead" "uuid", "p_student_name" "text", "p_student_date_of_birth" "date", "p_parent_name" "text", "p_parent_phone" "text", "p_curriculum" "uuid", "p_level" "uuid", "p_subject" "uuid", "p_desired_start" "date", "p_preferred_schedule" "text", "p_consent" boolean, "p_consent_method" "text", "p_over_18" boolean, "p_zalo_phone" "text", "p_home_address" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_tuition_invoice"("p_enrollment_tuition_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_tuition public.enrollment_tuition%rowtype;

  v_student_id uuid;

  v_invoice_id uuid :=
    gen_random_uuid();

  v_invoice_number text;
begin
  if not public.has_role(
    'SUPER_ADMIN'
  ) then
    raise exception
      'SUPER_ADMIN role required';
  end if;


  if p_enrollment_tuition_id is null then
    raise exception
      'Enrollment tuition id is required';
  end if;


  select *
  into v_tuition
  from public.enrollment_tuition
  where id =
    p_enrollment_tuition_id
  for update;


  if not found then
    raise exception
      'Enrollment tuition term not found';
  end if;


  if v_tuition.status =
    'CANCELLED'
  then
    raise exception
      'Cannot create an invoice from a cancelled tuition term';
  end if;


  if exists (
    select 1
    from public.invoices
    where enrollment_tuition_id =
      p_enrollment_tuition_id
  ) then
    raise exception
      'An invoice already exists for this tuition term';
  end if;


  select enrollment.student_id
  into v_student_id
  from public.enrollments
    as enrollment
  where enrollment.id =
    v_tuition.enrollment_id;


  if not found then
    raise exception
      'Enrollment not found';
  end if;


  v_invoice_number :=
    'INV-'
    || to_char(
      current_date,
      'YYYY'
    )
    || '-'
    || lpad(
      nextval(
        'public.invoice_number_seq'
      )::text,
      6,
      '0'
    );


  insert into public.invoices (
    id,
    invoice_number,
    enrollment_tuition_id,
    enrollment_id_snapshot,
    student_id_snapshot,
    branch_id_snapshot,
    branch_code_snapshot,
    branch_name_snapshot,
    currency,
    subtotal,
    total_amount,
    status,
    notes
  )
  values (
    v_invoice_id,
    v_invoice_number,
    v_tuition.id,
    v_tuition.enrollment_id,
    v_student_id,
    v_tuition.branch_id_snapshot,
    v_tuition.branch_code_snapshot,
    v_tuition.branch_name_snapshot,
    v_tuition.currency,
    v_tuition.amount,
    v_tuition.amount,
    'DRAFT',
    nullif(
      btrim(
        coalesce(
          p_notes,
          ''
        )
      ),
      ''
    )
  );


  insert into public.invoice_items (
    invoice_id,
    line_no,
    item_type,
    description,
    quantity,
    unit_amount,
    line_total
  )
  values (
    v_invoice_id,
    1,
    'TUITION',
    v_tuition.plan_name_snapshot,
    1,
    v_tuition.amount,
    v_tuition.amount
  );


  return v_invoice_id;
end;
$$;


ALTER FUNCTION "public"."create_tuition_invoice"("p_enrollment_tuition_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_tuition_term"("p_enrollment_id" "uuid", "p_tuition_plan_id" "uuid", "p_starts_on" "date", "p_discount_type" "text", "p_discount_value" numeric, "p_discount_name" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare quote jsonb; result uuid;
begin
  if not coalesce(public.has_role('SUPER_ADMIN'),false) then raise exception 'SUPER_ADMIN role required'; end if;
  -- Serialize creations per enrollment; final insert still passes all existing triggers.
  perform 1 from enrollments where id=p_enrollment_id for update;
  quote := preview_tuition_term(p_enrollment_id,p_tuition_plan_id,p_starts_on,p_discount_type,p_discount_value,p_discount_name);
  if length(p_notes)>2000 then raise exception 'Notes too long'; end if;
  insert into enrollment_tuition(enrollment_id,tuition_plan_id,starts_on,status,discount_type,discount_value,discount_name,notes)
  values(p_enrollment_id,p_tuition_plan_id,(quote->>'starts_on')::date,
    case when (quote->>'starts_on')::date>(now() at time zone 'Asia/Ho_Chi_Minh')::date then 'SCHEDULED' else 'ACTIVE' end,
    p_discount_type,p_discount_value,p_discount_name,p_notes) returning id into result;
  return result;
end $$;


ALTER FUNCTION "public"."create_tuition_term"("p_enrollment_id" "uuid", "p_tuition_plan_id" "uuid", "p_starts_on" "date", "p_discount_type" "text", "p_discount_value" numeric, "p_discount_name" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_activity_funnel"("p_from" "date", "p_to" "date", "p_branch" "uuid", "p_campaign" "uuid", "p_source" "text", "p_owner" "uuid", "p_program" "text") RETURNS TABLE("metric" "text", "value" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or not public.account_is_active() or p_from is null or p_to is null or p_to < p_from then
    raise exception 'CRM_REPORT_UNAUTHORIZED';
  end if;
  return query
  with hits as (
    select event.event_type
    from public.crm_lead_events event
    join public.crm_leads lead on lead.id = event.lead_id
    where (event.created_at at time zone 'Asia/Ho_Chi_Minh')::date between p_from and p_to
      and public.crm_can('crm.view', lead.branch_id)
      and (p_branch is null or lead.branch_id = p_branch)
      and (p_campaign is null or lead.campaign_id = p_campaign)
      and (p_source is null or lead.source_type = p_source)
      and (p_owner is null or lead.owner_user_id = p_owner)
      and (p_program is null or lead.program_interest = p_program)
      and event.event_type in ('CONTACTED', 'QUALIFIED', 'TRIAL_BOOKED', 'TRIAL_COMPLETED', 'PROPOSAL_SENT', 'NEGOTIATION_UPDATED', 'WON', 'LOST')
  )
  select * from (values
    ('contacted', (select count(*)::numeric from hits where event_type = 'CONTACTED')),
    ('qualified', (select count(*)::numeric from hits where event_type = 'QUALIFIED')),
    ('trial_booked', (select count(*)::numeric from hits where event_type = 'TRIAL_BOOKED')),
    ('trial_completed', (select count(*)::numeric from hits where event_type = 'TRIAL_COMPLETED')),
    ('proposal', (select count(*)::numeric from hits where event_type = 'PROPOSAL_SENT')),
    ('negotiating', (select count(*)::numeric from hits where event_type = 'NEGOTIATION_UPDATED')),
    ('won', (select count(*)::numeric from hits where event_type = 'WON')),
    ('lost', (select count(*)::numeric from hits where event_type = 'LOST'))
  ) metrics(metric, value);
end $$;


ALTER FUNCTION "public"."crm_activity_funnel"("p_from" "date", "p_to" "date", "p_branch" "uuid", "p_campaign" "uuid", "p_source" "text", "p_owner" "uuid", "p_program" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_actor"("p_permission" "text", "p_branch" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor uuid := auth.uid();
begin
  if actor is null
     or not coalesce(public.account_is_active(), false)
     or not coalesce(public.crm_can(p_permission, p_branch), false)
  then
    raise exception 'CRM_LEAD_UNAUTHORIZED';
  end if;
  return actor;
end $$;


ALTER FUNCTION "public"."crm_actor"("p_permission" "text", "p_branch" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_business_snapshot"("p_branch" "uuid") RETURNS TABLE("metric" "text", "value" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
  month_start date := date_trunc('month', now() at time zone 'Asia/Ho_Chi_Minh')::date;
begin
  if auth.uid() is null or not public.account_is_active() then
    raise exception 'CRM_REPORT_UNAUTHORIZED';
  end if;
  return query
  with leads as (
    select lead.id, lead.status, lead.created_at, lead.next_follow_up_on, lead.campaign_id
    from public.crm_leads lead
    where public.crm_can('crm.view', lead.branch_id)
      and (p_branch is null or lead.branch_id = p_branch)
  ), month_cohort as (
    select leads.id,
      coalesce(max(case event.to_status when 'WON' then 8 else null end), 1) as reached
    from leads
    left join public.crm_lead_events event on event.lead_id = leads.id
    where (leads.created_at at time zone 'Asia/Ho_Chi_Minh')::date >= month_start
    group by leads.id
  ), cases as (
    select item.id, item.status, item.opened_at, item.returned_at
    from public.crm_reactivation_cases item
    where public.crm_can('crm.reactivation.view', item.branch_id)
      and (p_branch is null or item.branch_id = p_branch)
  ), sales as (
    select sale.movement_id, sale.warranty_until
    from public.instrument_events sale
    where sale.kind = 'SALE'
      and public.crm_can('instrument_customer.view', sale.branch_id)
      and (p_branch is null or sale.branch_id = p_branch)
  )
  select * from (values
    ('leads_created_month', (select count(*)::numeric from month_cohort)),
    ('uncontacted', (select count(*)::numeric from leads where status = 'NEW')),
    ('follow_up_today', (select count(*)::numeric from leads where next_follow_up_on = today and status not in ('WON', 'LOST'))),
    ('follow_up_overdue', (select count(*)::numeric from leads where next_follow_up_on < today and status not in ('WON', 'LOST'))),
    ('qualified_now', (select count(*)::numeric from leads where status = 'QUALIFIED')),
    ('negotiating_now', (select count(*)::numeric from leads where status = 'NEGOTIATING')),
    ('trial_today', (select count(*)::numeric from leads where status = 'TRIAL_BOOKED' and next_follow_up_on = today)),
    ('won_cohort_month', (select count(*)::numeric from month_cohort where reached >= 8)),
    ('reactivation_open', (select count(*)::numeric from cases where status not in ('RETURNED', 'NOT_INTERESTED', 'LOST'))),
    ('reactivation_need_contact', (select count(*)::numeric from cases where status = 'NEW_REACTIVATION')),
    ('reactivation_interested', (select count(*)::numeric from cases where status = 'INTERESTED')),
    ('reactivation_returned_month', (select count(*)::numeric from cases where returned_at is not null and (returned_at at time zone 'Asia/Ho_Chi_Minh')::date >= month_start)),
    ('reactivation_opened_month', (select count(*)::numeric from cases where (opened_at at time zone 'Asia/Ho_Chi_Minh')::date >= month_start)),
    ('warranty_active', (select count(*)::numeric from sales where warranty_until >= today)),
    ('warranty_expiring', (select count(*)::numeric from sales where warranty_until between today and today + 30)),
    ('warranty_open', (
      select count(*)::numeric from public.instrument_warranty_cases item
      join sales on sales.movement_id = item.sale_event_id
      where item.status in ('OPEN', 'INSPECTING', 'WAITING_PART', 'IN_REPAIR')
    )),
    ('after_sales_follow_up', (
      select count(*)::numeric from sales
      join lateral (
        select followup.next_follow_up_on, followup.outcome
        from public.instrument_customer_followups followup
        where followup.sale_event_id = sales.movement_id
        order by followup.created_at desc
        limit 1
      ) latest on true
      where latest.next_follow_up_on is not null and latest.next_follow_up_on <= today
    )),
    ('upgrade_opportunities', (
      select count(*)::numeric from sales
      where exists (
        select 1 from public.instrument_customer_followups followup
        where followup.sale_event_id = sales.movement_id and followup.outcome = 'UPGRADE_OPPORTUNITY'
      )
    )),
    ('repurchased', (
      select count(*)::numeric from sales
      where exists (
        select 1 from public.instrument_customer_followups followup
        where followup.sale_event_id = sales.movement_id and followup.outcome = 'REPURCHASED'
      )
    )),
    ('campaigns_active', (
      select count(*)::numeric from public.crm_campaigns campaign
      where campaign.status = 'ACTIVE'
        and (p_branch is null or campaign.branch_id is null or campaign.branch_id = p_branch)
        and (campaign.branch_id is null and public.has_role('SUPER_ADMIN') or campaign.branch_id is not null and public.crm_can('crm.campaign.view', campaign.branch_id))
    ))
  ) metrics(metric, value);
end $$;


ALTER FUNCTION "public"."crm_business_snapshot"("p_branch" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_campaign_summary"() RETURNS TABLE("campaign_id" "uuid", "leads" bigint, "qualified" bigint, "won" bigint, "lost" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with visible as (
    select lead.campaign_id,
      coalesce(max(case event.to_status
        when 'QUALIFIED' then 3 when 'TRIAL_BOOKED' then 4 when 'TRIAL_COMPLETED' then 5
        when 'PROPOSAL_SENT' then 6 when 'NEGOTIATING' then 7 when 'WON' then 8 else null end), 1) as reached,
      bool_or(event.to_status = 'LOST') as lost
    from public.crm_leads lead
    left join public.crm_lead_events event on event.lead_id = lead.id
    where lead.campaign_id is not null
      and public.crm_can('crm.campaign.view', lead.branch_id)
    group by lead.id, lead.campaign_id
  )
  select visible.campaign_id, count(*)::bigint,
    count(*) filter (where visible.reached >= 3)::bigint,
    count(*) filter (where visible.reached >= 8)::bigint,
    count(*) filter (where visible.lost)::bigint
  from visible
  group by visible.campaign_id
$$;


ALTER FUNCTION "public"."crm_campaign_summary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_can"("p_permission" "text", "p_branch" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select public.account_is_active()
    and p_branch is not null
    and exists(select 1 from public.branches where id = p_branch)
    and (
      public.has_role('SUPER_ADMIN')
      or exists (
        select 1
        from public.user_roles ur
        join public.roles r on r.id = ur.role_id
        join public.role_permissions rp on rp.role_id = r.id
        join public.permissions p on p.id = rp.permission_id
        where ur.user_id = auth.uid()
          and r.code <> 'SUPER_ADMIN'
          and ur.branch_id = p_branch
          and ur.is_active
          and (ur.valid_from is null or ur.valid_from <= now())
          and (ur.valid_until is null or ur.valid_until > now())
          and p.code = p_permission
      )
    )
$$;


ALTER FUNCTION "public"."crm_can"("p_permission" "text", "p_branch" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_channel"("p_channel" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  cleaned text := nullif(upper(btrim(coalesce(p_channel, ''))), '');
begin
  if cleaned is not null and cleaned not in ('PHONE', 'ZALO', 'SMS', 'EMAIL', 'IN_PERSON', 'OTHER') then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  return cleaned;
end $$;


ALTER FUNCTION "public"."crm_channel"("p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_cohort_funnel"("p_from" "date", "p_to" "date", "p_branch" "uuid", "p_campaign" "uuid", "p_source" "text", "p_owner" "uuid", "p_program" "text") RETURNS TABLE("metric" "text", "value" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or not public.account_is_active() or p_from is null or p_to is null or p_to < p_from then
    raise exception 'CRM_REPORT_UNAUTHORIZED';
  end if;
  return query
  with visible as (
    select lead.id, lead.created_at, lead.first_contact_at
    from public.crm_leads lead
    where (lead.created_at at time zone 'Asia/Ho_Chi_Minh')::date between p_from and p_to
      and public.crm_can('crm.view', lead.branch_id)
      and (p_branch is null or lead.branch_id = p_branch)
      and (p_campaign is null or lead.campaign_id = p_campaign)
      and (p_source is null or lead.source_type = p_source)
      and (p_owner is null or lead.owner_user_id = p_owner)
      and (p_program is null or lead.program_interest = p_program)
  ), ranked as (
    select visible.id, visible.created_at, visible.first_contact_at,
      coalesce(max(case event.to_status
        when 'CONTACTED' then 2 when 'QUALIFIED' then 3 when 'TRIAL_BOOKED' then 4
        when 'TRIAL_COMPLETED' then 5 when 'PROPOSAL_SENT' then 6 when 'NEGOTIATING' then 7
        when 'WON' then 8 else null end), 1) as reached,
      bool_or(event.to_status = 'LOST') as lost,
      min(event.created_at) filter (where event.to_status = 'WON') as won_at
    from visible
    left join public.crm_lead_events event on event.lead_id = visible.id
    group by visible.id, visible.created_at, visible.first_contact_at
  )
  select * from (values
    ('new', (select count(*)::numeric from ranked)),
    ('contacted', (select count(*)::numeric from ranked where reached >= 2)),
    ('qualified', (select count(*)::numeric from ranked where reached >= 3)),
    ('trial_booked', (select count(*)::numeric from ranked where reached >= 4)),
    ('trial_completed', (select count(*)::numeric from ranked where reached >= 5)),
    ('proposal', (select count(*)::numeric from ranked where reached >= 6)),
    ('negotiating', (select count(*)::numeric from ranked where reached >= 7)),
    ('won', (select count(*)::numeric from ranked where reached >= 8)),
    ('lost', (select count(*)::numeric from ranked where lost))
  ) metrics(metric, value)
  union all
  select 'hours_to_first_contact', round(avg(extract(epoch from (first_contact_at - created_at)) / 3600.0)::numeric, 2) from ranked where first_contact_at is not null
  union all
  select 'days_to_close', round(avg(extract(epoch from (won_at - created_at)) / 86400.0)::numeric, 2) from ranked where won_at is not null;
end $$;


ALTER FUNCTION "public"."crm_cohort_funnel"("p_from" "date", "p_to" "date", "p_branch" "uuid", "p_campaign" "uuid", "p_source" "text", "p_owner" "uuid", "p_program" "text") OWNER TO "postgres";


