CREATE OR REPLACE FUNCTION "public"."crm_lead_channel_state"("p_lead" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  lead public.crm_leads%rowtype;
  state text;
begin
  if p_lead is null or auth.uid() is null then
    return null;
  end if;
  select * into lead from public.crm_leads where id = p_lead;
  if not found or not public.crm_can('crm.view', lead.branch_id) then
    return null;
  end if;
  select case link.status
    when 'ACTIVE' then 'VERIFIED'
    when 'PENDING' then 'LINKED'
    when 'REVOKED' then 'REVOKED'
    else 'NONE'
  end
  into state
  from public.customer_channel_links link
  where link.provider = 'ZALO'
    and (
      (lead.converted_student_id is not null and link.student_id = lead.converted_student_id)
      or (lead.converted_parent_id is not null and link.parent_id = lead.converted_parent_id)
      or exists (
        select 1 from public.registration_applications app
        where app.id = link.registration_application_id
          and app.crm_lead_id = lead.id
      )
    )
  order by case link.status when 'ACTIVE' then 0 when 'PENDING' then 1 when 'REVOKED' then 2 else 3 end,
    link.created_at desc
  limit 1;
  return coalesce(state, 'NONE');
end;
$$;


ALTER FUNCTION "public"."crm_lead_channel_state"("p_lead" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."crm_leads" (
    "id" "uuid" NOT NULL,
    "branch_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'NEW'::"text" NOT NULL,
    "full_name" "text",
    "phone" "text",
    "email" "text",
    "phone_key" "text",
    "email_key" "text",
    "parent_name" "text",
    "student_name" "text",
    "student_date_of_birth" "date",
    "program_interest" "text",
    "instrument_interest" "text",
    "source_type" "text" NOT NULL,
    "owner_user_id" "uuid",
    "first_contact_at" timestamp with time zone,
    "last_contact_at" timestamp with time zone,
    "next_follow_up_on" "date",
    "lost_reason" "text",
    "converted_at" timestamp with time zone,
    "converted_student_id" "uuid",
    "converted_parent_id" "uuid",
    "version" integer DEFAULT 1 NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "campaign_id" "uuid",
    "external_source" "text",
    "external_lead_id" "text",
    "campaign_reference" "text",
    "received_at" timestamp with time zone,
    "interest_level" "text" DEFAULT 'REFERENCE'::"text" NOT NULL,
    CONSTRAINT "crm_leads_campaign_reference_check" CHECK ((("campaign_reference" IS NULL) OR (("char_length"("campaign_reference") >= 1) AND ("char_length"("campaign_reference") <= 120)))),
    CONSTRAINT "crm_leads_check" CHECK ((("full_name" IS NOT NULL) OR ("phone_key" IS NOT NULL) OR ("email_key" IS NOT NULL) OR ("parent_name" IS NOT NULL) OR ("student_name" IS NOT NULL))),
    CONSTRAINT "crm_leads_check1" CHECK ((("status" <> 'LOST'::"text") OR ("lost_reason" IS NOT NULL))),
    CONSTRAINT "crm_leads_check2" CHECK (((("converted_at" IS NULL) AND ("converted_student_id" IS NULL) AND ("converted_parent_id" IS NULL)) OR (("converted_at" IS NOT NULL) AND (("converted_student_id" IS NOT NULL) OR ("converted_parent_id" IS NOT NULL))))),
    CONSTRAINT "crm_leads_check3" CHECK ((("phone" IS NULL) = ("phone_key" IS NULL))),
    CONSTRAINT "crm_leads_check4" CHECK ((("email" IS NULL) = ("email_key" IS NULL))),
    CONSTRAINT "crm_leads_email_check" CHECK ((("email" IS NULL) OR (("char_length"("email") >= 1) AND ("char_length"("email") <= 200)))),
    CONSTRAINT "crm_leads_email_key_check" CHECK ((("email_key" IS NULL) OR ("email_key" ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'::"text"))),
    CONSTRAINT "crm_leads_external_lead_id_check" CHECK ((("external_lead_id" IS NULL) OR (("char_length"("external_lead_id") >= 1) AND ("char_length"("external_lead_id") <= 120)))),
    CONSTRAINT "crm_leads_external_source_check" CHECK ((("external_source" IS NULL) OR (("char_length"("external_source") >= 1) AND ("char_length"("external_source") <= 80)))),
    CONSTRAINT "crm_leads_full_name_check" CHECK ((("full_name" IS NULL) OR (("char_length"("full_name") >= 1) AND ("char_length"("full_name") <= 200)))),
    CONSTRAINT "crm_leads_instrument_interest_check" CHECK ((("instrument_interest" IS NULL) OR (("char_length"("instrument_interest") >= 1) AND ("char_length"("instrument_interest") <= 200)))),
    CONSTRAINT "crm_leads_interest_level_check" CHECK (("interest_level" = ANY (ARRAY['REFERENCE'::"text", 'INTERESTED'::"text", 'POTENTIAL'::"text"]))),
    CONSTRAINT "crm_leads_lost_reason_check" CHECK ((("lost_reason" IS NULL) OR (("char_length"("lost_reason") >= 1) AND ("char_length"("lost_reason") <= 2000)))),
    CONSTRAINT "crm_leads_next_follow_up_on_check" CHECK ((("next_follow_up_on" IS NULL) OR "isfinite"("next_follow_up_on"))),
    CONSTRAINT "crm_leads_parent_name_check" CHECK ((("parent_name" IS NULL) OR (("char_length"("parent_name") >= 1) AND ("char_length"("parent_name") <= 200)))),
    CONSTRAINT "crm_leads_phone_check" CHECK ((("phone" IS NULL) OR (("char_length"("phone") >= 1) AND ("char_length"("phone") <= 40)))),
    CONSTRAINT "crm_leads_phone_key_check" CHECK ((("phone_key" IS NULL) OR ("phone_key" ~ '^[0-9]{6,20}$'::"text"))),
    CONSTRAINT "crm_leads_program_interest_check" CHECK ((("program_interest" IS NULL) OR (("char_length"("program_interest") >= 1) AND ("char_length"("program_interest") <= 200)))),
    CONSTRAINT "crm_leads_source_type_check" CHECK (("source_type" = ANY (ARRAY['MANUAL'::"text", 'WALK_IN'::"text", 'REFERRAL'::"text", 'WEBSITE'::"text", 'ZALO'::"text", 'PHONE'::"text", 'OTHER'::"text"]))),
    CONSTRAINT "crm_leads_status_check" CHECK (("status" = ANY (ARRAY['NEW'::"text", 'CONTACTED'::"text", 'QUALIFIED'::"text", 'TRIAL_BOOKED'::"text", 'TRIAL_COMPLETED'::"text", 'PROPOSAL_SENT'::"text", 'NEGOTIATING'::"text", 'WON'::"text", 'LOST'::"text"]))),
    CONSTRAINT "crm_leads_student_date_of_birth_check" CHECK ((("student_date_of_birth" IS NULL) OR "isfinite"("student_date_of_birth"))),
    CONSTRAINT "crm_leads_student_name_check" CHECK ((("student_name" IS NULL) OR (("char_length"("student_name") >= 1) AND ("char_length"("student_name") <= 200)))),
    CONSTRAINT "crm_leads_version_check" CHECK (("version" > 0))
);


