COMMENT ON TABLE "public"."crm_leads" IS 'Prospective CRM household. Not a student, parent, or instrument buyer. Conversion columns stay empty until a later sprint.';



CREATE OR REPLACE FUNCTION "public"."crm_lead_lock"("p_lead" "uuid", "p_version" integer, "p_permission" "text") RETURNS "public"."crm_leads"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  row public.crm_leads%rowtype;
begin
  select * into row from public.crm_leads where id = p_lead for update;
  if not found then
    raise exception 'CRM_LEAD_UNAUTHORIZED';
  end if;
  perform public.crm_actor(p_permission, row.branch_id);
  if row.version is distinct from p_version then
    raise exception 'CRM_LEAD_STALE';
  end if;
  return row;
end $$;


ALTER FUNCTION "public"."crm_lead_lock"("p_lead" "uuid", "p_version" integer, "p_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_lead_match_candidates"("p_lead" "uuid") RETURNS TABLE("student_id" "uuid", "full_name" "text", "date_of_birth" "date", "student_code" "text", "default_branch_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  lead public.crm_leads%rowtype;
  wanted text;
begin
  select * into lead from public.crm_leads where id = p_lead;
  if not found then
    return;
  end if;
  perform public.crm_actor('crm.view', lead.branch_id);
  wanted := nullif(lower(btrim(coalesce(lead.student_name, lead.full_name, ''))), '');
  if wanted is null or lead.student_date_of_birth is null then
    return;
  end if;
  return query
  select student.id, student.full_name, student.date_of_birth, student.student_code, student.default_branch_id
  from public.students student
  where student.date_of_birth = lead.student_date_of_birth
    and lower(btrim(coalesce(student.full_name, ''))) = wanted
  order by student.student_code
  limit 20;
end $$;


ALTER FUNCTION "public"."crm_lead_match_candidates"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_lead_replay"("p_request" "uuid", "p_lead" "uuid", "p_event" "text", "p_actor" "uuid", "p_note" "text", "p_channel" "text", "p_metadata" "jsonb", "p_permission" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  existing public.crm_lead_events%rowtype;
  branch uuid;
begin
  if p_request is null then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('crm-lead-request:' || p_request::text, 0));
  select * into existing from public.crm_lead_events where id = p_request;
  if not found then
    return false;
  end if;
  select lead.branch_id into branch from public.crm_leads lead where lead.id = existing.lead_id;
  if branch is null then
    raise exception 'CRM_LEAD_UNAUTHORIZED';
  end if;
  perform public.crm_actor(p_permission, branch);
  if existing.lead_id is distinct from p_lead
     or existing.event_type is distinct from p_event
     or existing.actor_id is distinct from p_actor
     or existing.note is distinct from p_note
     or existing.channel is distinct from p_channel
     or existing.metadata is distinct from p_metadata
  then
    raise exception 'CRM_LEAD_REQUEST_MISMATCH';
  end if;
  return true;
end $$;


ALTER FUNCTION "public"."crm_lead_replay"("p_request" "uuid", "p_lead" "uuid", "p_event" "text", "p_actor" "uuid", "p_note" "text", "p_channel" "text", "p_metadata" "jsonb", "p_permission" "text") OWNER TO "postgres";


