    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  cleaned text := nullif(btrim(coalesce(p_value, '')), '');
begin
  if cleaned is not null and char_length(cleaned) > p_limit then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  return cleaned;
end $$;


