CREATE TABLE IF NOT EXISTS "public"."academic_operation_policies" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "version_no" integer NOT NULL,
    "effective_on" "date" NOT NULL,
    "absence_report_deadline_hours" integer,
    "makeup_use_within_days" integer,
    "max_open_makeup_credits" integer,
    "late_cancel_hours" integer,
    "max_pause_calendar_days" integer,
    "pause_money_decision" "text" DEFAULT 'UNDECIDED'::"text" NOT NULL,
    "note" "text" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "academic_operation_policies_absence_report_deadline_hours_check" CHECK ((("absence_report_deadline_hours" IS NULL) OR ("absence_report_deadline_hours" >= 0))),
    CONSTRAINT "academic_operation_policies_late_cancel_hours_check" CHECK ((("late_cancel_hours" IS NULL) OR ("late_cancel_hours" >= 0))),
    CONSTRAINT "academic_operation_policies_makeup_use_within_days_check" CHECK ((("makeup_use_within_days" IS NULL) OR ("makeup_use_within_days" > 0))),
    CONSTRAINT "academic_operation_policies_max_open_makeup_credits_check" CHECK ((("max_open_makeup_credits" IS NULL) OR ("max_open_makeup_credits" > 0))),
    CONSTRAINT "academic_operation_policies_max_pause_calendar_days_check" CHECK ((("max_pause_calendar_days" IS NULL) OR ("max_pause_calendar_days" > 0))),
    CONSTRAINT "academic_operation_policies_note_check" CHECK ((("char_length"("btrim"("note")) >= 1) AND ("char_length"("btrim"("note")) <= 2000))),
    CONSTRAINT "academic_operation_policies_pause_money_decision_check" CHECK (("pause_money_decision" = 'UNDECIDED'::"text")),
    CONSTRAINT "academic_operation_policies_version_no_check" CHECK (("version_no" > 0))
);


