CREATE OR REPLACE FUNCTION "public"."draft_learning_homework"("p_codes" "text"[]) RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select nullif(string_agg(part.label_vi, ' · ' order by case part.part_group when 'CONTENT' then 1 when 'METHOD' then 2 when 'DURATION' then 3 else 4 end, part.sort_order), '')
  from unnest(coalesce(p_codes, array[]::text[])) as input(code)
  join public.learning_homework_parts part on part.code = input.code and part.active
$$;


ALTER FUNCTION "public"."draft_learning_homework"("p_codes" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."draft_learning_progress_note"("p_codes" "text"[]) RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with picked as (
    select option.signal, option.draft_clause_vi, option.sort_order
    from unnest(coalesce(p_codes, array[]::text[])) as input(code)
    join public.learning_observation_options option on option.code = input.code
  ), parts as (
    select
      (select string_agg(draft_clause_vi, ' và ' order by sort_order) from picked where signal = 'STRENGTH') as strength,
      (select string_agg(draft_clause_vi, '. ' order by sort_order) from picked where signal = 'DEVELOPMENT') as development
  )
  select nullif(btrim(concat_ws(' ',
    case when strength is not null then 'Em ' || strength || '.' end,
    case when development is not null then development || '.' end
  )), '')
  from parts
$$;


ALTER FUNCTION "public"."draft_learning_progress_note"("p_codes" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."employee_private_profile_summary"("p_employee" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  row_value
    hr_private.employee_private_profiles%rowtype;
begin
  if auth.uid() is null
     or not coalesce(
       public.account_is_active(),
       false
     )
     or not coalesce(
       public.has_role('SUPER_ADMIN'),
       false
     )
  then
    raise exception
      'EMPLOYEE_PRIVATE_UNAUTHORIZED';
  end if;

  select *
    into row_value
  from hr_private.employee_private_profiles
  where employee_id = p_employee;

  if not found then
    return null;
  end if;

  return jsonb_build_object(
    'employee_id',
      row_value.employee_id,
    'email',
      row_value.email,
    'phone',
      row_value.phone,
    'address',
      row_value.address,
    'citizen_id_masked',
      '********' ||
      right(row_value.citizen_id, 4),
    'has_citizen_id',
      true,
    'updated_at',
      row_value.updated_at
  );
end;
$$;


ALTER FUNCTION "public"."employee_private_profile_summary"("p_employee" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."employee_schedule"("p_employee" "uuid", "p_from" "date", "p_to" "date") RETURNS TABLE("work_date" "date", "shift_code" "text", "unit_code" "text", "employment_version" integer, "starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "scheduled_minutes" integer, "schedule_state" "text", "trip_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare d date; v public.employee_versions; t public.employee_trips; dow integer; snapshot jsonb;begin
 if not public.has_role('SUPER_ADMIN') and not exists(select 1 from public.employees e where e.id=p_employee and e.profile_id=auth.uid()) then raise exception 'Employee attendance denied'; end if;
 if p_from is null or p_to is null or not isfinite(p_from) or not isfinite(p_to) or p_to<p_from or p_to-p_from>62 then raise exception 'Schedule range must be at most 63 days'; end if;
 if not exists(select 1 from public.employees where id=p_employee) then raise exception 'Employee not found'; end if;
 for d in select generate_series(p_from::timestamp,p_to::timestamp,interval '1 day')::date loop
  -- Recorded shifts retain their original assignment/schedule even after a later HR change.
  for snapshot in select a.schedule_snapshot from (select distinct on(a.shift_code) a.shift_code,a.schedule_snapshot from public.employee_attendance_entries a where a.employee_id=p_employee and a.work_date=d order by a.shift_code,a.revision desc) a loop
   work_date:=d;shift_code:=snapshot->>'shift_code';unit_code:=snapshot->>'unit_code';employment_version:=(snapshot->>'employment_version')::integer;
   starts_at:=(snapshot->>'starts_at')::timestamptz;ends_at:=(snapshot->>'ends_at')::timestamptz;scheduled_minutes:=(snapshot->>'scheduled_minutes')::integer;schedule_state:=snapshot->>'schedule_state';trip_id:=(snapshot->>'trip_id')::uuid;return next;
  end loop;
  v:=hr_private.employee_at(p_employee,d);
  if v.id is null or v.employment_status<>'ACTIVE' or v.pay_type<>'MONTHLY' then continue; end if;
  select tr.* into t from public.employee_trips tr join public.employee_trip_reviews r on r.trip_id=tr.id and r.decision='APPROVED' where tr.employee_id=p_employee and d between tr.starts_on and tr.ends_on;
  dow:=extract(isodow from d); work_date:=d; unit_code:=v.unit_code; employment_version:=v.version; trip_id:=t.id;
  if dow=6 and not exists(select 1 from public.employee_attendance_entries a where a.employee_id=p_employee and a.work_date=d and a.shift_code='AM') then
   shift_code:='AM';starts_at:=(d+time '08:00') at time zone 'Asia/Ho_Chi_Minh';ends_at:=(d+time '11:00') at time zone 'Asia/Ho_Chi_Minh';scheduled_minutes:=180;schedule_state:=case when t.id is null then 'SCHEDULED' else 'BUSINESS_TRIP' end;return next;
  end if;
  if exists(select 1 from public.employee_attendance_entries a where a.employee_id=p_employee and a.work_date=d and a.shift_code='PM') then continue;end if;
  shift_code:='PM';starts_at:=(d+time '14:00') at time zone 'Asia/Ho_Chi_Minh';ends_at:=(d+time '21:00') at time zone 'Asia/Ho_Chi_Minh';scheduled_minutes:=420;
  schedule_state:=case when dow=7 and v.unit_code in ('ST','LX') then 'SCHEDULED_OFF' when t.id is not null then 'BUSINESS_TRIP' else 'SCHEDULED' end;
  if dow=7 and v.unit_code='HQ' and t.id is not null and t.origin_unit='HQ' and t.destination_unit in ('ST','LX') then ends_at:=(d+time '18:00') at time zone 'Asia/Ho_Chi_Minh';scheduled_minutes:=240;end if;
  if schedule_state='SCHEDULED_OFF' then scheduled_minutes:=0;end if;
  return next;
 end loop;end$$;


ALTER FUNCTION "public"."employee_schedule"("p_employee" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."end_staff_compensation_component"("p_component" "uuid", "p_effective_to" "date", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  before_row public.staff_compensation_components%rowtype;
  after_row public.staff_compensation_components%rowtype;
begin
  if auth.uid() is null
     or not coalesce(public.account_is_active(),false)
     or not coalesce(public.has_role('SUPER_ADMIN'),false)
  then
    raise exception 'STAFF_COMPENSATION_UNAUTHORIZED';
  end if;

  if p_component is null then
    raise exception 'STAFF_COMPENSATION_COMPONENT_ID_REQUIRED';
  end if;

  if p_effective_to is null or not isfinite(p_effective_to) then
    raise exception 'STAFF_COMPENSATION_END_DATE_REQUIRED';
  end if;

  if p_reason is null
     or char_length(btrim(p_reason)) not between 1 and 2000
  then
    raise exception 'STAFF_COMPENSATION_REASON_REQUIRED';
  end if;

  select *
    into before_row
  from public.staff_compensation_components
  where id = p_component
  for update;

  if not found then
    raise exception 'STAFF_COMPENSATION_COMPONENT_NOT_FOUND';
  end if;

  if p_effective_to < before_row.effective_from then
    raise exception 'STAFF_COMPENSATION_END_BEFORE_START';
  end if;

  if before_row.effective_to is not null then
    if before_row.effective_to = p_effective_to then
      return jsonb_build_object(
        'status','ALREADY_ENDED',
        'component_id',before_row.id,
        'effective_to',before_row.effective_to
      );
    end if;

    raise exception 'STAFF_COMPENSATION_ALREADY_ENDED';
  end if;

  update public.staff_compensation_components
  set effective_to = p_effective_to
  where id = before_row.id
  returning * into after_row;

  insert into public.employee_audit(
    employee_id,
    action,
    before_data,
    after_data,
    reason,
    actor
  )
  values(
    before_row.employee_id,
    'COMPENSATION_COMPONENT_ENDED',
    to_jsonb(before_row),
    to_jsonb(after_row),
    btrim(p_reason),
    auth.uid()
  );

  return jsonb_build_object(
    'status','ENDED',
    'component_id',after_row.id,
    'employee_id',after_row.employee_id,
    'component_code',after_row.component_code,
    'effective_from',after_row.effective_from,
    'effective_to',after_row.effective_to
  );
end;
$$;


ALTER FUNCTION "public"."end_staff_compensation_component"("p_component" "uuid", "p_effective_to" "date", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."end_staff_compensation_component"("p_component" "uuid", "p_effective_to" "date", "p_reason" "text") IS 'Ends an open Staff compensation component at an explicit effective date and writes employee_audit. SUPER_ADMIN only in V1.';



CREATE OR REPLACE FUNCTION "public"."end_staff_position"("p_assignment" "uuid", "p_effective_to" "date", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  before_row jsonb;
  employee uuid;
begin
  if not coalesce(public.has_role('SUPER_ADMIN'), false) then
    raise exception 'STAFF_PROFILE_UNAUTHORIZED';
  end if;
  if nullif(btrim(p_reason), '') is null then
    raise exception 'STAFF_ASSIGNMENT_REASON_REQUIRED';
  end if;
  if p_effective_to is null or not isfinite(p_effective_to) then
    raise exception 'STAFF_ASSIGNMENT_DATE_INVALID';
  end if;
  select to_jsonb(a), a.employee_id into before_row, employee
  from public.staff_position_assignments a where a.id = p_assignment for update;
  if before_row is null then
    raise exception 'STAFF_ASSIGNMENT_NOT_FOUND';
  end if;
  if (before_row->>'effective_from')::date > p_effective_to then
    raise exception 'STAFF_ASSIGNMENT_DATE_INVALID';
  end if;
  update public.staff_position_assignments
  set effective_to = p_effective_to, status = 'INACTIVE'
  where id = p_assignment
    and position_code = before_row->>'position_code'
    and effective_from = (before_row->>'effective_from')::date
    and reason = before_row->>'reason';
  insert into public.employee_audit(employee_id, action, before_data, after_data, reason, actor)
  select employee, 'POSITION_ENDED', before_row, to_jsonb(a), btrim(p_reason), auth.uid()
  from public.staff_position_assignments a where a.id = p_assignment;
end;
$$;


ALTER FUNCTION "public"."end_staff_position"("p_assignment" "uuid", "p_effective_to" "date", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."end_staff_teaching"("p_assignment" "uuid", "p_effective_to" "date", "p_reason" "text") RETURNS "void"
