CREATE OR REPLACE FUNCTION "public"."enqueue_domain_notification"("p_event" "text", "p_entity" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  src record;
  link record;
  consent public.registration_zalo_phone_consents;
  created_id uuid;
  seen integer := 0;
  created integer := 0;
  subject_type text;
  subject_id uuid;
  job_status text;
  job_key text;
  phone_status text;
  parameters jsonb;
  tracking text;
begin
  if p_event is null or p_event not in (
    'REGISTRATION_COMPLETED', 'PAYMENT_CONFIRMED', 'CLASS_ASSIGNED', 'FIRST_CLASS_UPCOMING',
    'SCHEDULE_CHANGED', 'LEARNING_REPORT_PUBLISHED', 'TUITION_REMINDER', 'COURSE_EXPIRING',
    'END_OF_COURSE_REPORT_PUBLISHED'
  ) then
    raise exception 'Unsupported notification event';
  end if;
  if p_event not in (
    'PAYMENT_CONFIRMED', 'REGISTRATION_COMPLETED', 'CLASS_ASSIGNED',
    'LEARNING_REPORT_PUBLISHED', 'END_OF_COURSE_REPORT_PUBLISHED'
  ) then
    return 0;
  end if;
  select * into src from notification_private.domain_notice_source(p_event, p_entity);
  if not found then
    return 0;
  end if;
  if p_event = 'REGISTRATION_COMPLETED' then
    select * into consent
    from public.registration_zalo_phone_consents
    where application_id = p_entity and revoked_at is null
    order by consented_at desc
    limit 1;
    if found then
      phone_status := coalesce(notification_private.registration_phone_payment_status(p_entity), 'CHƯA XÁC ĐỊNH');
      parameters := src.parameters || jsonb_build_object('payment_status', phone_status);
      created_id := gen_random_uuid();
      tracking := replace(created_id::text, '-', '');
      job_key := concat_ws(':', 'domain', p_event, p_entity::text, src.template_key, 'phone', consent.id::text);
      insert into public.notification_jobs(
        id, recipient_id, student_id, branch_id, channel, delivery_mode, template_key, payload,
        entity_type, entity_id, idempotency_key, status,
        recipient_subject_type, recipient_subject_id, created_by
      ) values (
        created_id, null, src.student_id, src.branch_id, 'ZALO', 'LIVE', src.template_key,
        jsonb_build_object(
          'title', src.title,
          'href', src.href,
          'parameters', parameters,
          'delivery', jsonb_build_object(
            'channel', 'PHONE',
            'normalized_recipient', consent.normalized_phone,
            'consent_id', consent.id,
            'template_id', '640377',
            'notice_version', consent.notice_version,
            'tracking_id', tracking
          )
        ),
        p_event, p_entity, job_key, 'QUEUED', 'REGISTRATION', p_entity, auth.uid()
      ) on conflict (idempotency_key) do nothing returning id into created_id;
      if created_id is not null then
        created := 1;
        insert into public.notification_events(job_id, event, actor_id) values (created_id, 'CREATED', auth.uid());
      end if;
      return created;
    end if;
    src.parameters := src.parameters || jsonb_build_object(
      'payment_status', coalesce(notification_private.registration_phone_payment_status(p_entity), 'CHƯA XÁC ĐỊNH')
    );
  end if;
  for link in
    select * from notification_private.active_zalo_links(src.registration_id, src.parent_id, src.student_id)
  loop
    seen := seen + 1;
    created_id := null;
    insert into public.notification_jobs(
      recipient_id, student_id, branch_id, channel, delivery_mode, template_key, payload,
      entity_type, entity_id, idempotency_key, status, channel_link_id,
      recipient_subject_type, recipient_subject_id, created_by
    ) values (
      null, src.student_id, src.branch_id, 'ZALO', 'LIVE', src.template_key,
      jsonb_build_object('title', src.title, 'href', src.href, 'parameters', src.parameters),
      p_event, p_entity,
      concat_ws(':', 'domain', p_event, p_entity::text, src.template_key, link.id::text),
      'QUEUED', link.id, link.subject_type, link.subject_id, auth.uid()
    ) on conflict (idempotency_key) do nothing returning id into created_id;
    if created_id is not null then
      created := created + 1;
      insert into public.notification_events(job_id, event, actor_id) values (created_id, 'CREATED', auth.uid());
    end if;
  end loop;
  if seen = 0 then
    subject_type := case
      when src.registration_id is not null then 'REGISTRATION'
      when src.parent_id is not null then 'PARENT'
      else 'STUDENT'
    end;
    subject_id := coalesce(src.registration_id, src.parent_id, src.student_id);
    job_status := 'SKIPPED_NO_CHANNEL';
    job_key := concat_ws(':', 'domain', p_event, p_entity::text, src.template_key, 'no-channel');
    created_id := null;
    insert into public.notification_jobs(
      recipient_id, student_id, branch_id, channel, delivery_mode, template_key, payload,
      entity_type, entity_id, idempotency_key, status, error_code,
      recipient_subject_type, recipient_subject_id, created_by
    ) values (
      null, src.student_id, src.branch_id, 'ZALO', 'LIVE', src.template_key,
      jsonb_build_object('title', src.title, 'href', src.href, 'parameters', src.parameters),
      p_event, p_entity, job_key, job_status, job_status,
      subject_type, subject_id, auth.uid()
    ) on conflict (idempotency_key) do nothing returning id into created_id;
    if created_id is not null then
      created := created + 1;
      insert into public.notification_events(job_id, event, actor_id) values (created_id, 'CREATED', auth.uid());
    end if;
  end if;
  return created;
end $$;


ALTER FUNCTION "public"."enqueue_domain_notification"("p_event" "text", "p_entity" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_notification_event"("p_event" "text", "p_entity" "uuid", "p_channel" "text" DEFAULT 'IN_APP'::"text", "p_mode" "text" DEFAULT 'LIVE'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  s uuid;
  b uuid;
  u uuid;
  v text := '1';
  t text;
  target text;
  title text;
  rec record;
  j uuid;
  n integer := 0;
begin
  if not public.has_role('SUPER_ADMIN') then
    raise exception 'Unauthorized';
  end if;
  if p_channel is null or p_channel not in ('EMAIL', 'ZALO', 'IN_APP')
    or p_mode is null or p_mode not in ('LIVE', 'MOCK') then
    raise exception 'Invalid channel or mode';
  end if;
  if p_event = 'TUITION_PAYMENT_RECEIVED' then
    if p_channel is distinct from 'ZALO' or p_mode is distinct from 'LIVE' then
      raise exception 'Unsupported notification event';
    end if;
    return public.enqueue_tuition_payment_received(p_entity);
  end if;
  t := p_event;
  case p_event
    when 'ONBOARDING' then
      select id into u from profiles where id = p_entity and status = 'ACTIVE';
      target := '/';
      title := 'Chào mừng bạn đến Vibe Academy';
    when 'TUITION_REMINDER' then
      select e.student_id, et.branch_id_snapshot into s, b
      from tuition_reminders r
      join enrollment_tuition et on et.id = r.enrollment_tuition_id
      join enrollments e on e.id = et.enrollment_id
      where r.id = p_entity
        and r.status = 'PENDING'
        and r.window_start <= (now() at time zone 'Asia/Ho_Chi_Minh')::date
        and e.status = 'ACTIVE'
        and et.status in ('ACTIVE', 'SCHEDULED');
      target := '/my-learning';
      title := 'Bạn có nhắc học phí cần xem';
    when 'LEARNING_REPORT' then
      select student_id, branch_id, version::text,
             case report_type when 'MONTHLY' then 'MONTHLY_REPORT' else 'END_OF_COURSE' end
      into s, b, v, t
      from learning_reports
      where id = p_entity and status = 'APPROVED';
      target := '/my-learning';
      title := 'Báo cáo học tập đã được duyệt';
    when 'SCHEDULE_CHANGED' then
      select c.branch_id, o.updated_at::text into b, v
      from session_occurrences o
      join schedules sc on sc.id = o.schedule_id
      join classes c on c.id = sc.class_id
      where o.id = p_entity;
      target := '/my-learning';
      title := 'Lịch học có cập nhật';
    when 'ATTENDANCE_NOTICE' then
      select e.student_id, c.branch_id, a.updated_at::text into s, b, v
      from attendance_records a
      join enrollments e on e.id = a.enrollment_id
      join classes c on c.id = e.class_id
      where a.id = p_entity;
      target := '/my-learning';
      title := 'Điểm danh buổi học có cập nhật';
    when 'FEEDBACK_FOLLOW_UP' then
      select student_id, branch_id, respondent_user_id, version::text into s, b, u, v
      from lesson_feedback
      where id = p_entity and resolution_status = 'RESOLVED';
      target := '/my-learning';
      title := 'Phản hồi buổi học đã được cập nhật';
    else
      raise exception 'Unsupported notification event';
  end case;
  if (p_event = 'ONBOARDING' and u is null) or (p_event <> 'ONBOARDING' and b is null) then
    raise exception 'Eligible source not found';
  end if;
  for rec in
    with audience_students as (
      select s as sid where s is not null
      union
      select e.student_id
      from enrollments e
      join schedules sc on sc.class_id = e.class_id
      join session_occurrences o on o.schedule_id = sc.id
      where p_event = 'SCHEDULE_CHANGED'
        and o.id = p_entity
        and e.status = 'ACTIVE'
        and e.started_at <= o.occurrence_date
        and (e.ended_at is null or e.ended_at >= o.occurrence_date)
    ), audience as (
      select u as uid, s as sid where p_event = 'ONBOARDING'
      union
      select st.user_id, a.sid from audience_students a join students st on st.id = a.sid
      union
      select p.user_id, a.sid
      from audience_students a
      join student_parents sp on sp.student_id = a.sid
      join parents p on p.id = sp.parent_id
    )
    select distinct uid, sid from audience where uid is not null and (u is null or uid = u)
  loop
    if not notification_private.recipient_allowed(rec.uid, rec.sid, b, t) then
      continue;
    end if;
    j := null;
    insert into notification_jobs(
      recipient_id, student_id, branch_id, channel, delivery_mode, template_key, payload,
      entity_type, entity_id, idempotency_key, created_by
    ) values (
      rec.uid, rec.sid, b, p_channel, p_mode, t,
      jsonb_build_object('title', title, 'href', target),
      p_event, p_entity,
      concat_ws(':', p_event, p_entity, v, rec.uid, p_channel, p_mode),
      auth.uid()
    ) on conflict (idempotency_key) do nothing
    returning id into j;
    if j is not null then
      n := n + 1;
      insert into notification_events(job_id, event, actor_id) values (j, 'CREATED', auth.uid());
    end if;
  end loop;
  return n;
end $$;


ALTER FUNCTION "public"."enqueue_notification_event"("p_event" "text", "p_entity" "uuid", "p_channel" "text", "p_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_tuition_payment_received"("p_payment" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  payment public.payments%rowtype;
  student_name text;
  parameters jsonb;
  payload jsonb;
  parent record;
  created_id uuid;
  created integer := 0;
  seen integer := 0;
begin
  if auth.uid() is not null and not public.has_role('SUPER_ADMIN') then
    raise exception 'Unauthorized';
  end if;
  if p_payment is null then
    return 0;
  end if;
  select * into payment from public.payments where id = p_payment;
  if not found or payment.status is distinct from 'POSTED' then
    return 0;
  end if;
  select left(coalesce(student.full_name, 'Học viên'), 80)
  into student_name
  from public.students student
  where student.id = payment.student_id_snapshot;
  parameters := jsonb_build_object(
    'student_name', coalesce(student_name, 'Học viên'),
    'amount', trim(to_char(payment.amount, 'FM999999999990.00')) || ' ' || payment.currency,
    'payment_date', to_char((payment.paid_at at time zone 'Asia/Ho_Chi_Minh'), 'YYYY-MM-DD'),
    'payment_number', left(payment.payment_number, 40)
  );
  payload := jsonb_build_object(
    'title', 'Thanh toán đã được ghi nhận',
    'href', '/my-learning',
    'parameters', parameters
  );
  for parent in
    select * from notification_private.finance_zalo_parents(payment.student_id_snapshot)
  loop
    seen := seen + 1;
    created_id := null;
    insert into public.notification_jobs(
      recipient_id, student_id, branch_id, channel, delivery_mode, template_key, payload,
      entity_type, entity_id, idempotency_key, status, channel_link_id,
      recipient_subject_type, recipient_subject_id, created_by
    ) values (
      parent.profile_id,
      payment.student_id_snapshot,
      payment.branch_id_snapshot,
      'ZALO',
      'LIVE',
      'ZALO_PAYMENT_RECEIVED',
      payload,
      'TUITION_PAYMENT_RECEIVED',
      payment.id,
      concat_ws(':', 'TUITION_PAYMENT_RECEIVED', payment.id::text, 'ZALO_PAYMENT_RECEIVED', parent.channel_link_id::text, 'ZALO'),
      'PENDING',
      parent.channel_link_id,
      'PARENT',
      parent.parent_id,
      auth.uid()
    ) on conflict (idempotency_key) do nothing
    returning id into created_id;
    if created_id is not null then
      created := created + 1;
      insert into public.notification_events(job_id, event, actor_id)
      values (created_id, 'CREATED', auth.uid());
    end if;
  end loop;
  if seen = 0 then
    created_id := null;
    insert into public.notification_jobs(
      recipient_id, student_id, branch_id, channel, delivery_mode, template_key, payload,
      entity_type, entity_id, idempotency_key, status, error_code,
      recipient_subject_type, recipient_subject_id, created_by
    ) values (
      null,
      payment.student_id_snapshot,
      payment.branch_id_snapshot,
      'ZALO',
      'LIVE',
      'ZALO_PAYMENT_RECEIVED',
      payload,
      'TUITION_PAYMENT_RECEIVED',
      payment.id,
      concat_ws(':', 'TUITION_PAYMENT_RECEIVED', payment.id::text, 'ZALO_PAYMENT_RECEIVED', 'no-link', 'ZALO'),
      'SKIPPED_NO_CHANNEL',
      'ZALO_RECIPIENT_NOT_LINKED',
      'STUDENT',
      payment.student_id_snapshot,
      auth.uid()
    ) on conflict (idempotency_key) do nothing
    returning id into created_id;
    if created_id is not null then
      created := created + 1;
      insert into public.notification_events(job_id, event, actor_id, details)
      values (created_id, 'SKIPPED_NO_CHANNEL', auth.uid(), jsonb_build_object('error_code', 'ZALO_RECIPIENT_NOT_LINKED'));
    end if;
  end if;
  return created;
end $$;


ALTER FUNCTION "public"."enqueue_tuition_payment_received"("p_payment" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enrollment_lifecycle_state"("p_enrollment" "uuid", "p_on" "date") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case
    when enrollment.status = 'ACTIVE'
      and class_row.status = 'ACTIVE'
      and enrollment.started_at is not null
      and enrollment.started_at <= p_on
      and (enrollment.ended_at is null or enrollment.ended_at >= p_on)
      and not exists (
        select 1
        from public.student_placement_cases placement
        where placement.enrollment_id = enrollment.id
          and (
            placement.status in ('UNASSIGNED', 'MATCHING')
            or (
              placement.status = 'SCHEDULED'
              and placement.scheduled_start_date > p_on
            )
          )
      )
    then case
      when public.is_enrollment_paused_on(enrollment.id, p_on) then 'PAUSED'
      else 'ACTIVE'
    end
    else null
  end
  from public.enrollments enrollment
  join public.classes class_row on class_row.id = enrollment.class_id
  where enrollment.id = p_enrollment
$$;


ALTER FUNCTION "public"."enrollment_lifecycle_state"("p_enrollment" "uuid", "p_on" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_session_learning_journal"("p_session" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor uuid := auth.uid();
  journal_id uuid;
begin
  if actor is null or not public.can_write_session_journal(p_session) then raise exception 'JOURNAL_UNAUTHORIZED'; end if;
  select id into journal_id from public.session_learning_journals where session_occurrence_id = p_session;
  if found then return journal_id; end if;
  perform set_config('journal.taxonomy_write', 'on', true);
  insert into public.session_learning_journals(session_occurrence_id, created_by)
  values (p_session, actor) returning id into journal_id;
  perform set_config('journal.taxonomy_write', 'off', true);
  return journal_id;
end $$;


ALTER FUNCTION "public"."ensure_session_learning_journal"("p_session" "uuid") OWNER TO "postgres";


