CREATE OR REPLACE FUNCTION "public"."finish_tuition_zalo_send"("p_send" "uuid", "p_outcome" "text", "p_error" "text" DEFAULT NULL::"text", "p_receipt" "text" DEFAULT NULL::"text", "p_message_id" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  send public.tuition_zalo_sends;
  parent_user uuid;
  created_job uuid;
  key text;
begin
  if not coalesce(public.has_role('SUPER_ADMIN'), false) then
    raise exception 'SUPER_ADMIN role required';
  end if;
  if p_outcome not in ('ERROR', 'SENT') then
    raise exception 'Invalid tuition Zalo outcome';
  end if;
  if p_outcome = 'SENT' and (
    p_error is not null
    or nullif(btrim(coalesce(p_receipt, '')), '') is null
    or p_message_id is null
    or p_message_id !~ '^[A-Za-z0-9_-]{1,80}$'
  ) then
    raise exception 'Sent tuition Zalo requires provider receipt';
  end if;
  if p_outcome = 'ERROR' and p_error not in ('PROVIDER_NOT_CONFIGURED', 'ZALO_PILOT_OUTBOUND_DISABLED', 'PROVIDER_REJECTED', 'ZALO_TOKEN_INVALID', 'ZALO_PROOF_INVALID') then
    raise exception 'Invalid tuition Zalo error';
  end if;
  select * into send from public.tuition_zalo_sends where id = p_send for update;
  if not found then
    raise exception 'Tuition Zalo send not found';
  end if;
  if send.send_status <> 'PREPARED' then
    return case send.send_status when 'SENT' then 'SENT' when 'DELIVERED' then 'SENT' when 'FAILED' then 'ERROR' else 'NOT_SENT' end;
  end if;

  update public.tuition_zalo_sends
  set send_status = case when p_outcome = 'SENT' then 'SENT' else 'FAILED' end,
      error_code = case when p_outcome = 'ERROR' then p_error else null end,
      provider_message_id = case when p_outcome = 'SENT' then p_message_id else null end,
      sent_at = case when p_outcome = 'SENT' then clock_timestamp() else null end
  where id = send.id;

  select user_id into parent_user from public.parents where id = send.parent_id;
  key := 'TUITION_ZALO:' || send.tracking_id;
  insert into public.notification_jobs(
    recipient_id, recipient_subject_type, recipient_subject_id, student_id, branch_id,
    channel, delivery_mode, template_key, payload, entity_type, entity_id,
    idempotency_key, status, attempts, error_code, provider_receipt, provider_message_id, sent_at, created_by
  )
  select parent_user, 'PARENT', send.parent_id, send.student_id, tuition.branch_id_snapshot,
    'ZALO', case when p_outcome = 'SENT' then 'LIVE' else 'MOCK' end, 'ZALO_TUITION_REMINDER',
    jsonb_build_object(
      'template_key', 'ZALO_TUITION_REMINDER',
      'provider_template_id', '643118',
      'template_kind', 'ZBS_RESPONSE',
      'outcome', p_outcome,
      'tracking_id', send.tracking_id,
      'reminder_id', send.reminder_id,
      'student_id', send.student_id,
      'parent_id', send.parent_id,
      'enrollment_tuition_id', send.enrollment_tuition_id
    ),
    'TUITION_REMINDER', send.reminder_id, key,
    case when p_outcome = 'SENT' then 'SENT' else 'FAILED' end,
    1,
    case when p_outcome = 'ERROR' then p_error else null end,
    case when p_outcome = 'SENT' then p_receipt else null end,
    case when p_outcome = 'SENT' then p_message_id else null end,
    case when p_outcome = 'SENT' then clock_timestamp() else null end,
    auth.uid()
  from public.enrollment_tuition tuition
  where tuition.id = send.enrollment_tuition_id
  on conflict (idempotency_key) do nothing
  returning id into created_job;

  if created_job is not null then
    update public.tuition_zalo_sends set job_id = created_job where id = send.id;
    insert into public.notification_events(job_id, event, actor_id, details)
    values (
      created_job,
      case when p_outcome = 'SENT' then 'CONFIRMED' else 'FAILED' end,
      auth.uid(),
      jsonb_build_object('mode', case when p_outcome = 'SENT' then 'LIVE' else 'MOCK' end, 'error_code', p_error, 'tracking_id', send.tracking_id)
    );
  end if;
  return p_outcome;
end $_$;


ALTER FUNCTION "public"."finish_tuition_zalo_send"("p_send" "uuid", "p_outcome" "text", "p_error" "text", "p_receipt" "text", "p_message_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finish_zalo_registration_attempt"("p_attempt" "uuid", "p_state" "text", "p_http" integer DEFAULT NULL::integer, "p_provider_error" integer DEFAULT NULL::integer, "p_message_id" "text" DEFAULT NULL::"text", "p_error" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare a zalo_notification_attempts; j notification_jobs;
begin
 select * into a from zalo_notification_attempts where id=p_attempt;
 if not found then return 'NOT_RECORDED'; end if;
 select * into j from notification_jobs where id=a.job_id for update;
 select * into a from zalo_notification_attempts where id=p_attempt for update;
 if a.state=p_state and a.state<>'REQUESTING' then return a.state; end if;
 if a.state<>'REQUESTING' or j.status<>'PROCESSING' or j.lease_token is distinct from a.id then return 'NOT_RECORDED'; end if;
 if p_state is null or p_state not in ('ACCEPTED','REJECTED','UNKNOWN') then return 'INVALID'; end if;
 if p_state='ACCEPTED' and (p_message_id is null or p_message_id !~ '^[A-Za-z0-9_-]{1,80}$') then return 'INVALID'; end if;
 if p_state='REJECTED' and (p_provider_error is null or p_provider_error <> all(array[-101,-103,-104,-106,-107,-108,-109,-110,-111,-112,-1121,-1122,-1123,-1124,-113,-1131,-115,-116,-117,-118,-120,-1202,-121,-122,-124,-1241,-125,-126,-127,-130,-131,-132,-135,-1351,-136,-137,-138,-1381,-139,-140,-141,-142,-143,-144,-1441,-145,-147,-1471,-1472,-148,-149,-1491,-150,-151,-152,-153,-158,-159,-160,-161,-162,-249])) then return 'INVALID'; end if;
 if p_error is not null and p_error !~ '^ZALO_[A-Z0-9_-]{1,64}$' then return 'INVALID'; end if;
 perform set_config('zalo.durable_write','on',true);
 update zalo_notification_attempts set state=p_state,completed_at=clock_timestamp(),http_status=p_http,provider_error=p_provider_error,provider_message_id=p_message_id,error_code=p_error where id=a.id;
 update notification_jobs set status=case p_state when 'ACCEPTED' then 'SENT' when 'REJECTED' then 'FAILED' else 'ACCEPTANCE_UNKNOWN' end,
  sent_at=case when p_state='ACCEPTED' then clock_timestamp() end,
  provider_message_id=p_message_id,provider_receipt=case when p_state='ACCEPTED' then 'ZALO_PHONE_ACCEPTED' end,
  error_code=case when p_state='UNKNOWN' then 'ZALO_ACCEPTANCE_UNKNOWN' else p_error end,
  lease_token=null,lease_until=null,updated_at=clock_timestamp() where id=j.id;
 insert into notification_events(job_id,event,details) values(j.id,case p_state when 'ACCEPTED' then 'SENT' else 'FAILED' end,
  jsonb_build_object('attempt_id',a.id,'state',p_state,'http_status',p_http,'provider_error',p_provider_error,'error_code',p_error));
 return p_state;
end $_$;


ALTER FUNCTION "public"."finish_zalo_registration_attempt"("p_attempt" "uuid", "p_state" "text", "p_http" integer, "p_provider_error" integer, "p_message_id" "text", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_learning_report"("p_enrollment_id" "uuid", "p_type" "text", "p_start" "date", "p_end" "date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  e enrollments;
  r learning_reports;
  result uuid;
  payload jsonb;
  required_end date;
begin
  if not coalesce(has_role('SUPER_ADMIN'),false) then
    raise exception 'Unauthorized';
  end if;
  if p_type is null or p_type not in ('MONTHLY','END_OF_COURSE')
     or p_start is null or p_end is null or p_end<p_start
     or p_end >= (now() at time zone 'Asia/Ho_Chi_Minh')::date
     or p_end-p_start>3660 then
    raise exception 'Invalid closed report period';
  end if;

  -- Serialize history checks and generation for this enrollment.
  select * into e from enrollments where id=p_enrollment_id for update;
  if not found or e.started_at is null or e.started_at>p_end
     or (e.ended_at is not null and e.ended_at<p_start) then
    raise exception 'Enrollment does not overlap period';
  end if;
  select * into r from learning_reports
  where enrollment_id=p_enrollment_id and report_type=p_type
    and period_start=p_start and period_end=p_end;
  -- Preserve historical/legacy periods and cancelled identities; never regenerate here.
  if found then return r.id; end if;

  if p_type='MONTHLY' then
    if p_start<e.started_at or (e.ended_at is not null and p_end>e.ended_at) then
      raise exception 'Monthly report must stay within enrollment dates; use END_OF_COURSE for a shortened final period';
    end if;
    -- All existing statuses count, as cancellation does not release the unique identity.
    if not exists(select 1 from learning_reports where enrollment_id=e.id and report_type='MONTHLY') then
      if extract(day from e.started_at)=1 then
        required_end := (date_trunc('month',e.started_at)+interval '1 month - 1 day')::date;
        if p_start<>e.started_at or p_end<>required_end then
          raise exception 'First monthly report must cover the enrollment start calendar month';
        end if;
      else
        required_end := (date_trunc('month',e.started_at)+interval '2 months - 1 day')::date;
        if p_start<>e.started_at or p_end<>required_end then
          raise exception 'First monthly report must start on the enrollment start date and end on the last day of the following month';
        end if;
      end if;
    elsif p_start<>date_trunc('month',p_start)::date
       or p_end<>(date_trunc('month',p_start)+interval '1 month - 1 day')::date then
      raise exception 'Monthly report must cover a full calendar month';
    end if;
    if exists(select 1 from learning_reports where enrollment_id=e.id and report_type='MONTHLY'
      and period_start<=p_end and period_end>=p_start) then
      raise exception 'Monthly report overlaps an existing report';
    end if;
  end if;

  -- END_OF_COURSE retains its existing closed-period/overlap semantics.
  payload:=learning_report_source(p_enrollment_id,p_start,p_end);
  insert into learning_reports(student_id,enrollment_id,curriculum_enrollment_id,branch_id,report_type,period_start,period_end,draft_data,generated_by)
  values(e.student_id,e.id,e.student_curriculum_enrollment_id,(payload->'branch'->>'id')::uuid,p_type,p_start,p_end,payload,auth.uid()) returning id into result;
  insert into learning_report_events(report_id,event,version,actor_id) values(result,'GENERATED',1,auth.uid());
  return result;
end $$;


ALTER FUNCTION "public"."generate_learning_report"("p_enrollment_id" "uuid", "p_type" "text", "p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_session_occurrences"("p_from" "date", "p_to" "date") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_inserted_count integer;
begin
  if p_from is null or p_to is null then
    raise exception 'Generation date range is required';
  end if;

  if p_to < p_from then
    raise exception 'Generation end date cannot be before start date';
  end if;

  if p_to - p_from > 366 then
    raise exception 'Generation date range cannot exceed 366 days';
  end if;

  insert into public.session_occurrences (
    schedule_id,
    occurrence_date,
    starts_at,
    ends_at,
    room_id,
    status,
    occurrence_type
  )
  select
    schedule.id,
    generated.occurrence_date,
    (
      generated.occurrence_date
      + schedule.start_time
    ) at time zone schedule.timezone,
    (
      generated.occurrence_date
      + schedule.end_time
    ) at time zone schedule.timezone,
    schedule.room_id,
    'SCHEDULED',
    'REGULAR'
  from public.schedules as schedule
  cross join lateral (
    select generated_at::date as occurrence_date
    from generate_series(
      greatest(
        p_from,
        schedule.effective_from
      )::timestamp,
      least(
        p_to,
        coalesce(schedule.effective_to, p_to)
      )::timestamp,
      interval '1 day'
    ) as generated_at
  ) as generated
  where schedule.status = 'ACTIVE'
    and schedule.effective_from <= p_to
    and (
      schedule.effective_to is null
      or schedule.effective_to >= p_from
    )
    and extract(
      isodow from generated.occurrence_date
    )::smallint = schedule.day_of_week
  on conflict (
    schedule_id,
    occurrence_date
  ) where occurrence_type = 'REGULAR'
  do nothing;

  get diagnostics
    v_inserted_count = row_count;

  return v_inserted_count;
end;
$$;


ALTER FUNCTION "public"."generate_session_occurrences"("p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_staff_payroll_v2"("p_period" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  p public.payroll_periods%rowtype;

  staff_row record;
  ev record;
  cfg record;
  sess record;
  session_cfg record;

  payroll_id_value uuid;
  currency_value text;
  pay_type_value text;

  staff_count_value integer := 0;
  line_count_value integer := 0;
  completed_session_count integer := 0;

  earnings_value numeric(16,2);
  reimbursement_value numeric(16,2);
  deduction_value numeric(16,2);
  base_salary_value numeric(16,2);
  teaching_value numeric(16,2);
  teaching_hours_value numeric(16,6);
  total_net_value numeric(16,2);

  before_state jsonb;
  after_state jsonb;
begin
  if auth.uid() is null
     or not coalesce(public.account_is_active(),false)
  then
    raise exception 'PAYROLL_V2_UNAUTHORIZED';
  end if;

  -- Resolve authoritative branch from the period, then authorize.
  select target.*
    into p
  from public.payroll_periods target
  where target.id = p_period
    and public.has_permission('payroll.prepare',target.branch_id)
    and (
      public.is_global_super_admin()
      or public.has_role_permission(
        'FINANCE',
        'payroll.prepare',
        target.branch_id
      )
    )
  for update;

  if not found then
    raise exception 'PAYROLL_V2_UNAUTHORIZED';
  end if;

  if p.status <> 'DRAFT' then
    raise exception 'PAYROLL_V2_REQUIRES_DRAFT';
  end if;

  if exists(
    select 1
    from public.payroll_adjustments a
    join public.teacher_payrolls t
      on t.id = a.payroll_id
    where t.period_id = p.id
  ) then
    raise exception 'PAYROLL_V2_ADJUSTMENTS_BLOCK_REGENERATION';
  end if;

  -- Serialize compensation and Staff evidence during generation.
  lock table public.staff_compensation_components in share mode;
  perform 1
  from public.employees
  order by id
  for update;

  before_state := public.payroll_approval_snapshot(p.id);

  -- DRAFT regeneration may replace previous calculated rows.
  delete from public.payroll_component_lines_v2
  where payroll_id in (
    select id
    from public.teacher_payrolls
    where period_id = p.id
  );

  delete from public.payroll_earning_lines
  where payroll_id in (
    select id
    from public.teacher_payrolls
    where period_id = p.id
  );

  delete from public.teacher_payrolls
  where period_id = p.id;

  if not exists(
    select 1
    from public.staff_compensation_components s
    where s.branch_id = p.branch_id
      and s.status = 'ACTIVE'
      and s.effective_from <= p.ends_on
      and (s.effective_to is null or s.effective_to >= p.starts_on)
  ) then
    raise exception 'PAYROLL_V2_NO_ELIGIBLE_STAFF';
  end if;

  for staff_row in
    select distinct
      e.id as employee_id,
      e.teacher_id,
      e.employee_code
    from public.employees e
    join public.staff_compensation_components s
      on s.employee_id = e.id
    where s.branch_id = p.branch_id
      and s.status = 'ACTIVE'
      and s.effective_from <= p.ends_on
      and (s.effective_to is null or s.effective_to >= p.starts_on)
    order by e.id
  loop
    -- Staff display/employment snapshot at period end.
    select
      v.full_name,
      v.employment_status,
      v.version,
      v.effective_on
      into ev
    from public.employee_versions v
    where v.employee_id = staff_row.employee_id
      and v.effective_on <= p.ends_on
    order by v.effective_on desc, v.version desc
    limit 1;

    if not found then
      raise exception 'PAYROLL_V2_EMPLOYMENT_VERSION_REQUIRED';
    end if;

    if ev.employment_status = 'TERMINATED' then
      raise exception 'PAYROLL_V2_TERMINATION_PRORATION_UNSUPPORTED';
    end if;

    if ev.employment_status not in ('ACTIVE','ON_LEAVE') then
      raise exception 'PAYROLL_V2_INVALID_EMPLOYMENT_STATUS';
    end if;

    -- V1 intentionally supports only fixed recurring amounts and per-session pay.
    if exists(
      select 1
      from public.staff_compensation_components s
      where s.employee_id = staff_row.employee_id
        and s.branch_id = p.branch_id
        and s.status = 'ACTIVE'
        and s.effective_from <= p.ends_on
        and (s.effective_to is null or s.effective_to >= p.starts_on)
        and s.calculation_method not in ('FIXED_AMOUNT','PER_SESSION')
    ) then
      raise exception 'PAYROLL_V2_CALCULATION_METHOD_UNSUPPORTED';
    end if;

    -- Fixed monthly components must cover the full payroll month in V1.
    -- Partial-month proration will be implemented separately rather than guessed.
    if exists(
      select 1
      from public.staff_compensation_components s
      where s.employee_id = staff_row.employee_id
        and s.branch_id = p.branch_id
        and s.status = 'ACTIVE'
        and s.calculation_method = 'FIXED_AMOUNT'
        and s.effective_from <= p.ends_on
        and (s.effective_to is null or s.effective_to >= p.starts_on)
        and (
          s.effective_from > p.starts_on
          or coalesce(s.effective_to,p.ends_on) < p.ends_on
        )
    ) then
      raise exception 'PAYROLL_V2_PARTIAL_FIXED_COMPONENT_UNSUPPORTED';
    end if;

    -- All monetary configs contributing to one payroll must use one currency.
    if (
      select count(distinct s.currency)
      from public.staff_compensation_components s
      where s.employee_id = staff_row.employee_id
        and s.branch_id = p.branch_id
        and s.status = 'ACTIVE'
        and s.effective_from <= p.ends_on
        and (s.effective_to is null or s.effective_to >= p.starts_on)
        and s.currency is not null
    ) > 1 then
      raise exception 'PAYROLL_V2_MULTIPLE_CURRENCIES_UNSUPPORTED';
    end if;

    select min(s.currency)
      into currency_value
    from public.staff_compensation_components s
    where s.employee_id = staff_row.employee_id
      and s.branch_id = p.branch_id
      and s.status = 'ACTIVE'
      and s.effective_from <= p.ends_on
      and (s.effective_to is null or s.effective_to >= p.starts_on)
      and s.currency is not null;

    if currency_value is null then
      raise exception 'PAYROLL_V2_CURRENCY_REQUIRED';
    end if;

    pay_type_value :=
      case
        when exists(
          select 1
          from public.staff_compensation_components s
          join public.payroll_component_catalog c
            on c.code = s.component_code
          where s.employee_id = staff_row.employee_id
            and s.branch_id = p.branch_id
            and s.status = 'ACTIVE'
            and s.effective_from <= p.ends_on
            and (s.effective_to is null or s.effective_to >= p.starts_on)
            and s.calculation_method = 'FIXED_AMOUNT'
            and c.category = 'EARNING'
        )
        then 'MONTHLY'

        when exists(
          select 1
          from public.staff_compensation_components s
          where s.employee_id = staff_row.employee_id
            and s.branch_id = p.branch_id
            and s.status = 'ACTIVE'
            and s.effective_from <= p.ends_on
            and (s.effective_to is null or s.effective_to >= p.starts_on)
            and s.calculation_method = 'PER_SESSION'
        )
        then 'PER_SESSION'

        else 'COMPONENT_V2'
      end;

    insert into public.teacher_payrolls(
      period_id,
      teacher_id,
      employee_id,
      branch_id,
      teacher_name,
      pay_type,
      currency,
      base_salary,
      teaching_hours,
      hourly_earnings,
      adjustment_amount,
      gross_amount,
      v2_earnings_amount,
      v2_reimbursement_amount,
      v2_deduction_amount,
      v2_net_amount,
      calculation_version
    )
    values(
      p.id,
      staff_row.teacher_id,
      staff_row.employee_id,
      p.branch_id,
      ev.full_name,
      pay_type_value,
      currency_value,
      0,
      0,
      0,
      0,
      0,
      0,
      0,
      0,
      0,
      'PAYROLL_V2_1'
    )
    returning id into payroll_id_value;

    staff_count_value := staff_count_value + 1;

    -- Fixed recurring components.
    for cfg in
      select
        s.*,
        c.category,
        c.name as component_name
      from public.staff_compensation_components s
      join public.payroll_component_catalog c
        on c.code = s.component_code
      where s.employee_id = staff_row.employee_id
        and s.branch_id = p.branch_id
        and s.status = 'ACTIVE'
        and s.calculation_method = 'FIXED_AMOUNT'
        and s.effective_from <= p.starts_on
        and (s.effective_to is null or s.effective_to >= p.ends_on)
      order by s.component_code, s.id
    loop
      insert into public.payroll_component_lines_v2(
        payroll_id,
        employee_id,
        component_config_id,
        component_code,
        category,
        calculation_method,
        source_type,
        source_session_id,
        earned_on,
        quantity,
        unit_rate,
        amount,
        currency,
        source_snapshot
      )
      values(
        payroll_id_value,
        staff_row.employee_id,
        cfg.id,
        cfg.component_code,
        cfg.category,
        cfg.calculation_method,
        'CONFIG',
        null,
        p.starts_on,
        1,
        cfg.amount,
        cfg.amount,
        cfg.currency,
        jsonb_build_object(
          'calculation_version','PAYROLL_V2_1',
          'component_config',to_jsonb(cfg),
          'period',jsonb_build_object(
            'id',p.id,
            'starts_on',p.starts_on,
            'ends_on',p.ends_on
          ),
          'employment',jsonb_build_object(
            'employee_id',staff_row.employee_id,
            'employee_code',staff_row.employee_code,
            'employee_version',ev.version,
            'employment_status',ev.employment_status
          )
        )
      );

      line_count_value := line_count_value + 1;
    end loop;

    -- Per-session teaching earnings are based ONLY on actual COMPLETED sessions.
    if staff_row.teacher_id is not null then
      for sess in
        select
          a.session_id,
          a.teacher_id,
          a.class_id,
          a.branch_id,
          a.occurrence_date,
          a.status,
          a.starts_at,
          a.ends_at,
          c.class_type
        from public.session_actual_teachers a
        join public.classes c
          on c.id = a.class_id
        where a.teacher_id = staff_row.teacher_id
          and a.branch_id = p.branch_id
          and a.occurrence_date between p.starts_on and p.ends_on
          and a.status = 'COMPLETED'
          and a.ends_at <= clock_timestamp()
        order by a.occurrence_date, a.session_id
      loop
        select
          s.*,
          c.category,
          c.name as component_name
          into session_cfg
        from public.staff_compensation_components s
        join public.payroll_component_catalog c
          on c.code = s.component_code
        where s.employee_id = staff_row.employee_id
          and s.branch_id = p.branch_id
          and s.component_code = 'TEACHING_PER_SESSION'
          and s.status = 'ACTIVE'
          and s.calculation_method = 'PER_SESSION'
          and s.effective_from <= sess.occurrence_date
          and (s.effective_to is null or s.effective_to >= sess.occurrence_date)
          and (s.class_type is null or s.class_type = sess.class_type)
        order by
          case when s.class_type is null then 1 else 0 end,
          s.effective_from desc,
          s.id
        limit 1;

        if found then
          insert into public.payroll_component_lines_v2(
            payroll_id,
            employee_id,
            component_config_id,
            component_code,
            category,
            calculation_method,
            source_type,
            source_session_id,
            earned_on,
            quantity,
            unit_rate,
            amount,
            currency,
            source_snapshot
          )
          values(
            payroll_id_value,
            staff_row.employee_id,
            session_cfg.id,
            session_cfg.component_code,
            session_cfg.category,
            session_cfg.calculation_method,
            'SESSION',
            sess.session_id,
            sess.occurrence_date,
            1,
            session_cfg.rate,
            session_cfg.rate,
            session_cfg.currency,
            jsonb_build_object(
              'calculation_version','PAYROLL_V2_1',
              'component_config',to_jsonb(session_cfg),
              'session',to_jsonb(sess),
              'duration_hours',
                round(
                  extract(epoch from (sess.ends_at - sess.starts_at))
                  / 3600.0,
                  6
                )
            )
          );

          line_count_value := line_count_value + 1;
          completed_session_count := completed_session_count + 1;
        end if;
      end loop;
    end if;

    select
      coalesce(sum(l.amount) filter (where l.category = 'EARNING'),0),
      coalesce(sum(l.amount) filter (where l.category = 'REIMBURSEMENT'),0),
      coalesce(sum(l.amount) filter (where l.category = 'DEDUCTION'),0),
      coalesce(sum(l.amount) filter (where l.component_code = 'BASE_SALARY'),0),
      coalesce(sum(l.amount) filter (where l.component_code = 'TEACHING_PER_SESSION'),0),
      coalesce(
        sum(
          (l.source_snapshot->>'duration_hours')::numeric
        ) filter (
          where l.component_code = 'TEACHING_PER_SESSION'
            and l.source_snapshot ? 'duration_hours'
        ),
        0
      )
      into
        earnings_value,
        reimbursement_value,
        deduction_value,
        base_salary_value,
        teaching_value,
        teaching_hours_value
    from public.payroll_component_lines_v2 l
    where l.payroll_id = payroll_id_value;

    update public.teacher_payrolls
    set
      base_salary = base_salary_value,
      teaching_hours = teaching_hours_value,
      hourly_earnings = teaching_value,
      v2_earnings_amount = earnings_value,
      v2_reimbursement_amount = reimbursement_value,
      v2_deduction_amount = deduction_value,
      calculation_version = 'PAYROLL_V2_1'
    where id = payroll_id_value;
  end loop;

  if staff_count_value = 0 then
    raise exception 'PAYROLL_V2_NO_ELIGIBLE_STAFF';
  end if;

  select coalesce(sum(t.v2_net_amount),0)
    into total_net_value
  from public.teacher_payrolls t
  where t.period_id = p.id;

  update public.payroll_periods
  set
    status = 'GENERATED',
    generated_by = auth.uid(),
    generated_at = clock_timestamp(),
    version = version + 1
  where id = p.id;

  after_state := public.payroll_approval_snapshot(p.id);

  insert into public.payroll_events(
    period_id,
    status,
    note,
    actor_id,
    event_type,
    before_snapshot,
    after_snapshot
  )
  values(
    p.id,
    'GENERATED',
    'Payroll V2.1 generated from Staff Compensation Components and actual COMPLETED teaching sessions',
    auth.uid(),
    'GENERATED',
    before_state,
    after_state
  );

  return jsonb_build_object(
    'status','GENERATED',
    'calculation_version','PAYROLL_V2_1',
    'period_id',p.id,
    'branch_id',p.branch_id,
    'staff_count',staff_count_value,
    'component_line_count',line_count_value,
    'completed_teaching_session_count',completed_session_count,
    'total_net_amount',total_net_value,
    'currency',
      case
        when (
          select count(distinct t.currency)
          from public.teacher_payrolls t
          where t.period_id = p.id
        ) = 1
        then (
          select min(t.currency)
          from public.teacher_payrolls t
          where t.period_id = p.id
        )
        else null
      end
  );
end;
$$;


ALTER FUNCTION "public"."generate_staff_payroll_v2"("p_period" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."generate_staff_payroll_v2"("p_period" "uuid") IS 'Generates one Staff payroll header per eligible employee from Staff Compensation Components. V2.1 supports FIXED_AMOUNT and actual COMPLETED TEACHING_PER_SESSION only. Refuses empty generation.';



CREATE OR REPLACE FUNCTION "public"."generate_teacher_payroll"("p_period" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare p public.payroll_periods; r record; s record; rule public.teacher_compensation_rules;
 eid uuid; pid uuid; evidence jsonb; amount numeric; v public.employee_versions;
begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Unauthorized';end if;
 select * into p from public.payroll_periods where id=p_period for update;
 if not found then raise exception 'Payroll period not found';end if;
 if p.status='GENERATED' then return;end if;
 if p.status<>'DRAFT' then raise exception 'Payroll generation requires DRAFT';end if;
 lock table public.teacher_compensation_rules in share mode;
 -- Serialize HR evidence changes with the employee attendance approval lock.
 perform 1 from public.employees order by id for update;
 if exists(select 1 from public.payroll_adjustments a join public.teacher_payrolls t on t.id=a.payroll_id where t.period_id=p.id) then raise exception 'Payroll with adjustments cannot regenerate; use correction adjustment';end if;
 if exists(select 1 from public.teacher_compensation_rules coverage where coverage.branch_id=p.branch_id and coverage.status='ACTIVE' and coverage.effective_from<=p.ends_on and coalesce(coverage.effective_to,p.ends_on)>=p.starts_on group by coalesce(coverage.employee_id,coverage.teacher_id) having count(distinct coverage.pay_type)>1 or count(distinct coverage.currency)>1 or bool_or(coverage.pay_type='MONTHLY' and (coverage.effective_from>p.starts_on or coalesce(coverage.effective_to,p.ends_on)<p.ends_on))) then raise exception 'Monthly rule must cover full period; pay type and currency cannot change within period';end if;
 delete from public.payroll_earning_lines where payroll_id in(select id from public.teacher_payrolls where period_id=p.id);
 delete from public.teacher_payrolls where period_id=p.id;
 for r in select coalesce(c.employee_id,e.id) employee_id,c.teacher_id,min(c.pay_type) pay_type,min(c.currency) currency
  from public.teacher_compensation_rules c left join public.employees e on e.teacher_id=c.teacher_id
  where c.branch_id=p.branch_id and c.status='ACTIVE' and c.effective_from<=p.ends_on and coalesce(c.effective_to,p.ends_on)>=p.starts_on
  group by coalesce(c.employee_id,e.id),c.teacher_id loop
  eid:=r.employee_id;
  if r.pay_type='MONTHLY' and eid is null then raise exception 'Monthly payroll requires linked Employee Master and approved attendance';end if;
  if eid is not null then v:=hr_private.employee_at(eid,p.ends_on);end if;
  insert into public.teacher_payrolls(period_id,teacher_id,employee_id,branch_id,teacher_name,pay_type,currency)
   values(p.id,r.teacher_id,eid,p.branch_id,coalesce(case when eid is not null then v.full_name end,(select coalesce(full_name,teacher_code) from public.teachers where id=r.teacher_id)),r.pay_type,r.currency) returning id into pid;
  if r.pay_type='MONTHLY' then
   select * into strict rule from public.teacher_compensation_rules c where c.branch_id=p.branch_id and c.status='ACTIVE' and c.pay_type='MONTHLY' and (c.employee_id=eid or c.teacher_id=r.teacher_id) and c.effective_from<=p.starts_on and coalesce(c.effective_to,p.ends_on)>=p.ends_on;
   evidence:=hr_private.monthly_payroll_evidence(eid,p.starts_on,p.ends_on);
   if exists(select 1 from jsonb_array_elements(evidence->'sources') x left join public.organization_units u on u.code=x->'schedule'->>'unit_code' where u.branch_id is distinct from p.branch_id) then raise exception 'Monthly assignment crosses payroll branch; review required';end if;
   amount:=round(rule.rate*(evidence->>'payable_minutes')::numeric/(evidence->>'required_minutes')::numeric,2);
   insert into public.payroll_earning_lines(payroll_id,actual_teacher_id,employee_id,branch_id,earned_on,rule_id,earning_type,rate,amount,calculation_snapshot)
    values(pid,r.teacher_id,eid,p.branch_id,p.starts_on,rule.id,'MONTHLY_BASE',rule.rate,amount,evidence||jsonb_build_object('salary_rule',to_jsonb(rule)));
  end if;
 end loop;
 for s in select a.*,c.class_type from public.session_actual_teachers a join public.classes c on c.id=a.class_id
  where a.branch_id=p.branch_id and a.occurrence_date between p.starts_on and p.ends_on and a.status='COMPLETED' and a.ends_at<=now() order by a.occurrence_date,a.session_id loop
  select * into rule from public.teacher_compensation_rules c where c.teacher_id=s.teacher_id and c.branch_id=p.branch_id and c.status='ACTIVE'
   and s.occurrence_date>=c.effective_from and (c.effective_to is null or s.occurrence_date<=c.effective_to)
   and (c.class_type is null or c.class_type=s.class_type);
  if not found then
   select c.* into rule from public.teacher_compensation_rules c join public.employees e on e.id=c.employee_id where e.teacher_id=s.teacher_id and c.branch_id=p.branch_id and c.status='ACTIVE' and s.occurrence_date>=c.effective_from and (c.effective_to is null or s.occurrence_date<=c.effective_to);
  end if;
  if rule.id is null then raise exception 'Completed session has unresolved teacher or compensation';end if;
  select t.id,t.employee_id into pid,eid from public.teacher_payrolls t where t.period_id=p.id and (t.teacher_id=s.teacher_id or t.employee_id=rule.employee_id);
  if pid is null then raise exception 'Completed session has unresolved teacher or compensation';end if;
  amount:=case rule.pay_type when 'PER_SESSION' then rule.rate when 'HOURLY' then round(extract(epoch from(s.ends_at-s.starts_at))/3600*rule.rate,2) else 0 end;
  insert into public.payroll_earning_lines(payroll_id,session_id,actual_teacher_id,employee_id,class_id,branch_id,earned_on,rule_id,earning_type,duration_hours,rate,amount,calculation_snapshot)
   values(pid,s.session_id,s.teacher_id,eid,s.class_id,s.branch_id,s.occurrence_date,rule.id,'TEACHING',extract(epoch from(s.ends_at-s.starts_at))/3600,rule.rate,amount,
   jsonb_build_object('calculation_version','PAYROLL_V11','pay_type',rule.pay_type,'session',to_jsonb(s),'salary_rule',to_jsonb(rule)));
 end loop;
 update public.teacher_payrolls t set base_salary=x.base,teaching_hours=x.hours,hourly_earnings=x.teaching,gross_amount=x.base+x.teaching from
  (select t2.id,coalesce(sum(l.amount) filter(where l.earning_type='MONTHLY_BASE'),0) base,coalesce(sum(l.duration_hours),0) hours,coalesce(sum(l.amount) filter(where l.earning_type='TEACHING'),0) teaching from public.teacher_payrolls t2 left join public.payroll_earning_lines l on l.payroll_id=t2.id where t2.period_id=p.id group by t2.id) x where t.id=x.id;
 update public.payroll_periods set status='GENERATED',generated_by=auth.uid(),generated_at=now(),version=version+1 where id=p.id;
 insert into public.payroll_events(period_id,status,note,actor_id,event_type) values(p.id,'GENERATED','Payroll V1.1: approved scheduled minutes and actual completed teaching',auth.uid(),'GENERATED');
end$$;


ALTER FUNCTION "public"."generate_teacher_payroll"("p_period" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_tuition_reminders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  t record;
  created integer := 0;
  affected integer;
  today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
begin
  if not coalesce(public.has_role('SUPER_ADMIN'), false) then
    raise exception 'SUPER_ADMIN role required';
  end if;
  for t in
    select et.id, et.starts_on, et.duration_months_snapshot, e.id as enrollment_id
    from enrollment_tuition et
    join enrollments e on e.id = et.enrollment_id
    where e.status = 'ACTIVE'
      and et.status in ('ACTIVE', 'SCHEDULED')
      and et.starts_on <= today
      and et.effective_ends_on >= today
      and et.duration_months_snapshot in (3, 12)
    order by et.id
    for update of et, e
  loop
    insert into tuition_reminders(enrollment_tuition_id, event_code, window_start, window_end)
      select t.id, 'RENEWAL_V1', w.window_start, w.window_end
      from tuition_reminder_window(t.starts_on, t.duration_months_snapshot) w
      on conflict (enrollment_tuition_id, event_code) do nothing;
    get diagnostics affected = row_count;
    created := created + affected;
    if t.duration_months_snapshot in (3, 12) and exists (
      select 1
      from registration_applications a
      join registration_deposit_terms d on d.application_id = a.id
      where a.linked_enrollment_id = t.enrollment_id
        and a.status = 'COMPLETED'
        and d.payment_option = 'DEPOSIT_50'
    ) then
      insert into tuition_reminders(enrollment_tuition_id, event_code, window_start, window_end)
        select t.id, 'BALANCE_50_V1', w.window_start, w.window_end
        from tuition_balance_due_window(t.starts_on, t.duration_months_snapshot) w
        on conflict (enrollment_tuition_id, event_code) do nothing;
      get diagnostics affected = row_count;
      created := created + affected;
    end if;
  end loop;
  return created;
end $$;


ALTER FUNCTION "public"."generate_tuition_reminders"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_attendance_qr_manageable_branches"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  result jsonb;
begin
  if auth.uid() is null
     or not coalesce(
       public.account_is_active(),
       false
     )
  then
    raise exception 'QR_ATTENDANCE_UNAUTHORIZED';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', b.id,
        'code', b.code,
        'name', b.name
      )
      order by b.name, b.id
    ),
    '[]'::jsonb
  )
  into result
  from public.branches b
  where b.status = 'ACTIVE'
    and (
      coalesce(
        public.is_global_super_admin(),
        false
      )
      or coalesce(
        public.has_permission(
          'attendance.manage',
          b.id
        ),
        false
      )
    );

  return result;
end;
$$;


ALTER FUNCTION "public"."get_attendance_qr_manageable_branches"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_attendance_qr_recent_scans"("p_branch" "uuid", "p_limit" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  safe_limit integer;
  result jsonb;
begin
  if auth.uid() is null
     or not coalesce(
       public.account_is_active(),
       false
     )
  then
    raise exception 'QR_ATTENDANCE_UNAUTHORIZED';
  end if;

  if not (
    coalesce(
      public.is_global_super_admin(),
      false
    )
    or coalesce(
      public.has_permission(
        'attendance.manage',
        p_branch
      ),
      false
    )
  ) then
    raise exception 'QR_ATTENDANCE_MANAGE_DENIED';
  end if;

  safe_limit :=
    least(
      greatest(
        coalesce(p_limit,30),
        1
      ),
      100
    );

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id',
          x.id,

        'employee_id',
          x.employee_id,

        'employee_code',
          d.employee_code,

        'employee_name',
          d.full_name,

        'branch_id',
          x.branch_id,

        'work_date',
          x.work_date,

        'shift_code',
          x.shift_code,

        'event_type',
          x.event_type,

        'scanned_at',
          x.scanned_at,

        'verification_method',
          x.verification_method,

        'verification_status',
          case
            when x.event_type='CHECK_IN'
              then 'WAITING_CHECK_OUT'
            else coalesce(
              v.verification_status,
              'PENDING'
            )
          end
      )
      order by x.scanned_at desc,x.id desc
    ),
    '[]'::jsonb
  )
  into result
  from (
    select e.*
    from public.employee_attendance_scan_events e
    where e.branch_id=p_branch
    order by e.scanned_at desc,e.id desc
    limit safe_limit
  ) x
  left join public.employee_directory d
    on d.id=x.employee_id
  left join public.employee_attendance_qr_verifications v
    on v.check_out_event_id=x.id;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_attendance_qr_recent_scans"("p_branch" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_attendance_qr_status"("p_branch" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  today_vn date;

  session_row
    public.attendance_qr_sessions%rowtype;
begin
  if auth.uid() is null
     or not coalesce(
       public.account_is_active(),
       false
     )
  then
    raise exception 'QR_ATTENDANCE_UNAUTHORIZED';
  end if;

  if not (
    coalesce(
      public.is_global_super_admin(),
      false
    )
    or coalesce(
      public.has_permission(
        'attendance.manage',
        p_branch
      ),
      false
    )
  ) then
    raise exception 'QR_ATTENDANCE_MANAGE_DENIED';
  end if;

  today_vn :=
    (
      clock_timestamp()
      at time zone 'Asia/Ho_Chi_Minh'
    )::date;

  select s.*
  into session_row
  from public.attendance_qr_sessions s
  where s.branch_id = p_branch
    and s.work_date = today_vn
    and s.status = 'ACTIVE'
  limit 1;

  if not found then
    return jsonb_build_object(
      'status', 'INACTIVE',
      'branch_id', p_branch,
      'work_date', today_vn
    );
  end if;

  return jsonb_build_object(
    'status', 'ACTIVE',
    'session_id', session_row.id,
    'branch_id', session_row.branch_id,
    'work_date', session_row.work_date,
    'started_at', session_row.started_at
  );
end;
$$;


ALTER FUNCTION "public"."get_attendance_qr_status"("p_branch" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_attendance_qr_verified_entries"("p_employee" "uuid", "p_from" "date", "p_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  result jsonb;
begin
  if auth.uid() is null
     or not coalesce(
       public.account_is_active(),
       false
     )
     or not coalesce(
       public.has_role('SUPER_ADMIN'),
       false
     )
  then
    raise exception 'QR_ATTENDANCE_READ_DENIED';
  end if;

  if p_employee is null
     or p_from is null
     or p_to is null
     or p_to<p_from
     or p_to-p_from>62
  then
    raise exception
      'QR_ATTENDANCE_INVALID_RANGE';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'attendance_entry_id',
          v.attendance_entry_id,

        'work_date',
          v.work_date,

        'shift_code',
          v.shift_code,

        'verification_method',
          v.verification_method,

        'verification_status',
          v.verification_status,

        'verified_at',
          v.verified_at
      )
      order by v.work_date,v.shift_code
    ),
    '[]'::jsonb
  )
  into result
  from public.employee_attendance_qr_verifications v
  where v.employee_id=p_employee
    and v.work_date between p_from and p_to
    and v.verification_status='VERIFIED';

  return result;
end;
$$;


ALTER FUNCTION "public"."get_employee_attendance_qr_verified_entries"("p_employee" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


