CREATE OR REPLACE FUNCTION "public"."guard_enrollment_class_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_code text;
begin
  if new.status not in ('ACTIVE', 'PAUSED') then
    return new;
  end if;

  -- Allow historical rows that already exist when only non-status fields change is N/A on INSERT.
  v_code := public.class_enrollment_compatibility(new.class_id, new.student_id);

  if v_code = 'IN_SCOPE' then
    return new;
  end if;

  raise exception 'Enrollment blocked: %', v_code
    using errcode = 'P0001';
end;
$$;


ALTER FUNCTION "public"."guard_enrollment_class_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_enrollment_class_scope_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_code text;
begin
  if new.status in ('ACTIVE', 'PAUSED')
     and old.status is distinct from new.status
     and old.status not in ('ACTIVE', 'PAUSED') then
    v_code := public.class_enrollment_compatibility(new.class_id, new.student_id);
    if v_code <> 'IN_SCOPE' then
      raise exception 'Enrollment blocked: %', v_code
        using errcode = 'P0001';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_enrollment_class_scope_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_enrollment_pause_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  enrollment public.enrollments%rowtype;
begin

  if tg_op = 'DELETE' then
    raise exception
      'Pause history cannot be deleted; cancel the pause instead';
  end if;


  if tg_op = 'UPDATE' then

    if
      old.status = 'CANCELLED'
      or new.enrollment_id <> old.enrollment_id
      or new.starts_on <> old.starts_on
      or new.ends_on <> old.ends_on
      or new.reason <> old.reason
    then
      raise exception
        'Pause dates and history cannot be edited; cancel and create a new pause';
    end if;

  end if;


  select *
  into enrollment
  from public.enrollments
  where id = new.enrollment_id
  for update;


  if tg_op = 'INSERT' then

    if enrollment.status <> 'ACTIVE' then
      raise exception
        'Only active enrollments can receive a new pause';
    end if;


    if enrollment.started_at is null then
      raise exception
        'An enrollment must have a study start date before it can be paused';
    end if;


    if
      new.starts_on < enrollment.started_at
      or (
        enrollment.ended_at is not null
        and new.ends_on > enrollment.ended_at
      )
    then
      raise exception
        'Pause dates must fall within the enrollment study period';
    end if;

  end if;


  if
    tg_op = 'INSERT'
    or new.status is distinct from old.status
  then

    perform occurrence.id
    from public.session_occurrences occurrence

    join public.schedules schedule
      on schedule.id = occurrence.schedule_id

    where schedule.class_id = enrollment.class_id

      and occurrence.occurrence_type = 'REGULAR'

      and occurrence.occurrence_date
        between new.starts_on and new.ends_on

    order by occurrence.id
    for update of occurrence;


    if exists (

      select 1
      from public.session_occurrences occurrence

      join public.schedules schedule
        on schedule.id = occurrence.schedule_id

      where schedule.class_id = enrollment.class_id

        and occurrence.occurrence_type = 'REGULAR'

        and occurrence.occurrence_date
          between new.starts_on and new.ends_on

        and (
          occurrence.status <> 'SCHEDULED'
          or exists (
            select 1
            from public.attendance_records attendance
            where attendance.session_occurrence_id =
                occurrence.id
              and attendance.enrollment_id =
                new.enrollment_id
          )
        )

    ) then
      raise exception
        'Pause changes are blocked for dates with recorded attendance or finalized regular sessions';
    end if;

  end if;


  return new;
end;
$$;


ALTER FUNCTION "public"."guard_enrollment_pause_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_enrollment_tuition_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_discount_type text;
  v_discount_value numeric(14,2);
  v_discount_amount numeric(14,2);
  v_amount numeric(14,2);
  v_invoice_exists boolean;
begin

  -- -------------------------------------------------------
  -- Immutable historical identity / snapshots.
  -- -------------------------------------------------------

  if new.enrollment_id <>
       old.enrollment_id

     or new.tuition_plan_id <>
        old.tuition_plan_id

     or new.starts_on <>
        old.starts_on

     or new.base_ends_on <>
        old.base_ends_on

     or new.plan_code_snapshot <>
        old.plan_code_snapshot

     or new.plan_name_snapshot <>
        old.plan_name_snapshot

     or new.duration_months_snapshot <>
        old.duration_months_snapshot

     or new.branch_id_snapshot <>
        old.branch_id_snapshot

     or new.branch_code_snapshot <>
        old.branch_code_snapshot

     or new.branch_name_snapshot <>
        old.branch_name_snapshot

     or new.list_price <>
        old.list_price

     or new.currency <>
        old.currency
  then
    raise exception
      'Core tuition term snapshots are immutable';
  end if;


  -- -------------------------------------------------------
  -- Pause Engine may extend effective_ends_on.
  -- It may never shrink below contractual base_ends_on.
  -- -------------------------------------------------------

  if new.effective_ends_on <
     old.base_ends_on
  then
    raise exception
      'Effective tuition end cannot be earlier than the base tuition end';
  end if;


  -- -------------------------------------------------------
  -- Normalize requested discount.
  -- -------------------------------------------------------

  v_discount_type :=
    upper(
      coalesce(
        nullif(
          btrim(
            new.discount_type
          ),
          ''
        ),
        'NONE'
      )
    );


  v_discount_value :=
    coalesce(
      new.discount_value,
      0
    );


  if v_discount_type = 'NONE' then

    v_discount_value := 0;
    new.discount_name := null;

  elsif v_discount_type in (
    'PERCENT',
    'FIXED'
  ) then

    if new.discount_name is null
       or btrim(
         new.discount_name
       ) = ''
    then
      raise exception
        'Discount name is required when a discount is applied';
    end if;


    new.discount_name :=
      btrim(
        new.discount_name
      );

  else

    raise exception
      'Invalid tuition discount type: %',
      v_discount_type;

  end if;


  v_discount_amount :=
    public.calculate_tuition_discount_amount(
      old.list_price,
      v_discount_type,
      v_discount_value
    );


  v_amount :=
    round(
      old.list_price
      - v_discount_amount,
      2
    );


  -- -------------------------------------------------------
  -- Invoice snapshot boundary.
  --
  -- Once any invoice exists for this tuition term, pricing
  -- history is closed. Later financial corrections must use
  -- adjustment / credit / refund records.
  -- -------------------------------------------------------

  select exists (
    select 1
    from public.invoices
    where enrollment_tuition_id =
      old.id
  )
  into v_invoice_exists;


  if v_invoice_exists
     and (
       v_discount_type is distinct from
         old.discount_type

       or v_discount_value is distinct from
         old.discount_value

       or new.discount_name is distinct from
         old.discount_name

       or v_discount_amount is distinct from
         old.discount_amount

       or v_amount is distinct from
         old.amount
     )
  then
    raise exception
      'Tuition discount cannot change after invoice creation';
  end if;


  -- -------------------------------------------------------
  -- Apply normalized values.
  -- -------------------------------------------------------

  new.discount_type :=
    v_discount_type;

  new.discount_value :=
    v_discount_value;

  new.discount_amount :=
    v_discount_amount;

  new.amount :=
    v_amount;


  return new;

end;
$$;


ALTER FUNCTION "public"."guard_enrollment_tuition_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_future_academic_progress"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_level_started_at timestamptz;
begin
  if tg_table_name = 'student_subject_progress' then
    select slp.started_at into v_level_started_at
    from public.student_level_progress slp
    where slp.id = new.level_progress_id;
  elsif tg_table_name = 'student_component_progress' then
    select slp.started_at into v_level_started_at
    from public.student_subject_progress ssp
    join public.student_level_progress slp on slp.id = ssp.level_progress_id
    where ssp.id = new.subject_progress_id;
  else
    raise exception 'Unsupported academic progress table';
  end if;

  if v_level_started_at is null then
    raise exception 'Academic level has no start date';
  end if;

  if v_level_started_at > now()
     and (new.status is distinct from 'NOT_STARTED' or new.score is not null or new.passed_at is not null) then
    raise exception 'Academic progress cannot be updated before the scheduled start date';
  end if;

  return new;
end;
$$;


