CREATE OR REPLACE FUNCTION "public"."guard_invoice_cancellation_with_payments"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if old.status is distinct from
      new.status
    and new.status =
      'CANCELLED'
    and exists (
      select 1
      from public.payment_allocations
        as allocation
      join public.payments
        as payment
        on payment.id =
          allocation.payment_id
      where allocation.invoice_id =
        old.id
        and payment.status =
          'POSTED'
    )
  then
    raise exception
      'Cannot cancel an invoice with posted payment allocations';
  end if;


  return new;
end;
$$;


