CREATE OR REPLACE FUNCTION "public"."guard_invoice_item_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_invoice_status text;
begin
  if tg_op = 'UPDATE'
    or tg_op = 'DELETE'
  then
    raise exception
      'Invoice items are immutable';
  end if;


  select invoice.status
  into v_invoice_status
  from public.invoices as invoice
  where invoice.id = new.invoice_id;


  if not found then
    raise exception
      'Invoice not found';
  end if;


  if v_invoice_status <> 'DRAFT' then
    raise exception
      'Invoice items can only be created while invoice is in DRAFT status';
  end if;


  return new;
end;
$$;


