CREATE OR REPLACE FUNCTION "public"."guard_learning_report"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'Report is immutable';
  end if;

  if old.status in ('PUBLISHED', 'CANCELLED') then
    raise exception 'Report is immutable';
  end if;

  -- Once approved, the only allowed mutation is publication.
  if old.status = 'APPROVED' then
    if new.status <> 'PUBLISHED'
       or new.sent_at is null
       or new.snapshot_data is distinct from old.snapshot_data
       or new.teacher_summary is distinct from old.teacher_summary
       or new.admin_note is distinct from old.admin_note
       or new.approved_at is distinct from old.approved_at
       or new.approved_by is distinct from old.approved_by then
      raise exception 'Report is immutable';
    end if;
  end if;

  if (
    new.student_id,
    new.enrollment_id,
    new.curriculum_enrollment_id,
    new.branch_id,
    new.report_type,
    new.period_start,
    new.period_end
  )
  is distinct from (
    old.student_id,
    old.enrollment_id,
    old.curriculum_enrollment_id,
    old.branch_id,
    old.report_type,
    old.period_start,
    old.period_end
  ) then
    raise exception 'Report identity is immutable';
  end if;

  return new;
end
$$;


ALTER FUNCTION "public"."guard_learning_report"() OWNER TO "postgres";


