CREATE OR REPLACE FUNCTION "public"."guard_payroll_history"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare pid uuid; state text;
begin
 if tg_table_name='payroll_periods' then
 if old.status='FINALIZED' or (old.status='APPROVED' and (tg_op='DELETE' or new.status<>'FINALIZED' or (to_jsonb(new)-array['status','version','finalized_by','finalized_at']) is distinct from (to_jsonb(old)-array['status','version','finalized_by','finalized_at']))) then raise exception 'Approved payroll is immutable'; end if;
 elsif tg_table_name='teacher_payrolls' then
 if tg_op='UPDATE' and (new.period_id is distinct from old.period_id or new.teacher_id is distinct from old.teacher_id or new.branch_id is distinct from old.branch_id) then raise exception 'Payroll identity is immutable'; end if;
 pid:=case when tg_op='INSERT' then new.period_id else old.period_id end;
 else
 if tg_op='UPDATE' and new.payroll_id is distinct from old.payroll_id then raise exception 'Payroll identity is immutable'; end if;
 select period_id into pid from teacher_payrolls where id=case when tg_op='INSERT' then new.payroll_id else old.payroll_id end;
 end if;
 if pid is not null then
 select status into state from payroll_periods where id=pid;
 if state in ('APPROVED','FINALIZED') then raise exception 'Approved payroll is immutable'; end if;
 end if;
 if tg_table_name='payroll_adjustments' and tg_op in ('UPDATE','DELETE') then
 if tg_op='DELETE' or (to_jsonb(new)-array['approved_by','approved_at']) is distinct from (to_jsonb(old)-array['approved_by','approved_at']) then raise exception 'Adjustment history is immutable'; end if;
 end if;
 if tg_op='DELETE' then return old; end if;
 return new;
end $$;


ALTER FUNCTION "public"."guard_payroll_history"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_payroll_pending_retroactive_close"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  if new.status in ('APPROVED','FINALIZED')
     and new.status is distinct from old.status
     and exists (
       select 1
       from public.payroll_retroactive_claims r
       where r.target_period_id = new.id
         and r.status = 'APPROVED'
         and r.posted_action_id is null
     )
  then
    raise exception
      'PAYROLL_RETROACTIVE_PENDING_BLOCKS_CLOSE';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_payroll_pending_retroactive_close"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_payroll_period_action_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  period_state text;
begin
  if tg_op = 'DELETE' then
    raise exception
      'PAYROLL_V2_PERIOD_ACTION_DELETE_FORBIDDEN';
  end if;

  select p.status
  into period_state
  from public.payroll_periods p
  where p.id = old.period_id;

  if period_state in ('APPROVED','FINALIZED') then
    raise exception
      'PAYROLL_V2_APPROVED_PERIOD_ACTION_IMMUTABLE';
  end if;

  if new.period_id is distinct from old.period_id
     or new.employee_id is distinct from old.employee_id
     or new.component_code is distinct from old.component_code
     or new.category is distinct from old.category
     or new.source_type is distinct from old.source_type
     or new.source_expense_claim_id
          is distinct from old.source_expense_claim_id
     or new.source_retroactive_claim_id
          is distinct from old.source_retroactive_claim_id
     or new.amount is distinct from old.amount
     or new.currency is distinct from old.currency
     or new.reason is distinct from old.reason
     or new.request_key is distinct from old.request_key
     or new.request_payload is distinct from old.request_payload
     or new.source_snapshot is distinct from old.source_snapshot
     or new.created_by is distinct from old.created_by
     or new.created_at is distinct from old.created_at
  then
    raise exception
      'PAYROLL_V2_PERIOD_ACTION_IDENTITY_IMMUTABLE';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_payroll_period_action_v2"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_placement_enrollment_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare c classes%rowtype; code text;
begin
 if tg_op='UPDATE' then
   if new.class_id is distinct from old.class_id or new.student_id is distinct from old.student_id then
     if coalesce(old.started_at,old.enrolled_at)<=registration_vietnam_today() or placement_learning_history_exists(old.id) then
       raise exception 'PLACEMENT_HISTORY_LOCKED';
     end if;
   end if;
   if (new.class_id,new.student_id,new.started_at,new.status) is not distinct from (old.class_id,old.student_id,old.started_at,old.status) then return new; end if;
   if new.status='PAUSED' and old.status='ACTIVE' and new.class_id=old.class_id and new.student_id=old.student_id and new.started_at is not distinct from old.started_at then return new; end if;
 end if;
 if new.status not in ('ACTIVE','PAUSED') then return new; end if;
 select * into c from classes where id=new.class_id for update;
 perform 1 from students where id=new.student_id for update;
 if c.id is null or c.status<>'ACTIVE' then raise exception 'PLACEMENT_CLASS_DENIED'; end if;
 if new.started_at is null or (c.start_date is not null and new.started_at<c.start_date) or (c.end_date is not null and new.started_at>c.end_date) then raise exception 'PLACEMENT_START_DENIED'; end if;
 if exists(select 1 from students where id=new.student_id and (status<>'ACTIVE' or default_branch_id is distinct from c.branch_id)) then raise exception 'PLACEMENT_CLASS_DENIED'; end if;
 if exists(select 1 from enrollments where class_id=c.id and student_id=new.student_id and id<>new.id and status in ('ACTIVE','PAUSED')) then raise exception 'PLACEMENT_ALREADY_ENROLLED'; end if;
 if (select count(*) from enrollments where class_id=c.id and id<>new.id and status in ('ACTIVE','PAUSED'))>=c.capacity then raise exception 'PLACEMENT_CLASS_FULL'; end if;
 code:=class_enrollment_compatibility(c.id,new.student_id);
 if code<>'IN_SCOPE' then raise exception 'PLACEMENT_LEVEL_DENIED'; end if;
 code:=placement_schedule_check(c.id,new.student_id,new.started_at,new.ended_at,new.id);
 if code<>'CLEAR' then raise exception '%',code; end if;
 return new;
end $$;


ALTER FUNCTION "public"."guard_placement_enrollment_integrity"() OWNER TO "postgres";


