ALTER FUNCTION "public"."guard_refund_allocation_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_refund_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.refund_number <>
      old.refund_number
    or new.payment_id <>
      old.payment_id
    or new.student_id_snapshot <>
      old.student_id_snapshot
    or new.branch_id_snapshot <>
      old.branch_id_snapshot
    or new.branch_code_snapshot <>
      old.branch_code_snapshot
    or new.branch_name_snapshot <>
      old.branch_name_snapshot
    or new.amount <>
      old.amount
    or new.currency <>
      old.currency
    or new.refunded_at <>
      old.refunded_at
    or new.reason <>
      old.reason
    or new.created_by is distinct from
      old.created_by
    or new.created_at <>
      old.created_at
  then
    raise exception
      'Refund financial snapshots are immutable';
  end if;


  if old.status = 'VOIDED' then
    raise exception
      'Voided refunds are immutable';
  end if;


  if new.status is distinct from
    old.status
  then
    if not (
      old.status = 'POSTED'
      and new.status = 'VOIDED'
    )
    then
      raise exception
        'Invalid refund status transition from % to %',
        old.status,
        new.status;
    end if;
  end if;


  return new;
end;
$$;


ALTER FUNCTION "public"."guard_refund_update"() OWNER TO "postgres";


