CREATE OR REPLACE FUNCTION "public"."invalidate_tuition_reminders"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if tg_table_name='enrollment_tuition' and new.status in ('COMPLETED','CANCELLED') then
    update tuition_reminders set status='CANCELLED',marked_at=now(),marked_by=auth.uid(),reason='Kỳ học phí đã kết thúc hoặc bị hủy'
      where enrollment_tuition_id=new.id and status='PENDING';
  elsif tg_table_name='enrollments' and new.status<>'ACTIVE' then
    update tuition_reminders set status='CANCELLED',marked_at=now(),marked_by=auth.uid(),reason='Ghi danh không còn hoạt động'
      where enrollment_tuition_id in (select id from enrollment_tuition where enrollment_id=new.id) and status='PENDING';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."invalidate_tuition_reminders"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."inventory_monthly_report"("p_branch" "uuid", "p_month" "date", "p_offset" integer DEFAULT 0) RETURNS TABLE("item_id" "uuid", "code" "text", "name" "text", "unit" "text", "opening" numeric, "inbound" numeric, "outbound" numeric, "closing" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare start_at timestamptz; end_at timestamptz;
begin
 if not public.has_permission('inventory.view',p_branch) then raise exception 'Unauthorized'; end if;
 if p_month is null or not isfinite(p_month) or extract(day from p_month)<>1 or p_offset is null or p_offset<0 or p_offset>1000000 then raise exception 'Invalid inventory report filter'; end if;
 start_at:=p_month::timestamp at time zone 'Asia/Ho_Chi_Minh';
 end_at:=(p_month+interval '1 month')::timestamp at time zone 'Asia/Ho_Chi_Minh';
 return query select i.id,i.code,i.name,i.unit,
 coalesce(sum(e.delta) filter(where e.created_at<start_at),0),
 coalesce(sum(e.delta) filter(where e.created_at>=start_at and e.delta>0),0),
 coalesce(-sum(e.delta) filter(where e.created_at>=start_at and e.delta<0),0),
 coalesce(sum(e.delta),0)
 from public.inventory_items i left join public.inventory_entries e on e.item_id=i.id and e.branch_id=p_branch and e.created_at<end_at
 group by i.id order by i.code limit 26 offset p_offset;
end$$;


ALTER FUNCTION "public"."inventory_monthly_report"("p_branch" "uuid", "p_month" "date", "p_offset" integer) OWNER TO "postgres";


