CREATE OR REPLACE FUNCTION "public"."issue_invoice"("p_invoice_id" "uuid", "p_issued_on" "date", "p_due_on" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_status text;
begin
  if not public.has_role(
    'SUPER_ADMIN'
  ) then
    raise exception
      'SUPER_ADMIN role required';
  end if;


  if p_invoice_id is null
    or p_issued_on is null
    or p_due_on is null
  then
    raise exception
      'Invoice id, issued date and due date are required';
  end if;


  if p_due_on < p_issued_on then
    raise exception
      'Invoice due date cannot be earlier than issue date';
  end if;


  select invoice.status
  into v_status
  from public.invoices as invoice
  where invoice.id =
    p_invoice_id
  for update;


  if not found then
    raise exception
      'Invoice not found';
  end if;


  if v_status <> 'DRAFT' then
    raise exception
      'Only draft invoices can be issued';
  end if;


  update public.invoices
  set
    status = 'ISSUED',
    issued_on = p_issued_on,
    due_on = p_due_on
  where id =
    p_invoice_id;
end;
$$;


ALTER FUNCTION "public"."issue_invoice"("p_invoice_id" "uuid", "p_issued_on" "date", "p_due_on" "date") OWNER TO "postgres";


