CREATE OR REPLACE FUNCTION "public"."learning_report_source"("p_enrollment_id" "uuid", "p_start" "date", "p_end" "date") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
with context as (
  select e.*, s.full_name,s.student_code,c.branch_id,c.name class_name,b.name branch_name
  from enrollments e join students s on s.id=e.student_id join classes c on c.id=e.class_id join branches b on b.id=c.branch_id
  where e.id=p_enrollment_id
), sessions as (
  select o.id,o.occurrence_type,a.id attendance_id,a.status attendance_status
  from context e join schedules sc on sc.class_id=e.class_id join session_occurrences o on o.schedule_id=sc.id
  left join attendance_records a on a.session_occurrence_id=o.id and a.enrollment_id=e.id
  where o.status = 'COMPLETED'
    and o.starts_at >= (p_start::timestamp at time zone 'Asia/Ho_Chi_Minh')
    and o.starts_at < ((p_end+1)::timestamp at time zone 'Asia/Ho_Chi_Minh')
    and (a.id is not null or
      (o.occurrence_type='MAKEUP' and exists(select 1 from session_occurrence_participants sp where sp.session_occurrence_id=o.id and sp.enrollment_id=e.id)) or
      (o.occurrence_type='REGULAR' and e.started_at <= o.occurrence_date and (e.ended_at is null or e.ended_at>=o.occurrence_date)
        and not exists(select 1 from enrollment_pauses ep where ep.enrollment_id=e.id and ep.status='ACTIVE' and o.occurrence_date between ep.starts_on and ep.ends_on)))
), journal_rows as (
  select j.content,j.repertoire,j.skills,j.homework,j.observation,j.updated_at
  from sessions s join learning_journals j on j.attendance_record_id=s.attendance_id
  where not exists(select 1 from student_learning_journal_entries e where e.attendance_record_id=s.attendance_id)
  union all
  select e.progress_note as content, '' as repertoire, '' as skills, e.individual_homework as homework,
    e.observation, e.updated_at
  from sessions s join student_learning_journal_entries e on e.attendance_record_id=s.attendance_id
  join session_learning_journals j on j.id=e.session_journal_id where j.status='SUBMITTED'
), subjects as (
  select l.name grade,lp.status grade_status,cs.name,cs.is_required,cs.completion_rule,
    coalesce(sp.status,'NOT_STARTED') status,sp.score,
    coalesce((select jsonb_agg(jsonb_build_object('name',cc.name,'required',cc.is_required,'status',coalesce(cp.status,'NOT_STARTED'),'score',cp.score) order by cc.sort_order,cc.id)
      from curriculum_subject_components cc left join student_component_progress cp on cp.component_id=cc.id and cp.subject_progress_id=sp.id
      where cc.subject_id=cs.id and cc.status='ACTIVE' and cs.completion_rule='ALL_REQUIRED_COMPONENTS'),'[]'::jsonb) components
  from context e join student_level_progress lp on lp.enrollment_id=e.student_curriculum_enrollment_id
  join curriculum_levels l on l.id=lp.level_id
  join curriculum_subjects cs on cs.level_id=l.id and cs.status='ACTIVE'
  left join student_subject_progress sp on sp.subject_id=cs.id and sp.level_progress_id=lp.id
)
select jsonb_build_object(
 'schema_version',1,'as_of',now(),'period_start',p_start,'period_end',p_end,
 'student',jsonb_build_object('id',e.student_id,'name',e.full_name,'code',e.student_code),
 'branch',jsonb_build_object('id',e.branch_id,'name',e.branch_name),'class_name',e.class_name,
 'teachers',coalesce((select jsonb_agg(jsonb_build_object('code',t.teacher_code,'name',p.full_name,'role',ct.teacher_role) order by t.teacher_code)
   from class_teachers ct join teachers t on t.id=ct.teacher_id left join profiles p on p.id=t.user_id
   where ct.class_id=e.class_id and ct.assigned_at<=p_end and (ct.ended_at is null or ct.ended_at>=p_start)),'[]'::jsonb),
 'academic',jsonb_build_object('curriculum',cu.name,'current_grade',cl.name,'status',ce.status,
   'subjects',coalesce((select jsonb_agg(to_jsonb(s) order by s.grade,s.name) from subjects s),'[]'::jsonb)),
 'attendance',(select jsonb_build_object('scheduled',count(*),'attended',count(*) filter(where attendance_status in ('PRESENT','LATE')),
   'present',count(*) filter(where attendance_status='PRESENT'),'late',count(*) filter(where attendance_status='LATE'),
   'absent',count(*) filter(where attendance_status='ABSENT'),'excused',count(*) filter(where attendance_status='EXCUSED'),
   'unmarked',count(*) filter(where attendance_status is null),'makeup',count(*) filter(where occurrence_type='MAKEUP'),
   'rate',round(100.0 * count(*) filter(where attendance_status in ('PRESENT','LATE')) / nullif(count(*) filter(where attendance_status is not null),0),1)) from sessions),
 'journals',jsonb_build_object('count',(select count(*) from journal_rows),'excerpts',coalesce((select jsonb_agg(to_jsonb(j)) from (select * from journal_rows order by updated_at desc limit 30) j),'[]'::jsonb))
) from context e left join student_curriculum_enrollments ce on ce.id=e.student_curriculum_enrollment_id
left join curriculums cu on cu.id=ce.curriculum_id left join curriculum_levels cl on cl.id=ce.current_level_id;
$$;


ALTER FUNCTION "public"."learning_report_source"("p_enrollment_id" "uuid", "p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."learning_review_due"("p_submitted" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare d timestamp; remaining integer:=2;
begin
 if p_submitted is null then return null; end if;
 d:=p_submitted at time zone 'Asia/Ho_Chi_Minh';
 while remaining>0 loop
 d:=d+interval '1 day';
 if extract(isodow from d)<6 then remaining:=remaining-1; end if;
 end loop;
 return d at time zone 'Asia/Ho_Chi_Minh';
end$$;


ALTER FUNCTION "public"."learning_review_due"("p_submitted" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."learning_source_access"("p_kind" "text", "p_entity" "uuid") RETURNS TABLE("student_id" "uuid", "branch_id" "uuid", "source_version" integer, "staff" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare s uuid;b uuid;v integer; is_staff boolean; teacher uuid;
begin
 if auth.uid() is null or not account_is_active() then return; end if;
 if p_kind='REPORT' then
  select r.student_id,r.branch_id,r.version into s,b,v from learning_reports r where r.id=p_entity and r.status='PUBLISHED';
 elsif p_kind='FEEDBACK' then
  select f.student_id,f.branch_id,1,f.teacher_id into s,b,v,teacher from lesson_feedback f where f.id=p_entity;
 else return; end if;
 if s is null then return; end if;
 is_staff:=has_role('SUPER_ADMIN') or
  (has_role('BRANCH_ADMIN') and has_permission('students.view',b)) or
  (has_role('ACADEMIC_ADMIN') and has_permission('learning_reports.view',b)) or
  (has_role('TEACHER') and case when p_kind='FEEDBACK' then exists(select 1 from teachers where id=teacher and user_id=auth.uid() and status='ACTIVE') else teacher_can_access_student(s) end);
 if is_staff or can_read_student_history(s,b,case when p_kind='REPORT' then 'learning_reports' else 'attendance' end) then
  return query select s,b,v,is_staff;
 end if;
end$$;


ALTER FUNCTION "public"."learning_source_access"("p_kind" "text", "p_entity" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."learning_version_analytics"("p_version" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v public.learning_versions; lessons jsonb; assessments jsonb;
begin
 if not public.account_is_active() or not public.has_role('SUPER_ADMIN') then raise exception 'Unauthorized'; end if;
 select * into v from public.learning_versions where id=p_version;
 if not found then raise exception 'Learning version not found'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('code',l.value->>'code','title',l.value->>'title',
   'acknowledged_learners',coalesce(p.learners,0)) order by m.ordinality,l.ordinality),'[]') into lessons
 from jsonb_array_elements(v.content->'modules') with ordinality m
 cross join lateral jsonb_array_elements(m.value->'lessons') with ordinality l
 left join (select lesson_code,count(distinct student_id) learners from public.learning_lesson_progress
   where version_id=p_version group by lesson_code) p on p.lesson_code=l.value->>'code';

 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'title',a.title,'kind',a.kind,'policy_state',a.state,
   'attempts',s.attempts,'learners',s.learners,'in_progress',s.in_progress,'pending_review',s.pending_review,
   'passed',s.passed,'failed',s.failed,'average_completed_score',s.average_completed_score)
   order by a.created_at,a.id),'[]') into assessments
 from public.learning_assessments a
 cross join lateral (select count(*) attempts,count(distinct r.student_id) learners,
   count(*) filter(where r.state='IN_PROGRESS') in_progress,
   count(*) filter(where r.state='PENDING_REVIEW') pending_review,
   count(*) filter(where r.state='PASSED') passed,count(*) filter(where r.state='FAILED') failed,
   round(avg(r.score) filter(where r.state in('PASSED','FAILED')),2) average_completed_score
   from public.learning_effective_assessment_results r where r.assessment_id=a.id) s
 where a.version_id=p_version;
 return jsonb_build_object('version_id',v.id,'title',v.title,'version',v.version,'state',v.state,
   'lessons',lessons,'assessments',assessments);
end$$;


ALTER FUNCTION "public"."learning_version_analytics"("p_version" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."legacy_business_snapshot"("p_row" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select jsonb_build_object(
  'student',(select to_jsonb(s) from public.students s where s.id=r.target_student_id),
  'enrollments',(select jsonb_agg(to_jsonb(e) order by e.id) from public.enrollments e where e.student_id=r.target_student_id),
  'academic',(select jsonb_agg(to_jsonb(a) order by a.id) from public.student_curriculum_enrollments a where a.student_id=r.target_student_id),
  'levels',(select jsonb_agg(to_jsonb(l) order by l.id) from public.student_level_progress l join public.student_curriculum_enrollments a on a.id=l.enrollment_id where a.student_id=r.target_student_id),
  'subjects',(select jsonb_agg(to_jsonb(s) order by s.id) from public.student_subject_progress s join public.student_level_progress l on l.id=s.level_progress_id join public.student_curriculum_enrollments a on a.id=l.enrollment_id where a.student_id=r.target_student_id),
  'components',(select jsonb_agg(to_jsonb(c) order by c.id) from public.student_component_progress c join public.student_subject_progress s on s.id=c.subject_progress_id join public.student_level_progress l on l.id=s.level_progress_id join public.student_curriculum_enrollments a on a.id=l.enrollment_id where a.student_id=r.target_student_id),
  'tuition',(select jsonb_agg(to_jsonb(t) order by t.id) from public.enrollment_tuition t join public.enrollments e on e.id=t.enrollment_id where e.student_id=r.target_student_id),
  'pauses',(select jsonb_agg(to_jsonb(p) order by p.id) from public.enrollment_pauses p where p.enrollment_id=r.target_enrollment_id),
  'parents',(select jsonb_agg(to_jsonb(p) order by p.parent_id) from public.student_parents p where p.student_id=r.target_student_id)
 ) from public.migration_batch_rows r where r.id=p_row
$$;


ALTER FUNCTION "public"."legacy_business_snapshot"("p_row" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."legacy_row_errors"("p_row" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare r public.migration_batch_rows%rowtype; b public.migration_batches%rowtype; p jsonb;
 errors jsonb:='[]'; cl record; lev record; plan record; price record;
 start_date date; tuition_start date; baseline_end date; pause_start date; pause_end date; final numeric; paid numeric; debt numeric; calculated numeric;
begin
 select * into r from public.migration_batch_rows where id=p_row;
 select * into b from public.migration_batches where id=r.batch_id;
 p:=r.normalized_payload;
 if nullif(btrim(p->>'full_name'),'') is null or nullif(btrim(p->>'student_code'),'') is null then errors:=errors||'"IDENTITY_REQUIRED"'::jsonb; end if;
 if nullif(btrim(p->>'class_code'),'') is null then errors:=errors||'"CLASS_MAPPING_REQUIRED"'::jsonb; end if;
 select c.id,c.status,co.curriculum_id,co.level_id,co.status as course_status into cl
 from public.classes c join public.courses co on co.id=c.course_id where c.branch_id=b.branch_id and c.code=p->>'class_code';
 if cl.id is null or cl.status not in ('ACTIVE','COMPLETED') or cl.course_status<>'ACTIVE' then errors:=errors||'"CLASS_MAPPING_INVALID"'::jsonb; end if;
 select l.id,l.curriculum_id into lev from public.curriculum_levels l join public.curriculums c on c.id=l.curriculum_id
 where c.code=p->>'curriculum_code' and l.code=p->>'level_code' and l.status='ACTIVE' and c.status='ACTIVE';
 if lev.id is null or cl.curriculum_id is distinct from lev.curriculum_id or (cl.level_id is not null and cl.level_id<>lev.id) then errors:=errors||'"ACADEMIC_MAPPING_INVALID"'::jsonb; end if;
 if not exists(select 1 from public.curriculum_subjects where level_id=lev.id and status='ACTIVE') then errors:=errors||'"ACTIVE_SUBJECTS_REQUIRED"'::jsonb; end if;
 if exists(select 1 from public.curriculum_subjects s where s.level_id=lev.id and s.status='ACTIVE' and s.is_required and s.completion_rule='ALL_REQUIRED_COMPONENTS'
 and not exists(select 1 from public.curriculum_subject_components c where c.subject_id=s.id and c.status='ACTIVE' and c.is_required)) then errors:=errors||'"REQUIRED_COMPONENTS_MISSING"'::jsonb; end if;
 begin
  if coalesce(p->>'started_at','') !~ '^\d{4}-\d{2}-\d{2}$' or coalesce(p->>'tuition_starts_on','') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'date'; end if;
  start_date:=(p->>'started_at')::date; tuition_start:=(p->>'tuition_starts_on')::date;
  if start_date>b.cutover_date or tuition_start<start_date or tuition_start>b.cutover_date then errors:=errors||'"TUITION_BASELINE_DATES_REQUIRE_REVIEW"'::jsonb; end if;
 exception when others then errors:=errors||'"START_DATE_INVALID"'::jsonb; end;
 select id,duration_months into plan from public.tuition_plans where code=p->>'tuition_plan_code' and status='ACTIVE';
 select list_price,currency into price from public.tuition_plan_branch_prices
 where tuition_plan_id=plan.id and status='ACTIVE' and (branch_id=b.branch_id or branch_id is null)
 order by (branch_id is not null) desc limit 1;
 if plan.id is null or price.list_price is null then errors:=errors||'"TUITION_PLAN_MAPPING_INVALID"'::jsonb; end if;
 begin
  if coalesce(p->>'final_amount','') !~ '^\d+(\.\d{1,2})?$' or coalesce(p->>'opening_paid_amount','') !~ '^\d+(\.\d{1,2})?$'
   or coalesce(p->>'opening_outstanding','') !~ '^\d+(\.\d{1,2})?$' then raise exception 'money'; end if;
  final:=(p->>'final_amount')::numeric; paid:=(p->>'opening_paid_amount')::numeric; debt:=(p->>'opening_outstanding')::numeric;
  calculated:=price.list_price-public.calculate_tuition_discount_amount(price.list_price,p->>'discount_type',(p->>'discount_value')::numeric);
  if calculated is null or calculated<>final or paid+debt<>final or paid>final then errors:=errors||'"FINANCE_RECONCILIATION_MISMATCH"'::jsonb; end if;
  if p->>'currency' is distinct from price.currency then errors:=errors||'"CURRENCY_MISMATCH"'::jsonb; end if;
  if p->>'currency'='VND' and (trunc(final)<>final or trunc(paid)<>paid or trunc(debt)<>debt) then errors:=errors||'"VND_FRACTION_NOT_ALLOWED"'::jsonb; end if;
  if p->>'discount_type'<>'NONE' and nullif(btrim(p->>'discount_name'),'') is null then errors:=errors||'"DISCOUNT_EVIDENCE_REQUIRED"'::jsonb; end if;
 exception when others then errors:=errors||'"MONEY_INVALID"'::jsonb; end;
 if coalesce(p->>'student_status','') not in ('ACTIVE','PAUSED','INACTIVE') or coalesce(p->>'tuition_status','') not in ('ACTIVE','PAUSED','EXPIRED','CANCELLED') then errors:=errors||'"STATUS_BASELINE_REQUIRES_REVIEW"'::jsonb; end if;
 begin
  if exists(select 1 from jsonb_each_text(p) x where x.key in ('base_ends_on','effective_ends_on','pause_starts_on','pause_ends_on') and x.value<>'' and x.value !~ '^\d{4}-\d{2}-\d{2}$') then raise exception 'Invalid ISO date'; end if;
  baseline_end:=coalesce(nullif(p->>'effective_ends_on','')::date,public.calculate_tuition_base_end(tuition_start,plan.duration_months));
  if baseline_end<public.calculate_tuition_base_end(tuition_start,plan.duration_months) then errors:=errors||'"EFFECTIVE_END_INVALID"'::jsonb; end if;
  if nullif(p->>'base_ends_on','') is not null and (p->>'base_ends_on')::date<>public.calculate_tuition_base_end(tuition_start,plan.duration_months) then errors:=errors||'"BASE_END_MISMATCH"'::jsonb; end if;
  if p->>'tuition_status'='EXPIRED' and baseline_end>=b.cutover_date then errors:=errors||'"EXPIRED_END_INVALID"'::jsonb; end if;
  if p->>'tuition_status' in ('ACTIVE','PAUSED') and baseline_end<b.cutover_date then errors:=errors||'"ACTIVE_END_INVALID"'::jsonb; end if;
  if p->>'tuition_status'='PAUSED' or p->>'student_status'='PAUSED' then
   pause_start:=nullif(p->>'pause_starts_on','')::date; pause_end:=nullif(p->>'pause_ends_on','')::date;
   if pause_start is null or pause_end is null or pause_start>pause_end or pause_start>b.cutover_date or pause_end<b.cutover_date or pause_start<start_date then errors:=errors||'"PAUSE_BASELINE_REQUIRES_REVIEW"'::jsonb; end if;
   if baseline_end-public.calculate_tuition_base_end(tuition_start,plan.duration_months)<greatest(0,least(pause_end,baseline_end)-greatest(pause_start,tuition_start)+1) then errors:=errors||'"PAUSE_EXTENSION_MISMATCH"'::jsonb; end if;
  elsif nullif(p->>'pause_starts_on','') is not null or nullif(p->>'pause_ends_on','') is not null then errors:=errors||'"PAUSE_STATUS_MISMATCH"'::jsonb;
  end if;
 exception when others then errors:=errors||'"BASELINE_DATE_INVALID"'::jsonb; end;
 if exists(select 1 from public.students s where s.student_code=p->>'student_code' or lower(btrim(s.full_name))=lower(btrim(p->>'full_name')))
 and not exists(select 1 from public.migration_source_mappings m where m.source_system=b.source_system and m.source_entity_type=r.source_entity_type and m.source_reference=r.source_reference and m.payload=p)
 then errors:=errors||'"POSSIBLE_DUPLICATE_REQUIRES_REVIEW"'::jsonb; end if;
 if exists(select 1 from public.migration_source_mappings m where m.source_system=b.source_system and m.source_entity_type=r.source_entity_type and m.source_reference=r.source_reference and m.payload is distinct from p) then errors:=errors||'"SOURCE_ALREADY_IMPORTED_DIFFERENT_PAYLOAD"'::jsonb; end if;
 if exists(select 1 from public.migration_source_mappings m where m.source_system=b.source_system and m.source_entity_type=r.source_entity_type and m.source_reference=r.source_reference and m.status='ROLLED_BACK') then errors:=errors||'"ROLLED_BACK_SOURCE_REQUIRES_CORRECTION"'::jsonb; end if;
 return errors;
end $_$;


ALTER FUNCTION "public"."legacy_row_errors"("p_row" "uuid") OWNER TO "postgres";


