    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$ select 2 $$;


ALTER FUNCTION "public"."lesson_feedback_low_threshold"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lesson_operator_component"("p_curriculum_id" "uuid", "p_level_id" "uuid", "p_subject_id" "uuid", "p_component_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or not public.has_role('SUPER_ADMIN') then
    raise exception 'Unauthorized' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.curriculum_subject_components component
    join public.curriculum_subjects subject on subject.id = component.subject_id
    join public.curriculum_levels level on level.id = subject.level_id
    where component.id = p_component_id
      and subject.id = p_subject_id
      and level.id = p_level_id
      and level.curriculum_id = p_curriculum_id
  ) then
    raise exception 'Invalid academic structure' using errcode = 'P0001';
  end if;

  perform 1
  from public.curriculum_subject_components
  where id = p_component_id
  for update;

  return p_component_id;
end;
$$;


ALTER FUNCTION "public"."lesson_operator_component"("p_curriculum_id" "uuid", "p_level_id" "uuid", "p_subject_id" "uuid", "p_component_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_customer_channel"("p_provider" "text", "p_provider_user_id" "text", "p_external_link_key" "text", "p_registration_application_id" "uuid", "p_parent_id" "uuid", "p_student_id" "uuid", "p_consent_at" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  existing public.customer_channel_links;
  created uuid;
begin
  if auth.uid() is null or not public.has_role('SUPER_ADMIN') then
    raise exception 'Unauthorized';
  end if;
  if p_provider is distinct from 'ZALO' then
    raise exception 'Unsupported provider';
  end if;
  if p_provider_user_id is null or p_provider_user_id !~ '^[0-9]{8,32}$' then
    raise exception 'Invalid Zalo identity';
  end if;
  if p_external_link_key is null or p_external_link_key !~ '^[A-Za-z0-9_-]{6,80}$' then
    raise exception 'Invalid channel key';
  end if;
  if num_nonnulls(p_registration_application_id, p_parent_id, p_student_id) <> 1 then
    raise exception 'Exactly one channel subject';
  end if;
  if p_registration_application_id is not null and not exists(
    select 1 from public.registration_applications where id = p_registration_application_id
  ) then
    raise exception 'Channel subject not found';
  end if;
  if p_parent_id is not null and not exists(
    select 1 from public.parents where id = p_parent_id
  ) then
    raise exception 'Channel subject not found';
  end if;
  if p_student_id is not null and not exists(
    select 1 from public.students where id = p_student_id
  ) then
    raise exception 'Channel subject not found';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('zalo-channel:' || p_provider_user_id, 0));
  select * into existing
  from public.customer_channel_links
  where provider = 'ZALO'
    and status <> 'REVOKED'
    and registration_application_id is not distinct from p_registration_application_id
    and parent_id is not distinct from p_parent_id
    and student_id is not distinct from p_student_id;
  if found then
    if existing.provider_user_id is distinct from p_provider_user_id
      or existing.external_link_key is distinct from p_external_link_key then
      raise exception 'Channel already linked';
    end if;
    return existing.id;
  end if;

  insert into public.customer_channel_links(
    provider, provider_user_id, external_link_key, registration_application_id,
    parent_id, student_id, status, linked_at, consent_at
  ) values (
    'ZALO', p_provider_user_id, p_external_link_key, p_registration_application_id,
    p_parent_id, p_student_id,
    case when p_consent_at is null then 'PENDING' else 'ACTIVE' end,
    case when p_consent_at is null then null else clock_timestamp() end,
    p_consent_at
  )
  returning id into created;
  return created;
exception
  when unique_violation then
    raise exception 'Channel already linked';
end;
$_$;


ALTER FUNCTION "public"."link_customer_channel"("p_provider" "text", "p_provider_user_id" "text", "p_external_link_key" "text", "p_registration_application_id" "uuid", "p_parent_id" "uuid", "p_student_id" "uuid", "p_consent_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_employee_identity"("p_employee" "uuid", "p_profile" "uuid", "p_teacher" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$declare before_row jsonb;begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Employee administration denied'; end if;
 if nullif(btrim(p_reason),'') is null then raise exception 'Reason required'; end if;
 select to_jsonb(e) into before_row from public.employees e where id=p_employee for update;
 if before_row is null then raise exception 'Employee not found'; end if;
 perform hr_private.check_links(p_profile,p_teacher);
 update public.employees set profile_id=p_profile,teacher_id=p_teacher where id=p_employee;
 insert into public.employee_audit(employee_id,action,before_data,after_data,reason,actor) select p_employee,'IDENTITY_LINK',before_row,to_jsonb(e),p_reason,auth.uid() from public.employees e where id=p_employee;
end$$;


ALTER FUNCTION "public"."link_employee_identity"("p_employee" "uuid", "p_profile" "uuid", "p_teacher" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_instrument_sale_customer"("p_request" "uuid", "p_sale" "uuid", "p_student" "uuid", "p_parent" "uuid", "p_contact_name" "text", "p_contact_phone" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  sale public.instrument_events%rowtype;
  existing public.instrument_sale_customer_links%rowtype;
  actor uuid := auth.uid();
  contact text := public.crm_text(p_contact_name, 200);
begin
  if actor is null or not public.account_is_active() or p_request is null then
    raise exception 'INSTRUMENT_CUSTOMER_UNAUTHORIZED';
  end if;
  select * into sale from public.instrument_events where movement_id = p_sale and kind = 'SALE';
  if not found or not coalesce(public.crm_can('instrument_customer.manage', sale.branch_id), false) then
    raise exception 'INSTRUMENT_CUSTOMER_UNAUTHORIZED';
  end if;
  if p_student is null and p_parent is null and contact is null then
    raise exception 'INSTRUMENT_CUSTOMER_INVALID';
  end if;
  if p_student is not null and not exists (select 1 from public.students where id = p_student) then
    raise exception 'INSTRUMENT_CUSTOMER_INVALID';
  end if;
  if p_parent is not null and not exists (select 1 from public.parents where id = p_parent and status = 'ACTIVE') then
    raise exception 'INSTRUMENT_CUSTOMER_INVALID';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('instrument-customer:' || p_sale::text, 0));
  select * into existing from public.instrument_sale_customer_links where id = p_request or sale_event_id = p_sale;
  if found then
    if existing.sale_event_id is distinct from p_sale
      or existing.student_id is distinct from p_student
      or existing.parent_id is distinct from p_parent
      or existing.contact_name is distinct from contact
    then
      raise exception 'INSTRUMENT_CUSTOMER_ALREADY_LINKED';
    end if;
    return existing.id;
  end if;
  perform set_config('instrument.customer_write', 'on', true);
  insert into public.instrument_sale_customer_links(id, sale_event_id, student_id, parent_id, contact_name, contact_phone, created_by)
  values (p_request, p_sale, p_student, p_parent, contact, public.crm_text(p_contact_phone, 40), actor);
  perform set_config('instrument.customer_write', 'off', true);
  return p_request;
end $$;


ALTER FUNCTION "public"."link_instrument_sale_customer"("p_request" "uuid", "p_sale" "uuid", "p_student" "uuid", "p_parent" "uuid", "p_contact_name" "text", "p_contact_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_current_student_enrollments"("p_branch" "uuid", "p_search" "text", "p_limit" integer DEFAULT NULL::integer, "p_offset" integer DEFAULT 0, "p_class" "uuid" DEFAULT NULL::"uuid", "p_teacher" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("enrollment_id" "uuid", "student_id" "uuid", "student_code" "text", "student_name" "text", "branch_name" "text", "course_name" "text", "level_name" "text", "class_name" "text", "teacher_name" "text", "schedule_label" "text", "started_on" "date", "package_name" "text", "attendance_marked" integer, "class_id" "uuid", "branch_id" "uuid", "student_status" "text", "enrollment_status" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select enrollment.id, student.id, student.student_code, student.full_name, branch.name,
    course.name,
    (select level.name from public.curriculum_levels level where level.id = course.level_id),
    class_row.name,
    (select coalesce(profile.full_name, teacher.full_name) from public.class_teachers ct
      join public.teachers teacher on teacher.id = ct.teacher_id
      left join public.profiles profile on profile.id = teacher.user_id
      where ct.class_id = class_row.id and ct.teacher_role = 'PRIMARY' and ct.is_active
      order by ct.assigned_at desc
      limit 1),
    (select string_agg(
        case schedule.day_of_week
          when 1 then 'Thứ 2'
          when 2 then 'Thứ 3'
          when 3 then 'Thứ 4'
          when 4 then 'Thứ 5'
          when 5 then 'Thứ 6'
          when 6 then 'Thứ 7'
          else 'Chủ nhật'
        end || ' ' || to_char(schedule.start_time, 'HH24:MI') || '–' || to_char(schedule.end_time, 'HH24:MI'),
        ', ' order by schedule.day_of_week, schedule.start_time)
      from public.schedules schedule
      where schedule.class_id = class_row.id and schedule.status = 'ACTIVE'),
    enrollment.started_at,
    (select tuition.plan_name_snapshot from public.enrollment_tuition tuition
      where tuition.enrollment_id = enrollment.id and tuition.status <> 'CANCELLED'
      order by tuition.starts_on desc limit 1),
    (select count(*)::integer from public.attendance_records record where record.enrollment_id = enrollment.id),
    class_row.id,
    class_row.branch_id,
    student.status,
    enrollment.status
  from public.enrollments enrollment
  join public.students student on student.id = enrollment.student_id
  join public.classes class_row on class_row.id = enrollment.class_id
  join public.branches branch on branch.id = class_row.branch_id
  join public.courses course on course.id = class_row.course_id
  where public.enrollment_lifecycle_state(enrollment.id, public.registration_vietnam_today()) = 'ACTIVE'
    and public.registration_can('student_placement.view', class_row.branch_id)
    and (p_branch is null or class_row.branch_id = p_branch)
    and (p_class is null or class_row.id = p_class)
    and (
      p_teacher is null
      or exists (
        select 1 from public.class_teachers ct
        where ct.class_id = class_row.id
          and ct.teacher_id = p_teacher
          and ct.is_active
      )
    )
    and (
      nullif(btrim(coalesce(p_search, '')), '') is null
      or student.full_name ilike '%' || replace(btrim(p_search), '%', '') || '%'
      or student.student_code ilike '%' || replace(btrim(p_search), '%', '') || '%'
    )
  order by student.full_name, enrollment.started_at
  limit case when p_limit is null then null else least(greatest(p_limit, 0), 100) end
  offset greatest(coalesce(p_offset, 0), 0)
$$;


ALTER FUNCTION "public"."list_current_student_enrollments"("p_branch" "uuid", "p_search" "text", "p_limit" integer, "p_offset" integer, "p_class" "uuid", "p_teacher" "uuid") OWNER TO "postgres";


