CREATE OR REPLACE FUNCTION "public"."list_employee_expense_claims_v2"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or not coalesce(public.account_is_active(),false) then raise exception 'EXPENSE_UNAUTHORIZED'; end if;
  if p_status is not null and p_status not in ('DRAFT','SUBMITTED','RETURNED','APPROVED','REJECTED','CANCELLED') then raise exception 'EXPENSE_INVALID_STATUS_FILTER'; end if;
  if p_limit not between 1 and 100 or p_offset not between 0 and 10000 then raise exception 'EXPENSE_INVALID_PAGE'; end if;
  return jsonb_build_object(
    'claims',coalesce((select jsonb_agg(to_jsonb(q) order by q.created_at desc,q.id) from (
      select c.id,c.employee_id,c.branch_id,c.trip_id,c.claim_model,c.title,c.status,c.requested_month,c.currency,
        c.version,c.created_by,c.approved_amount,c.created_at,e.employee_code,
        (select ev.full_name from public.employee_versions ev where ev.employee_id=c.employee_id
          order by ev.effective_on desc,ev.version desc limit 1) full_name,
        case when c.claim_model='ITEMIZED_V2' then coalesce((select sum(i.amount) from public.employee_expense_claim_items_v2 i where i.claim_id=c.id),0)
          else coalesce((select sum(l.total_amount) from public.employee_expense_claim_lines l where l.claim_id=c.id),0) end total_amount,
        case when exists(select 1 from public.payroll_period_actions_v2 a where a.source_expense_claim_id=c.id and a.status='ACTIVE') then 'POSTED' else 'NOT_POSTED' end payroll_posting_state
      from public.employee_expense_claims c join public.employees e on e.id=c.employee_id
      where public.can_read_employee_expense_claim(c.id) and (p_status is null or c.status=p_status)
      order by c.created_at desc,c.id limit p_limit offset p_offset
    ) q),'[]'::jsonb),
    'limit',p_limit,'offset',p_offset
  );
end;
$$;


ALTER FUNCTION "public"."list_employee_expense_claims_v2"("p_status" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_future_start_placements"("p_branch" "uuid", "p_filter" "text", "p_search" "text", "p_limit" integer DEFAULT NULL::integer, "p_offset" integer DEFAULT 0) RETURNS TABLE("placement_id" "uuid", "placement_version" integer, "student_id" "uuid", "student_name" "text", "parent_name" "text", "branch_id" "uuid", "branch_name" "text", "program_name" "text", "level_name" "text", "desired_start" "date", "preferred_schedule" "text", "placement_status" "text", "class_name" "text", "teacher_name" "text", "scheduled_start" "date", "owner_name" "text", "completed_on" "date", "days_waiting" integer, "opened_on" "date", "enrollment_id" "uuid", "class_id" "uuid", "course_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select placement.id, placement.version, student.id, student.full_name, app.parent_name,
    placement.branch_id, branch.name,
    coalesce(program.name, app.program_interest),
    (select level.name from public.curriculum_levels level where level.id = program.level_id),
    placement.desired_start_date, placement.preferred_schedule,
    'SCHEDULED_FUTURE'::text,
    class_row.name,
    (select teacher.full_name from public.teachers teacher where teacher.id = placement.assigned_teacher_id),
    placement.scheduled_start_date,
    (select profile.full_name from public.profiles profile where profile.id = placement.owner_user_id),
    coalesce(app.payment_confirmed_at, app.completed_at)::date,
    public.registration_vietnam_today() - placement.opened_at::date,
    placement.opened_at::date,
    placement.enrollment_id,
    placement.assigned_class_id,
    coalesce(app.course_id, class_row.course_id)
  from public.student_placement_cases placement
  join public.students student on student.id = placement.student_id
  join public.registration_applications app on app.id = placement.registration_application_id
  join public.branches branch on branch.id = placement.branch_id
  left join public.classes class_row on class_row.id = placement.assigned_class_id
  left join public.courses program on program.id = coalesce(app.course_id, class_row.course_id)
  where public.registration_can('student_placement.view', placement.branch_id)
    and (p_branch is null or placement.branch_id = p_branch)
    and placement.status = 'SCHEDULED'
    and placement.scheduled_start_date > public.registration_vietnam_today()
    and (
      nullif(btrim(coalesce(p_search, '')), '') is null
      or student.full_name ilike '%' || replace(btrim(p_search), '%', '') || '%'
      or student.student_code ilike '%' || replace(btrim(p_search), '%', '') || '%'
    )
  order by placement.scheduled_start_date, student.full_name
  limit case when p_limit is null then null else least(greatest(p_limit, 0), 100) end
  offset greatest(coalesce(p_offset, 0), 0)
$$;


