CREATE OR REPLACE FUNCTION "public"."list_instrument_customer_care"("p_branch" "uuid", "p_filter" "text") RETURNS TABLE("sale_event_id" "uuid", "branch_id" "uuid", "customer_name" "text", "customer_phone" "text", "product_name" "text", "brand" "text", "model" "text", "serial" "text", "sold_on" "date", "sale_price" numeric, "currency" "text", "warranty_until" "date", "days_remaining" integer, "case_id" "uuid", "case_status" "text", "last_contact_at" timestamp with time zone, "next_follow_up_on" "date", "outcome" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
begin
  if auth.uid() is null or not public.account_is_active() then
    raise exception 'INSTRUMENT_CUSTOMER_UNAUTHORIZED';
  end if;
  return query
  select
    sale.movement_id,
    sale.branch_id,
    coalesce(student.full_name, link.contact_name),
    coalesce(student.phone, link.contact_phone),
    item.name,
    catalogue.brand,
    catalogue.model,
    unit.serial,
    (sale.created_at at time zone 'Asia/Ho_Chi_Minh')::date,
    sale.sale_price,
    sale.currency,
    sale.warranty_until,
    case when sale.warranty_until is null then null else (sale.warranty_until - today) end,
    warranty.id,
    warranty.status,
    followup.contacted_at,
    followup.next_follow_up_on,
    followup.outcome
  from public.instrument_events sale
  join public.instrument_units unit on unit.id = sale.unit_id
  join public.instrument_catalogue catalogue on catalogue.item_id = unit.item_id
  join public.inventory_items item on item.id = unit.item_id
  left join public.instrument_sale_customer_links link on link.sale_event_id = sale.movement_id
  left join public.students student on student.id = link.student_id
  left join lateral (
    select item_case.id, item_case.status
    from public.instrument_warranty_cases item_case
    where item_case.sale_event_id = sale.movement_id
    order by item_case.opened_at desc
    limit 1
  ) warranty on true
  left join lateral (
    select item_followup.contacted_at, item_followup.next_follow_up_on, item_followup.outcome
    from public.instrument_customer_followups item_followup
    where item_followup.sale_event_id = sale.movement_id
    order by item_followup.created_at desc
    limit 1
  ) followup on true
  where sale.kind = 'SALE'
    and public.crm_can('instrument_customer.view', sale.branch_id)
    and (p_branch is null or sale.branch_id = p_branch)
    and (
      p_filter is null
      or (p_filter = 'ACTIVE' and sale.warranty_until >= today)
      or (p_filter = 'EXPIRING' and sale.warranty_until between today and today + 30)
      or (p_filter = 'EXPIRED' and sale.warranty_until < today)
      or (p_filter = 'OPEN_CASE' and warranty.status in ('OPEN', 'INSPECTING', 'WAITING_PART', 'IN_REPAIR'))
      or (p_filter = 'WAITING_PART' and warranty.status = 'WAITING_PART')
      or (p_filter = 'COMPLETED' and warranty.status = 'COMPLETED')
      or (p_filter = 'FOLLOW_UP' and followup.next_follow_up_on is not null and followup.next_follow_up_on <= today)
    );
end $$;


ALTER FUNCTION "public"."list_instrument_customer_care"("p_branch" "uuid", "p_filter" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_operating_expense_context"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or not coalesce(public.account_is_active(),false) then raise exception 'OPERATING_EXPENSE_UNAUTHORIZED'; end if;
  if not (
    public.is_global_super_admin()
    or exists(select 1 from public.user_roles ur join public.roles r on r.id=ur.role_id
      where ur.user_id=auth.uid() and r.code='FINANCE' and ur.is_active
        and (ur.valid_from is null or ur.valid_from<=now()) and (ur.valid_until is null or ur.valid_until>now())
        and exists(select 1 from public.role_permissions rp join public.permissions p on p.id=rp.permission_id
          where rp.role_id=r.id and p.code in ('operating_expense.view','operating_expense.manage')))
  ) then raise exception 'OPERATING_EXPENSE_UNAUTHORIZED'; end if;

  return jsonb_build_object(
    'branches',coalesce((select jsonb_agg(jsonb_build_object('id',b.id,'name',b.name,'code',b.code) order by b.name,b.id)
      from public.branches b where b.status='ACTIVE' and public.can_read_operating_expense_branch(b.id)),'[]'::jsonb),
    'templates',coalesce((select jsonb_agg(jsonb_build_object(
        'id',t.id,'branch_id',t.branch_id,'branch_name',b.name,'category',t.category,
        'custom_category_name',t.custom_category_name,'name',t.name,'vendor',t.vendor,
        'amount_mode',t.amount_mode,'expected_amount',t.expected_amount,'currency',t.currency,
        'effective_from',t.effective_from,'effective_to',t.effective_to,'status',t.status,'version',t.version
      ) order by b.name,t.name,t.id)
      from public.operating_expense_templates t
      join public.branches b on b.id=t.branch_id
      where public.can_read_operating_expense_branch(t.branch_id)),'[]'::jsonb),
    'categories',jsonb_build_array(
      'RENT','ELECTRICITY','WATER','INTERNET','FIXED_PHONE','SECURITY','CLEANING','SOFTWARE','MAINTENANCE','OTHER'
    ),
    'payment_status','NO_OUTGOING_PAYMENT_LEDGER'
  );
end;
$$;


ALTER FUNCTION "public"."list_operating_expense_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_operating_expenses"("p_month" "date" DEFAULT NULL::"date", "p_branch" "uuid" DEFAULT NULL::"uuid", "p_category" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare month_value date; result jsonb;
begin
  if auth.uid() is null or not coalesce(public.account_is_active(),false) then raise exception 'OPERATING_EXPENSE_UNAUTHORIZED'; end if;
  if p_limit not between 1 and 100 or p_offset not between 0 and 10000 then raise exception 'OPERATING_EXPENSE_INVALID_PAGE'; end if;
  if p_status is not null and p_status not in ('DRAFT','RECORDED','CANCELLED') then raise exception 'OPERATING_EXPENSE_INVALID_STATUS'; end if;
  if p_category is not null and p_category not in (
    'RENT','ELECTRICITY','WATER','INTERNET','FIXED_PHONE','SECURITY','CLEANING','SOFTWARE','MAINTENANCE','OTHER'
  ) then raise exception 'OPERATING_EXPENSE_INVALID_CATEGORY'; end if;
  if p_search is not null and char_length(btrim(p_search))>100 then raise exception 'OPERATING_EXPENSE_INVALID_SEARCH'; end if;
  month_value:=vibe_operating_expense_private.month_start(p_month);

  with visible as (
    select r.id,r.template_id,r.branch_id,b.name branch_name,r.expense_month,r.category,r.custom_category_name,
      r.name,r.vendor,r.expected_amount,
      case when r.status='RECORDED' then r.actual_amount else null end actual_amount,
      case when r.status='RECORDED' and r.expected_amount is not null then r.actual_amount-r.expected_amount else null end variance_amount,
      r.currency,r.status,r.version,r.expense_date,r.due_date
    from public.operating_expense_records r
    join public.branches b on b.id=r.branch_id
    where public.can_read_operating_expense_branch(r.branch_id)
      and (month_value is null or r.expense_month=month_value)
      and (p_branch is null or r.branch_id=p_branch)
      and (p_category is null or r.category=p_category)
      and (p_status is null or r.status=p_status)
      and (p_search is null or btrim(p_search)='' or r.name ilike '%'||btrim(p_search)||'%'
        or coalesce(r.vendor,'') ilike '%'||btrim(p_search)||'%'
        or coalesce(r.custom_category_name,'') ilike '%'||btrim(p_search)||'%'
        or coalesce(r.reference,'') ilike '%'||btrim(p_search)||'%')
  ), page_rows as (
    select * from visible order by expense_month desc,name,id limit p_limit+1 offset p_offset
  )
  select jsonb_build_object(
    'rows',coalesce((select jsonb_agg(to_jsonb(q) order by q.expense_month desc,q.name,q.id)
      from (select * from page_rows order by expense_month desc,name,id limit p_limit) q),'[]'::jsonb),
    'has_more',(select count(*)>p_limit from page_rows),
    'limit',p_limit,'offset',p_offset,
    'payment_status','NO_OUTGOING_PAYMENT_LEDGER'
  ) into result;
  return result;
end;
$$;


ALTER FUNCTION "public"."list_operating_expenses"("p_month" "date", "p_branch" "uuid", "p_category" "text", "p_status" "text", "p_search" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_paused_student_enrollments"("p_branch" "uuid", "p_search" "text", "p_limit" integer DEFAULT NULL::integer, "p_offset" integer DEFAULT 0, "p_class" "uuid" DEFAULT NULL::"uuid", "p_teacher" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("enrollment_id" "uuid", "student_id" "uuid", "student_code" "text", "student_name" "text", "branch_name" "text", "course_name" "text", "level_name" "text", "class_name" "text", "teacher_name" "text", "schedule_label" "text", "started_on" "date", "package_name" "text", "attendance_marked" integer, "class_id" "uuid", "branch_id" "uuid", "student_status" "text", "enrollment_status" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select enrollment.id, student.id, student.student_code, student.full_name, branch.name,
    course.name,
    (select level.name from public.curriculum_levels level where level.id = course.level_id),
    class_row.name,
    (select coalesce(profile.full_name, teacher.full_name) from public.class_teachers ct
      join public.teachers teacher on teacher.id = ct.teacher_id
      left join public.profiles profile on profile.id = teacher.user_id
      where ct.class_id = class_row.id and ct.teacher_role = 'PRIMARY' and ct.is_active
      order by ct.assigned_at desc
      limit 1),
    (select string_agg(
        case schedule.day_of_week
          when 1 then 'Thứ 2'
          when 2 then 'Thứ 3'
          when 3 then 'Thứ 4'
          when 4 then 'Thứ 5'
          when 5 then 'Thứ 6'
          when 6 then 'Thứ 7'
          else 'Chủ nhật'
        end || ' ' || to_char(schedule.start_time, 'HH24:MI') || '–' || to_char(schedule.end_time, 'HH24:MI'),
        ', ' order by schedule.day_of_week, schedule.start_time)
      from public.schedules schedule
      where schedule.class_id = class_row.id and schedule.status = 'ACTIVE'),
    enrollment.started_at,
    (select tuition.plan_name_snapshot from public.enrollment_tuition tuition
      where tuition.enrollment_id = enrollment.id and tuition.status <> 'CANCELLED'
      order by tuition.starts_on desc limit 1),
    (select count(*)::integer from public.attendance_records record where record.enrollment_id = enrollment.id),
    class_row.id,
    class_row.branch_id,
    student.status,
    enrollment.status
  from public.enrollments enrollment
  join public.students student on student.id = enrollment.student_id
  join public.classes class_row on class_row.id = enrollment.class_id
  join public.branches branch on branch.id = class_row.branch_id
  join public.courses course on course.id = class_row.course_id
  where public.enrollment_lifecycle_state(enrollment.id, public.registration_vietnam_today()) = 'PAUSED'
    and public.registration_can('student_placement.view', class_row.branch_id)
    and (p_branch is null or class_row.branch_id = p_branch)
    and (p_class is null or class_row.id = p_class)
    and (
      p_teacher is null
      or exists (
        select 1 from public.class_teachers ct
        where ct.class_id = class_row.id
          and ct.teacher_id = p_teacher
          and ct.is_active
      )
    )
    and (
      nullif(btrim(coalesce(p_search, '')), '') is null
      or student.full_name ilike '%' || replace(btrim(p_search), '%', '') || '%'
      or student.student_code ilike '%' || replace(btrim(p_search), '%', '') || '%'
    )
  order by student.full_name, enrollment.started_at
  limit case when p_limit is null then null else least(greatest(p_limit, 0), 100) end
  offset greatest(coalesce(p_offset, 0), 0)
$$;


ALTER FUNCTION "public"."list_paused_student_enrollments"("p_branch" "uuid", "p_search" "text", "p_limit" integer, "p_offset" integer, "p_class" "uuid", "p_teacher" "uuid") OWNER TO "postgres";


