CREATE OR REPLACE FUNCTION "public"."list_payroll_disbursements_v2"("p_period" "uuid" DEFAULT NULL::"uuid", "p_branch" "uuid" DEFAULT NULL::"uuid", "p_payment_status" "text" DEFAULT NULL::"text", "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare result jsonb;
begin
  if auth.uid() is null or not coalesce(public.account_is_active(),false) then raise exception 'PAYROLL_DISBURSEMENT_UNAUTHORIZED'; end if;
  if p_payment_status is not null and p_payment_status not in('NOT_PAID','PARTIALLY_PAID','PAID') then raise exception 'PAYROLL_DISBURSEMENT_INVALID_STATUS'; end if;
  if p_limit not between 1 and 100 or p_offset not between 0 and 10000 then raise exception 'PAYROLL_DISBURSEMENT_INVALID_PAGE'; end if;
  if p_search is not null and char_length(btrim(p_search))>100 then raise exception 'PAYROLL_DISBURSEMENT_INVALID_SEARCH'; end if;

  with visible as (
    select pay.id,pay.period_id,pay.employee_id,pay.teacher_id,pay.branch_id,pay.teacher_name,
      coalesce(emp.employee_code,teacher.teacher_code,'—') employee_code,
      pay.currency,period.starts_on,period.ends_on,period.status period_status,branch.name branch_name,
      payroll_disbursement_private.payable_amount(pay) payable_amount,
      coalesce(disb.paid_amount,0::numeric) paid_amount
    from public.teacher_payrolls pay
    join public.payroll_periods period on period.id=pay.period_id
    join public.branches branch on branch.id=pay.branch_id
    left join public.employees emp on emp.id=pay.employee_id
    left join public.teachers teacher on teacher.id=pay.teacher_id
    left join lateral(
      select sum(d.amount) paid_amount from public.payroll_disbursements d
      where d.payroll_id=pay.id and d.status='ACTIVE'
    ) disb on true
    where period.status in('APPROVED','FINALIZED')
      and (p_period is null or pay.period_id=p_period)
      and (p_branch is null or pay.branch_id=p_branch)
      and (p_search is null or btrim(p_search)='' or pay.teacher_name ilike '%'||btrim(p_search)||'%'
        or coalesce(emp.employee_code,teacher.teacher_code,'') ilike '%'||btrim(p_search)||'%')
      and (
        public.is_global_super_admin()
        or public.has_role_permission('FINANCE','payroll.view',pay.branch_id)
        or coalesce(public.can_read_employee_payroll(pay.employee_id,pay.branch_id),false)
        or coalesce(public.can_read_own_payroll(pay.teacher_id,pay.branch_id),false)
      )
  ), classified as (
    select visible.*,(payable_amount-paid_amount) remaining_amount,
      case when paid_amount=0 then 'NOT_PAID'
        when paid_amount<payable_amount then 'PARTIALLY_PAID' else 'PAID' end payment_status
    from visible
  ), filtered as (
    select * from classified where p_payment_status is null or payment_status=p_payment_status
  ), page_rows as (
    select * from filtered order by starts_on desc,teacher_name,id limit p_limit+1 offset p_offset
  )
  select jsonb_build_object(
    'rows',coalesce((select jsonb_agg(to_jsonb(q) order by q.starts_on desc,q.teacher_name,q.id)
      from (select * from page_rows order by starts_on desc,teacher_name,id limit p_limit) q),'[]'::jsonb),
    'has_more',(select count(*)>p_limit from page_rows),
    'limit',p_limit,'offset',p_offset
  ) into result;
  return result;
end;
$$;


ALTER FUNCTION "public"."list_payroll_disbursements_v2"("p_period" "uuid", "p_branch" "uuid", "p_payment_status" "text", "p_search" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_placement_class_options"("p_branch" "uuid") RETURNS TABLE("id" "uuid", "name" "text", "branch_id" "uuid", "open_seats" integer, "code" "text", "branch_name" "text", "course_id" "uuid", "curriculum_name" "text", "level_label" "text", "teacher_name" "text", "room_name" "text", "schedule_label" "text", "duration_minutes" integer, "enrolled_count" integer, "capacity" integer, "status" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select class_row.id,
    class_row.name,
    class_row.branch_id,
    class_row.capacity - coalesce(occupancy.n, 0),
    class_row.code,
    branch.name,
    class_row.course_id,
    curriculum.name,
    case
      when from_level.name is null or to_level.name is null then null
      when from_level.id = to_level.id then from_level.name
      else from_level.name || ' – ' || to_level.name
    end,
    (
      select min(coalesce(profile.full_name, teacher.full_name))
      from public.class_teachers ct
      join public.teachers teacher on teacher.id = ct.teacher_id
      left join public.profiles profile on profile.id = teacher.user_id
      where ct.class_id = class_row.id and ct.teacher_role = 'PRIMARY' and (ct.is_active or ct.ended_at is not null)
        and ct.assigned_at <= public.registration_vietnam_today()
        and (ct.ended_at is null or ct.ended_at >= public.registration_vietnam_today())
      having count(*) = 1
    ),
    (
      select room.name
      from public.schedules schedule
      left join public.rooms room on room.id = schedule.room_id
      where schedule.class_id = class_row.id and schedule.status = 'ACTIVE'
      order by schedule.day_of_week, schedule.start_time
      limit 1
    ),
    (
      select string_agg(
        case schedule.day_of_week
          when 1 then 'Thứ 2'
          when 2 then 'Thứ 3'
          when 3 then 'Thứ 4'
          when 4 then 'Thứ 5'
          when 5 then 'Thứ 6'
          when 6 then 'Thứ 7'
          else 'Chủ nhật'
        end || ' ' || to_char(schedule.start_time, 'HH24:MI') || '–' || to_char(schedule.end_time, 'HH24:MI'),
        ', ' order by schedule.day_of_week, schedule.start_time
      )
      from public.schedules schedule
      where schedule.class_id = class_row.id and schedule.status = 'ACTIVE'
    ),
    (
      select (extract(epoch from (schedule.end_time - schedule.start_time)) / 60)::integer
      from public.schedules schedule
      where schedule.class_id = class_row.id and schedule.status = 'ACTIVE'
      order by schedule.day_of_week, schedule.start_time
      limit 1
    ),
    coalesce(occupancy.n, 0),
    class_row.capacity,
    class_row.status
  from public.classes class_row
  left join (
    select enrollment.class_id, count(*)::integer n
    from public.enrollments enrollment
    join public.classes c on c.id = enrollment.class_id
    where enrollment.status in ('ACTIVE', 'PAUSED')
      and (p_branch is null or c.branch_id = p_branch)
    group by enrollment.class_id
  ) occupancy on occupancy.class_id = class_row.id
  join public.branches branch on branch.id = class_row.branch_id
  join public.courses course on course.id = class_row.course_id
  join public.curriculums curriculum on curriculum.id = course.curriculum_id
  left join public.curriculum_levels from_level on from_level.id = class_row.accepted_from_level_id
  left join public.curriculum_levels to_level on to_level.id = class_row.accepted_to_level_id
  where class_row.status = 'ACTIVE'
    and public.registration_can('student_placement.view', class_row.branch_id)
    and (p_branch is null or class_row.branch_id = p_branch)
    and coalesce(occupancy.n, 0) < class_row.capacity
  order by class_row.name, class_row.id
$$;


ALTER FUNCTION "public"."list_placement_class_options"("p_branch" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_waiting_placements"("p_branch" "uuid", "p_filter" "text", "p_search" "text", "p_limit" integer DEFAULT NULL::integer, "p_offset" integer DEFAULT 0) RETURNS TABLE("placement_id" "uuid", "placement_version" integer, "student_id" "uuid", "student_name" "text", "parent_name" "text", "branch_id" "uuid", "branch_name" "text", "program_name" "text", "level_name" "text", "desired_start" "date", "preferred_schedule" "text", "placement_status" "text", "class_name" "text", "teacher_name" "text", "scheduled_start" "date", "owner_name" "text", "completed_on" "date", "days_waiting" integer, "opened_on" "date", "enrollment_id" "uuid", "class_id" "uuid", "course_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select placement.id, placement.version, student.id, student.full_name, app.parent_name,
    placement.branch_id, branch.name,
    coalesce(curriculum.name, program.name, app.program_interest),
    coalesce(registration_level.name, course_level.name),
    placement.desired_start_date, placement.preferred_schedule,
    placement.status,
    class_row.name,
    (select teacher.full_name from public.teachers teacher where teacher.id = placement.assigned_teacher_id),
    placement.scheduled_start_date,
    (select profile.full_name from public.profiles profile where profile.id = placement.owner_user_id),
    coalesce(app.payment_confirmed_at, app.completed_at)::date,
    public.registration_vietnam_today() - placement.opened_at::date,
    placement.opened_at::date,
    placement.enrollment_id,
    placement.assigned_class_id,
    coalesce(app.course_id, class_row.course_id)
  from public.student_placement_cases placement
  join public.students student on student.id = placement.student_id
  join public.registration_applications app on app.id = placement.registration_application_id
  join public.branches branch on branch.id = placement.branch_id
  left join public.classes class_row on class_row.id = placement.assigned_class_id
  left join public.courses program on program.id = coalesce(app.course_id, class_row.course_id)
  left join public.curriculums curriculum on curriculum.id = coalesce(app.curriculum_id, program.curriculum_id)
  left join public.curriculum_levels registration_level on registration_level.id = app.level_id
  left join public.curriculum_levels course_level on course_level.id = program.level_id
  where public.registration_can('student_placement.view', placement.branch_id)
    and (p_branch is null or placement.branch_id = p_branch)
    and placement.status in ('UNASSIGNED', 'MATCHING')
    and (
      coalesce(p_filter, 'ALL') = 'ALL'
      or (p_filter = 'UNASSIGNED' and placement.status = 'UNASSIGNED')
      or (p_filter = 'MATCHING' and placement.status = 'MATCHING')
    )
    and (
      nullif(btrim(coalesce(p_search, '')), '') is null
      or student.full_name ilike '%' || replace(btrim(p_search), '%', '') || '%'
      or student.student_code ilike '%' || replace(btrim(p_search), '%', '') || '%'
    )
  order by placement.opened_at, student.full_name
  limit case when p_limit is null then null else least(greatest(p_limit, 0), 100) end
  offset greatest(coalesce(p_offset, 0), 0)
$$;


ALTER FUNCTION "public"."list_waiting_placements"("p_branch" "uuid", "p_filter" "text", "p_search" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


