    coalesce(app.course_id, class_row.course_id)
  from public.student_placement_cases placement
  join public.students student on student.id = placement.student_id
  join public.registration_applications app on app.id = placement.registration_application_id
  join public.branches branch on branch.id = placement.branch_id
  left join public.classes class_row on class_row.id = placement.assigned_class_id
  left join public.courses program on program.id = coalesce(app.course_id, class_row.course_id)
  left join public.curriculums curriculum on curriculum.id = coalesce(app.curriculum_id, program.curriculum_id)
  left join public.curriculum_levels registration_level on registration_level.id = app.level_id
  left join public.curriculum_levels course_level on course_level.id = program.level_id
  where public.registration_can('student_placement.view', placement.branch_id)
    and (p_curriculum is null or coalesce(app.curriculum_id, program.curriculum_id) = p_curriculum)
    and (p_branch is null or placement.branch_id = p_branch)
    and placement.status in ('UNASSIGNED', 'MATCHING')
    and (
      coalesce(p_filter, 'ALL') = 'ALL'
      or (p_filter = 'UNASSIGNED' and placement.status = 'UNASSIGNED')
      or (p_filter = 'MATCHING' and placement.status = 'MATCHING')
    )
    and (
      nullif(btrim(coalesce(p_search, '')), '') is null
      or student.full_name ilike '%' || replace(btrim(p_search), '%', '') || '%'
      or student.student_code ilike '%' || replace(btrim(p_search), '%', '') || '%'
    )
  order by placement.opened_at, student.full_name
  limit case when p_limit is null then null else least(greatest(p_limit, 0), 100) end
  offset greatest(coalesce(p_offset, 0), 0)
$$;


ALTER FUNCTION "public"."list_waiting_placements_by_curriculum"("p_curriculum" "uuid", "p_branch" "uuid", "p_filter" "text", "p_search" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."manage_notification"("p_job" "uuid", "p_action" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  j public.notification_jobs;
begin
  if not public.has_role('SUPER_ADMIN') then
    raise exception 'Unauthorized';
  end if;
  select * into j from public.notification_jobs where id = p_job for update;
  if not found then
    raise exception 'Job not found';
  end if;
  if p_action = 'RETRY' and j.channel = 'ZALO' then
    perform notification_private.refresh_zalo_job(j.id);
  elsif p_action = 'RETRY' and (j.status = 'FAILED' or (j.status = 'PROCESSING' and j.lease_until < now())) then
    update public.notification_jobs
    set status = 'PENDING', lease_token = null, lease_until = null, error_code = null, updated_at = now()
    where id = j.id;
  elsif p_action = 'CANCEL' and j.status in ('PENDING', 'FAILED', 'QUEUED', 'RETRYING', 'SKIPPED_NO_CHANNEL') then
    update public.notification_jobs
    set status = 'CANCELLED', next_attempt_at = null, updated_at = now()
    where id = j.id;
  else
    raise exception 'Invalid notification transition';
  end if;
  insert into public.notification_events(job_id, event, actor_id) values (j.id, p_action, auth.uid());
end $$;


ALTER FUNCTION "public"."manage_notification"("p_job" "uuid", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."map_learning_academic_shadow"("p_version" "uuid", "p_subject" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v public.learning_versions;s public.curriculum_subjects;existing public.learning_academic_mappings;
begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Unauthorized';end if;
 if p_reason is null or length(trim(p_reason)) not between 1 and 2000 then raise exception 'Mapping evidence required';end if;
 select * into v from public.learning_versions where id=p_version for update;
 if not found or v.state<>'PUBLISHED' then raise exception 'Published version required';end if;
 select * into s from public.curriculum_subjects where id=p_subject;
 if not found or s.level_id<>v.level_id or s.status<>'ACTIVE' or s.completion_rule<>'DIRECT_ASSESSMENT' or not exists(select 1 from public.curriculum_levels l join public.curriculums c on c.id=l.curriculum_id where l.id=v.level_id and l.status='ACTIVE' and c.status='ACTIVE') then raise exception 'Active direct assessment subject in the same Grade required';end if;
 select * into existing from public.learning_academic_mappings where version_id=p_version;
 if found then
 if existing.subject_id is distinct from p_subject or existing.reason is distinct from trim(p_reason) or existing.created_by is distinct from auth.uid() then raise exception 'Mapping is immutable; create a new content version';end if;
 return p_version;
 end if;
 insert into public.learning_academic_mappings(version_id,subject_id,created_by,reason) values(p_version,p_subject,auth.uid(),trim(p_reason));
 insert into public.learning_audit(entity_id,event,actor,reason) values(p_version,'ACADEMIC_SHADOW_MAPPED',auth.uid(),trim(p_reason));
 return p_version;
end$$;


ALTER FUNCTION "public"."map_learning_academic_shadow"("p_version" "uuid", "p_subject" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_makeup_credit_from_attendance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_type text;
begin
  select occurrence_type into v_type from public.session_occurrences where id = new.session_occurrence_id;
  if v_type is distinct from 'MAKEUP' then
    return new;
  end if;
  if new.status = 'PRESENT' then
    update public.makeup_credits
    set status = 'USED', used_at = now()
    where enrollment_id = new.enrollment_id
      and reserved_occurrence_id = new.session_occurrence_id
      and status = 'RESERVED';
  elsif tg_op = 'UPDATE' and old.status = 'PRESENT' then
    update public.makeup_credits
    set status = 'RESERVED', used_at = null
    where enrollment_id = new.enrollment_id
      and reserved_occurrence_id = new.session_occurrence_id
      and status = 'USED';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."mark_makeup_credit_from_attendance"() OWNER TO "postgres";


