CREATE OR REPLACE FUNCTION "public"."materialize_qr_attendance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  check_in_row
    public.employee_attendance_scan_events%rowtype;

  existing_entry
    public.employee_attendance_entries%rowtype;

  entry_id_value uuid;

  starts_value timestamptz;
  ends_value timestamptz;

  late_value integer;
  early_value integer;

  status_value text;
begin
  if new.event_type <> 'CHECK_OUT' then
    return new;
  end if;

  if exists (
    select 1
    from public.employee_attendance_qr_verifications v
    where v.check_out_event_id=new.id
  ) then
    return new;
  end if;

  select *
  into check_in_row
  from public.employee_attendance_scan_events
  where id=new.paired_check_in_id;

  if not found then
    raise exception
      'QR_ATTENDANCE_CHECK_IN_EVIDENCE_MISSING';
  end if;

  if check_in_row.event_type <> 'CHECK_IN'
     or check_in_row.employee_id is distinct from new.employee_id
     or check_in_row.work_date is distinct from new.work_date
     or check_in_row.shift_code is distinct from new.shift_code
     or check_in_row.branch_id is distinct from new.branch_id
  then
    raise exception
      'QR_ATTENDANCE_PAIR_CONFLICT';
  end if;

  if check_in_row.scanned_at > new.scanned_at then
    raise exception
      'QR_ATTENDANCE_TIME_CONFLICT';
  end if;

  if check_in_row.schedule_snapshot
     is distinct from new.schedule_snapshot
  then
    raise exception
      'QR_ATTENDANCE_SCHEDULE_SNAPSHOT_CONFLICT';
  end if;

  select *
  into existing_entry
  from public.employee_attendance_entries e
  where e.employee_id=new.employee_id
    and e.work_date=new.work_date
    and e.shift_code=new.shift_code
  order by e.revision desc
  limit 1;

  if found then
    insert into public.employee_attendance_qr_verifications(
      employee_id,
      work_date,
      shift_code,
      branch_id,
      check_in_event_id,
      check_out_event_id,
      verification_status,
      conflict_reason
    )
    values(
      new.employee_id,
      new.work_date,
      new.shift_code,
      new.branch_id,
      check_in_row.id,
      new.id,
      'CONFLICT',
      'ATTENDANCE_ENTRY_ALREADY_EXISTS'
    );

    return new;
  end if;

  starts_value :=
    (
      check_in_row.schedule_snapshot
      ->>'starts_at'
    )::timestamptz;

  ends_value :=
    (
      check_in_row.schedule_snapshot
      ->>'ends_at'
    )::timestamptz;

  if starts_value is null
     or ends_value is null
     or ends_value <= starts_value
  then
    raise exception
      'QR_ATTENDANCE_INVALID_SCHEDULE_SNAPSHOT';
  end if;

  late_value :=
    greatest(
      0,
      ceil(
        extract(
          epoch from (
            check_in_row.scanned_at
            - starts_value
          )
        ) / 60
      )::integer
    );

  early_value :=
    greatest(
      0,
      ceil(
        extract(
          epoch from (
            ends_value
            - new.scanned_at
          )
        ) / 60
      )::integer
    );

  status_value :=
    case
      when late_value > 0 then 'LATE'
      when early_value > 0 then 'EARLY_LEAVE'
      else 'WORKED'
    end;

  insert into public.employee_attendance_entries(
    employee_id,
    work_date,
    shift_code,
    revision,
    status,
    entry_kind,
    schedule_snapshot,
    arrived_at,
    departed_at,
    late_minutes,
    early_minutes,
    reason,
    actor,
    checker,
    previous_entry_id,
    request_id,
    leave_policy_id,
    paid_leave_minutes,
    unpaid_leave_minutes
  )
  values(
    new.employee_id,
    new.work_date,
    new.shift_code,
    1,
    status_value,
    'INITIAL',
    check_in_row.schedule_snapshot,
    check_in_row.scanned_at,
    new.scanned_at,
    late_value,
    early_value,
    'QR_SYSTEM_AUTO',
    new.profile_id,
    null,
    null,
    null,
    null,
    0,
    0
  )
  returning id
  into entry_id_value;

  insert into public.employee_attendance_qr_verifications(
    employee_id,
    work_date,
    shift_code,
    branch_id,
    check_in_event_id,
    check_out_event_id,
    attendance_entry_id,
    verification_status
  )
  values(
    new.employee_id,
    new.work_date,
    new.shift_code,
    new.branch_id,
    check_in_row.id,
    new.id,
    entry_id_value,
    'VERIFIED'
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."materialize_qr_attendance"() OWNER TO "postgres";


