CREATE OR REPLACE FUNCTION "public"."mint_attendance_qr_token"("p_session" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  session_row
    public.attendance_qr_sessions%rowtype;

  plain_token text;
  hashed_token bytea;

  issued timestamptz;
  expires timestamptz;

  token_id_value uuid;
  today_vn date;
begin
  if auth.uid() is null
     or not coalesce(
       public.account_is_active(),
       false
     )
  then
    raise exception 'QR_ATTENDANCE_UNAUTHORIZED';
  end if;

  select s.*
  into session_row
  from public.attendance_qr_sessions s
  where s.id = p_session
  for update;

  if not found then
    raise exception 'QR_ATTENDANCE_SESSION_NOT_FOUND';
  end if;

  if not (
    coalesce(
      public.is_global_super_admin(),
      false
    )
    or coalesce(
      public.has_permission(
        'attendance.manage',
        session_row.branch_id
      ),
      false
    )
  ) then
    raise exception 'QR_ATTENDANCE_MANAGE_DENIED';
  end if;

  today_vn :=
    (
      clock_timestamp()
      at time zone 'Asia/Ho_Chi_Minh'
    )::date;

  if session_row.status <> 'ACTIVE'
     or session_row.work_date <> today_vn
  then
    raise exception 'QR_ATTENDANCE_SESSION_NOT_ACTIVE';
  end if;

  issued := clock_timestamp();
  expires := issued + interval '60 seconds';

  plain_token :=
    replace(
      pg_catalog.gen_random_uuid()::text,
      '-',
      ''
    )
    ||
    replace(
      pg_catalog.gen_random_uuid()::text,
      '-',
      ''
    );

  hashed_token :=
    extensions.digest(
      plain_token,
      'sha256'
    );

  insert into public.attendance_qr_tokens(
    session_id,
    token_hash,
    issued_at,
    expires_at
  )
  values(
    session_row.id,
    hashed_token,
    issued,
    expires
  )
  returning id
  into token_id_value;

  return jsonb_build_object(
    'status', 'ISSUED',
    'session_id', session_row.id,
    'token_id', token_id_value,
    'branch_id', session_row.branch_id,
    'work_date', session_row.work_date,
    'token', plain_token,
    'issued_at', issued,
    'expires_at', expires,
    'ttl_seconds', 60
  );
end;
$$;


ALTER FUNCTION "public"."mint_attendance_qr_token"("p_session" "uuid") OWNER TO "postgres";


