CREATE OR REPLACE FUNCTION "public"."note_tuition_zalo_delivery"("p_tracking_id" "text", "p_message_id" "text", "p_delivery_time" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  send public.tuition_zalo_sends;
  device_time timestamptz;
begin
  if p_tracking_id is null or p_tracking_id !~ '^[A-Za-z0-9]{1,48}$'
    or p_message_id is null or p_message_id !~ '^[A-Za-z0-9_-]{1,80}$'
    or p_delivery_time is null or p_delivery_time !~ '^[0-9]{13}$' then
    return 'IGNORED';
  end if;
  device_time := to_timestamp(p_delivery_time::numeric / 1000.0);
  select * into send
  from public.tuition_zalo_sends
  where tracking_id = p_tracking_id
  for update;
  if not found or send.provider_message_id is distinct from p_message_id then
    return 'IGNORED';
  end if;
  if send.send_status = 'DELIVERED' then
    return 'IDEMPOTENT';
  end if;
  if send.send_status is distinct from 'SENT' then
    return 'IGNORED';
  end if;
  update public.tuition_zalo_sends
  set send_status = 'DELIVERED', delivered_at = device_time
  where id = send.id and send_status = 'SENT';
  return 'DELIVERED';
end $_$;


ALTER FUNCTION "public"."note_tuition_zalo_delivery"("p_tracking_id" "text", "p_message_id" "text", "p_delivery_time" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."note_tuition_zalo_response_probe"("p_http" integer, "p_error" integer, "p_message" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  detail text;
  failures integer;
begin
  detail := left(coalesce(p_message, ''), 120);
  if detail !~ '^[A-Za-z0-9 ._-]{0,120}$' then
    detail := '';
  end if;
  if p_http between 200 and 299 and p_error = 0 then
    update public.tuition_zalo_response_sync
    set activated_at = coalesce(activated_at, clock_timestamp()),
        last_success_at = clock_timestamp(),
        auth_backoff_until = null,
        auth_failures = 0,
        updated_at = clock_timestamp()
    where id;
    return;
  end if;
  if p_error in (-124, -1241) then
    update public.tuition_zalo_response_sync
    set auth_failures = auth_failures + 1,
        last_error_at = clock_timestamp(),
        last_error_code = p_error::text,
        last_error_detail = detail,
        updated_at = clock_timestamp()
    where id
    returning auth_failures into failures;
    update public.tuition_zalo_response_sync
    set auth_backoff_until = clock_timestamp() + case
      when failures <= 1 then interval '15 minutes'
      when failures = 2 then interval '1 hour'
      else interval '6 hours'
    end
    where id;
    return;
  end if;
  update public.tuition_zalo_response_sync
  set last_error_at = clock_timestamp(),
      last_error_code = case when p_error is null then 'HTTP' else p_error::text end,
      last_error_detail = detail,
      updated_at = clock_timestamp()
  where id;
end $_$;


ALTER FUNCTION "public"."note_tuition_zalo_response_probe"("p_http" integer, "p_error" integer, "p_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_instrument_warranty_case"("p_request" "uuid", "p_sale" "uuid", "p_issue" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  sale public.instrument_events%rowtype;
  actor uuid := auth.uid();
  issue text := public.crm_text(p_issue, 2000);
  existing uuid;
begin
  if actor is null or issue is null or p_request is null then raise exception 'INSTRUMENT_CUSTOMER_INVALID'; end if;
  select * into sale from public.instrument_events where movement_id = p_sale and kind = 'SALE';
  if not found or not coalesce(public.crm_can('instrument_customer.manage', sale.branch_id), false) then
    raise exception 'INSTRUMENT_CUSTOMER_UNAUTHORIZED';
  end if;
  select id into existing from public.instrument_warranty_events where id = p_request;
  if found then return (select case_id from public.instrument_warranty_events where id = p_request); end if;
  if exists (
    select 1 from public.instrument_warranty_cases
    where sale_event_id = p_sale and status not in ('COMPLETED', 'REJECTED', 'CANCELLED')
  ) then
    raise exception 'INSTRUMENT_WARRANTY_ALREADY_OPEN';
  end if;
  perform set_config('instrument.customer_write', 'on', true);
  insert into public.instrument_warranty_cases(id, sale_event_id, issue, handled_by)
  values (p_request, p_sale, issue, actor);
  insert into public.instrument_warranty_events(id, case_id, event_type, to_status, actor_id, note)
  values (p_request, p_request, 'OPENED', 'OPEN', actor, issue);
  perform set_config('instrument.customer_write', 'off', true);
  return p_request;
end $$;


ALTER FUNCTION "public"."open_instrument_warranty_case"("p_request" "uuid", "p_sale" "uuid", "p_issue" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."override_learning_assessment"("p_assessment" "uuid", "p_student" "uuid", "p_attempts" integer, "p_until" timestamp with time zone, "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$declare result uuid;begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Unauthorized'; end if;
 if p_until is null or p_until<=now() then raise exception 'Future override expiry required'; end if;
 insert into public.learning_assessment_overrides(assessment_id,student_id,extra_attempts,valid_until,reason,created_by) values(p_assessment,p_student,p_attempts,p_until,trim(p_reason),auth.uid()) returning id into result;
 insert into public.learning_audit(entity_id,event,actor,reason) values(result,'ASSESSMENT_OVERRIDE',auth.uid(),trim(p_reason));
 return result;
end$$;


ALTER FUNCTION "public"."override_learning_assessment"("p_assessment" "uuid", "p_student" "uuid", "p_attempts" integer, "p_until" timestamp with time zone, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."own_notifications"("p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "title" "text", "href" "text", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select j.id,j.payload->>'title',j.payload->>'href',i.created_at from notification_inbox i join notification_jobs j on j.id=i.job_id
 where i.recipient_id=auth.uid() and notification_private.recipient_allowed(j.recipient_id,j.student_id,j.branch_id,j.template_key)
 order by i.created_at desc,j.id limit 26 offset greatest(0,least(coalesce(p_offset,0),100000))
$$;


ALTER FUNCTION "public"."own_notifications"("p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."own_payroll_off_cycle_corrections"("p_offset" integer DEFAULT 0) RETURNS TABLE("correction_id" "uuid", "period_id" "uuid", "currency" "text", "amount" numeric, "reason" "text", "approved_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select c.id,p.period_id,c.currency,c.delta,c.reason,c.approved_at
 from payroll_corrections c join teacher_payrolls p on p.id=c.original_payroll_id
 join payroll_periods per on per.id=p.period_id
 where c.run_type='OFF_CYCLE_CORRECTION' and per.status='FINALIZED'
 and (public.can_read_own_payroll(p.teacher_id,p.branch_id) or public.can_read_employee_payroll(p.employee_id,p.branch_id))
 order by c.approved_at desc,c.id limit 26 offset greatest(0,least(coalesce(p_offset,0),100000))
$$;


ALTER FUNCTION "public"."own_payroll_off_cycle_corrections"("p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."own_payrolls"("p_offset" integer DEFAULT 0) RETURNS SETOF "public"."teacher_payrolls"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$begin
 if not public.account_is_active() then raise exception 'Unauthorized';end if;
 if p_offset is null or p_offset<0 or p_offset>100000 then raise exception 'Invalid page';end if;
 return query select t.* from public.teacher_payrolls t join public.payroll_periods p on p.id=t.period_id where p.status in ('APPROVED','FINALIZED') and (public.can_read_employee_payroll(t.employee_id,t.branch_id) or public.can_read_own_payroll(t.teacher_id,t.branch_id)) order by p.starts_on desc,t.id offset p_offset limit 26;
end$$;


ALTER FUNCTION "public"."own_payrolls"("p_offset" integer) OWNER TO "postgres";


