CREATE OR REPLACE FUNCTION "public"."parent_can_access_student"("p_student" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select public.has_role('PARENT') and (public.has_role_permission('PARENT','students.view_related',null) or exists(select 1 from public.enrollments e join public.classes c on c.id=e.class_id where e.student_id=p_student and public.student_belongs_to_branch(p_student,c.branch_id) and public.has_role_permission('PARENT','students.view_related',c.branch_id))) and exists(select 1 from public.parents p join public.student_parents sp on sp.parent_id=p.id
 where p.user_id=auth.uid() and p.status='ACTIVE' and sp.is_active and (sp.valid_from is null or sp.valid_from<=now()) and (sp.valid_until is null or sp.valid_until>now()) and sp.student_id=p_student)
$$;


ALTER FUNCTION "public"."parent_can_access_student"("p_student" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pause_makeup_desk"("p_section" "text", "p_query" "text", "p_status" "text", "p_page" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_query text := left(replace(replace(coalesce(p_query, ''), '%', ''), '_', ''), 80);
  v_page integer := greatest(coalesce(p_page, 1), 1);
  v_today date := public.vietnam_today();
  v_policy public.academic_operation_policies%rowtype;
begin
  perform public.academic_operation_actor();
  select * into v_policy from public.current_academic_operation_policy();
  if p_section = 'student' then
    return jsonb_build_object(
      'pauses', coalesce((select jsonb_agg(jsonb_build_object('starts_on', pause.starts_on, 'ends_on', pause.ends_on, 'status', pause.status) order by pause.starts_on desc) from public.enrollment_pauses pause join public.enrollments enrollment on enrollment.id = pause.enrollment_id where enrollment.student_id = p_query::uuid and pause.status = 'ACTIVE'), '[]'::jsonb),
      'credits', coalesce((select jsonb_agg(jsonb_build_object('status', credit.status, 'label', case credit.status when 'AVAILABLE' then 'Còn dùng được' when 'RESERVED' then 'Đã đặt' when 'USED' then 'Đã học' when 'CANCELLED' then 'Bị thu hồi' else credit.status end)) from public.makeup_credits credit join public.enrollments enrollment on enrollment.id = credit.enrollment_id where enrollment.student_id = p_query::uuid and credit.status <> 'CANCELLED'), '[]'::jsonb),
      'absences', (select count(*) from public.absence_reports report join public.enrollments enrollment on enrollment.id = report.enrollment_id where enrollment.student_id = p_query::uuid)
    );
  end if;
  return jsonb_build_object(
    'policy_version', v_policy.version_no,
    'decisions', jsonb_build_array(
      case when v_policy.absence_report_deadline_hours is null then 'Chưa có hạn báo vắng được duyệt.' else null end,
      case when v_policy.makeup_use_within_days is null then 'Chưa có hạn học bù được duyệt. Không có quyền nào được đánh dấu hết hạn.' else null end,
      case when v_policy.max_open_makeup_credits is null then 'Chưa có số lần học bù tối đa được duyệt.' else null end,
      case when v_policy.late_cancel_hours is null then 'Chưa có quy định hủy muộn được duyệt.' else null end,
      case when v_policy.max_pause_calendar_days is null then 'Chưa có thời lượng bảo lưu tối đa được duyệt.' else null end,
      'Chưa có quyết định hoàn tiền hoặc tạo khoản thu. Không gửi Zalo từ màn này.'
    ),
    'overview', jsonb_build_object(
      'pending', (select count(*) from public.enrollment_pause_requests where status = 'REQUESTED'),
      'active', (select count(*) from public.enrollment_pauses where status = 'ACTIVE' and starts_on <= v_today and ends_on >= v_today),
      'ending_soon', (select count(*) from public.enrollment_pauses where status = 'ACTIVE' and ends_on between v_today and v_today + 7),
      'expiring_credits', case when v_policy.makeup_use_within_days is null then null else 0 end,
      'upcoming_makeups', (select count(*) from public.session_occurrences where occurrence_type = 'MAKEUP' and status = 'SCHEDULED' and occurrence_date >= v_today),
      'exceptions', (select count(*) from public.academic_operation_exceptions where created_at > now() - interval '30 days')
    ),
    'rows', case p_section
      when 'makeup' then coalesce((
        select jsonb_agg(row_data) from (
          select jsonb_build_object(
            'credit_id', credit.id,
            'student_code', student.student_code,
            'student_name', student.full_name,
            'label', case credit.status when 'AVAILABLE' then 'Còn dùng được' when 'RESERVED' then 'Đã đặt' when 'USED' then 'Đã học' when 'CANCELLED' then 'Bị thu hồi' else credit.status end,
            'status', credit.status,
            'source_date', source.occurrence_date,
            'source_reason', credit.source_reason,
            'destination_id', credit.reserved_occurrence_id,
            'destination_date', destination.occurrence_date,
            'destination_status', destination.status,
            'capacity', class_row.capacity,
            'taken', (select count(*) from public.session_occurrence_participants participant where participant.session_occurrence_id = destination.id)
          ) as row_data
          from public.makeup_credits credit
          join public.enrollments enrollment on enrollment.id = credit.enrollment_id
          join public.students student on student.id = enrollment.student_id
          join public.session_occurrences source on source.id = credit.source_occurrence_id
          left join public.session_occurrences destination on destination.id = credit.reserved_occurrence_id
          left join public.schedules schedule on schedule.id = destination.schedule_id
          left join public.classes class_row on class_row.id = schedule.class_id
          where (v_query = '' or student.student_code ilike '%' || v_query || '%' or student.full_name ilike '%' || v_query || '%')
            and (coalesce(p_status, '') = '' or credit.status = p_status)
          order by source.occurrence_date desc, credit.id
          offset (v_page - 1) * 20 limit 20
        ) page
      ), '[]'::jsonb)
      when 'history' then coalesce((
        select jsonb_agg(row_data) from (
          select jsonb_build_object('at', event.created_at, 'event', event.event_type, 'note', event.note, 'actor_id', event.actor_id, 'enrollment_id', event.enrollment_id) as row_data
          from public.enrollment_pause_events event
          order by event.created_at desc
          offset (v_page - 1) * 20 limit 20
        ) page
      ), '[]'::jsonb)
      else coalesce((
        select jsonb_agg(row_data) from (
          select jsonb_build_object(
            'request_id', request.id,
            'student_code', student.student_code,
            'student_name', student.full_name,
            'class_code', class_row.code,
            'starts_on', request.starts_on,
            'ends_on', request.ends_on,
            'status', request.status,
            'reason', request.reason,
            'pause_id', request.pause_id
          ) as row_data
          from public.enrollment_pause_requests request
          join public.enrollments enrollment on enrollment.id = request.enrollment_id
          join public.students student on student.id = enrollment.student_id
          join public.classes class_row on class_row.id = enrollment.class_id
          where (v_query = '' or student.student_code ilike '%' || v_query || '%' or student.full_name ilike '%' || v_query || '%')
            and (coalesce(p_status, '') = '' or request.status = p_status)
          order by request.requested_at desc
          offset (v_page - 1) * 20 limit 20
        ) page
      ), '[]'::jsonb)
    end,
    'choices', coalesce((
      select jsonb_agg(jsonb_build_object('enrollment_id', enrollment.id, 'student_code', student.student_code, 'student_name', student.full_name, 'class_code', class_row.code, 'class_id', class_row.id))
      from (
        select enrollment.id, enrollment.student_id, enrollment.class_id
        from public.enrollments enrollment
        where enrollment.status = 'ACTIVE'
        order by enrollment.started_at desc nulls last
        limit 50
      ) enrollment
      join public.students student on student.id = enrollment.student_id
      join public.classes class_row on class_row.id = enrollment.class_id
      where v_query = '' or student.student_code ilike '%' || v_query || '%' or student.full_name ilike '%' || v_query || '%' or class_row.code ilike '%' || v_query || '%'
    ), '[]'::jsonb)
  );
exception
  when invalid_text_representation then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Mã học viên hoặc bản ghi không đúng định dạng.'));
end;
$$;


ALTER FUNCTION "public"."pause_makeup_desk"("p_section" "text", "p_query" "text", "p_status" "text", "p_page" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pause_makeup_reconcile_report"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'active_pause_overlap_pairs', (
      select count(*) from public.enrollment_pauses left_pause
      join public.enrollment_pauses right_pause
        on right_pause.enrollment_id = left_pause.enrollment_id
       and right_pause.id > left_pause.id
       and left_pause.status = 'ACTIVE' and right_pause.status = 'ACTIVE'
       and daterange(left_pause.starts_on, left_pause.ends_on, '[]') && daterange(right_pause.starts_on, right_pause.ends_on, '[]')
    ),
    'duplicate_credit_groups', (
      select count(*) from (
        select source_occurrence_id, enrollment_id
        from public.makeup_credits
        group by source_occurrence_id, enrollment_id
        having count(*) > 1
      ) duplicate_credit
    ),
    'excused_credits_without_excused_attendance', (
      select count(*) from public.makeup_credits credit
      left join public.attendance_records attendance on attendance.id = credit.source_attendance_record_id
      where credit.source_reason = 'EXCUSED'
        and (attendance.id is null or attendance.status is distinct from 'EXCUSED')
        and credit.status <> 'CANCELLED'
    ),
    'active_pauses_without_request', (
      select count(*) from public.enrollment_pauses pause
      where pause.status = 'ACTIVE'
        and not exists (select 1 from public.enrollment_pause_requests request where request.pause_id = pause.id)
    ),
    'inferred_credits_created', 0
  )
$$;


ALTER FUNCTION "public"."pause_makeup_reconcile_report"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payroll_approval_snapshot"("p_period" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'period',
      to_jsonb(p),

    'payrolls',
      coalesce(
        (
          select jsonb_agg(to_jsonb(t) order by t.id)
          from public.teacher_payrolls t
          where t.period_id=p.id
        ),
        '[]'::jsonb
      ),

    'component_lines_v2',
      coalesce(
        (
          select jsonb_agg(
            to_jsonb(l)
            order by l.payroll_id,l.earned_on,l.id
          )
          from public.payroll_component_lines_v2 l
          join public.teacher_payrolls t
            on t.id=l.payroll_id
          where t.period_id=p.id
        ),
        '[]'::jsonb
      ),

    'period_actions_v2',
      coalesce(
        (
          select jsonb_agg(
            to_jsonb(a)
            order by a.created_at,a.id
          )
          from public.payroll_period_actions_v2 a
          where a.period_id=p.id
        ),
        '[]'::jsonb
      ),

    'adjustments',
      coalesce(
        (
          select jsonb_agg(to_jsonb(a) order by a.id)
          from public.payroll_adjustments a
          join public.teacher_payrolls t
            on t.id=a.payroll_id
          where t.period_id=p.id
        ),
        '[]'::jsonb
      )
  )
  from public.payroll_periods p
  where p.id=p_period
$$;


ALTER FUNCTION "public"."payroll_approval_snapshot"("p_period" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payroll_delivery_contact"("p_payroll" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  pay public.teacher_payrolls%rowtype;
  period_row public.payroll_periods%rowtype;
  contact
    hr_private.employee_private_profiles%rowtype;
begin
  if auth.uid() is null
     or not coalesce(
       public.account_is_active(),
       false
     )
  then
    raise exception
      'PAYROLL_DELIVERY_UNAUTHORIZED';
  end if;

  select *
    into pay
  from public.teacher_payrolls
  where id = p_payroll;

  if not found then
    return null;
  end if;

  select *
    into period_row
  from public.payroll_periods
  where id = pay.period_id;

  if period_row.status
     not in ('APPROVED', 'FINALIZED')
  then
    return null;
  end if;

  if not (
    coalesce(
      public.has_role('SUPER_ADMIN'),
      false
    )
    or coalesce(
      public.has_role_permission(
        'FINANCE',
        'payroll.view',
        pay.branch_id
      ),
      false
    )
    or coalesce(
      public.can_read_employee_payroll(
        pay.employee_id,
        pay.branch_id
      ),
      false
    )
    or coalesce(
      public.can_read_own_payroll(
        pay.teacher_id,
        pay.branch_id
      ),
      false
    )
  )
  then
    return null;
  end if;

  if pay.employee_id is null then
    return jsonb_build_object(
      'employee_id', null,
      'email', null,
      'phone', null
    );
  end if;

  select *
    into contact
  from hr_private.employee_private_profiles
  where employee_id = pay.employee_id;

  if not found then
    return jsonb_build_object(
      'employee_id',
        pay.employee_id,
      'email', null,
      'phone', null
    );
  end if;

  return jsonb_build_object(
    'employee_id',
      contact.employee_id,
    'email',
      contact.email,
    'phone',
      contact.phone
  );
end;
$$;


ALTER FUNCTION "public"."payroll_delivery_contact"("p_payroll" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payroll_payslip"("p_payroll" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  pay public.teacher_payrolls;
  period public.payroll_periods;
  code text;
  is_v2 boolean;
begin
  if not coalesce(public.account_is_active(), false) then
    raise exception 'Unauthorized';
  end if;

  select *
  into pay
  from public.teacher_payrolls
  where id = p_payroll;

  if not found then
    return null;
  end if;

  select *
  into period
  from public.payroll_periods
  where id = pay.period_id;

  if period.status not in ('APPROVED', 'FINALIZED') then
    return null;
  end if;

  if not (
    coalesce(public.has_role('SUPER_ADMIN'), false)
    or coalesce(
      public.has_role_permission(
        'FINANCE',
        'payroll.view',
        pay.branch_id
      ),
      false
    )
    or coalesce(
      public.can_read_employee_payroll(
        pay.employee_id,
        pay.branch_id
      ),
      false
    )
    or coalesce(
      public.can_read_own_payroll(
        pay.teacher_id,
        pay.branch_id
      ),
      false
    )
  ) then
    return null;
  end if;

  select employee_code
  into code
  from public.employees
  where id = pay.employee_id;

  is_v2 :=
    coalesce(
      pay.calculation_version like 'PAYROLL_V2%',
      false
    );

  return jsonb_build_object(
    'payroll',
    to_jsonb(pay),

    'employee_code',
    coalesce(code, pay.teacher_id::text),

    'engine',
    case
      when is_v2 then 'V2'
      else 'V1'
    end,

    'period',
    jsonb_build_object(
      'starts_on', period.starts_on,
      'ends_on', period.ends_on,
      'status', period.status,
      'approved_by', period.approved_by,
      'approved_at', period.approved_at,
      'finalized_at', period.finalized_at
    ),

    'lines',
    case
      when not is_v2 then
        coalesce(
          (
            select jsonb_agg(
              jsonb_build_object(
                'id', l.id,
                'earned_on', l.earned_on,
                'kind',
                  case
                    when l.earning_type = 'MONTHLY_BASE'
                      then 'MONTHLY_BASE'
                    else coalesce(
                      l.calculation_snapshot ->> 'pay_type',
                      pay.pay_type
                    )
                  end,
                'hours', l.duration_hours,
                'rate', l.rate,
                'amount', l.amount,
                'required_minutes',
                  l.calculation_snapshot -> 'required_minutes',
                'payable_minutes',
                  l.calculation_snapshot -> 'payable_minutes'
              )
              order by l.earned_on, l.id
            )
            from public.payroll_earning_lines l
            where l.payroll_id = pay.id
          ),
          '[]'::jsonb
        )
      else
        '[]'::jsonb
    end,

    'component_lines_v2',
    case
      when is_v2 then
        coalesce(
          (
            select jsonb_agg(
              jsonb_build_object(
                'id', l.id,
                'component_code', l.component_code,
                'category', l.category,
                'calculation_method', l.calculation_method,
                'source_type', l.source_type,
                'source_session_id', l.source_session_id,
                'earned_on', l.earned_on,
                'quantity', l.quantity,
                'unit_rate', l.unit_rate,
                'amount', l.amount,
                'currency', l.currency
              )
              order by
                l.earned_on,
                l.component_code,
                l.id
            )
            from public.payroll_component_lines_v2 l
            where l.payroll_id = pay.id
          ),
          '[]'::jsonb
        )
      else
        '[]'::jsonb
    end,

    'period_actions_v2',
    case
      when is_v2 then
        coalesce(
          (
            select jsonb_agg(
              jsonb_build_object(
                'id', a.id,
                'component_code', a.component_code,
                'category', a.category,
                'source_type', a.source_type,
                'source_expense_claim_id',
                  a.source_expense_claim_id,
                'amount', a.amount,
                'currency', a.currency,
                'reason', a.reason,
                'approved_at', a.approved_at
              )
              order by a.created_at, a.id
            )
            from public.payroll_period_actions_v2 a
            where a.period_id = pay.period_id
              and a.employee_id = pay.employee_id
              and a.status = 'ACTIVE'
          ),
          '[]'::jsonb
        )
      else
        '[]'::jsonb
    end,

    'adjustments',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', a.id,
            'kind', a.kind,
            'amount', a.amount,
            'reason', a.reason
          )
          order by a.created_at, a.id
        )
        from public.payroll_adjustments a
        where a.payroll_id = pay.id
      ),
      '[]'::jsonb
    ),

    'totals',
    case
      when is_v2 then
        jsonb_build_object(
          'earnings',
            pay.v2_earnings_amount,
          'reimbursements',
            pay.v2_reimbursement_amount,
          'deductions',
            pay.v2_deduction_amount,
          'adjustment',
            pay.adjustment_amount,
          'net',
            pay.v2_net_amount
        )
      else
        null
    end
  );
end;
$$;


ALTER FUNCTION "public"."payroll_payslip"("p_payroll" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."placement_compatible_classes"("p_cases" "uuid"[]) RETURNS TABLE("placement_id" "uuid", "class_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or cardinality(p_cases) > 100 then raise exception 'PLACEMENT_UNAUTHORIZED'; end if;
  return query
  select p.id, c.id
  from public.student_placement_cases p
  join public.registration_applications a on a.id = p.registration_application_id
  join public.classes c on c.branch_id = p.branch_id and c.status = 'ACTIVE'
  join public.courses course on course.id = c.course_id
  where p.id = any(p_cases)
    and public.registration_can('student_placement.view', p.branch_id)
    and (
      (a.course_id is not null and c.course_id = a.course_id)
      or (a.course_id is null and course.curriculum_id = a.curriculum_id)
    )
    and public.class_enrollment_compatibility(c.id, p.student_id) = 'IN_SCOPE'
    and (c.start_date is null or coalesce(p.scheduled_start_date, p.desired_start_date, c.start_date) >= c.start_date)
    and (c.end_date is null or c.end_date >= greatest(public.registration_vietnam_today(), p.scheduled_start_date, p.desired_start_date));
end;
$$;


ALTER FUNCTION "public"."placement_compatible_classes"("p_cases" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."placement_learning_history_exists"("p_enrollment" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists(select 1 from public.attendance_records where enrollment_id = p_enrollment)
    or exists(select 1 from public.enrollment_tuition where enrollment_id = p_enrollment)
    or exists(select 1 from public.enrollment_pauses where enrollment_id = p_enrollment)
    or exists(select 1 from public.makeup_credits where enrollment_id = p_enrollment)
    or exists(select 1 from public.lesson_feedback where enrollment_id = p_enrollment)
    or exists(select 1 from public.learning_reports where enrollment_id = p_enrollment)
    or exists(select 1 from public.learning_access_grants where enrollment_id = p_enrollment)
    or exists(select 1 from public.session_occurrence_participants where enrollment_id = p_enrollment)
    or exists(select 1 from public.invoices where enrollment_id_snapshot = p_enrollment)
    or exists(select 1 from public.student_retention_alerts where enrollment_id = p_enrollment)
    or exists(select 1 from public.crm_reactivation_cases where source_enrollment_id = p_enrollment)
    or exists(select 1 from public.enrollments where id = p_enrollment and student_curriculum_enrollment_id is not null)
$$;


ALTER FUNCTION "public"."placement_learning_history_exists"("p_enrollment" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."placement_reason"("p_reason" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  value text := btrim(coalesce(p_reason, ''));
begin
  if char_length(value) < 1 or char_length(value) > 2000 then
    raise exception 'PLACEMENT_REASON_REQUIRED';
  end if;
  return value;
end $$;


