CREATE OR REPLACE FUNCTION "public"."placement_schedule_check"("p_class" "uuid", "p_student" "uuid", "p_start" "date", "p_end" "date" DEFAULT NULL::"date", "p_exclude" "uuid" DEFAULT NULL::"uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare horizon date; first_day date:=greatest(p_start,registration_vietnam_today()); result text;
begin
 -- After the last known schedule/assignment/exception boundary, two more weeks
 -- cover every weekly recurrence. Unsupported timezones fail closed, not "clear".
 select greatest(first_day,
   (select max(start_date) from classes), (select max(end_date) from classes),
   (select max(effective_from) from schedules), (select max(effective_to) from schedules),
   (select max(assigned_at) from class_teachers), (select max(ended_at) from class_teachers),
   (select max((ends_at at time zone 'Asia/Ho_Chi_Minh')::date) from session_occurrences),
   (select max(started_at) from enrollments), (select max(ended_at) from enrollments),
   (select max(ends_on) from enrollment_pauses)) + 14 into horizon;
 horizon:=least(horizon,coalesce(p_end,horizon));
 if exists(select 1 from schedules s join classes c on c.id=s.class_id
   where s.status='ACTIVE' and s.timezone<>'Asia/Ho_Chi_Minh'
   and (c.branch_id=(select branch_id from classes where id=p_class)
     or exists(select 1 from enrollments e where e.class_id=c.id and e.student_id=p_student and e.status in ('ACTIVE','PAUSED')))) then
   return 'PLACEMENT_SCHEDULE_UNKNOWN';
 end if;
 if not exists(select 1 from placement_timetable(p_class,first_day,horizon) where not makeup) then
   return 'PLACEMENT_SCHEDULE_REQUIRED';
 end if;
 if exists(select 1 from placement_timetable(p_class,first_day,horizon) where teacher_id is null or room_id is null) then
   return 'PLACEMENT_SCHEDULE_UNKNOWN';
 end if;
 if exists(select 1 from enrollments e where e.student_id=p_student and e.id is distinct from p_exclude
   and e.class_id<>p_class and e.status in ('ACTIVE','PAUSED') and coalesce(e.ended_at,horizon)>=first_day
   and not exists(select 1 from placement_timetable(e.class_id,greatest(first_day,e.started_at),least(horizon,e.ended_at)))) then
   return 'PLACEMENT_SCHEDULE_UNKNOWN';
 end if;
 with target as materialized (select * from placement_timetable(p_class,first_day,horizon)),
 others as materialized (
   select c.id class_id,t.* from classes c
   cross join lateral placement_timetable(c.id,first_day,horizon) t
   where c.id<>p_class and c.status not in ('CANCELLED','COMPLETED')
 ), overlapping_slots as (
   select a.*,b.class_id other_class,b.session_id other_session,b.makeup other_makeup,
     b.room_id other_room,b.teacher_id other_teacher
   from target a join others b on a.starts_at<b.ends_at and b.starts_at<a.ends_at
 )
 select case
   when exists(select 1 from overlapping_slots where room_id=other_room) then 'PLACEMENT_ROOM_CONFLICT'
   when exists(select 1 from overlapping_slots where teacher_id=other_teacher) then 'PLACEMENT_TEACHER_CONFLICT'
   when exists(select 1 from overlapping_slots o join enrollments e on e.class_id=o.other_class
     where not o.makeup and e.student_id=p_student and e.id is distinct from p_exclude
       and e.status in ('ACTIVE','PAUSED')
       and (o.starts_at at time zone 'Asia/Ho_Chi_Minh')::date between coalesce(e.started_at,e.enrolled_at) and coalesce(e.ended_at,horizon)
       and not is_enrollment_paused_on(e.id,(o.starts_at at time zone 'Asia/Ho_Chi_Minh')::date)
       and (not o.other_makeup or exists(select 1 from session_occurrence_participants sp where sp.session_occurrence_id=o.other_session and sp.enrollment_id=e.id))) then 'PLACEMENT_STUDENT_CONFLICT'
   when exists(select 1 from target a join session_actual_teachers v on a.starts_at<v.ends_at and v.starts_at<a.ends_at
     join session_occurrence_participants sp on sp.session_occurrence_id=v.session_id
     join enrollments e on e.id=sp.enrollment_id
     where not a.makeup and v.class_id<>p_class and v.status<>'CANCELLED' and e.student_id=p_student) then 'PLACEMENT_STUDENT_CONFLICT'
   when exists(select 1 from overlapping_slots o join classes c on c.id=o.other_class
     where (o.other_room is null or o.other_teacher is null)
     and (c.branch_id=(select branch_id from classes where id=p_class)
       or exists(select 1 from enrollments e where e.class_id=c.id and e.student_id=p_student and e.status in ('ACTIVE','PAUSED')))) then 'PLACEMENT_SCHEDULE_UNKNOWN'
   when exists(select 1 from target a join target b on a.starts_at<b.ends_at and b.starts_at<a.ends_at
     and (a.session_id,a.starts_at)<(b.session_id,b.starts_at)
     where a.room_id=b.room_id or a.teacher_id=b.teacher_id or (not a.makeup and not b.makeup)) then 'PLACEMENT_SCHEDULE_UNKNOWN'
   else 'CLEAR' end into result;
 return result;
end $$;


ALTER FUNCTION "public"."placement_schedule_check"("p_class" "uuid", "p_student" "uuid", "p_start" "date", "p_end" "date", "p_exclude" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."placement_timetable"("p_class" "uuid", "p_from" "date", "p_to" "date") RETURNS TABLE("session_id" "uuid", "starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "room_id" "uuid", "teacher_id" "uuid", "makeup" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select s.id, (d.day::date+s.start_time) at time zone s.timezone,
   (d.day::date+s.end_time) at time zone s.timezone, s.room_id, t.teacher_id, false
 from schedules s join classes c on c.id=s.class_id
 cross join lateral generate_series(greatest(p_from,s.effective_from,c.start_date)::timestamp,
   least(p_to,coalesce(s.effective_to,p_to),coalesce(c.end_date,p_to))::timestamp,interval '1 day') d(day)
 left join lateral (
   select (array_agg(ct.teacher_id))[1] teacher_id from class_teachers ct
   where ct.class_id=c.id and ct.teacher_role='PRIMARY' and (ct.is_active or ct.ended_at is not null)
     and ct.assigned_at<=d.day::date and (ct.ended_at is null or ct.ended_at>=d.day::date)
   having count(*)=1
 ) t on true
 where s.class_id=p_class and s.status='ACTIVE' and extract(isodow from d.day)=s.day_of_week
 and not exists(select 1 from session_occurrences o where o.schedule_id=s.id and o.occurrence_type='REGULAR'
   and coalesce((o.original_starts_at at time zone s.timezone)::date,o.occurrence_date)=d.day::date)
 union all
 select v.session_id,v.starts_at,v.ends_at,v.room_id,v.teacher_id,v.occurrence_type='MAKEUP'
 from session_actual_teachers v
 where v.class_id=p_class and v.status<>'CANCELLED'
 and v.starts_at < (p_to+1)::timestamp at time zone 'Asia/Ho_Chi_Minh'
 and v.ends_at > p_from::timestamp at time zone 'Asia/Ho_Chi_Minh'
$$;


ALTER FUNCTION "public"."placement_timetable"("p_class" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_academic_journey"("p_student" "uuid", "p_offset" integer DEFAULT 0) RETURNS TABLE("program_id" "uuid", "curriculum" "text", "status" "text", "is_primary" boolean, "current_level_id" "uuid", "levels" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select e.id,c.name,e.status,e.is_primary,e.current_level_id,
 coalesce((select jsonb_agg(jsonb_build_object('id',l.id,'name',l.name,'status',lp.status,
  'subjects',coalesce((select jsonb_agg(jsonb_build_object(
   'id',s.id,'name',s.name,'status',s.status,'is_required',s.is_required,'completion_rule',s.completion_rule,
   'progressStatus',coalesce(sp.status,'NOT_STARTED'),
   'components',coalesce((select jsonb_agg(jsonb_build_object('id',cc.id,'name',cc.name,
    'status',cc.status,'is_required',cc.is_required,'progressStatus',coalesce(cp.status,'NOT_STARTED')) order by cc.sort_order,cc.id)
    from curriculum_subject_components cc left join student_component_progress cp
    on cp.component_id=cc.id and cp.subject_progress_id=sp.id where cc.subject_id=s.id),'[]'::jsonb)) order by s.sort_order,s.id)
   from curriculum_subjects s left join student_subject_progress sp on sp.subject_id=s.id and sp.level_progress_id=lp.id
   where s.level_id=l.id),'[]'::jsonb)) order by l.sequence_no,l.id)
  from student_level_progress lp join curriculum_levels l on l.id=lp.level_id where lp.enrollment_id=e.id),'[]'::jsonb)
 from student_curriculum_enrollments e join curriculums c on c.id=e.curriculum_id
 where e.student_id=p_student and (public.can_read_family_academic(p_student) or public.teacher_can_read_student_academic(p_student))
 order by e.is_primary desc,e.started_at,e.id limit 26 offset greatest(0,least(coalesce(p_offset,0),100000))
$$;


ALTER FUNCTION "public"."portal_academic_journey"("p_student" "uuid", "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_students"("p_student" "uuid" DEFAULT NULL::"uuid", "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "student_code" "text", "full_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select s.id,s.student_code,s.full_name from public.students s
 where (p_student is null or s.id=p_student) and (
  public.student_can_access_self(s.id) or public.parent_can_access_student(s.id)
  or exists(select 1 from public.enrollments e join public.classes c on c.id=e.class_id
   where e.student_id=s.id and public.can_read_student_history(s.id,c.branch_id,'attendance')))
 order by s.full_name,s.id limit 26 offset greatest(0,least(coalesce(p_offset,0),100000))
$$;


ALTER FUNCTION "public"."portal_students"("p_student" "uuid", "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_upcoming_sessions"("p_student" "uuid", "p_offset" integer DEFAULT 0) RETURNS TABLE("session_id" "uuid", "starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "class_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select distinct o.id,o.starts_at,o.ends_at,c.name
 from public.enrollments e join public.classes c on c.id=e.class_id
 join public.schedules sc on sc.class_id=c.id join public.session_occurrences o on o.schedule_id=sc.id
 where e.student_id=p_student and public.can_read_student_history(p_student,c.branch_id,'attendance')
 and e.status='ACTIVE' and o.status='SCHEDULED' and o.ends_at>=now()
 and e.started_at<=o.occurrence_date and (e.ended_at is null or e.ended_at>=o.occurrence_date)
 and ((o.occurrence_type='REGULAR' and not public.is_enrollment_paused_on(e.id,o.occurrence_date))
  or exists(select 1 from public.session_occurrence_participants p where p.session_occurrence_id=o.id and p.enrollment_id=e.id))
 order by o.starts_at,o.id limit 26 offset greatest(0,least(coalesce(p_offset,0),100000))
$$;


ALTER FUNCTION "public"."portal_upcoming_sessions"("p_student" "uuid", "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_expense_claim_to_payroll_v2"("p_period" "uuid", "p_version" integer, "p_claim" "uuid", "p_reason" "text", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare period_row public.payroll_periods%rowtype; payroll_row public.teacher_payrolls%rowtype;
  claim_row public.employee_expense_claims%rowtype; prior public.payroll_period_actions_v2%rowtype;
  inserted public.payroll_period_actions_v2%rowtype; payload jsonb; claim_snapshot jsonb;
  before_state jsonb; after_state jsonb; source_count integer; source_total numeric(16,2);
begin
  if auth.uid() is null or not coalesce(public.account_is_active(),false) then raise exception 'PAYROLL_V2_ACTION_UNAUTHORIZED'; end if;
  select p.* into period_row from public.payroll_periods p where p.id=p_period
    and public.has_permission('payroll.prepare',p.branch_id)
    and (public.is_global_super_admin() or public.has_role_permission('FINANCE','payroll.prepare',p.branch_id)) for update;
  if not found then raise exception 'PAYROLL_V2_ACTION_UNAUTHORIZED'; end if;
  if p_key is null then raise exception 'PAYROLL_V2_ACTION_KEY_REQUIRED'; end if;
  if p_reason is null or char_length(btrim(p_reason)) not between 1 and 2000 then raise exception 'PAYROLL_V2_ACTION_REASON_REQUIRED'; end if;
  payload:=jsonb_build_object('action','POST_EXPENSE_CLAIM','period_id',p_period,'period_version',p_version,'claim_id',p_claim,'reason',btrim(p_reason));
  select * into prior from public.payroll_period_actions_v2 a where a.created_by=auth.uid() and a.request_key=p_key;
  if found then
    if prior.request_payload is distinct from payload then raise exception 'PAYROLL_V2_ACTION_KEY_ALREADY_USED'; end if;
    return jsonb_build_object('status',case when prior.status='ACTIVE' then 'ALREADY_POSTED' else 'ALREADY_CANCELLED' end,
      'action_id',prior.id,'claim_id',prior.source_expense_claim_id,'amount',prior.amount,'currency',prior.currency,
      'payment_status','NOT_PAID_BY_THIS_ACTION');
  end if;
  if period_row.version is distinct from p_version then raise exception 'PAYROLL_V2_PERIOD_CHANGED_RELOAD'; end if;
  if period_row.status not in ('GENERATED','REVIEW') then raise exception 'PAYROLL_V2_ACTION_REQUIRES_GENERATED_OR_REVIEW'; end if;
  select c.* into claim_row from public.employee_expense_claims c where c.id=p_claim for update;
  if not found then raise exception 'PAYROLL_V2_EXPENSE_CLAIM_UNAVAILABLE'; end if;
  if claim_row.status<>'APPROVED' or claim_row.approved_amount is null or claim_row.approved_amount<=0 then raise exception 'PAYROLL_V2_EXPENSE_CLAIM_NOT_APPROVED'; end if;
  if claim_row.branch_id is distinct from period_row.branch_id or claim_row.requested_month is distinct from period_row.starts_on then raise exception 'PAYROLL_V2_EXPENSE_CLAIM_PERIOD_MISMATCH'; end if;
  if claim_row.claim_model='ITEMIZED_V2' then
    select count(*)::integer,coalesce(sum(i.amount),0) into source_count,source_total from public.employee_expense_claim_items_v2 i where i.claim_id=claim_row.id;
  else
    select count(*)::integer,coalesce(sum(l.total_amount),0) into source_count,source_total from public.employee_expense_claim_lines l where l.claim_id=claim_row.id and l.reservation_active;
    if exists(select 1 from public.employee_expense_claim_lines l join public.payroll_adjustments a on a.trip_id=l.trip_id and a.kind='TRAVEL_ALLOWANCE' where l.claim_id=claim_row.id) then
      raise exception 'PAYROLL_V2_EXPENSE_CLAIM_LEGACY_CONFLICT';
    end if;
  end if;
  if source_count=0 or source_total is distinct from claim_row.approved_amount then raise exception 'PAYROLL_V2_EXPENSE_CLAIM_LINES_INVALID'; end if;
  if exists(select 1 from public.payroll_period_actions_v2 a where a.source_expense_claim_id=claim_row.id and a.status='ACTIVE') then raise exception 'PAYROLL_V2_EXPENSE_CLAIM_ALREADY_POSTED'; end if;
  select t.* into payroll_row from public.teacher_payrolls t where t.period_id=period_row.id and t.employee_id=claim_row.employee_id and t.calculation_version like 'PAYROLL_V2%' for update;
  if not found then raise exception 'PAYROLL_V2_EXPENSE_CLAIM_PAYROLL_HEADER_REQUIRED'; end if;
  if payroll_row.currency is distinct from claim_row.currency then raise exception 'PAYROLL_V2_ACTION_CURRENCY_MISMATCH'; end if;
  claim_snapshot:=vibe_expense_private.snapshot(claim_row.id); before_state:=public.payroll_approval_snapshot(period_row.id);
  insert into public.payroll_period_actions_v2(period_id,employee_id,component_code,category,source_type,source_expense_claim_id,amount,currency,reason,request_key,request_payload,source_snapshot,created_by)
  values(period_row.id,claim_row.employee_id,'TRAVEL_EXPENSE','REIMBURSEMENT','EXPENSE_CLAIM',claim_row.id,claim_row.approved_amount,claim_row.currency,btrim(p_reason),p_key,payload,
    jsonb_build_object('integration_version','PAYROLL_V2_EXPENSE_ITEMIZED_V2','expense_claim',claim_snapshot),auth.uid()) returning * into inserted;
  perform public.refresh_staff_payroll_v2_totals(period_row.id,claim_row.employee_id);
  update public.payroll_periods set version=version+1 where id=period_row.id;
  after_state:=public.payroll_approval_snapshot(period_row.id);
  insert into public.payroll_events(period_id,status,note,actor_id,event_type,before_snapshot,after_snapshot)
  values(period_row.id,period_row.status,btrim(p_reason),auth.uid(),'V2_PERIOD_ACTION',before_state,after_state);
  return jsonb_build_object('status','POSTED','action_id',inserted.id,'period_id',inserted.period_id,'employee_id',inserted.employee_id,
    'claim_id',inserted.source_expense_claim_id,'component_code',inserted.component_code,'amount',inserted.amount,'currency',inserted.currency,
    'payment_status','NOT_PAID_BY_THIS_ACTION');
end;
$$;


ALTER FUNCTION "public"."post_expense_claim_to_payroll_v2"("p_period" "uuid", "p_version" integer, "p_claim" "uuid", "p_reason" "text", "p_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."post_expense_claim_to_payroll_v2"("p_period" "uuid", "p_version" integer, "p_claim" "uuid", "p_reason" "text", "p_key" "uuid") IS 'Posts an approved legacy or itemized V2 claim to Payroll. Posting is not payment proof.';



CREATE OR REPLACE FUNCTION "public"."post_inventory_movement"("p_request" "uuid", "p_item" "uuid", "p_branch" "uuid", "p_kind" "text", "p_quantity" numeric, "p_reason" "text", "p_destination" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare old public.inventory_movements; stock numeric; change numeric; stamp timestamptz;
begin
 if not public.has_permission('inventory.manage',p_branch) or
   (p_destination is not null and not public.has_permission('inventory.manage',p_destination)) then raise exception 'Unauthorized'; end if;
 if p_request is null or p_item is null or p_branch is null or p_kind is null or p_kind not in('RECEIPT','OUTBOUND','TRANSFER','ADJUSTMENT') or
 p_quantity is null or p_quantity=0 or p_quantity='NaN'::numeric or abs(p_quantity)>1000000000 or p_quantity<>round(p_quantity,3) or
 (p_kind<>'ADJUSTMENT' and p_quantity<0) or p_reason is null or length(trim(p_reason)) not between 1 and 2000 or
 (p_kind='TRANSFER' and (p_destination is null or p_destination=p_branch)) or (p_kind<>'TRANSFER' and p_destination is not null)
 then raise exception 'Invalid inventory movement'; end if;
 -- Same request, even with a different item, must serialize before payload checking.
 perform pg_advisory_xact_lock(hashtextextended('inventory-request:'||p_request::text,0));
 select * into old from public.inventory_movements where id=p_request;
 if found then
   if old.item_id is distinct from p_item or old.branch_id is distinct from p_branch or old.destination_id is distinct from p_destination or
   old.kind is distinct from p_kind or old.quantity is distinct from p_quantity or old.reason is distinct from trim(p_reason) or old.created_by is distinct from auth.uid()
   then raise exception 'Inventory request payload mismatch'; end if;
   return old.id;
 end if;
 -- Serialize all branches for this item, avoiding opposing-transfer deadlocks.
 perform 1 from public.inventory_items where id=p_item for update;
 if not found then raise exception 'Inventory item not found'; end if;
 if not exists(select 1 from public.branches where id=p_branch and status='ACTIVE') or
 (p_destination is not null and not exists(select 1 from public.branches where id=p_destination and status='ACTIVE')) then raise exception 'Inactive or missing branch'; end if;
 select coalesce(sum(delta),0) into stock from public.inventory_entries where item_id=p_item and branch_id=p_branch;
 change:=case when p_kind in('OUTBOUND','TRANSFER') then -p_quantity else p_quantity end;
 if stock+change<0 then raise exception 'Insufficient inventory'; end if;
 stamp:=clock_timestamp();
 insert into public.inventory_movements(id,item_id,branch_id,destination_id,kind,quantity,reason,created_by,created_at)
 values(p_request,p_item,p_branch,p_destination,p_kind,p_quantity,trim(p_reason),auth.uid(),stamp);
 insert into public.inventory_entries(movement_id,branch_id,item_id,delta,created_at) values(p_request,p_branch,p_item,change,stamp);
 if p_kind='TRANSFER' then
 insert into public.inventory_entries(movement_id,branch_id,item_id,delta,created_at) values(p_request,p_destination,p_item,p_quantity,stamp);
 end if;
 return p_request;
end$$;


ALTER FUNCTION "public"."post_inventory_movement"("p_request" "uuid", "p_item" "uuid", "p_branch" "uuid", "p_kind" "text", "p_quantity" numeric, "p_reason" "text", "p_destination" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_payroll_retroactive_claim"("p_claim" "uuid", "p_version" integer, "p_period_version" integer, "p_reason" "text", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  c public.payroll_retroactive_claims%rowtype;
  source_row public.payroll_periods%rowtype;
  target_row public.payroll_periods%rowtype;
  pay public.teacher_payrolls%rowtype;
  inserted public.payroll_period_actions_v2%rowtype;
  before_state jsonb;
  after_state jsonb;
begin
  select r.*
  into c
  from public.payroll_retroactive_claims r
  where r.id = p_claim
  for update;

  if not found
     or c.target_period_id is null
  then
    raise exception
      'RETROACTIVE_CLAIM_UNAVAILABLE';
  end if;

  select p.*
  into target_row
  from public.payroll_periods p
  where p.id = c.target_period_id
    and public.has_permission(
      'payroll.prepare',
      p.branch_id
    )
    and (
      public.is_global_super_admin()
      or public.has_role_permission(
        'FINANCE',
        'payroll.prepare',
        p.branch_id
      )
    )
  for update;

  if not found then
    raise exception 'RETROACTIVE_UNAUTHORIZED';
  end if;

  if c.version is distinct from p_version
     or target_row.version
        is distinct from p_period_version
  then
    raise exception
      'RETROACTIVE_CHANGED_RELOAD';
  end if;

  if c.status <> 'APPROVED' then
    raise exception
      'RETROACTIVE_REQUIRES_APPROVED';
  end if;

  if target_row.status
     not in ('GENERATED','REVIEW')
  then
    raise exception
      'RETROACTIVE_TARGET_MUST_BE_GENERATED_OR_REVIEW';
  end if;

  if p_reason is null
     or char_length(btrim(p_reason))
        not between 1 and 2000
  then
    raise exception
      'RETROACTIVE_POST_REASON_REQUIRED';
  end if;

  if p_key is null then
    raise exception
      'RETROACTIVE_REQUEST_KEY_REQUIRED';
  end if;

  select *
  into source_row
  from public.payroll_periods
  where id = c.source_period_id;

  select t.*
  into pay
  from public.teacher_payrolls t
  where t.period_id = target_row.id
    and t.employee_id = c.employee_id
    and t.calculation_version like 'PAYROLL_V2%'
  for update;

  if not found then
    raise exception
      'RETROACTIVE_TARGET_PAYROLL_HEADER_REQUIRED';
  end if;

  if pay.currency is distinct from c.currency then
    raise exception
      'RETROACTIVE_CURRENCY_MISMATCH';
  end if;

  if exists (
    select 1
    from public.payroll_period_actions_v2 a
    where a.source_retroactive_claim_id = c.id
      and a.status = 'ACTIVE'
  ) then
    raise exception
      'RETROACTIVE_ALREADY_POSTED';
  end if;

  before_state :=
    public.payroll_approval_snapshot(
      target_row.id
    );

  insert into public.payroll_period_actions_v2(
    period_id,
    employee_id,
    component_code,
    category,
    source_type,
    source_expense_claim_id,
    source_retroactive_claim_id,
    amount,
    currency,
    reason,
    request_key,
    request_payload,
    source_snapshot,
    created_by
  )
  values(
    target_row.id,
    c.employee_id,
    'RETROACTIVE_PAY',
    'EARNING',
    'RETROACTIVE_PAY',
    null,
    c.id,
    c.amount,
    c.currency,
    'Truy lĩnh kỳ ' ||
      to_char(source_row.starts_on,'MM/YYYY') ||
      ': ' ||
      c.reason,
    p_key,
    jsonb_build_object(
      'claim_id', c.id,
      'claim_version', c.version,
      'target_period_version',
        target_row.version
    ),
    jsonb_build_object(
      'integration_version',
        'RETROACTIVE_PAY_V1',
      'claim_id', c.id,
      'source_period_id',
        c.source_period_id,
      'source_month',
        to_char(
          source_row.starts_on,
          'YYYY-MM'
        ),
      'claim_snapshot',
        c.source_snapshot
    ),
    auth.uid()
  )
  returning * into inserted;

  perform public.refresh_staff_payroll_v2_totals(
    target_row.id,
    c.employee_id
  );

  update public.payroll_periods
  set version = version + 1
  where id = target_row.id;

  update public.payroll_retroactive_claims
  set
    status = 'POSTED',
    version = version + 1,
    posted_by = auth.uid(),
    posted_at = clock_timestamp(),
    posted_action_id = inserted.id
  where id = c.id;

  after_state :=
    public.payroll_approval_snapshot(
      target_row.id
    );

  insert into public.payroll_events(
    period_id,
    status,
    note,
    actor_id,
    event_type,
    before_snapshot,
    after_snapshot
  )
  values(
    target_row.id,
    target_row.status,
    btrim(p_reason),
    auth.uid(),
    'RETROACTIVE_PAY_POSTED',
    before_state,
    after_state
  );

  return jsonb_build_object(
    'status','POSTED',
    'claim_id',c.id,
    'action_id',inserted.id,
    'target_period_id',target_row.id,
    'employee_id',c.employee_id,
    'amount',c.amount,
    'currency',c.currency,
    'payment_status',
      'NOT_PAID_BY_THIS_ACTION'
  );
end;
$$;


ALTER FUNCTION "public"."post_payroll_retroactive_claim"("p_claim" "uuid", "p_version" integer, "p_period_version" integer, "p_reason" "text", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_reviewed_momo_deposit_receipts"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare ord public.registration_momo_orders%rowtype;
  branch public.branches%rowtype; finance_id uuid;
begin
  if new.status <> 'COMPLETED' or old.status = 'COMPLETED' or new.deposit_confirmed_at is null then
    return new;
  end if;
  select * into branch from public.branches where id = new.branch_id;
  for ord in select * from public.registration_momo_orders
    where application_id = new.id and state = 'PAID' and finance_payment_id is null
    order by paid_at for update loop
    finance_id := gen_random_uuid();
    insert into public.payments(id, payment_number, student_id_snapshot, branch_id_snapshot,
      branch_code_snapshot, branch_name_snapshot, amount, currency, payment_method,
      paid_at, reference, notes, status)
    values(finance_id, 'PAY-' || to_char(timezone('Asia/Ho_Chi_Minh', now()), 'YYYY') || '-'
      || lpad(nextval('public.payment_number_seq')::text, 6, '0'), new.linked_student_id,
      branch.id, branch.code, branch.name, ord.amount, 'VND', 'OTHER', ord.paid_at,
      'MOMO:' || ord.provider_transaction_id, 'Thanh toán hồ sơ ' || new.application_code, 'POSTED');
    update public.registration_momo_orders set finance_payment_id = finance_id where id = ord.id;
  end loop;
  return new;
end $$;


ALTER FUNCTION "public"."post_reviewed_momo_deposit_receipts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_enrollment_tuition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare

  v_enrollment_started_at date;
  v_legacy jsonb;
  v_accepted_end date;
  v_current_pause_days integer;

  v_branch_id uuid;
  v_branch_code text;
  v_branch_name text;

  v_plan_code text;
  v_plan_name text;
  v_duration_months integer;

  v_list_price numeric(14,2);
  v_currency text;

  v_existing_terms bigint;

  v_discount_type text;
  v_discount_value numeric(14,2);

begin
  if new.legacy_migration_row_id is not null then
    v_legacy:=public.authorized_legacy_tuition_payload(new.legacy_migration_row_id,new.enrollment_id);
    if new.starts_on is distinct from (v_legacy->>'tuition_starts_on')::date then raise exception 'Legacy baseline date mismatch'; end if;
  elsif new.legacy_extension_days<>0 then raise exception 'Legacy extension requires approved baseline';
  end if;

  -- -------------------------------------------------------
  -- Load Enrollment + Class + Branch.
  -- -------------------------------------------------------

  select
    e.started_at,
    c.branch_id,
    b.code,
    b.name

  into
    v_enrollment_started_at,
    v_branch_id,
    v_branch_code,
    v_branch_name

  from public.enrollments e

  join public.classes c
    on c.id = e.class_id

  join public.branches b
    on b.id = c.branch_id

  where e.id = new.enrollment_id;


  if not found then
    raise exception
      'Enrollment, class, or branch does not exist';
  end if;


  if v_enrollment_started_at is null then
    raise exception
      'An enrollment must have a study start date before tuition can begin';
  end if;


  -- -------------------------------------------------------
  -- Load active Tuition Plan.
  -- -------------------------------------------------------

  select
    tp.code,
    tp.name,
    tp.duration_months

  into
    v_plan_code,
    v_plan_name,
    v_duration_months

  from public.tuition_plans tp

  where tp.id = new.tuition_plan_id
    and tp.status = 'ACTIVE';


  if not found then
    raise exception
      'Tuition plan does not exist or is inactive';
  end if;


  -- -------------------------------------------------------
  -- Resolve price.
  --
  -- Priority:
  -- 1. Exact branch override
  -- 2. Default price (branch_id NULL)
  -- -------------------------------------------------------

  select
    p.list_price,
    p.currency

  into
    v_list_price,
    v_currency

  from public.tuition_plan_branch_prices p

  where p.tuition_plan_id =
          new.tuition_plan_id

    and p.status = 'ACTIVE'

    and (
      p.branch_id = v_branch_id
      or p.branch_id is null
    )

  order by
    case
      when p.branch_id = v_branch_id
        then 0
      else 1
    end

  limit 1;


  if not found then
    raise exception
      'No active tuition price exists for plan % at branch %',
      v_plan_code,
      v_branch_code;
  end if;


  -- -------------------------------------------------------
  -- First tuition term MUST begin on actual started_at.
  -- -------------------------------------------------------

  select count(*)

  into v_existing_terms

  from public.enrollment_tuition et

  where et.enrollment_id =
          new.enrollment_id

    and et.status <> 'CANCELLED';


  if v_existing_terms = 0 and v_legacy is null
     and new.starts_on <>
         v_enrollment_started_at then

    raise exception
      'The first tuition term must start on the enrollment study start date';

  end if;


  if new.starts_on <
     v_enrollment_started_at then

    raise exception
      'Tuition cannot start before the enrollment study start date';

  end if;


  -- -------------------------------------------------------
  -- Normalize discount input.
  -- -------------------------------------------------------

  v_discount_type :=
    upper(
      coalesce(
        nullif(
          btrim(
            new.discount_type
          ),
          ''
        ),
        'NONE'
      )
    );


  v_discount_value :=
    coalesce(
      new.discount_value,
      0
    );


  if v_discount_type = 'NONE' then

    v_discount_value := 0;
    new.discount_name := null;

  elsif v_discount_type in (
    'PERCENT',
    'FIXED'
  ) then

    if new.discount_name is null
       or btrim(
         new.discount_name
       ) = '' then

      raise exception
        'Discount name is required when a discount is applied';

    end if;


    new.discount_name :=
      btrim(
        new.discount_name
      );

  else

    raise exception
      'Invalid tuition discount type: %',
      v_discount_type;

  end if;


  -- -------------------------------------------------------
  -- Snapshot Plan.
  -- -------------------------------------------------------

  new.plan_code_snapshot :=
    v_plan_code;

  new.plan_name_snapshot :=
    v_plan_name;

  new.duration_months_snapshot :=
    v_duration_months;


  -- -------------------------------------------------------
  -- Snapshot Branch.
  -- -------------------------------------------------------

  new.branch_id_snapshot :=
    v_branch_id;

  new.branch_code_snapshot :=
    v_branch_code;

  new.branch_name_snapshot :=
    v_branch_name;


  -- -------------------------------------------------------
  -- Snapshot Price.
  -- -------------------------------------------------------

  new.list_price :=
    v_list_price;

  new.currency :=
    v_currency;


  -- -------------------------------------------------------
  -- Calculate Discount.
  -- -------------------------------------------------------

  new.discount_type :=
    v_discount_type;

  new.discount_value :=
    v_discount_value;


  new.discount_amount :=
    public.calculate_tuition_discount_amount(
      v_list_price,
      v_discount_type,
      v_discount_value
    );


  -- -------------------------------------------------------
  -- Calculate Final Amount.
  -- -------------------------------------------------------

  new.amount :=
    round(
      v_list_price
      - new.discount_amount,
      2
    );


  -- -------------------------------------------------------
  -- Calculate contractual end.
  -- -------------------------------------------------------

  new.base_ends_on :=
    public.calculate_tuition_base_end(
      new.starts_on,
      v_duration_months
    );


  -- -------------------------------------------------------
  -- At creation:
  --
  -- effective end = original base end.
  --
  -- Enrollment Pause will extend this in a later step.
  -- -------------------------------------------------------

  new.effective_ends_on :=
    new.base_ends_on;


  if v_legacy is not null then
    v_accepted_end:=coalesce(nullif(v_legacy->>'effective_ends_on','')::date,new.base_ends_on);
    select coalesce(sum(greatest(0,least(ends_on,v_accepted_end)-greatest(starts_on,new.starts_on)+1)),0)::integer
    into v_current_pause_days from public.enrollment_pauses where enrollment_id=new.enrollment_id and status='ACTIVE';
    new.legacy_extension_days:=v_accepted_end-new.base_ends_on-v_current_pause_days;
    if new.legacy_extension_days<0 then raise exception 'Legacy pause extension mismatch'; end if;
    new.effective_ends_on:=v_accepted_end;
  end if;
  return new;

end;
$$;


ALTER FUNCTION "public"."prepare_enrollment_tuition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_operating_expense_month"("p_month" "date", "p_branch" "uuid", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  month_value date:=vibe_operating_expense_private.month_start(p_month);
  payload jsonb; prior jsonb; created uuid[]:='{}'; skipped integer:=0; tpl record; record_id uuid; result jsonb;
begin
  if not vibe_operating_expense_private.can_manage(p_branch) then raise exception 'OPERATING_EXPENSE_UNAUTHORIZED'; end if;
  if month_value is null then raise exception 'OPERATING_EXPENSE_MONTH_REQUIRED'; end if;
  payload:=jsonb_build_object('operation','MONTH_PREPARED','month',month_value,'branch_id',p_branch);
  prior:=vibe_operating_expense_private.replay(p_key,payload);
  if prior is not null then return prior; end if;

  for tpl in
    select * from public.operating_expense_templates
    where branch_id=p_branch and status='ACTIVE'
      and date_trunc('month',effective_from)::date<=month_value
      and (effective_to is null or date_trunc('month',effective_to)::date>=month_value)
    order by name,id
    for update
  loop
    if exists(select 1 from public.operating_expense_records r where r.template_id=tpl.id and r.expense_month=month_value and r.status in ('DRAFT','RECORDED')) then
      skipped:=skipped+1;
      continue;
    end if;
    record_id:=gen_random_uuid();
    insert into public.operating_expense_records(
      id,template_id,branch_id,expense_month,category,custom_category_name,name,vendor,expected_amount,currency,created_by
    ) values(
      record_id,tpl.id,tpl.branch_id,month_value,tpl.category,tpl.custom_category_name,tpl.name,tpl.vendor,tpl.expected_amount,tpl.currency,auth.uid()
    );
    created:=array_append(created,record_id);
  end loop;

  result:=jsonb_build_object(
    'month',month_value,'branch_id',p_branch,'created_ids',to_jsonb(created),
    'created_count',coalesce(array_length(created,1),0),'skipped_count',skipped,
    'status','DRAFT','payment_status','NO_OUTGOING_PAYMENT_LEDGER'
  );
  return vibe_operating_expense_private.write_event(null,created[1],'MONTH_PREPARED',p_key,payload,null,result,result);
end;
$$;


ALTER FUNCTION "public"."prepare_operating_expense_month"("p_month" "date", "p_branch" "uuid", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_session_occurrence_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_source_type text;
  v_source_class_id uuid;
  v_occurrence_class_id uuid;
begin
  if tg_op = 'INSERT' then
    new.original_starts_at := coalesce(
      new.original_starts_at,
      new.starts_at
    );

    new.original_ends_at := coalesce(
      new.original_ends_at,
      new.ends_at
    );

    if new.original_room_id is null then
      new.original_room_id := new.room_id;
    end if;
  else
    new.original_starts_at :=
      old.original_starts_at;

    new.original_ends_at :=
      old.original_ends_at;

    new.original_room_id :=
      old.original_room_id;
  end if;

  if new.occurrence_type = 'MAKEUP' then
    select
      source.occurrence_type,
      source_schedule.class_id
    into
      v_source_type,
      v_source_class_id
    from public.session_occurrences as source
    join public.schedules as source_schedule
      on source_schedule.id = source.schedule_id
    where source.id = new.source_occurrence_id;

    if v_source_type is distinct from 'REGULAR' then
      raise exception
        'A makeup session must reference a regular source occurrence';
    end if;

    select schedule.class_id
    into v_occurrence_class_id
    from public.schedules as schedule
    where schedule.id = new.schedule_id;

    if v_source_class_id is distinct from
      v_occurrence_class_id
    then
      raise exception
        'A makeup session must belong to the source occurrence class';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prepare_session_occurrence_identity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_zalo_registration_retry"("p_job" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare j notification_jobs; ord bigint; decision record;
begin
 if auth.uid() is null or not public.has_role('SUPER_ADMIN') then raise exception 'Unauthorized'; end if;
 select * into j from notification_jobs where id=p_job for update;
 if not (coalesce(notification_private.zalo_retry_eligible(p_job),false) or (j.status='QUEUED' and j.channel='ZALO' and j.entity_type='REGISTRATION_COMPLETED' and j.payload->'delivery'->>'channel'='PHONE' and j.attempts<5)) then return jsonb_build_object('state','ZALO_RETRY_DENIED'); end if;
 select order_code into ord from registration_payos_orders where application_id=j.entity_id and state='PAID' order by paid_at desc limit 1;
 perform set_config('zalo.durable_write','on',true);
 update notification_jobs set status='QUEUED',error_code=null,lease_token=null,lease_until=null,updated_at=clock_timestamp() where id=j.id;
 select * into decision from preview_zalo_dispatch_decision(ord);
 if decision.decision is distinct from 'SEND' or decision.job_id is distinct from j.id then
  update notification_jobs set status=j.status,error_code=j.error_code where id=j.id;
  return jsonb_build_object('state',coalesce(decision.decision,'ZALO_RETRY_DENIED'));
 end if;
 insert into notification_events(job_id,event,actor_id,details) values(j.id,'RETRY',auth.uid(),jsonb_build_object('source','MANUAL','previous_error',j.error_code));
 return jsonb_build_object('state','QUEUED','orderCode',ord);
end $$;


