CREATE OR REPLACE FUNCTION "public"."prevent_attended_makeup_participant_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if exists (
    select 1
    from public.attendance_records
    where session_occurrence_id =
        old.session_occurrence_id
      and enrollment_id = old.enrollment_id
  ) then
    raise exception
      'A makeup participant with attendance cannot be removed';
  end if;

  return old;
end;
$$;


