CREATE OR REPLACE FUNCTION "public"."preview_registration_zalo_payload"("p_application" "uuid") RETURNS TABLE("customer_name" "text", "registration_code" "text", "student_name" "text", "program_name" "text", "branch_name" "text", "order_code" "text", "payment_status" "text", "registration_completed" boolean, "tuition_fully_paid" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  app public.registration_applications;
  terms public.registration_deposit_terms;
  paid bigint;
  sent_status text;
  sent_order text;
begin
  if auth.uid() is null or not public.has_role('SUPER_ADMIN') then
    raise exception 'Unauthorized';
  end if;
  select * into app from public.registration_applications where id = p_application;
  if not found then
    raise exception 'Registration not found';
  end if;
  select * into terms from public.registration_deposit_terms where application_id = app.id;
  select coalesce(sum(ord.attributed_amount), 0) into paid
  from public.registration_payos_orders ord
  where ord.application_id = app.id and ord.state = 'PAID';
  select job.payload->'parameters'->>'payment_status', job.payload->'parameters'->>'order_code'
    into sent_status, sent_order
  from public.notification_jobs job
  where job.entity_id = app.id and job.payload->'delivery'->>'channel' = 'PHONE'
  order by job.created_at desc
  limit 1;
  return query
  select
    left(coalesce(app.parent_name, 'Phụ huynh'), 80),
    app.application_code,
    left(coalesce(app.student_name, 'Học viên'), 80),
    left(coalesce(curriculum.name, app.program_interest, 'Chương trình đã đăng ký'), 80),
    left(branch.name, 80),
    coalesce(sent_order, app.application_code),
    coalesce(sent_status, notification_private.registration_phone_payment_status(app.id), 'CHƯA XÁC ĐỊNH'),
    app.status = 'COMPLETED',
    terms.tuition_amount is not null and paid >= terms.tuition_amount
  from public.branches branch
  left join public.curriculums curriculum on curriculum.id = app.curriculum_id
  where branch.id = app.branch_id;
end $$;


ALTER FUNCTION "public"."preview_registration_zalo_payload"("p_application" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_staff_payroll_v2"("p_period" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
 p public.payroll_periods%rowtype; staff record; cfg record; sess record; chosen record; employment record;
 issues text[]; global_issues text[] := '{}'; projected numeric; current_amount numeric; currency_value text;
 rows_value jsonb := '[]'; sources jsonb; amount_value numeric;
begin
 select * into p from public.payroll_periods target where target.id=p_period
 and auth.uid() is not null and public.account_is_active()
 and public.has_permission('payroll.prepare',target.branch_id)
 and (public.is_global_super_admin() or public.has_role_permission('FINANCE','payroll.prepare',target.branch_id));
 if not found then raise exception 'PAYROLL_V2_UNAUTHORIZED'; end if;
 if p.status not in ('DRAFT','GENERATED','REVIEW') then global_issues:=array_append(global_issues,'Kỳ đã duyệt/chốt; dùng quy trình sửa sai.'); end if;
 if exists(select 1 from public.payroll_adjustments a join public.teacher_payrolls t on t.id=a.payroll_id where t.period_id=p.id) then global_issues:=array_append(global_issues,'Có điều chỉnh cũ: bộ tính hiện tại chặn tính lại.'); end if;
 for staff in select distinct e.id,e.employee_code,e.teacher_id from public.employees e join public.staff_compensation_components c on c.employee_id=e.id where c.branch_id=p.branch_id and c.status='ACTIVE' and c.effective_from<=p.ends_on and (c.effective_to is null or c.effective_to>=p.starts_on) order by e.id loop
  issues:='{}'; projected:=0;
  select v.* into employment from public.employee_versions v where v.employee_id=staff.id and v.effective_on<=p.ends_on order by v.effective_on desc,v.version desc limit 1;
  if not found or employment.employment_status not in ('ACTIVE','ON_LEAVE') then issues:=array_append(issues,'Thiếu hồ sơ hiệu lực hoặc cần chia lương khi nghỉ việc; chưa hỗ trợ.'); end if;
  select min(c.currency) into currency_value from public.staff_compensation_components c where c.employee_id=staff.id and c.branch_id=p.branch_id and c.status='ACTIVE' and c.effective_from<=p.ends_on and (c.effective_to is null or c.effective_to>=p.starts_on);
  if currency_value is null or (select count(distinct c.currency) from public.staff_compensation_components c where c.employee_id=staff.id and c.branch_id=p.branch_id and c.status='ACTIVE' and c.effective_from<=p.ends_on and (c.effective_to is null or c.effective_to>=p.starts_on))<>1 then issues:=array_append(issues,'Thiếu hoặc có nhiều tiền tệ trong cùng hồ sơ.'); end if;
  for cfg in select c.*,cat.category from public.staff_compensation_components c join public.payroll_component_catalog cat on cat.code=c.component_code where c.employee_id=staff.id and c.branch_id=p.branch_id and c.status='ACTIVE' and c.effective_from<=p.ends_on and (c.effective_to is null or c.effective_to>=p.starts_on) order by c.id loop
   if cfg.calculation_method not in ('FIXED_AMOUNT','PER_SESSION') then issues:=array_append(issues,cfg.component_code||': phương pháp chưa được hỗ trợ.');
   elsif cfg.calculation_method='FIXED_AMOUNT' then
    if cfg.effective_from>p.starts_on or coalesce(cfg.effective_to,p.ends_on)<p.ends_on then issues:=array_append(issues,cfg.component_code||': hiệu lực không phủ trọn tháng; không tự chia lương.');
    elsif cfg.amount is null then issues:=array_append(issues,cfg.component_code||': thiếu số tiền.');
    else projected:=projected+case when cfg.category='DEDUCTION' then -cfg.amount else cfg.amount end; end if;
   end if;
  end loop;
  if exists(select 1 from public.staff_compensation_components a join public.staff_compensation_components b on a.id<b.id and a.employee_id=b.employee_id and a.branch_id=b.branch_id and daterange(a.effective_from,a.effective_to,'[]') && daterange(b.effective_from,b.effective_to,'[]') where a.employee_id=staff.id and a.branch_id=p.branch_id and a.status='ACTIVE' and b.status='ACTIVE' and a.effective_from<=p.ends_on and coalesce(a.effective_to,p.ends_on)>=p.starts_on and b.effective_from<=p.ends_on and coalesce(b.effective_to,p.ends_on)>=p.starts_on and ((a.component_code=b.component_code and a.calculation_method='FIXED_AMOUNT') or (a.component_code='SOCIAL_LABOR_INSURANCE' and b.component_code in ('SOCIAL_INSURANCE','LABOR_INSURANCE')) or (b.component_code='SOCIAL_LABOR_INSURANCE' and a.component_code in ('SOCIAL_INSURANCE','LABOR_INSURANCE')))) then issues:=array_append(issues,'Cấu hình trùng phạm vi hoặc bảo hiểm gộp giao với mã cũ.'); end if;
  for sess in select a.*,c.class_type from public.session_actual_teachers a join public.classes c on c.id=a.class_id where a.teacher_id=staff.teacher_id and a.branch_id=p.branch_id and a.occurrence_date between p.starts_on and p.ends_on and a.status='COMPLETED' and a.ends_at<=statement_timestamp() order by a.session_id loop
   select c.*,cat.category into chosen from public.staff_compensation_components c join public.payroll_component_catalog cat on cat.code=c.component_code where c.employee_id=staff.id and c.branch_id=p.branch_id and c.component_code='TEACHING_PER_SESSION' and c.status='ACTIVE' and c.calculation_method='PER_SESSION' and c.effective_from<=sess.occurrence_date and (c.effective_to is null or c.effective_to>=sess.occurrence_date) and (c.class_type is null or c.class_type=sess.class_type) order by case when c.class_type is null then 1 else 0 end,c.effective_from desc,c.id limit 1;
   if found then
    if chosen.rate is null then issues:=array_append(issues,'Buổi dạy thiếu đơn giá.'); else projected:=projected+case when chosen.category='DEDUCTION' then -chosen.rate else chosen.rate end; end if;
   end if;
  end loop;
  if exists(select 1 from public.payroll_period_actions_v2 a where a.period_id=p.id and a.employee_id=staff.id and a.status='ACTIVE' and a.currency is distinct from currency_value) then issues:=array_append(issues,'Khoản phát sinh khác tiền tệ cấu hình.'); end if;
  select coalesce(sum(a.amount),0) into amount_value from public.payroll_period_actions_v2 a where a.period_id=p.id and a.employee_id=staff.id and a.status='ACTIVE';
  projected:=projected+amount_value;
  select case when t.calculation_version like 'PAYROLL_V2%' then t.v2_net_amount else t.gross_amount end into current_amount from public.teacher_payrolls t where t.period_id=p.id and t.employee_id=staff.id;
  rows_value:=rows_value||jsonb_build_array(jsonb_build_object('employee_id',staff.id,'name',coalesce(employment.full_name,staff.employee_code),'currency',currency_value,'current',current_amount::text,'projected',case when cardinality(issues)=0 then projected::text else null end,'delta',case when cardinality(issues)=0 and current_amount is not null then (projected-current_amount)::text else null end,'issues',to_jsonb(issues)));
 end loop;
 if jsonb_array_length(rows_value)=0 then global_issues:=array_append(global_issues,'Chưa có nhân viên có cấu hình hợp lệ trong kỳ.'); end if;
 if exists(select 1 from public.teacher_payrolls t where t.period_id=p.id and not exists(select 1 from jsonb_array_elements(rows_value) r where r->>'employee_id'=t.employee_id::text)) then global_issues:=array_append(global_issues,'Có bản tính cũ không còn cấu hình; cần đối soát trước khi thay thế.'); end if;
 if exists(select 1 from public.payroll_period_actions_v2 a where a.period_id=p.id and a.status='ACTIVE' and not exists(select 1 from jsonb_array_elements(rows_value) r where r->>'employee_id'=a.employee_id::text)) then global_issues:=array_append(global_issues,'Khoản phát sinh có nhân viên không còn cấu hình trong kỳ.'); end if;
 -- Fingerprint source evidence as well as amounts: equal totals alone are insufficient.
 sources:=jsonb_build_object('period',public.payroll_approval_snapshot(p.id),'configs',(select jsonb_agg(to_jsonb(c) order by c.id) from public.staff_compensation_components c where c.branch_id=p.branch_id),'staff',(select jsonb_agg(to_jsonb(e) order by e.id) from public.employees e),'employment',(select jsonb_agg(to_jsonb(v) order by v.employee_id,v.version) from public.employee_versions v),'catalog',(select jsonb_agg(to_jsonb(c) order by c.code) from public.payroll_component_catalog c),'sessions',(select jsonb_agg(to_jsonb(a)||jsonb_build_object('class_type',c.class_type) order by a.session_id) from public.session_actual_teachers a join public.classes c on c.id=a.class_id where a.branch_id=p.branch_id and a.occurrence_date between p.starts_on and p.ends_on));
 return jsonb_build_object('version',p.version,'status',p.status,'rows',rows_value,'issues',to_jsonb(global_issues),'blocked',cardinality(global_issues)>0 or exists(select 1 from jsonb_array_elements(rows_value) r where jsonb_array_length(r->'issues')>0),'fingerprint',md5(sources::text||rows_value::text));
end $$;


ALTER FUNCTION "public"."preview_staff_payroll_v2"("p_period" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_tuition_discount"("p_tuition_id" "uuid", "p_discount_type" "text", "p_discount_value" numeric, "p_discount_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare t enrollment_tuition%rowtype; discount numeric(14,2);
begin
  if not coalesce(public.has_role('SUPER_ADMIN'),false) then raise exception 'SUPER_ADMIN role required'; end if;
  select * into t from enrollment_tuition where id=p_tuition_id;
  if not found or t.status='CANCELLED' then raise exception 'Tuition unavailable'; end if;
  if exists(select 1 from invoices where enrollment_tuition_id=t.id) then raise exception 'Tuition discount cannot change after invoice creation'; end if;
  if p_discount_type is null or p_discount_type not in ('NONE','PERCENT','FIXED') or p_discount_value is null then raise exception 'Invalid discount'; end if;
  if p_discount_type<>'NONE' and nullif(btrim(p_discount_name),'') is null then raise exception 'Discount name required'; end if;
  if length(p_discount_name)>300 then raise exception 'Discount name too long'; end if;
  discount := calculate_tuition_discount_amount(t.list_price,p_discount_type,p_discount_value);
  return jsonb_build_object('list_price',t.list_price,'currency',t.currency,'discount_amount',discount,'amount',t.list_price-discount,
    'starts_on',t.starts_on,'base_ends_on',t.base_ends_on,'branch_name',t.branch_name_snapshot,'plan_name',t.plan_name_snapshot);
end $$;


ALTER FUNCTION "public"."preview_tuition_discount"("p_tuition_id" "uuid", "p_discount_type" "text", "p_discount_value" numeric, "p_discount_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_tuition_term"("p_enrollment_id" "uuid", "p_tuition_plan_id" "uuid", "p_starts_on" "date", "p_discount_type" "text", "p_discount_value" numeric, "p_discount_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  e record; plan record; price record; latest record;
  discount numeric(14,2); start_date date;
begin
  if not coalesce(public.has_role('SUPER_ADMIN'), false) then raise exception 'SUPER_ADMIN role required'; end if;
  select en.started_at, en.status, c.branch_id, b.name as branch_name into e
  from enrollments en join classes c on c.id=en.class_id join branches b on b.id=c.branch_id
  where en.id=p_enrollment_id;
  if not found or e.status <> 'ACTIVE' or e.started_at is null then raise exception 'Active enrollment with study start required'; end if;
  select name, duration_months into plan from tuition_plans where id=p_tuition_plan_id and status='ACTIVE';
  if not found then raise exception 'Tuition plan does not exist or is inactive'; end if;
  select list_price, currency into price from tuition_plan_branch_prices
  where tuition_plan_id=p_tuition_plan_id and status='ACTIVE' and (branch_id=e.branch_id or branch_id is null)
  order by (branch_id is not null) desc limit 1;
  if not found then raise exception 'No active tuition price'; end if;
  select effective_ends_on, status into latest from enrollment_tuition
  where enrollment_id=p_enrollment_id and status<>'CANCELLED' order by effective_ends_on desc limit 1;
  if latest.status='SCHEDULED' then raise exception 'Scheduled tuition already exists'; end if;
  start_date := coalesce(p_starts_on, latest.effective_ends_on+1, e.started_at);
  if start_date < e.started_at or (latest.effective_ends_on is null and start_date<>e.started_at) then
    raise exception 'Invalid tuition study start date';
  end if;
  if p_discount_type is null or p_discount_type not in ('NONE','PERCENT','FIXED') or p_discount_value is null then raise exception 'Invalid discount'; end if;
  if p_discount_type<>'NONE' and nullif(btrim(p_discount_name),'') is null then raise exception 'Discount name required'; end if;
  if length(p_discount_name)>300 then raise exception 'Discount name too long'; end if;
  discount := calculate_tuition_discount_amount(price.list_price,p_discount_type,p_discount_value);
  if exists(select 1 from enrollment_tuition where enrollment_id=p_enrollment_id and status<>'CANCELLED'
    and daterange(starts_on,effective_ends_on,'[]') && daterange(start_date,calculate_tuition_base_end(start_date,plan.duration_months),'[]')) then
    raise exception 'Tuition periods overlap';
  end if;
  return jsonb_build_object('starts_on',start_date,'base_ends_on',calculate_tuition_base_end(start_date,plan.duration_months),
    'branch_name',e.branch_name,'plan_name',plan.name,'list_price',price.list_price,'currency',price.currency,
    'discount_amount',discount,'amount',price.list_price-discount);
end $$;


ALTER FUNCTION "public"."preview_tuition_term"("p_enrollment_id" "uuid", "p_tuition_plan_id" "uuid", "p_starts_on" "date", "p_discount_type" "text", "p_discount_value" numeric, "p_discount_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_zalo_dispatch_decision"("p_order_code" bigint) RETURNS TABLE("decision" "text", "job_id" "uuid", "provider_user_id" "text", "idempotency_key" "text", "parameters" "jsonb", "delivery_channel" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  target record;
  job public.notification_jobs;
  expected text;
begin
  select ord.application_id, app.status as application_status, ord.state as order_state,
    terms.payment_option, consent.normalized_phone, consent.id as consent_id
  into target
  from public.registration_payos_orders ord
  join public.registration_applications app on app.id = ord.application_id
  join public.registration_deposit_terms terms on terms.application_id = ord.application_id
  left join public.registration_zalo_phone_consents consent
    on consent.application_id = ord.application_id and consent.revoked_at is null
  where ord.order_code = p_order_code;
  if not found then
    return query select 'NOT_THIS_APPLICATION', null::uuid, null::text, null::text, null::jsonb, null::text;
    return;
  end if;
  if target.order_state is distinct from 'PAID' or target.application_status is distinct from 'COMPLETED' then
    return query select 'NOT_SENDABLE', null::uuid, null::text, null::text, null::jsonb, 'PHONE'::text;
    return;
  end if;
  if target.normalized_phone is null then
    return query select 'NO_CONSENT', null::uuid, null::text, null::text, null::jsonb, 'PHONE'::text;
    return;
  end if;
  expected := case target.payment_option
    when 'DEPOSIT_50' then 'Đã nhận thanh toán 50%'
    when 'FULL' then 'Đã thanh toán đủ'
    else null
  end;
  select * into job
  from public.notification_jobs notification
  where notification.entity_type = 'REGISTRATION_COMPLETED'
    and notification.entity_id = target.application_id
    and notification.channel = 'ZALO'
    and notification.template_key = 'ZALO_REGISTRATION_CONFIRMED'
    and notification.payload->'delivery'->>'channel' = 'PHONE'
  order by notification.created_at
  limit 1;
  if job.id is null then
    return query select 'NO_JOB', null::uuid, null::text, null::text, null::jsonb, 'PHONE'::text;
    return;
  end if;
  if job.status = 'ACCEPTANCE_UNKNOWN' then
    return query select 'AMBIGUOUS', job.id, null::text, null::text, null::jsonb, 'PHONE'::text;
    return;
  end if;
  if job.status in ('SENT', 'DELIVERED') then
    return query select 'ALREADY_ACCEPTED', job.id, null::text, null::text, null::jsonb, 'PHONE'::text;
    return;
  end if;
  if job.payload->'delivery'->>'normalized_recipient' is distinct from target.normalized_phone then
    return query select 'WRONG_RECIPIENT', job.id, null::text, null::text, null::jsonb, 'PHONE'::text;
    return;
  end if;
  if not exists (
    select 1 from public.registration_zalo_phone_consents consent
    where consent.id = target.consent_id
      and consent.revoked_at is null
      and consent.normalized_phone = job.payload->'delivery'->>'normalized_recipient'
  ) then
    return query select 'NO_CONSENT', job.id, null::text, null::text, null::jsonb, 'PHONE'::text;
    return;
  end if;
  if expected is null or job.payload->'parameters'->>'payment_status' is distinct from expected then
    return query select 'PAYLOAD_REJECTED', job.id, null::text, null::text, null::jsonb, 'PHONE'::text;
    return;
  end if;
  if not exists (
    select 1 from public.notification_templates template
    where template.template_key = job.template_key
      and template.provider = 'ZALO'
      and template.provider_template_id = '640377'
      and template.status = 'APPROVED'
      and template.enabled
  ) then
    return query select 'GATE_DISABLED', job.id, null::text, null::text, null::jsonb, 'PHONE'::text;
    return;
  end if;
  if job.status not in ('QUEUED', 'RETRYING') then
    return query select 'NOT_SENDABLE', job.id, null::text, null::text, null::jsonb, 'PHONE'::text;
    return;
  end if;
  return query select 'SEND', job.id, target.normalized_phone, job.idempotency_key, job.payload->'parameters', 'PHONE'::text;
end $$;


ALTER FUNCTION "public"."preview_zalo_dispatch_decision"("p_order_code" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_tuition_zalo_webhook"("p_event_id" "uuid", "p_oa_id" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare event public.integration_webhook_events; applied text; message jsonb; candidate public.tuition_zalo_sends;
begin
  select * into event from integration_webhook_events where id=p_event_id and provider='ZALO'
    and event_type in ('user_click_response_button','user_received_message') and status='ACCEPTED' for update;
  if not found then return 'missing_event'; end if;
  if event.processed_at is not null then return 'duplicate'; end if;
  begin
    if event.event_type='user_click_response_button' then
      applied:=public.apply_tuition_zalo_response(event.payload,p_oa_id);
    else
      message:=event.payload->'message';
      -- Ingress already verified App/OA/signature. Delivery remains distinct from response.
      select * into candidate from tuition_zalo_sends where tracking_id=message->>'tracking_id';
      if found and candidate.context_captured_at is not null and candidate.app_id is distinct from event.payload->>'app_id' then
        applied:='app_mismatch';
      elsif found and candidate.oa_id is not null and candidate.oa_id is distinct from p_oa_id then
        applied:='oa_mismatch';
      else
        applied:=public.note_tuition_zalo_delivery(message->>'tracking_id',message->>'msg_id',message->>'delivery_time');
      end if;
    end if;
    if applied in ('recorded','duplicate','conflict','DELIVERED','IDEMPOTENT') then
      perform public.mark_zalo_webhook_processed(event.id,null);
      update integration_webhook_events set next_attempt_at=null where id=event.id;
    else
      perform public.mark_zalo_webhook_processed(event.id,upper(coalesce(applied,'APPLY_FAILED')));
      update integration_webhook_events set next_attempt_at=clock_timestamp()+make_interval(secs=>least(900,15*power(2,least(event.attempt_count,6))::integer)) where id=event.id;
    end if;
  exception when others then
    perform public.mark_zalo_webhook_processed(event.id,'APPLY_FAILED');
    update integration_webhook_events set next_attempt_at=clock_timestamp()+interval '1 minute' where id=event.id;
    return 'apply_failed';
  end;
  return applied;
end $$;


ALTER FUNCTION "public"."process_tuition_zalo_webhook"("p_event_id" "uuid", "p_oa_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."public_report_snapshot"("p_snapshot" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select jsonb_build_object(
 'schema_version',p_snapshot->'schema_version','as_of',p_snapshot->'as_of',
 'period_start',p_snapshot->'period_start','period_end',p_snapshot->'period_end',
 'student',jsonb_build_object('id',p_snapshot#>'{student,id}','name',p_snapshot#>'{student,name}','code',p_snapshot#>'{student,code}'),
 'branch',jsonb_build_object('id',p_snapshot#>'{branch,id}','name',p_snapshot#>'{branch,name}'),
 'class_name',p_snapshot->'class_name',
 'attendance',(select jsonb_object_agg(k,p_snapshot->'attendance'->k) from unnest(array['scheduled','attended','present','late','absent','excused','unmarked','makeup','rate']) k),
 'teacher_summary',(select jsonb_object_agg(k,p_snapshot->'teacher_summary'->k) from unnest(array['achievement','difficulty','intervention','next_month_plan','practice_consistency','lesson_preparation','learning_attitude','general_comment','strengths','improvement_areas','next_focus','recommendation']) k),
 'academic',jsonb_build_object('curriculum',p_snapshot#>'{academic,curriculum}','current_grade',p_snapshot#>'{academic,current_grade}','status',p_snapshot#>'{academic,status}',
  'subjects',coalesce((select jsonb_agg(jsonb_build_object('grade',s->'grade','grade_status',s->'grade_status','name',s->'name','is_required',s->'is_required','completion_rule',s->'completion_rule','status',s->'status','score',s->'score',
   'components',coalesce((select jsonb_agg(jsonb_build_object('name',c->'name','required',c->'required','status',c->'status','score',c->'score')) from jsonb_array_elements(coalesce(s->'components','[]'::jsonb)) c),'[]'::jsonb)))
   from jsonb_array_elements(coalesce(p_snapshot#>'{academic,subjects}','[]'::jsonb)) s),'[]'::jsonb)),
 'journals',jsonb_build_object('count',p_snapshot#>'{journals,count}','excerpts',coalesce((select jsonb_agg(jsonb_build_object('content',j->'content','repertoire',j->'repertoire','skills',j->'skills','homework',j->'homework','observation',j->'observation','updated_at',j->'updated_at')) from jsonb_array_elements(coalesce(p_snapshot#>'{journals,excerpts}','[]'::jsonb)) j),'[]'::jsonb)),
 'teachers',coalesce((select jsonb_agg(jsonb_build_object('code',t->'code','name',t->'name','role',t->'role')) from jsonb_array_elements(coalesce(p_snapshot->'teachers','[]'::jsonb)) t),'[]'::jsonb))
$$;


ALTER FUNCTION "public"."public_report_snapshot"("p_snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_enrollment_tuition_effective_end"("p_tuition_id" "uuid") RETURNS "date"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_status text;
  v_effective_ends_on date;
begin
  if p_tuition_id is null then
    raise exception
      'Tuition term id is required';
  end if;


  select tuition.status
  into v_status
  from public.enrollment_tuition as tuition
  where tuition.id = p_tuition_id
  for update;


  if not found then
    raise exception
      'Tuition term not found';
  end if;


  if v_status = 'CANCELLED' then
    select tuition.effective_ends_on
    into v_effective_ends_on
    from public.enrollment_tuition as tuition
    where tuition.id = p_tuition_id;

    return v_effective_ends_on;
  end if;


  v_effective_ends_on :=
    public.calculate_enrollment_tuition_effective_end(
      p_tuition_id
    );


  update public.enrollment_tuition
  set effective_ends_on =
    v_effective_ends_on
  where id = p_tuition_id
    and effective_ends_on is distinct from
      v_effective_ends_on;


  return v_effective_ends_on;
end;
$$;


ALTER FUNCTION "public"."recalculate_enrollment_tuition_effective_end"("p_tuition_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receive_instrument"("p_request" "uuid", "p_item" "uuid", "p_serial" "text", "p_branch" "uuid", "p_supplier" "text", "p_cost" numeric, "p_price" numeric, "p_currency" "text", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare old public.instrument_events; unit public.instrument_units; commercial public.instrument_commercial_details; result uuid;
begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Unauthorized'; end if;
 if p_request is null then raise exception 'Invalid instrument request'; end if;
 perform pg_advisory_xact_lock(hashtextextended('inventory-request:'||p_request::text,0));
 select * into old from public.instrument_events where movement_id=p_request;
 if found then
 select * into unit from public.instrument_units where id=old.unit_id;
 select * into commercial from public.instrument_commercial_details where unit_id=unit.id;
 if old.kind<>'RECEIPT' or old.created_by is distinct from auth.uid() or old.branch_id is distinct from p_branch or unit.item_id is distinct from p_item or unit.serial is distinct from trim(p_serial)
 or commercial.supplier is distinct from trim(p_supplier) or commercial.acquisition_cost is distinct from p_cost or commercial.asking_price is distinct from p_price or commercial.currency is distinct from p_currency or old.reason is distinct from trim(p_reason)
 then raise exception 'Inventory request payload mismatch'; end if;
 return unit.id;
 end if;
 perform 1 from public.inventory_items where id=p_item for update;
 if not found then raise exception 'Inventory item not found'; end if;
 insert into public.instrument_units(item_id,serial) values(p_item,trim(p_serial)) returning id into result;
 insert into public.instrument_commercial_details(unit_id,supplier,acquisition_cost,asking_price,currency) values(result,trim(p_supplier),p_cost,p_price,p_currency);
 insert into public.instrument_events(movement_id,unit_id,kind,branch_id,reason,created_by) values(p_request,result,'RECEIPT',p_branch,trim(p_reason),auth.uid());
 perform public.post_inventory_movement(p_request,p_item,p_branch,'RECEIPT',1,p_reason);
 return result;
end$$;


ALTER FUNCTION "public"."receive_instrument"("p_request" "uuid", "p_item" "uuid", "p_serial" "text", "p_branch" "uuid", "p_supplier" "text", "p_cost" numeric, "p_price" numeric, "p_currency" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_integration_webhook_event"("p_provider" "text", "p_external_event_id" "text", "p_event_type" "text", "p_payload" "jsonb", "p_payload_digest" "text", "p_supported" boolean) RETURNS TABLE("event_id" "uuid", "event_status" "text", "is_duplicate" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  existing public.integration_webhook_events;
  next_status text;
begin
  if p_provider is distinct from 'ZALO' then
    raise exception 'Unsupported provider';
  end if;
  if p_payload_digest is null or p_payload_digest !~ '^[0-9a-f]{64}$' then
    raise exception 'Payload digest required';
  end if;
  if p_event_type is null or p_event_type !~ '^[A-Za-z0-9_]{1,80}$' then
    raise exception 'Event type required';
  end if;
  if p_external_event_id is not null and p_external_event_id !~ '^[A-Za-z0-9_-]{1,80}$' then
    raise exception 'External event id invalid';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Payload object required';
  end if;
  if p_payload ?| array['access_token', 'refresh_token', 'app_secret', 'oa_secret', 'secret'] then
    raise exception 'Secret material refused';
  end if;
  if p_supported is null then
    raise exception 'Supported flag required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('zalo-webhook:' || p_payload_digest, 0));
  select * into existing
  from public.integration_webhook_events
  where provider = 'ZALO' and payload_digest = p_payload_digest;
  if found then
    return query select existing.id, existing.status, true;
    return;
  end if;

  next_status := case when p_supported then 'ACCEPTED' else 'UNSUPPORTED' end;
  return query
  insert into public.integration_webhook_events(
    provider, external_event_id, event_type, status, payload, payload_digest,
    verification_result, attempt_count
  ) values (
    'ZALO', p_external_event_id, p_event_type, next_status, p_payload, p_payload_digest,
    'VALID', 1
  )
  returning id, status, false;
end;
$_$;


ALTER FUNCTION "public"."record_integration_webhook_event"("p_provider" "text", "p_external_event_id" "text", "p_event_type" "text", "p_payload" "jsonb", "p_payload_digest" "text", "p_supported" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_learning_activity"("p_version" "uuid", "p_lesson" "text", "p_kind" "text", "p_request" "uuid" DEFAULT NULL::"uuid", "p_response" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$declare v public.learning_versions; learner uuid; previous public.learning_practice_attempts;begin
 select * into v from public.learning_versions where id=p_version and state='PUBLISHED' for share;
 if not found then raise exception 'Learning content unavailable'; end if;
 learner:=public.learning_learner_for_level(v.level_id);
 if learner is null then raise exception 'Learning access denied or expired'; end if;
 if not exists(select 1 from jsonb_array_elements(v.content->'modules') m cross join lateral jsonb_array_elements(m->'lessons') l where l->>'code'=p_lesson) then raise exception 'Lesson not found'; end if;
 if p_kind='COMPLETE_LESSON' then
 insert into public.learning_lesson_progress(student_id,version_id,lesson_code) values(learner,p_version,p_lesson) on conflict do nothing;
 elsif p_kind='PRACTICE' and p_request is not null then
 perform pg_advisory_xact_lock(hashtextextended('learning-practice:'||p_request::text,0));
 select * into previous from public.learning_practice_attempts where id=p_request;
 if found then
 if previous.student_id is distinct from learner or previous.version_id is distinct from p_version or previous.lesson_code is distinct from p_lesson or previous.response is distinct from p_response then raise exception 'Practice request mismatch'; end if;
 else insert into public.learning_practice_attempts(id,student_id,version_id,lesson_code,response) values(p_request,learner,p_version,p_lesson,p_response); end if;
 else raise exception 'Unsupported learning activity'; end if;
end$$;


ALTER FUNCTION "public"."record_learning_activity"("p_version" "uuid", "p_lesson" "text", "p_kind" "text", "p_request" "uuid", "p_response" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_legacy_import_failure"("p_row" "uuid", "p_version" integer, "p_code" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare r public.migration_batch_rows%rowtype; b public.migration_batches%rowtype; safe_code text;
begin
 select * into r from public.migration_batch_rows where id=p_row for update;
 select * into b from public.migration_batches where id=r.batch_id;
 if b.id is null or not public.has_role('SUPER_ADMIN') or not public.has_permission('migration.import',b.branch_id) then raise exception 'Unauthorized'; end if;
 if r.status<>'READY' or p_version is null or r.version<>p_version then return; end if;
 safe_code:=case when p_code ~ '^[A-Z0-9]{5,20}$' then p_code else 'UNCONFIRMED' end;
 update public.migration_batch_rows set last_import_error=safe_code where id=p_row;
 insert into public.migration_audit_events(row_id,batch_id,actor_id,action,reason,row_version) values(p_row,b.id,auth.uid(),'IMPORT_FAILED',safe_code,p_version);
end $_$;


ALTER FUNCTION "public"."record_legacy_import_failure"("p_row" "uuid", "p_version" integer, "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_operating_expense"("p_record" "uuid", "p_version" integer, "p_expense_date" "date", "p_due_date" "date", "p_actual_amount" numeric, "p_vendor" "text", "p_reference" "text", "p_note" "text", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare rec public.operating_expense_records; payload jsonb; prior jsonb; vendor_name text; reference_text text; note_text text; before_data jsonb; result jsonb;
begin
  select * into rec from public.operating_expense_records where id=p_record for update;
  if not found then raise exception 'OPERATING_EXPENSE_RECORD_NOT_FOUND'; end if;
  if not vibe_operating_expense_private.can_manage(rec.branch_id) then raise exception 'OPERATING_EXPENSE_UNAUTHORIZED'; end if;
  vendor_name:=nullif(btrim(coalesce(p_vendor,'')),'');
  reference_text:=nullif(btrim(coalesce(p_reference,'')),'');
  note_text:=nullif(btrim(coalesce(p_note,'')),'');
  payload:=jsonb_build_object(
    'operation','RECORDED','record_id',p_record,'version',p_version,'expense_date',p_expense_date,'due_date',p_due_date,
    'actual_amount',p_actual_amount,'vendor',vendor_name,'reference',reference_text,'note',note_text
  );
  prior:=vibe_operating_expense_private.replay(p_key,payload);
  if prior is not null then return prior; end if;
  if rec.status<>'DRAFT' then raise exception 'OPERATING_EXPENSE_DRAFT_REQUIRED'; end if;
  if p_version is distinct from rec.version then raise exception 'OPERATING_EXPENSE_CHANGED_RELOAD'; end if;
  if p_expense_date is null or not isfinite(p_expense_date) then raise exception 'OPERATING_EXPENSE_INVALID_DATE'; end if;
  if p_due_date is not null and not isfinite(p_due_date) then raise exception 'OPERATING_EXPENSE_INVALID_DATE'; end if;
  if not vibe_operating_expense_private.money_ok(p_actual_amount,rec.currency,true) then
    if rec.currency='VND' and p_actual_amount is not null and p_actual_amount<>trunc(p_actual_amount) then
      raise exception 'OPERATING_EXPENSE_VND_REQUIRES_WHOLE_DONG';
    end if;
    raise exception 'OPERATING_EXPENSE_INVALID_AMOUNT';
  end if;
  before_data:=vibe_operating_expense_private.record_view(p_record);
  update public.operating_expense_records set
    expense_date=p_expense_date,due_date=p_due_date,actual_amount=p_actual_amount,vendor=vendor_name,
    reference=reference_text,note=note_text,status='RECORDED',recorded_by=auth.uid(),recorded_at=clock_timestamp(),
    version=version+1,updated_at=clock_timestamp()
  where id=p_record;
  result:=vibe_operating_expense_private.record_view(p_record)||jsonb_build_object('record_id',p_record,'status','RECORDED','payment_status','NO_OUTGOING_PAYMENT_LEDGER');
  return vibe_operating_expense_private.write_event(rec.template_id,p_record,'RECORDED',p_key,payload,before_data,result,result);
end;
$$;


ALTER FUNCTION "public"."record_operating_expense"("p_record" "uuid", "p_version" integer, "p_expense_date" "date", "p_due_date" "date", "p_actual_amount" numeric, "p_vendor" "text", "p_reference" "text", "p_note" "text", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_payroll_disbursement"("p_payroll" "uuid", "p_amount" numeric, "p_currency" "text", "p_paid_on" "date", "p_payment_method" "text", "p_reference" "text", "p_note" "text", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  pay public.teacher_payrolls; period public.payroll_periods; locked record; employee uuid; payable numeric; paid numeric; remaining numeric;
  payload jsonb; prior public.payroll_disbursements; payment_id uuid:=gen_random_uuid(); result jsonb;
begin
  if auth.uid() is null or not coalesce(public.account_is_active(),false) then raise exception 'PAYROLL_DISBURSEMENT_UNAUTHORIZED'; end if;
  if p_key is null then raise exception 'PAYROLL_DISBURSEMENT_REQUEST_KEY_REQUIRED'; end if;
  if p_reference is not null and (char_length(btrim(p_reference))<1 or char_length(btrim(p_reference))>200) then raise exception 'PAYROLL_DISBURSEMENT_INVALID_REFERENCE'; end if;
  if p_note is not null and (char_length(btrim(p_note))<1 or char_length(btrim(p_note))>2000) then raise exception 'PAYROLL_DISBURSEMENT_INVALID_NOTE'; end if;
  payload:=jsonb_build_object('operation','RECORD','payroll_id',p_payroll,'amount',p_amount,'currency',p_currency,
    'paid_on',p_paid_on,'payment_method',p_payment_method,'reference',nullif(btrim(p_reference),''),'note',nullif(btrim(p_note),''));
  perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||':'||p_key::text,0));
  select * into prior from public.payroll_disbursements where created_by=auth.uid() and request_key=p_key;
  if found then
    if prior.request_payload<>payload then raise exception 'PAYROLL_DISBURSEMENT_REQUEST_KEY_REUSED'; end if;
    return prior.request_result;
  end if;

  select payrow pay,periodrow period into locked
  from public.teacher_payrolls payrow join public.payroll_periods periodrow on periodrow.id=payrow.period_id
  where payrow.id=p_payroll for update of payrow,periodrow;
  if not found then raise exception 'PAYROLL_DISBURSEMENT_PAYROLL_NOT_FOUND'; end if;
  pay:=locked.pay; period:=locked.period;
  if period.status<>'FINALIZED' then raise exception 'PAYROLL_DISBURSEMENT_FINALIZED_REQUIRED'; end if;
  if not (public.is_global_super_admin() or public.has_role_permission('FINANCE','payroll.disburse',pay.branch_id)) then raise exception 'PAYROLL_DISBURSEMENT_UNAUTHORIZED'; end if;
  if p_amount is null or p_amount<='0'::numeric or p_amount='NaN'::numeric or p_amount<>round(p_amount,2) then raise exception 'PAYROLL_DISBURSEMENT_INVALID_AMOUNT'; end if;
  if p_currency is null or p_currency<>pay.currency then raise exception 'PAYROLL_DISBURSEMENT_CURRENCY_MISMATCH'; end if;
  if p_currency='VND' and p_amount<>trunc(p_amount) then raise exception 'PAYROLL_DISBURSEMENT_VND_WHOLE_REQUIRED'; end if;
  if p_payment_method is null or p_payment_method not in('BANK_TRANSFER','CASH','OTHER') then raise exception 'PAYROLL_DISBURSEMENT_INVALID_METHOD'; end if;
  if p_paid_on is null or not isfinite(p_paid_on) or p_paid_on>(now() at time zone 'Asia/Ho_Chi_Minh')::date then raise exception 'PAYROLL_DISBURSEMENT_INVALID_DATE'; end if;
  employee:=pay.employee_id;
  if employee is null then select id into employee from public.employees where teacher_id=pay.teacher_id order by hire_date,id limit 1; end if;
  if employee is null then raise exception 'PAYROLL_DISBURSEMENT_EMPLOYEE_REQUIRED'; end if;
  payable:=payroll_disbursement_private.payable_amount(pay);
  if payable<=0 then raise exception 'PAYROLL_DISBURSEMENT_POSITIVE_PAYABLE_REQUIRED'; end if;
  select coalesce(sum(amount),0) into paid from public.payroll_disbursements where payroll_id=pay.id and status='ACTIVE';
  remaining:=payable-paid;
  if p_amount>remaining then raise exception 'PAYROLL_DISBURSEMENT_EXCEEDS_REMAINING'; end if;
  paid:=paid+p_amount; remaining:=payable-paid;
  result:=jsonb_build_object('payroll_id',pay.id,'payment_id',payment_id,'amount',p_amount,'paid_amount',paid,
    'remaining_amount',remaining,'payment_status',case when remaining=0 then 'PAID' else 'PARTIALLY_PAID' end);
  insert into public.payroll_disbursements(id,payroll_id,period_id,employee_id,branch_id,amount,currency,paid_on,payment_method,
    reference,note,request_key,request_payload,request_result,created_by)
  values(payment_id,pay.id,pay.period_id,employee,pay.branch_id,p_amount,p_currency,p_paid_on,p_payment_method,
    nullif(btrim(p_reference),''),nullif(btrim(p_note),''),p_key,payload,result,auth.uid());
  return result;
end;
$$;


ALTER FUNCTION "public"."record_payroll_disbursement"("p_payroll" "uuid", "p_amount" numeric, "p_currency" "text", "p_paid_on" "date", "p_payment_method" "text", "p_reference" "text", "p_note" "text", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_registration_zalo_phone_consent"("p_application" "uuid", "p_phone" "text", "p_confirmed" boolean) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  normalized text := notification_private.normalize_vn_phone(p_phone);
begin
  if auth.uid() is null or not public.has_role('SUPER_ADMIN') then
    raise exception 'Unauthorized';
  end if;
  if p_confirmed is distinct from true then
    raise exception 'PHONE_CONSENT_REQUIRED';
  end if;
  if normalized is null then
    raise exception 'PHONE_INVALID';
  end if;
  if not exists (select 1 from public.registration_applications where id = p_application) then
    raise exception 'Registration not found';
  end if;
  -- Same lock order as dispatch: job, registration, consent.
  perform 1 from notification_jobs where entity_id=p_application and entity_type='REGISTRATION_COMPLETED' and channel='ZALO' order by id for update;
  perform 1 from registration_applications where id=p_application for update;
  update public.registration_zalo_phone_consents
  set revoked_at = clock_timestamp()
  where application_id = p_application and revoked_at is null and normalized_phone is distinct from normalized;
  insert into public.registration_zalo_phone_consents(
    application_id, normalized_phone, notice_version, source, actor_id
  )
  select p_application, normalized, 'zbs-phone-v1', 'REGISTRATION_FORM', auth.uid()
  where not exists (
    select 1 from public.registration_zalo_phone_consents
    where application_id = p_application and revoked_at is null and normalized_phone = normalized
  );
  return left(normalized, 4) || '…' || right(normalized, 3);
end $$;


ALTER FUNCTION "public"."record_registration_zalo_phone_consent"("p_application" "uuid", "p_phone" "text", "p_confirmed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_staff_portrait"("p_employee" "uuid", "p_path" "text", "p_type" "text", "p_bytes" integer, "p_width" integer, "p_height" integer) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  previous text;
  result uuid;
begin
  if not coalesce(public.has_role('SUPER_ADMIN'), false) then
    raise exception 'STAFF_PROFILE_UNAUTHORIZED';
  end if;
  if not exists(select 1 from public.employees where id = p_employee) then
    raise exception 'STAFF_EMPLOYEE_NOT_FOUND';
  end if;
  if p_path is distinct from p_employee::text || '/' || split_part(p_path, '/', 2)
     or split_part(p_path, '/', 2) !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png|webp)$'
     or p_type not in ('image/jpeg', 'image/png', 'image/webp')
     or p_bytes is null or p_bytes <= 0 or p_bytes > 2000000
     or p_width is null or p_height is null
     or p_width < 400 or p_height < 400 or p_width > 4000 or p_height > 4000
  then
    raise exception 'STAFF_PORTRAIT_INVALID';
  end if;
  perform 1 from public.employees where id = p_employee for update;
  select storage_path into previous
  from public.staff_portraits
  where employee_id = p_employee and status = 'ACTIVE'
  for update;
  update public.staff_portraits
  set status = 'REPLACED'
  where employee_id = p_employee and status = 'ACTIVE';
  insert into public.staff_portraits(
    employee_id, storage_path, content_type, byte_size, width, height, created_by
  ) values (
    p_employee, p_path, p_type, p_bytes, p_width, p_height, auth.uid()
  ) returning id into result;
  insert into public.employee_audit(employee_id, action, before_data, after_data, reason, actor)
  values (
    p_employee,
    'PORTRAIT_RECORDED',
    case when previous is null then null else jsonb_build_object('storage_path', previous) end,
    jsonb_build_object('id', result),
    'Cập nhật chân dung hồ sơ nhân sự',
    auth.uid()
  );
  return previous;
end;
$_$;


ALTER FUNCTION "public"."record_staff_portrait"("p_employee" "uuid", "p_path" "text", "p_type" "text", "p_bytes" integer, "p_width" integer, "p_height" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_tuition_zalo_api_reply"("p_template_id" "text", "p_app_id" "text", "p_oa_id" "text", "p_row_oa_id" "text", "p_tracking_id" "text", "p_message_id" "text", "p_button" "text", "p_submit_ms" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  outcome text;
  reply uuid;
  submit_at timestamptz;
begin
  if p_template_id is null or p_template_id !~ '^[0-9]{1,20}$' or p_app_id is null or p_app_id !~ '^[0-9]{8,32}$' then
    return 'invalid_report';
  end if;
  if p_oa_id is null or p_row_oa_id is distinct from p_oa_id then
    outcome := 'oa_mismatch';
  elsif not exists (
    select 1 from public.notification_templates template
    where template.template_key = 'ZALO_TUITION_REMINDER'
      and template.provider_template_id = p_template_id
  ) then
    outcome := 'template_mismatch';
  elsif p_app_id is distinct from (
    select credential.app_id from notification_private.zalo_credentials credential
    where credential.oa_id = p_oa_id
    limit 1
  ) then
    outcome := 'app_mismatch';
  elsif exists (select 1 from tuition_zalo_sends candidate where candidate.tracking_id=p_tracking_id
    and candidate.context_captured_at is not null and candidate.app_id is distinct from p_app_id) then
    outcome := 'app_mismatch';
  elsif exists (select 1 from tuition_zalo_sends candidate where candidate.tracking_id=p_tracking_id
    and candidate.context_captured_at is not null and candidate.provider_template_id is distinct from p_template_id) then
    outcome := 'template_mismatch';
  elsif p_submit_ms is null or p_submit_ms !~ '^[0-9]{13}$' then
    outcome := 'invalid_time';
  elsif exists (
    select 1 from public.tuition_zalo_sends candidate
    where candidate.tracking_id = p_tracking_id
      and candidate.sent_at is not null
      and coalesce(candidate.context_captured_at,candidate.sent_at) > to_timestamp(p_submit_ms::numeric / 1000.0)
  ) then
    outcome := 'invalid_time';
  else
    outcome := public.record_tuition_zalo_reply('Zalo response API', p_tracking_id, p_message_id, p_button, p_submit_ms, p_oa_id);
  end if;
  if p_submit_ms ~ '^[0-9]{13}$' and p_tracking_id ~ '^[A-Za-z0-9]{1,48}$' and p_message_id ~ '^[A-Za-z0-9_-]{1,80}$' and p_button in ('Tiếp tục học', 'Dừng học', 'Yêu cầu khác') and p_oa_id ~ '^[0-9]{8,32}$' then
    submit_at := to_timestamp(p_submit_ms::numeric / 1000.0);
    if exists (
      select 1 from public.tuition_zalo_reply_api_events prior
      where prior.tracking_id = p_tracking_id
        and prior.message_id = p_message_id
        and prior.response_text = p_button
        and prior.submit_time = submit_at
        and prior.result = outcome
    ) then
      return outcome;
    end if;
    select id into reply
    from public.tuition_zalo_replies
    where event_key = p_tracking_id || ':' || p_submit_ms || ':' || p_button || ':' || p_message_id;
    insert into public.tuition_zalo_reply_api_events(
      reply_id, template_id, app_id, oa_id, tracking_id, message_id, response_text, submit_time, result
    ) values (
      reply, p_template_id, p_app_id, p_oa_id, p_tracking_id, p_message_id, p_button, submit_at, outcome
    );
  end if;
  return outcome;
end $_$;


ALTER FUNCTION "public"."record_tuition_zalo_api_reply"("p_template_id" "text", "p_app_id" "text", "p_oa_id" "text", "p_row_oa_id" "text", "p_tracking_id" "text", "p_message_id" "text", "p_button" "text", "p_submit_ms" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_tuition_zalo_attempt"("p_reminder" "uuid", "p_parent" "uuid", "p_outcome" "text", "p_error" "text" DEFAULT NULL::"text", "p_receipt" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  reminder public.tuition_reminders;
  parent_user uuid;
  job_id uuid;
  job_status text;
  key text;
begin
  if not coalesce(public.has_role('SUPER_ADMIN'), false) then
    raise exception 'SUPER_ADMIN role required';
  end if;
  if p_outcome not in ('ERROR', 'SENT') then
    raise exception 'Invalid tuition Zalo outcome';
  end if;
  if p_outcome = 'SENT' and (p_error is not null or nullif(btrim(coalesce(p_receipt, '')), '') is null) then
    raise exception 'Sent tuition Zalo requires provider receipt';
  end if;
  if p_outcome = 'ERROR' and p_error is distinct from 'PROVIDER_NOT_CONFIGURED' then
    raise exception 'Invalid tuition Zalo error';
  end if;
  select * into reminder from public.tuition_reminders where id = p_reminder;
  if not found then
    raise exception 'Tuition reminder not found';
  end if;
  select user_id into parent_user from public.parents where id = p_parent and status = 'ACTIVE';
  if not found then
    raise exception 'Tuition recipient not found';
  end if;
  key := 'TUITION_ZALO:' || p_reminder::text || ':' || p_parent::text;
  insert into public.notification_jobs(
    recipient_id, recipient_subject_type, recipient_subject_id, student_id, branch_id,
    channel, delivery_mode, template_key, payload, entity_type, entity_id,
    idempotency_key, status, attempts, error_code, provider_receipt, sent_at, created_by
  )
  select parent_user, 'PARENT', p_parent, enrollment.student_id, tuition.branch_id_snapshot,
    'ZALO', 'MOCK', 'ZALO_TUITION_REMINDER',
    jsonb_build_object('template_key', 'ZALO_TUITION_REMINDER', 'outcome', p_outcome),
    'TUITION_REMINDER', p_reminder, key,
    case when p_outcome = 'SENT' then 'SENT' else 'FAILED' end,
    1,
    case when p_outcome = 'ERROR' then p_error else null end,
    case when p_outcome = 'SENT' then p_receipt else null end,
    case when p_outcome = 'SENT' then clock_timestamp() else null end,
    auth.uid()
  from public.enrollment_tuition tuition
  join public.enrollments enrollment on enrollment.id = tuition.enrollment_id
  where tuition.id = reminder.enrollment_tuition_id
  on conflict (idempotency_key) do nothing
  returning id into job_id;
  select status into job_status from public.notification_jobs where idempotency_key = key;
  if job_id is not null then
    insert into public.notification_events(job_id, event, actor_id, details)
    values (job_id, case when p_outcome = 'SENT' then 'CONFIRMED' else 'FAILED' end, auth.uid(),
      jsonb_build_object('mode', 'MOCK', 'error_code', p_error));
  end if;
  return case job_status when 'SENT' then 'SENT' when 'DELIVERED' then 'SENT' when 'FAILED' then 'ERROR' else 'NOT_SENT' end;
end $$;


ALTER FUNCTION "public"."record_tuition_zalo_attempt"("p_reminder" "uuid", "p_parent" "uuid", "p_outcome" "text", "p_error" "text", "p_receipt" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_tuition_zalo_contact_note"("p_reminder" "uuid", "p_note" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  state public.tuition_zalo_reply_states;
begin
  if auth.uid() is null or not coalesce(public.has_role('SUPER_ADMIN'), false) then
    raise exception 'SUPER_ADMIN role required';
  end if;
  if p_note is null or nullif(btrim(p_note), '') is null or char_length(btrim(p_note)) > 2000 then
    raise exception 'Invalid tuition contact note';
  end if;
  select * into state from public.tuition_zalo_reply_states where reminder_id = p_reminder for update;
  if not found or state.reply_choice is distinct from 'CONTACT' then
    raise exception 'Tuition contact note requires the current other-request reply';
  end if;
  update public.tuition_zalo_reply_states
  set contact_note = btrim(p_note),
      contact_noted_at = clock_timestamp(),
      contact_noted_by = auth.uid()
  where reminder_id = p_reminder
    and reply_choice = 'CONTACT';
  return 'noted';
end $$;


ALTER FUNCTION "public"."record_tuition_zalo_contact_note"("p_reminder" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_tuition_zalo_notice_consent"("p_student" "uuid", "p_parent" "uuid", "p_confirmed" boolean, "p_source" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or not coalesce(public.has_role('SUPER_ADMIN'), false) then
    raise exception 'SUPER_ADMIN role required';
  end if;
  if p_confirmed is distinct from true then
    raise exception 'Tuition notice consent must be confirmed';
  end if;
  if p_source is null or p_source not in (
    'TUITION_NOTICE_IN_PERSON',
    'TUITION_NOTICE_PHONE',
    'TUITION_NOTICE_WRITTEN'
  ) then
    raise exception 'Invalid tuition notice consent source';
  end if;
  if not exists (
    select 1
    from public.student_parents link
    join public.parents parent on parent.id = link.parent_id and parent.status = 'ACTIVE'
    join public.students student on student.id = link.student_id and student.status = 'ACTIVE'
    where link.student_id = p_student
      and link.parent_id = p_parent
      and link.can_view_finance
      and link.is_active
      and (link.valid_from is null or link.valid_from <= clock_timestamp())
      and (link.valid_until is null or link.valid_until > clock_timestamp())
  ) then
    raise exception 'Tuition recipient not found';
  end if;
  if exists (
    select 1 from public.tuition_zalo_consents consent
    where consent.student_id = p_student
      and consent.parent_id = p_parent
      and consent.revoked_at is null
  ) then
    return 'already_recorded';
  end if;
  insert into public.tuition_zalo_consents (
    student_id, parent_id, granted_at, revoked_at, consent_scope, source, recorded_by
  ) values (
    p_student, p_parent, clock_timestamp(), null, 'ONE_STUDENT', p_source, auth.uid()
  )
  on conflict (student_id, parent_id) do update
    set granted_at = excluded.granted_at,
        revoked_at = null,
        consent_scope = 'ONE_STUDENT',
        source = excluded.source,
        recorded_by = excluded.recorded_by
    where public.tuition_zalo_consents.revoked_at is not null;
  return 'recorded';
end $$;


ALTER FUNCTION "public"."record_tuition_zalo_notice_consent"("p_student" "uuid", "p_parent" "uuid", "p_confirmed" boolean, "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_tuition_zalo_reply"("p_source" "text", "p_tracking" "text", "p_message_id" "text", "p_button" "text", "p_submit_ms" "text", "p_oa_id" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  choice text;
  submit_at timestamptz;
  reply_event_key text;
  send public.tuition_zalo_sends;
  inserted uuid;
  different boolean;
begin
  if p_source is null or p_source not in ('Zalo ZBS', 'Zalo response report import', 'Zalo response API') then
    return 'invalid_source';
  end if;
  if p_oa_id is null or p_oa_id !~ '^[0-9]{8,32}$' then
    return 'oa_mismatch';
  end if;
  if p_message_id is null or p_message_id !~ '^[A-Za-z0-9_-]{1,80}$' then
    return 'invalid_message';
  end if;
  if p_button = 'Tiếp tục học' then
    choice := 'CONTINUE';
  elsif p_button = 'Dừng học' then
    choice := 'STOP';
  elsif p_button = 'Yêu cầu khác' then
    choice := 'CONTACT';
  else
    return 'invalid_button';
  end if;
  if p_tracking is null or p_tracking !~ '^[A-Za-z0-9]{1,48}$' then
    return 'invalid_tracking';
  end if;
  if p_submit_ms is null or p_submit_ms !~ '^[0-9]{13}$' then
    return 'invalid_time';
  end if;
  submit_at := to_timestamp(p_submit_ms::numeric / 1000.0);
  select * into send from public.tuition_zalo_sends where tracking_id = p_tracking for update;
  if not found then
    return 'unknown_tracking';
  end if;
  if send.send_status not in ('SENT', 'DELIVERED') or send.provider_message_id is null then
    return 'send_not_accepted';
  end if;
  if send.provider_message_id is distinct from p_message_id then
    return 'message_mismatch';
  end if;
  if send.oa_id is not null and send.oa_id is distinct from p_oa_id then
    return 'oa_mismatch';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('tuition-zalo-reply:' || send.reminder_id::text, 0));
  if exists (
    select 1 from public.tuition_zalo_replies reply
    where reply.tracking_id = p_tracking
      and reply.provider_message_id = p_message_id
      and reply.button_data = p_button
      and floor(extract(epoch from reply.submit_time)) = floor(extract(epoch from submit_at))
  ) then
    return 'duplicate';
  end if;
  different := exists (
    select 1 from public.tuition_zalo_replies reply
    where reply.provider_message_id = p_message_id
      and reply.tracking_id = p_tracking
      and reply.button_data <> p_button
  );
  reply_event_key := p_tracking || ':' || p_submit_ms || ':' || p_button || ':' || p_message_id;
  insert into public.tuition_zalo_replies(
    send_id, reminder_id, student_id, tracking_id, reply_choice, button_data,
    submit_time, provider_message_id, oa_id, source, event_key
  ) values (
    send.id, send.reminder_id, send.student_id, p_tracking, choice, p_button,
    submit_at, p_message_id, p_oa_id, p_source, reply_event_key
  )
  on conflict (event_key) do nothing
  returning id into inserted;
  if inserted is null then
    return 'duplicate';
  end if;
  if exists (
    select 1 from public.tuition_zalo_reply_states state
    where state.reminder_id = send.reminder_id
      and state.student_id <> send.student_id
  ) then
    raise exception 'Tuition reply student mismatch';
  end if;
  insert into public.tuition_zalo_reply_states(
    reminder_id, student_id, reply_choice, submit_time, needs_review, updated_at
  )
  select send.reminder_id, send.student_id, picked.reply_choice, picked.submit_time,
    (
      select count(distinct prior.reply_choice) > 1
      from public.tuition_zalo_replies prior
      where prior.reminder_id = send.reminder_id
    ),
    clock_timestamp()
  from (
    select reply.reply_choice, reply.submit_time
    from public.tuition_zalo_replies reply
    where reply.reminder_id = send.reminder_id
    order by reply.submit_time desc, reply.received_at desc, reply.seq desc
    limit 1
  ) picked
  on conflict (reminder_id) do update
  set reply_choice = excluded.reply_choice,
      submit_time = excluded.submit_time,
      needs_review = excluded.needs_review,
      updated_at = excluded.updated_at
  where public.tuition_zalo_reply_states.student_id = excluded.student_id;
  if different then
    return 'conflict';
  end if;
  return 'recorded';
end $_$;


ALTER FUNCTION "public"."record_tuition_zalo_reply"("p_source" "text", "p_tracking" "text", "p_message_id" "text", "p_button" "text", "p_submit_ms" "text", "p_oa_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_verified_momo_ipn"("p_order_id" "text", "p_partner_code" "text", "p_transaction_id" "text", "p_amount" bigint, "p_result_code" integer) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare ord public.registration_momo_orders%rowtype;
  app public.registration_applications%rowtype;
  terms public.registration_deposit_terms%rowtype;
  paid_total bigint;
begin
  if not coalesce(public.momo_service_request(), false) then
    raise exception 'MOMO_SERVER_ONLY';
  end if;
  select * into ord from public.registration_momo_orders where order_id = p_order_id;
  if not found then raise exception 'MOMO_ORDER_MISMATCH'; end if;
  select * into app from public.registration_applications where id = ord.application_id for update;
  select * into ord from public.registration_momo_orders where order_id = p_order_id for update;
  if not found or ord.state not in ('READY', 'PAID') or ord.partner_code is distinct from p_partner_code
     or p_transaction_id is null or p_transaction_id = '' or p_amount is distinct from ord.amount then
    raise exception 'MOMO_ORDER_MISMATCH';
  end if;
  if p_result_code <> 0 then return 'IGNORED_NON_SUCCESS'; end if;
  if ord.state = 'PAID' then
    if ord.provider_transaction_id <> p_transaction_id then raise exception 'MOMO_TRANSACTION_CONFLICT'; end if;
    return 'ALREADY_PAID';
  end if;
  select * into terms from public.registration_deposit_terms where application_id = app.id;
  if not found or app.status not in ('VERIFIED', 'PAYMENT_PENDING') then
    raise exception 'REGISTRATION_DEPOSIT_MISMATCH';
  end if;
  insert into public.registration_momo_ipn_events(order_id, provider_transaction_id, result_code, amount)
    values(ord.order_id, p_transaction_id, p_result_code, p_amount);
  update public.registration_momo_orders set state = 'PAID', provider_transaction_id = p_transaction_id,
    paid_at = clock_timestamp() where id = ord.id;
  select coalesce(sum(amount), 0)::bigint into paid_total from public.registration_momo_orders
    where application_id = app.id and state = 'PAID';
  if paid_total < terms.amount_due then return 'PARTIAL_DEPOSIT'; end if;
  perform set_config('registration.write', 'on', true);
  update public.registration_applications set status = 'PAID',
    deposit_confirmed_at = clock_timestamp(), version = version + 1,
    updated_at = clock_timestamp() where id = app.id;
  perform set_config('registration.write', 'off', true);
  return public.complete_momo_deposit_registration(app.id);
end $$;


ALTER FUNCTION "public"."record_verified_momo_ipn"("p_order_id" "text", "p_partner_code" "text", "p_transaction_id" "text", "p_amount" bigint, "p_result_code" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_verified_payos_webhook"("p_order_code" bigint, "p_payment_link_id" "text", "p_reference" "text", "p_amount" bigint, "p_currency" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  ord public.registration_payos_orders%rowtype;
  app public.registration_applications%rowtype;
  terms public.registration_deposit_terms%rowtype;
  paid_total bigint;
begin
  if not coalesce(public.momo_service_request(), false) then raise exception 'PAYOS_SERVER_ONLY'; end if;
  if p_currency is distinct from 'VND' then raise exception 'PAYOS_CURRENCY_MISMATCH'; end if;
  if p_reference is null or btrim(p_reference) = '' then raise exception 'PAYOS_REFERENCE_REQUIRED'; end if;
  select * into ord from public.registration_payos_orders where order_code = p_order_code;
  if not found then raise exception 'PAYOS_ORDER_UNKNOWN'; end if;
  select * into app from public.registration_applications where id = ord.application_id for update;
  select * into ord from public.registration_payos_orders where order_code = p_order_code for update;
  if ord.payment_link_id is not null and ord.payment_link_id is distinct from p_payment_link_id then
    raise exception 'PAYOS_LINK_MISMATCH';
  end if;
  if p_amount is null or p_amount <= 0 or p_amount > ord.amount then raise exception 'PAYOS_AMOUNT_MISMATCH'; end if;
  if ord.state in ('CANCELLED', 'EXPIRED') then
    insert into public.registration_payos_webhook_events(order_code, provider_reference, amount, outcome)
    values (ord.order_code, p_reference, p_amount, 'LATE_PAYMENT_REVIEW')
    on conflict (order_code, provider_reference) do nothing;
    update public.registration_payos_orders
    set state = 'EXCEPTION', provider_reference = coalesce(ord.provider_reference, p_reference)
    where id = ord.id and state in ('CANCELLED', 'EXPIRED');
    return 'LATE_PAYMENT_REVIEW';
  end if;
  if ord.state = 'EXCEPTION' then return 'LATE_PAYMENT_REVIEW'; end if;
  if ord.state = 'PAID' then
    if ord.provider_reference <> p_reference then raise exception 'PAYOS_REFERENCE_CONFLICT'; end if;
    return 'ALREADY_PAID';
  end if;
  if ord.state <> 'PENDING' then raise exception 'PAYOS_ORDER_STATE_CONFLICT'; end if;
  select * into terms from public.registration_deposit_terms where application_id = app.id;
  if not found or app.status not in ('VERIFIED', 'PAYMENT_PENDING') then
    raise exception 'REGISTRATION_DEPOSIT_MISMATCH';
  end if;
  insert into public.registration_payos_webhook_events(order_code, provider_reference, amount, outcome)
  values (ord.order_code, p_reference, p_amount, 'VERIFIED');
  update public.registration_payos_orders set state = 'PAID', provider_reference = p_reference,
    attributed_amount = p_amount, paid_at = clock_timestamp() where id = ord.id;
  paid_total := public.registration_payos_paid_total(app.id)
    + coalesce((select sum(amount) from public.registration_momo_orders
                where application_id = app.id and state = 'PAID'), 0);
  if paid_total < terms.amount_due then return 'PARTIAL_DEPOSIT'; end if;
  perform set_config('registration.write', 'on', true);
  update public.registration_applications set status = 'PAID',
    deposit_confirmed_at = clock_timestamp(), version = version + 1,
    updated_at = clock_timestamp() where id = app.id;
  perform set_config('registration.write', 'off', true);
  return public.complete_payos_registration(app.id);
end $$;


ALTER FUNCTION "public"."record_verified_payos_webhook"("p_order_code" bigint, "p_payment_link_id" "text", "p_reference" "text", "p_amount" bigint, "p_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_zalo_phone_acceptance"("p_job" "uuid", "p_message_id" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
begin
  if p_message_id is null or p_message_id !~ '^[A-Za-z0-9_-]{1,80}$' then
    return 'INVALID';
  end if;
  update public.notification_jobs
  set status = 'SENT', error_code = null, sent_at = clock_timestamp(), delivered_at = null,
    provider_message_id = p_message_id, provider_receipt = 'ZALO_PHONE_ACCEPTED',
    lease_token = null, lease_until = null, updated_at = clock_timestamp()
  where id = p_job and status = 'PROCESSING' and payload->'delivery'->>'channel' = 'PHONE' and provider_message_id is null;
  if not found then
    return 'NOT_RECORDED';
  end if;
  insert into public.notification_events(job_id, event, details)
  values (p_job, 'SENT', jsonb_build_object('state', 'ACCEPTED', 'channel', 'PHONE'));
  return 'ACCEPTED';
end $_$;


ALTER FUNCTION "public"."record_zalo_phone_acceptance"("p_job" "uuid", "p_message_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_zalo_phone_delivery"("p_message_id" "text", "p_tracking_id" "text", "p_recipient_phone" "text", "p_sender_id" "text", "p_delivery_time" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  job public.notification_jobs;
  device_time timestamptz;
begin
  if p_sender_id is null or p_recipient_phone is null or p_recipient_phone = p_sender_id then
    return 'IGNORED';
  end if;
  if p_recipient_phone !~ '^84[0-9]{9}$' or p_delivery_time !~ '^[0-9]{10,16}$' then
    return 'IGNORED';
  end if;
  device_time := to_timestamp(p_delivery_time::numeric / 1000.0);
  select * into job
  from public.notification_jobs
  where channel = 'ZALO'
    and provider_message_id = p_message_id
    and payload->'delivery'->>'tracking_id' = p_tracking_id
    and payload->'delivery'->>'normalized_recipient' = p_recipient_phone
    and payload->'delivery'->>'channel' = 'PHONE'
  for update;
  if not found then
    return 'IGNORED';
  end if;
  if job.status = 'DELIVERED' then
    return 'IDEMPOTENT';
  end if;
  if job.status is distinct from 'SENT' then
    return 'IGNORED';
  end if;
  update public.notification_jobs
  set status = 'DELIVERED', delivered_at = device_time, updated_at = clock_timestamp()
  where id = job.id and status = 'SENT';
  insert into public.notification_events(job_id, event, details)
  values (job.id, 'DELIVERED', jsonb_build_object('state', 'DELIVERED', 'delivery_time', p_delivery_time));
  return 'DELIVERED';
end $_$;


ALTER FUNCTION "public"."record_zalo_phone_delivery"("p_message_id" "text", "p_tracking_id" "text", "p_recipient_phone" "text", "p_sender_id" "text", "p_delivery_time" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_zalo_phone_rejection"("p_job" "uuid", "p_error" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare provider_error integer;
begin
  if p_error is null or (p_error not in (
    'PROVIDER_REJECTED', 'ZALO_TOKEN_EXPIRED', 'ZALO_TOKEN_INVALID',
    'ZALO_OUTBOUND_NOT_CONFIGURED', 'RECIPIENT_INELIGIBLE'
  ) and p_error !~ '^ZALO_PROVIDER_-?[0-9]{1,6}$') then
    return 'INVALID';
  end if;
  if p_error = 'ZALO_TOKEN_INVALID' then provider_error := -124;
  elsif p_error ~ '^ZALO_PROVIDER_' then provider_error := substring(p_error from 15)::integer;
  end if;
  update public.notification_jobs
  set status = 'FAILED', error_code = p_error, lease_token = null,
    lease_until = null, updated_at = clock_timestamp()
  where id = p_job and status = 'PROCESSING'
    and payload->'delivery'->>'channel' = 'PHONE' and provider_message_id is null;
  if not found then return 'NOT_RECORDED'; end if;
  insert into public.notification_events(job_id, event, details)
  values (p_job, 'FAILED', jsonb_strip_nulls(jsonb_build_object(
    'channel', 'PHONE', 'error_code', p_error, 'provider_error', provider_error)));
  return 'REJECTED';
end $_$;


ALTER FUNCTION "public"."record_zalo_phone_rejection"("p_job" "uuid", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_zalo_template_acceptance"("p_job" "uuid", "p_message_id" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  job public.notification_jobs;
begin
  if p_message_id is null or btrim(p_message_id) = '' then
    raise exception 'Provider message id required';
  end if;
  select * into job from public.notification_jobs where id = p_job for update;
  if not found or job.channel is distinct from 'ZALO' or job.status not in ('QUEUED', 'RETRYING') then
    raise exception 'Outbound job is not sendable';
  end if;
  update public.notification_jobs
  set status = 'SENT', attempts = job.attempts + 1, error_code = null,
    sent_at = clock_timestamp(), delivered_at = null,
    provider_receipt = 'ZALO_ACCEPTED', provider_message_id = left(btrim(p_message_id), 80),
    next_attempt_at = null, updated_at = clock_timestamp()
  where id = job.id;
  insert into public.notification_events(job_id, event, details)
  values (job.id, 'SENT', jsonb_build_object('state', 'ACCEPTED'));
  return 'ACCEPTED';
end $$;


