  set status = 'DELIVERED', delivered_at = clock_timestamp(), updated_at = clock_timestamp()
  where id = job.id;
  insert into public.notification_events(job_id, event, details)
  values (job.id, 'DELIVERED', jsonb_build_object('state', 'DELIVERED'));
  return 'DELIVERED';
end $$;


