CREATE OR REPLACE FUNCTION "public"."reevaluate_registration_zalo_channel"("p_application" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare j notification_jobs; c registration_zalo_phone_consents; src record;
begin
 if auth.uid() is null or not public.has_role('SUPER_ADMIN') then raise exception 'Unauthorized'; end if;
 -- Serialize with manual recovery/worker claims; never replace an attempted recipient.
 perform 1 from notification_jobs where entity_id=p_application and entity_type='REGISTRATION_COMPLETED' and channel='ZALO' order by id for update;
 perform 1 from registration_applications where id=p_application and status='COMPLETED' for update;
 if not found then return 'NOT_SENDABLE'; end if;
 if (select count(*) from notification_jobs where entity_id=p_application and entity_type='REGISTRATION_COMPLETED' and channel='ZALO') <> 1 then return 'ZALO_RETRY_DENIED'; end if;
 select * into j from notification_jobs where entity_id=p_application and entity_type='REGISTRATION_COMPLETED' and channel='ZALO';
 if j.status in ('SENT','DELIVERED') or j.sent_at is not null or j.provider_message_id is not null then return 'ALREADY_ACCEPTED'; end if;
 if j.provider_receipt is not null or exists(select 1 from notification_events where job_id=j.id and event in ('CLAIMED','SENT','FAILED')) or j.attempts<>0 or exists(select 1 from zalo_notification_attempts where job_id=j.id) or j.status not in ('SKIPPED_NO_CHANNEL','QUEUED') then return 'ZALO_RETRY_DENIED'; end if;
 select * into c from registration_zalo_phone_consents where application_id=p_application and revoked_at is null for share;
 if not found then return 'NO_CONSENT'; end if;
 if j.payload->'delivery'->>'channel'='PHONE' then
   if j.payload->'delivery'->>'consent_id' is distinct from c.id::text or j.payload->'delivery'->>'normalized_recipient' is distinct from c.normalized_phone then return 'WRONG_RECIPIENT'; end if;
   if j.status='QUEUED' then return 'CHANNEL_READY'; end if;
   if not exists(select 1 from notification_templates where template_key=j.template_key and enabled and status='APPROVED') then return 'GATE_DISABLED'; end if;
 end if;
 if j.status <> 'SKIPPED_NO_CHANNEL' then return 'ZALO_RETRY_DENIED'; end if;
 select * into src from notification_private.domain_notice_source('REGISTRATION_COMPLETED',p_application);
 if not found or notification_private.registration_phone_payment_status(p_application) is null then return 'NOT_SENDABLE'; end if;
 perform set_config('zalo.durable_write','on',true);
 update notification_jobs set status=case when exists(select 1 from notification_templates where template_key=j.template_key and enabled and status='APPROVED') then 'QUEUED' else 'SKIPPED_NO_CHANNEL' end,error_code=case when exists(select 1 from notification_templates where template_key=j.template_key and enabled and status='APPROVED') then null else 'GATE_DISABLED' end,updated_at=clock_timestamp(),
   payload=jsonb_build_object('title',src.title,'href',src.href,'parameters',src.parameters||jsonb_build_object('payment_status',notification_private.registration_phone_payment_status(p_application)),
     'delivery',jsonb_build_object('channel','PHONE','normalized_recipient',c.normalized_phone,'consent_id',c.id,'template_id','640377','notice_version',c.notice_version,'tracking_id',replace(j.id::text,'-','')))
 where id=j.id;
 insert into notification_events(job_id,event,actor_id,details) values(j.id,'RETRY',auth.uid(),jsonb_build_object('source','CHANNEL_REEVALUATION','previous_status',j.status,'request_sent',false));
 return case when exists(select 1 from notification_templates where template_key=j.template_key and enabled and status='APPROVED') then 'CHANNEL_READY' else 'GATE_DISABLED' end;
end $$;


ALTER FUNCTION "public"."reevaluate_registration_zalo_channel"("p_application" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_attendance_retention_alerts"("p_branch" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  signal record;
  existing public.student_retention_alerts%rowtype;
  created_count integer := 0;
  refreshed_count integer := 0;
  resolved_count integer := 0;
  actor uuid := auth.uid();
begin
  if actor is null
     or not coalesce(public.account_is_active(),false)
     or not coalesce(public.has_role('SUPER_ADMIN'),false)
  then
    raise exception 'RETENTION_ALERT_UNAUTHORIZED';
  end if;

  if p_branch is not null
     and not exists(
       select 1
       from public.branches
       where id=p_branch
     )
  then
    raise exception 'RETENTION_ALERT_BRANCH_INVALID';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('attendance_retention_v1',0)
  );

  for signal in
    select *
    from public.attendance_retention_signals_v1(p_branch)
  loop
    select *
      into existing
    from public.student_retention_alerts a
    where a.enrollment_id=signal.enrollment_id
      and a.rule_code='CONSECUTIVE_ABSENCE_2'
      and a.status in ('NEW','CONTACTED','FOLLOW_UP')
    for update;

    if found then
      update public.student_retention_alerts
      set
        student_id=signal.student_id,
        branch_id=signal.branch_id,
        class_id=signal.class_id,
        first_signal_on=signal.first_signal_on,
        last_signal_on=signal.last_signal_on,
        consecutive_absence_count=signal.consecutive_absence_count,
        evidence_snapshot=signal.evidence_snapshot,
        last_detected_at=clock_timestamp(),
        updated_at=clock_timestamp()
      where id=existing.id;

      insert into public.student_retention_events(
        alert_id,
        event_type,
        from_status,
        to_status,
        evidence_snapshot,
        actor_id
      )
      values(
        existing.id,
        'REFRESHED',
        existing.status,
        existing.status,
        signal.evidence_snapshot,
        actor
      );

      refreshed_count:=refreshed_count+1;

    else
      insert into public.student_retention_alerts(
        student_id,
        enrollment_id,
        branch_id,
        class_id,
        rule_code,
        severity,
        status,
        first_signal_on,
        last_signal_on,
        consecutive_absence_count,
        evidence_snapshot
      )
      values(
        signal.student_id,
        signal.enrollment_id,
        signal.branch_id,
        signal.class_id,
        'CONSECUTIVE_ABSENCE_2',
        'HIGH',
        'NEW',
        signal.first_signal_on,
        signal.last_signal_on,
        signal.consecutive_absence_count,
        signal.evidence_snapshot
      )
      returning * into existing;

      insert into public.student_retention_events(
        alert_id,
        event_type,
        to_status,
        evidence_snapshot,
        actor_id
      )
      values(
        existing.id,
        'DETECTED',
        'NEW',
        signal.evidence_snapshot,
        actor
      );

      created_count:=created_count+1;
    end if;
  end loop;

  -- Auto-resolve open alerts when latest completed REGULAR attendance
  -- is no longer an absence signal.
  for existing in
    select a.*
    from public.student_retention_alerts a
    where a.rule_code='CONSECUTIVE_ABSENCE_2'
      and a.status in ('NEW','CONTACTED','FOLLOW_UP')
      and (p_branch is null or a.branch_id=p_branch)
      and not exists(
        select 1
        from public.attendance_retention_signals_v1(p_branch) s
        where s.enrollment_id=a.enrollment_id
      )
      and exists(
        select 1
        from public.attendance_records ar
        join public.session_occurrences so
          on so.id=ar.session_occurrence_id
        where ar.enrollment_id=a.enrollment_id
          and so.status='COMPLETED'
          and so.occurrence_type='REGULAR'
          and ar.status in ('PRESENT','LATE')
          and so.occurrence_date>=a.last_signal_on
      )
    for update
  loop
    update public.student_retention_alerts
    set
      status='RESOLVED',
      resolution_code='RETURNED_TO_CLASS',
      resolved_at=clock_timestamp(),
      latest_note='Tự động đóng cảnh báo sau khi học viên quay lại lớp.',
      updated_at=clock_timestamp()
    where id=existing.id;

    insert into public.student_retention_events(
      alert_id,
      event_type,
      from_status,
      to_status,
      note,
      actor_id
    )
    values(
      existing.id,
      'AUTO_RESOLVED',
      existing.status,
      'RESOLVED',
      'Tự động đóng cảnh báo sau khi học viên quay lại lớp.',
      actor
    );

    resolved_count:=resolved_count+1;
  end loop;

  return jsonb_build_object(
    'status','REFRESHED',
    'rule_code','CONSECUTIVE_ABSENCE_2',
    'created',created_count,
    'refreshed',refreshed_count,
    'auto_resolved',resolved_count
  );
end;
$$;


ALTER FUNCTION "public"."refresh_attendance_retention_alerts"("p_branch" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."refresh_attendance_retention_alerts"("p_branch" "uuid") IS 'Idempotently refreshes CONSECUTIVE_ABSENCE_2 alerts and auto-resolves when learner returns to a completed regular class. SUPER_ADMIN only in V1.';



CREATE OR REPLACE FUNCTION "public"."refresh_crm_reactivation"("p_branch" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
  opened integer := 0;
  extra integer := 0;
  actor uuid := auth.uid();
begin
  if actor is null or not public.account_is_active() then
    raise exception 'CRM_REACTIVATION_UNAUTHORIZED';
  end if;
  if p_branch is null then
    if not public.has_role('SUPER_ADMIN') then raise exception 'CRM_REACTIVATION_UNAUTHORIZED'; end if;
  else
    if not coalesce(public.crm_can('crm.reactivation.manage', p_branch), false) then
      raise exception 'CRM_REACTIVATION_UNAUTHORIZED';
    end if;
  end if;

  perform set_config('crm.case_write', 'on', true);

  with eligible as (
    select distinct on (enrollment.student_id)
      enrollment.student_id,
      enrollment.id as enrollment_id,
      class_row.branch_id,
      'PAUSE_ENDED_NOT_RETURNED'::text as source_reason,
      pause.ends_on as reference_on,
      course.name as program_name
    from public.enrollment_pauses pause
    join public.enrollments enrollment on enrollment.id = pause.enrollment_id
    join public.classes class_row on class_row.id = enrollment.class_id
    join public.courses course on course.id = class_row.course_id
    where pause.status = 'ACTIVE'
      and pause.ends_on < today
      and enrollment.status in ('WITHDRAWN', 'COMPLETED')
      and not public.crm_reactivation_returned(enrollment.student_id)
      and (p_branch is null or class_row.branch_id = p_branch)
      and public.crm_can('crm.reactivation.manage', class_row.branch_id)
    order by enrollment.student_id, pause.ends_on desc
  ), inserted as (
    insert into public.crm_reactivation_cases(
      student_id, source_enrollment_id, branch_id, source_reason, reference_on, program_name
    )
    select student_id, enrollment_id, branch_id, source_reason, reference_on, program_name
    from eligible
    where not exists (
      select 1 from public.crm_reactivation_cases open_case
      where open_case.student_id = eligible.student_id
        and open_case.status <> 'RETURNED'
    )
    returning id, branch_id
  )
  insert into public.crm_reactivation_events(id, case_id, event_type, to_status, actor_id)
  select gen_random_uuid(), id, 'OPENED', 'NEW_REACTIVATION', actor from inserted;

  get diagnostics opened = row_count;

  with inactive as (
    select student.id as student_id, student.default_branch_id as branch_id
    from public.students student
    where student.status = 'INACTIVE'
      and student.default_branch_id is not null
      and not public.crm_reactivation_returned(student.id)
      and (p_branch is null or student.default_branch_id = p_branch)
      and public.crm_can('crm.reactivation.manage', student.default_branch_id)
      and not exists (
        select 1 from public.crm_reactivation_cases open_case
        where open_case.student_id = student.id
          and open_case.status <> 'RETURNED'
      )
  ), inserted as (
    insert into public.crm_reactivation_cases(student_id, branch_id, source_reason, reference_on, program_name)
    select inactive.student_id, inactive.branch_id, 'INACTIVE_STUDENT',
      (
        select enrollment.ended_at
        from public.enrollments enrollment
        where enrollment.student_id = inactive.student_id and enrollment.ended_at is not null
        order by enrollment.ended_at desc
        limit 1
      ),
      (
        select course.name
        from public.enrollments enrollment
        join public.classes class_row on class_row.id = enrollment.class_id
        join public.courses course on course.id = class_row.course_id
        where enrollment.student_id = inactive.student_id
        order by enrollment.created_at desc
        limit 1
      )
    from inactive
    returning id
  )
  insert into public.crm_reactivation_events(id, case_id, event_type, to_status, actor_id)
  select gen_random_uuid(), id, 'OPENED', 'NEW_REACTIVATION', actor from inserted;
  get diagnostics extra = row_count;
  opened := opened + extra;

  with returned as (
    update public.crm_reactivation_cases item
    set status = 'RETURNED', returned_at = clock_timestamp(), version = version + 1, updated_at = clock_timestamp()
    where item.status not in ('RETURNED', 'NOT_INTERESTED', 'LOST')
      and public.crm_reactivation_returned(item.student_id)
      and (p_branch is null or item.branch_id = p_branch)
      and public.crm_can('crm.reactivation.manage', item.branch_id)
    returning item.id, item.status
  )
  insert into public.crm_reactivation_events(id, case_id, event_type, to_status, actor_id, metadata)
  select gen_random_uuid(), id, 'RETURNED', 'RETURNED', actor, jsonb_build_object('evidence', 'ACTIVE_ENROLLMENT')
  from returned;

  perform set_config('crm.case_write', 'off', true);
  return opened;
end $$;


ALTER FUNCTION "public"."refresh_crm_reactivation"("p_branch" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_staff_payroll_v2_totals"("p_period" "uuid", "p_employee" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  update public.teacher_payrolls t
  set calculation_version=t.calculation_version
  where t.period_id=p_period
    and t.employee_id=p_employee
    and t.calculation_version like 'PAYROLL_V2%';

  if not found then
    raise exception 'PAYROLL_V2_HEADER_REQUIRED';
  end if;
end;
$$;


