CREATE OR REPLACE FUNCTION "public"."registration_academic_selection_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.curriculum_id is null and new.level_id is null and new.subject_id is null then
    return new;
  end if;
  if new.curriculum_id is null or new.level_id is null
     or not exists (select 1 from public.curriculums where id = new.curriculum_id and status = 'ACTIVE')
     or not exists (select 1 from public.curriculum_levels where id = new.level_id and curriculum_id = new.curriculum_id and status = 'ACTIVE')
     or (new.subject_id is not null and not exists (
       select 1 from public.curriculum_subjects where id = new.subject_id and level_id = new.level_id and status = 'ACTIVE'
     )) then
    raise exception 'REGISTRATION_ACADEMIC_SELECTION_INVALID';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."registration_academic_selection_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."registration_authoritative_list_price"("p_branch" "uuid", "p_plan" "uuid") RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case
    when plan.code = 'VIBE_3_MONTHS' and branch_is_can_tho then 5500000
    when plan.code = 'VIBE_12_MONTHS' and branch_is_can_tho then 16500000
    when plan.code = 'VIBE_3_MONTHS' then 4500000
    when plan.code = 'VIBE_12_MONTHS' then 13500000
    else null
  end
  from public.tuition_plans plan
  cross join lateral (
    select exists (
      select 1 from public.branches branch
      where branch.id = p_branch
        and (branch.code in ('V01', 'CT01') or branch.name = 'Vibe Academy Cần Thơ')
    ) as branch_is_can_tho
  ) branch
  where plan.id = p_plan;
$$;


ALTER FUNCTION "public"."registration_authoritative_list_price"("p_branch" "uuid", "p_plan" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."registration_can"("p_permission" "text", "p_branch" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select public.account_is_active()
    and p_branch is not null
    and p_permission in (
      'registration.view', 'registration.create', 'registration.update', 'registration.complete',
      'student_placement.view', 'student_placement.manage'
    )
    and exists(select 1 from public.branches where id = p_branch)
    and (
      public.has_role('SUPER_ADMIN')
      or exists (
        select 1
        from public.user_roles ur
        join public.roles r on r.id = ur.role_id
        join public.role_permissions rp on rp.role_id = r.id
        join public.permissions p on p.id = rp.permission_id
        where ur.user_id = auth.uid()
          and r.code <> 'SUPER_ADMIN'
          and ur.branch_id = p_branch
          and ur.is_active
          and (ur.valid_from is null or ur.valid_from <= now())
          and (ur.valid_until is null or ur.valid_until > now())
          and p.code = p_permission
      )
    )
$$;


ALTER FUNCTION "public"."registration_can"("p_permission" "text", "p_branch" "uuid") OWNER TO "postgres";


