CREATE OR REPLACE FUNCTION "public"."registration_is_over_18"("p_birth" "date") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  anniversary date;
  year_n integer;
  month_n integer;
  day_n integer;
  month_end integer;
begin
  if p_birth is null then return false; end if;
  year_n := extract(year from p_birth)::integer + 18;
  month_n := extract(month from p_birth)::integer;
  day_n := extract(day from p_birth)::integer;
  month_end := extract(day from (make_date(year_n, month_n, 1) + interval '1 month - 1 day'))::integer;
  anniversary := make_date(year_n, month_n, least(day_n, month_end));
  return anniversary < public.registration_vietnam_today();
end $$;


ALTER FUNCTION "public"."registration_is_over_18"("p_birth" "date") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."registration_applications" (
    "id" "uuid" NOT NULL,
    "application_code" "text" NOT NULL,
    "crm_lead_id" "uuid",
    "branch_id" "uuid" NOT NULL,
    "student_name" "text",
    "student_date_of_birth" "date",
    "parent_name" "text",
    "parent_phone" "text",
    "parent_email" "text",
    "program_interest" "text",
    "instrument_interest" "text",
    "course_id" "uuid",
    "invoice_id" "uuid",
    "desired_start_date" "date",
    "preferred_schedule" "text",
    "status" "text" DEFAULT 'DRAFT'::"text" NOT NULL,
    "linked_student_id" "uuid",
    "linked_parent_id" "uuid",
    "linked_enrollment_id" "uuid",
    "submitted_at" timestamp with time zone,
    "verified_at" timestamp with time zone,
    "payment_confirmed_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "created_by" "uuid" NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "curriculum_id" "uuid",
    "level_id" "uuid",
    "subject_id" "uuid",
    "deposit_confirmed_at" timestamp with time zone,
    "student_over_18" boolean DEFAULT false NOT NULL,
    "zalo_phone" "text",
    "home_address" "text",
    CONSTRAINT "registration_applications_check1" CHECK ((("payment_confirmed_at" IS NULL) OR ("invoice_id" IS NOT NULL))),
    CONSTRAINT "registration_applications_parent_phone_check" CHECK ((("parent_phone" IS NULL) OR ("char_length"("parent_phone") <= 40))),
    CONSTRAINT "registration_applications_preferred_schedule_check" CHECK ((("preferred_schedule" IS NULL) OR ("char_length"("preferred_schedule") <= 500))),
    CONSTRAINT "registration_applications_status_check" CHECK (("status" = ANY (ARRAY['DRAFT'::"text", 'SUBMITTED'::"text", 'VERIFIED'::"text", 'PAYMENT_PENDING'::"text", 'PAID'::"text", 'COMPLETED'::"text", 'CANCELLED'::"text", 'REJECTED'::"text", 'EXPIRED'::"text"]))),
    CONSTRAINT "registration_applications_student_name_check" CHECK (("char_length"("btrim"(COALESCE("student_name", ''::"text"))) <= 200)),
    CONSTRAINT "registration_applications_version_check" CHECK (("version" > 0)),
    CONSTRAINT "registration_completed_identity_check" CHECK ((("status" <> 'COMPLETED'::"text") OR (("linked_student_id" IS NOT NULL) AND ("completed_at" IS NOT NULL) AND (("linked_parent_id" IS NOT NULL) OR "student_over_18")))),
    CONSTRAINT "registration_home_address_check" CHECK ((("home_address" IS NULL) OR ((("char_length"("home_address") >= 1) AND ("char_length"("home_address") <= 300)) AND ("home_address" = "btrim"("home_address")) AND ("home_address" !~ '\s{2,}'::"text")))),
    CONSTRAINT "registration_zalo_phone_check" CHECK ((("zalo_phone" IS NULL) OR ("zalo_phone" ~ '^84[0-9]{9}$'::"text")))
);


ALTER TABLE "public"."registration_applications" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."registration_lock"("p_application" "uuid", "p_version" integer, "p_permission" "text") RETURNS "public"."registration_applications"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  row public.registration_applications%rowtype;
begin
  select * into row from public.registration_applications where id = p_application for update;
  if not found then raise exception 'REGISTRATION_NOT_FOUND'; end if;
  if not public.registration_can(p_permission, row.branch_id) then
    raise exception 'REGISTRATION_UNAUTHORIZED';
  end if;
  if row.version is distinct from p_version then raise exception 'REGISTRATION_STALE'; end if;
  return row;
end $$;


