CREATE OR REPLACE FUNCTION "public"."release_completed_makeup_without_present"("p_credit_id" "uuid", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_credit public.makeup_credits%rowtype;
  v_status text;
begin
  v_actor := public.academic_operation_actor();
  if p_note is null or char_length(btrim(p_note)) not between 1 and 500 then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Nhập lý do trả quyền.'));
  end if;
  select * into v_credit from public.makeup_credits where id = p_credit_id for update;
  if not found or v_credit.status <> 'RESERVED' then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Chỉ trả quyền đang kẹt ở trạng thái đã đặt.'));
  end if;
  select status into v_status from public.session_occurrences where id = v_credit.reserved_occurrence_id;
  if v_status is distinct from 'COMPLETED' then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Buổi đích chưa chốt. Hãy hủy chỗ nếu buổi còn trong lịch.'));
  end if;
  if exists (
    select 1 from public.attendance_records attendance
    where attendance.session_occurrence_id = v_credit.reserved_occurrence_id
      and attendance.enrollment_id = v_credit.enrollment_id
      and attendance.status = 'PRESENT'
  ) then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Đã có điểm danh có mặt. Quyền phải được tính đã học, không trả lại.'));
  end if;
  update public.makeup_credits
  set status = 'AVAILABLE', reserved_occurrence_id = null, reserved_at = null, used_at = null, cancelled_at = null
  where id = v_credit.id and status = 'RESERVED';
  insert into public.academic_operation_exceptions (kind, enrollment_id, source_id, actor_id, note)
  values ('MAKEUP_CREDIT_RELEASED', v_credit.enrollment_id, v_credit.id, v_actor, btrim(p_note));
  return jsonb_build_object('ok', true, 'credit_id', v_credit.id, 'status', 'AVAILABLE');
end;
$$;


ALTER FUNCTION "public"."release_completed_makeup_without_present"("p_credit_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_makeup_credit_for_removed_participant"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if old.makeup_credit_id is not null then

    update public.makeup_credits
    set
      status = 'AVAILABLE',

      reserved_occurrence_id = null,
      reserved_at = null,
      used_at = null,
      cancelled_at = null

    where id = old.makeup_credit_id

      and reserved_occurrence_id =
        old.session_occurrence_id

      and status = 'RESERVED';

  end if;

  return old;
end;
$$;


ALTER FUNCTION "public"."release_makeup_credit_for_removed_participant"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_employee_expense_claim_item_v2"("p_claim" "uuid", "p_version" integer, "p_item" "uuid", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare c public.employee_expense_claims; payload jsonb; prior jsonb; before_data jsonb;
begin
  select * into c from public.employee_expense_claims
  where id=p_claim and claim_model='ITEMIZED_V2' and created_by=auth.uid()
    and vibe_expense_private.owns_employee(employee_id,branch_id) for update;
  if not found then raise exception 'EXPENSE_UNAUTHORIZED'; end if;
  payload:=jsonb_build_object('action','REMOVE_ITEM_V2','claim_id',p_claim,'version',p_version,'item_id',p_item);
  prior:=vibe_expense_private.replay(p_key,payload); if prior is not null then return prior; end if;
  if c.version is distinct from p_version then raise exception 'EXPENSE_CHANGED_RELOAD'; end if;
  if c.status not in ('DRAFT','RETURNED') then raise exception 'EXPENSE_V2_ITEMS_LOCKED'; end if;
  before_data:=vibe_expense_private.snapshot(p_claim);
  delete from public.employee_expense_claim_items_v2 where id=p_item and claim_id=p_claim;
  if not found then raise exception 'EXPENSE_V2_ITEM_UNAVAILABLE'; end if;
  update public.employee_expense_claims set version=version+1,updated_at=clock_timestamp() where id=p_claim;
  return vibe_expense_private.record_event(p_claim,p_key,payload,'ITEM_REMOVED',before_data);
end;
$$;


ALTER FUNCTION "public"."remove_employee_expense_claim_item_v2"("p_claim" "uuid", "p_version" integer, "p_item" "uuid", "p_key" "uuid") OWNER TO "postgres";


