CREATE OR REPLACE FUNCTION "public"."reorder_curriculum_lesson"("p_curriculum_id" "uuid", "p_level_id" "uuid", "p_subject_id" "uuid", "p_lesson_id" "uuid", "p_direction" "text", "p_scope" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_component uuid;
  v_neighbor uuid;
  v_current integer;
  v_other integer;
begin
  if p_direction is distinct from 'up' and p_direction is distinct from 'down' then
    raise exception 'Invalid lesson order' using errcode = 'P0001';
  end if;
  if p_scope is distinct from 'active' and p_scope is distinct from 'all' then
    raise exception 'Invalid lesson order' using errcode = 'P0001';
  end if;

  select item.component_id into v_component
  from public.curriculum_component_items item
  where item.id = p_lesson_id;

  if v_component is null then
    raise exception 'Lesson not found' using errcode = 'P0001';
  end if;

  perform public.lesson_operator_component(p_curriculum_id, p_level_id, p_subject_id, v_component);
  perform public.normalize_lesson_order(v_component);

  with ranked as (
    select id, row_number() over (order by sort_order, id) as position
    from public.curriculum_component_items
    where component_id = v_component
      and (p_scope = 'all' or status = 'ACTIVE')
  ), current_row as (
    select position from ranked where id = p_lesson_id
  )
  select neighbor.id into v_neighbor
  from ranked neighbor
  join current_row current
    on neighbor.position = current.position + case when p_direction = 'up' then -1 else 1 end;

  if v_neighbor is null then
    raise exception 'Invalid lesson order' using errcode = 'P0001';
  end if;

  select sort_order into v_current
  from public.curriculum_component_items
  where id = p_lesson_id;
  select sort_order into v_other
  from public.curriculum_component_items
  where id = v_neighbor;

  update public.curriculum_component_items
  set sort_order = -1
  where id = p_lesson_id;
  update public.curriculum_component_items
  set sort_order = v_current
  where id = v_neighbor;
  update public.curriculum_component_items
  set sort_order = v_other
  where id = p_lesson_id;

  perform public.normalize_lesson_order(v_component);
end;
$$;


ALTER FUNCTION "public"."reorder_curriculum_lesson"("p_curriculum_id" "uuid", "p_level_id" "uuid", "p_subject_id" "uuid", "p_lesson_id" "uuid", "p_direction" "text", "p_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_approved_pause_end"("p_request_id" "uuid", "p_ends_on" "date", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_request public.enrollment_pause_requests%rowtype;
  v_pause uuid;
begin
  v_actor := public.academic_operation_actor();
  if p_note is null or char_length(btrim(p_note)) not between 1 and 500 then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Nhập lý do đổi ngày kết thúc.'));
  end if;
  select * into v_request from public.enrollment_pause_requests where id = p_request_id for update;
  if not found or v_request.status <> 'APPROVED' or v_request.pause_id is null then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Chỉ đổi được bảo lưu đã duyệt và còn hiệu lực.'));
  end if;
  if p_ends_on < v_request.starts_on then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Ngày kết thúc mới không được trước ngày bắt đầu.'));
  end if;
  if p_ends_on = v_request.ends_on then
    return jsonb_build_object('ok', true, 'request_id', v_request.id, 'repeated', true);
  end if;
  begin
    update public.enrollment_pauses
    set status = 'CANCELLED', cancelled_at = now(), cancelled_by = v_actor, cancel_reason = btrim(p_note)
    where id = v_request.pause_id and status = 'ACTIVE';
    if not found then
      return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Đợt bảo lưu gốc không còn hiệu lực.'));
    end if;
    insert into public.enrollment_pauses (enrollment_id, starts_on, ends_on, reason, created_by)
    values (v_request.enrollment_id, v_request.starts_on, p_ends_on, v_request.reason, v_actor)
    returning id into v_pause;
  exception
    when exclusion_violation or raise_exception then
      insert into public.academic_operation_exceptions (kind, enrollment_id, source_id, actor_id, note, payload)
      values ('PAUSE_BLOCKED', v_request.enrollment_id, v_request.id, v_actor, sqlerrm, jsonb_build_object('requested_end', p_ends_on));
      return jsonb_build_object('ok', false, 'blockers', jsonb_build_array(sqlerrm), 'exception_recorded', true);
  end;
  update public.enrollment_pause_requests
  set pause_id = v_pause, ends_on = p_ends_on, end_note = btrim(p_note), ended_by = v_actor, ended_at = now()
  where id = v_request.id;
  insert into public.enrollment_pause_events (request_id, enrollment_id, event_type, actor_id, note, payload)
  values (v_request.id, v_request.enrollment_id, 'END_REPLACED', v_actor, btrim(p_note), jsonb_build_object('pause_id', v_pause, 'ends_on', p_ends_on));
  return jsonb_build_object('ok', true, 'request_id', v_request.id, 'pause_id', v_pause);
end;
$$;


ALTER FUNCTION "public"."replace_approved_pause_end"("p_request_id" "uuid", "p_ends_on" "date", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replay_pending_tuition_zalo_clicks"("p_oa_id" "text", "p_limit" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare event record; applied text; replayed integer:=0;
begin
  if p_oa_id is null or p_oa_id !~ '^[0-9]{8,32}$' or p_limit is null or p_limit<1 or p_limit>20 then return 0; end if;
  for event in select id from integration_webhook_events where provider='ZALO'
    and event_type in ('user_click_response_button','user_received_message') and status='ACCEPTED' and processed_at is null
    and received_at<clock_timestamp()-interval '15 seconds' and (next_attempt_at is null or next_attempt_at<=clock_timestamp())
    order by received_at,id limit p_limit for update skip locked
  loop
    applied:=public.process_tuition_zalo_webhook(event.id,p_oa_id);
    if applied in ('recorded','duplicate','conflict','DELIVERED','IDEMPOTENT') then replayed:=replayed+1; end if;
  end loop;
  return replayed;
end $_$;


ALTER FUNCTION "public"."replay_pending_tuition_zalo_clicks"("p_oa_id" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_absence"("p_attendance_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_attendance public.attendance_records%rowtype;
  v_existing uuid;
  v_type text;
  v_date date;
  v_id uuid;
begin
  v_actor := public.academic_operation_actor();
  if p_reason is null or char_length(btrim(p_reason)) not between 1 and 500 then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Nhập lý do báo vắng.'));
  end if;
  select * into v_attendance from public.attendance_records where id = p_attendance_id;
  if not found then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Chưa có dòng điểm danh để gắn báo vắng.'));
  end if;
  if v_attendance.status = 'PRESENT' then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Buổi này đang là có mặt, không ghi báo vắng.'));
  end if;
  select occurrence.occurrence_type, occurrence.occurrence_date into v_type, v_date
  from public.session_occurrences occurrence where occurrence.id = v_attendance.session_occurrence_id;
  if v_type = 'REGULAR' and public.is_enrollment_paused_on(v_attendance.enrollment_id, v_date) then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Học viên đang bảo lưu ngày này. Không đánh vắng và không cấp học bù.'));
  end if;
  if v_type is null then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Không tìm thấy buổi học.'));
  end if;
  select id into v_existing from public.absence_reports where attendance_record_id = v_attendance.id;
  if v_existing is not null then
    return jsonb_build_object('ok', true, 'report_id', v_existing, 'repeated', true);
  end if;
  insert into public.absence_reports (attendance_record_id, enrollment_id, session_occurrence_id, reason, reported_by)
  values (v_attendance.id, v_attendance.enrollment_id, v_attendance.session_occurrence_id, btrim(p_reason), v_actor)
  returning id into v_id;
  return jsonb_build_object('ok', true, 'report_id', v_id, 'confirmation', 'PENDING');
end;
$$;


ALTER FUNCTION "public"."report_absence"("p_attendance_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_employee_attendance"("p_employee" "uuid", "p_date" "date", "p_shift" "text", "p_revision" integer, "p_status" "text", "p_arrived" timestamp with time zone, "p_departed" timestamp with time zone, "p_reason" "text", "p_key" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$declare s jsonb;latest public.employee_attendance_entries;result uuid;existing public.employee_attendance_requests;begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Employee attendance denied';end if;
 perform 1 from public.employees where id=p_employee for update;if not found then raise exception 'Employee not found';end if;
 select * into existing from public.employee_attendance_requests where idempotency_key=p_key;
 if found then
  if existing.employee_id=p_employee and existing.work_date=p_date and existing.shift_code=p_shift and existing.expected_revision=p_revision and existing.proposed_status=p_status and existing.arrived_at is not distinct from p_arrived and existing.departed_at is not distinct from p_departed and existing.reason=btrim(p_reason) and existing.maker=auth.uid() then return existing.id;end if;
  raise exception 'Idempotency key payload mismatch';
 end if;
 if p_date>(now() at time zone 'Asia/Ho_Chi_Minh')::date then raise exception 'Future attendance is not evidence';end if;
 select * into latest from public.employee_attendance_entries where employee_id=p_employee and work_date=p_date and shift_code=p_shift order by revision desc limit 1;
 if p_revision is distinct from coalesce(latest.revision,0) then raise exception 'Attendance changed; reload';end if;
 select to_jsonb(x) into s from public.employee_schedule(p_employee,p_date,p_date) x where x.shift_code=p_shift;
 if s is null then raise exception 'No active monthly employee shift';end if;
 if latest.id is not null then s:=latest.schedule_snapshot;end if;
 if s->>'schedule_state'='SCHEDULED_OFF' and p_status<>'SCHEDULED_OFF' then raise exception 'Scheduled rest cannot become absence or leave';end if;
 if p_status='SCHEDULED_OFF' and s->>'schedule_state'<>'SCHEDULED_OFF' then raise exception 'Scheduled rest requires schedule evidence';end if;
 if p_status='BUSINESS_TRIP' and s->>'trip_id' is null then raise exception 'Approved trip required';end if;
 if p_arrived is not null and ((p_arrived at time zone 'Asia/Ho_Chi_Minh')::date<>p_date or p_arrived>now()) then raise exception 'Invalid arrival evidence';end if;
 if p_departed is not null and ((p_departed at time zone 'Asia/Ho_Chi_Minh')::date<>p_date or p_departed>now() or p_arrived is null or p_departed<p_arrived) then raise exception 'Invalid departure evidence';end if;
 if p_status='LATE' and (p_arrived is null or p_arrived<=(s->>'starts_at')::timestamptz) then raise exception 'Late arrival evidence required';end if;
 if p_status='EARLY_LEAVE' and (p_departed is null or p_departed>=(s->>'ends_at')::timestamptz) then raise exception 'Early departure evidence required';end if;
 insert into public.employee_attendance_requests(employee_id,work_date,shift_code,expected_revision,proposed_status,arrived_at,departed_at,reason,schedule_snapshot,maker,idempotency_key)
 values(p_employee,p_date,p_shift,p_revision,p_status,p_arrived,p_departed,btrim(p_reason),s,auth.uid(),p_key) returning id into result;return result;end$$;


ALTER FUNCTION "public"."request_employee_attendance"("p_employee" "uuid", "p_date" "date", "p_shift" "text", "p_revision" integer, "p_status" "text", "p_arrived" timestamp with time zone, "p_departed" timestamp with time zone, "p_reason" "text", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_employee_trip"("p_employee" "uuid", "p_destination" "text", "p_branch" "uuid", "p_from" "date", "p_to" "date", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$declare v public.employee_versions; result uuid;begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Employee attendance denied'; end if;
 perform 1 from public.employees where id=p_employee for update;
 if not found then raise exception 'Employee not found';end if;
 if p_from is null or p_to is null or not isfinite(p_from) or not isfinite(p_to) or p_to<p_from or p_to-p_from>62 then raise exception 'Invalid trip date range';end if;
 v:=hr_private.employee_at(p_employee,p_from);
 if v.id is null or v.employment_status<>'ACTIVE' then raise exception 'Active employment required';end if;
 if not exists(select 1 from public.organization_units u join public.branches b on b.id=u.branch_id where u.code=p_destination and b.id=p_branch and b.status='ACTIVE') then raise exception 'Explicit active destination branch mapping required';end if;
 if exists(select 1 from generate_series(p_from::timestamp,p_to::timestamp,interval '1 day') d cross join lateral hr_private.employee_at(p_employee,d::date) e where e.employment_status is distinct from 'ACTIVE' or e.unit_code is distinct from v.unit_code) then raise exception 'Trip cannot cross employment assignment change';end if;
 insert into public.employee_trips(employee_id,origin_unit,destination_unit,destination_branch_id,starts_on,ends_on,reason,maker) values(p_employee,v.unit_code,p_destination,p_branch,p_from,p_to,btrim(p_reason),auth.uid()) returning id into result;
 return result;end$$;


ALTER FUNCTION "public"."request_employee_trip"("p_employee" "uuid", "p_destination" "text", "p_branch" "uuid", "p_from" "date", "p_to" "date", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_enrollment_pause"("p_enrollment_id" "uuid", "p_starts_on" "date", "p_ends_on" "date", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_preview jsonb;
  v_existing uuid;
  v_id uuid;
begin
  v_actor := public.academic_operation_actor();
  if p_reason is null or char_length(btrim(p_reason)) not between 1 and 500 then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Nhập lý do từ 1 đến 500 ký tự.'));
  end if;
  select request.id into v_existing
  from public.enrollment_pause_requests request
  where request.enrollment_id = p_enrollment_id
    and request.starts_on = p_starts_on
    and request.ends_on = p_ends_on
    and request.reason = btrim(p_reason)
    and request.status in ('REQUESTED', 'APPROVED');
  if v_existing is not null then
    return jsonb_build_object('ok', true, 'request_id', v_existing, 'repeated', true);
  end if;
  v_preview := public.preview_enrollment_pause(p_enrollment_id, p_starts_on, p_ends_on);
  if coalesce((v_preview->>'ok')::boolean, false) is not true then
    insert into public.academic_operation_exceptions (kind, enrollment_id, actor_id, note, payload)
    values ('PAUSE_BLOCKED', p_enrollment_id, v_actor, 'Yêu cầu bảo lưu bị chặn trước khi ghi.', v_preview);
    return v_preview || jsonb_build_object('exception_recorded', true);
  end if;
  insert into public.enrollment_pause_requests (enrollment_id, starts_on, ends_on, reason, status, requested_by)
  values (p_enrollment_id, p_starts_on, p_ends_on, btrim(p_reason), 'REQUESTED', v_actor)
  returning id into v_id;
  insert into public.enrollment_pause_events (request_id, enrollment_id, event_type, actor_id, note)
  values (v_id, p_enrollment_id, 'REQUESTED', v_actor, btrim(p_reason));
  return jsonb_build_object('ok', true, 'request_id', v_id, 'preview', v_preview);
end;
$$;


ALTER FUNCTION "public"."request_enrollment_pause"("p_enrollment_id" "uuid", "p_starts_on" "date", "p_ends_on" "date", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_financial_action"("p_operation" "text", "p_target_id" "uuid", "p_details" "jsonb", "p_reason" "text", "p_idempotency_key" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare validated jsonb;r public.financial_approval_requests; result uuid;
begin
 if not public.account_is_active() then raise exception 'Unauthorized'; end if;
 if p_reason is null or char_length(btrim(p_reason)) not between 1 and 2000 or p_idempotency_key is null then raise exception 'Reason and idempotency key required'; end if;
 -- Return a prior identical request before revalidating its now-posted source.
 select * into r from public.financial_approval_requests where maker_user_id=auth.uid() and idempotency_key=p_idempotency_key;
 if found then
   if not public.finance_action_allowed(finance_private.operation_permission(r.operation,'request'),r.branch_id) then raise exception 'Unauthorized'; end if;
   if r.operation is distinct from p_operation or r.target_id is distinct from p_target_id or r.details is distinct from p_details or r.reason is distinct from btrim(p_reason) then raise exception 'Idempotency key already used for different request'; end if;
   return r.id;
 end if;
 -- Serialize same maker/key; source is rechecked by the approver under source locks.
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_idempotency_key::text,0));
 select id into result from public.financial_approval_requests where maker_user_id=auth.uid() and idempotency_key=p_idempotency_key;
 if found then return public.request_financial_action(p_operation,p_target_id,p_details,p_reason,p_idempotency_key); end if;
 validated:=finance_private.validate_request(p_operation,p_target_id,p_details,finance_private.operation_permission(p_operation,'request'));
 insert into public.financial_approval_requests(operation,target_id,branch_id,details,reason,source_snapshot,maker_user_id,idempotency_key)
 values(p_operation,p_target_id,(validated->>'branch_id')::uuid,p_details,btrim(p_reason),validated->'source',auth.uid(),p_idempotency_key)
 returning id into result;
 insert into public.financial_approval_events(request_id,event,performed_by,reason,before_snapshot,after_snapshot)
 values(result,'REQUESTED',auth.uid(),btrim(p_reason),'{}',jsonb_build_object('source',validated->'source','details',p_details));
 return result;
end $$;


ALTER FUNCTION "public"."request_financial_action"("p_operation" "text", "p_target_id" "uuid", "p_details" "jsonb", "p_reason" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_registration_zalo_link"("p_application" "uuid") RETURNS TABLE("external_link_key" "text", "link_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  branch uuid;
  existing public.customer_channel_links;
  created_key text;
begin
  if auth.uid() is null or not public.account_is_active() then
    raise exception 'Unauthorized';
  end if;
  select app.branch_id into branch
  from public.registration_applications app
  where app.id = p_application;
  if branch is null then
    raise exception 'Registration not found';
  end if;
  if not public.registration_can('registration.view', branch) then
    raise exception 'Unauthorized';
  end if;

  select * into existing
  from public.customer_channel_links
  where provider = 'ZALO'
    and registration_application_id = p_application
    and status <> 'REVOKED';
  if found then
    return query select existing.external_link_key, existing.status;
    return;
  end if;

  created_key := replace(gen_random_uuid()::text, '-', '');
  insert into public.customer_channel_links(
    provider, provider_user_id, external_link_key, registration_application_id, status
  ) values (
    'ZALO', null, created_key, p_application, 'PENDING'
  );

  perform set_config('registration.write', 'on', true);
  insert into public.registration_application_events(
    id, application_id, event_type, actor_id, metadata
  ) values (
    gen_random_uuid(), p_application, 'ZALO_LINK_REQUESTED', auth.uid(), '{}'::jsonb
  );

  return query select created_key, 'PENDING'::text;
end;
$$;


ALTER FUNCTION "public"."request_registration_zalo_link"("p_application" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."require_paid_registration_completion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  -- Preserve main's pre-consolidation manual registration contract.
  -- New counter registrations carry curriculum_id; provider payments carry terms.
  if new.curriculum_id is null and new.invoice_id is null
    and not exists (select 1 from public.registration_deposit_terms where application_id=new.id) then
    return new;
  end if;
  if new.status = 'COMPLETED' and old.status is distinct from 'COMPLETED' then
    if not (new.invoice_id is not null and public.registration_invoice_settled(new.invoice_id))
       and not exists (
         select 1 from public.registration_deposit_terms terms
         where terms.application_id = new.id and new.deposit_confirmed_at is not null
           and (
             coalesce((select sum(ord.amount) from public.registration_momo_orders ord
                       where ord.application_id = new.id and ord.state = 'PAID'), 0)
             + coalesce((select sum(ord.attributed_amount) from public.registration_payos_orders ord
                         where ord.application_id = new.id and ord.state = 'PAID'), 0)
           ) >= terms.amount_due
       ) then
      raise exception 'REGISTRATION_PAYMENT_REQUIRED';
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."require_paid_registration_completion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reschedule_session_occurrence"("p_occurrence_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_room_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_occurrence_status text;
  v_current_starts_at timestamptz;
  v_current_ends_at timestamptz;
  v_current_room_id uuid;
  v_class_id uuid;
  v_branch_id uuid;
  v_timezone text;
  v_session_date date;
  v_room_branch_id uuid;
  v_room_status text;
  v_result uuid;
begin
  if p_starts_at is null or p_ends_at is null then
    raise exception 'Session start and end time are required';
  end if;

  if p_ends_at <= p_starts_at then
    raise exception 'End time must be after start time';
  end if;

  if nullif(btrim(p_reason), '') is null then
    raise exception 'Reschedule reason is required';
  end if;

  select
    occurrence.status,
    occurrence.starts_at,
    occurrence.ends_at,
    occurrence.room_id,
    schedule.class_id,
    class.branch_id,
    schedule.timezone
  into
    v_occurrence_status,
    v_current_starts_at,
    v_current_ends_at,
    v_current_room_id,
    v_class_id,
    v_branch_id,
    v_timezone
  from public.session_occurrences as occurrence
  join public.schedules as schedule
    on schedule.id = occurrence.schedule_id
  join public.classes as class
    on class.id = schedule.class_id
  where occurrence.id = p_occurrence_id
  for update of occurrence;

  if v_occurrence_status is null then
    raise exception 'Session not found';
  end if;

  if v_occurrence_status <> 'SCHEDULED' then
    raise exception 'Only scheduled sessions can be rescheduled';
  end if;

  if exists (
    select 1
    from public.attendance_records
    where session_occurrence_id = p_occurrence_id
  ) then
    raise exception 'Session with attendance cannot be rescheduled';
  end if;

  if
    p_starts_at = v_current_starts_at
    and p_ends_at = v_current_ends_at
    and p_room_id is not distinct from v_current_room_id
  then
    raise exception 'Reschedule must change the time or room';
  end if;

  if p_room_id is not null then
    select
      room.branch_id,
      room.status
    into
      v_room_branch_id,
      v_room_status
    from public.rooms as room
    where room.id = p_room_id;

    if v_room_status is distinct from 'ACTIVE' then
      raise exception 'Room is not available';
    end if;

    if v_room_branch_id is distinct from v_branch_id then
      raise exception
        'Room must belong to the same branch as the class';
    end if;
  end if;

  if exists (
    select 1
    from public.session_occurrences as other_occurrence
    join public.schedules as other_schedule
      on other_schedule.id = other_occurrence.schedule_id
    where other_occurrence.id <> p_occurrence_id
      and other_occurrence.status <> 'CANCELLED'
      and other_schedule.class_id = v_class_id
      and other_occurrence.starts_at < p_ends_at
      and other_occurrence.ends_at > p_starts_at
  ) then
    raise exception 'This class already has an overlapping session';
  end if;

  if
    p_room_id is not null
    and exists (
      select 1
      from public.session_occurrences as other_occurrence
      where other_occurrence.id <> p_occurrence_id
        and other_occurrence.status <> 'CANCELLED'
        and other_occurrence.room_id = p_room_id
        and other_occurrence.starts_at < p_ends_at
        and other_occurrence.ends_at > p_starts_at
    )
  then
    raise exception
      'This room is already occupied during that time';
  end if;

  v_session_date :=
    (p_starts_at at time zone v_timezone)::date;

  if exists (
    select 1
    from public.class_teachers as current_assignment
    join public.class_teachers as other_assignment
      on other_assignment.teacher_id =
        current_assignment.teacher_id
      and other_assignment.class_id <>
        current_assignment.class_id
    join public.schedules as other_schedule
      on other_schedule.class_id =
        other_assignment.class_id
    join public.session_occurrences as other_occurrence
      on other_occurrence.schedule_id = other_schedule.id
    where current_assignment.class_id = v_class_id
      and current_assignment.is_active = true
      and current_assignment.assigned_at <= v_session_date
      and (
        current_assignment.ended_at is null
        or current_assignment.ended_at >= v_session_date
      )
      and other_assignment.is_active = true
      and other_assignment.assigned_at <= v_session_date
      and (
        other_assignment.ended_at is null
        or other_assignment.ended_at >= v_session_date
      )
      and other_occurrence.id <> p_occurrence_id
      and other_occurrence.status <> 'CANCELLED'
      and other_occurrence.starts_at < p_ends_at
      and other_occurrence.ends_at > p_starts_at
  ) then
    raise exception
      'A teacher assigned to this class is already teaching another class at that time';
  end if;

  update public.session_occurrences
  set
    starts_at = p_starts_at,
    ends_at = p_ends_at,
    room_id = p_room_id,
    rescheduled_at = now(),
    rescheduled_by = auth.uid(),
    reschedule_reason = btrim(p_reason)
  where id = p_occurrence_id
  returning id into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."reschedule_session_occurrence"("p_occurrence_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_room_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_makeup_credit_for_participant"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_occurrence_type text;
  v_occurrence_status text;
  v_makeup_class_id uuid;
  v_credit_id uuid;
begin
  select occurrence.occurrence_type, occurrence.status, schedule.class_id
  into v_occurrence_type, v_occurrence_status, v_makeup_class_id
  from public.session_occurrences occurrence
  join public.schedules schedule on schedule.id = occurrence.schedule_id
  where occurrence.id = new.session_occurrence_id;

  if v_occurrence_type is distinct from 'MAKEUP' then
    raise exception 'Makeup credit can only be reserved for a makeup session' using errcode = 'P0001';
  end if;
  if v_occurrence_status is distinct from 'SCHEDULED' then
    raise exception 'Students can only be added to a scheduled makeup session' using errcode = 'P0001';
  end if;

  if new.makeup_credit_id is not null then
    select credit.id into v_credit_id
    from public.makeup_credits credit
    where credit.id = new.makeup_credit_id
      and credit.enrollment_id = new.enrollment_id
      and credit.status = 'AVAILABLE'
    for update;
    if v_credit_id is null then
      raise exception 'Quyền học bù không còn dùng được.' using errcode = 'P0001';
    end if;
    update public.makeup_credits
    set status = 'RESERVED', reserved_occurrence_id = new.session_occurrence_id, reserved_at = now(), used_at = null, cancelled_at = null
    where id = v_credit_id and status = 'AVAILABLE';
    if not found then
      raise exception 'Quyền học bù không còn dùng được.' using errcode = 'P0001';
    end if;
    return new;
  end if;

  select credit.id into v_credit_id
  from public.makeup_credits credit
  join public.session_occurrences source_occurrence on source_occurrence.id = credit.source_occurrence_id
  join public.schedules source_schedule on source_schedule.id = source_occurrence.schedule_id
  where credit.enrollment_id = new.enrollment_id
    and credit.status = 'AVAILABLE'
    and source_schedule.class_id = v_makeup_class_id
  order by source_occurrence.occurrence_date, credit.created_at, credit.id
  for update of credit skip locked
  limit 1;
  if v_credit_id is null then
    raise exception 'Selected student does not have an available makeup credit for this class' using errcode = 'P0001';
  end if;
  update public.makeup_credits
  set status = 'RESERVED', reserved_occurrence_id = new.session_occurrence_id, reserved_at = now(), used_at = null, cancelled_at = null
  where id = v_credit_id and status = 'AVAILABLE';
  if not found then
    raise exception 'Makeup credit is no longer available' using errcode = 'P0001';
  end if;
  new.makeup_credit_id := v_credit_id;
  return new;
end;
$$;


ALTER FUNCTION "public"."reserve_makeup_credit_for_participant"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."registration_momo_orders" (
    "id" "uuid" NOT NULL,
    "application_id" "uuid" NOT NULL,
    "order_id" "text" NOT NULL,
    "request_id" "text" NOT NULL,
    "amount" bigint NOT NULL,
    "partner_code" "text",
    "state" "text" DEFAULT 'RESERVED'::"text" NOT NULL,
    "pay_url" "text",
    "provider_transaction_id" "text",
    "finance_payment_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "paid_at" timestamp with time zone,
    CONSTRAINT "registration_momo_orders_amount_check" CHECK (("amount" > 0)),
    CONSTRAINT "registration_momo_orders_check" CHECK ((("state" <> 'PAID'::"text") OR (("provider_transaction_id" IS NOT NULL) AND ("paid_at" IS NOT NULL)))),
    CONSTRAINT "registration_momo_orders_state_check" CHECK (("state" = ANY (ARRAY['RESERVED'::"text", 'READY'::"text", 'PAID'::"text", 'FAILED'::"text", 'EXPIRED'::"text"])))
);


ALTER TABLE "public"."registration_momo_orders" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_registration_momo_order"("p_application" "uuid", "p_request" "uuid", "p_version" integer, "p_amount" bigint) RETURNS "public"."registration_momo_orders"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare app public.registration_applications%rowtype; terms public.registration_deposit_terms%rowtype;
  existing public.registration_momo_orders%rowtype; result public.registration_momo_orders%rowtype;
  paid_total bigint;
begin
  app := public.registration_lock(p_application, p_version, 'registration.update');
  if p_request is null then raise exception 'MOMO_REQUEST_INVALID'; end if;
  select * into existing from public.registration_momo_orders where id = p_request;
  if found then
    if existing.application_id <> app.id then raise exception 'MOMO_REQUEST_CONFLICT'; end if;
    return existing;
  end if;
  if app.status not in ('VERIFIED', 'PAYMENT_PENDING') then raise exception 'MOMO_ORDER_DENIED'; end if;
  select * into terms from public.registration_deposit_terms where application_id = app.id;
  if not found then raise exception 'REGISTRATION_QUOTE_REQUIRED'; end if;
  select coalesce(sum(amount), 0)::bigint into paid_total from public.registration_momo_orders
    where application_id = app.id and state = 'PAID';
  select * into existing from public.registration_momo_orders
    where application_id = app.id and state in ('RESERVED', 'READY') limit 1;
  if found then return existing; end if;
  if p_amount is null or p_amount < 1000 or p_amount > 50000000
     or p_amount > terms.tuition_amount - paid_total then
    raise exception 'MOMO_AMOUNT_INVALID';
  end if;
  insert into public.registration_momo_orders(id, application_id, order_id, request_id, amount)
  values(p_request, app.id, 'VIBE' || upper(replace(p_request::text, '-', '')),
    'REQ' || upper(replace(p_request::text, '-', '')), p_amount)
  returning * into result;
  return result;
end $$;


ALTER FUNCTION "public"."reserve_registration_momo_order"("p_application" "uuid", "p_request" "uuid", "p_version" integer, "p_amount" bigint) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."registration_payos_orders" (
    "id" "uuid" NOT NULL,
    "application_id" "uuid" NOT NULL,
    "provider" "text" DEFAULT 'PAYOS'::"text" NOT NULL,
    "order_code" bigint NOT NULL,
    "amount" bigint NOT NULL,
    "attributed_amount" bigint,
    "currency" "text" DEFAULT 'VND'::"text" NOT NULL,
    "description" "text" NOT NULL,
    "state" "text" DEFAULT 'RESERVED'::"text" NOT NULL,
    "payment_link_id" "text",
    "checkout_url" "text",
    "qr_code" "text",
    "provider_reference" "text",
    "finance_payment_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "activated_at" timestamp with time zone,
    "paid_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    CONSTRAINT "registration_payos_orders_amount_check" CHECK (("amount" > 0)),
    CONSTRAINT "registration_payos_orders_check" CHECK ((("attributed_amount" IS NULL) OR (("attributed_amount" > 0) AND ("attributed_amount" <= "amount")))),
    CONSTRAINT "registration_payos_orders_check1" CHECK ((("state" <> 'PAID'::"text") OR (("provider_reference" IS NOT NULL) AND ("paid_at" IS NOT NULL)))),
    CONSTRAINT "registration_payos_orders_check2" CHECK ((("state" <> 'PENDING'::"text") OR (("payment_link_id" IS NOT NULL) AND ("checkout_url" IS NOT NULL)))),
    CONSTRAINT "registration_payos_orders_currency_check" CHECK (("currency" = 'VND'::"text")),
    CONSTRAINT "registration_payos_orders_description_check" CHECK ((("char_length"("description") >= 1) AND ("char_length"("description") <= 25))),
    CONSTRAINT "registration_payos_orders_provider_check" CHECK (("provider" = 'PAYOS'::"text")),
    CONSTRAINT "registration_payos_orders_state_check" CHECK (("state" = ANY (ARRAY['RESERVED'::"text", 'PENDING'::"text", 'PAID'::"text", 'CANCELLED'::"text", 'EXPIRED'::"text", 'EXCEPTION'::"text"])))
);


ALTER TABLE "public"."registration_payos_orders" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_registration_payos_order"("p_application" "uuid", "p_request" "uuid", "p_version" integer) RETURNS "public"."registration_payos_orders"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  app public.registration_applications%rowtype;
  terms public.registration_deposit_terms%rowtype;
  existing public.registration_payos_orders%rowtype;
  result public.registration_payos_orders%rowtype;
  paid_total bigint;
  due_now bigint;
  code bigint;
begin
  if p_request is null then raise exception 'PAYOS_REQUEST_INVALID'; end if;
  select * into app from public.registration_applications where id = p_application for update;
  if not found then raise exception 'REGISTRATION_NOT_FOUND'; end if;
  if not public.registration_can('registration.update', app.branch_id) then
    raise exception 'REGISTRATION_UNAUTHORIZED';
  end if;
  select * into existing from public.registration_payos_orders where id = p_request;
  if found then
    if existing.application_id <> app.id then raise exception 'PAYOS_REQUEST_CONFLICT'; end if;
    return existing;
  end if;
  select * into existing from public.registration_payos_orders
    where application_id = app.id and state in ('RESERVED', 'PENDING')
    order by created_at desc limit 1;
  if found then return existing; end if;
  if app.status in ('PAID', 'COMPLETED') then
    select * into existing from public.registration_payos_orders
      where application_id = app.id and state = 'PAID'
      order by paid_at desc nulls last limit 1;
    if found then return existing; end if;
    raise exception 'PAYOS_ORDER_DENIED';
  end if;
  if app.version is distinct from p_version then raise exception 'REGISTRATION_STALE'; end if;
  if app.status not in ('VERIFIED', 'PAYMENT_PENDING') then raise exception 'PAYOS_ORDER_DENIED'; end if;
  select * into terms from public.registration_deposit_terms where application_id = app.id;
  if not found then raise exception 'REGISTRATION_QUOTE_REQUIRED'; end if;
  paid_total := public.registration_payos_paid_total(app.id)
    + coalesce((select sum(amount) from public.registration_momo_orders
                where application_id = app.id and state = 'PAID'), 0);
  due_now := terms.amount_due - paid_total;
  if due_now <= 0 then raise exception 'PAYOS_THRESHOLD_SATISFIED'; end if;
  if due_now > 50000000 then raise exception 'PAYOS_AMOUNT_INVALID'; end if;
  code := nextval('public.registration_payos_order_code_seq');
  insert into public.registration_payos_orders(
    id, application_id, order_code, amount, description)
  values (p_request, app.id, code, due_now, left('V' || code::text, 9))
  returning * into result;
  return result;
end $$;


ALTER FUNCTION "public"."reserve_registration_payos_order"("p_application" "uuid", "p_request" "uuid", "p_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_lesson_feedback"("p_id" "uuid", "p_version" integer, "p_status" "text", "p_note" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare f lesson_feedback;
begin
 if not coalesce(has_role('SUPER_ADMIN'),false) then raise exception 'Unauthorized'; end if;
 select * into f from lesson_feedback where id=p_id for update;
 if not found or f.version is distinct from p_version then raise exception 'Feedback changed; reload'; end if;
 if p_status is null or p_status not in ('IN_REVIEW','RESOLVED') or p_status=f.resolution_status or (f.resolution_status='RESOLVED' and p_status<>'IN_REVIEW') then raise exception 'Invalid resolution transition'; end if;
 if p_note is null or char_length(btrim(p_note)) not between 1 and 4000 then raise exception 'Resolution note required'; end if;
 update lesson_feedback set resolution_status=p_status,resolution_note=btrim(p_note),resolved_by=case when p_status='RESOLVED' then auth.uid() end,
 resolved_at=case when p_status='RESOLVED' then now() end where id=p_id;
 insert into lesson_feedback_events(feedback_id,status,note,actor_id) values(p_id,p_status,btrim(p_note),auth.uid());
 return p_id;
end $$;


ALTER FUNCTION "public"."resolve_lesson_feedback"("p_id" "uuid", "p_version" integer, "p_status" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_tuition_reminder"("p_reminder_id" "uuid", "p_status" "text", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not coalesce(public.has_role('SUPER_ADMIN'),false) then raise exception 'SUPER_ADMIN role required'; end if;
  if p_status is null or p_status not in ('SKIPPED','CANCELLED') or nullif(btrim(p_reason),'') is null or length(p_reason)>2000 then
    raise exception 'Invalid reminder resolution'; end if;
  update tuition_reminders set status=p_status,reason=btrim(p_reason),marked_by=auth.uid(),marked_at=now()
    where id=p_reminder_id and status='PENDING';
  if not found then raise exception 'Pending reminder not found'; end if;
  return p_reminder_id;
end $$;


ALTER FUNCTION "public"."resolve_tuition_reminder"("p_reminder_id" "uuid", "p_status" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_enrollment_shift"("p_enrollment_id" "uuid", "p_class_id" "uuid", "p_restore_on" "date", "p_reason" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_enrollment public.enrollments%rowtype;
  v_existing public.enrollment_shift_changes%rowtype;
  v_code text;
  v_count integer;
  v_capacity integer;
  v_new uuid;
  v_progress integer;
begin
  v_actor := public.academic_operation_actor();
  if p_reason is null or char_length(btrim(p_reason)) not between 1 and 500 then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Nhập lý do chuyển ca.'));
  end if;
  if p_idempotency_key is null or char_length(btrim(p_idempotency_key)) < 8 then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Thiếu mã chống ghi trùng.'));
  end if;
  select * into v_existing
  from public.enrollment_shift_changes
  where from_enrollment_id = p_enrollment_id and idempotency_key = btrim(p_idempotency_key);
  if found then
    return jsonb_build_object('ok', true, 'repeated', true, 'to_enrollment_id', v_existing.to_enrollment_id);
  end if;
  select * into v_enrollment from public.enrollments where id = p_enrollment_id for update;
  if not found or v_enrollment.status <> 'ACTIVE' then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Ghi danh cũ không còn đang học.'));
  end if;
  if p_class_id = v_enrollment.class_id then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Đây đúng ca hiện tại. Để quay lại ca này, chỉ cần kết thúc bảo lưu. Lịch sử ca vẫn giữ nguyên.'));
  end if;
  if p_restore_on <= coalesce(v_enrollment.started_at, v_enrollment.enrolled_at) then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Ngày hiệu lực phải sau ngày ca cũ bắt đầu.'));
  end if;
  v_code := public.class_enrollment_compatibility(p_class_id, v_enrollment.student_id);
  if v_code <> 'IN_SCOPE' then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array(case v_code
      when 'CLASS_SCOPE_UNCONFIGURED' then 'Ca đích chưa cấu hình khoảng trình độ.'
      when 'WRONG_PROGRAM' then 'Ca đích thuộc chương trình học khác.'
      when 'ACADEMIC_PROGRAM_MISSING' then 'Học viên chưa có chương trình đang học.'
      when 'CURRENT_LEVEL_MISSING' then 'Học viên chưa có trình độ hiện tại.'
      when 'OUTSIDE_SCOPE' then 'Trình độ hiện tại nằm ngoài khoảng của ca đích.'
      else 'Ca đích không phù hợp: ' || v_code
    end));
  end if;
  select capacity into v_capacity from public.classes where id = p_class_id and status = 'ACTIVE' for update;
  if not found then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Ca đích không ở trạng thái đang mở.'));
  end if;
  select count(*) into v_count
  from public.enrollments
  where class_id = p_class_id and status in ('ACTIVE', 'PAUSED')
    and (ended_at is null or ended_at >= p_restore_on);
  if v_count >= v_capacity then
    return jsonb_build_object('ok', false, 'blockers', jsonb_build_array('Ca đích đã đủ chỗ tại ngày hiệu lực.'));
  end if;
  select count(*) into v_progress
  from public.learning_lesson_progress
  where student_id = v_enrollment.student_id;
  begin
    update public.enrollment_pauses
    set status = 'CANCELLED', cancelled_at = now(), cancelled_by = v_actor, cancel_reason = btrim(p_reason)
    where enrollment_id = v_enrollment.id and status = 'ACTIVE' and starts_on >= p_restore_on;
    update public.enrollment_pauses
    set status = 'CANCELLED', cancelled_at = now(), cancelled_by = v_actor, cancel_reason = btrim(p_reason)
    where enrollment_id = v_enrollment.id and status = 'ACTIVE' and ends_on >= p_restore_on and starts_on < p_restore_on;
    insert into public.enrollment_pauses (enrollment_id, starts_on, ends_on, reason, created_by)
    select v_enrollment.id, pause.starts_on, p_restore_on - 1, pause.reason, v_actor
    from public.enrollment_pauses pause
    where pause.enrollment_id = v_enrollment.id and pause.status = 'CANCELLED' and pause.cancel_reason = btrim(p_reason)
      and pause.starts_on < p_restore_on and pause.ends_on >= p_restore_on
      and not exists (
        select 1 from public.enrollment_pauses active_pause
        where active_pause.enrollment_id = v_enrollment.id and active_pause.status = 'ACTIVE'
      );
    update public.enrollments
    set ended_at = p_restore_on - 1, status = 'COMPLETED'
    where id = v_enrollment.id;
    insert into public.enrollments (student_id, class_id, student_curriculum_enrollment_id, enrolled_at, started_at, status, notes)
    values (v_enrollment.student_id, p_class_id, v_enrollment.student_curriculum_enrollment_id, public.vietnam_today(), p_restore_on, 'ACTIVE', 'Chuyển ca từ ' || v_enrollment.id)
    returning id into v_new;
  exception
    when exclusion_violation or raise_exception or check_violation then
      return jsonb_build_object('ok', false, 'blockers', jsonb_build_array(sqlerrm));
  end;
  insert into public.enrollment_shift_changes (from_enrollment_id, to_enrollment_id, from_class_id, to_class_id, restore_on, reason, actor_id, idempotency_key)
  values (v_enrollment.id, v_new, v_enrollment.class_id, p_class_id, p_restore_on, btrim(p_reason), v_actor, btrim(p_idempotency_key));
  insert into public.enrollment_pause_events (enrollment_id, event_type, actor_id, note, payload)
  values (v_enrollment.id, 'SHIFT_RESTORED', v_actor, btrim(p_reason), jsonb_build_object('to_enrollment_id', v_new, 'to_class_id', p_class_id, 'lesson_progress_rows', v_progress));
  return jsonb_build_object('ok', true, 'to_enrollment_id', v_new, 'lesson_progress_rows', v_progress, 'money', 'Không hoàn tiền và không tạo khoản thu.');
end;
$$;


ALTER FUNCTION "public"."restore_enrollment_shift"("p_enrollment_id" "uuid", "p_class_id" "uuid", "p_restore_on" "date", "p_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retarget_payroll_retroactive_claim"("p_claim" "uuid", "p_version" integer, "p_target_period" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  c public.payroll_retroactive_claims%rowtype;
  source_row public.payroll_periods%rowtype;
  old_target public.payroll_periods%rowtype;
  new_target public.payroll_periods%rowtype;
begin
  if auth.uid() is null
     or not coalesce(
       public.account_is_active(),
       false
     )
  then
    raise exception
      'RETROACTIVE_UNAUTHORIZED';
  end if;

  select r.*
  into c
  from public.payroll_retroactive_claims r
  where r.id = p_claim
    and public.has_permission(
      'payroll.approve',
      r.branch_id
    )
    and (
      public.is_global_super_admin()
      or public.has_role_permission(
        'FINANCE',
        'payroll.approve',
        r.branch_id
      )
    )
  for update;

  if not found then
    raise exception
      'RETROACTIVE_UNAUTHORIZED';
  end if;

  if c.version is distinct from p_version then
    raise exception
      'RETROACTIVE_CHANGED_RELOAD';
  end if;

  if c.status <> 'APPROVED'
     or c.posted_action_id is not null
     or c.posted_at is not null
  then
    raise exception
      'RETROACTIVE_RETARGET_REQUIRES_APPROVED_UNPOSTED';
  end if;

  if p_reason is null
     or char_length(
       btrim(p_reason)
     ) not between 1 and 2000
  then
    raise exception
      'RETROACTIVE_RETARGET_REASON_REQUIRED';
  end if;

  select *
  into source_row
  from public.payroll_periods
  where id = c.source_period_id;

  if not found then
    raise exception
      'RETROACTIVE_SOURCE_PERIOD_MISSING';
  end if;

  if c.target_period_id is not null then
    select *
    into old_target
    from public.payroll_periods
    where id = c.target_period_id;
  end if;

  select *
  into new_target
  from public.payroll_periods
  where id = p_target_period
  for update;

  if not found then
    raise exception
      'RETROACTIVE_RETARGET_TARGET_MISSING';
  end if;

  if new_target.branch_id
       is distinct from c.branch_id
     or new_target.starts_on
        <= source_row.starts_on
  then
    raise exception
      'RETROACTIVE_RETARGET_SCOPE_INVALID';
  end if;

  if new_target.status
       not in ('DRAFT','GENERATED','REVIEW')
  then
    raise exception
      'RETROACTIVE_RETARGET_TARGET_MUST_BE_OPEN';
  end if;

  if c.target_period_id
       is not distinct from new_target.id
  then
    raise exception
      'RETROACTIVE_RETARGET_SAME_TARGET';
  end if;

  insert into public.payroll_retroactive_events(
    claim_id,
    event_type,
    from_target_period_id,
    to_target_period_id,
    reason,
    actor_id
  )
  values(
    c.id,
    'RETARGETED',
    c.target_period_id,
    new_target.id,
    btrim(p_reason),
    auth.uid()
  );

  update public.payroll_retroactive_claims
  set
    target_period_id = new_target.id,
    version = version + 1
  where id = c.id;

  return jsonb_build_object(
    'status','APPROVED',
    'claim_id',c.id,
    'from_target_period_id',
      c.target_period_id,
    'target_period_id',
      new_target.id,
    'payment_status',
      'NOT_PAID_BY_THIS_ACTION'
  );
end;
$$;


ALTER FUNCTION "public"."retarget_payroll_retroactive_claim"("p_claim" "uuid", "p_version" integer, "p_target_period" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retire_curriculum_lesson"("p_curriculum_id" "uuid", "p_level_id" "uuid", "p_subject_id" "uuid", "p_lesson_id" "uuid") RETURNS "public"."curriculum_component_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_component uuid;
  v_required boolean;
  v_row public.curriculum_component_items;
begin
  select item.component_id, item.is_required
  into v_component, v_required
  from public.curriculum_component_items item
  where item.id = p_lesson_id;

  if v_component is null then
    raise exception 'Lesson not found' using errcode = 'P0001';
  end if;

  perform public.lesson_operator_component(p_curriculum_id, p_level_id, p_subject_id, v_component);
  perform public.assert_required_active_lessons(v_component, p_lesson_id, 'INACTIVE', v_required);

  update public.curriculum_component_items
  set status = 'INACTIVE'
  where id = p_lesson_id
    and component_id = v_component
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."retire_curriculum_lesson"("p_curriculum_id" "uuid", "p_level_id" "uuid", "p_subject_id" "uuid", "p_lesson_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retire_operating_expense_template"("p_template" "uuid", "p_version" integer, "p_reason" "text", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare target public.operating_expense_templates; payload jsonb; prior jsonb; result jsonb; before_data jsonb;
begin
  select * into target from public.operating_expense_templates where id=p_template for update;
  if not found then raise exception 'OPERATING_EXPENSE_TEMPLATE_NOT_FOUND'; end if;
  if not vibe_operating_expense_private.can_manage(target.branch_id) then raise exception 'OPERATING_EXPENSE_UNAUTHORIZED'; end if;
  if p_reason is null or char_length(btrim(p_reason)) not between 1 and 2000 then raise exception 'OPERATING_EXPENSE_RETIRE_REASON_REQUIRED'; end if;
  payload:=jsonb_build_object('operation','TEMPLATE_RETIRED','template_id',p_template,'version',p_version,'reason',btrim(p_reason));
  prior:=vibe_operating_expense_private.replay(p_key,payload);
  if prior is not null then return prior; end if;
  if target.status='RETIRED' then raise exception 'OPERATING_EXPENSE_TEMPLATE_RETIRED'; end if;
  if p_version is distinct from target.version then raise exception 'OPERATING_EXPENSE_CHANGED_RELOAD'; end if;
  before_data:=to_jsonb(target);
  update public.operating_expense_templates set
    status='RETIRED',retired_by=auth.uid(),retired_at=clock_timestamp(),retire_reason=btrim(p_reason),
    version=version+1,updated_at=clock_timestamp()
  where id=p_template;
  result:=jsonb_build_object('template_id',p_template,'status','RETIRED');
  return vibe_operating_expense_private.write_event(p_template,null,'TEMPLATE_RETIRED',p_key,payload,before_data,to_jsonb((select t from public.operating_expense_templates t where t.id=p_template)),result);
end;
$$;


ALTER FUNCTION "public"."retire_operating_expense_template"("p_template" "uuid", "p_version" integer, "p_reason" "text", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_crm_lead_conversion"("p_request" "uuid", "p_lead" "uuid", "p_version" integer, "p_decision" "text", "p_student" "uuid", "p_parent" "uuid", "p_note" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
#variable_conflict use_variable
declare
  actor uuid := auth.uid();
  decision text := nullif(upper(btrim(coalesce(p_decision, ''))), '');
  note text := public.crm_text(p_note, 4000);
  row public.crm_leads%rowtype;
  student public.students%rowtype;
  wanted text;
  event_type text;
  meta jsonb;
begin
  if actor is null or not coalesce(public.account_is_active(), false) then
    raise exception 'CRM_LEAD_UNAUTHORIZED';
  end if;
  if p_request is null or decision is null or decision not in ('PENDING', 'LINKED', 'BLOCKED') then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  if decision = 'LINKED' and p_student is null then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  if decision <> 'LINKED' and (p_student is not null or p_parent is not null or note is null) then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  if p_parent is not null and not exists(select 1 from public.parents where id = p_parent and status = 'ACTIVE') then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  event_type := case when decision = 'LINKED' then 'CONVERTED' else 'CONVERSION_REVIEWED' end;
  meta := jsonb_build_object('decision', decision, 'student_id', p_student, 'parent_id', p_parent);
  if public.crm_lead_replay(p_request, p_lead, event_type, actor, note, null, meta, 'crm.lead.convert') then
    return p_lead;
  end if;
  row := public.crm_lead_lock(p_lead, p_version, 'crm.lead.convert');
  if row.status <> 'WON' then
    raise exception 'CRM_LEAD_TRANSITION_DENIED';
  end if;
  if row.converted_at is not null then
    if decision = 'LINKED' and row.converted_student_id = p_student and row.converted_parent_id is not distinct from p_parent then
      return row.id;
    end if;
    raise exception 'CRM_LEAD_ALREADY_CONVERTED';
  end if;
  if decision = 'LINKED' then
    select * into student from public.students where id = p_student;
    if not found then
      raise exception 'CRM_LEAD_INVALID';
    end if;
    wanted := nullif(lower(btrim(coalesce(row.student_name, row.full_name, ''))), '');
    if wanted is not null and row.student_date_of_birth is not null
       and (student.date_of_birth is distinct from row.student_date_of_birth
            or lower(btrim(coalesce(student.full_name, ''))) is distinct from wanted)
    then
      raise exception 'CRM_LEAD_MATCH_REJECTED';
    end if;
    if (wanted is null or row.student_date_of_birth is null) and note is null then
      raise exception 'CRM_LEAD_REVIEW_REQUIRED';
    end if;
  end if;
  perform set_config('crm.lead_write', 'on', true);
  if decision = 'LINKED' then
    update public.crm_leads set
      converted_student_id = p_student,
      converted_parent_id = p_parent,
      converted_at = clock_timestamp(),
      version = version + 1,
      updated_at = clock_timestamp()
    where id = row.id;
    if p_parent is not null then
      insert into public.student_parents(student_id, parent_id, relationship, is_primary)
      values (p_student, p_parent, 'GUARDIAN', true)
      on conflict (student_id, parent_id) do nothing;
    end if;
  else
    update public.crm_leads set
      version = version + 1,
      updated_at = clock_timestamp()
    where id = row.id;
  end if;
  insert into public.crm_lead_conversion_reviews(id, lead_id, decision, student_id, parent_id, note, actor_id)
  values (p_request, row.id, decision, case when decision = 'LINKED' then p_student end, case when decision = 'LINKED' then p_parent end, note, actor);
  insert into public.crm_lead_events(id, lead_id, event_type, from_status, to_status, actor_id, note, metadata)
  values (p_request, row.id, event_type, row.status, row.status, actor, note, meta);
  perform set_config('crm.lead_write', 'off', true);
  return row.id;
exception
  when unique_violation then
    raise exception 'CRM_LEAD_REQUEST_MISMATCH';
end $$;


ALTER FUNCTION "public"."review_crm_lead_conversion"("p_request" "uuid", "p_lead" "uuid", "p_version" integer, "p_decision" "text", "p_student" "uuid", "p_parent" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_employee_attendance"("p_request" "uuid", "p_decision" "text", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r public.employee_attendance_requests;old public.employee_attendance_entries;policy public.employee_leave_policies;e public.employee_versions;used integer;paid integer:=0;unpaid integer:=0;mins integer;eid uuid;result uuid;current_schedule jsonb;begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Employee attendance denied';end if;
 select * into r from public.employee_attendance_requests where id=p_request;if not found then raise exception 'Request not found';end if;
 perform 1 from public.employees where id=r.employee_id for update;
 if r.maker=auth.uid() then raise exception 'Independent attendance reviewer required';end if;
 select id into result from public.employee_attendance_reviews where request_id=r.id;if found then return result;end if;
 if p_decision='APPROVED' then
  select * into old from public.employee_attendance_entries where employee_id=r.employee_id and work_date=r.work_date and shift_code=r.shift_code order by revision desc limit 1;
  if r.expected_revision<>coalesce(old.revision,0) then raise exception 'Attendance changed; request again';end if;
  if old.id is null then
   select to_jsonb(x) into current_schedule from public.employee_schedule(r.employee_id,r.work_date,r.work_date) x where x.shift_code=r.shift_code;
   if current_schedule is distinct from r.schedule_snapshot then raise exception 'Schedule changed; request again';end if;
  end if;
  mins:=(r.schedule_snapshot->>'scheduled_minutes')::integer;
  if r.proposed_status='PAID_LEAVE' then
   select * into e from public.employee_versions where employee_id=r.employee_id and version=(r.schedule_snapshot->>'employment_version')::integer;
   select * into policy from public.employee_leave_policies where unit_code=r.schedule_snapshot->>'unit_code' and (employee_id is null or employee_id=r.employee_id) and (employee_group is null or employee_group=e.employee_group) and r.work_date between starts_on and ends_on order by (employee_id is not null) desc,(employee_group is not null) desc limit 1;
   if policy.id is null then raise exception 'Configure approved leave quota before paid leave';end if;
   select coalesce(sum(a.paid_leave_minutes),0) into used from (select distinct on(employee_id,work_date,shift_code) * from public.employee_attendance_entries where employee_id=r.employee_id order by employee_id,work_date,shift_code,revision desc) a where a.leave_policy_id=policy.id and a.id is distinct from old.id;
   paid:=least(mins,greatest(0,policy.paid_minutes-used));unpaid:=mins-paid;
  elsif r.proposed_status='UNPAID_LEAVE' then unpaid:=mins;end if;
  insert into public.employee_attendance_entries(employee_id,work_date,shift_code,revision,status,entry_kind,schedule_snapshot,arrived_at,departed_at,late_minutes,early_minutes,reason,actor,checker,previous_entry_id,request_id,leave_policy_id,paid_leave_minutes,unpaid_leave_minutes)
  values(r.employee_id,r.work_date,r.shift_code,r.expected_revision+1,r.proposed_status,case when old.id is null then 'INITIAL' else 'MANUAL_CORRECTION' end,r.schedule_snapshot,r.arrived_at,r.departed_at,
   greatest(0,ceil(extract(epoch from(r.arrived_at-(r.schedule_snapshot->>'starts_at')::timestamptz))/60))::integer,
   greatest(0,ceil(extract(epoch from((r.schedule_snapshot->>'ends_at')::timestamptz-r.departed_at))/60))::integer,
   r.reason,r.maker,auth.uid(),old.id,r.id,policy.id,paid,unpaid) returning id into eid;
 end if;
 insert into public.employee_attendance_reviews(request_id,decision,reason,checker,entry_id) values(r.id,p_decision,btrim(p_reason),auth.uid(),eid) returning id into result;return result;end$$;


ALTER FUNCTION "public"."review_employee_attendance"("p_request" "uuid", "p_decision" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_employee_expense_claim"("p_claim" "uuid", "p_version" integer, "p_decision" "text", "p_reason" "text", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare c public.employee_expense_claims; payload jsonb; prior jsonb; before_data jsonb; total numeric;
begin
  -- Authorize branch BEFORE taking the claim lock or exposing its version.
  select * into c from public.employee_expense_claims
    where id=p_claim and vibe_expense_private.can_review(branch_id) for update;
  if not found then raise exception 'EXPENSE_UNAUTHORIZED'; end if;
  if c.created_by=auth.uid() or exists(
    select 1 from public.employees e where e.id=c.employee_id and e.profile_id=auth.uid()
  ) then raise exception 'EXPENSE_INDEPENDENT_REVIEWER_REQUIRED'; end if;
  if p_decision is null or p_decision not in ('APPROVED','RETURNED','REJECTED') then raise exception 'EXPENSE_INVALID_DECISION'; end if;
  if p_reason is null or char_length(btrim(p_reason)) not between 1 and 2000 then raise exception 'EXPENSE_REVIEW_REASON_REQUIRED'; end if;
  payload:=jsonb_build_object('action','REVIEW','claim_id',p_claim,'version',p_version,'decision',p_decision,'reason',btrim(p_reason));
  prior:=vibe_expense_private.replay(p_key,payload); if prior is not null then return prior; end if;
  if c.version is distinct from p_version then raise exception 'EXPENSE_CHANGED_RELOAD'; end if;
  if c.status<>'SUBMITTED' then raise exception 'EXPENSE_REVIEW_REQUIRES_SUBMITTED'; end if;
  if p_decision='APPROVED' then total:=vibe_expense_private.validate_submission(p_claim); end if;
  before_data:=vibe_expense_private.snapshot(p_claim);
  update public.employee_expense_claims set status=p_decision,version=version+1,updated_at=clock_timestamp(),
    reviewed_by=auth.uid(),reviewed_at=clock_timestamp(),review_reason=btrim(p_reason),
    approved_amount=case when p_decision='APPROVED' then total else null end
  where id=p_claim;
  if p_decision='REJECTED' then
    update public.employee_expense_claim_lines set reservation_active=false where claim_id=p_claim;
  end if;
  return vibe_expense_private.record_event(p_claim,p_key,payload,p_decision,before_data);
end;
$$;


ALTER FUNCTION "public"."review_employee_expense_claim"("p_claim" "uuid", "p_version" integer, "p_decision" "text", "p_reason" "text", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_employee_expense_claim_v2"("p_claim" "uuid", "p_version" integer, "p_decision" "text", "p_reason" "text", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare c public.employee_expense_claims; payload jsonb; prior jsonb; before_data jsonb; total numeric;
begin
  select * into c from public.employee_expense_claims where id=p_claim and claim_model='ITEMIZED_V2'
    and vibe_expense_private.can_review(branch_id) for update;
  if not found then raise exception 'EXPENSE_UNAUTHORIZED'; end if;
  if c.created_by=auth.uid() or exists(select 1 from public.employees e where e.id=c.employee_id and e.profile_id=auth.uid()) then
    raise exception 'EXPENSE_INDEPENDENT_REVIEWER_REQUIRED';
  end if;
  if p_decision is null or p_decision not in ('APPROVED','RETURNED','REJECTED') then raise exception 'EXPENSE_INVALID_DECISION'; end if;
  if p_reason is null or char_length(btrim(p_reason)) not between 1 and 2000 then raise exception 'EXPENSE_REVIEW_REASON_REQUIRED'; end if;
  payload:=jsonb_build_object('action','REVIEW_V2','claim_id',p_claim,'version',p_version,'decision',p_decision,'reason',btrim(p_reason));
  prior:=vibe_expense_private.replay(p_key,payload); if prior is not null then return prior; end if;
  if c.version is distinct from p_version then raise exception 'EXPENSE_CHANGED_RELOAD'; end if;
  if c.status<>'SUBMITTED' then raise exception 'EXPENSE_REVIEW_REQUIRES_SUBMITTED'; end if;
  if p_decision='APPROVED' then total:=vibe_expense_private.validate_submission_v2(p_claim); end if;
  before_data:=vibe_expense_private.snapshot(p_claim);
  update public.employee_expense_claims set status=p_decision,version=version+1,updated_at=clock_timestamp(),
    reviewed_by=auth.uid(),reviewed_at=clock_timestamp(),review_reason=btrim(p_reason),
    approved_amount=case when p_decision='APPROVED' then total else null end where id=p_claim;
  return vibe_expense_private.record_event(p_claim,p_key,payload,p_decision,before_data);
end;
$$;


ALTER FUNCTION "public"."review_employee_expense_claim_v2"("p_claim" "uuid", "p_version" integer, "p_decision" "text", "p_reason" "text", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_employee_trip"("p_trip" "uuid", "p_decision" "text", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$declare t public.employee_trips;result uuid;begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Employee attendance denied';end if;
 select * into t from public.employee_trips where id=p_trip;
 if not found then raise exception 'Trip not found';end if;
 perform 1 from public.employees where id=t.employee_id for update;
 if t.maker=auth.uid() then raise exception 'Independent trip reviewer required';end if;
 select id into result from public.employee_trip_reviews where trip_id=t.id;
 if found then return result;end if;
 if p_decision='APPROVED' then
  if not exists(select 1 from public.organization_units u join public.branches b on b.id=u.branch_id where u.code=t.destination_unit and b.id=t.destination_branch_id and b.status='ACTIVE') then raise exception 'Destination mapping changed; request a new trip';end if;
  if exists(select 1 from public.employee_trips x join public.employee_trip_reviews r on r.trip_id=x.id and r.decision='APPROVED' where x.employee_id=t.employee_id and x.starts_on<=t.ends_on and x.ends_on>=t.starts_on) then raise exception 'Overlapping approved trip';end if;
  if exists(select 1 from public.employee_attendance_entries where employee_id=t.employee_id and work_date between t.starts_on and t.ends_on) then raise exception 'Attendance already recorded; review before changing schedule';end if;
  if exists(select 1 from generate_series(t.starts_on::timestamp,t.ends_on::timestamp,interval '1 day') d cross join lateral hr_private.employee_at(t.employee_id,d::date) e where e.employment_status is distinct from 'ACTIVE' or e.unit_code is distinct from t.origin_unit) then raise exception 'Employment changed; request a new trip';end if;
 end if;
 insert into public.employee_trip_reviews(trip_id,decision,reason,checker) values(t.id,p_decision,btrim(p_reason),auth.uid()) returning id into result;return result;end$$;


ALTER FUNCTION "public"."review_employee_trip"("p_trip" "uuid", "p_decision" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_learning_assessment"("p_attempt" "uuid", "p_marks" "jsonb", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare a public.learning_assessment_attempts; p public.learning_assessments; e jsonb; mark numeric; earned numeric:=0; total numeric:=0; final_evidence jsonb:='[]'; v_score numeric; result text;
begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Unauthorized'; end if;
 if p_reason is null or length(trim(p_reason)) not between 1 and 2000 or p_marks is null or jsonb_typeof(p_marks)<>'object' then raise exception 'Manual review evidence required'; end if;
 select * into a from public.learning_assessment_attempts where id=p_attempt for update;
 if not found or a.state<>'PENDING_REVIEW' then raise exception 'Attempt is not awaiting review'; end if;
 if exists(select 1 from public.students where id=a.student_id and user_id=auth.uid()) then raise exception 'Cannot review own assessment'; end if;
 select * into p from public.learning_assessments where id=a.assessment_id;
 for e in select value from jsonb_array_elements(a.evidence) loop
 total:=total+(e->>'max_points')::numeric;
 if e->>'mode'='AUTO' then mark:=(e->>'points')::numeric;
 else
 if jsonb_typeof(p_marks->(e->>'code')) is distinct from 'number' then raise exception 'All manual questions require marks'; end if;
 mark:=(p_marks->>(e->>'code'))::numeric;
 if mark<0 or mark>(e->>'max_points')::numeric then raise exception 'Manual mark outside rubric range'; end if;
 end if;
 earned:=earned+mark;final_evidence:=final_evidence||jsonb_build_array(e||jsonb_build_object('points',mark));
 end loop;
 v_score:=round(100*earned/total,4);result:=case when v_score>=p.pass_threshold then 'PASSED' else 'FAILED' end;
 update public.learning_assessment_attempts set state=result,score=v_score,evidence=final_evidence,reviewed_by=auth.uid(),review_reason=trim(p_reason),completed_at=clock_timestamp() where id=p_attempt;
 insert into public.learning_audit(entity_id,event,actor,reason) values(p_attempt,'ASSESSMENT_REVIEWED',auth.uid(),trim(p_reason));
 if result='PASSED' and p.kind='FINAL' then insert into public.learning_academic_shadow(attempt_id,version_id,student_id,proposed_outcome) values(p_attempt,p.version_id,a.student_id,'PASS') on conflict do nothing; end if;
end$$;


ALTER FUNCTION "public"."review_learning_assessment"("p_attempt" "uuid", "p_marks" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_legacy_row"("p_row" "uuid", "p_version" integer, "p_action" "text", "p_reason" "text", "p_payload" "jsonb" DEFAULT NULL::"jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r public.migration_batch_rows%rowtype; b public.migration_batches%rowtype; errors jsonb; reviewer uuid;
begin
 select * into r from public.migration_batch_rows where id=p_row for update;
 select * into b from public.migration_batches where id=r.batch_id;
 if b.id is null or not public.has_permission(case p_action when 'VALIDATE' then 'migration.validate' when 'IDENTITY' then 'migration.review_identity' when 'ACADEMIC' then 'migration.review_academic' when 'FINANCE' then 'migration.review_finance' else 'migration.upload' end,b.branch_id) then raise exception 'Unauthorized'; end if;
 if r.status in ('IMPORTED','ROLLED_BACK') or p_version is null or r.version<>p_version or b.signed_off_at is not null then raise exception 'Stale or imported row'; end if;
 if nullif(btrim(p_reason),'') is null or length(p_reason)>2000 then raise exception 'Review reason required'; end if;
 if p_action='MAP' then
  if jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>20000 then raise exception 'Invalid reviewed payload'; end if;
  if exists(select 1 from jsonb_each(p_payload) where jsonb_typeof(value)<>'string') then raise exception 'Reviewed cells must be text'; end if;
  p_payload:=public.normalize_legacy_payload(p_payload);
  if p_payload->>'legacy_reference' is distinct from r.source_reference then raise exception 'Source reference is immutable'; end if;
  update public.migration_batch_rows set normalized_payload=p_payload,version=version+1,status='NEEDS_REVIEW',identity_reviewed_by=null,academic_reviewed_by=null,finance_reviewed_by=null,validation_result='[]' where id=p_row;
 elsif p_action='REJECT' then
  update public.migration_batch_rows set status='REJECTED',identity_reviewed_by=null,academic_reviewed_by=null,finance_reviewed_by=null where id=p_row;
 elsif p_action in ('VALIDATE','IDENTITY','ACADEMIC','FINANCE') then
  errors:=public.legacy_row_errors(p_row);
  if errors<>'[]' then
   update public.migration_batch_rows set status='NEEDS_REVIEW',validation_result=errors,identity_reviewed_by=null,academic_reviewed_by=null,finance_reviewed_by=null where id=p_row;
  else
   if p_action='FINANCE' and auth.uid()=b.created_by then raise exception 'Financial reviewer must be independent of uploader'; end if;
   if p_action='FINANCE' and exists(select 1 from public.migration_audit_events where row_id=p_row and action='MAP' and actor_id=auth.uid()) then raise exception 'Financial reviewer must be independent of mapping author'; end if;
   update public.migration_batch_rows set status='VALIDATED',validation_result='[]',
    identity_reviewed_by=case when p_action='IDENTITY' then auth.uid() else identity_reviewed_by end,
    academic_reviewed_by=case when p_action='ACADEMIC' then auth.uid() else academic_reviewed_by end,
    finance_reviewed_by=case when p_action='FINANCE' then auth.uid() else finance_reviewed_by end where id=p_row;
   update public.migration_batch_rows set status='READY' where id=p_row and identity_reviewed_by is not null and academic_reviewed_by is not null and finance_reviewed_by is not null;
  end if;
 else raise exception 'Unknown review action'; end if;
 insert into public.migration_audit_events(row_id,batch_id,actor_id,action,reason,row_version,previous_payload,reviewed_payload)
 values(p_row,b.id,auth.uid(),p_action,p_reason,r.version,case when p_action='MAP' then r.normalized_payload end,case when p_action='MAP' then p_payload end);
 return (select status from public.migration_batch_rows where id=p_row);
end $$;


ALTER FUNCTION "public"."review_legacy_row"("p_row" "uuid", "p_version" integer, "p_action" "text", "p_reason" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_learning_access"("p_grant" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Unauthorized'; end if;
 if p_reason is null or length(trim(p_reason)) not between 1 and 2000 then raise exception 'Revocation reason required'; end if;
 update public.learning_access_grants set revoked_at=clock_timestamp() where id=p_grant and revoked_at is null;
 if found then insert into public.learning_audit(entity_id,event,actor,reason) values(p_grant,'REVOKE',auth.uid(),trim(p_reason)); end if;
end$$;


ALTER FUNCTION "public"."revoke_learning_access"("p_grant" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rollback_legacy_row"("p_row" "uuid", "p_approve" boolean, "p_reason" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r public.migration_batch_rows%rowtype; b public.migration_batches%rowtype; req public.migration_rollback_requests%rowtype; eligible boolean;
begin
 select * into b from public.migration_batches where id=(select batch_id from public.migration_batch_rows where id=p_row) for update;
 select * into r from public.migration_batch_rows where id=p_row for update;
 if b.id is null or not public.has_role('SUPER_ADMIN') or not public.has_permission(case when p_approve then 'migration.review_finance' else 'migration.rollback' end,b.branch_id) then raise exception 'Unauthorized'; end if;
 if r.status='ROLLED_BACK' then return 'COMPLETED'; end if;
 if r.status<>'IMPORTED' or b.signed_off_at is not null
  or exists(select 1 from public.migration_batch_rows x join public.migration_batches y on y.id=x.batch_id where x.target_enrollment_id=r.target_enrollment_id and y.signed_off_at is not null)
  or not exists(select 1 from public.migration_source_mappings where row_id=p_row and status='CURRENT') then raise exception 'Source batch requires correction, not rollback'; end if;
 if nullif(btrim(p_reason),'') is null or length(p_reason)>2000 then raise exception 'Rollback reason required'; end if;
 if p_approve is null then raise exception 'Explicit rollback action required'; end if;
 if not p_approve then
  insert into public.migration_rollback_requests(row_id,maker_id,reason) values(p_row,auth.uid(),p_reason) on conflict(row_id) do nothing;
  insert into public.migration_audit_events(row_id,batch_id,actor_id,action,reason) values(p_row,b.id,auth.uid(),'ROLLBACK_REQUEST',p_reason);
  return (select status from public.migration_rollback_requests where row_id=p_row);
 end if;
 select * into req from public.migration_rollback_requests where row_id=p_row for update;
 if req.row_id is null or req.status<>'REQUESTED' then raise exception 'Pending rollback request required'; end if;
 if req.maker_id=auth.uid() then raise exception 'Rollback maker cannot approve own request'; end if;
 -- Parent locks also prevent new FK-linked activity while eligibility is checked.
 perform 1 from public.students where id=r.target_student_id for update;
 perform 1 from public.enrollments where student_id=r.target_student_id for update;
 perform 1 from public.student_curriculum_enrollments where student_id=r.target_student_id for update;
 perform 1 from public.student_level_progress l join public.student_curriculum_enrollments a on a.id=l.enrollment_id where a.student_id=r.target_student_id for update of l;
 perform 1 from public.student_subject_progress s join public.student_level_progress l on l.id=s.level_progress_id join public.student_curriculum_enrollments a on a.id=l.enrollment_id where a.student_id=r.target_student_id for update of s;
 perform 1 from public.student_component_progress c join public.student_subject_progress s on s.id=c.subject_progress_id join public.student_level_progress l on l.id=s.level_progress_id join public.student_curriculum_enrollments a on a.id=l.enrollment_id where a.student_id=r.target_student_id for update of c;
 perform 1 from public.enrollment_tuition where enrollment_id=r.target_enrollment_id for update;
 perform 1 from public.enrollment_pauses where enrollment_id=r.target_enrollment_id for update;
 eligible:=r.business_snapshot is not null and r.business_snapshot=public.legacy_business_snapshot(p_row)
  and not exists(select 1 from public.attendance_records where enrollment_id=r.target_enrollment_id)
  and not exists(select 1 from public.session_occurrence_participants where enrollment_id=r.target_enrollment_id)
  and not exists(select 1 from public.learning_reports where student_id=r.target_student_id)
  and not exists(select 1 from public.lesson_feedback where student_id=r.target_student_id)
  and not exists(select 1 from public.invoices where student_id_snapshot=r.target_student_id)
  and not exists(select 1 from public.payments where student_id_snapshot=r.target_student_id)
  and not exists(select 1 from public.tuition_reminders where enrollment_tuition_id=r.target_tuition_id);
 if not eligible then
  update public.migration_rollback_requests set status='BLOCKED',checker_id=auth.uid(),checked_at=now() where row_id=p_row;
  insert into public.migration_audit_events(row_id,batch_id,actor_id,action,reason) values(p_row,b.id,auth.uid(),'ROLLBACK_BLOCKED','Business data changed or downstream activity exists; correction required');
  return 'BLOCKED';
 end if;
 insert into public.opening_reversals(receivable_id,rollback_row_id,reversed_amount,reversed_settlement)
 select o.id,p_row,o.amount,coalesce(s.amount,0) from public.opening_receivables o left join public.opening_settlements s on s.receivable_id=o.id where o.migration_row_id=p_row;
 update public.enrollment_tuition set status='CANCELLED' where id=r.target_tuition_id;
 update public.enrollments set status='WITHDRAWN' where id=r.target_enrollment_id;
 update public.student_curriculum_enrollments set status='WITHDRAWN' where student_id=r.target_student_id;
 update public.students set status='ARCHIVED' where id=r.target_student_id;
 update public.migration_batch_rows set status='ROLLED_BACK' where target_enrollment_id=r.target_enrollment_id;
 update public.migration_source_mappings set status='ROLLED_BACK' where row_id=p_row;
 update public.migration_rollback_requests set status='COMPLETED',checker_id=auth.uid(),checked_at=now() where row_id=p_row;
 insert into public.migration_audit_events(row_id,batch_id,actor_id,action,reason) values(p_row,b.id,auth.uid(),'ROLLBACK_APPROVED',p_reason);
 return 'COMPLETED';
end $$;


ALTER FUNCTION "public"."rollback_legacy_row"("p_row" "uuid", "p_approve" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_employee_expense_claim_item_v2"("p_claim" "uuid", "p_version" integer, "p_item" "uuid", "p_expense_date" "date", "p_category_name" "text", "p_note" "text", "p_amount" numeric, "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare c public.employee_expense_claims; old_item public.employee_expense_claim_items_v2; payload jsonb; prior jsonb; before_data jsonb;
begin
  select * into c from public.employee_expense_claims
  where id=p_claim and claim_model='ITEMIZED_V2' and created_by=auth.uid()
    and vibe_expense_private.owns_employee(employee_id,branch_id) for update;
  if not found then raise exception 'EXPENSE_UNAUTHORIZED'; end if;
  if p_item is null or p_expense_date is null or not isfinite(p_expense_date) then raise exception 'EXPENSE_V2_ITEM_AND_DATE_REQUIRED'; end if;
  if p_category_name is null or char_length(btrim(p_category_name)) not between 1 and 100 then raise exception 'EXPENSE_V2_CATEGORY_INVALID'; end if;
  if p_note is null or char_length(btrim(p_note)) not between 1 and 2000 then raise exception 'EXPENSE_V2_NOTE_REQUIRED'; end if;
  if p_amount is null or p_amount<=0 or p_amount>999999999999.99 or p_amount<>round(p_amount,2) then raise exception 'EXPENSE_INVALID_MONEY'; end if;
  if c.currency='VND' and p_amount<>trunc(p_amount) then raise exception 'EXPENSE_VND_REQUIRES_WHOLE_DONG'; end if;
  payload:=jsonb_build_object('action','SAVE_ITEM_V2','claim_id',p_claim,'version',p_version,'item_id',p_item,
    'expense_date',p_expense_date,'category_name',btrim(p_category_name),'note',btrim(p_note),'amount',p_amount);
  prior:=vibe_expense_private.replay(p_key,payload); if prior is not null then return prior; end if;
  if c.version is distinct from p_version then raise exception 'EXPENSE_CHANGED_RELOAD'; end if;
  if c.status not in ('DRAFT','RETURNED') then raise exception 'EXPENSE_V2_ITEMS_LOCKED'; end if;
  select * into old_item from public.employee_expense_claim_items_v2 where id=p_item;
  if found and old_item.claim_id<>p_claim then raise exception 'EXPENSE_V2_ITEM_UNAVAILABLE'; end if;
  before_data:=vibe_expense_private.snapshot(p_claim);
  insert into public.employee_expense_claim_items_v2(id,claim_id,expense_date,category_name,note,amount)
  values(p_item,p_claim,p_expense_date,btrim(p_category_name),btrim(p_note),p_amount)
  on conflict(id) do update set expense_date=excluded.expense_date,category_name=excluded.category_name,
    note=excluded.note,amount=excluded.amount,updated_at=clock_timestamp()
  where public.employee_expense_claim_items_v2.claim_id=p_claim;
  if not found then raise exception 'EXPENSE_V2_ITEM_UNAVAILABLE'; end if;
  if (select coalesce(sum(amount),0) from public.employee_expense_claim_items_v2 where claim_id=p_claim)>999999999999.99 then raise exception 'EXPENSE_TOTAL_TOO_LARGE'; end if;
  update public.employee_expense_claims set version=version+1,updated_at=clock_timestamp() where id=p_claim;
  return vibe_expense_private.record_event(p_claim,p_key,payload,'ITEM_SAVED',before_data);
end;
$$;


ALTER FUNCTION "public"."save_employee_expense_claim_item_v2"("p_claim" "uuid", "p_version" integer, "p_item" "uuid", "p_expense_date" "date", "p_category_name" "text", "p_note" "text", "p_amount" numeric, "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_employee_expense_claim_line"("p_claim" "uuid", "p_version" integer, "p_line" "uuid", "p_trip" "uuid", "p_allowance" numeric, "p_transport" numeric, "p_lodging" numeric, "p_note" "text", "p_evidence_reference" "text", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare c public.employee_expense_claims; old_line public.employee_expense_claim_lines;
  trip_data jsonb; payload jsonb; prior jsonb; before_data jsonb; result jsonb;
begin
  select * into c from public.employee_expense_claims
    where id=p_claim and created_by=auth.uid()
      and vibe_expense_private.owns_employee(employee_id,branch_id) for update;
  if not found then raise exception 'EXPENSE_UNAUTHORIZED'; end if;
  if p_line is null or p_trip is null then raise exception 'EXPENSE_LINE_AND_TRIP_REQUIRED'; end if;
  if p_allowance is null or p_transport is null or p_lodging is null
     or p_allowance<0 or p_transport<0 or p_lodging<0
     or p_allowance>999999999999.99 or p_transport>999999999999.99 or p_lodging>999999999999.99
     or p_allowance<>round(p_allowance,2) or p_transport<>round(p_transport,2) or p_lodging<>round(p_lodging,2)
     or p_allowance+p_transport+p_lodging>999999999999.99 then raise exception 'EXPENSE_INVALID_MONEY'; end if;
  if c.currency='VND' and (p_allowance<>trunc(p_allowance) or p_transport<>trunc(p_transport) or p_lodging<>trunc(p_lodging)) then
    raise exception 'EXPENSE_VND_REQUIRES_WHOLE_DONG';
  end if;
  if p_note is null or char_length(btrim(p_note)) not between 1 and 2000 then raise exception 'EXPENSE_LINE_REASON_REQUIRED'; end if;
  if p_evidence_reference is not null and char_length(btrim(p_evidence_reference))>2000 then raise exception 'EXPENSE_EVIDENCE_TOO_LONG'; end if;
  payload:=jsonb_build_object('action','SAVE_LINE','claim_id',p_claim,'version',p_version,'line_id',p_line,'trip_id',p_trip,
    'allowance',p_allowance,'transport',p_transport,'lodging',p_lodging,'note',btrim(p_note),'evidence_reference',nullif(btrim(p_evidence_reference),''));
  prior:=vibe_expense_private.replay(p_key,payload); if prior is not null then return prior; end if;
  if c.version is distinct from p_version then raise exception 'EXPENSE_CHANGED_RELOAD'; end if;
  if c.status not in ('DRAFT','RETURNED') then raise exception 'EXPENSE_LINES_LOCKED'; end if;
  select jsonb_build_object('trip',to_jsonb(t),'review',to_jsonb(r)) into trip_data
  from public.employee_trips t join public.employee_trip_reviews r on r.trip_id=t.id and r.decision='APPROVED'
  where t.id=p_trip and t.employee_id=c.employee_id;
  if trip_data is null then raise exception 'EXPENSE_APPROVED_OWN_TRIP_REQUIRED'; end if;
  if exists(select 1 from public.payroll_adjustments where trip_id=p_trip and kind='TRAVEL_ALLOWANCE') then
    raise exception 'EXPENSE_TRIP_ALREADY_IN_PAYROLL';
  end if;
  select * into old_line from public.employee_expense_claim_lines where id=p_line;
  if found and old_line.claim_id<>p_claim then raise exception 'EXPENSE_LINE_UNAVAILABLE'; end if;
  if old_line.id is null and (select count(*) from public.employee_expense_claim_lines where claim_id=p_claim)>=100 then
    raise exception 'EXPENSE_MAX_100_TRIPS_PER_CLAIM';
  end if;
  if exists(select 1 from public.employee_expense_claim_lines where trip_id=p_trip and reservation_active and id<>p_line) then
    raise exception 'EXPENSE_TRIP_RESERVED_BY_ANOTHER_CLAIM';
  end if;
  before_data:=vibe_expense_private.snapshot(p_claim);
  insert into public.employee_expense_claim_lines(id,claim_id,trip_id,allowance,transport,lodging,note,evidence_reference,trip_snapshot)
  values(p_line,p_claim,p_trip,p_allowance,p_transport,p_lodging,btrim(p_note),nullif(btrim(p_evidence_reference),''),trip_data)
  on conflict(id) do update set trip_id=excluded.trip_id,allowance=excluded.allowance,transport=excluded.transport,
    lodging=excluded.lodging,note=excluded.note,evidence_reference=excluded.evidence_reference,
    trip_snapshot=excluded.trip_snapshot,updated_at=clock_timestamp()
  where public.employee_expense_claim_lines.claim_id=p_claim;
  if not found then raise exception 'EXPENSE_LINE_UNAVAILABLE'; end if;
  if (select coalesce(sum(total_amount),0) from public.employee_expense_claim_lines where claim_id=p_claim)>999999999999.99 then
    raise exception 'EXPENSE_TOTAL_TOO_LARGE';
  end if;
  update public.employee_expense_claims set version=version+1,updated_at=clock_timestamp() where id=p_claim;
  result:=vibe_expense_private.record_event(p_claim,p_key,payload,'LINE_SAVED',before_data);
  return result;
end;
$$;


ALTER FUNCTION "public"."save_employee_expense_claim_line"("p_claim" "uuid", "p_version" integer, "p_line" "uuid", "p_trip" "uuid", "p_allowance" numeric, "p_transport" numeric, "p_lodging" numeric, "p_note" "text", "p_evidence_reference" "text", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_operating_expense_draft"("p_record" "uuid", "p_version" integer, "p_expense_date" "date", "p_due_date" "date", "p_vendor" "text", "p_reference" "text", "p_note" "text", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare rec public.operating_expense_records; payload jsonb; prior jsonb; vendor_name text; reference_text text; note_text text; before_data jsonb; result jsonb;
begin
  select * into rec from public.operating_expense_records where id=p_record for update;
  if not found then raise exception 'OPERATING_EXPENSE_RECORD_NOT_FOUND'; end if;
  if not vibe_operating_expense_private.can_manage(rec.branch_id) then raise exception 'OPERATING_EXPENSE_UNAUTHORIZED'; end if;
  payload:=jsonb_build_object(
    'operation','DRAFT_SAVED','record_id',p_record,'version',p_version,'expense_date',p_expense_date,'due_date',p_due_date,
    'vendor',nullif(btrim(coalesce(p_vendor,'')),''),'reference',nullif(btrim(coalesce(p_reference,'')),''),'note',nullif(btrim(coalesce(p_note,'')),'')
  );
  prior:=vibe_operating_expense_private.replay(p_key,payload);
  if prior is not null then return prior; end if;
  if rec.status<>'DRAFT' then raise exception 'OPERATING_EXPENSE_DRAFT_REQUIRED'; end if;
  if p_version is distinct from rec.version then raise exception 'OPERATING_EXPENSE_CHANGED_RELOAD'; end if;
  if p_expense_date is not null and not isfinite(p_expense_date) then raise exception 'OPERATING_EXPENSE_INVALID_DATE'; end if;
  if p_due_date is not null and not isfinite(p_due_date) then raise exception 'OPERATING_EXPENSE_INVALID_DATE'; end if;
  vendor_name:=nullif(btrim(coalesce(p_vendor,'')),'');
  reference_text:=nullif(btrim(coalesce(p_reference,'')),'');
  note_text:=nullif(btrim(coalesce(p_note,'')),'');
  if vendor_name is not null and char_length(vendor_name)>200 then raise exception 'OPERATING_EXPENSE_INVALID_VENDOR'; end if;
  if reference_text is not null and char_length(reference_text)>200 then raise exception 'OPERATING_EXPENSE_INVALID_REFERENCE'; end if;
  if note_text is not null and char_length(note_text)>2000 then raise exception 'OPERATING_EXPENSE_INVALID_NOTE'; end if;
  before_data:=vibe_operating_expense_private.record_view(p_record);
  update public.operating_expense_records set
    expense_date=p_expense_date,due_date=p_due_date,vendor=vendor_name,reference=reference_text,note=note_text,
    version=version+1,updated_at=clock_timestamp()
  where id=p_record;
  result:=vibe_operating_expense_private.record_view(p_record)||jsonb_build_object('record_id',p_record);
  return vibe_operating_expense_private.write_event(rec.template_id,p_record,'DRAFT_SAVED',p_key,payload,before_data,result,result);
end;
$$;


ALTER FUNCTION "public"."save_operating_expense_draft"("p_record" "uuid", "p_version" integer, "p_expense_date" "date", "p_due_date" "date", "p_vendor" "text", "p_reference" "text", "p_note" "text", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_session_learning_context"("p_session" "uuid", "p_content" "text", "p_context" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor uuid := auth.uid();
  journal_id uuid;
begin
  if p_context is not null and p_context not in ('TECHNIQUE','SIGHTREADING','REPERTOIRE','THEORY') then raise exception 'JOURNAL_CONTEXT_DENIED'; end if;
  journal_id := public.ensure_session_learning_journal(p_session);
  perform set_config('journal.taxonomy_write', 'on', true);
  update public.session_learning_journals set
    content_covered = coalesce(p_content, content_covered),
    curriculum_context = p_context,
    version = version + 1,
    updated_at = clock_timestamp(),
    revision_count = case when status = 'SUBMITTED' then revision_count + 1 else revision_count end,
    revised_at = case when status = 'SUBMITTED' then clock_timestamp() else revised_at end,
    revised_by = case when status = 'SUBMITTED' then actor else revised_by end
  where id = journal_id;
  perform set_config('journal.taxonomy_write', 'off', true);
  return journal_id;
end $$;


ALTER FUNCTION "public"."save_session_learning_context"("p_session" "uuid", "p_content" "text", "p_context" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_student_learning_entry"("p_attendance" "uuid", "p_observation" "text", "p_progress_note" "text", "p_homework" "text", "p_homework_custom" boolean, "p_next_focus" "text", "p_attention" boolean, "p_attention_reason" "text", "p_attention_detail" "text", "p_family_note" "text", "p_codes" "text"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor uuid := auth.uid();
  attendance public.attendance_records%rowtype;
  journal_id uuid;
  v_entry uuid;
  v_option text;
begin
  if actor is null or p_observation not in ('NOT_RECORDED','PRACTICING','NEEDS_REVIEW','ACHIEVED') then raise exception 'JOURNAL_INVALID'; end if;
  select * into attendance from public.attendance_records where id = p_attendance;
  if not found then raise exception 'JOURNAL_ATTENDANCE_MISSING'; end if;
  if not public.can_write_session_journal(attendance.session_occurrence_id) then raise exception 'JOURNAL_UNAUTHORIZED'; end if;
  if attendance.status in ('ABSENT','EXCUSED') and (
    coalesce(array_length(p_codes, 1), 0) > 0
    or p_observation <> 'NOT_RECORDED'
    or nullif(btrim(coalesce(p_progress_note, '')), '') is not null
  ) then
    raise exception 'JOURNAL_ABSENT_OBSERVATION_DENIED';
  end if;
  if coalesce(p_attention, false) and p_attention_reason is not null and not exists(
    select 1 from public.learning_attention_reasons reason where reason.code = p_attention_reason and reason.active
  ) then raise exception 'JOURNAL_ATTENTION_DENIED'; end if;
  if p_next_focus is not null and not exists(select 1 from public.learning_focus_options focus where focus.code = p_next_focus and focus.active) then
    raise exception 'JOURNAL_FOCUS_DENIED';
  end if;
  journal_id := public.ensure_session_learning_journal(attendance.session_occurrence_id);
  perform set_config('journal.taxonomy_write', 'on', true);
  insert into public.student_learning_journal_entries(session_journal_id, attendance_record_id, observation, progress_note, individual_homework, homework_custom, next_focus_code, attention_required, attention_reason_code, attention_detail, family_note)
  values (journal_id, attendance.id, p_observation, coalesce(p_progress_note, ''), coalesce(p_homework, ''), coalesce(p_homework_custom, false), p_next_focus, coalesce(p_attention, false), case when coalesce(p_attention, false) then p_attention_reason else null end, coalesce(p_attention_detail, ''), coalesce(p_family_note, ''))
  on conflict (attendance_record_id) do update set
    observation = excluded.observation,
    progress_note = excluded.progress_note,
    individual_homework = excluded.individual_homework,
    homework_custom = excluded.homework_custom,
    next_focus_code = excluded.next_focus_code,
    attention_required = excluded.attention_required,
    attention_reason_code = excluded.attention_reason_code,
    attention_detail = excluded.attention_detail,
    family_note = excluded.family_note,
    version = student_learning_journal_entries.version + 1,
    updated_at = clock_timestamp()
  returning id into v_entry;
  delete from public.student_journal_observation_selections selection where selection.entry_id = v_entry;
  if attendance.status in ('PRESENT','LATE') then
    foreach v_option in array coalesce(p_codes, array[]::text[]) loop
      if not exists(select 1 from public.learning_observation_options option where option.code = v_option and option.active) then
        raise exception 'JOURNAL_OPTION_INACTIVE';
      end if;
      insert into public.student_journal_observation_selections(entry_id, option_code, selected_by) values (v_entry, v_option, actor);
    end loop;
  end if;
  perform set_config('journal.taxonomy_write', 'off', true);
  return v_entry;
end $$;


ALTER FUNCTION "public"."save_student_learning_entry"("p_attendance" "uuid", "p_observation" "text", "p_progress_note" "text", "p_homework" "text", "p_homework_custom" boolean, "p_next_focus" "text", "p_attention" boolean, "p_attention_reason" "text", "p_attention_detail" "text", "p_family_note" "text", "p_codes" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scan_employee_attendance_qr"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  now_value timestamptz;
  today_vn date;

  linked_employee_count integer;

  employee_id_value uuid;
  employee_code_value text;
  employee_name_value text;

  token_hash_value bytea;

  token_row
    public.attendance_qr_tokens%rowtype;

  session_row
    public.attendance_qr_sessions%rowtype;

  same_token_event
    public.employee_attendance_scan_events%rowtype;

  open_check_in
    public.employee_attendance_scan_events%rowtype;

  inserted_event
    public.employee_attendance_scan_events%rowtype;

  schedule_json jsonb;

  shift_code_value text;
  event_type_value text;
  paired_check_in_value uuid;
begin
  if auth.uid() is null
     or not coalesce(
       public.account_is_active(),
       false
     )
  then
    raise exception 'QR_ATTENDANCE_LOGIN_REQUIRED';
  end if;

  if p_token is null
     or char_length(p_token) <> 64
     or p_token !~ '^[0-9a-fA-F]{64}$'
  then
    raise exception 'QR_ATTENDANCE_INVALID_TOKEN';
  end if;

  now_value := clock_timestamp();

  today_vn :=
    (
      now_value
      at time zone 'Asia/Ho_Chi_Minh'
    )::date;

  select count(*)
  into linked_employee_count
  from public.employees e
  where e.profile_id = auth.uid();

  if linked_employee_count = 0 then
    raise exception 'QR_ATTENDANCE_EMPLOYEE_LINK_REQUIRED';
  end if;

  if linked_employee_count <> 1 then
    raise exception 'QR_ATTENDANCE_EMPLOYEE_LINK_AMBIGUOUS';
  end if;

  select
    d.id,
    d.employee_code,
    d.full_name
  into
    employee_id_value,
    employee_code_value,
    employee_name_value
  from public.employee_directory d
  where d.profile_id = auth.uid()
    and d.employment_status = 'ACTIVE'
  limit 1;

  if employee_id_value is null then
    raise exception 'QR_ATTENDANCE_ACTIVE_EMPLOYEE_REQUIRED';
  end if;

  perform 1
  from public.employees e
  where e.id = employee_id_value
  for update;

  token_hash_value :=
    extensions.digest(
      p_token,
      'sha256'
    );

  select t.*
  into token_row
  from public.attendance_qr_tokens t
  where t.token_hash = token_hash_value
  for update;

  if not found then
    raise exception 'QR_ATTENDANCE_INVALID_TOKEN';
  end if;

  if token_row.revoked_at is not null
     or now_value < token_row.issued_at
     or now_value >= token_row.expires_at
  then
    raise exception 'QR_ATTENDANCE_TOKEN_EXPIRED';
  end if;

  select s.*
  into session_row
  from public.attendance_qr_sessions s
  where s.id = token_row.session_id
  for update;

  if not found
     or session_row.status <> 'ACTIVE'
     or session_row.work_date <> today_vn
  then
    raise exception 'QR_ATTENDANCE_SESSION_NOT_ACTIVE';
  end if;

  select e.*
  into same_token_event
  from public.employee_attendance_scan_events e
  where e.token_id = token_row.id
    and e.employee_id = employee_id_value
  limit 1;

  if found then
    return jsonb_build_object(
      'status', 'ALREADY_SCANNED',
      'event_id', same_token_event.id,
      'event_type', same_token_event.event_type,
      'employee_id', same_token_event.employee_id,
      'branch_id', same_token_event.branch_id,
      'work_date', same_token_event.work_date,
      'shift_code', same_token_event.shift_code,
      'scanned_at', same_token_event.scanned_at
    );
  end if;

  select ci.*
  into open_check_in
  from public.employee_attendance_scan_events ci
  where ci.employee_id = employee_id_value
    and ci.branch_id = session_row.branch_id
    and ci.work_date = today_vn
    and ci.event_type = 'CHECK_IN'
    and not exists (
      select 1
      from public.employee_attendance_scan_events co
      where co.paired_check_in_id = ci.id
        and co.event_type = 'CHECK_OUT'
    )
  order by ci.scanned_at desc
  limit 1
  for update;

  if found then
    event_type_value := 'CHECK_OUT';
    paired_check_in_value := open_check_in.id;
    shift_code_value := open_check_in.shift_code;
    schedule_json := open_check_in.schedule_snapshot;
  else
    select to_jsonb(s)
    into schedule_json
    from public.employee_schedule(
      employee_id_value,
      today_vn,
      today_vn
    ) s
    left join public.organization_units u
      on u.code = s.unit_code
    left join public.employee_trips trip
      on trip.id = s.trip_id
    where s.scheduled_minutes > 0
      and s.schedule_state <> 'SCHEDULED_OFF'
      and coalesce(
        trip.destination_branch_id,
        u.branch_id
      ) = session_row.branch_id
      and not exists (
        select 1
        from public.employee_attendance_scan_events e
        where e.employee_id = employee_id_value
          and e.work_date = today_vn
          and e.shift_code = s.shift_code
          and e.event_type = 'CHECK_IN'
      )
    order by
      case
        when now_value <= s.ends_at
          then 0
        else 1
      end,
      case
        when now_value <= s.ends_at
          then s.starts_at
        else null
      end asc nulls last,
      s.starts_at desc
    limit 1;

    if schedule_json is null then
      raise exception 'QR_ATTENDANCE_NO_ELIGIBLE_SHIFT_AT_BRANCH';
    end if;

    shift_code_value :=
      schedule_json->>'shift_code';

    event_type_value := 'CHECK_IN';
    paired_check_in_value := null;
  end if;

  insert into public.employee_attendance_scan_events(
    session_id,
    token_id,
    employee_id,
    profile_id,
    branch_id,
    work_date,
    shift_code,
    event_type,
    paired_check_in_id,
    schedule_snapshot,
    scanned_at,
    metadata
  )
  values(
    session_row.id,
    token_row.id,
    employee_id_value,
    auth.uid(),
    session_row.branch_id,
    today_vn,
    shift_code_value,
    event_type_value,
    paired_check_in_value,
    schedule_json,
    now_value,
    jsonb_build_object(
      'employee_code',
      employee_code_value,
      'employee_name',
      employee_name_value,
      'identity_source',
      'employees.profile_id',
      'schedule_source',
      'public.employee_schedule'
    )
  )
  returning *
  into inserted_event;

  return jsonb_build_object(
    'status', 'RECORDED',
    'event_id', inserted_event.id,
    'event_type', inserted_event.event_type,
    'employee_id', inserted_event.employee_id,
    'employee_code', employee_code_value,
    'employee_name', employee_name_value,
    'branch_id', inserted_event.branch_id,
    'work_date', inserted_event.work_date,
    'shift_code', inserted_event.shift_code,
    'scanned_at', inserted_event.scanned_at,
    'verification_method',
      inserted_event.verification_method
  );
end;
$_$;


ALTER FUNCTION "public"."scan_employee_attendance_qr"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scoped_students"("p_student" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "student_code" "text", "full_name" "text", "preferred_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select s.id,s.student_code,s.full_name,s.preferred_name from public.students s
 where (p_student is null or s.id=p_student) and (public.has_role('SUPER_ADMIN') or public.student_branch_permission(s.id,'students.view') or public.teacher_can_access_student(s.id)) order by s.student_code
$$;


ALTER FUNCTION "public"."scoped_students"("p_student" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_component_item_progress"("p_component_progress_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_component_id uuid;
  v_completion_rule text;
begin

  select
    scp.component_id,
    csc.completion_rule
  into
    v_component_id,
    v_completion_rule
  from public.student_component_progress scp
  join public.curriculum_subject_components csc
    on csc.id = scp.component_id
  where scp.id = p_component_progress_id;


  if v_component_id is null then
    return;
  end if;


  -- Only item-driven components require Item Progress.
  if v_completion_rule <> 'ALL_REQUIRED_ITEMS' then
    return;
  end if;


  insert into public.student_component_item_progress (
    component_progress_id,
    item_id,
    status
  )
  select
    p_component_progress_id,
    item.id,
    'NOT_STARTED'
  from public.curriculum_component_items item
  where item.component_id = v_component_id
    and item.status = 'ACTIVE'

  on conflict (
    component_progress_id,
    item_id
  )
  do nothing;

end;
$$;


ALTER FUNCTION "public"."seed_component_item_progress"("p_component_progress_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."select_journal_observation"("p_entry" "uuid", "p_code" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor uuid := auth.uid();
  entry public.student_learning_journal_entries%rowtype;
  attendance_status text;
  session_id uuid;
begin
  if actor is null or p_code is null then raise exception 'JOURNAL_INVALID'; end if;
  select * into entry from public.student_learning_journal_entries where id = p_entry;
  if not found then raise exception 'JOURNAL_ENTRY_MISSING'; end if;
  select attendance.status, attendance.session_occurrence_id into attendance_status, session_id
  from public.attendance_records attendance where attendance.id = entry.attendance_record_id;
  if not public.can_write_session_journal(session_id) then raise exception 'JOURNAL_UNAUTHORIZED'; end if;
  if attendance_status in ('ABSENT','EXCUSED') then raise exception 'JOURNAL_ABSENT_OBSERVATION_DENIED'; end if;
  if not exists(select 1 from public.learning_observation_options option where option.code = p_code and option.active) then
    raise exception 'JOURNAL_OPTION_INACTIVE';
  end if;
  perform set_config('journal.taxonomy_write', 'on', true);
  insert into public.student_journal_observation_selections(entry_id, option_code, selected_by) values (entry.id, p_code, actor);
  perform set_config('journal.taxonomy_write', 'off', true);
  return entry.id;
end $$;


ALTER FUNCTION "public"."select_journal_observation"("p_entry" "uuid", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."session_journal_branch"("p_session" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select class_row.branch_id
  from public.session_occurrences occurrence
  join public.schedules schedule on schedule.id = occurrence.schedule_id
  join public.classes class_row on class_row.id = schedule.class_id
  where occurrence.id = p_session
$$;


ALTER FUNCTION "public"."session_journal_branch"("p_session" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."session_teaching_academic"("p_program" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select jsonb_build_object('id',e.id,'name',cur.name,'level_id',e.current_level_id,'level_name',l.name,
  'started_at',lp.started_at,'level_status',lp.status,'subjects',coalesce((
   select jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'rule',s.completion_rule,
    'progress_id',sp.id,'status',coalesce(sp.status,'NOT_STARTED'),'components',coalesce((
     select jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'rule',c.completion_rule,
      'progress_id',cp.id,'status',coalesce(cp.status,'NOT_STARTED'),'items',coalesce((
       select jsonb_agg(jsonb_build_object('id',i.id,'name',i.name,'progress_id',ip.id,'status',coalesce(ip.status,'NOT_STARTED')) order by i.sort_order,i.id)
       from curriculum_component_items i left join student_component_item_progress ip on ip.item_id=i.id and ip.component_progress_id=cp.id
       where i.component_id=c.id and i.status='ACTIVE'),'[]'::jsonb)) order by c.sort_order,c.id)
     from curriculum_subject_components c left join student_component_progress cp on cp.component_id=c.id and cp.subject_progress_id=sp.id
     where c.subject_id=s.id and c.status='ACTIVE'),'[]'::jsonb)) order by s.sort_order,s.id)
   from curriculum_subjects s left join student_subject_progress sp on sp.subject_id=s.id and sp.level_progress_id=lp.id
   where s.level_id=e.current_level_id and s.status='ACTIVE'),'[]'::jsonb))
 from student_curriculum_enrollments e join curriculums cur on cur.id=e.curriculum_id
 left join curriculum_levels l on l.id=e.current_level_id
 left join student_level_progress lp on lp.enrollment_id=e.id and lp.level_id=e.current_level_id
 where e.id=p_program and e.status='ACTIVE'
$$;


ALTER FUNCTION "public"."session_teaching_academic"("p_program" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."session_teaching_roster"("p_session" "uuid") RETURNS TABLE("enrollment_id" "uuid", "student_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select e.id,e.student_id from public.session_occurrences o
 join public.schedules sc on sc.id=o.schedule_id join public.enrollments e on e.class_id=sc.class_id
 where o.id=p_session and (
  (o.occurrence_type='MAKEUP' and exists(select 1 from public.session_occurrence_participants p where p.session_occurrence_id=o.id and p.enrollment_id=e.id))
  or (o.occurrence_type='REGULAR' and e.started_at<=o.occurrence_date
      and (e.ended_at is null or e.ended_at>=o.occurrence_date)
      and not public.is_enrollment_paused_on(e.id,o.occurrence_date)))
$$;


ALTER FUNCTION "public"."session_teaching_roster"("p_session" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_class_level_scope"("p_class" "uuid", "p_from" "uuid", "p_to" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_course uuid;
begin
  if not coalesce(public.has_role('SUPER_ADMIN'), false) then
    raise exception 'Unauthorized' using errcode = 'P0001';
  end if;

  select course_id into v_course from public.classes where id = p_class;
  if v_course is null then
    raise exception 'Class not found' using errcode = 'P0001';
  end if;

  perform public.validate_class_level_scope(v_course, p_from, p_to);

  update public.classes
  set accepted_from_level_id = p_from,
      accepted_to_level_id = p_to,
      updated_at = now()
  where id = p_class;

  return p_class;
end;
$$;


ALTER FUNCTION "public"."set_class_level_scope"("p_class" "uuid", "p_from" "uuid", "p_to" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_crm_campaign_status"("p_request" "uuid", "p_campaign" "uuid", "p_version" integer, "p_status" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  row public.crm_campaigns%rowtype;
  next_status text := nullif(upper(btrim(coalesce(p_status, ''))), '');
begin
  if next_status is null or next_status not in ('DRAFT', 'ACTIVE', 'INACTIVE') or p_request is null then
    raise exception 'CRM_CAMPAIGN_INVALID';
  end if;
  select * into row from public.crm_campaigns where id = p_campaign for update;
  if not found then raise exception 'CRM_CAMPAIGN_UNAUTHORIZED'; end if;
  if row.branch_id is null then
    if not public.has_role('SUPER_ADMIN') then raise exception 'CRM_CAMPAIGN_UNAUTHORIZED'; end if;
  else
    perform public.crm_actor('crm.campaign.manage', row.branch_id);
  end if;
  if row.version is distinct from p_version then raise exception 'CRM_CAMPAIGN_STALE'; end if;
  perform set_config('crm.lead_write', 'on', true);
  update public.crm_campaigns set status = next_status, version = version + 1, updated_at = clock_timestamp() where id = row.id;
  perform set_config('crm.lead_write', 'off', true);
  return row.id;
end $$;


ALTER FUNCTION "public"."set_crm_campaign_status"("p_request" "uuid", "p_campaign" "uuid", "p_version" integer, "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_crm_lead_campaign"("p_request" "uuid", "p_lead" "uuid", "p_version" integer, "p_campaign" "uuid", "p_external_source" "text", "p_external_lead_id" "text", "p_campaign_reference" "text", "p_received_at" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  row public.crm_leads%rowtype;
  campaign public.crm_campaigns%rowtype;
  actor uuid := auth.uid();
  meta jsonb;
begin
  if actor is null or not public.account_is_active() or p_request is null then
    raise exception 'CRM_LEAD_UNAUTHORIZED';
  end if;
  if p_campaign is not null then
    select * into campaign from public.crm_campaigns where id = p_campaign;
    if not found or campaign.status = 'INACTIVE' then raise exception 'CRM_CAMPAIGN_INVALID'; end if;
  end if;
  meta := jsonb_build_object('campaign_id', p_campaign, 'external_lead_id', public.crm_text(p_external_lead_id, 120));
  if public.crm_lead_replay(p_request, p_lead, 'UPDATED', actor, null, null, meta, 'crm.lead.update') then
    return p_lead;
  end if;
  row := public.crm_lead_lock(p_lead, p_version, 'crm.lead.update');
  if p_campaign is not null and campaign.branch_id is not null and campaign.branch_id is distinct from row.branch_id then
    raise exception 'CRM_LEAD_UNAUTHORIZED';
  end if;
  perform set_config('crm.lead_write', 'on', true);
  update public.crm_leads set
    campaign_id = p_campaign,
    external_source = public.crm_text(p_external_source, 80),
    external_lead_id = public.crm_text(p_external_lead_id, 120),
    campaign_reference = public.crm_text(p_campaign_reference, 120),
    received_at = p_received_at,
    version = version + 1,
    updated_at = clock_timestamp()
  where id = row.id;
  insert into public.crm_lead_events(id, lead_id, event_type, from_status, to_status, actor_id, metadata)
  values (p_request, row.id, 'UPDATED', row.status, row.status, actor, meta);
  perform set_config('crm.lead_write', 'off', true);
  return row.id;
end $$;


ALTER FUNCTION "public"."set_crm_lead_campaign"("p_request" "uuid", "p_lead" "uuid", "p_version" integer, "p_campaign" "uuid", "p_external_source" "text", "p_external_lead_id" "text", "p_campaign_reference" "text", "p_received_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_crm_lead_follow_up"("p_request" "uuid", "p_lead" "uuid", "p_version" integer, "p_follow_up_on" "date", "p_note" "text", "p_channel" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  row public.crm_leads%rowtype;
  actor uuid := auth.uid();
  note text := public.crm_text(p_note, 4000);
  channel text := public.crm_channel(p_channel);
  meta jsonb;
begin
  if actor is null or not coalesce(public.account_is_active(), false) then
    raise exception 'CRM_LEAD_UNAUTHORIZED';
  end if;
  if p_follow_up_on is null or not isfinite(p_follow_up_on) then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  meta := jsonb_build_object('next_follow_up_on', p_follow_up_on);
  if public.crm_lead_replay(p_request, p_lead, 'FOLLOW_UP_SET', actor, note, channel, meta, 'crm.lead.update') then
    return p_lead;
  end if;
  row := public.crm_lead_lock(p_lead, p_version, 'crm.lead.update');
  perform set_config('crm.lead_write', 'on', true);
  update public.crm_leads set
    next_follow_up_on = p_follow_up_on,
    version = version + 1,
    updated_at = clock_timestamp()
  where id = row.id;
  insert into public.crm_lead_events(id, lead_id, event_type, from_status, to_status, actor_id, channel, note, metadata)
  values (p_request, row.id, 'FOLLOW_UP_SET', row.status, row.status, actor, channel, note, meta);
  perform set_config('crm.lead_write', 'off', true);
  return row.id;
end $$;


ALTER FUNCTION "public"."set_crm_lead_follow_up"("p_request" "uuid", "p_lead" "uuid", "p_version" integer, "p_follow_up_on" "date", "p_note" "text", "p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_crm_lead_interest"("p_request" "uuid", "p_lead" "uuid", "p_version" integer, "p_interest_level" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  row public.crm_leads%rowtype;
  v_interest text := upper(btrim(coalesce(p_interest_level, '')));
  v_actor uuid := auth.uid();
  v_meta jsonb;
begin
  if v_interest not in ('REFERENCE', 'INTERESTED', 'POTENTIAL') then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  v_meta := jsonb_build_object('to', v_interest);
  if public.crm_lead_replay(p_request, p_lead, 'INTEREST_LEVEL_SET', v_actor,
    null, null, v_meta, 'crm.lead.update') then return p_lead; end if;
  row := public.crm_lead_lock(p_lead, p_version, 'crm.lead.update');
  perform set_config('crm.lead_write', 'on', true);
  update public.crm_leads set interest_level = v_interest, version = version + 1,
    updated_at = clock_timestamp() where id = row.id;
  insert into public.crm_lead_events(id, lead_id, event_type, from_status, to_status, actor_id, metadata)
  values (p_request, row.id, 'INTEREST_LEVEL_SET', row.status, row.status, v_actor, v_meta);
  perform set_config('crm.lead_write', 'off', true);
  return row.id;
end $$;


ALTER FUNCTION "public"."set_crm_lead_interest"("p_request" "uuid", "p_lead" "uuid", "p_version" integer, "p_interest_level" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_employee_version"("p_employee" "uuid", "p_expected_version" integer, "p_effective_on" "date", "p_full_name" "text", "p_unit" "text", "p_group" "text", "p_status" "text", "p_pay_type" "text", "p_role" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare e public.employees; previous public.employee_versions; result uuid;begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Employee administration denied'; end if;
 select * into e from public.employees where id=p_employee for update;
 if not found then raise exception 'Employee not found'; end if;
 select * into previous from public.employee_versions where employee_id=e.id order by version desc limit 1;
 if p_expected_version is distinct from coalesce(previous.version,0) then raise exception 'Employee changed; reload before saving'; end if;
 if p_effective_on is null or p_effective_on<e.hire_date or p_effective_on<previous.effective_on then raise exception 'Invalid effective date'; end if;
 insert into public.employee_versions(employee_id,version,effective_on,full_name,unit_code,employee_group,employment_status,end_date,pay_type,operational_role_id,reason,created_by)
 values(e.id,coalesce(previous.version,0)+1,p_effective_on,btrim(p_full_name),p_unit,btrim(p_group),p_status,case when p_status='TERMINATED' then p_effective_on end,p_pay_type,p_role,btrim(p_reason),auth.uid()) returning id into result;
 insert into public.employee_audit(employee_id,action,before_data,after_data,reason,actor)
 select e.id,'EMPLOYMENT_VERSION',case when previous.id is not null then to_jsonb(previous) end,to_jsonb(v),p_reason,auth.uid() from public.employee_versions v where id=result;
 return result;end$$;


ALTER FUNCTION "public"."set_employee_version"("p_employee" "uuid", "p_expected_version" integer, "p_effective_on" "date", "p_full_name" "text", "p_unit" "text", "p_group" "text", "p_status" "text", "p_pay_type" "text", "p_role" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_notification_template_mapping"("p_template_key" "text", "p_provider_template_id" "text", "p_status" "text" DEFAULT 'PENDING'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
begin
  if not public.has_role('SUPER_ADMIN') then
    raise exception 'Unauthorized';
  end if;
  if p_template_key is distinct from 'ZALO_REGISTRATION_CONFIRMED' then
    raise exception 'Unsupported notification template';
  end if;
  if p_status is null or p_status not in ('PENDING', 'APPROVED') then
    raise exception 'Invalid template status';
  end if;
  if p_provider_template_id is null or p_provider_template_id !~ '^[A-Za-z0-9_-]{1,80}$' then
    raise exception 'Provider template id required';
  end if;
  if p_status = 'APPROVED' and nullif(btrim(p_provider_template_id), '') is null then
    raise exception 'Approved template requires a provider template id';
  end if;
  update public.notification_templates
  set
    provider_template_id = p_provider_template_id,
    status = p_status,
    enabled = false
  where template_key = p_template_key
    and provider = 'ZALO';
  if not found then
    raise exception 'Notification template not found';
  end if;
end $_$;


ALTER FUNCTION "public"."set_notification_template_mapping"("p_template_key" "text", "p_provider_template_id" "text", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_registration_branch"("p_application" "uuid", "p_version" integer, "p_branch" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare app public.registration_applications%rowtype;
begin
  app := public.registration_lock(p_application, p_version, 'registration.update');
  if not public.registration_can('registration.update', p_branch) then raise exception 'REGISTRATION_UNAUTHORIZED'; end if;
  if app.status not in ('DRAFT', 'SUBMITTED', 'VERIFIED') or p_branch is null
     or exists (select 1 from public.registration_deposit_terms where application_id = app.id)
     or not exists (select 1 from public.branches where id = p_branch) then
    raise exception 'REGISTRATION_BRANCH_LOCKED';
  end if;
  perform set_config('registration.write', 'on', true);
  update public.registration_applications
  set branch_id = p_branch, version = version + 1, updated_at = clock_timestamp()
  where id = app.id;
  insert into public.registration_application_events(id, application_id, event_type, from_status, to_status, actor_id)
  values (gen_random_uuid(), app.id, 'BRANCH_SET', app.status, app.status, auth.uid());
  perform set_config('registration.write', 'off', true);
  return app.id;
end $$;


ALTER FUNCTION "public"."set_registration_branch"("p_application" "uuid", "p_version" integer, "p_branch" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_registration_deposit_quote"("p_application" "uuid", "p_version" integer, "p_plan" "uuid", "p_discount_type" "text" DEFAULT 'NONE'::"text", "p_discount_value" numeric DEFAULT 0, "p_discount_name" "text" DEFAULT NULL::"text", "p_payment_option" "text" DEFAULT 'DEPOSIT_50'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  app public.registration_applications%rowtype;
  plan public.tuition_plans%rowtype;
  price public.tuition_plan_branch_prices%rowtype;
  discount_type text;
  payment_option text;
  discount_amount numeric;
  list_amount bigint;
  agreed bigint;
  due bigint;
  expected bigint;
begin
  app := public.registration_lock(p_application, p_version, 'registration.update');
  discount_type := upper(coalesce(nullif(btrim(p_discount_type), ''), 'NONE'));
  payment_option := upper(coalesce(nullif(btrim(p_payment_option), ''), 'DEPOSIT_50'));
  if app.status <> 'VERIFIED' or p_plan is null
     or payment_option not in ('DEPOSIT_50', 'FULL')
     or exists(select 1 from public.registration_momo_orders where application_id = p_application) then
    raise exception 'REGISTRATION_QUOTE_DENIED';
  end if;
  select * into plan from public.tuition_plans where id = p_plan and status = 'ACTIVE';
  if not found then raise exception 'REGISTRATION_QUOTE_DENIED'; end if;
  if discount_type <> 'NONE' and nullif(btrim(p_discount_name), '') is null then
    raise exception 'REGISTRATION_DISCOUNT_EVIDENCE_REQUIRED';
  end if;
  expected := public.registration_authoritative_list_price(app.branch_id, p_plan);
  if plan.code in ('VIBE_3_MONTHS', 'VIBE_12_MONTHS') then
    select * into price from public.tuition_plan_branch_prices
    where tuition_plan_id = p_plan and status = 'ACTIVE' and currency = 'VND'
      and list_price = expected
      and (
        branch_id = app.branch_id
        or (
          branch_id is null
          and not exists (
            select 1 from public.tuition_plan_branch_prices specific
            where specific.tuition_plan_id = p_plan
              and specific.branch_id = app.branch_id
              and specific.status = 'ACTIVE'
          )
        )
      )
    order by (branch_id = app.branch_id) desc nulls last, created_at desc
    limit 1;
  else
    select * into price from public.tuition_plan_branch_prices
    where tuition_plan_id = p_plan and status = 'ACTIVE' and currency = 'VND'
      and branch_id = app.branch_id
    order by created_at desc limit 1;
  end if;
  if not found or price.list_price <= 0 or price.list_price > 100000000
     or price.list_price <> trunc(price.list_price)
     or (expected is not null and price.list_price <> expected) then
    raise exception 'REGISTRATION_PRICE_UNAVAILABLE';
  end if;
  discount_amount := public.calculate_tuition_discount_amount(
    price.list_price, discount_type, coalesce(p_discount_value, 0));
  if discount_amount <> trunc(discount_amount) then
    raise exception 'REGISTRATION_DISCOUNT_NOT_WHOLE_VND';
  end if;
  list_amount := price.list_price::bigint;
  agreed := list_amount - discount_amount::bigint;
  if agreed <= 0 or agreed > 100000000 then
    raise exception 'REGISTRATION_PRICE_UNAVAILABLE';
  end if;
  due := case when payment_option = 'FULL' then agreed else (agreed + 1) / 2 end;
  insert into public.registration_deposit_terms(
    application_id, branch_id, tuition_plan_id, price_id, tuition_amount, quoted_by,
    list_amount, discount_type, discount_value, discount_name, discount_amount,
    payment_option, amount_due)
  values (
    app.id, app.branch_id, p_plan, price.id, agreed, auth.uid(),
    list_amount, discount_type, coalesce(p_discount_value, 0),
    nullif(btrim(p_discount_name), ''), discount_amount::bigint,
    payment_option, due)
  on conflict (application_id) do update set
    branch_id = excluded.branch_id,
    tuition_plan_id = excluded.tuition_plan_id,
    price_id = excluded.price_id,
    tuition_amount = excluded.tuition_amount,
    quoted_by = excluded.quoted_by,
    quoted_at = clock_timestamp(),
    list_amount = excluded.list_amount,
    discount_type = excluded.discount_type,
    discount_value = excluded.discount_value,
    discount_name = excluded.discount_name,
    discount_amount = excluded.discount_amount,
    payment_option = excluded.payment_option,
    amount_due = excluded.amount_due;
  return app.id;
end $$;


ALTER FUNCTION "public"."set_registration_deposit_quote"("p_application" "uuid", "p_version" integer, "p_plan" "uuid", "p_discount_type" "text", "p_discount_value" numeric, "p_discount_name" "text", "p_payment_option" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_session_occurrence_status"("p_occurrence_id" "uuid", "p_status" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_status text;
begin
  if p_status not in (
    'SCHEDULED',
    'COMPLETED',
    'CANCELLED'
  ) then
    raise exception 'Invalid session status';
  end if;

  update public.session_occurrences
  set status = p_status
  where id = p_occurrence_id
  returning status into v_status;

  if v_status is null then
    raise exception 'Session not found';
  end if;

  return v_status;
end;
$$;


ALTER FUNCTION "public"."set_session_occurrence_status"("p_occurrence_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_session_teacher"("p_session_id" "uuid", "p_teacher_id" "uuid", "p_type" "text", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare s record;
begin
 if not coalesce(has_role('SUPER_ADMIN'),false) then raise exception 'Unauthorized'; end if;
 select o.status,c.branch_id into s from session_occurrences o join schedules sc on sc.id=o.schedule_id join classes c on c.id=sc.class_id where o.id=p_session_id for update of o;
 if not found then raise exception 'Session not found'; end if;
 if s.status<>'SCHEDULED' or exists(select 1 from session_teacher_snapshots where session_id=p_session_id) then raise exception 'Completed or cancelled session assignment is locked'; end if;
 if p_reason is null or char_length(btrim(p_reason)) not between 1 and 2000 then raise exception 'Assignment reason required'; end if;
 if p_teacher_id is not null then
   if p_type is null or p_type not in ('PRIMARY','SUBSTITUTE','OVERRIDE') then raise exception 'Invalid assignment type'; end if;
   if not exists(select 1 from teachers where id=p_teacher_id and status='ACTIVE') then raise exception 'Teacher must be active'; end if;
   if not exists(select 1 from teacher_branches where teacher_id=p_teacher_id and branch_id=s.branch_id) then raise exception 'Teacher must belong to session branch'; end if;
 end if;
 update session_teacher_assignments set effective_status='REPLACED',replaced_at=now(),replaced_by=auth.uid(),replacement_reason=btrim(p_reason) where session_id=p_session_id and effective_status='ACTIVE';
 if p_teacher_id is not null then
 insert into session_teacher_assignments(session_id,teacher_id,assignment_type,reason,assigned_by) values(p_session_id,p_teacher_id,p_type,btrim(p_reason),auth.uid());
 end if;
end $$;


ALTER FUNCTION "public"."set_session_teacher"("p_session_id" "uuid", "p_teacher_id" "uuid", "p_type" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_student_placement_matching"("p_request" "uuid", "p_placement" "uuid", "p_version" integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor uuid := auth.uid();
  row public.student_placement_cases%rowtype;
begin
  if actor is null or p_request is null then raise exception 'PLACEMENT_INVALID'; end if;
  if exists(select 1 from public.student_placement_events where id = p_request) then return p_placement; end if;
  select * into row from public.student_placement_cases where id = p_placement for update;
  if not found or not public.registration_can('student_placement.manage', row.branch_id) then raise exception 'PLACEMENT_UNAUTHORIZED'; end if;
  if row.version is distinct from p_version then raise exception 'PLACEMENT_STALE'; end if;
  if row.status <> 'UNASSIGNED' then raise exception 'PLACEMENT_TRANSITION_DENIED'; end if;
  perform set_config('registration.write', 'on', true);
  update public.student_placement_cases set status = 'MATCHING', version = version + 1, updated_at = clock_timestamp() where id = row.id;
  insert into public.student_placement_events(id, placement_id, event_type, actor_id) values (p_request, row.id, 'PLACEMENT_MATCHING', actor);
  perform set_config('registration.write', 'off', true);
  return row.id;
end $$;


ALTER FUNCTION "public"."set_student_placement_matching"("p_request" "uuid", "p_placement" "uuid", "p_version" integer) OWNER TO "postgres";


