CREATE OR REPLACE FUNCTION "public"."settle_outbound_notification"("p_job" "uuid", "p_error" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  job public.notification_jobs;
  next_attempts integer;
  next_status text;
begin
  if p_error is null or btrim(p_error) = '' then
    raise exception 'Live Zalo send is disabled';
  end if;
  if p_error not in (
    'PROVIDER_TIMEOUT', 'PROVIDER_UNAVAILABLE', 'ZALO_OUTBOUND_NOT_CONFIGURED',
    'TEMPLATE_NOT_APPROVED', 'PROVIDER_NOT_CONFIGURED', 'RECIPIENT_INELIGIBLE',
    'PROVIDER_REJECTED', 'ZALO_RECIPIENT_NOT_LINKED'
  ) then
    raise exception 'Invalid provider error code';
  end if;
  select * into job from public.notification_jobs where id = p_job for update;
  if not found or job.channel is distinct from 'ZALO' or job.status not in ('QUEUED', 'RETRYING', 'PENDING', 'PROCESSING') then
    raise exception 'Outbound job is not sendable';
  end if;
  next_attempts := job.attempts + 1;
  if p_error in ('PROVIDER_TIMEOUT', 'PROVIDER_UNAVAILABLE') and next_attempts < 5 then
    next_status := 'RETRYING';
    update public.notification_jobs
    set status = next_status, attempts = next_attempts, error_code = p_error,
      next_attempt_at = now() + (next_attempts * interval '15 minutes'),
      sent_at = null, provider_receipt = null, provider_message_id = null, updated_at = now()
    where id = job.id;
  else
    next_status := 'FAILED';
    update public.notification_jobs
    set status = next_status, attempts = next_attempts, error_code = p_error,
      next_attempt_at = null, sent_at = null, provider_receipt = null, provider_message_id = null,
      updated_at = now()
    where id = job.id;
  end if;
  insert into public.notification_events(job_id, event, details)
  values (job.id, next_status, jsonb_build_object('error_code', p_error));
  return next_status;
end $$;


ALTER FUNCTION "public"."settle_outbound_notification"("p_job" "uuid", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sign_off_legacy_batch"("p_batch" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare b public.migration_batches%rowtype;
begin
 select * into b from public.migration_batches where id=p_batch for update;
 if b.id is null or not public.has_role('SUPER_ADMIN') or not public.has_permission('migration.sign_off_final',b.branch_id) then raise exception 'Unauthorized'; end if;
 if nullif(btrim(p_reason),'') is null or length(p_reason)>2000 then raise exception 'Sign-off reason required'; end if;
 perform 1 from public.migration_batch_rows where batch_id=p_batch for update;
 if not exists(select 1 from public.migration_batch_rows where batch_id=p_batch and status='IMPORTED')
  or exists(select 1 from public.migration_batch_rows where batch_id=p_batch and status not in ('IMPORTED','REJECTED'))
  or exists(select 1 from public.migration_rollback_requests q join public.migration_batch_rows r on r.id=q.row_id where r.batch_id=p_batch and q.status='REQUESTED')
  or exists(select 1 from public.migration_reconciliation where batch_id=p_batch and status='IMPORTED' and (amount_difference is distinct from 0 or paid_difference is distinct from 0 or outstanding_difference is distinct from 0)) then raise exception 'Exact reconciliation and completed review required'; end if;
 update public.migration_batches set signed_off_by=auth.uid(),signed_off_at=now() where id=p_batch and signed_off_at is null;
 insert into public.migration_audit_events(batch_id,actor_id,action,reason) values(p_batch,auth.uid(),'SIGN_OFF',p_reason);
end $$;


ALTER FUNCTION "public"."sign_off_legacy_batch"("p_batch" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."snapshot_tuition_zalo_send_context"("p_tracking_id" "text", "p_app_id" "text", "p_oa_id" "text", "p_template_id" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare candidate public.tuition_zalo_sends;
begin
  if p_app_id is null or p_oa_id is null or p_template_id is null then return 'invalid_context'; end if;
  if not exists(select 1 from notification_private.zalo_credentials where app_id=p_app_id and oa_id=p_oa_id and state='READY')
    or not exists(select 1 from notification_templates where template_key='ZALO_TUITION_REMINDER' and provider_template_id=p_template_id)
    then return 'context_mismatch'; end if;
  select * into candidate from tuition_zalo_sends where tracking_id=p_tracking_id for update;
  if not found or candidate.send_status<>'PREPARED' then return 'send_not_prepared'; end if;
  if candidate.context_captured_at is not null then
    if candidate.app_id=p_app_id and candidate.oa_id=p_oa_id and candidate.provider_template_id=p_template_id then return 'captured'; end if;
    return 'context_mismatch';
  end if;
  update tuition_zalo_sends set app_id=p_app_id,oa_id=p_oa_id,provider_template_id=p_template_id,context_captured_at=clock_timestamp() where id=candidate.id;
  return 'captured';
end $$;


ALTER FUNCTION "public"."snapshot_tuition_zalo_send_context"("p_tracking_id" "text", "p_app_id" "text", "p_oa_id" "text", "p_template_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."staff_name_card"("p_employee" "uuid") RETURNS TABLE("full_name" "text", "employee_code" "text", "teaching_badges" "text"[], "position_badges" "text"[], "branch_name" "text", "portrait_path" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
begin
  if not coalesce(public.has_role('SUPER_ADMIN'), false) then
    raise exception 'STAFF_PROFILE_UNAUTHORIZED';
  end if;
  return query
  select
    directory.full_name,
    directory.employee_code,
    coalesce((
      select array_agg(label order by label)
      from (
        select distinct case a.capacity
          when 'TEACHER' then 'Giáo viên ' || c.name
          when 'ASSISTANT' then 'Trợ giảng ' || c.name
        end as label
        from public.staff_teaching_assignments a
        join public.curriculums c on c.id = a.curriculum_id
        where a.employee_id = directory.id
          and a.status = 'ACTIVE'
          and a.effective_from <= today
          and (a.effective_to is null or a.effective_to >= today)
          and nullif(btrim(c.name), '') is not null
      ) labels
      where label is not null
    ), '{}'::text[]),
    coalesce((
      select array_agg(code order by code)
      from (
        select distinct p.position_code as code
        from public.staff_position_assignments p
        where p.employee_id = directory.id
          and p.status = 'ACTIVE'
          and p.position_code in ('VAS', 'VAM', 'VAH')
          and p.effective_from <= today
          and (p.effective_to is null or p.effective_to >= today)
      ) codes
    ), '{}'::text[]),
    case when branch.id is not null and branch.status = 'ACTIVE' then branch.name else null end,
    (
      select portrait.storage_path
      from public.staff_portraits portrait
      where portrait.employee_id = directory.id and portrait.status = 'ACTIVE'
      limit 1
    )
  from public.employee_directory directory
  left join public.organization_units unit on unit.code = directory.unit_code
  left join public.branches branch on branch.id = unit.branch_id
  where directory.id = p_employee;
end;
$$;


ALTER FUNCTION "public"."staff_name_card"("p_employee" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stage_legacy_batch"("p_source" "text", "p_filename" "text", "p_hash" "text", "p_cutover" "date", "p_branch" "uuid", "p_rows" "jsonb", "p_raw_csv" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare bid uuid; item jsonb; normalized jsonb; n integer:=0; existing public.migration_batches%rowtype;
begin
 if not public.has_permission('migration.upload',p_branch) then raise exception 'Unauthorized'; end if;
 if p_cutover is null or p_cutover>(now() at time zone 'Asia/Ho_Chi_Minh')::date then raise exception 'Invalid cutover date'; end if;
 if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) not between 1 and 500 then raise exception 'Expected 1 to 500 source rows'; end if;
 if octet_length(p_rows::text)>1000000 then raise exception 'Source payload too large'; end if;
 if p_raw_csv is not null and (octet_length(p_raw_csv)>500000 or encode(sha256(convert_to(p_raw_csv,'UTF8')),'hex')<>p_hash) then raise exception 'Raw file hash mismatch'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_source||':'||p_hash,0));
 select * into existing from public.migration_batches where source_system=p_source and source_file_hash=p_hash and template_version='V1';
 if found then
  if existing.branch_id<>p_branch or existing.cutover_date<>p_cutover or
   (select jsonb_agg(raw_payload order by row_number) from public.migration_batch_rows where batch_id=existing.id) is distinct from p_rows then
   raise exception 'File identity conflicts with previous upload';
  end if;
  return existing.id;
 end if;
 insert into public.migration_batches(source_system,source_file_name,source_file_hash,cutover_date,branch_id,created_by,raw_csv)
 values(p_source,p_filename,p_hash,p_cutover,p_branch,auth.uid(),p_raw_csv) returning id into bid;
 for item in select value from jsonb_array_elements(p_rows) loop
  if jsonb_typeof(item) is distinct from 'object' or octet_length(item::text)>20000 then raise exception 'Invalid source row'; end if;
  if exists(select 1 from jsonb_each(item) where jsonb_typeof(value)<>'string') then raise exception 'Source cells must be text'; end if;
  normalized:=public.normalize_legacy_payload(item);
  n:=n+1;
  insert into public.migration_batch_rows(batch_id,row_number,source_reference,raw_payload,normalized_payload)
  values(bid,n,normalized->>'legacy_reference',item,normalized);
 end loop;
 insert into public.migration_audit_events(batch_id,actor_id,action,reason) values(bid,auth.uid(),'UPLOAD','Source accepted for review only');
 return bid;
end $$;


ALTER FUNCTION "public"."stage_legacy_batch"("p_source" "text", "p_filename" "text", "p_hash" "text", "p_cutover" "date", "p_branch" "uuid", "p_rows" "jsonb", "p_raw_csv" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stamp_academic_progress_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin

  if tg_op = 'INSERT'
     or new.status is distinct from old.status
  then

    -- Any status other than NOT_STARTED means learning has begun.
    if new.status <> 'NOT_STARTED' then
      new.started_at := coalesce(new.started_at, now());
    end if;

    -- PASS timestamp.
    if new.status in ('PASS', 'MERIT', 'DISTINCTION') then
      new.passed_at := coalesce(new.passed_at, now());
    else
      new.passed_at := null;
    end if;

  end if;

  new.updated_at := now();

  return new;
end;
$$;


ALTER FUNCTION "public"."stamp_academic_progress_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stamp_learning_journal"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' then
    if new.attendance_record_id is distinct from old.attendance_record_id then
      raise exception 'Journal attendance cannot be changed';
    end if;
    new.created_at := old.created_at;
    -- Keep attribution on edits; allow FK cleanup when a user is deleted.
    if new.created_by is not null then new.created_by := old.created_by; end if;
  else
    new.created_by := auth.uid();
    new.created_at := now();
  end if;
  new.updated_by := auth.uid();
  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."stamp_learning_journal"() OWNER TO "postgres";


