    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin new.version:=old.version+1; new.updated_at:=now(); return new; end $$;


ALTER FUNCTION "public"."stamp_learning_report"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stamp_level_progress_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin

  if tg_op = 'INSERT'
     or new.status is distinct from old.status
  then

    if new.status = 'IN_PROGRESS' then
      new.started_at := coalesce(new.started_at, now());
    end if;

    if new.status = 'COMPLETED' then
      new.started_at := coalesce(new.started_at, now());
      new.completed_at := coalesce(new.completed_at, now());
    elsif tg_op = 'UPDATE'
          and old.status = 'COMPLETED'
          and new.status <> 'COMPLETED'
    then
      new.completed_at := null;
    end if;

  end if;

  new.updated_at := now();

  return new;
end;
$$;


ALTER FUNCTION "public"."stamp_level_progress_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_attendance_qr_session"("p_branch" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  today_vn date;
  current_session
    public.attendance_qr_sessions%rowtype;
begin
  if auth.uid() is null
     or not coalesce(
       public.account_is_active(),
       false
     )
  then
    raise exception 'QR_ATTENDANCE_UNAUTHORIZED';
  end if;

  if p_branch is null then
    raise exception 'QR_ATTENDANCE_BRANCH_REQUIRED';
  end if;

  if not (
    coalesce(
      public.is_global_super_admin(),
      false
    )
    or coalesce(
      public.has_permission(
        'attendance.manage',
        p_branch
      ),
      false
    )
  ) then
    raise exception 'QR_ATTENDANCE_MANAGE_DENIED';
  end if;

  if not exists (
    select 1
    from public.branches b
    where b.id = p_branch
      and b.status = 'ACTIVE'
  ) then
    raise exception 'QR_ATTENDANCE_BRANCH_INACTIVE';
  end if;

  today_vn :=
    (
      clock_timestamp()
      at time zone 'Asia/Ho_Chi_Minh'
    )::date;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'VIBE_QR_BRANCH:' || p_branch::text,
      0
    )
  );

  update public.attendance_qr_sessions
  set
    status = 'EXPIRED',
    stopped_at = clock_timestamp(),
    stop_reason = 'AUTO_EXPIRED_DATE'
  where branch_id = p_branch
    and status = 'ACTIVE'
    and work_date <> today_vn;

  select s.*
  into current_session
  from public.attendance_qr_sessions s
  where s.branch_id = p_branch
    and s.work_date = today_vn
    and s.status = 'ACTIVE'
  limit 1;

  if found then
    return jsonb_build_object(
      'status', 'ALREADY_ACTIVE',
      'session_id', current_session.id,
      'branch_id', current_session.branch_id,
      'work_date', current_session.work_date,
      'started_at', current_session.started_at
    );
  end if;

  insert into public.attendance_qr_sessions(
    branch_id,
    work_date,
    started_by
  )
  values(
    p_branch,
    today_vn,
    auth.uid()
  )
  returning *
  into current_session;

  return jsonb_build_object(
    'status', 'STARTED',
    'session_id', current_session.id,
    'branch_id', current_session.branch_id,
    'work_date', current_session.work_date,
    'started_at', current_session.started_at
  );
end;
$$;


ALTER FUNCTION "public"."start_attendance_qr_session"("p_branch" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_learning_assessment"("p_id" "uuid", "p_request" "uuid", "p_identity_confirmed" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare p public.learning_assessments; v public.learning_versions; learner uuid; prior public.learning_assessment_attempts; used integer; failed_at timestamptz; override uuid; delivered jsonb;
begin
 select * into p from public.learning_assessments where id=p_id and state='APPROVED';
 if not found then raise exception 'Assessment unavailable'; end if;
 select * into v from public.learning_versions where id=p.version_id and state='PUBLISHED';
 if not found then raise exception 'Learning content unavailable'; end if;
 learner:=public.learning_learner_for_level(v.level_id);
 if learner is null then raise exception 'Learning access denied or expired'; end if;
 if p_request is null or (p.kind='FINAL' and p_identity_confirmed is distinct from true) then raise exception 'Identity confirmation required'; end if;
 perform pg_advisory_xact_lock(hashtextextended('assessment:'||p_id::text||':'||learner::text,0));
 select * into prior from public.learning_assessment_attempts where id=p_request;
 if found then
 if prior.assessment_id is distinct from p_id or prior.student_id is distinct from learner then raise exception 'Assessment request mismatch'; end if;
 return prior.id;
 end if;
 if exists(select 1 from public.learning_assessment_attempts where assessment_id=p_id and student_id=learner and state in('IN_PROGRESS','PENDING_REVIEW')) then raise exception 'An assessment attempt is already active'; end if;
 select count(*),max(completed_at) filter(where state='FAILED') into used,failed_at from public.learning_effective_assessment_results where assessment_id=p_id and student_id=learner;
 if (p.attempt_limit is not null and used>=p.attempt_limit) or (failed_at is not null and failed_at+make_interval(secs=>p.cooldown_seconds)>clock_timestamp()) then
 select o.id into override from public.learning_assessment_overrides o where o.assessment_id=p_id and o.student_id=learner and o.valid_until>clock_timestamp() and (failed_at is null or o.created_at>=failed_at)
 and (select count(*) from public.learning_assessment_attempts a where a.override_id=o.id)<o.extra_attempts order by o.created_at,o.id limit 1 for update;
 if override is null then raise exception 'Assessment attempt limit or cooldown reached'; end if;
 end if;
 select jsonb_agg(jsonb_build_object('code',q->'code','type',q->'type','prompt',q->'prompt','options',case when jsonb_typeof(q->'options')='array' then (select jsonb_agg(o order by random()) from jsonb_array_elements(q->'options') o) else 'null'::jsonb end,'points',q->'points','mode',q->'mode') order by random()) into delivered from jsonb_array_elements(p.questions) q;
 insert into public.learning_assessment_attempts(id,assessment_id,student_id,override_id,policy_snapshot,question_snapshot,identity_confirmed)
 values(p_request,p_id,learner,override,jsonb_build_object('version_id',p.version_id,'kind',p.kind,'threshold',p.pass_threshold,'attempt_limit',p.attempt_limit,'cooldown_seconds',p.cooldown_seconds,'academic_mode','SHADOW'),delivered,coalesce(p_identity_confirmed,false));
 return p_request;
end$$;


ALTER FUNCTION "public"."start_learning_assessment"("p_id" "uuid", "p_request" "uuid", "p_identity_confirmed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_student_academic_level"("p_enrollment_id" "uuid", "p_level_id" "uuid", "p_started_at" "date" DEFAULT (("now"() AT TIME ZONE 'Asia/Ho_Chi_Minh'::"text"))::"date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_curriculum_id uuid;
  v_enrollment_status text;
  v_level_progress_id uuid;
  v_level_sequence integer;
begin

  if auth.uid() is not null
     and not public.has_role('SUPER_ADMIN')
  then
    raise exception
      'Only SUPER_ADMIN can start an academic level';
  end if;


  if p_enrollment_id is null
     or p_level_id is null
     or p_started_at is null
  then
    raise exception
      'Enrollment, level and start date are required';
  end if;


  select
    curriculum_id,
    status
  into
    v_curriculum_id,
    v_enrollment_status
  from public.student_curriculum_enrollments
  where id = p_enrollment_id
  for update;


  if v_curriculum_id is null then
    raise exception
      'Academic enrollment not found';
  end if;


  if v_enrollment_status <> 'ACTIVE' then
    raise exception
      'Academic enrollment must be ACTIVE';
  end if;


  if not exists (
    select 1
    from public.curriculums
    where id = v_curriculum_id
      and status = 'ACTIVE'
  ) then
    raise exception
      'Curriculum does not exist or is inactive';
  end if;


  select sequence_no
  into v_level_sequence
  from public.curriculum_levels
  where id = p_level_id
    and curriculum_id = v_curriculum_id
    and status = 'ACTIVE';


  if v_level_sequence is null then
    raise exception
      'Level does not belong to this active curriculum';
  end if;


  select id
  into v_level_progress_id
  from public.student_level_progress
  where enrollment_id = p_enrollment_id
    and level_id = p_level_id
    and status = 'AVAILABLE';


  if v_level_progress_id is null then
    raise exception
      'Academic level is not available to start';
  end if;


  if exists (
    select 1
    from public.student_level_progress
    where enrollment_id = p_enrollment_id
      and status = 'IN_PROGRESS'
      and id <> v_level_progress_id
  ) then
    raise exception
      'Another academic level is already in progress';
  end if;


  if not exists (
    select 1
    from public.curriculum_subjects
    where level_id = p_level_id
      and status = 'ACTIVE'
  ) then
    raise exception
      'Academic level has no active subjects';
  end if;


  -- Only grades that are actually part of this student's
  -- academic journey are prerequisites.
  if exists (
    select 1
    from public.student_level_progress previous_progress
    join public.curriculum_levels previous_level
      on previous_level.id = previous_progress.level_id
    where previous_progress.enrollment_id = p_enrollment_id
      and previous_level.curriculum_id = v_curriculum_id
      and previous_level.sequence_no < v_level_sequence
      and previous_progress.status <> 'COMPLETED'
  ) then
    raise exception
      'Previous academic levels in this student journey must be completed first';
  end if;


  if exists (
    select 1
    from public.curriculum_subjects s
    where s.level_id = p_level_id
      and s.status = 'ACTIVE'
      and s.is_required = true
      and s.completion_rule = 'ALL_REQUIRED_COMPONENTS'
      and not exists (
        select 1
        from public.curriculum_subject_components c
        where c.subject_id = s.id
          and c.status = 'ACTIVE'
          and c.is_required = true
      )
  ) then
    raise exception
      'A required subject has no required active components';
  end if;


  update public.student_level_progress
  set
    status = 'IN_PROGRESS',
    unlocked_at = coalesce(unlocked_at, now()),
    started_at =
      p_started_at::timestamp
      at time zone 'Asia/Ho_Chi_Minh',
    completed_at = null,
    updated_at = now()
  where id = v_level_progress_id;


  insert into public.student_subject_progress (
    level_progress_id,
    subject_id,
    status
  )
  select
    v_level_progress_id,
    cs.id,
    'NOT_STARTED'
  from public.curriculum_subjects cs
  where cs.level_id = p_level_id
    and cs.status = 'ACTIVE'
  on conflict (level_progress_id, subject_id)
  do nothing;


  insert into public.student_component_progress (
    subject_progress_id,
    component_id,
    status
  )
  select
    ssp.id,
    csc.id,
    'NOT_STARTED'
  from public.student_subject_progress ssp
  join public.curriculum_subjects cs
    on cs.id = ssp.subject_id
  join public.curriculum_subject_components csc
    on csc.subject_id = cs.id
   and csc.status = 'ACTIVE'
  where ssp.level_progress_id = v_level_progress_id
  on conflict (
    subject_progress_id,
    component_id
  )
  do nothing;


  update public.student_curriculum_enrollments
  set
    current_level_id = p_level_id,
    updated_at = now()
  where id = p_enrollment_id;


  return v_level_progress_id;

end;
$$;


