CREATE OR REPLACE FUNCTION "public"."submit_learning_assessment"("p_attempt" "uuid", "p_answers" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare a public.learning_assessment_attempts; p public.learning_assessments; level uuid; learner uuid; q jsonb; answer jsonb; points numeric; total numeric:=0; earned numeric:=0; pending boolean:=false; correct boolean; v_score numeric; v_evidence jsonb:='[]'; result text;
begin
 select * into a from public.learning_assessment_attempts where id=p_attempt for update;
 if not found then raise exception 'Assessment attempt unavailable'; end if;
 select * into p from public.learning_assessments where id=a.assessment_id;
 select level_id into level from public.learning_versions where id=p.version_id and state='PUBLISHED';
 learner:=public.learning_learner_for_level(level);
 if learner is null or learner<>a.student_id then raise exception 'Learning access denied or expired'; end if;
 if a.state<>'IN_PROGRESS' then
 if a.answers=p_answers then return; end if;
 raise exception 'Assessment submission is immutable';
 end if;
 if p_answers is null or jsonb_typeof(p_answers)<>'object' or octet_length(p_answers::text)>100000 then raise exception 'Invalid assessment answers'; end if;
 if exists(select 1 from jsonb_object_keys(p_answers) k where not exists(select 1 from jsonb_array_elements(p.questions) question where question->>'code'=k)) then raise exception 'Unknown question in submission'; end if;
 for q in select value from jsonb_array_elements(p.questions) loop
 points:=(q->>'points')::numeric;total:=total+points;answer:=p_answers->(q->>'code');correct:=false;
 if q->>'mode'<>'AUTO' then pending:=true;
 elsif q->>'type' in('SINGLE_CHOICE','TRUE_FALSE') then correct:=coalesce(answer=q->'key',false);
 elsif q->>'type'='MULTIPLE_CHOICE' and jsonb_typeof(answer)='array' then
 correct:=answer @> (q->'key') and (q->'key') @> answer and jsonb_array_length(answer)=jsonb_array_length(q->'key');
 end if;
 if correct then earned:=earned+points; end if;
 v_evidence:=v_evidence||jsonb_build_array(jsonb_build_object('code',q->>'code','mode',q->>'mode','points',case when q->>'mode'='AUTO' then case when correct then points else 0 end else null end,'max_points',points));
 end loop;
 v_score:=round(100*earned/total,4);result:=case when pending then 'PENDING_REVIEW' when v_score>=p.pass_threshold then 'PASSED' else 'FAILED' end;
 update public.learning_assessment_attempts set answers=p_answers,state=result,score=case when pending then null else v_score end,evidence=v_evidence,submitted_at=clock_timestamp(),completed_at=case when pending then null else clock_timestamp() end where id=p_attempt;
 if result='PASSED' and p.kind='FINAL' then insert into public.learning_academic_shadow(attempt_id,version_id,student_id,proposed_outcome) values(p_attempt,p.version_id,learner,'PASS') on conflict do nothing; end if;
end$$;


ALTER FUNCTION "public"."submit_learning_assessment"("p_attempt" "uuid", "p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_lesson_feedback"("p_session_id" "uuid", "p_student_id" "uuid", "p_respondent_type" "text", "p_overall" integer, "p_quality" integer DEFAULT NULL::integer, "p_communication" integer DEFAULT NULL::integer, "p_progress" integer DEFAULT NULL::integer, "p_comment" "text" DEFAULT ''::"text", "p_reasons" "text"[] DEFAULT '{}'::"text"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare c record; t record; result uuid; low boolean; allowed text[];
begin
 if not public.account_is_active() then raise exception 'Unauthorized'; end if;
 if p_respondent_type='STUDENT' then
   if not exists(select 1 from students where id=p_student_id and user_id=auth.uid() and status='ACTIVE') then raise exception 'Invalid respondent relationship'; end if;
 elsif p_respondent_type='PARENT' then
   if not exists(select 1 from parents p join student_parents sp on sp.parent_id=p.id where p.user_id=auth.uid() and p.status='ACTIVE' and sp.student_id=p_student_id and sp.is_active and (sp.valid_from is null or sp.valid_from<=now()) and (sp.valid_until is null or sp.valid_until>now())) then raise exception 'Invalid respondent relationship'; end if;
 else raise exception 'Invalid respondent type'; end if;
 if p_overall is null or p_overall not between 1 and 5 or p_quality not between 1 and 5 or p_communication not between 1 and 5 or p_progress not between 1 and 5 or p_comment is null or char_length(p_comment)>4000 then raise exception 'Invalid ratings or comment'; end if;
 if p_reasons is null then p_reasons := '{}'; end if;
 if p_overall<=2 then
   allowed := array['CONTENT_UNCLEAR','PACE_INAPPROPRIATE','TEACHER_SUPPORT_INSUFFICIENT','SESSION_TIMING_ISSUE','CONTENT_BELOW_EXPECTATION'];
 elsif p_overall>=4 then
   allowed := array['TEACHER_CLEAR_GUIDANCE','CONTENT_APPROPRIATE','TEACHER_SUPPORTIVE','SESSION_ON_TIME','OVERALL_SATISFIED'];
 else
   allowed := array[]::text[];
 end if;
 if exists (select 1 from unnest(p_reasons) code group by code having count(*)>1)
    or exists (select 1 from unnest(p_reasons) code where code <> all(allowed)) then
   raise exception 'Unsupported feedback reason';
 end if;
 select o.id,o.starts_at,o.ends_at,o.occurrence_date,sc.class_id,cl.name class_name,cl.branch_id,b.name branch_name,
   e.id enrollment_id,s.full_name student_name,s.student_code
 into c from session_occurrences o join schedules sc on sc.id=o.schedule_id join classes cl on cl.id=sc.class_id
 join branches b on b.id=cl.branch_id join enrollments e on e.class_id=cl.id and e.student_id=p_student_id
 join students s on s.id=e.student_id join attendance_records a on a.enrollment_id=e.id and a.session_occurrence_id=o.id
 where o.id=p_session_id and o.status='COMPLETED' and o.ends_at<=now() and a.status in ('PRESENT','LATE');
 if not found then raise exception 'Session is not eligible for feedback'; end if;
 if not public.has_role_permission(p_respondent_type,'feedback.submit',c.branch_id) then raise exception 'Unauthorized'; end if;
 select tr.id,tr.full_name,tr.teacher_code into t from session_actual_teachers v join teachers tr on tr.id=v.teacher_id where v.session_id=c.id;
 if not found then raise exception 'Session teacher is missing or ambiguous'; end if;
 low:=p_overall<=lesson_feedback_low_threshold();
 insert into lesson_feedback(session_occurrence_id,enrollment_id,student_id,respondent_user_id,respondent_type,teacher_id,branch_id,session_starts_at,
 context_snapshot,overall_rating,lesson_quality_rating,teacher_communication_rating,progress_perception_rating,comment,is_low_rating,resolution_status)
 values(c.id,c.enrollment_id,p_student_id,auth.uid(),p_respondent_type,t.id,c.branch_id,c.starts_at,
 jsonb_build_object('student_name',c.student_name,'student_code',c.student_code,'teacher_name',coalesce(t.full_name,t.teacher_code),'branch_name',c.branch_name,'class_name',c.class_name,
 'respondent_name',(select full_name from profiles where id=auth.uid()),'teacher_basis','ACTUAL_SESSION_TEACHER'),
 p_overall,p_quality,p_communication,p_progress,btrim(p_comment),low,case when low then 'NEEDS_REVIEW' else 'NORMAL' end) returning id into result;
 insert into lesson_feedback_reasons(feedback_id, reason_code, reason_label)
 select result, code, case code
   when 'TEACHER_CLEAR_GUIDANCE' then 'Giảng viên hướng dẫn dễ hiểu'
   when 'CONTENT_APPROPRIATE' then 'Nội dung buổi học phù hợp'
   when 'TEACHER_SUPPORTIVE' then 'Giảng viên tận tâm và hỗ trợ tốt'
   when 'SESSION_ON_TIME' then 'Buổi học diễn ra đúng giờ, đúng kế hoạch'
   when 'OVERALL_SATISFIED' then 'Tôi hài lòng với buổi học hôm nay'
   when 'CONTENT_UNCLEAR' then 'Nội dung buổi học chưa dễ hiểu'
   when 'PACE_INAPPROPRIATE' then 'Tiến độ buổi học chưa phù hợp'
   when 'TEACHER_SUPPORT_INSUFFICIENT' then 'Tôi chưa nhận được đủ sự hỗ trợ từ giảng viên'
   when 'SESSION_TIMING_ISSUE' then 'Buổi học chưa diễn ra đúng giờ hoặc đúng kế hoạch'
   when 'CONTENT_BELOW_EXPECTATION' then 'Nội dung buổi học chưa đúng kỳ vọng'
 end
 from unnest(p_reasons) as code;
 return result;
end $$;


ALTER FUNCTION "public"."submit_lesson_feedback"("p_session_id" "uuid", "p_student_id" "uuid", "p_respondent_type" "text", "p_overall" integer, "p_quality" integer, "p_communication" integer, "p_progress" integer, "p_comment" "text", "p_reasons" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_payroll_retroactive_claim"("p_claim" "uuid", "p_version" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  c public.payroll_retroactive_claims%rowtype;
begin
  select r.*
  into c
  from public.payroll_retroactive_claims r
  where r.id = p_claim
    and public.has_permission(
      'payroll.prepare',
      r.branch_id
    )
    and (
      public.is_global_super_admin()
      or public.has_role_permission(
        'FINANCE',
        'payroll.prepare',
        r.branch_id
      )
    )
  for update;

  if not found then
    raise exception 'RETROACTIVE_UNAUTHORIZED';
  end if;

  if c.version is distinct from p_version then
    raise exception
      'RETROACTIVE_CHANGED_RELOAD';
  end if;

  if c.status <> 'DRAFT' then
    raise exception
      'RETROACTIVE_REQUIRES_DRAFT';
  end if;

  update public.payroll_retroactive_claims
  set
    status = 'REVIEW',
    version = version + 1,
    submitted_by = auth.uid(),
    submitted_at = clock_timestamp()
  where id = c.id;

  return jsonb_build_object(
    'status','REVIEW',
    'claim_id',c.id
  );
end;
$$;


ALTER FUNCTION "public"."submit_payroll_retroactive_claim"("p_claim" "uuid", "p_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_session_learning_journal"("p_session" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor uuid := auth.uid();
  journal public.session_learning_journals%rowtype;
begin
  if actor is null or not public.can_write_session_journal(p_session) then raise exception 'JOURNAL_UNAUTHORIZED'; end if;
  if not exists(select 1 from session_occurrences where id=p_session and status='COMPLETED') then raise exception 'JOURNAL_SESSION_NOT_COMPLETED'; end if;
  select * into journal from public.session_learning_journals where session_occurrence_id = p_session for update;
  if not found then raise exception 'JOURNAL_SESSION_MISSING'; end if;
  if nullif(btrim(journal.content_covered), '') is null then raise exception 'JOURNAL_CONTENT_REQUIRED'; end if;
  if exists(
    select 1
    from public.attendance_records attendance
    left join public.student_learning_journal_entries entry on entry.attendance_record_id = attendance.id
    where attendance.session_occurrence_id = p_session
      and attendance.status in ('PRESENT','LATE')
      and (entry.id is null or nullif(btrim(entry.progress_note), '') is null or entry.observation = 'NOT_RECORDED')
  ) then
    raise exception 'JOURNAL_PROGRESS_REQUIRED';
  end if;
  perform set_config('journal.taxonomy_write', 'on', true);
  update public.session_learning_journals set
    status = 'SUBMITTED',
    submitted_at = coalesce(submitted_at, clock_timestamp()),
    submitted_by = coalesce(submitted_by, actor),
    version = version + 1,
    updated_at = clock_timestamp()
  where id = journal.id;
  perform set_config('journal.taxonomy_write', 'off', true);
  return journal.id;
end $$;


ALTER FUNCTION "public"."submit_session_learning_journal"("p_session" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_component_progress_from_items"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_component_progress_id uuid;
  v_component_id uuid;
  v_completion_rule text;

  v_total integer;
  v_not_started integer;
  v_in_progress integer;
  v_completed integer;
  v_legacy_failed integer;

  v_new_status text;
begin

  if tg_op = 'DELETE' then
    v_component_progress_id := old.component_progress_id;
  else
    v_component_progress_id := new.component_progress_id;
  end if;


  select
    scp.component_id,
    csc.completion_rule
  into
    v_component_id,
    v_completion_rule
  from public.student_component_progress scp
  join public.curriculum_subject_components csc
    on csc.id = scp.component_id
  where scp.id = v_component_progress_id;


  -- Direct-assessment components are managed directly.
  if v_completion_rule is distinct from 'ALL_REQUIRED_ITEMS' then
    if tg_op = 'DELETE' then
      return old;
    else
      return new;
    end if;
  end if;


  -- Count ACTIVE + REQUIRED curriculum items.
  -- Missing student progress counts as NOT_STARTED.
  select
    count(*)::integer,

    count(*) filter (
      where coalesce(scip.status, 'NOT_STARTED') = 'NOT_STARTED'
    )::integer,

    count(*) filter (
      where scip.status = 'IN_PROGRESS'
    )::integer,

    count(*) filter (
      where scip.status in (
        'PASS',
        'MERIT',
        'DISTINCTION',
        'EXEMPT'
      )
    )::integer,

    count(*) filter (
      where scip.status = 'NOT_PASSED'
    )::integer

  into
    v_total,
    v_not_started,
    v_in_progress,
    v_completed,
    v_legacy_failed

  from public.curriculum_component_items item

  left join public.student_component_item_progress scip
    on scip.item_id = item.id
   and scip.component_progress_id = v_component_progress_id

  where item.component_id = v_component_id
    and item.status = 'ACTIVE'
    and item.is_required = true;


  -- ALL_REQUIRED_ITEMS must actually have required active items.
  if v_total = 0 then
    if tg_op = 'DELETE' then
      return old;
    else
      return new;
    end if;
  end if;


  -- All required items untouched.
  if v_not_started = v_total then
    v_new_status := 'NOT_STARTED';

  -- All required items completed successfully.
  elsif v_completed = v_total then
    v_new_status := 'PASS';

  -- Legacy final failure remains representable.
  elsif v_legacy_failed > 0
    and (v_completed + v_legacy_failed) = v_total
  then
    v_new_status := 'NOT_PASSED';

  -- Any mixed/active state.
  else
    v_new_status := 'IN_PROGRESS';

  end if;


  update public.student_component_progress
  set
    status = v_new_status,

    started_at =
      case
        when v_new_status = 'NOT_STARTED'
          then started_at
        else coalesce(started_at, now())
      end,

    passed_at =
      case
        when v_new_status = 'PASS'
          then coalesce(passed_at, now())
        else null
      end,

    updated_at = now()

  where id = v_component_progress_id;


  if tg_op = 'DELETE' then
    return old;
  else
    return new;
  end if;

end;
$$;


ALTER FUNCTION "public"."sync_component_progress_from_items"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_enrollment_tuition_from_pause"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_tuition record;
begin
  for v_tuition in
    select tuition.id
    from public.enrollment_tuition as tuition
    where tuition.enrollment_id =
        new.enrollment_id
      and tuition.status <> 'CANCELLED'
    order by
      tuition.starts_on,
      tuition.id
    for update
  loop
    perform
      public.recalculate_enrollment_tuition_effective_end(
        v_tuition.id
      );
  end loop;


  return new;
end;
$$;


ALTER FUNCTION "public"."sync_enrollment_tuition_from_pause"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_feedback_conversation_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
 if new.kind='FEEDBACK' and new.state is distinct from old.state then
  update lesson_feedback set resolution_status=case when new.state='RESOLVED' then 'RESOLVED' else 'IN_REVIEW' end,
   resolved_at=case when new.state='RESOLVED' then clock_timestamp() end,
   resolved_by=case when new.state='RESOLVED' then auth.uid() end
  where id=new.entity_id;
  insert into lesson_feedback_events(feedback_id,status,note,actor_id)
  values(new.entity_id,case when new.state='RESOLVED' then 'RESOLVED' else 'IN_REVIEW' end,'Trạng thái cập nhật từ trao đổi công khai; xem lịch sử trao đổi.',auth.uid());
 end if;
 return new;
end$$;


ALTER FUNCTION "public"."sync_feedback_conversation_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_level_progress_from_subjects"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_level_progress_id uuid;
  v_level_id uuid;
  v_completion_rule text;

  v_total integer;
  v_completed integer;
  v_started integer;

  v_current_status text;
  v_new_status text;
begin

  if tg_op = 'DELETE' then
    v_level_progress_id := old.level_progress_id;
  else
    v_level_progress_id := new.level_progress_id;
  end if;


  select
    slp.level_id,
    cl.completion_rule,
    slp.status
  into
    v_level_id,
    v_completion_rule,
    v_current_status
  from public.student_level_progress slp
  join public.curriculum_levels cl
    on cl.id = slp.level_id
  where slp.id = v_level_progress_id;


  -- Manual levels are not automatically completed.
  if v_completion_rule is distinct from 'ALL_REQUIRED_SUBJECTS' then
    if tg_op = 'DELETE' then
      return old;
    else
      return new;
    end if;
  end if;


  select
    count(*)::integer,

    count(*) filter (
      where ssp.status in ('PASS', 'MERIT', 'DISTINCTION', 'EXEMPT')
    )::integer,

    count(*) filter (
      where ssp.status <> 'NOT_STARTED'
    )::integer

  into
    v_total,
    v_completed,
    v_started

  from public.curriculum_subjects cs
  left join public.student_subject_progress ssp
    on ssp.subject_id = cs.id and ssp.level_progress_id = v_level_progress_id
  where cs.level_id = v_level_id
    and cs.is_required = true
    and cs.status = 'ACTIVE';


  -- No required subjects = do not auto-complete.
  if v_total = 0 then
    if tg_op = 'DELETE' then
      return old;
    else
      return new;
    end if;
  end if;


  if v_completed = v_total then

    v_new_status := 'COMPLETED';

  elsif v_started > 0 then

    v_new_status := 'IN_PROGRESS';

  elsif v_current_status in ('IN_PROGRESS', 'COMPLETED') then

    v_new_status := 'IN_PROGRESS';

  else

    if tg_op = 'DELETE' then
      return old;
    else
      return new;
    end if;

  end if;


  update public.student_level_progress
  set status = v_new_status
  where id = v_level_progress_id
    and status is distinct from v_new_status;


  if tg_op = 'DELETE' then
    return old;
  else
    return new;
  end if;

end;
$$;


ALTER FUNCTION "public"."sync_level_progress_from_subjects"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_makeup_credits_from_session_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.status = old.status then
    return new;
  end if;

  if new.occurrence_type = 'REGULAR' and new.status = 'COMPLETED' then
    insert into public.makeup_credits (enrollment_id, source_occurrence_id, source_attendance_record_id, source_reason, status)
    select attendance.enrollment_id, new.id, attendance.id, 'EXCUSED', 'AVAILABLE'
    from public.attendance_records attendance
    where attendance.session_occurrence_id = new.id
      and attendance.status = 'EXCUSED'
      and not public.is_enrollment_paused_on(attendance.enrollment_id, new.occurrence_date)
    on conflict (source_occurrence_id, enrollment_id) do update
    set source_attendance_record_id = excluded.source_attendance_record_id,
      source_reason = 'EXCUSED', status = 'AVAILABLE',
      reserved_occurrence_id = null, reserved_at = null, used_at = null, cancelled_at = null
    where public.makeup_credits.status in ('AVAILABLE', 'CANCELLED');
    return new;
  end if;

  if new.occurrence_type = 'REGULAR' and new.status = 'CANCELLED' then
    insert into public.makeup_credits (enrollment_id, source_occurrence_id, source_attendance_record_id, source_reason, status)
    select enrollment.id, new.id, null, 'SESSION_CANCELLED', 'AVAILABLE'
    from public.schedules schedule
    join public.enrollments enrollment on enrollment.class_id = schedule.class_id
    where schedule.id = new.schedule_id
      and coalesce(enrollment.started_at, enrollment.enrolled_at) <= new.occurrence_date
      and (enrollment.ended_at is null or enrollment.ended_at >= new.occurrence_date)
      and not public.is_enrollment_paused_on(enrollment.id, new.occurrence_date)
    on conflict (source_occurrence_id, enrollment_id) do update
    set source_attendance_record_id = null, source_reason = 'SESSION_CANCELLED', status = 'AVAILABLE',
      reserved_occurrence_id = null, reserved_at = null, used_at = null, cancelled_at = null
    where public.makeup_credits.status in ('AVAILABLE', 'CANCELLED');
    return new;
  end if;

  if new.occurrence_type = 'REGULAR' and new.status = 'SCHEDULED' and old.status in ('COMPLETED', 'CANCELLED') then
    update public.makeup_credits
    set status = 'CANCELLED', reserved_occurrence_id = null, reserved_at = null, used_at = null, cancelled_at = now()
    where source_occurrence_id = new.id and status = 'AVAILABLE';
    return new;
  end if;

  if new.occurrence_type = 'MAKEUP' and new.status = 'COMPLETED' then
    update public.makeup_credits credit
    set status = 'USED', used_at = coalesce(credit.used_at, now())
    where credit.reserved_occurrence_id = new.id and credit.status = 'RESERVED'
      and exists (
        select 1 from public.attendance_records attendance
        where attendance.session_occurrence_id = new.id
          and attendance.enrollment_id = credit.enrollment_id
          and attendance.status = 'PRESENT'
      );
    insert into public.academic_operation_exceptions (kind, enrollment_id, source_id, note, payload)
    select 'MAKEUP_COMPLETED_WITHOUT_PRESENT', credit.enrollment_id, credit.id,
      'Buổi bù đã chốt nhưng chưa có điểm danh có mặt. Quyền vẫn là đã đặt, không tự thu và không tự xóa.',
      jsonb_build_object('occurrence_id', new.id)
    from public.makeup_credits credit
    where credit.reserved_occurrence_id = new.id and credit.status = 'RESERVED'
      and not exists (
        select 1 from public.academic_operation_exceptions existing
        where existing.kind = 'MAKEUP_COMPLETED_WITHOUT_PRESENT' and existing.source_id = credit.id
      );
    return new;
  end if;

  if new.occurrence_type = 'MAKEUP' and new.status = 'CANCELLED' then
    update public.makeup_credits
    set status = 'AVAILABLE', reserved_occurrence_id = null, reserved_at = null, used_at = null, cancelled_at = null
    where reserved_occurrence_id = new.id and status = 'RESERVED';
    return new;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_makeup_credits_from_session_status"() OWNER TO "postgres";


