CREATE OR REPLACE FUNCTION "public"."sync_retroactive_claim_action_cancel"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  if old.source_type = 'RETROACTIVE_PAY'
     and old.status = 'ACTIVE'
     and new.status = 'CANCELLED'
     and old.source_retroactive_claim_id
         is not null
  then
    update public.payroll_retroactive_claims
    set
      status = 'APPROVED',
      version = version + 1,
      posted_by = null,
      posted_at = null,
      posted_action_id = null
    where id =
      old.source_retroactive_claim_id
      and status = 'POSTED';
  end if;

  return new;
end;
$$;


