CREATE OR REPLACE FUNCTION "public"."sync_subject_progress_from_components"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_subject_progress_id uuid;
  v_subject_id uuid;
  v_completion_rule text;

  v_total integer;
  v_not_started integer;
  v_pass integer;
  v_not_passed integer;
  v_exempt integer;

  v_new_status text;
begin

  if tg_op = 'DELETE' then
    v_subject_progress_id := old.subject_progress_id;
  else
    v_subject_progress_id := new.subject_progress_id;
  end if;


  select
    ssp.subject_id,
    cs.completion_rule
  into
    v_subject_id,
    v_completion_rule
  from public.student_subject_progress ssp
  join public.curriculum_subjects cs
    on cs.id = ssp.subject_id
  where ssp.id = v_subject_progress_id;


  -- Direct Assessment / Manual subjects
  -- are not calculated from components.
  if v_completion_rule is distinct from 'ALL_REQUIRED_COMPONENTS' then
    if tg_op = 'DELETE' then
      return old;
    else
      return new;
    end if;
  end if;


  select
    count(*)::integer,

    count(*) filter (
      where coalesce(scp.status, 'NOT_STARTED') = 'NOT_STARTED'
    )::integer,

    count(*) filter (
      where scp.status in ('PASS', 'MERIT', 'DISTINCTION')
    )::integer,

    count(*) filter (
      where scp.status = 'NOT_PASSED'
    )::integer,

    count(*) filter (
      where scp.status = 'EXEMPT'
    )::integer

  into
    v_total,
    v_not_started,
    v_pass,
    v_not_passed,
    v_exempt

  from public.curriculum_subject_components csc
  left join public.student_component_progress scp
    on scp.component_id = csc.id and scp.subject_progress_id = v_subject_progress_id
  where csc.subject_id = v_subject_id
    and csc.is_required = true
    and csc.status = 'ACTIVE';


  -- No required components = do not auto-complete.
  if v_total = 0 then
    if tg_op = 'DELETE' then
      return old;
    else
      return new;
    end if;
  end if;


  if v_not_started = v_total then

    v_new_status := 'NOT_STARTED';

  elsif (v_pass + v_exempt) = v_total then

    v_new_status := 'PASS';

  elsif
    v_not_passed > 0
    and (v_pass + v_exempt + v_not_passed) = v_total
  then

    v_new_status := 'NOT_PASSED';

  else

    v_new_status := 'IN_PROGRESS';

  end if;


  update public.student_subject_progress
  set status = v_new_status
  where id = v_subject_progress_id
    and status is distinct from v_new_status;


  if tg_op = 'DELETE' then
    return old;
  else
    return new;
  end if;

end;
$$;


ALTER FUNCTION "public"."sync_subject_progress_from_components"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_teacher_payroll_v2_totals"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  line_earnings numeric(16,2) := 0;
  line_reimbursements numeric(16,2) := 0;
  line_deductions numeric(16,2) := 0;
  action_earnings numeric(16,2) := 0;
  action_reimbursements numeric(16,2) := 0;
begin
  if new.calculation_version like 'PAYROLL_V2%' then
    select
      coalesce(sum(l.amount) filter(where l.category='EARNING'),0),
      coalesce(sum(l.amount) filter(where l.category='REIMBURSEMENT'),0),
      coalesce(sum(l.amount) filter(where l.category='DEDUCTION'),0)
    into
      line_earnings,
      line_reimbursements,
      line_deductions
    from public.payroll_component_lines_v2 l
    where l.payroll_id=new.id;

    select
      coalesce(sum(a.amount) filter(where a.category='EARNING'),0),
      coalesce(sum(a.amount) filter(where a.category='REIMBURSEMENT'),0)
    into
      action_earnings,
      action_reimbursements
    from public.payroll_period_actions_v2 a
    where a.period_id=new.period_id
      and a.employee_id=new.employee_id
      and a.status='ACTIVE';

    new.v2_earnings_amount :=
      line_earnings + action_earnings;

    new.v2_reimbursement_amount :=
      line_reimbursements + action_reimbursements;

    new.v2_deduction_amount :=
      line_deductions;

    new.v2_net_amount :=
      new.v2_earnings_amount
      + new.v2_reimbursement_amount
      - new.v2_deduction_amount
      + coalesce(new.adjustment_amount,0);

    -- Compatibility for current summary UI.
    new.gross_amount := new.v2_net_amount;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_teacher_payroll_v2_totals"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_assigned_to_session"("p_session" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select public.has_role('TEACHER') and exists(select 1 from public.session_actual_teachers v
 join public.teachers t on t.id=v.teacher_id
 where v.session_id=p_session and t.user_id=auth.uid() and t.status='ACTIVE'
 and public.has_role_permission('TEACHER','attendance.view',v.branch_id)
 and (v.is_locked or exists(select 1 from public.session_teacher_assignments a where a.session_id=v.session_id and a.teacher_id=t.id and a.effective_status='ACTIVE')
 or public.teacher_can_access_class(v.class_id)))
$$;


ALTER FUNCTION "public"."teacher_assigned_to_session"("p_session" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_can_access_class"("p_class" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select public.has_role('TEACHER') and exists(select 1 from public.teachers t
 join public.class_teachers ct on ct.teacher_id=t.id join public.classes c on c.id=ct.class_id
 where t.user_id=auth.uid() and t.status='ACTIVE' and ct.class_id=p_class and ct.is_active and c.status='ACTIVE'
 and ct.assigned_at <= (now() at time zone 'Asia/Ho_Chi_Minh')::date
 and (ct.ended_at is null or ct.ended_at >= (now() at time zone 'Asia/Ho_Chi_Minh')::date)
 and (c.start_date is null or c.start_date <= (now() at time zone 'Asia/Ho_Chi_Minh')::date)
 and (c.end_date is null or c.end_date >= (now() at time zone 'Asia/Ho_Chi_Minh')::date)
 and public.has_role_permission('TEACHER','classes.view',c.branch_id))
$$;


ALTER FUNCTION "public"."teacher_can_access_class"("p_class" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_can_access_session"("p_session" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select public.has_role('TEACHER') and exists(select 1 from public.session_actual_teachers v
 join public.teachers t on t.id=v.teacher_id
 where v.session_id=p_session and v.status in ('SCHEDULED','COMPLETED') and t.user_id=auth.uid() and t.status='ACTIVE'
 and public.has_role_permission('TEACHER','attendance.view',v.branch_id)
 and (v.is_locked or exists(select 1 from public.session_teacher_assignments a where a.session_id=v.session_id and a.teacher_id=t.id and a.effective_status='ACTIVE')
 or public.teacher_can_access_class(v.class_id)))
$$;


ALTER FUNCTION "public"."teacher_can_access_session"("p_session" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_can_access_student"("p_student" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select public.has_role('TEACHER') and exists(select 1 from public.enrollments e join public.classes c on c.id=e.class_id
 where e.student_id=p_student and public.has_role_permission('TEACHER','students.view_related',c.branch_id) and (
 (public.teacher_can_access_class(c.id) and e.status='ACTIVE' and not public.is_enrollment_paused_on(e.id,(now() at time zone 'Asia/Ho_Chi_Minh')::date) and e.started_at <= (now() at time zone 'Asia/Ho_Chi_Minh')::date
 and (e.ended_at is null or e.ended_at >= (now() at time zone 'Asia/Ho_Chi_Minh')::date))
 or exists(select 1 from public.session_occurrences o join public.schedules sc on sc.id=o.schedule_id
 where sc.class_id=c.id and public.teacher_can_access_session(o.id) and o.status='SCHEDULED' and e.status='ACTIVE'
 and e.started_at<=o.occurrence_date and (e.ended_at is null or e.ended_at>=o.occurrence_date)
 and ((o.occurrence_type='REGULAR' and not public.is_enrollment_paused_on(e.id,o.occurrence_date)) or exists(select 1 from public.session_occurrence_participants sp where sp.session_occurrence_id=o.id and sp.enrollment_id=e.id)))))
$$;


