CREATE OR REPLACE FUNCTION "public"."teacher_portal_attendance"("p_session" "uuid", "p_offset" integer DEFAULT 0) RETURNS TABLE("attendance_id" "uuid", "student_name" "text", "status" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
