CREATE OR REPLACE FUNCTION "public"."teacher_portal_sessions"("p_history" boolean DEFAULT false, "p_offset" integer DEFAULT 0) RETURNS TABLE("session_id" "uuid", "class_name" "text", "starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "status" "text", "room_name" "text", "roster_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select o.id, c.name, o.starts_at, o.ends_at, o.status, r.name,
  (select count(*)::integer from public.session_teaching_roster(o.id))
 from session_occurrences o
 join schedules s on s.id=o.schedule_id
 join classes c on c.id=s.class_id
 join session_actual_teachers a on a.session_id=o.id
 join teachers t on t.id=a.teacher_id
 left join rooms r on r.id=o.room_id
 where t.user_id=auth.uid() and t.status='ACTIVE' and public.teacher_can_access_session(o.id)
 and ((p_history and o.status='COMPLETED') or (not p_history and o.status='SCHEDULED' and o.ends_at>=now()))
 order by case when p_history then o.starts_at end desc, case when not p_history then o.starts_at end, o.id
 limit 26 offset greatest(0, least(coalesce(p_offset, 0), 100000))
$$;


ALTER FUNCTION "public"."teacher_portal_sessions"("p_history" boolean, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_session_workspace"("p_session" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare result jsonb;
begin
 if auth.uid() is null or not coalesce(public.account_is_active(),false) or not
   (public.has_role('SUPER_ADMIN') or public.teacher_can_access_session(p_session) or public.teacher_assigned_to_session(p_session)) then raise exception 'TEACHING_UNAUTHORIZED'; end if;
 select jsonb_build_object(
  'id',o.id,'class_id',c.id,'class_name',c.name,'date',o.occurrence_date,'starts_at',o.starts_at,'ends_at',o.ends_at,
  'status',o.status,'type',o.occurrence_type,'room',r.name,'teacher',t.full_name,'assignment_type',actual.assignment_type,
  'scope_from',lf.name,'scope_to',lt.name,'note',o.notes,
  'journal',(select jsonb_build_object('id',j.id,'content_covered',j.content_covered,'curriculum_context',j.curriculum_context,
    'status',j.status,'version',j.version,'submitted_at',j.submitted_at,'submitted_by',j.submitted_by,
    'revision_count',j.revision_count,'revised_at',j.revised_at,'revised_by',j.revised_by)
    from session_learning_journals j where j.session_occurrence_id=o.id),
  'participants',coalesce((select jsonb_agg(jsonb_build_object(
    'enrollment_id',rr.enrollment_id,'student_id',rr.student_id,'name',st.full_name,
    'attendance_id',a.id,'attendance',a.status,'compatibility',public.class_enrollment_compatibility(c.id,rr.student_id),
    'academic',case when public.has_role('SUPER_ADMIN') or public.teacher_can_read_student_academic(rr.student_id)
       then public.session_teaching_academic(current_academic.student_curriculum_enrollment_id) else null end,
    'academic_readable',public.has_role('SUPER_ADMIN') or public.teacher_can_read_student_academic(rr.student_id),
    'entry',(select (to_jsonb(entry)-'internal_note') || jsonb_build_object('codes',coalesce((
      select jsonb_agg(sel.option_code order by sel.option_code) from student_journal_observation_selections sel where sel.entry_id=entry.id),'[]'::jsonb))
      from student_learning_journal_entries entry where entry.attendance_record_id=a.id)
   ) order by st.full_name,rr.enrollment_id)
   from public.session_teaching_roster(o.id) rr join students st on st.id=rr.student_id
   left join attendance_records a on a.session_occurrence_id=o.id and a.enrollment_id=rr.enrollment_id
   left join lateral public.class_student_current_level(c.id,rr.student_id) current_academic on true),'[]'::jsonb),
  'options',jsonb_build_object(
    'observations',(select coalesce(jsonb_agg(to_jsonb(x) order by x.sort_order),'[]'::jsonb) from learning_observation_options x where active),
    'focus',(select coalesce(jsonb_agg(to_jsonb(x) order by x.sort_order),'[]'::jsonb) from learning_focus_options x where active),
    'reasons',(select coalesce(jsonb_agg(to_jsonb(x) order by x.sort_order),'[]'::jsonb) from learning_attention_reasons x where active),
    'homework',(select coalesce(jsonb_agg(to_jsonb(x) order by x.sort_order),'[]'::jsonb) from learning_homework_parts x where active))
 ) into result
 from session_occurrences o join schedules sc on sc.id=o.schedule_id join classes c on c.id=sc.class_id
 left join rooms r on r.id=o.room_id left join session_actual_teachers actual on actual.session_id=o.id
 left join teachers t on t.id=actual.teacher_id
 left join curriculum_levels lf on lf.id=c.accepted_from_level_id left join curriculum_levels lt on lt.id=c.accepted_to_level_id
 where o.id=p_session;
 if result is null then raise exception 'TEACHING_SESSION_MISSING'; end if;
 return result;
end $$;


ALTER FUNCTION "public"."teacher_session_workspace"("p_session" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_session_write"("p_session" "uuid", "p_action" "text", "p_enrollment" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
 o public.session_occurrences%rowtype; student uuid; class_id uuid; attendance public.attendance_records%rowtype;
 journal public.session_learning_journals%rowtype; entry public.student_learning_journal_entries%rowtype;
 level_progress uuid; progress uuid; kind text; next_status text; old_status text; structure record;
begin
 if auth.uid() is null or not coalesce(public.account_is_active(),false) then raise exception 'TEACHING_UNAUTHORIZED'; end if;
 -- Lock session before checking assignment so completion, reassignment and lane writes serialize.
 select * into o from session_occurrences where id=p_session for update;
 if not found then raise exception 'TEACHING_SESSION_MISSING'; end if;
 if o.status='CANCELLED' then
  if not (public.has_role('SUPER_ADMIN') or public.teacher_assigned_to_session(p_session)) then raise exception 'TEACHING_UNAUTHORIZED'; end if;
  raise exception 'TEACHING_CANCELLED';
 end if;
 if not (public.has_role('SUPER_ADMIN') or public.teacher_can_access_session(p_session)) then raise exception 'TEACHING_UNAUTHORIZED'; end if;
 select sc.class_id into class_id from schedules sc where sc.id=o.schedule_id;
 if p_action in ('attendance','progress','journal') then
  select rr.student_id into student from public.session_teaching_roster(p_session) rr where rr.enrollment_id=p_enrollment;
  if student is null then raise exception 'TEACHING_PARTICIPANT_DENIED'; end if;
  select * into attendance from attendance_records where session_occurrence_id=p_session and enrollment_id=p_enrollment for update;
 end if;
 if p_action='attendance' then
  if p_payload->>'status' is null or p_payload->>'status' not in ('PRESENT','ABSENT','LATE','EXCUSED') then raise exception 'TEACHING_STATUS_INVALID'; end if;
  -- Do not silently invalidate an existing qualitative entry when correcting attendance.
  if p_payload->>'status' in ('ABSENT','EXCUSED') and exists(select 1 from student_learning_journal_entries e where e.attendance_record_id=attendance.id
    and (e.observation<>'NOT_RECORDED' or nullif(btrim(e.progress_note),'') is not null)) then raise exception 'TEACHING_ATTENDANCE_HAS_FEEDBACK'; end if;
  insert into attendance_records(session_occurrence_id,enrollment_id,status,marked_at,marked_by)
  values(p_session,p_enrollment,p_payload->>'status',clock_timestamp(),auth.uid())
  on conflict(session_occurrence_id,enrollment_id) do update set status=excluded.status,marked_at=excluded.marked_at,marked_by=excluded.marked_by;
 elsif p_action='progress' then
  if attendance.status is null or attendance.status not in ('PRESENT','LATE') then raise exception 'TEACHING_ATTENDANCE_REQUIRED'; end if;
  if not (public.has_role('SUPER_ADMIN') or public.teacher_can_read_student_academic(student)) then raise exception 'TEACHING_ACADEMIC_DENIED'; end if;
  progress := (p_payload->>'progress_id')::uuid; kind := p_payload->>'kind'; next_status := p_payload->>'status';
  if next_status is null or next_status not in ('NOT_STARTED','IN_PROGRESS','PASS','MERIT','DISTINCTION') then raise exception 'TEACHING_STATUS_INVALID'; end if;
  select lp.id into level_progress from public.class_student_current_level(class_id,student) current_academic
  join student_level_progress lp on lp.enrollment_id=current_academic.student_curriculum_enrollment_id and lp.level_id=current_academic.current_level_id
  join curriculum_levels l on l.id=lp.level_id join curriculums cur on cur.id=l.curriculum_id
  where l.status='ACTIVE' and cur.status='ACTIVE' for update of lp;
  if level_progress is null then raise exception 'TEACHING_ACADEMIC_MISSING'; end if;
  if exists(select 1 from student_level_progress where id=level_progress and (started_at is null or started_at>now())) then raise exception 'TEACHING_FUTURE_LEVEL'; end if;
  if kind='subject' then
   select sp.status,s.completion_rule into structure from student_subject_progress sp join curriculum_subjects s on s.id=sp.subject_id
   where sp.id=progress and sp.level_progress_id=level_progress and s.level_id=(select level_id from student_level_progress where id=level_progress) and s.status='ACTIVE';
   if not found or structure.completion_rule not in ('DIRECT_ASSESSMENT','MANUAL') then raise exception 'TEACHING_PROGRESS_DENIED'; end if;
   old_status:=structure.status;
  elsif kind='component' then
   select cp.status,c.completion_rule into structure from student_component_progress cp
   join student_subject_progress sp on sp.id=cp.subject_progress_id join curriculum_subject_components c on c.id=cp.component_id and c.subject_id=sp.subject_id
   join curriculum_subjects s on s.id=sp.subject_id
   where cp.id=progress and sp.level_progress_id=level_progress and s.status='ACTIVE' and c.status='ACTIVE';
   if not found or structure.completion_rule<>'DIRECT_ASSESSMENT' then raise exception 'TEACHING_PROGRESS_DENIED'; end if;
   old_status:=structure.status;
  elsif kind='item' then
   select ip.status into old_status from student_component_item_progress ip
   join student_component_progress cp on cp.id=ip.component_progress_id
   join student_subject_progress sp on sp.id=cp.subject_progress_id
   join curriculum_component_items i on i.id=ip.item_id and i.component_id=cp.component_id
   join curriculum_subject_components c on c.id=cp.component_id and c.subject_id=sp.subject_id
   join curriculum_subjects s on s.id=sp.subject_id
   where ip.id=progress and sp.level_progress_id=level_progress and i.status='ACTIVE' and c.status='ACTIVE' and s.status='ACTIVE';
   if not found then raise exception 'TEACHING_PROGRESS_DENIED'; end if;
  else raise exception 'TEACHING_PROGRESS_DENIED'; end if;
  if old_status is distinct from p_payload->>'expected_status' then raise exception 'TEACHING_STALE'; end if;
  -- These are the SAME student progress writes used by admin actions, retaining all
  -- future-start, sealed-grade and component/subject/level roll-up triggers.
  if kind='subject' then update student_subject_progress set status=next_status where id=progress;
  elsif kind='component' then update student_component_progress set status=next_status where id=progress;
  else update student_component_item_progress set status=next_status where id=progress; end if;
 elsif p_action='context' then
  select * into journal from session_learning_journals where session_occurrence_id=p_session for update;
  if coalesce(journal.version,0) <> coalesce((p_payload->>'version')::integer,-1) then raise exception 'TEACHING_STALE'; end if;
  perform public.save_session_learning_context(p_session,p_payload->>'content',nullif(p_payload->>'context',''));
 elsif p_action='journal' then
  if attendance.id is null then raise exception 'JOURNAL_ATTENDANCE_MISSING'; end if;
  select * into entry from student_learning_journal_entries where attendance_record_id=attendance.id for update;
  if coalesce(entry.version,0) <> coalesce((p_payload->>'version')::integer,-1) then raise exception 'TEACHING_STALE'; end if;
  perform public.save_student_learning_entry(attendance.id,p_payload->>'observation',p_payload->>'progress_note',p_payload->>'homework',
    coalesce((p_payload->>'homework_custom')::boolean,false),nullif(p_payload->>'focus',''),coalesce((p_payload->>'attention')::boolean,false),
    nullif(p_payload->>'attention_reason',''),p_payload->>'attention_detail',p_payload->>'family_note',
    array(select jsonb_array_elements_text(coalesce(p_payload->'codes','[]'::jsonb))));
  select * into journal from session_learning_journals where session_occurrence_id=p_session;
  -- The existing context writer owns submitted revision metadata; retain original submit actor/time.
  if journal.status='SUBMITTED' then perform public.save_session_learning_context(p_session,null,journal.curriculum_context); end if;
 elsif p_action='complete' then
  if o.status<>'SCHEDULED' then raise exception 'TEACHING_STATUS_INVALID'; end if;
  perform public.set_session_occurrence_status(p_session,'COMPLETED');
 elsif p_action='submit' then
  perform public.submit_session_learning_journal(p_session);
 else raise exception 'TEACHING_ACTION_INVALID'; end if;
end $$;


ALTER FUNCTION "public"."teacher_session_write"("p_session" "uuid", "p_action" "text", "p_enrollment" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transition_crm_lead"("p_request" "uuid", "p_lead" "uuid", "p_version" integer, "p_to_status" "text", "p_note" "text", "p_channel" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  row public.crm_leads%rowtype;
  actor uuid := auth.uid();
  target text := nullif(upper(btrim(coalesce(p_to_status, ''))), '');
  note text := public.crm_text(p_note, 4000);
  channel text := public.crm_channel(p_channel);
  event_type text;
  meta jsonb := '{}'::jsonb;
begin
  if actor is null or not coalesce(public.account_is_active(), false) then
    raise exception 'CRM_LEAD_UNAUTHORIZED';
  end if;
  if target is null or target not in (
    'CONTACTED', 'QUALIFIED', 'TRIAL_BOOKED', 'TRIAL_COMPLETED', 'PROPOSAL_SENT', 'NEGOTIATING', 'WON', 'LOST'
  ) then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  if target = 'LOST' and note is null then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  event_type := case target when 'NEGOTIATING' then 'NEGOTIATION_UPDATED' else target end;
  if public.crm_lead_replay(p_request, p_lead, event_type, actor, note, channel, meta, 'crm.lead.update') then
    return p_lead;
  end if;
  row := public.crm_lead_lock(p_lead, p_version, 'crm.lead.update');
  if not (
    (row.status = 'NEW' and target in ('CONTACTED', 'LOST'))
    or (row.status = 'CONTACTED' and target in ('QUALIFIED', 'LOST'))
    or (row.status = 'QUALIFIED' and target in ('TRIAL_BOOKED', 'LOST'))
    or (row.status = 'TRIAL_BOOKED' and target in ('TRIAL_COMPLETED', 'LOST'))
    or (row.status = 'TRIAL_COMPLETED' and target in ('PROPOSAL_SENT', 'LOST'))
    or (row.status = 'PROPOSAL_SENT' and target in ('NEGOTIATING', 'LOST'))
    or (row.status = 'NEGOTIATING' and target in ('WON', 'LOST'))
  ) then
    raise exception 'CRM_LEAD_TRANSITION_DENIED';
  end if;
  perform set_config('crm.lead_write', 'on', true);
  update public.crm_leads set
    status = target,
    lost_reason = case when target = 'LOST' then note else lost_reason end,
    first_contact_at = coalesce(first_contact_at, clock_timestamp()),
    last_contact_at = clock_timestamp(),
    version = version + 1,
    updated_at = clock_timestamp()
  where id = row.id;
  insert into public.crm_lead_events(id, lead_id, event_type, from_status, to_status, actor_id, channel, note, metadata)
  values (p_request, row.id, event_type, row.status, target, actor, channel, note, meta);
  perform set_config('crm.lead_write', 'off', true);
  return row.id;
end $$;


ALTER FUNCTION "public"."transition_crm_lead"("p_request" "uuid", "p_lead" "uuid", "p_version" integer, "p_to_status" "text", "p_note" "text", "p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transition_crm_reactivation"("p_request" "uuid", "p_case" "uuid", "p_version" integer, "p_to_status" "text", "p_note" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  row public.crm_reactivation_cases%rowtype;
  target text := nullif(upper(btrim(coalesce(p_to_status, ''))), '');
  note text := public.crm_text(p_note, 2000);
  actor uuid := auth.uid();
  prior public.crm_reactivation_events%rowtype;
begin
  if actor is null or p_request is null or target is null then raise exception 'CRM_REACTIVATION_INVALID'; end if;
  select * into prior from public.crm_reactivation_events where id = p_request;
  if found then
    select * into row from public.crm_reactivation_cases where id = prior.case_id;
    if not found or not coalesce(public.crm_can('crm.reactivation.manage', row.branch_id), false) then
      raise exception 'CRM_REACTIVATION_UNAUTHORIZED';
    end if;
    if prior.case_id is distinct from p_case or prior.to_status is distinct from target then
      raise exception 'CRM_REACTIVATION_REQUEST_MISMATCH';
    end if;
    return p_case;
  end if;
  select * into row from public.crm_reactivation_cases where id = p_case for update;
  if not found or not coalesce(public.crm_can('crm.reactivation.manage', row.branch_id), false) then
    raise exception 'CRM_REACTIVATION_UNAUTHORIZED';
  end if;
  if row.version is distinct from p_version then raise exception 'CRM_REACTIVATION_STALE'; end if;
  if row.status in ('RETURNED', 'NOT_INTERESTED', 'LOST') then raise exception 'CRM_REACTIVATION_TERMINAL'; end if;
  if target in ('NOT_INTERESTED', 'LOST') and note is null then raise exception 'CRM_REACTIVATION_NOTE_REQUIRED'; end if;
  if not (row.status, target) in (
    ('NEW_REACTIVATION', 'CONTACTED'), ('NEW_REACTIVATION', 'NOT_INTERESTED'), ('NEW_REACTIVATION', 'LOST'),
    ('CONTACTED', 'INTERESTED'), ('CONTACTED', 'NOT_INTERESTED'), ('CONTACTED', 'LOST'),
    ('INTERESTED', 'TRIAL_OR_PLACEMENT'), ('INTERESTED', 'NOT_INTERESTED'), ('INTERESTED', 'LOST'),
    ('TRIAL_OR_PLACEMENT', 'OFFER_SENT'), ('TRIAL_OR_PLACEMENT', 'NOT_INTERESTED'), ('TRIAL_OR_PLACEMENT', 'LOST'),
    ('OFFER_SENT', 'RETURNED'), ('OFFER_SENT', 'NOT_INTERESTED'), ('OFFER_SENT', 'LOST')
  ) then
    raise exception 'CRM_REACTIVATION_TRANSITION_DENIED';
  end if;
  if target = 'RETURNED' and not public.crm_reactivation_returned(row.student_id) then
    raise exception 'CRM_REACTIVATION_RETURN_UNPROVEN';
  end if;
  perform set_config('crm.case_write', 'on', true);
  update public.crm_reactivation_cases set
    status = target,
    last_contact_at = case when target in ('CONTACTED', 'INTERESTED', 'TRIAL_OR_PLACEMENT', 'OFFER_SENT', 'RETURNED') then clock_timestamp() else last_contact_at end,
    returned_at = case when target = 'RETURNED' then clock_timestamp() else returned_at end,
    latest_note = coalesce(note, latest_note),
    version = version + 1,
    updated_at = clock_timestamp()
  where id = row.id;
  insert into public.crm_reactivation_events(id, case_id, event_type, from_status, to_status, actor_id, note)
  values (p_request, row.id, target, row.status, target, actor, note);
  perform set_config('crm.case_write', 'off', true);
  return row.id;
end $$;


ALTER FUNCTION "public"."transition_crm_reactivation"("p_request" "uuid", "p_case" "uuid", "p_version" integer, "p_to_status" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transition_instrument_warranty"("p_request" "uuid", "p_case" "uuid", "p_version" integer, "p_status" "text", "p_note" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  row public.instrument_warranty_cases%rowtype;
  sale public.instrument_events%rowtype;
  target text := nullif(upper(btrim(coalesce(p_status, ''))), '');
  actor uuid := auth.uid();
begin
  if p_request is null or target is null or target not in ('INSPECTING', 'WAITING_PART', 'IN_REPAIR', 'COMPLETED', 'REJECTED', 'CANCELLED') then
    raise exception 'INSTRUMENT_CUSTOMER_INVALID';
  end if;
  if exists (select 1 from public.instrument_warranty_events where id = p_request and case_id is distinct from p_case) then
    raise exception 'INSTRUMENT_CUSTOMER_REQUEST_MISMATCH';
  end if;
  if exists (select 1 from public.instrument_warranty_events where id = p_request) then
    return p_case;
  end if;
  select * into row from public.instrument_warranty_cases where id = p_case for update;
  if not found then raise exception 'INSTRUMENT_CUSTOMER_UNAUTHORIZED'; end if;
  select * into sale from public.instrument_events where movement_id = row.sale_event_id;
  if not coalesce(public.crm_can('instrument_customer.manage', sale.branch_id), false) then
    raise exception 'INSTRUMENT_CUSTOMER_UNAUTHORIZED';
  end if;
  if row.version is distinct from p_version then raise exception 'INSTRUMENT_WARRANTY_STALE'; end if;
  if row.status in ('COMPLETED', 'REJECTED', 'CANCELLED') then raise exception 'INSTRUMENT_WARRANTY_TERMINAL'; end if;
  perform set_config('instrument.customer_write', 'on', true);
  update public.instrument_warranty_cases set
    status = target,
    diagnosis = case when target = 'INSPECTING' then coalesce(public.crm_text(p_note, 2000), diagnosis) else diagnosis end,
    resolution = case when target in ('COMPLETED', 'REJECTED', 'CANCELLED') then public.crm_text(p_note, 2000) else resolution end,
    closed_at = case when target in ('COMPLETED', 'REJECTED', 'CANCELLED') then clock_timestamp() else closed_at end,
    handled_by = actor,
    version = version + 1,
    updated_at = clock_timestamp()
  where id = row.id;
  insert into public.instrument_warranty_events(id, case_id, event_type, from_status, to_status, actor_id, note)
  values (p_request, row.id, 'STATUS_CHANGED', row.status, target, actor, public.crm_text(p_note, 2000));
  perform set_config('instrument.customer_write', 'off', true);
  return row.id;
end $$;


ALTER FUNCTION "public"."transition_instrument_warranty"("p_request" "uuid", "p_case" "uuid", "p_version" integer, "p_status" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transition_learning_version"("p_id" "uuid", "p_action" "text", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$declare v public.learning_versions; target text;begin
 if not public.has_role('SUPER_ADMIN') then raise exception 'Unauthorized'; end if;
 if p_reason is null or length(trim(p_reason)) not between 1 and 2000 then raise exception 'Review reason required'; end if;
 select * into v from public.learning_versions where id=p_id for update;
 if not found then raise exception 'Learning version not found'; end if;
 target:=case when p_action='SUBMIT' and v.state='DRAFT' then 'IN_REVIEW'
 when p_action='APPROVE' and v.state='IN_REVIEW' then 'APPROVED'
 when p_action='PUBLISH' and v.state='APPROVED' then 'PUBLISHED'
 when p_action='RETIRE' and v.state='PUBLISHED' then 'RETIRED' end;
 if target is null then raise exception 'Invalid learning transition'; end if;
 if target='APPROVED' and v.author_id=auth.uid() then raise exception 'Independent content reviewer required'; end if;
 update public.learning_versions set state=target,
 reviewer_id=case when target='APPROVED' then auth.uid() else reviewer_id end,
 review_note=case when target='APPROVED' then trim(p_reason) else review_note end where id=p_id;
 insert into public.learning_audit(entity_id,event,actor,reason) values(p_id,target,auth.uid(),trim(p_reason));
end$$;


ALTER FUNCTION "public"."transition_learning_version"("p_id" "uuid", "p_action" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transition_payroll"("p_period" "uuid", "p_version" integer, "p_status" "text", "p_note" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
 perform public.transition_payroll_with_override(p_period,p_version,p_status,p_note,null,null);
end $$;


ALTER FUNCTION "public"."transition_payroll"("p_period" "uuid", "p_version" integer, "p_status" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transition_payroll_with_override"("p_period" "uuid", "p_version" integer, "p_status" "text", "p_note" "text", "p_override_type" "text", "p_override_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  p public.payroll_periods;
  before_state jsonb;
  after_state jsonb;
  emergency boolean;
  action_permission text;
begin
  action_permission:=
    case p_status
      when 'APPROVED' then 'payroll.approve'
      when 'FINALIZED' then 'payroll.finalize'
      else 'payroll.prepare'
    end;

  -- Authorize scope before locking or revealing the record version.
  select *
    into p
  from public.payroll_periods target
  where target.id=p_period
    and public.has_permission(action_permission,target.branch_id)
    and (
      public.is_global_super_admin()
      or public.has_role_permission(
        'FINANCE',
        action_permission,
        target.branch_id
      )
    )
  for update;

  if not found then
    raise exception 'Unauthorized';
  end if;

  if p.version is distinct from p_version then
    raise exception 'Payroll changed; reload';
  end if;

  emergency:=
    p_override_type is not null
    or p_override_reason is not null;

  if emergency then
    if p_status not in ('APPROVED','FINALIZED')
       or not public.has_permission(action_permission,p.branch_id)
       or not public.is_global_super_admin()
       or p_override_type is distinct from 'MAKER_CHECKER_EMERGENCY'
       or p_override_reason is null
       or char_length(btrim(p_override_reason)) not between 1 and 2000
    then
      raise exception 'Valid SUPER_ADMIN emergency override reason and type required';
    end if;

  elsif p_status in ('APPROVED','FINALIZED')
    and (
      p.generated_by is null
      or p.generated_by=auth.uid()
      or exists(
        select 1
        from public.payroll_adjustments a
        join public.teacher_payrolls t
          on t.id=a.payroll_id
        where t.period_id=p.id
          and a.created_by=auth.uid()
      )
      or exists(
        select 1
        from public.payroll_period_actions_v2 a
        where a.period_id=p.id
          and a.status='ACTIVE'
          and a.created_by=auth.uid()
      )
    )
  then
    raise exception 'Payroll maker cannot approve or finalize';
  end if;

  before_state:=public.payroll_approval_snapshot(p.id);

  if p_note is null
     or char_length(btrim(p_note)) not between 1 and 2000
  then
    raise exception 'Audit note required';
  end if;

  if p_status is null
     or not (
       (p.status='GENERATED' and p_status in ('DRAFT','REVIEW'))
       or
       (p.status='REVIEW' and p_status in ('DRAFT','APPROVED'))
       or
       (p.status='APPROVED' and p_status='FINALIZED')
     )
  then
    raise exception 'Invalid payroll transition';
  end if;

  if p_status='DRAFT'
     and exists(
       select 1
       from public.payroll_adjustments a
       join public.teacher_payrolls t
         on t.id=a.payroll_id
       where t.period_id=p.id
     )
  then
    raise exception 'Payroll with adjustments cannot return to draft';
  end if;

  if p_status='APPROVED'
     and not exists(
       select 1
       from public.teacher_payrolls
       where period_id=p.id
     )
  then
    raise exception 'Empty payroll cannot be approved';
  end if;

  if p_status='APPROVED' then
    update public.payroll_adjustments a
    set
      approved_by=auth.uid(),
      approved_at=now()
    from public.teacher_payrolls t
    where t.id=a.payroll_id
      and t.period_id=p.id;

    update public.payroll_period_actions_v2
    set
      approved_by=auth.uid(),
      approved_at=now()
    where period_id=p.id
      and status='ACTIVE';
  end if;

  update public.payroll_periods
  set
    status=p_status,
    version=version+1,
    approved_by=
      case
        when p_status='APPROVED' then auth.uid()
        else approved_by
      end,
    approved_at=
      case
        when p_status='APPROVED' then now()
        else approved_at
      end,
    finalized_by=
      case
        when p_status='FINALIZED' then auth.uid()
        else finalized_by
      end,
    finalized_at=
      case
        when p_status='FINALIZED' then now()
        else finalized_at
      end
  where id=p.id;

  after_state:=public.payroll_approval_snapshot(p.id);

  insert into public.payroll_events(
    period_id,
    status,
    note,
    actor_id,
    event_type,
    override_type,
    override_reason,
    before_snapshot,
    after_snapshot
  )
  values(
    p.id,
    p_status,
    btrim(p_note),
    auth.uid(),
    case
      when emergency then 'EMERGENCY_OVERRIDE'
      else 'STATUS_TRANSITION'
    end,
    case when emergency then p_override_type end,
    case when emergency then btrim(p_override_reason) end,
    before_state,
    after_state
  );
end;
$$;


ALTER FUNCTION "public"."transition_payroll_with_override"("p_period" "uuid", "p_version" integer, "p_status" "text", "p_note" "text", "p_override_type" "text", "p_override_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transition_registration_application"("p_request" "uuid", "p_application" "uuid", "p_version" integer, "p_action" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor uuid := auth.uid();
  row public.registration_applications%rowtype;
  next_status text;
  event_name text;
begin
  if actor is null or p_request is null or p_action not in ('SUBMIT', 'VERIFY', 'CANCEL') then
    raise exception 'REGISTRATION_INVALID';
  end if;
  if exists(select 1 from public.registration_application_events where id = p_request) then
    return p_application;
  end if;
  row := public.registration_lock(p_application, p_version, 'registration.update');
  if p_action = 'SUBMIT' and row.status = 'DRAFT' then
    if nullif(btrim(coalesce(row.student_name, '')), '') is null or row.student_date_of_birth is null then
      raise exception 'REGISTRATION_INCOMPLETE';
    end if;
    next_status := 'SUBMITTED'; event_name := 'SUBMITTED';
  elsif p_action = 'VERIFY' and row.status = 'SUBMITTED' then
    next_status := 'VERIFIED'; event_name := 'VERIFIED';
  elsif p_action = 'CANCEL' and row.status not in ('COMPLETED', 'CANCELLED', 'REJECTED', 'EXPIRED') then
    next_status := 'CANCELLED'; event_name := 'CANCELLED';
  else
    raise exception 'REGISTRATION_TRANSITION_DENIED';
  end if;
  perform set_config('registration.write', 'on', true);
  update public.registration_applications set
    status = next_status,
    submitted_at = case when next_status = 'SUBMITTED' then clock_timestamp() else submitted_at end,
    verified_at = case when next_status = 'VERIFIED' then clock_timestamp() else verified_at end,
    version = version + 1,
    updated_at = clock_timestamp()
  where id = row.id;
  insert into public.registration_application_events(id, application_id, event_type, from_status, to_status, actor_id)
  values (p_request, row.id, event_name, row.status, next_status, actor);
  perform set_config('registration.write', 'off', true);
  return row.id;
end $$;


ALTER FUNCTION "public"."transition_registration_application"("p_request" "uuid", "p_application" "uuid", "p_version" integer, "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tuition_balance_due_window"("p_starts_on" "date", "p_duration_months" integer DEFAULT 12) RETURNS TABLE("window_start" "date", "window_end" "date")
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO 'public'
    AS $$
  select case p_duration_months
      when 3 then (p_starts_on + interval '1 month')::date
      else (p_starts_on + interval '2 months' + interval '21 days')::date
    end,
    case p_duration_months
      when 3 then (p_starts_on + interval '1 month')::date + 6
      else (p_starts_on + interval '3 months' + interval '6 days')::date
    end
  where p_duration_months in (3, 12);
$$;


ALTER FUNCTION "public"."tuition_balance_due_window"("p_starts_on" "date", "p_duration_months" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tuition_reminder_kpis"() RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
  result jsonb;
begin
  if not coalesce(public.has_role('SUPER_ADMIN'), false) then
    raise exception 'SUPER_ADMIN role required';
  end if;
  select jsonb_build_object(
    'upcoming', count(*) filter (where r.status = 'PENDING' and r.window_start > today),
    'payment', count(*) filter (where r.status = 'PENDING' and r.event_code = 'BALANCE_50_V1'
      and et.duration_months_snapshot = 3 and r.window_start <= today and r.window_end >= today),
    'week', count(*) filter (where r.status = 'PENDING' and r.event_code <> 'BALANCE_50_V1'
      and r.window_start <= today and r.window_end >= today
      and (
        (case when r.event_code = 'RENEWAL_V1' and et.duration_months_snapshot = 3 then r.window_start + 14 else null end) is null
        or (case when r.event_code = 'RENEWAL_V1' and et.duration_months_snapshot = 3 then r.window_start + 14 else null end) > today
      )),
    'red', count(*) filter (where r.status = 'PENDING' and r.window_end >= today
      and (case
        when r.event_code = 'BALANCE_50_V1' and et.duration_months_snapshot = 12 then r.window_start
        when r.event_code = 'RENEWAL_V1' and et.duration_months_snapshot = 3 then r.window_start + 14
        else null
      end) <= today),
    'overdue', count(*) filter (where r.status = 'PENDING' and r.window_end < today),
    'sent', count(*) filter (where r.status = 'SENT'
      and (r.marked_at at time zone 'Asia/Ho_Chi_Minh')::date >= date_trunc('month', today)::date
      and (r.marked_at at time zone 'Asia/Ho_Chi_Minh')::date < (date_trunc('month', today) + interval '1 month')::date)
  ) into result
  from tuition_reminders r
  join enrollment_tuition et on et.id = r.enrollment_tuition_id;
  return result;
end $$;


ALTER FUNCTION "public"."tuition_reminder_kpis"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tuition_reminder_window"("p_starts_on" "date", "p_duration_months" integer) RETURNS TABLE("window_start" "date", "window_end" "date")
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO 'public'
    AS $$
  select case p_duration_months
      when 3 then (p_starts_on + interval '2 months')::date
      else (p_starts_on + interval '9 months')::date
    end,
    case p_duration_months
      when 3 then public.calculate_tuition_base_end(p_starts_on, 3)
      else (p_starts_on + interval '10 months')::date - 1
    end
  where p_duration_months in (3, 12);
$$;


ALTER FUNCTION "public"."tuition_reminder_window"("p_starts_on" "date", "p_duration_months" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tuition_zalo_response_sync_gate"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'activated', sync.activated_at is not null,
    'checkpoint_ms', sync.checkpoint_ms,
    'overlap_ms', sync.overlap_ms,
    'page_limit', sync.page_limit,
    'interval_seconds', sync.interval_seconds,
    'auth_backoff_until', sync.auth_backoff_until,
    'earliest_send_ms', (
      select floor(extract(epoch from min(sent_at)) * 1000)::bigint
      from public.tuition_zalo_sends
      where send_status in ('SENT', 'DELIVERED') and sent_at is not null
    )
  )
  from public.tuition_zalo_response_sync sync
  where sync.id;
$$;


ALTER FUNCTION "public"."tuition_zalo_response_sync_gate"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tuition_zalo_response_sync_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  sync public.tuition_zalo_response_sync;
  credential_count integer;
  credential_app text;
  credential_oa text;
begin
  if not coalesce(public.has_role('SUPER_ADMIN'), false) then
    raise exception 'SUPER_ADMIN role required';
  end if;
  select * into sync from public.tuition_zalo_response_sync where id;
  select count(*) into credential_count from notification_private.zalo_credentials;
  if credential_count = 1 then
    select app_id, oa_id into credential_app, credential_oa from notification_private.zalo_credentials limit 1;
  end if;
  return jsonb_build_object(
    'activated', sync.activated_at is not null,
    'last_success_at', sync.last_success_at,
    'last_error_at', sync.last_error_at,
    'last_error_code', sync.last_error_code,
    'last_error_detail', sync.last_error_detail,
    'auth_backoff_until', sync.auth_backoff_until,
    'checkpoint_ms', sync.checkpoint_ms,
    'interval_seconds', sync.interval_seconds,
    'webhook_clicks', (
      select count(*) from public.integration_webhook_events
      where provider = 'ZALO' and event_type = 'user_click_response_button' and status = 'ACCEPTED'
    ),
    'webhook_pending', (
      select count(*) from public.integration_webhook_events
      where provider = 'ZALO' and event_type = 'user_click_response_button' and status = 'ACCEPTED' and processed_at is null
    ),
    'credential_app_id', credential_app,
    'credential_oa_id', credential_oa
  );
end $$;


ALTER FUNCTION "public"."tuition_zalo_response_sync_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unlock_next_academic_level"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_curriculum_id uuid;
  v_current_sequence integer;
  v_next_level_id uuid;
begin

  -- Only react when the level has just become COMPLETED.
  if new.status <> 'COMPLETED'
     or old.status = 'COMPLETED'
  then
    return new;
  end if;


  select
    sce.curriculum_id,
    cl.sequence_no
  into
    v_curriculum_id,
    v_current_sequence
  from public.student_curriculum_enrollments sce
  join public.curriculum_levels cl
    on cl.id = new.level_id
  where sce.id = new.enrollment_id;


  if v_curriculum_id is null then
    return new;
  end if;


  -- Find the next ACTIVE level in the same curriculum.
  select cl.id
  into v_next_level_id
  from public.curriculum_levels cl
  where cl.curriculum_id = v_curriculum_id
    and cl.status = 'ACTIVE'
    and cl.sequence_no > v_current_sequence
  order by cl.sequence_no
  limit 1;


  -- No next level means the whole academic program is complete.
  if v_next_level_id is null then

    update public.student_curriculum_enrollments
    set
      status = 'COMPLETED',
      completed_at = coalesce(
        completed_at,
        (now() at time zone 'Asia/Ho_Chi_Minh')::date
      ),
      updated_at = now()
    where id = new.enrollment_id;

    return new;

  end if;


  -- Create / unlock only the next level.
  insert into public.student_level_progress (
    enrollment_id,
    level_id,
    status,
    unlocked_at
  )
  values (
    new.enrollment_id,
    v_next_level_id,
    'AVAILABLE',
    now()
  )
  on conflict (enrollment_id, level_id)
  do update
  set
    status =
      case
        when student_level_progress.status = 'LOCKED'
          then 'AVAILABLE'
        else student_level_progress.status
      end,

    unlocked_at =
      coalesce(
        student_level_progress.unlocked_at,
        now()
      ),

    updated_at = now();


  return new;
end;
$$;


ALTER FUNCTION "public"."unlock_next_academic_level"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_attendance_retention_alert"("p_alert" "uuid", "p_status" "text", "p_channel" "text", "p_note" "text", "p_follow_up_on" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  current public.student_retention_alerts%rowtype;
  actor uuid := auth.uid();
  event_type_value text;
begin
  if actor is null
     or not coalesce(public.account_is_active(),false)
     or not coalesce(public.has_role('SUPER_ADMIN'),false)
  then
    raise exception 'RETENTION_ALERT_UNAUTHORIZED';
  end if;

  select *
    into current
  from public.student_retention_alerts
  where id=p_alert
  for update;

  if not found then
    raise exception 'RETENTION_ALERT_NOT_FOUND';
  end if;

  if current.status in ('RESOLVED','LOST','DISMISSED') then
    raise exception 'RETENTION_ALERT_ALREADY_CLOSED';
  end if;

  if p_status not in (
    'CONTACTED',
    'FOLLOW_UP',
    'RESOLVED',
    'LOST',
    'DISMISSED'
  ) then
    raise exception 'RETENTION_ALERT_STATUS_INVALID';
  end if;

  if p_channel is not null
     and p_channel not in (
       'PHONE','ZALO','SMS','EMAIL','IN_PERSON','OTHER'
     )
  then
    raise exception 'RETENTION_ALERT_CHANNEL_INVALID';
  end if;

  if p_note is null
     or char_length(btrim(p_note)) not between 1 and 4000
  then
    raise exception 'RETENTION_ALERT_NOTE_REQUIRED';
  end if;

  if p_status='FOLLOW_UP' and p_follow_up_on is null then
    raise exception 'RETENTION_ALERT_FOLLOW_UP_DATE_REQUIRED';
  end if;

  event_type_value:=
    case
      when p_status='CONTACTED' then 'CONTACTED'
      when p_status='FOLLOW_UP' then 'FOLLOW_UP_SET'
      else 'STATUS_CHANGED'
    end;

  update public.student_retention_alerts
  set
    status=p_status,
    owner_user_id=coalesce(owner_user_id,actor),
    latest_contact_channel=p_channel,
    latest_note=btrim(p_note),
    follow_up_on=
      case
        when p_status='FOLLOW_UP' then p_follow_up_on
        when p_status in ('RESOLVED','LOST','DISMISSED') then null
        else follow_up_on
      end,
    resolution_code=
      case
        when p_status='RESOLVED' then 'CONTINUING'
        when p_status='LOST' then 'WITHDRAWN'
        when p_status='DISMISSED' then 'FALSE_POSITIVE'
        else resolution_code
      end,
    resolved_at=
      case
        when p_status in ('RESOLVED','LOST','DISMISSED')
          then clock_timestamp()
        else null
      end,
    updated_at=clock_timestamp()
  where id=current.id;

  insert into public.student_retention_events(
    alert_id,
    event_type,
    from_status,
    to_status,
    channel,
    note,
    follow_up_on,
    actor_id
  )
  values(
    current.id,
    event_type_value,
    current.status,
    p_status,
    p_channel,
    btrim(p_note),
    p_follow_up_on,
    actor
  );

  return jsonb_build_object(
    'status','UPDATED',
    'alert_id',current.id,
    'from_status',current.status,
    'to_status',p_status
  );
end;
$$;


ALTER FUNCTION "public"."update_attendance_retention_alert"("p_alert" "uuid", "p_status" "text", "p_channel" "text", "p_note" "text", "p_follow_up_on" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_attendance_retention_alert"("p_alert" "uuid", "p_status" "text", "p_channel" "text", "p_note" "text", "p_follow_up_on" "date") IS 'Records human follow-up lifecycle for attendance retention alerts. No automatic external messaging.';



CREATE OR REPLACE FUNCTION "public"."update_crm_campaign"("p_campaign" "uuid", "p_version" integer, "p_name" "text", "p_channel" "text", "p_starts_on" "date", "p_ends_on" "date", "p_budget" numeric, "p_currency" "text", "p_utm_source" "text", "p_utm_medium" "text", "p_utm_campaign" "text", "p_utm_content" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  row public.crm_campaigns%rowtype;
  next_name text := public.crm_text(p_name, 200);
begin
  if next_name is null or (p_budget is null) <> (p_currency is null) or (p_budget is not null and p_budget < 0) then
    raise exception 'CRM_CAMPAIGN_INVALID';
  end if;
  select * into row from public.crm_campaigns where id = p_campaign for update;
  if not found then raise exception 'CRM_CAMPAIGN_UNAUTHORIZED'; end if;
  if row.branch_id is null then
    if not public.has_role('SUPER_ADMIN') then raise exception 'CRM_CAMPAIGN_UNAUTHORIZED'; end if;
  elsif not coalesce(public.crm_can('crm.campaign.manage', row.branch_id), false) then
    raise exception 'CRM_CAMPAIGN_UNAUTHORIZED';
  end if;
  if row.version is distinct from p_version then raise exception 'CRM_CAMPAIGN_STALE'; end if;
  perform set_config('crm.lead_write', 'on', true);
  update public.crm_campaigns set
    name = next_name,
    channel = public.crm_text(p_channel, 80),
    starts_on = p_starts_on,
    ends_on = p_ends_on,
    budget_amount = p_budget,
    currency = nullif(upper(btrim(coalesce(p_currency, ''))), ''),
    utm_source = public.crm_text(p_utm_source, 120),
    utm_medium = public.crm_text(p_utm_medium, 120),
    utm_campaign = public.crm_text(p_utm_campaign, 120),
    utm_content = public.crm_text(p_utm_content, 120),
    version = version + 1,
    updated_at = clock_timestamp()
  where id = row.id;
  perform set_config('crm.lead_write', 'off', true);
  return row.id;
end $$;


ALTER FUNCTION "public"."update_crm_campaign"("p_campaign" "uuid", "p_version" integer, "p_name" "text", "p_channel" "text", "p_starts_on" "date", "p_ends_on" "date", "p_budget" numeric, "p_currency" "text", "p_utm_source" "text", "p_utm_medium" "text", "p_utm_campaign" "text", "p_utm_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_crm_lead"("p_request" "uuid", "p_lead" "uuid", "p_version" integer, "p_full_name" "text", "p_phone" "text", "p_email" "text", "p_parent_name" "text", "p_student_name" "text", "p_student_date_of_birth" "date", "p_program_interest" "text", "p_instrument_interest" "text", "p_source_type" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
#variable_conflict use_variable
declare
  row public.crm_leads%rowtype;
  actor uuid := auth.uid();
  source text := coalesce(nullif(upper(btrim(coalesce(p_source_type, ''))), ''), 'MANUAL');
  name text := public.crm_text(p_full_name, 200);
  phone text := public.crm_text(p_phone, 40);
  email text := public.crm_text(p_email, 200);
  parent_name text := public.crm_text(p_parent_name, 200);
  student_name text := public.crm_text(p_student_name, 200);
  program text := public.crm_text(p_program_interest, 200);
  instrument text := public.crm_text(p_instrument_interest, 200);
  phone_key text := public.crm_phone_key(phone);
  email_key text := public.crm_email_key(email);
  meta jsonb;
begin
  if actor is null or not coalesce(public.account_is_active(), false) then
    raise exception 'CRM_LEAD_UNAUTHORIZED';
  end if;
  if source not in ('MANUAL', 'WALK_IN', 'REFERRAL', 'WEBSITE', 'ZALO', 'PHONE', 'OTHER')
     or (p_student_date_of_birth is not null and not isfinite(p_student_date_of_birth))
     or (email_key is not null and email_key !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$')
     or (phone is not null and (phone_key is null or phone_key !~ '^[0-9]{6,20}$'))
     or (name is null and phone_key is null and email_key is null and parent_name is null and student_name is null)
  then
    raise exception 'CRM_LEAD_INVALID';
  end if;
  meta := jsonb_build_object(
    'full_name', name, 'phone', phone, 'email', email, 'parent_name', parent_name,
    'student_name', student_name, 'student_date_of_birth', p_student_date_of_birth,
    'program_interest', program, 'instrument_interest', instrument, 'source_type', source
  );
  if public.crm_lead_replay(p_request, p_lead, 'UPDATED', actor, null, null, meta, 'crm.lead.update') then
    return p_lead;
  end if;
  row := public.crm_lead_lock(p_lead, p_version, 'crm.lead.update');
  perform set_config('crm.lead_write', 'on', true);
  update public.crm_leads set
    full_name = name, phone = phone, email = email, phone_key = phone_key, email_key = email_key,
    parent_name = parent_name, student_name = student_name, student_date_of_birth = p_student_date_of_birth,
    program_interest = program, instrument_interest = instrument, source_type = source,
    version = version + 1, updated_at = clock_timestamp()
  where id = row.id;
  insert into public.crm_lead_events(id, lead_id, event_type, from_status, to_status, actor_id, metadata)
  values (p_request, row.id, 'UPDATED', row.status, row.status, actor, meta);
  perform set_config('crm.lead_write', 'off', true);
  return row.id;
end $_$;


ALTER FUNCTION "public"."update_crm_lead"("p_request" "uuid", "p_lead" "uuid", "p_version" integer, "p_full_name" "text", "p_phone" "text", "p_email" "text", "p_parent_name" "text", "p_student_name" "text", "p_student_date_of_birth" "date", "p_program_interest" "text", "p_instrument_interest" "text", "p_source_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_curriculum_lesson"("p_curriculum_id" "uuid", "p_level_id" "uuid", "p_subject_id" "uuid", "p_lesson_id" "uuid", "p_code" "text", "p_name" "text", "p_is_required" boolean, "p_sort_order" integer, "p_status" "text") RETURNS "public"."curriculum_component_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_component uuid;
  v_code text;
  v_name text;
  v_current_order integer;
  v_row public.curriculum_component_items;
begin
  select item.component_id, item.sort_order
  into v_component, v_current_order
  from public.curriculum_component_items item
  where item.id = p_lesson_id;

  if v_component is null then
    raise exception 'Lesson not found' using errcode = 'P0001';
  end if;

  perform public.lesson_operator_component(p_curriculum_id, p_level_id, p_subject_id, v_component);
  v_code := upper(trim(coalesce(p_code, '')));
  v_name := trim(coalesce(p_name, ''));

  if v_code !~ '^[A-Z0-9_-]{2,50}$' then
    raise exception 'Invalid lesson code' using errcode = 'P0001';
  end if;
  if v_name = '' or char_length(v_name) > 200 then
    raise exception 'Lesson name is required' using errcode = 'P0001';
  end if;
  if p_status is distinct from 'ACTIVE' and p_status is distinct from 'INACTIVE' then
    raise exception 'Invalid lesson status' using errcode = 'P0001';
  end if;
  if p_sort_order is null or p_sort_order < 0 then
    raise exception 'Invalid sort order' using errcode = 'P0001';
  end if;
  if p_is_required is null then
    raise exception 'Invalid lesson requirement' using errcode = 'P0001';
  end if;

  perform public.assert_required_active_lessons(v_component, p_lesson_id, p_status, p_is_required);

  if p_sort_order > 0 and p_sort_order is distinct from v_current_order then
    update public.curriculum_component_items
    set sort_order = sort_order + 1
    where component_id = v_component
      and id <> p_lesson_id
      and sort_order >= p_sort_order;
  end if;

  update public.curriculum_component_items
  set code = v_code,
      name = v_name,
      is_required = p_is_required,
      sort_order = case when p_sort_order = 0 then sort_order else p_sort_order end,
      status = p_status
  where id = p_lesson_id
    and component_id = v_component
  returning * into v_row;

  perform public.normalize_lesson_order(v_component);

  select * into v_row
  from public.curriculum_component_items
  where id = p_lesson_id;

  return v_row;
exception
  when unique_violation then
    raise exception 'Lesson code already exists' using errcode = '23505';
end;
$_$;


ALTER FUNCTION "public"."update_curriculum_lesson"("p_curriculum_id" "uuid", "p_level_id" "uuid", "p_subject_id" "uuid", "p_lesson_id" "uuid", "p_code" "text", "p_name" "text", "p_is_required" boolean, "p_sort_order" integer, "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_employee_private_profile"("p_employee" "uuid", "p_email" "text", "p_phone" "text", "p_address" "text", "p_citizen_id" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  before_row
    hr_private.employee_private_profiles%rowtype;

  after_row
    hr_private.employee_private_profiles%rowtype;

  has_before boolean := false;

  email_value text;
  phone_value text;
  address_value text;
  citizen_value text;

  before_snapshot jsonb;
  after_snapshot jsonb;
begin
  if auth.uid() is null
     or not coalesce(
       public.account_is_active(),
       false
     )
     or not coalesce(
       public.has_role('SUPER_ADMIN'),
       false
     )
  then
    raise exception
      'EMPLOYEE_PRIVATE_UNAUTHORIZED';
  end if;

  if p_employee is null
     or not exists (
       select 1
       from public.employees e
       where e.id = p_employee
     )
  then
    raise exception
      'EMPLOYEE_PRIVATE_EMPLOYEE_NOT_FOUND';
  end if;

  if p_reason is null
     or char_length(
       btrim(p_reason)
     ) not between 1 and 2000
  then
    raise exception
      'EMPLOYEE_PRIVATE_REASON_REQUIRED';
  end if;

  email_value :=
    hr_private.normalize_employee_email(
      p_email
    );

  phone_value :=
    hr_private.normalize_employee_phone(
      p_phone
    );

  address_value :=
    hr_private.normalize_employee_address(
      p_address
    );

  select *
    into before_row
  from hr_private.employee_private_profiles
  where employee_id = p_employee
  for update;

  has_before := found;

  if has_before then
    citizen_value :=
      case
        when nullif(
          btrim(
            coalesce(p_citizen_id, '')
          ),
          ''
        ) is null
        then before_row.citizen_id
        else
          hr_private.normalize_employee_citizen_id(
            p_citizen_id
          )
      end;

    before_snapshot :=
      jsonb_build_object(
        'email_present', true,
        'phone_last4',
          right(before_row.phone, 4),
        'address_present', true,
        'citizen_id_masked',
          '********' ||
          right(before_row.citizen_id, 4)
      );

    update
      hr_private.employee_private_profiles
    set
      email = email_value,
      phone = phone_value,
      address = address_value,
      citizen_id = citizen_value,
      updated_at = clock_timestamp(),
      updated_by = auth.uid()
    where employee_id = p_employee
    returning *
      into after_row;
  else
    citizen_value :=
      hr_private.normalize_employee_citizen_id(
        p_citizen_id
      );

    insert into
      hr_private.employee_private_profiles (
        employee_id,
        email,
        phone,
        address,
        citizen_id,
        created_by,
        updated_by
      )
    values (
      p_employee,
      email_value,
      phone_value,
      address_value,
      citizen_value,
      auth.uid(),
      auth.uid()
    )
    returning *
      into after_row;

    before_snapshot := null;
  end if;

  after_snapshot :=
    jsonb_build_object(
      'email_present', true,
      'phone_last4',
        right(after_row.phone, 4),
      'address_present', true,
      'citizen_id_masked',
        '********' ||
        right(after_row.citizen_id, 4)
    );

  insert into public.employee_audit (
    employee_id,
    action,
    before_data,
    after_data,
    reason,
    actor
  )
  values (
    p_employee,
    case
      when has_before
        then 'PRIVATE_PROFILE_UPDATED'
      else 'PRIVATE_PROFILE_CREATED'
    end,
    before_snapshot,
    after_snapshot,
    btrim(p_reason),
    auth.uid()
  );

  return jsonb_build_object(
    'status',
      case
        when has_before
          then 'UPDATED'
        else 'CREATED'
      end,
    'employee_id',
      after_row.employee_id,
    'email',
      after_row.email,
    'phone',
      after_row.phone,
    'address',
      after_row.address,
    'citizen_id_masked',
      '********' ||
      right(after_row.citizen_id, 4),
    'updated_at',
      after_row.updated_at
  );
end;
$$;


ALTER FUNCTION "public"."update_employee_private_profile"("p_employee" "uuid", "p_email" "text", "p_phone" "text", "p_address" "text", "p_citizen_id" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_learning_report"("p_id" "uuid", "p_version" integer, "p_action" "text", "p_summary" "jsonb" DEFAULT '{}'::"jsonb", "p_note" "text" DEFAULT ''::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  r learning_reports;
  new_data jsonb;
begin
  if not coalesce(has_role('SUPER_ADMIN'), false) then
    raise exception 'Unauthorized';
  end if;

  select *
  into r
  from learning_reports
  where id = p_id
  for update;

  if not found or r.version is distinct from p_version then
    raise exception 'Report changed; reload';
  end if;

  if r.status in ('PUBLISHED', 'CANCELLED') then
  raise exception 'Report is immutable';
end if;

if r.status = 'APPROVED'
   and p_action <> 'PUBLISH' then
  raise exception 'Report is immutable';
end if;

  if p_action = 'SAVE' and r.status = 'DRAFT' then

    if p_summary is null
       or jsonb_typeof(p_summary) <> 'object'
       or p_note is null then
      raise exception 'Invalid summary';
    end if;

    if exists (
      select 1
      from jsonb_each(p_summary) x
      where x.key not in (
        'achievement',
        'difficulty',
        'intervention',
        'next_month_plan',
        'practice_consistency',
        'lesson_preparation',
        'learning_attitude',
        'general_comment',
        'strengths',
        'improvement_areas',
        'next_focus',
        'recommendation'
      )
      or jsonb_typeof(x.value) <> 'string'
      or char_length(x.value #>> '{}') > 4000
    ) then
      raise exception 'Invalid summary';
    end if;

    update learning_reports
    set teacher_summary = p_summary,
        admin_note = p_note
    where id = p_id;

  elsif p_action = 'REGENERATE'
        and r.status = 'DRAFT' then

    new_data := learning_report_source(
      r.enrollment_id,
      r.period_start,
      r.period_end
    );

    update learning_reports
    set draft_data = new_data,
        generated_at = now(),
        generated_by = auth.uid()
    where id = p_id;

  elsif p_action = 'READY'
        and r.status = 'DRAFT' then

    update learning_reports
    set status = 'READY_FOR_REVIEW'
    where id = p_id;

  elsif p_action = 'APPROVE'
        and r.status = 'READY_FOR_REVIEW' then

    update learning_reports
    set status = 'APPROVED',
        snapshot_data =
          r.draft_data ||
          jsonb_build_object(
            'teacher_summary', r.teacher_summary,
            'admin_note', r.admin_note
          ),
        approved_at = now(),
        approved_by = auth.uid()
    where id = p_id;

  elsif p_action = 'PUBLISH'
        and r.status = 'APPROVED' then

    update learning_reports
    set status = 'PUBLISHED',
        sent_at = now()
    where id = p_id;

  elsif p_action = 'RETURN'
        and r.status = 'READY_FOR_REVIEW' then

    update learning_reports
    set status = 'DRAFT'
    where id = p_id;

  elsif p_action = 'CANCEL'
        and r.status in ('DRAFT', 'READY_FOR_REVIEW') then

    update learning_reports
    set status = 'CANCELLED'
    where id = p_id;

  else
    raise exception 'Invalid report transition';
  end if;

  insert into learning_report_events(
    report_id,
    event,
    version,
    actor_id
  )
  values (
    p_id,
    p_action,
    r.version + 1,
    auth.uid()
  );

  return p_id;
end
$$;


ALTER FUNCTION "public"."update_learning_report"("p_id" "uuid", "p_version" integer, "p_action" "text", "p_summary" "jsonb", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_operating_expense_template"("p_template" "uuid", "p_version" integer, "p_category" "text", "p_custom_category_name" "text", "p_name" "text", "p_vendor" "text", "p_amount_mode" "text", "p_expected_amount" numeric, "p_currency" "text", "p_effective_from" "date", "p_effective_to" "date", "p_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  target public.operating_expense_templates; payload jsonb; prior jsonb; custom_name text; vendor_name text; currency_code text; result jsonb; before_data jsonb;
begin
  select * into target from public.operating_expense_templates where id=p_template for update;
  if not found then raise exception 'OPERATING_EXPENSE_TEMPLATE_NOT_FOUND'; end if;
  if not vibe_operating_expense_private.can_manage(target.branch_id) then raise exception 'OPERATING_EXPENSE_UNAUTHORIZED'; end if;
  if target.status<>'ACTIVE' then raise exception 'OPERATING_EXPENSE_TEMPLATE_RETIRED'; end if;
  if p_version is distinct from target.version then raise exception 'OPERATING_EXPENSE_CHANGED_RELOAD'; end if;
  if p_category is null or p_category not in (
    'RENT','ELECTRICITY','WATER','INTERNET','FIXED_PHONE','SECURITY','CLEANING','SOFTWARE','MAINTENANCE','OTHER'
  ) then raise exception 'OPERATING_EXPENSE_INVALID_CATEGORY'; end if;
  custom_name:=nullif(btrim(coalesce(p_custom_category_name,'')),'');
  if p_category='OTHER' then
    if custom_name is null or char_length(custom_name)>100 then raise exception 'OPERATING_EXPENSE_CUSTOM_CATEGORY_REQUIRED'; end if;
  elsif custom_name is not null then
    raise exception 'OPERATING_EXPENSE_CUSTOM_CATEGORY_NOT_ALLOWED';
  end if;
  if p_name is null or char_length(btrim(p_name)) not between 1 and 200 then raise exception 'OPERATING_EXPENSE_NAME_REQUIRED'; end if;
  vendor_name:=nullif(btrim(coalesce(p_vendor,'')),'');
  currency_code:=upper(coalesce(p_currency,target.currency));
  if p_amount_mode not in ('FIXED','VARIABLE') then raise exception 'OPERATING_EXPENSE_INVALID_AMOUNT_MODE'; end if;
  if p_amount_mode='FIXED' and not vibe_operating_expense_private.money_ok(p_expected_amount,currency_code,true) then
    raise exception 'OPERATING_EXPENSE_FIXED_AMOUNT_REQUIRED';
  end if;
  if p_expected_amount is not null and currency_code='VND' and p_expected_amount<>trunc(p_expected_amount) then
    raise exception 'OPERATING_EXPENSE_VND_REQUIRES_WHOLE_DONG';
  end if;
  if p_effective_from is null or not isfinite(p_effective_from) then raise exception 'OPERATING_EXPENSE_EFFECTIVE_FROM_REQUIRED'; end if;
  if p_effective_to is not null and (not isfinite(p_effective_to) or p_effective_to<p_effective_from) then raise exception 'OPERATING_EXPENSE_INVALID_EFFECTIVE_TO'; end if;
  payload:=jsonb_build_object(
    'operation','TEMPLATE_UPDATED','template_id',p_template,'version',p_version,'category',p_category,
    'custom_category_name',custom_name,'name',btrim(p_name),'vendor',vendor_name,'amount_mode',p_amount_mode,
    'expected_amount',p_expected_amount,'currency',currency_code,'effective_from',p_effective_from,'effective_to',p_effective_to
  );
  prior:=vibe_operating_expense_private.replay(p_key,payload);
  if prior is not null then return prior; end if;
  before_data:=to_jsonb(target);
  update public.operating_expense_templates set
    category=p_category,custom_category_name=custom_name,name=btrim(p_name),vendor=vendor_name,amount_mode=p_amount_mode,
    expected_amount=p_expected_amount,currency=currency_code,effective_from=p_effective_from,effective_to=p_effective_to,
    version=version+1,updated_at=clock_timestamp()
  where id=p_template;
  result:=jsonb_build_object('template_id',p_template,'status','ACTIVE','version',p_version+1);
  return vibe_operating_expense_private.write_event(p_template,null,'TEMPLATE_UPDATED',p_key,payload,before_data,to_jsonb((select t from public.operating_expense_templates t where t.id=p_template)),result);
end;
$$;


ALTER FUNCTION "public"."update_operating_expense_template"("p_template" "uuid", "p_version" integer, "p_category" "text", "p_custom_category_name" "text", "p_name" "text", "p_vendor" "text", "p_amount_mode" "text", "p_expected_amount" numeric, "p_currency" "text", "p_effective_from" "date", "p_effective_to" "date", "p_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_registration_intake"("p_application" "uuid", "p_version" integer, "p_request" "uuid", "p_branch" "uuid", "p_lead" "uuid", "p_student_name" "text", "p_student_date_of_birth" "date", "p_parent_name" "text", "p_parent_phone" "text", "p_curriculum" "uuid", "p_level" "uuid", "p_subject" "uuid", "p_desired_start" "date", "p_preferred_schedule" "text", "p_consent" boolean, "p_consent_method" "text", "p_over_18" boolean, "p_zalo_phone" "text", "p_home_address" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  row public.registration_applications%rowtype;
  prepared jsonb;
  new_role text;
  old_role text;
begin
  if p_request is null or auth.uid() is null then raise exception 'REGISTRATION_INVALID'; end if;
  perform pg_advisory_xact_lock(hashtextextended('registration-intake:' || p_request::text, 0));
  perform 1 from public.registration_applications where id = p_application for update;
  if exists(select 1 from public.registration_application_events where id = p_request and application_id = p_application) then
    return;
  end if;
  if exists(select 1 from public.registration_application_events where id = p_request) then
    raise exception 'REGISTRATION_REQUEST_CONFLICT';
  end if;
  row := public.registration_lock(p_application, p_version, 'registration.update');
  if row.status not in ('DRAFT', 'SUBMITTED') or row.branch_id is distinct from p_branch then
    raise exception 'REGISTRATION_TRANSITION_DENIED';
  end if;
  prepared := public.registration_prepare_intake(
    p_student_date_of_birth, p_over_18, p_parent_name, p_parent_phone,
    p_zalo_phone, p_home_address, p_consent, p_consent_method
  );
  if p_curriculum is null or p_level is null
     or not exists (select 1 from public.curriculums where id = p_curriculum and status = 'ACTIVE')
     or not exists (select 1 from public.curriculum_levels where id = p_level and curriculum_id = p_curriculum and status = 'ACTIVE')
     or (p_subject is not null and not exists (
       select 1 from public.curriculum_subjects where id = p_subject and level_id = p_level and status = 'ACTIVE'
     )) then
    raise exception 'REGISTRATION_ACADEMIC_SELECTION_INVALID';
  end if;
  new_role := case when p_over_18 then 'STUDENT' else 'PARENT' end;
  old_role := case when row.student_over_18 then 'STUDENT' else 'PARENT' end;
  if row.zalo_phone is distinct from (prepared->>'zalo') or old_role is distinct from new_role then
    update public.registration_zalo_phone_consents
      set revoked_at = clock_timestamp(), revoked_by = auth.uid()
    where application_id = p_application and revoked_at is null;
  end if;
  perform set_config('registration.write', 'on', true);
  update public.registration_applications set
    student_name = nullif(btrim(coalesce(p_student_name, '')), ''),
    student_date_of_birth = p_student_date_of_birth,
    student_over_18 = coalesce(p_over_18, false),
    parent_name = case when p_over_18 and prepared->>'parent_name' is null then parent_name else prepared->>'parent_name' end,
    parent_phone = case when p_over_18 and prepared->>'parent_phone' is null then parent_phone else prepared->>'parent_phone' end,
    zalo_phone = prepared->>'zalo',
    home_address = prepared->>'address',
    curriculum_id = p_curriculum,
    level_id = p_level,
    subject_id = case
      when p_subject is not null then p_subject
      when curriculum_id is not distinct from p_curriculum and level_id is not distinct from p_level then subject_id
      else null
    end,
    desired_start_date = p_desired_start,
    preferred_schedule = nullif(btrim(coalesce(p_preferred_schedule, '')), ''),
    version = version + 1,
    updated_at = clock_timestamp()
  where id = p_application;
  insert into public.registration_application_events(id, application_id, event_type, from_status, to_status, actor_id)
  values (p_request, p_application, 'INTAKE_UPDATED', row.status, row.status, auth.uid());
  perform set_config('registration.write', 'off', true);
  if p_consent is true and not exists (
    select 1 from public.registration_zalo_phone_consents
    where application_id = p_application and revoked_at is null and normalized_phone = prepared->>'zalo'
  ) then
    perform public.update_registration_zalo_consent(p_application, null, 'RECORD', prepared->>'zalo', true, p_consent_method, 'REGISTRATION_FORM');
  end if;
end $$;


ALTER FUNCTION "public"."update_registration_intake"("p_application" "uuid", "p_version" integer, "p_request" "uuid", "p_branch" "uuid", "p_lead" "uuid", "p_student_name" "text", "p_student_date_of_birth" "date", "p_parent_name" "text", "p_parent_phone" "text", "p_curriculum" "uuid", "p_level" "uuid", "p_subject" "uuid", "p_desired_start" "date", "p_preferred_schedule" "text", "p_consent" boolean, "p_consent_method" "text", "p_over_18" boolean, "p_zalo_phone" "text", "p_home_address" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_registration_zalo_consent"("p_application" "uuid", "p_expected" "uuid", "p_operation" "text", "p_phone" "text", "p_confirmed" boolean, "p_method" "text", "p_source" "text" DEFAULT 'REGISTRATION_RECORD'::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare c registration_zalo_phone_consents; j notification_jobs; result text; normalized text;
begin
 if auth.uid() is null or not has_role('SUPER_ADMIN') then raise exception 'Unauthorized'; end if;
 if p_operation is null or p_operation not in ('RECORD','REVOKE') or p_source is null or p_source not in ('REGISTRATION_FORM','REGISTRATION_RECORD') then raise exception 'PHONE_CONSENT_INVALID'; end if;
 if p_confirmed is distinct from true then raise exception 'PHONE_CONSENT_REQUIRED'; end if;
 -- Same lock order as claims/recovery. Expected consent fences stale tabs and double submits.
 perform 1 from notification_jobs where entity_id=p_application and entity_type='REGISTRATION_COMPLETED' and channel='ZALO' order by id for update;
 perform 1 from registration_applications where id=p_application for update;
 if not found then raise exception 'REGISTRATION_NOT_FOUND'; end if;
 select * into c from registration_zalo_phone_consents where application_id=p_application and revoked_at is null for update;
 if c.id is distinct from p_expected then raise exception 'PHONE_CONSENT_STALE'; end if;
 if p_operation='RECORD' then
   if p_method is null or p_method not in ('IN_PERSON','PHONE','WRITTEN') then raise exception 'PHONE_CONSENT_SOURCE_REQUIRED'; end if;
   if p_phone is null or btrim(p_phone) !~ '^\+?[0-9 () .-]+$' then raise exception 'PHONE_INVALID'; end if;
   normalized:=notification_private.normalize_vn_phone(p_phone);
   if normalized is null then raise exception 'PHONE_INVALID'; end if;
 end if;
 if c.id is not null then
   update registration_zalo_phone_consents set revoked_at=clock_timestamp(),revoked_by=auth.uid() where id=c.id;
 end if;
 if p_operation='RECORD' then
   insert into registration_zalo_phone_consents(application_id,normalized_phone,notice_version,source,actor_id,confirmation_method)
   values(p_application,normalized,'zbs-phone-v1',p_source,auth.uid(),p_method);
 end if;
 -- Only explicitly recorded changes may replace a never-attempted snapshot.
 -- Checks alone retain the existing WRONG_RECIPIENT protection.
 for j in select * from notification_jobs where entity_id=p_application and entity_type='REGISTRATION_COMPLETED' and channel='ZALO' loop
   if j.attempts=0 and j.status in ('QUEUED','SKIPPED_NO_CHANNEL') and j.sent_at is null and j.provider_message_id is null and j.provider_receipt is null
      and not exists(select 1 from zalo_notification_attempts where job_id=j.id)
      and not exists(select 1 from notification_events where job_id=j.id and event in ('CLAIMED','SENT','FAILED')) then
     perform set_config('zalo.durable_write','on',true);
     update notification_jobs set payload=payload-'delivery',status='SKIPPED_NO_CHANNEL',error_code='NO_CONSENT',updated_at=clock_timestamp() where id=j.id;
     insert into notification_events(job_id,event,actor_id,details) values(j.id,'RETRY',auth.uid(),jsonb_build_object('source','CONSENT_'||p_operation,'previous_consent_id',c.id,'request_sent',false));
   end if;
 end loop;
 result:=reevaluate_registration_zalo_channel(p_application);
 return case when p_operation='REVOKE' then 'CONSENT_REVOKED' when result='NOT_SENDABLE' then 'CONSENT_RECORDED' else result end;
end $_$;


ALTER FUNCTION "public"."update_registration_zalo_consent"("p_application" "uuid", "p_expected" "uuid", "p_operation" "text", "p_phone" "text", "p_confirmed" boolean, "p_method" "text", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_student_academic_enrollment_start_date"("p_enrollment_id" "uuid", "p_started_at" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_enrollment public.student_curriculum_enrollments%rowtype;
  v_level_progress_id uuid;
begin
  if not coalesce(public.has_role('SUPER_ADMIN'),false) then raise exception 'Unauthorized'; end if;
  if p_enrollment_id is null then
    raise exception 'Academic enrollment is required';
  end if;

  if p_started_at is null then
    raise exception 'Academic enrollment start date is required';
  end if;

  select *
  into v_enrollment
  from public.student_curriculum_enrollments
  where id = p_enrollment_id
  for update;

  if not found then
    raise exception 'Academic enrollment does not exist';
  end if;

  -- Saving the same value is harmless.
  if v_enrollment.started_at = p_started_at then
    return;
  end if;

  -- -------------------------------------------------------
  -- Completed academic history must never be rewritten.
  --
  -- Check this before enrollment status because completing
  -- a grade may also automatically change enrollment status.
  -- -------------------------------------------------------
  if exists (
    select 1
    from public.student_level_progress slp
    where slp.enrollment_id = p_enrollment_id
      and (
        slp.status = 'COMPLETED'
        or slp.completed_at is not null
      )
  ) then
    raise exception
      'Academic enrollment start date cannot be changed after a grade has been completed';
  end if;

  if v_enrollment.status <> 'ACTIVE' then
    raise exception
      'Only active academic enrollments can change their start date';
  end if;

  -- -------------------------------------------------------
  -- Component activity is checked first because component
  -- workflow may also promote its parent subject status.
  -- -------------------------------------------------------
  if exists (
    select 1
    from public.student_component_progress scp
    join public.student_subject_progress ssp
      on ssp.id = scp.subject_progress_id
    join public.student_level_progress slp
      on slp.id = ssp.level_progress_id
    where slp.enrollment_id = p_enrollment_id
      and (
        scp.status <> 'NOT_STARTED'
        or scp.score is not null
        or scp.started_at is not null
        or scp.passed_at is not null
      )
  ) then
    raise exception
      'Academic enrollment start date cannot be changed after component progress has started';
  end if;

  -- -------------------------------------------------------
  -- Subject activity makes the original start date
  -- historical.
  -- -------------------------------------------------------
  if exists (
    select 1
    from public.student_subject_progress ssp
    join public.student_level_progress slp
      on slp.id = ssp.level_progress_id
    where slp.enrollment_id = p_enrollment_id
      and (
        ssp.status <> 'NOT_STARTED'
        or ssp.score is not null
        or ssp.started_at is not null
        or ssp.passed_at is not null
      )
  ) then
    raise exception
      'Academic enrollment start date cannot be changed after subject progress has started';
  end if;

  -- -------------------------------------------------------
  -- v1 edits only the current IN_PROGRESS grade.
  -- -------------------------------------------------------
  select slp.id
  into v_level_progress_id
  from public.student_level_progress slp
  where slp.enrollment_id = p_enrollment_id
    and slp.level_id = v_enrollment.current_level_id
    and slp.status = 'IN_PROGRESS'
  for update;

  if not found then
    raise exception
      'Academic enrollment does not have a current in-progress grade';
  end if;

  -- Keep enrollment and current grade dates synchronized.
  update public.student_curriculum_enrollments
  set
    started_at = p_started_at,
    updated_at = now()
  where id = p_enrollment_id;

  update public.student_level_progress
  set
    started_at =
      p_started_at::timestamp
      at time zone 'Asia/Ho_Chi_Minh',
    updated_at = now()
  where id = v_level_progress_id;
end;
$$;


ALTER FUNCTION "public"."update_student_academic_enrollment_start_date"("p_enrollment_id" "uuid", "p_started_at" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_student_academic_enrollment_start_date"("p_enrollment_id" "uuid", "p_started_at" "date") IS 'Changes an ACTIVE academic program enrollment start date before real academic progress exists and keeps the current IN_PROGRESS level start date synchronized.';



CREATE OR REPLACE FUNCTION "public"."update_student_basic"("p_student" "uuid", "p_full_name" "text", "p_preferred_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
 if not public.student_branch_permission(p_student,'students.update_basic') then raise exception 'Unauthorized'; end if;
 if p_full_name is null or char_length(btrim(p_full_name)) not between 1 and 200 or char_length(p_preferred_name)>200 then raise exception 'Invalid student name'; end if;
 update public.students set full_name=btrim(p_full_name),preferred_name=nullif(btrim(p_preferred_name),'') where id=p_student;
 if not found then raise exception 'Student not found'; end if;
end $$;


ALTER FUNCTION "public"."update_student_basic"("p_student" "uuid", "p_full_name" "text", "p_preferred_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_tuition_discount"("p_tuition_id" "uuid", "p_discount_type" "text", "p_discount_value" numeric, "p_discount_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not coalesce(public.has_role('SUPER_ADMIN'),false) then raise exception 'SUPER_ADMIN role required'; end if;
  -- Same row lock as create_tuition_invoice, preventing invoice/discount races.
  perform 1 from enrollment_tuition where id=p_tuition_id for update;
  perform preview_tuition_discount(p_tuition_id,p_discount_type,p_discount_value,p_discount_name);
  update enrollment_tuition set discount_type=p_discount_type,discount_value=p_discount_value,discount_name=p_discount_name where id=p_tuition_id;
  return p_tuition_id;
end $$;


ALTER FUNCTION "public"."update_tuition_discount"("p_tuition_id" "uuid", "p_discount_type" "text", "p_discount_value" numeric, "p_discount_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_attendance_record_class"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_occurrence_class_id uuid;
  v_occurrence_status text;
  v_occurrence_type text;
  v_occurrence_date date;

  v_enrollment_class_id uuid;
  v_enrollment_started_at date;
  v_enrollment_ended_at date;
begin

  select
    schedule.class_id,
    occurrence.status,
    occurrence.occurrence_type,
    occurrence.occurrence_date
  into
    v_occurrence_class_id,
    v_occurrence_status,
    v_occurrence_type,
    v_occurrence_date
  from public.session_occurrences as occurrence

  join public.schedules as schedule
    on schedule.id = occurrence.schedule_id

  where occurrence.id =
    new.session_occurrence_id;


  if v_occurrence_status = 'CANCELLED' then
    raise exception
      'Attendance cannot be recorded for a cancelled session';
  end if;


  select
    enrollment.class_id,
    enrollment.started_at,
    enrollment.ended_at
  into
    v_enrollment_class_id,
    v_enrollment_started_at,
    v_enrollment_ended_at
  from public.enrollments as enrollment
  where enrollment.id = new.enrollment_id;


  if v_occurrence_class_id is distinct from
    v_enrollment_class_id
  then
    raise exception
      'Attendance enrollment must belong to the occurrence class';
  end if;


  -- -------------------------------------------------------
  -- REGULAR SESSION STUDY PERIOD
  -- -------------------------------------------------------

  if
    v_occurrence_type = 'REGULAR'
    and (
      v_enrollment_started_at is null
      or v_enrollment_started_at > v_occurrence_date
      or (
        v_enrollment_ended_at is not null
        and v_enrollment_ended_at < v_occurrence_date
      )
    )
  then
    raise exception
      'Attendance cannot be recorded outside the enrollment study period';
  end if;


  -- -------------------------------------------------------
  -- REGULAR SESSION PAUSE RULE
  -- -------------------------------------------------------

  if
    v_occurrence_type = 'REGULAR'
    and public.is_enrollment_paused_on(
      new.enrollment_id,
      v_occurrence_date
    )
  then
    raise exception
      'Attendance cannot be recorded while the enrollment is paused';
  end if;


  -- -------------------------------------------------------
  -- MAKEUP SESSION EXPLICIT ROSTER
  -- -------------------------------------------------------

  if
    v_occurrence_type = 'MAKEUP'
    and not exists (
      select 1
      from public.session_occurrence_participants
      where session_occurrence_id =
          new.session_occurrence_id
        and enrollment_id =
          new.enrollment_id
    )
  then
    raise exception
      'Attendance enrollment must be a makeup participant';
  end if;


  return new;
end;
$$;


ALTER FUNCTION "public"."validate_attendance_record_class"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_class_level_scope"("p_course_id" "uuid", "p_from" "uuid", "p_to" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_curriculum uuid;
  v_from_curriculum uuid;
  v_to_curriculum uuid;
  v_from_seq integer;
  v_to_seq integer;
begin
  if p_from is null and p_to is null then
    return;
  end if;

  if p_from is null or p_to is null then
    raise exception 'Class level scope requires both from and to Levels, or both null'
      using errcode = 'P0001';
  end if;

  select curriculum_id into v_curriculum
  from public.courses
  where id = p_course_id;

  if v_curriculum is null then
    raise exception 'Course not found for class level scope'
      using errcode = 'P0001';
  end if;

  select curriculum_id, sequence_no into v_from_curriculum, v_from_seq
  from public.curriculum_levels
  where id = p_from;

  if not found then
    raise exception 'From Level not found'
      using errcode = 'P0001';
  end if;

  select curriculum_id, sequence_no into v_to_curriculum, v_to_seq
  from public.curriculum_levels
  where id = p_to;

  if not found then
    raise exception 'To Level not found'
      using errcode = 'P0001';
  end if;

  if v_from_curriculum is distinct from v_curriculum
     or v_to_curriculum is distinct from v_curriculum then
    raise exception 'Class level scope must use Levels from the Course curriculum'
      using errcode = 'P0001';
  end if;

  if v_from_seq > v_to_seq then
    raise exception 'Class level scope from sequence cannot exceed to sequence'
      using errcode = 'P0001';
  end if;
end;
$$;


ALTER FUNCTION "public"."validate_class_level_scope"("p_course_id" "uuid", "p_from" "uuid", "p_to" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_component_item_rule"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin

  if new.completion_rule = 'ALL_REQUIRED_ITEMS'
    and not exists (
      select 1
      from public.curriculum_component_items item
      where item.component_id = new.id
        and item.status = 'ACTIVE'
        and item.is_required = true
    )
  then
    raise exception
      'ALL_REQUIRED_ITEMS component requires at least one required active item';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_component_item_rule"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_learning_content"("p_content" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare m jsonb; l jsonb; b jsonb; module_codes text[]:='{}'; lesson_codes text[]:='{}';
begin
 if p_content is null or jsonb_typeof(p_content)<>'object' or jsonb_typeof(p_content->'modules') is distinct from 'array' or octet_length(p_content::text)>1000000 then raise exception 'Invalid learning content'; end if;
 if jsonb_array_length(p_content->'modules') not between 1 and 100 then raise exception 'Invalid learning content'; end if;
 for m in select value from jsonb_array_elements(p_content->'modules') loop
 if jsonb_typeof(m)<>'object' or coalesce(m->>'code','')!~'^[A-Z0-9._-]{1,50}$' or (m->>'code')=any(module_codes) or length(trim(coalesce(m->>'title',''))) not between 1 and 200 or jsonb_typeof(m->'lessons') is distinct from 'array' then raise exception 'Invalid learning module'; end if;
 module_codes:=array_append(module_codes,m->>'code');
 if jsonb_array_length(m->'lessons') not between 1 and 100 then raise exception 'Invalid learning module'; end if;
 for l in select value from jsonb_array_elements(m->'lessons') loop
 if jsonb_typeof(l)<>'object' or coalesce(l->>'code','')!~'^[A-Z0-9._-]{1,80}$' or (l->>'code')=any(lesson_codes) or length(trim(coalesce(l->>'title',''))) not between 1 and 200 or jsonb_typeof(l->'blocks') is distinct from 'array' then raise exception 'Invalid learning lesson'; end if;
 lesson_codes:=array_append(lesson_codes,l->>'code');
 if jsonb_array_length(l->'blocks') not between 1 and 100 then raise exception 'Invalid learning lesson'; end if;
 for b in select value from jsonb_array_elements(l->'blocks') loop
 if jsonb_typeof(b)<>'object' or coalesce(b->>'type','') not in('TEXT','MEDIA_REFERENCE') or length(trim(coalesce(b->>'text',''))) not between 1 and 10000 or
 (b->>'type'='MEDIA_REFERENCE' and length(trim(coalesce(b->>'asset_ref',''))) not between 1 and 500) then raise exception 'Invalid learning block'; end if;
 end loop;
 end loop;
 end loop;
end$_$;


ALTER FUNCTION "public"."validate_learning_content"("p_content" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_legacy_batch"("p_batch" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare b public.migration_batches%rowtype; r public.migration_batch_rows%rowtype; errors jsonb; checked integer:=0;
begin
 select * into b from public.migration_batches where id=p_batch for update;
 if b.id is null or not public.has_permission('migration.validate',b.branch_id) then raise exception 'Unauthorized'; end if;
 if b.signed_off_at is not null then raise exception 'Signed-off batch is immutable'; end if;
 for r in select * from public.migration_batch_rows where batch_id=p_batch and status in ('NEEDS_REVIEW','VALIDATED','READY') order by row_number for update loop
  errors:=public.legacy_row_errors(r.id);
  update public.migration_batch_rows set validation_result=errors,
   status=case when errors<>'[]' then 'NEEDS_REVIEW' when identity_reviewed_by is not null and academic_reviewed_by is not null and finance_reviewed_by is not null then 'READY' else 'VALIDATED' end,
   identity_reviewed_by=case when errors='[]' then identity_reviewed_by end,
   academic_reviewed_by=case when errors='[]' then academic_reviewed_by end,
   finance_reviewed_by=case when errors='[]' then finance_reviewed_by end where id=r.id;
  checked:=checked+1;
 end loop;
 insert into public.migration_audit_events(batch_id,actor_id,action,reason) values(p_batch,auth.uid(),'VALIDATE_BATCH','Dry run; no business writes');
 return checked;
end $$;


ALTER FUNCTION "public"."validate_legacy_batch"("p_batch" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_makeup_participant"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_occurrence_type text;
  v_occurrence_class_id uuid;
  v_enrollment_class_id uuid;
begin
  select
    occurrence.occurrence_type,
    schedule.class_id
  into
    v_occurrence_type,
    v_occurrence_class_id
  from public.session_occurrences as occurrence
  join public.schedules as schedule
    on schedule.id = occurrence.schedule_id
  where occurrence.id = new.session_occurrence_id;

  if v_occurrence_type is distinct from 'MAKEUP' then
    raise exception
      'Explicit participants are only allowed for makeup sessions';
  end if;

  select enrollment.class_id
  into v_enrollment_class_id
  from public.enrollments as enrollment
  where enrollment.id = new.enrollment_id;

  if v_occurrence_class_id is distinct from
    v_enrollment_class_id
  then
    raise exception
      'Makeup participant must belong to the occurrence class';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_makeup_participant"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_session_occurrence_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_class_id uuid;
  v_roster_count integer;
  v_attendance_count integer;
begin

  if new.status = old.status then
    return new;
  end if;


  if not (
    (
      old.status = 'SCHEDULED'
      and new.status in (
        'COMPLETED',
        'CANCELLED'
      )
    )
    or
    (
      old.status in (
        'COMPLETED',
        'CANCELLED'
      )
      and new.status = 'SCHEDULED'
    )
  ) then
    raise exception
      'Invalid session status transition from % to %',
      old.status,
      new.status;
  end if;


  if new.status = 'CANCELLED' then

    select count(*)::integer
    into v_attendance_count
    from public.attendance_records
    where session_occurrence_id = old.id;


    if v_attendance_count > 0 then
      raise exception
        'A session with attendance records cannot be cancelled';
    end if;

  end if;


  if new.status = 'COMPLETED' then

    -- MAKEUP: explicit participant roster.
    if old.occurrence_type = 'MAKEUP' then

      select count(*)::integer
      into v_roster_count
      from public.session_occurrence_participants
      where session_occurrence_id = old.id;


      select count(*)::integer
      into v_attendance_count
      from public.attendance_records as attendance

      join public.session_occurrence_participants
        as participant
        on participant.session_occurrence_id =
          attendance.session_occurrence_id
        and participant.enrollment_id =
          attendance.enrollment_id

      where attendance.session_occurrence_id =
        old.id;

    -- REGULAR: dated roster.
    else

      select schedule.class_id
      into v_class_id
      from public.schedules as schedule
      where schedule.id = old.schedule_id;


      select count(*)::integer
      into v_roster_count
      from public.enrollments as enrollment

      where enrollment.class_id = v_class_id

        and enrollment.started_at is not null

        and enrollment.started_at <=
          old.occurrence_date

        and (
          enrollment.ended_at is null
          or enrollment.ended_at >=
            old.occurrence_date
        )

        and not public.is_enrollment_paused_on(
          enrollment.id,
          old.occurrence_date
        );


      select count(*)::integer
      into v_attendance_count
      from public.attendance_records as attendance

      join public.enrollments as enrollment
        on enrollment.id =
          attendance.enrollment_id

      where attendance.session_occurrence_id =
          old.id

        and enrollment.class_id =
          v_class_id

        and enrollment.started_at is not null

        and enrollment.started_at <=
          old.occurrence_date

        and (
          enrollment.ended_at is null
          or enrollment.ended_at >=
            old.occurrence_date
        )

        and not public.is_enrollment_paused_on(
          enrollment.id,
          old.occurrence_date
        );

    end if;


    if v_attendance_count <>
      v_roster_count
    then
      raise exception
        'All students in the session roster must be marked before completion';
    end if;

  end if;


  return new;
end;
$$;


ALTER FUNCTION "public"."validate_session_occurrence_status"() OWNER TO "postgres";


