CREATE OR REPLACE FUNCTION "public"."waiting_placement_summary"("p_branch" "uuid") RETURNS TABLE("waiting_count" integer, "unassigned_count" integer, "matching_count" integer, "scheduled_count" integer, "average_wait" numeric, "over_3" integer, "over_7" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with visible as (
    select
      public.registration_vietnam_today() - placement.opened_at::date as days,
      placement.status,
      placement.scheduled_start_date
    from public.student_placement_cases placement
    where public.registration_can('student_placement.view', placement.branch_id)
      and (p_branch is null or placement.branch_id = p_branch)
      and (
        placement.status in ('UNASSIGNED', 'MATCHING')
        or (
          placement.status = 'SCHEDULED'
          and placement.scheduled_start_date > public.registration_vietnam_today()
        )
      )
  ),
  waiting as (
    select * from visible where status in ('UNASSIGNED', 'MATCHING')
  )
  select
    (select count(*)::integer from waiting),
    (select count(*)::integer from waiting where status = 'UNASSIGNED'),
    (select count(*)::integer from waiting where status = 'MATCHING'),
    (select count(*)::integer from visible where status = 'SCHEDULED'),
    (select coalesce(round(avg(days), 1), 0) from waiting),
    (select count(*)::integer from waiting where days > 3),
    (select count(*)::integer from waiting where days > 7)
$$;


ALTER FUNCTION "public"."waiting_placement_summary"("p_branch" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wake_tuition_zalo_callbacks"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.send_status in ('SENT','DELIVERED') and old.send_status='PREPARED' then
    update integration_webhook_events set next_attempt_at=null where id in (
      select id from integration_webhook_events where provider='ZALO' and processed_at is null
      and payload->'message'->>'tracking_id'=new.tracking_id for update skip locked
    );
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."wake_tuition_zalo_callbacks"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."zalo_connection_evidence"("p_app" "text", "p_oa" "text", "p_source" "text" DEFAULT NULL::"text", "p_result" "text" DEFAULT NULL::"text", "p_http" integer DEFAULT NULL::integer, "p_error" integer DEFAULT NULL::integer, "p_match" boolean DEFAULT NULL::boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare result jsonb;
begin
 if p_result is not null then
  insert into notification_private.zalo_connection_checks(app_id,oa_id,source,result,http_status,provider_error,oa_matches)
  values(p_app,p_oa,p_source,p_result,p_http,p_error,p_match)
  on conflict(app_id,oa_id,source) do update set checked_at=clock_timestamp(),result=excluded.result,http_status=excluded.http_status,provider_error=excluded.provider_error,oa_matches=excluded.oa_matches;
 end if;
 select coalesce(jsonb_agg(to_jsonb(c) order by checked_at desc),'[]'::jsonb) into result from notification_private.zalo_connection_checks c where app_id=p_app and oa_id=p_oa;
 return result;
end $$;


ALTER FUNCTION "public"."zalo_connection_evidence"("p_app" "text", "p_oa" "text", "p_source" "text", "p_result" "text", "p_http" integer, "p_error" integer, "p_match" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."zalo_credential_command"("p_action" "text", "p_app" "text", "p_oa" "text", "p_version" bigint DEFAULT NULL::bigint, "p_operation" "uuid" DEFAULT NULL::"uuid", "p_access" "text" DEFAULT NULL::"text", "p_refresh" "text" DEFAULT NULL::"text", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_error" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare c notification_private.zalo_credentials; result jsonb;
begin
 if p_app is null or p_app !~ '^[0-9]{8,32}$' or p_oa is null or p_oa !~ '^[0-9]{8,32}$' then raise exception 'INVALID_IDENTITY'; end if;
 if p_action='BOOTSTRAP' then
  insert into notification_private.zalo_credentials(app_id,oa_id,access_token,refresh_token,expires_at,state,error_code)
  values(p_app,p_oa,notification_private.zalo_encrypt(nullif(p_access,'')),notification_private.zalo_encrypt(nullif(p_refresh,'')),p_expires_at,
   case when nullif(p_refresh,'') is null then 'REAUTH_REQUIRED' else 'NEEDS_REFRESH' end,
   case when nullif(p_refresh,'') is null then 'ZALO_REFRESH_TOKEN_MISSING' else null end)
  on conflict do nothing;
 end if;
 select * into c from notification_private.zalo_credentials where app_id=p_app and oa_id=p_oa for update;
 c.access_token := notification_private.zalo_decrypt(c.access_token);
 c.refresh_token := notification_private.zalo_decrypt(c.refresh_token);
 if p_action='READ' or p_action='BOOTSTRAP' then
  if c.app_id is null then return null; end if;
  return to_jsonb(c);
 end if;
 if p_action in ('REPLACE','REAUTH_CLAIM') and c.app_id is null and p_version=0 then
  insert into notification_private.zalo_credentials(app_id,oa_id,state) values(p_app,p_oa,'REAUTH_REQUIRED') on conflict do nothing;
  select * into c from notification_private.zalo_credentials where app_id=p_app and oa_id=p_oa for update;
  if c.version<>1 or c.access_token is not null then return jsonb_build_object('state','STALE'); end if;
 elsif c.version is distinct from p_version then return jsonb_build_object('state','STALE');
 end if;
 if p_action='REAUTH_CLAIM' then
  if p_operation is null then raise exception 'INVALID_OPERATION'; end if;
  if c.state='REFRESHING' and c.operation_started_at>clock_timestamp()-interval '1 minute' then return jsonb_build_object('state','BUSY'); end if;
  update notification_private.zalo_credentials set state='REFRESHING',operation_id=p_operation,operation_started_at=clock_timestamp(),error_code=null,updated_at=clock_timestamp() where app_id=p_app and oa_id=p_oa;
  return jsonb_build_object('state','CLAIMED','version',c.version);
 elsif p_action='CLAIM' then
  -- A lease is never stolen: a single-use refresh may already have been consumed.
  if c.state not in ('READY','NEEDS_REFRESH') or c.operation_id is not null then return jsonb_build_object('state','BUSY_OR_BLOCKED'); end if;
  if c.refresh_token is null or p_operation is null then return jsonb_build_object('state','REAUTH_REQUIRED'); end if;
  update notification_private.zalo_credentials set state='REFRESHING',operation_id=p_operation,
   operation_started_at=clock_timestamp(),error_code=null,updated_at=clock_timestamp() where app_id=p_app and oa_id=p_oa;
  return jsonb_build_object('state','CLAIMED');
 elsif p_action='COMMIT' then
  if c.committed_operation=p_operation and c.state='READY' then return jsonb_build_object('state','COMMITTED'); end if;
  if c.state<>'REFRESHING' or c.operation_id is distinct from p_operation then return jsonb_build_object('state','STALE'); end if;
 elsif p_action='REPLACE' then
  if c.refresh_token is not null and c.refresh_token=p_refresh then return jsonb_build_object('state','REAUTH_REQUIRED'); end if;
  -- Reauthorization must not race an in-flight refresh. An old uncertain lock can
  -- only be replaced explicitly after the 15s network timeout has passed.
  if c.state='REFRESHING' and c.operation_started_at>clock_timestamp()-interval '1 minute' then return jsonb_build_object('state','BUSY'); end if;
 elsif p_action='VERIFY' then
  if c.state<>'VERIFYING' then return jsonb_build_object('state','STALE'); end if;
  update notification_private.zalo_credentials set state='READY',error_code=null,updated_at=clock_timestamp() where app_id=p_app and oa_id=p_oa;
  return jsonb_build_object('state','VERIFIED');
 elsif p_action='BLOCK' then
  if p_error is null or p_error not in ('ZALO_TOKEN_INVALID','ZALO_PROOF_INVALID','ZALO_REFRESH_UNCERTAIN','ZALO_RECONNECT_REQUIRED','ZALO_REFRESH_TOKEN_MISSING') then raise exception 'INVALID_ERROR'; end if;
  if p_operation is null and c.state='REFRESHING' then return jsonb_build_object('state','STALE'); end if;
  if p_operation is not null and c.operation_id is distinct from p_operation then return jsonb_build_object('state','STALE'); end if;
  update notification_private.zalo_credentials set state=case
   when p_error='ZALO_TOKEN_INVALID' and refresh_token is not null then 'NEEDS_REFRESH'
   when p_error='ZALO_PROOF_INVALID' then 'PROOF_INVALID'
   when p_error='ZALO_REFRESH_UNCERTAIN' then 'UNCERTAIN' else 'REAUTH_REQUIRED' end,
   error_code=p_error,updated_at=clock_timestamp() where app_id=p_app and oa_id=p_oa;
  return jsonb_build_object('state','BLOCKED');
 else raise exception 'INVALID_COMMAND';
 end if;
 if nullif(btrim(p_access),'') is null or nullif(btrim(p_refresh),'') is null or length(p_access)>8192 or length(p_refresh)>8192 then raise exception 'INVALID_CREDENTIAL_PAIR'; end if;
 if (p_action='COMMIT' or p_expires_at is not null) and (p_expires_at is null or p_expires_at<=clock_timestamp() or p_expires_at>clock_timestamp()+interval '26 hours') then raise exception 'INVALID_EXPIRY'; end if;
 update notification_private.zalo_credentials set access_token=notification_private.zalo_encrypt(p_access),refresh_token=notification_private.zalo_encrypt(p_refresh),expires_at=p_expires_at,
  last_refreshed_at=case when p_action='COMMIT' then clock_timestamp() else last_refreshed_at end,
  refresh_expires_at=clock_timestamp()+interval '3 months',
  version=c.version+1,state=case when p_action='REPLACE' and p_expires_at is null then 'NEEDS_REFRESH' else 'VERIFYING' end,
  operation_id=null,operation_started_at=null,committed_operation=p_operation,error_code=null,updated_at=clock_timestamp()
 where app_id=p_app and oa_id=p_oa;
 return jsonb_build_object('state','COMMITTED');
end $_$;


ALTER FUNCTION "public"."zalo_credential_command"("p_action" "text", "p_app" "text", "p_oa" "text", "p_version" bigint, "p_operation" "uuid", "p_access" "text", "p_refresh" "text", "p_expires_at" timestamp with time zone, "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."zalo_integration_overview"() RETURNS TABLE("total_events" bigint, "events_today" bigint, "accepted_events" bigint, "pending_events" bigint, "failed_events" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or not public.has_role('SUPER_ADMIN') then
    raise exception 'Unauthorized';
  end if;
  return query
  select
    count(*)::bigint,
    count(*) filter (
      where (received_at at time zone 'Asia/Ho_Chi_Minh')::date = public.registration_vietnam_today()
    )::bigint,
    count(*) filter (where status = 'ACCEPTED')::bigint,
    count(*) filter (where processed_at is null and processing_error is null)::bigint,
    count(*) filter (where processing_error is not null)::bigint
  from public.integration_webhook_events
  where provider = 'ZALO';
end;
$$;


ALTER FUNCTION "public"."zalo_integration_overview"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."zalo_linked_customers"() RETURNS TABLE("link_id" "uuid", "entity_type" "text", "display_label" "text", "branch_name" "text", "linked_at" timestamp with time zone, "last_verified_at" timestamp with time zone, "link_status" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or not public.has_role('SUPER_ADMIN') then
    raise exception 'Unauthorized';
  end if;
  return query
  select
    link.id,
    case
      when link.registration_application_id is not null then 'REGISTRATION'
      when link.parent_id is not null then 'PARENT'
      else 'STUDENT'
    end,
    case
      when link.registration_application_id is not null then coalesce(nullif(btrim(app.student_name), ''), app.application_code)
      when link.student_id is not null then coalesce(nullif(btrim(student.full_name), ''), student.student_code)
      else coalesce(
        (select profile.full_name from public.profiles profile where profile.id = parent.user_id),
        parent.parent_code
      )
    end,
    case
      when app.id is not null then branch.name
      when student.id is not null then student_branch.name
      else null
    end,
    link.linked_at,
    link.last_verified_at,
    link.status
  from public.customer_channel_links link
  left join public.registration_applications app on app.id = link.registration_application_id
  left join public.branches branch on branch.id = app.branch_id
  left join public.parents parent on parent.id = link.parent_id
  left join public.students student on student.id = link.student_id
  left join public.branches student_branch on student_branch.id = student.default_branch_id
  where link.provider = 'ZALO'
  order by link.created_at desc
  limit 100;
end;
$$;


ALTER FUNCTION "public"."zalo_linked_customers"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."zalo_oauth_state"("p_action" "text", "p_hash" "text", "p_user" "uuid", "p_app" "text", "p_oa" "text", "p_verifier" "text" DEFAULT NULL::"text", "p_version" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare s notification_private.zalo_oauth_states;
begin
 if p_hash !~ '^[0-9a-f]{64}$' or not exists(select 1 from public.user_roles ur join public.roles r on r.id=ur.role_id where ur.user_id=p_user and r.code='SUPER_ADMIN') then raise exception 'OAUTH_DENIED'; end if;
 if p_action='CREATE' then
  if p_verifier is null or length(p_verifier)<>43 or p_version is null then raise exception 'OAUTH_INVALID'; end if;
  delete from notification_private.zalo_oauth_states where expires_at<clock_timestamp()-interval '1 day';
  insert into notification_private.zalo_oauth_states values(p_hash,p_user,p_app,p_oa,p_version,notification_private.zalo_encrypt(p_verifier),clock_timestamp()+interval '10 minutes',null);
  return jsonb_build_object('state','CREATED');
 elsif p_action='CONSUME' then
  select * into s from notification_private.zalo_oauth_states where state_hash=p_hash for update;
  if s.administrator is distinct from p_user or s.app_id is distinct from p_app or s.oa_id is distinct from p_oa or s.consumed_at is not null or s.expires_at<=clock_timestamp() then raise exception 'OAUTH_INVALID'; end if;
  update notification_private.zalo_oauth_states set consumed_at=clock_timestamp() where state_hash=p_hash;
  return jsonb_build_object('verifier',notification_private.zalo_decrypt(s.verifier),'version',s.version);
 end if;
 raise exception 'OAUTH_INVALID';
end $_$;


ALTER FUNCTION "public"."zalo_oauth_state"("p_action" "text", "p_hash" "text", "p_user" "uuid", "p_app" "text", "p_oa" "text", "p_verifier" "text", "p_version" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."zalo_recent_events"("p_limit" integer) RETURNS TABLE("id" "uuid", "received_at" timestamp with time zone, "event_type" "text", "external_event_id" "text", "status" "text", "processing_state" "text", "processing_error" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or not public.has_role('SUPER_ADMIN') then
    raise exception 'Unauthorized';
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 50 then
    raise exception 'Limit out of range';
  end if;
  return query
  select
    event.id,
    event.received_at,
    event.event_type,
    event.external_event_id,
    event.status,
    case
      when event.processing_error is not null then 'FAILED'
      when event.processed_at is not null then 'PROCESSED'
      else 'PENDING'
    end,
    event.processing_error
  from public.integration_webhook_events event
  where event.provider = 'ZALO'
  order by event.received_at desc, event.id desc
  limit p_limit;
end;
$$;


ALTER FUNCTION "public"."zalo_recent_events"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."zalo_registration_recovery"("p_job" "uuid", "p_action" "text" DEFAULT 'VIEW'::"text", "p_expected" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare j notification_jobs; a registration_applications; c registration_zalo_phone_consents; reason text; mode text:='BLOCKED'; ord bigint; d record; h jsonb;
begin
 if auth.uid() is null or not has_role('SUPER_ADMIN') then raise exception 'Unauthorized'; end if;
 if p_action not in ('VIEW','CHECK','PREPARE') then raise exception 'Invalid action'; end if;
 select * into j from notification_jobs where id=p_job and channel='ZALO' and entity_type='REGISTRATION_COMPLETED' for update;
 if not found then raise exception 'Unauthorized'; end if;
 select * into a from registration_applications where id=j.entity_id;
 -- SUPER_ADMIN is the existing cross-branch recovery role; do not widen it.
 if a.id is null or a.branch_id is distinct from j.branch_id then raise exception 'Unauthorized'; end if;
 if p_action='PREPARE' and (p_expected is null or p_expected<>j.attempts) then return jsonb_build_object('state','BLOCKED','reason','STALE_ACTION','attempts',j.attempts,'jobId',j.id,'applicationId',a.id); end if;
 if p_action in ('CHECK','PREPARE') and j.attempts=0 and j.sent_at is null and j.provider_message_id is null and not exists(select 1 from zalo_notification_attempts where job_id=j.id) and not exists(select 1 from notification_events where job_id=j.id and event in ('CLAIMED','SENT','FAILED')) then
   perform reevaluate_registration_zalo_channel(a.id);
   select * into j from notification_jobs where id=p_job;
 end if;
 select * into c from registration_zalo_phone_consents where application_id=a.id and revoked_at is null;
 select coalesce(jsonb_agg(jsonb_build_object('number',attempt_number,'state',state,'http',http_status,'providerError',provider_error) order by attempt_number),'[]'::jsonb) into h from zalo_notification_attempts where job_id=j.id;
 if j.status='DELIVERED' or j.delivered_at is not null then mode:='DELIVERED'; reason:='DELIVERED';
 elsif j.status='SENT' or j.sent_at is not null or j.provider_message_id is not null then mode:='ACCEPTED'; reason:='ACCEPTED';
 elsif j.status in ('PROCESSING','ACCEPTANCE_UNKNOWN') or (not exists(select 1 from zalo_notification_attempts where job_id=j.id) and exists(select 1 from notification_events where job_id=j.id and event in ('CLAIMED','SENT'))) or exists(select 1 from zalo_notification_attempts where job_id=j.id and state in ('REQUESTING','UNKNOWN','ACCEPTED')) then mode:='UNCERTAIN'; reason:='ZALO_ACCEPTANCE_UNKNOWN';
 elsif a.status<>'COMPLETED' then reason:='NOT_SENDABLE';
 elsif c.id is null then reason:='NO_CONSENT';
 elsif j.payload->'delivery'->>'channel' is distinct from 'PHONE' then reason:='CHANNEL_SNAPSHOT_REQUIRED';
 elsif j.payload->'delivery'->>'consent_id' is distinct from c.id::text or j.payload->'delivery'->>'normalized_recipient' is distinct from c.normalized_phone then reason:='WRONG_RECIPIENT';
 elsif not exists(select 1 from notification_templates where template_key=j.template_key and provider='ZALO' and enabled and status='APPROVED' and provider_template_id='640377') then reason:='GATE_DISABLED';
 else
   select order_code into ord from registration_payos_orders where application_id=a.id and state='PAID' order by paid_at desc limit 1;
   if notification_private.zalo_retry_eligible(j.id) then
     mode:='RETRY'; reason:='CHANNEL_READY';
     if p_action='PREPARE' then
       perform prepare_zalo_registration_retry(j.id);
       select * into d from preview_zalo_dispatch_decision(ord);
       if d.decision is distinct from 'SEND' then mode:='BLOCKED';reason:=coalesce(d.decision,'NOT_SENDABLE'); end if;
     end if;
   else
     select * into d from preview_zalo_dispatch_decision(ord);
     if d.decision='SEND' and d.job_id=j.id and j.attempts=0 and not exists(select 1 from notification_events where job_id=j.id and event in ('CLAIMED','SENT','FAILED')) then mode:='SEND';reason:='CHANNEL_READY';
     else reason:=case when j.attempts>0 then 'ZALO_RETRY_DENIED' else coalesce(d.decision,'NOT_SENDABLE') end; end if;
   end if;
 end if;
 return jsonb_build_object('state',mode,'reason',reason,'jobId',j.id,'applicationId',a.id,'attempts',j.attempts,'orderCode',ord,
 'consentedPhone',case when c.id is not null then left(c.normalized_phone,4)||'…'||right(c.normalized_phone,3) end,
 'snapshotPhone',case when j.payload->'delivery'->>'normalized_recipient' is not null then left(j.payload->'delivery'->>'normalized_recipient',4)||'…'||right(j.payload->'delivery'->>'normalized_recipient',3) end,'history',h);
end $$;


ALTER FUNCTION "public"."zalo_registration_recovery"("p_job" "uuid", "p_action" "text", "p_expected" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."zalo_scheduler_health"("p_result" "text" DEFAULT NULL::"text", "p_interval" integer DEFAULT 600) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
begin
 if p_result is not null then
  if p_result !~ '^[A-Z][A-Z0-9_-]{1,79}$' or p_interval<60 or p_interval>3600 then raise exception 'INVALID_HEALTH'; end if;
  insert into notification_private.zalo_scheduler values(true,clock_timestamp(),p_result,clock_timestamp()+make_interval(secs=>p_interval))
  on conflict(id) do update set checked_at=excluded.checked_at,result=excluded.result,next_check_at=excluded.next_check_at;
 end if;
 return (select to_jsonb(s)-'id' from notification_private.zalo_scheduler s where id);
end $_$;


ALTER FUNCTION "public"."zalo_scheduler_health"("p_result" "text", "p_interval" integer) OWNER TO "postgres";


