    AS $$
  select auth.uid() is not null and coalesce(public.account_is_active(), false)
    and (
      coalesce(public.has_role('SUPER_ADMIN'), false)
      or coalesce(public.has_role_permission('FINANCE', 'payroll.approve', p_branch), false)
    );
$$;


