CREATE OR REPLACE FUNCTION "vibe_expense_private"."record_event"("p_claim" "uuid", "p_key" "uuid", "p_payload" "jsonb", "p_event" "text", "p_before" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
declare result jsonb; after_data jsonb;
begin
  after_data := vibe_expense_private.snapshot(p_claim);
  result := jsonb_build_object(
    'claim_id',p_claim,'status',after_data->'claim'->>'status',
    'version',(after_data->'claim'->>'version')::integer,
    'total_amount',after_data->'total_amount',
    'approved_amount',after_data->'claim'->'approved_amount',
    'payroll_integration','NOT_ENABLED_IN_PHASE_1'
  );
  insert into public.employee_expense_claim_events(
    claim_id,event_type,actor_id,request_key,request_payload,before_snapshot,after_snapshot,result
  ) values(p_claim,p_event,auth.uid(),p_key,p_payload,p_before,after_data,result);
  return result;
end;
$$;


ALTER FUNCTION "vibe_expense_private"."record_event"("p_claim" "uuid", "p_key" "uuid", "p_payload" "jsonb", "p_event" "text", "p_before" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vibe_expense_private"."replay"("p_key" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
declare ev public.employee_expense_claim_events;
begin
  if auth.uid() is null or p_key is null then raise exception 'EXPENSE_REQUEST_KEY_REQUIRED'; end if;
  perform pg_advisory_xact_lock(hashtextextended('vibe_expense:'||auth.uid()::text||':'||p_key::text,0));
  select * into ev from public.employee_expense_claim_events
    where actor_id=auth.uid() and request_key=p_key;
  if found then
    if ev.request_payload is distinct from p_payload then raise exception 'EXPENSE_REQUEST_KEY_REUSED'; end if;
    return ev.result;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "vibe_expense_private"."replay"("p_key" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vibe_expense_private"."snapshot"("p_claim" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'claim', to_jsonb(c) - 'submitted_snapshot',
    'trip', case when c.trip_id is null then null else
      (select jsonb_build_object('id',t.id,'starts_on',t.starts_on,'ends_on',t.ends_on,
        'reason',t.reason,'destination_unit',t.destination_unit)
       from public.employee_trips t where t.id=c.trip_id) end,
    'lines', case when c.claim_model='LEGACY_TRIP_SUMMARY' then
      coalesce((select jsonb_agg(to_jsonb(l) order by l.id)
        from public.employee_expense_claim_lines l where l.claim_id=c.id), '[]'::jsonb)
      else '[]'::jsonb end,
    'items', case when c.claim_model='ITEMIZED_V2' then
      coalesce((select jsonb_agg(to_jsonb(i) order by i.expense_date,i.id)
        from public.employee_expense_claim_items_v2 i where i.claim_id=c.id), '[]'::jsonb)
      else '[]'::jsonb end,
    'category_breakdown', case when c.claim_model='ITEMIZED_V2' then
      coalesce((select jsonb_agg(jsonb_build_object('category_name',x.category_name,'amount',x.amount) order by x.category_name)
        from (select i.category_name,sum(i.amount) amount from public.employee_expense_claim_items_v2 i
          where i.claim_id=c.id group by i.category_name) x), '[]'::jsonb)
      else '[]'::jsonb end,
    'total_amount', case when c.claim_model='ITEMIZED_V2' then
      coalesce((select sum(i.amount) from public.employee_expense_claim_items_v2 i where i.claim_id=c.id),0)
      else coalesce((select sum(l.total_amount) from public.employee_expense_claim_lines l where l.claim_id=c.id),0) end,
    'payroll_posting', coalesce((select jsonb_build_object(
        'action_id',a.id,'period_id',a.period_id,'status',a.status,'created_at',a.created_at
      ) from public.payroll_period_actions_v2 a
      where a.source_expense_claim_id=c.id and a.status='ACTIVE'
      order by a.created_at desc limit 1), jsonb_build_object('status','NOT_POSTED')),
    'payment_status','NO_AUTHORITATIVE_PAYMENT_EVIDENCE'
  ) from public.employee_expense_claims c where c.id=p_claim;
$$;


ALTER FUNCTION "vibe_expense_private"."snapshot"("p_claim" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vibe_expense_private"."validate_submission"("p_claim" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
declare c public.employee_expense_claims; total numeric; number_lines integer;
begin
  select * into strict c from public.employee_expense_claims where id=p_claim;
  select count(*),coalesce(sum(total_amount),0) into number_lines,total
    from public.employee_expense_claim_lines where claim_id=p_claim;
  if number_lines=0 or total<=0 then raise exception 'EXPENSE_NONEMPTY_POSITIVE_CLAIM_REQUIRED'; end if;
  if exists(select 1 from public.employee_expense_claim_lines l where l.claim_id=p_claim
    and (l.total_amount<=0 or not l.reservation_active)) then raise exception 'EXPENSE_POSITIVE_LINES_REQUIRED'; end if;
  if exists(select 1 from public.employee_expense_claim_lines l where l.claim_id=p_claim
    and (l.transport>0 or l.lodging>0) and nullif(btrim(l.evidence_reference),'') is null) then
    raise exception 'EXPENSE_TRANSPORT_LODGING_EVIDENCE_REQUIRED';
  end if;
  if exists(
    select 1 from public.employee_expense_claim_lines l
    left join public.employee_trips t on t.id=l.trip_id
    left join public.employee_trip_reviews r on r.trip_id=t.id and r.decision='APPROVED'
    where l.claim_id=p_claim and (
      t.id is null or t.employee_id is distinct from c.employee_id or r.id is null
      or t.ends_on>(now() at time zone 'Asia/Ho_Chi_Minh')::date
      or not l.reservation_active
      or l.trip_snapshot is distinct from jsonb_build_object('trip',to_jsonb(t),'review',to_jsonb(r))
    )
  ) then raise exception 'EXPENSE_TRIP_EVIDENCE_CHANGED_OR_NOT_FINISHED'; end if;
  if exists(select 1 from public.employee_expense_claim_lines l join public.payroll_adjustments a
    on a.trip_id=l.trip_id and a.kind='TRAVEL_ALLOWANCE' where l.claim_id=p_claim) then
    raise exception 'EXPENSE_TRIP_ALREADY_IN_PAYROLL';
  end if;
  return total;
end;
$$;


ALTER FUNCTION "vibe_expense_private"."validate_submission"("p_claim" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vibe_expense_private"."validate_submission_v2"("p_claim" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
declare c public.employee_expense_claims; total numeric; item_count integer;
begin
  select * into strict c from public.employee_expense_claims where id=p_claim and claim_model='ITEMIZED_V2';
  if not exists(select 1 from public.employee_trips t join public.employee_trip_reviews r on r.trip_id=t.id and r.decision='APPROVED' where t.id=c.trip_id and t.employee_id=c.employee_id) then
    raise exception 'EXPENSE_APPROVED_OWN_TRIP_REQUIRED';
  end if;
  select count(*)::integer,coalesce(sum(amount),0) into item_count,total from public.employee_expense_claim_items_v2 where claim_id=p_claim;
  if item_count=0 or total<=0 then raise exception 'EXPENSE_NONEMPTY_POSITIVE_CLAIM_REQUIRED'; end if;
  if total>999999999999.99 then raise exception 'EXPENSE_TOTAL_TOO_LARGE'; end if;
  return total;
end;
$$;


ALTER FUNCTION "vibe_expense_private"."validate_submission_v2"("p_claim" "uuid") OWNER TO "postgres";


