    CONSTRAINT "payments_void_state_check" CHECK (((("status" = 'POSTED'::"text") AND ("voided_at" IS NULL) AND ("voided_by" IS NULL) AND ("void_reason" IS NULL)) OR (("status" = 'VOIDED'::"text") AND ("voided_at" IS NOT NULL) AND ("void_reason" IS NOT NULL) AND ("btrim"("void_reason") <> ''::"text"))))
);


