CREATE OR REPLACE VIEW "public"."finance_cash_ledger" WITH ("security_invoker"='true') AS
 SELECT "payment"."id" AS "transaction_id",
    "payment"."payment_number" AS "transaction_number",
    'PAYMENT'::"text" AS "transaction_type",
    "payment"."student_id_snapshot" AS "student_id",
    "payment"."branch_id_snapshot" AS "branch_id",
    "payment"."branch_code_snapshot" AS "branch_code",
    "payment"."branch_name_snapshot" AS "branch_name",
    "payment"."currency",
    "payment"."paid_at" AS "occurred_at",
    ("timezone"('Asia/Ho_Chi_Minh'::"text", "payment"."paid_at"))::"date" AS "occurred_on",
    ("date_trunc"('month'::"text", "timezone"('Asia/Ho_Chi_Minh'::"text", "payment"."paid_at")))::"date" AS "month_start",
    "payment"."amount" AS "cash_in",
    (0)::numeric(14,2) AS "cash_out",
    "payment"."amount" AS "net_cash",
    "payment"."payment_method",
    "payment"."reference",
    "payment"."notes"
   FROM "public"."payments" "payment"
  WHERE ("payment"."status" = 'POSTED'::"text")
UNION ALL
 SELECT "refund"."id" AS "transaction_id",
    "refund"."refund_number" AS "transaction_number",
    'REFUND'::"text" AS "transaction_type",
    "refund"."student_id_snapshot" AS "student_id",
    "refund"."branch_id_snapshot" AS "branch_id",
    "refund"."branch_code_snapshot" AS "branch_code",
    "refund"."branch_name_snapshot" AS "branch_name",
    "refund"."currency",
    "refund"."refunded_at" AS "occurred_at",
    ("timezone"('Asia/Ho_Chi_Minh'::"text", "refund"."refunded_at"))::"date" AS "occurred_on",
    ("date_trunc"('month'::"text", "timezone"('Asia/Ho_Chi_Minh'::"text", "refund"."refunded_at")))::"date" AS "month_start",
    (0)::numeric(14,2) AS "cash_in",
    "refund"."amount" AS "cash_out",
    (((0)::numeric - "refund"."amount"))::numeric(14,2) AS "net_cash",
    NULL::"text" AS "payment_method",
    NULL::"text" AS "reference",
    "refund"."notes"
   FROM "public"."refunds" "refund"
  WHERE ("refund"."status" = 'POSTED'::"text");


ALTER VIEW "public"."finance_cash_ledger" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."branch_daily_cash_summary" WITH ("security_invoker"='true') AS
 SELECT "branch_id",
    "branch_code",
    "branch_name",
    "currency",
    "occurred_on",
    "count"(*) FILTER (WHERE ("transaction_type" = 'PAYMENT'::"text")) AS "payment_count",
    "count"(*) FILTER (WHERE ("transaction_type" = 'REFUND'::"text")) AS "refund_count",
    (COALESCE("sum"("cash_in"), (0)::numeric))::numeric(14,2) AS "cash_in",
    (COALESCE("sum"("cash_out"), (0)::numeric))::numeric(14,2) AS "cash_out",
    (COALESCE("sum"("net_cash"), (0)::numeric))::numeric(14,2) AS "net_cash"
   FROM "public"."finance_cash_ledger" "ledger"
  GROUP BY "branch_id", "branch_code", "branch_name", "currency", "occurred_on";


