CREATE OR REPLACE VIEW "public"."invoice_receivables" WITH ("security_invoker"='true') AS
 SELECT "invoice"."id" AS "invoice_id",
    "invoice"."invoice_number",
    "invoice"."enrollment_tuition_id",
    "invoice"."enrollment_id_snapshot",
    "invoice"."student_id_snapshot",
    "invoice"."branch_id_snapshot",
    "invoice"."branch_code_snapshot",
    "invoice"."branch_name_snapshot",
    "invoice"."currency",
    "invoice"."total_amount",
    "invoice"."status" AS "invoice_status",
    "invoice"."issued_on",
    "invoice"."due_on",
    (GREATEST((COALESCE("payment_totals"."gross_allocated_amount", (0)::numeric) - COALESCE("refund_totals"."refunded_amount", (0)::numeric)), (0)::numeric))::numeric(14,2) AS "allocated_amount",
    (GREATEST(("invoice"."total_amount" - GREATEST((COALESCE("payment_totals"."gross_allocated_amount", (0)::numeric) - COALESCE("refund_totals"."refunded_amount", (0)::numeric)), (0)::numeric)), (0)::numeric))::numeric(14,2) AS "outstanding_balance",
        CASE
            WHEN ("invoice"."status" = 'DRAFT'::"text") THEN 'DRAFT'::"text"
            WHEN ("invoice"."status" = 'CANCELLED'::"text") THEN 'CANCELLED'::"text"
            WHEN (GREATEST(("invoice"."total_amount" - GREATEST((COALESCE("payment_totals"."gross_allocated_amount", (0)::numeric) - COALESCE("refund_totals"."refunded_amount", (0)::numeric)), (0)::numeric)), (0)::numeric) = (0)::numeric) THEN 'PAID'::"text"
            WHEN ("invoice"."due_on" < ("timezone"('Asia/Ho_Chi_Minh'::"text", "now"()))::"date") THEN 'OVERDUE'::"text"
            WHEN (GREATEST((COALESCE("payment_totals"."gross_allocated_amount", (0)::numeric) - COALESCE("refund_totals"."refunded_amount", (0)::numeric)), (0)::numeric) > (0)::numeric) THEN 'PARTIALLY_PAID'::"text"
            ELSE 'UNPAID'::"text"
        END AS "receivable_status",
        CASE
            WHEN (("invoice"."status" = 'ISSUED'::"text") AND (GREATEST(("invoice"."total_amount" - GREATEST((COALESCE("payment_totals"."gross_allocated_amount", (0)::numeric) - COALESCE("refund_totals"."refunded_amount", (0)::numeric)), (0)::numeric)), (0)::numeric) > (0)::numeric) AND ("invoice"."due_on" < ("timezone"('Asia/Ho_Chi_Minh'::"text", "now"()))::"date")) THEN true
            ELSE false
        END AS "is_overdue",
        CASE
            WHEN (("invoice"."status" = 'ISSUED'::"text") AND (GREATEST(("invoice"."total_amount" - GREATEST((COALESCE("payment_totals"."gross_allocated_amount", (0)::numeric) - COALESCE("refund_totals"."refunded_amount", (0)::numeric)), (0)::numeric)), (0)::numeric) > (0)::numeric) AND ("invoice"."due_on" < ("timezone"('Asia/Ho_Chi_Minh'::"text", "now"()))::"date")) THEN (("timezone"('Asia/Ho_Chi_Minh'::"text", "now"()))::"date" - "invoice"."due_on")
            ELSE 0
        END AS "days_overdue",
    "invoice"."created_at",
    "invoice"."updated_at",
    (COALESCE("payment_totals"."gross_allocated_amount", (0)::numeric))::numeric(14,2) AS "gross_allocated_amount",
    (COALESCE("refund_totals"."refunded_amount", (0)::numeric))::numeric(14,2) AS "refunded_amount"
   FROM (("public"."invoices" "invoice"
     LEFT JOIN LATERAL ( SELECT (COALESCE("sum"("allocation"."amount"), (0)::numeric))::numeric(14,2) AS "gross_allocated_amount"
           FROM ("public"."payment_allocations" "allocation"
             JOIN "public"."payments" "payment" ON (("payment"."id" = "allocation"."payment_id")))
          WHERE (("allocation"."invoice_id" = "invoice"."id") AND ("payment"."status" = 'POSTED'::"text"))) "payment_totals" ON (true))
     LEFT JOIN LATERAL ( SELECT (COALESCE("sum"("refund_allocation"."amount"), (0)::numeric))::numeric(14,2) AS "refunded_amount"
           FROM ((("public"."refund_allocations" "refund_allocation"
             JOIN "public"."refunds" "refund" ON (("refund"."id" = "refund_allocation"."refund_id")))
             JOIN "public"."payment_allocations" "allocation" ON (("allocation"."id" = "refund_allocation"."payment_allocation_id")))
             JOIN "public"."payments" "payment" ON (("payment"."id" = "allocation"."payment_id")))
          WHERE (("allocation"."invoice_id" = "invoice"."id") AND ("payment"."status" = 'POSTED'::"text") AND ("refund"."status" = 'POSTED'::"text"))) "refund_totals" ON (true));


ALTER VIEW "public"."invoice_receivables" OWNER TO "postgres";


