    CONSTRAINT "opening_receivable_corrections_check" CHECK ((("delta" <> (0)::numeric) AND ("delta" = ("corrected_amount" - "old_amount")))),
    CONSTRAINT "opening_receivable_corrections_corrected_amount_check" CHECK (("corrected_amount" >= (0)::numeric))
);


ALTER TABLE "public"."opening_receivable_corrections" OWNER TO "postgres";


