CREATE OR REPLACE VIEW "public"."payment_allocation_effective" WITH ("security_invoker"='true') AS
 SELECT "a"."id",
    "a"."payment_id",
    "a"."invoice_id",
    "a"."amount",
    "a"."created_by",
    "a"."created_at",
    "a"."opening_receivable_id",
    "a"."credit_use_id",
    (COALESCE("c"."released", (0)::numeric))::numeric(14,2) AS "released_to_credit",
    (("a"."amount" - COALESCE("c"."released", (0)::numeric)))::numeric(14,2) AS "effective_amount"
   FROM ("public"."payment_allocations" "a"
     LEFT JOIN LATERAL ( SELECT "sum"("customer_credits"."amount") AS "released"
           FROM "public"."customer_credits"
          WHERE ("customer_credits"."source_allocation_id" = "a"."id")) "c" ON (true));


ALTER VIEW "public"."payment_allocation_effective" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."opening_receivable_balances" WITH ("security_invoker"='true') AS
 SELECT "r"."id",
    "r"."migration_row_id",
    "r"."tuition_id",
    "r"."enrollment_id",
    "r"."student_id",
    "r"."branch_id",
    "r"."opening_as_of_date",
    "r"."currency",
    "r"."amount",
    "r"."origin",
    "r"."transaction_type",
    "r"."created_at",
    (COALESCE("s"."amount", (0)::numeric))::numeric(14,2) AS "opening_paid_amount",
    ((((((("r"."amount" - COALESCE("v"."reversed_amount", (0)::numeric)) + COALESCE("c"."delta", (0)::numeric)) + COALESCE("sc"."released", (0)::numeric)) - COALESCE("s"."amount", (0)::numeric)) + COALESCE("v"."reversed_settlement", (0)::numeric)) - COALESCE("a"."net_paid", (0)::numeric)))::numeric(14,2) AS "outstanding_balance",
    ("v"."receivable_id" IS NOT NULL) AS "reversed",
    (("r"."amount" - COALESCE("v"."reversed_amount", (0)::numeric)))::numeric(14,2) AS "net_opening_amount",
    ((COALESCE("s"."amount", (0)::numeric) - COALESCE("v"."reversed_settlement", (0)::numeric)))::numeric(14,2) AS "net_opening_paid",
    (COALESCE("c"."delta", (0)::numeric))::numeric(14,2) AS "correction_amount",
    (COALESCE("a"."gross_paid", (0)::numeric))::numeric(14,2) AS "post_cutover_allocated",
    (COALESCE("a"."refunded", (0)::numeric))::numeric(14,2) AS "post_cutover_refunded",
    (COALESCE("a"."net_paid", (0)::numeric))::numeric(14,2) AS "post_cutover_net_paid",
    (0)::numeric(14,2) AS "new_revenue_from_collection"
   FROM ((((("public"."opening_receivables" "r"
     LEFT JOIN "public"."opening_settlements" "s" ON (("s"."receivable_id" = "r"."id")))
     LEFT JOIN "public"."opening_reversals" "v" ON (("v"."receivable_id" = "r"."id")))
     LEFT JOIN LATERAL ( SELECT "sum"("customer_credits"."amount") AS "released"
           FROM "public"."customer_credits"
          WHERE ("customer_credits"."settlement_id" = "s"."id")) "sc" ON (true))
     LEFT JOIN LATERAL ( SELECT "sum"("opening_receivable_corrections"."delta") AS "delta"
           FROM "public"."opening_receivable_corrections"
          WHERE ("opening_receivable_corrections"."opening_receivable_id" = "r"."id")) "c" ON (true))
     LEFT JOIN LATERAL ( SELECT "sum"("pa"."effective_amount") AS "gross_paid",
            "sum"(COALESCE("ra"."amount", (0)::numeric)) AS "refunded",
            "sum"(("pa"."effective_amount" - COALESCE("ra"."amount", (0)::numeric))) AS "net_paid"
           FROM (("public"."payment_allocation_effective" "pa"
             JOIN "public"."payments" "p" ON ((("p"."id" = "pa"."payment_id") AND ("p"."status" = 'POSTED'::"text"))))
             LEFT JOIN LATERAL ( SELECT "sum"("a_1"."amount") AS "amount"
                   FROM ("public"."refund_allocations" "a_1"
                     JOIN "public"."refunds" "f" ON ((("f"."id" = "a_1"."refund_id") AND ("f"."status" = 'POSTED'::"text"))))
                  WHERE ("a_1"."payment_allocation_id" = "pa"."id")) "ra" ON (true))
          WHERE ("pa"."opening_receivable_id" = "r"."id")) "a" ON (true));


ALTER VIEW "public"."opening_receivable_balances" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."standard_branch_finance_summary" WITH ("security_invoker"='true') AS
 WITH "receivables" AS (
         SELECT "receivable"."branch_id_snapshot" AS "branch_id",
            "receivable"."branch_code_snapshot" AS "branch_code",
            "receivable"."branch_name_snapshot" AS "branch_name",
            "receivable"."currency",
            "count"(*) FILTER (WHERE ("receivable"."invoice_status" = 'ISSUED'::"text")) AS "issued_invoice_count",
            "count"(*) FILTER (WHERE ("receivable"."receivable_status" = 'OVERDUE'::"text")) AS "overdue_invoice_count",
            (COALESCE("sum"("receivable"."total_amount") FILTER (WHERE ("receivable"."invoice_status" = 'ISSUED'::"text")), (0)::numeric))::numeric(14,2) AS "billed_amount",
            (COALESCE("sum"("receivable"."allocated_amount") FILTER (WHERE ("receivable"."invoice_status" = 'ISSUED'::"text")), (0)::numeric))::numeric(14,2) AS "applied_payment_amount",
            (COALESCE("sum"("receivable"."outstanding_balance") FILTER (WHERE ("receivable"."invoice_status" = 'ISSUED'::"text")), (0)::numeric))::numeric(14,2) AS "outstanding_amount",
            (COALESCE("sum"("receivable"."outstanding_balance") FILTER (WHERE ("receivable"."receivable_status" = 'OVERDUE'::"text")), (0)::numeric))::numeric(14,2) AS "overdue_amount"
           FROM "public"."invoice_receivables" "receivable"
          GROUP BY "receivable"."branch_id_snapshot", "receivable"."branch_code_snapshot", "receivable"."branch_name_snapshot", "receivable"."currency"
        ), "cash" AS (
         SELECT "ledger"."branch_id",
            "ledger"."branch_code",
            "ledger"."branch_name",
            "ledger"."currency",
            (COALESCE("sum"("ledger"."cash_in"), (0)::numeric))::numeric(14,2) AS "cash_received",
            (COALESCE("sum"("ledger"."cash_out"), (0)::numeric))::numeric(14,2) AS "cash_refunded",
            (COALESCE("sum"("ledger"."net_cash"), (0)::numeric))::numeric(14,2) AS "net_cash"
           FROM "public"."finance_cash_ledger" "ledger"
          GROUP BY "ledger"."branch_id", "ledger"."branch_code", "ledger"."branch_name", "ledger"."currency"
        )
 SELECT COALESCE("receivables"."branch_id", "cash"."branch_id") AS "branch_id",
    COALESCE("receivables"."branch_code", "cash"."branch_code") AS "branch_code",
    COALESCE("receivables"."branch_name", "cash"."branch_name") AS "branch_name",
    COALESCE("receivables"."currency", "cash"."currency") AS "currency",
    COALESCE("receivables"."issued_invoice_count", (0)::bigint) AS "issued_invoice_count",
    COALESCE("receivables"."overdue_invoice_count", (0)::bigint) AS "overdue_invoice_count",
    (COALESCE("receivables"."billed_amount", (0)::numeric))::numeric(14,2) AS "billed_amount",
    (COALESCE("receivables"."applied_payment_amount", (0)::numeric))::numeric(14,2) AS "applied_payment_amount",
    (COALESCE("receivables"."outstanding_amount", (0)::numeric))::numeric(14,2) AS "outstanding_amount",
    (COALESCE("receivables"."overdue_amount", (0)::numeric))::numeric(14,2) AS "overdue_amount",
    (COALESCE("cash"."cash_received", (0)::numeric))::numeric(14,2) AS "cash_received",
    (COALESCE("cash"."cash_refunded", (0)::numeric))::numeric(14,2) AS "cash_refunded",
    (COALESCE("cash"."net_cash", (0)::numeric))::numeric(14,2) AS "net_cash"
   FROM ("receivables"
     FULL JOIN "cash" ON ((("cash"."branch_id" = "receivables"."branch_id") AND ("cash"."currency" = "receivables"."currency"))));


ALTER VIEW "public"."standard_branch_finance_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."branch_finance_summary" WITH ("security_invoker"='true') AS
 SELECT "branch_id",
    "branch_code",
    "branch_name",
    "currency",
    ("sum"("issued_invoice_count"))::bigint AS "issued_invoice_count",
    ("sum"("overdue_invoice_count"))::bigint AS "overdue_invoice_count",
    ("sum"("billed_amount"))::numeric(14,2) AS "billed_amount",
    ("sum"("applied_payment_amount"))::numeric(14,2) AS "applied_payment_amount",
    ("sum"("outstanding_amount"))::numeric(14,2) AS "outstanding_amount",
    ("sum"("overdue_amount"))::numeric(14,2) AS "overdue_amount",
    ("sum"("cash_received"))::numeric(14,2) AS "cash_received",
    ("sum"("cash_refunded"))::numeric(14,2) AS "cash_refunded",
    ("sum"("net_cash"))::numeric(14,2) AS "net_cash"
   FROM ( SELECT "standard_branch_finance_summary"."branch_id",
            "standard_branch_finance_summary"."branch_code",
            "standard_branch_finance_summary"."branch_name",
            "standard_branch_finance_summary"."currency",
            "standard_branch_finance_summary"."issued_invoice_count",
            "standard_branch_finance_summary"."overdue_invoice_count",
            "standard_branch_finance_summary"."billed_amount",
            "standard_branch_finance_summary"."applied_payment_amount",
            "standard_branch_finance_summary"."outstanding_amount",
            "standard_branch_finance_summary"."overdue_amount",
            "standard_branch_finance_summary"."cash_received",
            "standard_branch_finance_summary"."cash_refunded",
            "standard_branch_finance_summary"."net_cash"
           FROM "public"."standard_branch_finance_summary"
        UNION ALL
         SELECT "o"."branch_id",
            "b"."code",
            "b"."name",
            "o"."currency",
            (0)::bigint AS "int8",
            (0)::bigint AS "int8",
            (0)::numeric(14,2) AS "numeric",
            (0)::numeric(14,2) AS "numeric",
            "o"."outstanding_balance",
            (0)::numeric(14,2) AS "numeric",
            (0)::numeric(14,2) AS "numeric",
            (0)::numeric(14,2) AS "numeric",
            (0)::numeric(14,2) AS "numeric"
           FROM ("public"."opening_receivable_balances" "o"
             JOIN "public"."branches" "b" ON (("b"."id" = "o"."branch_id")))
          WHERE (NOT "o"."reversed")) "combined"
  GROUP BY "branch_id", "branch_code", "branch_name", "currency";


ALTER VIEW "public"."branch_finance_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."branch_monthly_cash_summary" WITH ("security_invoker"='true') AS
 SELECT "branch_id",
    "branch_code",
    "branch_name",
    "currency",
    "month_start",
    "count"(*) FILTER (WHERE ("transaction_type" = 'PAYMENT'::"text")) AS "payment_count",
    "count"(*) FILTER (WHERE ("transaction_type" = 'REFUND'::"text")) AS "refund_count",
    (COALESCE("sum"("cash_in"), (0)::numeric))::numeric(14,2) AS "cash_in",
    (COALESCE("sum"("cash_out"), (0)::numeric))::numeric(14,2) AS "cash_out",
    (COALESCE("sum"("net_cash"), (0)::numeric))::numeric(14,2) AS "net_cash"
   FROM "public"."finance_cash_ledger" "ledger"
  GROUP BY "branch_id", "branch_code", "branch_name", "currency", "month_start";


ALTER VIEW "public"."branch_monthly_cash_summary" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."enrollment_tuition" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "enrollment_id" "uuid" NOT NULL,
    "tuition_plan_id" "uuid" NOT NULL,
    "starts_on" "date" NOT NULL,
    "base_ends_on" "date" NOT NULL,
    "effective_ends_on" "date" NOT NULL,
    "plan_code_snapshot" "text" NOT NULL,
    "plan_name_snapshot" "text" NOT NULL,
    "duration_months_snapshot" integer NOT NULL,
    "amount" numeric(14,2) NOT NULL,
    "currency" "text" DEFAULT 'VND'::"text" NOT NULL,
    "status" "text" DEFAULT 'ACTIVE'::"text" NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "list_price" numeric(14,2) NOT NULL,
    "discount_type" "text" DEFAULT 'NONE'::"text" NOT NULL,
    "discount_value" numeric(14,2) DEFAULT 0 NOT NULL,
    "discount_amount" numeric(14,2) DEFAULT 0 NOT NULL,
    "discount_name" "text",
    "branch_id_snapshot" "uuid" NOT NULL,
    "branch_code_snapshot" "text" NOT NULL,
    "branch_name_snapshot" "text" NOT NULL,
    "legacy_migration_row_id" "uuid",
    "legacy_extension_days" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "enrollment_tuition_amount_calculation_check" CHECK (("amount" = ("list_price" - "discount_amount"))),
    CONSTRAINT "enrollment_tuition_amount_check" CHECK (("amount" >= (0)::numeric)),
    CONSTRAINT "enrollment_tuition_currency_check" CHECK (("currency" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "enrollment_tuition_dates_check" CHECK ((("base_ends_on" >= "starts_on") AND ("effective_ends_on" >= "base_ends_on"))),
    CONSTRAINT "enrollment_tuition_discount_amount_check" CHECK ((("discount_amount" >= (0)::numeric) AND ("discount_amount" <= "list_price"))),
    CONSTRAINT "enrollment_tuition_discount_rules_check" CHECK (((("discount_type" = 'NONE'::"text") AND ("discount_value" = (0)::numeric) AND ("discount_amount" = (0)::numeric) AND ("discount_name" IS NULL)) OR (("discount_type" = 'PERCENT'::"text") AND ("discount_value" >= (0)::numeric) AND ("discount_value" <= (100)::numeric) AND ("discount_name" IS NOT NULL) AND ("btrim"("discount_name") <> ''::"text")) OR (("discount_type" = 'FIXED'::"text") AND ("discount_value" >= (0)::numeric) AND ("discount_value" <= "list_price") AND ("discount_amount" = "discount_value") AND ("discount_name" IS NOT NULL) AND ("btrim"("discount_name") <> ''::"text")))),
    CONSTRAINT "enrollment_tuition_discount_type_check" CHECK (("discount_type" = ANY (ARRAY['NONE'::"text", 'PERCENT'::"text", 'FIXED'::"text"]))),
    CONSTRAINT "enrollment_tuition_discount_value_check" CHECK (("discount_value" >= (0)::numeric)),
    CONSTRAINT "enrollment_tuition_duration_months_snapshot_check" CHECK ((("duration_months_snapshot" > 0) AND ("duration_months_snapshot" <= 60))),
    CONSTRAINT "enrollment_tuition_legacy_extension_days_check" CHECK (("legacy_extension_days" >= 0)),
    CONSTRAINT "enrollment_tuition_list_price_check" CHECK (("list_price" >= (0)::numeric)),
    CONSTRAINT "enrollment_tuition_status_check" CHECK (("status" = ANY (ARRAY['SCHEDULED'::"text", 'ACTIVE'::"text", 'COMPLETED'::"text", 'CANCELLED'::"text"])))
);


ALTER TABLE "public"."enrollment_tuition" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."enrollments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "student_id" "uuid" NOT NULL,
    "class_id" "uuid" NOT NULL,
    "student_curriculum_enrollment_id" "uuid",
    "enrolled_at" "date" DEFAULT CURRENT_DATE NOT NULL,
    "started_at" "date",
    "ended_at" "date",
    "status" "text" DEFAULT 'ACTIVE'::"text" NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "enrollments_dates_check" CHECK ((("ended_at" IS NULL) OR ("started_at" IS NULL) OR ("ended_at" >= "started_at"))),
    CONSTRAINT "enrollments_status_check" CHECK (("status" = ANY (ARRAY['ACTIVE'::"text", 'COMPLETED'::"text", 'WITHDRAWN'::"text"])))
);


ALTER TABLE "public"."enrollments" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."revenue_forecast_months" WITH ("security_invoker"='true') AS
 SELECT ("date_trunc"('month'::"text", "timezone"('Asia/Ho_Chi_Minh'::"text", "now"())))::"date" AS "month_start"
UNION ALL
 SELECT (("date_trunc"('month'::"text", "timezone"('Asia/Ho_Chi_Minh'::"text", "now"())) + '1 mon'::interval))::"date" AS "month_start";


ALTER VIEW "public"."revenue_forecast_months" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."branch_monthly_revenue_forecast" WITH ("security_invoker"='true') AS
 WITH "months" AS (
         SELECT "revenue_forecast_months"."month_start"
           FROM "public"."revenue_forecast_months"
        ), "renewals" AS (
         SELECT "tuition"."branch_id_snapshot" AS "branch_id",
            "tuition"."branch_code_snapshot" AS "branch_code",
            "tuition"."branch_name_snapshot" AS "branch_name",
            "tuition"."currency",
            ("date_trunc"('month'::"text", ("tuition"."effective_ends_on")::timestamp with time zone))::"date" AS "month_start",
            "count"(*) AS "expiring_tuition_count",
            "count"(DISTINCT "enrollment"."student_id") AS "expiring_student_count",
            (COALESCE("sum"("tuition"."amount"), (0)::numeric))::numeric(14,2) AS "projected_renewal_amount"
           FROM ("public"."enrollment_tuition" "tuition"
             JOIN "public"."enrollments" "enrollment" ON (("enrollment"."id" = "tuition"."enrollment_id")))
          WHERE (("tuition"."status" = 'ACTIVE'::"text") AND (NOT (EXISTS ( SELECT 1
                   FROM "public"."opening_receivables" "opening"
                  WHERE ("opening"."tuition_id" = "tuition"."id")))))
          GROUP BY "tuition"."branch_id_snapshot", "tuition"."branch_code_snapshot", "tuition"."branch_name_snapshot", "tuition"."currency", (("date_trunc"('month'::"text", ("tuition"."effective_ends_on")::timestamp with time zone))::"date")
        ), "receivables" AS (
         SELECT "receivable"."branch_id_snapshot" AS "branch_id",
            "receivable"."branch_code_snapshot" AS "branch_code",
            "receivable"."branch_name_snapshot" AS "branch_name",
            "receivable"."currency",
            ("date_trunc"('month'::"text", ("receivable"."due_on")::timestamp with time zone))::"date" AS "month_start",
            "count"(*) FILTER (WHERE ("receivable"."invoice_status" = 'ISSUED'::"text")) AS "invoices_due_count",
            (COALESCE("sum"("receivable"."outstanding_balance") FILTER (WHERE ("receivable"."invoice_status" = 'ISSUED'::"text")), (0)::numeric))::numeric(14,2) AS "expected_cash_due"
           FROM "public"."invoice_receivables" "receivable"
          WHERE ("receivable"."due_on" IS NOT NULL)
          GROUP BY "receivable"."branch_id_snapshot", "receivable"."branch_code_snapshot", "receivable"."branch_name_snapshot", "receivable"."currency", (("date_trunc"('month'::"text", ("receivable"."due_on")::timestamp with time zone))::"date")
        ), "branch_currency" AS (
         SELECT "tuition"."branch_id_snapshot" AS "branch_id",
            "tuition"."branch_code_snapshot" AS "branch_code",
            "tuition"."branch_name_snapshot" AS "branch_name",
            "tuition"."currency"
           FROM "public"."enrollment_tuition" "tuition"
        UNION
         SELECT "receivable"."branch_id_snapshot",
            "receivable"."branch_code_snapshot",
            "receivable"."branch_name_snapshot",
            "receivable"."currency"
           FROM "public"."invoice_receivables" "receivable"
        )
 SELECT "branch_currency"."branch_id",
    "branch_currency"."branch_code",
    "branch_currency"."branch_name",
    "branch_currency"."currency",
    "months"."month_start",
        CASE
            WHEN ("months"."month_start" = ("date_trunc"('month'::"text", "timezone"('Asia/Ho_Chi_Minh'::"text", "now"())))::"date") THEN 'CURRENT_MONTH'::"text"
            ELSE 'NEXT_MONTH'::"text"
        END AS "forecast_period",
    COALESCE("renewals"."expiring_tuition_count", (0)::bigint) AS "expiring_tuition_count",
    COALESCE("renewals"."expiring_student_count", (0)::bigint) AS "expiring_student_count",
    (COALESCE("renewals"."projected_renewal_amount", (0)::numeric))::numeric(14,2) AS "projected_renewal_amount",
    COALESCE("receivables"."invoices_due_count", (0)::bigint) AS "invoices_due_count",
    (COALESCE("receivables"."expected_cash_due", (0)::numeric))::numeric(14,2) AS "expected_cash_due",
    ((COALESCE("renewals"."projected_renewal_amount", (0)::numeric) + COALESCE("receivables"."expected_cash_due", (0)::numeric)))::numeric(14,2) AS "gross_forecast_opportunity"
   FROM ((("branch_currency"
     CROSS JOIN "months")
     LEFT JOIN "renewals" ON ((("renewals"."branch_id" = "branch_currency"."branch_id") AND ("renewals"."currency" = "branch_currency"."currency") AND ("renewals"."month_start" = "months"."month_start"))))
     LEFT JOIN "receivables" ON ((("receivables"."branch_id" = "branch_currency"."branch_id") AND ("receivables"."currency" = "branch_currency"."currency") AND ("receivables"."month_start" = "months"."month_start"))));


ALTER VIEW "public"."branch_monthly_revenue_forecast" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."invoice_only_branch_receivable_summary" WITH ("security_invoker"='true') AS
 SELECT "branch_id_snapshot" AS "branch_id",
    "branch_code_snapshot" AS "branch_code",
    "branch_name_snapshot" AS "branch_name",
    "currency",
    "count"(*) FILTER (WHERE ("invoice_status" = 'ISSUED'::"text")) AS "issued_invoice_count",
    "count"(*) FILTER (WHERE ("receivable_status" = 'OVERDUE'::"text")) AS "overdue_invoice_count",
    (COALESCE("sum"("total_amount") FILTER (WHERE ("invoice_status" = 'ISSUED'::"text")), (0)::numeric))::numeric(14,2) AS "total_invoiced",
    (COALESCE("sum"("allocated_amount") FILTER (WHERE ("invoice_status" = 'ISSUED'::"text")), (0)::numeric))::numeric(14,2) AS "total_paid",
    (COALESCE("sum"("outstanding_balance") FILTER (WHERE ("invoice_status" = 'ISSUED'::"text")), (0)::numeric))::numeric(14,2) AS "total_outstanding",
    (COALESCE("sum"("outstanding_balance") FILTER (WHERE ("receivable_status" = 'OVERDUE'::"text")), (0)::numeric))::numeric(14,2) AS "total_overdue"
   FROM "public"."invoice_receivables" "receivable"
  GROUP BY "branch_id_snapshot", "branch_code_snapshot", "branch_name_snapshot", "currency";


ALTER VIEW "public"."invoice_only_branch_receivable_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."branch_receivable_summary" WITH ("security_invoker"='true') AS
 SELECT "branch_id",
    "branch_code",
    "branch_name",
    "currency",
    ("sum"("issued_invoice_count"))::bigint AS "issued_invoice_count",
    ("sum"("overdue_invoice_count"))::bigint AS "overdue_invoice_count",
    ("sum"("total_invoiced"))::numeric(14,2) AS "total_invoiced",
    ("sum"("total_paid"))::numeric(14,2) AS "total_paid",
    ("sum"("total_outstanding"))::numeric(14,2) AS "total_outstanding",
    ("sum"("total_overdue"))::numeric(14,2) AS "total_overdue"
   FROM ( SELECT "invoice_only_branch_receivable_summary"."branch_id",
            "invoice_only_branch_receivable_summary"."branch_code",
            "invoice_only_branch_receivable_summary"."branch_name",
            "invoice_only_branch_receivable_summary"."currency",
            "invoice_only_branch_receivable_summary"."issued_invoice_count",
            "invoice_only_branch_receivable_summary"."overdue_invoice_count",
            "invoice_only_branch_receivable_summary"."total_invoiced",
            "invoice_only_branch_receivable_summary"."total_paid",
            "invoice_only_branch_receivable_summary"."total_outstanding",
            "invoice_only_branch_receivable_summary"."total_overdue"
           FROM "public"."invoice_only_branch_receivable_summary"
        UNION ALL
         SELECT "o"."branch_id",
            "b"."code",
            "b"."name",
            "o"."currency",
            (0)::bigint AS "int8",
            (0)::bigint AS "int8",
            (0)::numeric(14,2) AS "numeric",
            (0)::numeric(14,2) AS "numeric",
            "o"."outstanding_balance",
            (0)::numeric(14,2) AS "numeric"
           FROM ("public"."opening_receivable_balances" "o"
             JOIN "public"."branches" "b" ON (("b"."id" = "o"."branch_id")))
          WHERE (NOT "o"."reversed")) "combined"
  GROUP BY "branch_id", "branch_code", "branch_name", "currency";


ALTER VIEW "public"."branch_receivable_summary" OWNER TO "postgres";


