CREATE TABLE IF NOT EXISTS "public"."crm_campaigns" (
    "id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "platform" "text" NOT NULL,
    "channel" "text",
    "branch_id" "uuid",
    "starts_on" "date",
    "ends_on" "date",
    "budget_amount" numeric,
    "currency" "text",
    "status" "text" DEFAULT 'DRAFT'::"text" NOT NULL,
    "utm_source" "text",
    "utm_medium" "text",
    "utm_campaign" "text",
    "utm_content" "text",
    "version" integer DEFAULT 1 NOT NULL,
    "created_by" "uuid" NOT NULL,
