CREATE OR REPLACE VIEW "public"."customer_credit_balances" WITH ("security_invoker"='true') AS
 SELECT "c"."id",
    "c"."student_id",
    "c"."branch_id",
    "c"."currency",
    "c"."payment_id",
    "c"."source_allocation_id",
    "c"."opening_receivable_id",
    "c"."correction_id",
    "c"."cause_request_id",
    "c"."settlement_id",
    "c"."amount",
    "c"."created_at",
    "c"."created_by",
    (COALESCE("u"."applied", (0)::numeric))::numeric(14,2) AS "applied_amount",
    (COALESCE("u"."refunded", (0)::numeric))::numeric(14,2) AS "refunded_amount",
    (
        CASE
            WHEN ("p"."status" = 'VOIDED'::"text") THEN (0)::numeric
            ELSE (("c"."amount" - COALESCE("u"."applied", (0)::numeric)) - COALESCE("u"."refunded", (0)::numeric))
        END)::numeric(14,2) AS "remaining_credit",
    ("c"."payment_id" IS NULL) AS "legacy_settlement_credit",
    "p"."status" AS "payment_status",
    (
        CASE
            WHEN ("p"."status" = 'VOIDED'::"text") THEN "c"."amount"
            ELSE (0)::numeric
        END)::numeric(14,2) AS "voided_amount"
   FROM (("public"."customer_credits" "c"
     LEFT JOIN "public"."payments" "p" ON (("p"."id" = "c"."payment_id")))
     LEFT JOIN LATERAL ( SELECT "sum"(
                CASE
                    WHEN (("u_1"."kind" = 'APPLY'::"text") AND ("p"."status" = 'POSTED'::"text")) THEN "u_1"."amount"
                    ELSE (0)::numeric
                END) AS "applied",
            "sum"(
                CASE
                    WHEN (("u_1"."kind" = 'REFUND'::"text") AND ("r"."status" = 'POSTED'::"text")) THEN "u_1"."amount"
                    ELSE (0)::numeric
                END) AS "refunded"
           FROM ("public"."customer_credit_uses" "u_1"
             LEFT JOIN "public"."refunds" "r" ON (("r"."id" = "u_1"."refund_id")))
          WHERE ("u_1"."credit_id" = "c"."id")) "u" ON (true));


ALTER VIEW "public"."customer_credit_balances" OWNER TO "postgres";


