CREATE OR REPLACE VIEW "public"."employee_directory" WITH ("security_invoker"='true') AS
 SELECT "e"."id",
    "e"."employee_code",
    "e"."home_unit",
    "e"."hire_date",
    "e"."profile_id",
    "e"."teacher_id",
    "e"."created_at",
    "e"."created_by",
    "v"."full_name",
    "v"."unit_code",
    "v"."employee_group",
    "v"."employment_status",
    "v"."end_date",
    "v"."pay_type",
    "v"."operational_role_id",
    "v"."effective_on",
    "v"."version",
    "latest"."version" AS "latest_version",
    "latest"."effective_on" AS "latest_effective_on"
   FROM (("public"."employees" "e"
     LEFT JOIN LATERAL ( SELECT "employee_versions"."id",
            "employee_versions"."employee_id",
            "employee_versions"."version",
            "employee_versions"."effective_on",
            "employee_versions"."full_name",
            "employee_versions"."unit_code",
            "employee_versions"."employee_group",
            "employee_versions"."employment_status",
            "employee_versions"."end_date",
            "employee_versions"."pay_type",
            "employee_versions"."operational_role_id",
            "employee_versions"."reason",
            "employee_versions"."created_at",
            "employee_versions"."created_by"
           FROM "public"."employee_versions"
          WHERE (("employee_versions"."employee_id" = "e"."id") AND ("employee_versions"."effective_on" <= (("now"() AT TIME ZONE 'Asia/Ho_Chi_Minh'::"text"))::"date"))
          ORDER BY "employee_versions"."effective_on" DESC, "employee_versions"."version" DESC
         LIMIT 1) "v" ON (true))
     LEFT JOIN LATERAL ( SELECT "employee_versions"."version",
            "employee_versions"."effective_on"
           FROM "public"."employee_versions"
          WHERE ("employee_versions"."employee_id" = "e"."id")
          ORDER BY "employee_versions"."version" DESC
         LIMIT 1) "latest" ON (true));


ALTER VIEW "public"."employee_directory" OWNER TO "postgres";


