CREATE OR REPLACE VIEW "public"."invoice_only_student_receivable_summary" WITH ("security_invoker"='true') AS
 SELECT "student_id_snapshot" AS "student_id",
    "currency",
    "count"(*) FILTER (WHERE ("invoice_status" = 'ISSUED'::"text")) AS "issued_invoice_count",
    "count"(*) FILTER (WHERE ("receivable_status" = 'UNPAID'::"text")) AS "unpaid_invoice_count",
    "count"(*) FILTER (WHERE ("receivable_status" = 'PARTIALLY_PAID'::"text")) AS "partially_paid_invoice_count",
    "count"(*) FILTER (WHERE ("receivable_status" = 'OVERDUE'::"text")) AS "overdue_invoice_count",
    "count"(*) FILTER (WHERE ("receivable_status" = 'PAID'::"text")) AS "paid_invoice_count",
    (COALESCE("sum"("total_amount") FILTER (WHERE ("invoice_status" = 'ISSUED'::"text")), (0)::numeric))::numeric(14,2) AS "total_invoiced",
    (COALESCE("sum"("allocated_amount") FILTER (WHERE ("invoice_status" = 'ISSUED'::"text")), (0)::numeric))::numeric(14,2) AS "total_paid",
    (COALESCE("sum"("outstanding_balance") FILTER (WHERE ("invoice_status" = 'ISSUED'::"text")), (0)::numeric))::numeric(14,2) AS "total_outstanding",
    (COALESCE("sum"("outstanding_balance") FILTER (WHERE ("receivable_status" = 'OVERDUE'::"text")), (0)::numeric))::numeric(14,2) AS "total_overdue"
   FROM "public"."invoice_receivables" "receivable"
  GROUP BY "student_id_snapshot", "currency";


ALTER VIEW "public"."invoice_only_student_receivable_summary" OWNER TO "postgres";


