CREATE OR REPLACE VIEW "public"."learning_effective_assessment_results" WITH ("security_invoker"='true') AS
 SELECT "a"."id",
    "a"."assessment_id",
    "a"."student_id",
    "a"."question_snapshot",
    "a"."policy_snapshot",
    "a"."answers",
    COALESCE("r"."corrected_state", "a"."state") AS "state",
    COALESCE("r"."corrected_score", "a"."score") AS "score",
    COALESCE("r"."evidence", "a"."evidence") AS "evidence",
    "a"."started_at",
    "a"."submitted_at",
    "a"."completed_at",
    "r"."id" AS "revision_id",
    "r"."created_at" AS "regraded_at"
   FROM ("public"."learning_assessment_attempts" "a"
     LEFT JOIN LATERAL ( SELECT "r_1"."id",
            "r_1"."attempt_id",
            "r_1"."previous_regrade_id",
            "r_1"."prior_score",
            "r_1"."corrected_score",
            "r_1"."prior_state",
            "r_1"."corrected_state",
            "r_1"."marks",
            "r_1"."evidence",
            "r_1"."reason",
            "r_1"."reviewer_id",
            "r_1"."created_at"
           FROM "public"."learning_assessment_regrades" "r_1"
          WHERE ("r_1"."attempt_id" = "a"."id")
          ORDER BY "r_1"."created_at" DESC, "r_1"."id" DESC
         LIMIT 1) "r" ON (true));


ALTER VIEW "public"."learning_effective_assessment_results" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."learning_final_shadow_outcomes" WITH ("security_invoker"='true') AS
 SELECT "id" AS "attempt_id",
    "student_id",
    (("policy_snapshot" ->> 'version_id'::"text"))::"uuid" AS "version_id",
    "revision_id",
    "score",
        CASE
            WHEN ("state" = 'PASSED'::"text") THEN 'PASS'::"text"
            ELSE 'NOT_PASSED'::"text"
        END AS "proposed_outcome",
    'SHADOW'::"text" AS "mode"
   FROM "public"."learning_effective_assessment_results" "a"
  WHERE ((("policy_snapshot" ->> 'kind'::"text") = 'FINAL'::"text") AND ("state" = ANY (ARRAY['PASSED'::"text", 'FAILED'::"text"])) AND "public"."has_role"('SUPER_ADMIN'::"text"));


