CREATE OR REPLACE VIEW "public"."learning_academic_reconciliation" WITH ("security_invoker"='true') AS
 SELECT "outcome"."attempt_id",
    "outcome"."student_id",
    "outcome"."version_id",
    "outcome"."revision_id",
    "outcome"."score",
    "outcome"."proposed_outcome",
    "v"."level_id",
    "m"."subject_id",
    "s"."name" AS "subject_name",
    "e"."enrollment_count",
    "p"."progress_count",
    "p"."actual_status",
        CASE
            WHEN ("m"."version_id" IS NULL) THEN 'UNMAPPED'::"text"
            WHEN (("s"."level_id" IS DISTINCT FROM "v"."level_id") OR ("s"."status" IS DISTINCT FROM 'ACTIVE'::"text") OR ("s"."completion_rule" IS DISTINCT FROM 'DIRECT_ASSESSMENT'::"text") OR ("l"."status" IS DISTINCT FROM 'ACTIVE'::"text") OR ("c"."status" IS DISTINCT FROM 'ACTIVE'::"text")) THEN 'INACTIVE_OR_CHANGED_REQUIREMENT'::"text"
            WHEN ("e"."enrollment_count" = 0) THEN 'NO_ACADEMIC_ENROLLMENT'::"text"
            WHEN ("e"."enrollment_count" > 1) THEN 'AMBIGUOUS_ACADEMIC_ENROLLMENT'::"text"
            WHEN ("p"."progress_count" <> 1) THEN 'NO_UNIQUE_SUBJECT_PROGRESS'::"text"
            WHEN (("outcome"."proposed_outcome" = 'PASS'::"text") AND ("p"."actual_status" = ANY (ARRAY['PASS'::"text", 'EXEMPT'::"text"]))) THEN 'MATCH'::"text"
            WHEN (("outcome"."proposed_outcome" = 'NOT_PASSED'::"text") AND ("p"."actual_status" = 'NOT_PASSED'::"text")) THEN 'MATCH'::"text"
            ELSE 'DIFFERENCE_REVIEW_REQUIRED'::"text"
        END AS "reconciliation_status",
    'SHADOW_ONLY'::"text" AS "mode"
   FROM ((((((("public"."learning_final_shadow_outcomes" "outcome"
     JOIN "public"."learning_versions" "v" ON (("v"."id" = "outcome"."version_id")))
     JOIN "public"."curriculum_levels" "l" ON (("l"."id" = "v"."level_id")))
     JOIN "public"."curriculums" "c" ON (("c"."id" = "l"."curriculum_id")))
     LEFT JOIN "public"."learning_academic_mappings" "m" ON (("m"."version_id" = "v"."id")))
     LEFT JOIN "public"."curriculum_subjects" "s" ON (("s"."id" = "m"."subject_id")))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "enrollment_count"
           FROM "public"."student_curriculum_enrollments" "e_1"
          WHERE (("e_1"."student_id" = "outcome"."student_id") AND ("e_1"."curriculum_id" = "l"."curriculum_id") AND ("e_1"."status" = ANY (ARRAY['ACTIVE'::"text", 'PAUSED'::"text", 'COMPLETED'::"text"])))) "e" ON (true))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "progress_count",
            "min"("sp"."status") AS "actual_status"
           FROM (("public"."student_subject_progress" "sp"
             JOIN "public"."student_level_progress" "lp" ON (("lp"."id" = "sp"."level_progress_id")))
             JOIN "public"."student_curriculum_enrollments" "en" ON (("en"."id" = "lp"."enrollment_id")))
          WHERE (("en"."student_id" = "outcome"."student_id") AND ("en"."curriculum_id" = "l"."curriculum_id") AND ("en"."status" = ANY (ARRAY['ACTIVE'::"text", 'PAUSED'::"text", 'COMPLETED'::"text"])) AND ("lp"."level_id" = "v"."level_id") AND ("sp"."subject_id" = "m"."subject_id"))) "p" ON (true))
  WHERE "public"."has_role"('SUPER_ADMIN'::"text");


