CREATE OR REPLACE VIEW "public"."session_actual_teachers" WITH ("security_invoker"='true') AS
 SELECT "o"."id" AS "session_id",
    "sc"."class_id",
    "c"."branch_id",
    "o"."occurrence_date",
    "o"."starts_at",
    "o"."ends_at",
    "o"."status",
    "o"."schedule_id",
    "o"."room_id",
    "o"."notes",
    "o"."occurrence_type",
    "o"."source_occurrence_id",
    "primary_teacher"."teacher_id" AS "primary_teacher_id",
        CASE
            WHEN ("snap"."session_id" IS NOT NULL) THEN "snap"."teacher_id"
            ELSE COALESCE("a"."teacher_id", "primary_teacher"."teacher_id")
        END AS "teacher_id",
        CASE
            WHEN ("snap"."session_id" IS NOT NULL) THEN "snap"."assignment_type"
            ELSE COALESCE("a"."assignment_type", 'PRIMARY'::"text")
        END AS "assignment_type",
    "a"."reason",
    "a"."assigned_by",
    "a"."assigned_at",
    ("snap"."session_id" IS NOT NULL) AS "is_locked"
   FROM ((((("public"."session_occurrences" "o"
     JOIN "public"."schedules" "sc" ON (("sc"."id" = "o"."schedule_id")))
     JOIN "public"."classes" "c" ON (("c"."id" = "sc"."class_id")))
     LEFT JOIN "public"."session_teacher_assignments" "a" ON ((("a"."session_id" = "o"."id") AND ("a"."effective_status" = 'ACTIVE'::"text"))))
     LEFT JOIN "public"."session_teacher_snapshots" "snap" ON (("snap"."session_id" = "o"."id")))
     LEFT JOIN LATERAL ( SELECT ("array_agg"("ct"."teacher_id"))[1] AS "teacher_id"
           FROM "public"."class_teachers" "ct"
          WHERE (("ct"."class_id" = "c"."id") AND ("ct"."teacher_role" = 'PRIMARY'::"text") AND ("ct"."assigned_at" <= "o"."occurrence_date") AND (("ct"."ended_at" IS NULL) OR ("ct"."ended_at" >= "o"."occurrence_date")) AND ("ct"."is_active" OR ("ct"."ended_at" IS NOT NULL)))
         HAVING ("count"(*) = 1)) "primary_teacher" ON (true));


ALTER VIEW "public"."session_actual_teachers" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."learning_journal_teachers" WITH ("security_invoker"='true') AS
 SELECT "j"."id" AS "journal_id",
    "v"."session_id",
    "v"."teacher_id",
    "v"."assignment_type"
   FROM (("public"."learning_journals" "j"
     JOIN "public"."attendance_records" "a" ON (("a"."id" = "j"."attendance_record_id")))
     JOIN "public"."session_actual_teachers" "v" ON (("v"."session_id" = "a"."session_occurrence_id")));


