    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "student_id" "uuid" NOT NULL,
    "enrollment_id" "uuid" NOT NULL,
    "curriculum_enrollment_id" "uuid",
    "branch_id" "uuid" NOT NULL,
    "report_type" "text" NOT NULL,
    "period_start" "date" NOT NULL,
    "period_end" "date" NOT NULL,
    "status" "text" DEFAULT 'DRAFT'::"text" NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "draft_data" "jsonb" NOT NULL,
    "snapshot_data" "jsonb",
    "teacher_summary" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "admin_note" "text" DEFAULT ''::"text" NOT NULL,
    "generated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "generated_by" "uuid" NOT NULL,
    "approved_at" timestamp with time zone,
    "approved_by" "uuid",
    "sent_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "learning_reports_admin_note_check" CHECK (("char_length"("admin_note") <= 4000)),
    CONSTRAINT "learning_reports_approval_snapshot_check" CHECK (((("status" = ANY (ARRAY['APPROVED'::"text", 'PUBLISHED'::"text"])) AND ("snapshot_data" IS NOT NULL) AND ("approved_at" IS NOT NULL) AND ("approved_by" IS NOT NULL)) OR (("status" <> ALL (ARRAY['APPROVED'::"text", 'PUBLISHED'::"text"])) AND ("snapshot_data" IS NULL) AND ("approved_at" IS NULL) AND ("approved_by" IS NULL)))),
    CONSTRAINT "learning_reports_check" CHECK (("period_end" >= "period_start")),
    CONSTRAINT "learning_reports_report_type_check" CHECK (("report_type" = ANY (ARRAY['MONTHLY'::"text", 'END_OF_COURSE'::"text"]))),
    CONSTRAINT "learning_reports_sent_at_state_check" CHECK (((("status" = 'PUBLISHED'::"text") AND ("sent_at" IS NOT NULL)) OR (("status" <> 'PUBLISHED'::"text") AND ("sent_at" IS NULL)))),
    CONSTRAINT "learning_reports_status_check" CHECK (("status" = ANY (ARRAY['DRAFT'::"text", 'READY_FOR_REVIEW'::"text", 'APPROVED'::"text", 'PUBLISHED'::"text", 'CANCELLED'::"text"]))),
    CONSTRAINT "learning_reports_teacher_summary_check" CHECK ((("jsonb_typeof"("teacher_summary") = 'object'::"text") AND ("octet_length"(("teacher_summary")::"text") <= 20000))),
    CONSTRAINT "learning_reports_version_check" CHECK (("version" > 0))
);


