CREATE OR REPLACE VIEW "public"."learning_report_list" WITH ("security_invoker"='true') AS
 SELECT "r"."id",
    "r"."student_id",
    "r"."enrollment_id",
    "r"."branch_id",
    "r"."report_type",
    "r"."status",
    "r"."period_start",
    "r"."period_end",
    "r"."generated_at",
    "r"."approved_at",
    ((COALESCE("r"."snapshot_data", "r"."draft_data") -> 'student'::"text") ->> 'name'::"text") AS "student_name",
    ((COALESCE("r"."snapshot_data", "r"."draft_data") -> 'student'::"text") ->> 'code'::"text") AS "student_code",
    ((COALESCE("r"."snapshot_data", "r"."draft_data") -> 'branch'::"text") ->> 'name'::"text") AS "branch_name",
    "e"."class_id",
    COALESCE((COALESCE("r"."snapshot_data", "r"."draft_data") ->> 'class_name'::"text"), "class_row"."name") AS "class_name",
    ((COALESCE("r"."snapshot_data", "r"."draft_data") -> 'academic'::"text") ->> 'current_grade'::"text") AS "current_grade",
    ((COALESCE("r"."snapshot_data", "r"."draft_data") -> 'academic'::"text") ->> 'status'::"text") AS "academic_status",
    ((COALESCE("r"."snapshot_data", "r"."draft_data") -> 'academic'::"text") ->> 'curriculum'::"text") AS "curriculum_name",
    ( SELECT "string_agg"(COALESCE(("teacher"."value" ->> 'name'::"text"), ("teacher"."value" ->> 'code'::"text")), ', '::"text" ORDER BY ("teacher"."value" ->> 'role'::"text"), ("teacher"."value" ->> 'code'::"text")) AS "string_agg"
           FROM "jsonb_array_elements"(COALESCE((COALESCE("r"."snapshot_data", "r"."draft_data") -> 'teachers'::"text"), '[]'::"jsonb")) "teacher"("value")) AS "teacher_names"
   FROM (("public"."learning_reports" "r"
     LEFT JOIN "public"."enrollments" "e" ON (("e"."id" = "r"."enrollment_id")))
     LEFT JOIN "public"."classes" "class_row" ON (("class_row"."id" = "e"."class_id")));


ALTER VIEW "public"."learning_report_list" OWNER TO "postgres";


