CREATE TABLE IF NOT EXISTS "public"."makeup_credits" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "enrollment_id" "uuid" NOT NULL,
    "source_occurrence_id" "uuid" NOT NULL,
    "source_attendance_record_id" "uuid",
    "source_reason" "text" NOT NULL,
    "status" "text" DEFAULT 'AVAILABLE'::"text" NOT NULL,
    "reserved_occurrence_id" "uuid",
    "reserved_at" timestamp with time zone,
    "used_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "notes" "text",
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "makeup_credits_excused_attendance_check" CHECK (((("source_reason" = 'EXCUSED'::"text") AND ("source_attendance_record_id" IS NOT NULL)) OR (("source_reason" = 'SESSION_CANCELLED'::"text") AND ("source_attendance_record_id" IS NULL)))),
    CONSTRAINT "makeup_credits_reservation_state_check" CHECK (((("status" = 'AVAILABLE'::"text") AND ("reserved_occurrence_id" IS NULL) AND ("reserved_at" IS NULL) AND ("used_at" IS NULL) AND ("cancelled_at" IS NULL)) OR (("status" = 'RESERVED'::"text") AND ("reserved_occurrence_id" IS NOT NULL) AND ("reserved_at" IS NOT NULL) AND ("used_at" IS NULL) AND ("cancelled_at" IS NULL)) OR (("status" = 'USED'::"text") AND ("reserved_occurrence_id" IS NOT NULL) AND ("reserved_at" IS NOT NULL) AND ("used_at" IS NOT NULL) AND ("cancelled_at" IS NULL)) OR (("status" = 'CANCELLED'::"text") AND ("reserved_occurrence_id" IS NULL) AND ("used_at" IS NULL) AND ("cancelled_at" IS NOT NULL)))),
    CONSTRAINT "makeup_credits_source_reason_check" CHECK (("source_reason" = ANY (ARRAY['EXCUSED'::"text", 'SESSION_CANCELLED'::"text"]))),
    CONSTRAINT "makeup_credits_status_check" CHECK (("status" = ANY (ARRAY['AVAILABLE'::"text", 'RESERVED'::"text", 'USED'::"text", 'CANCELLED'::"text"])))
);


