    CONSTRAINT "migration_batch_rows_source_reference_check" CHECK ((("length"("btrim"("source_reference")) >= 1) AND ("length"("btrim"("source_reference")) <= 200))),
    CONSTRAINT "migration_batch_rows_status_check" CHECK (("status" = ANY (ARRAY['NEEDS_REVIEW'::"text", 'VALIDATED'::"text", 'READY'::"text", 'IMPORTED'::"text", 'REJECTED'::"text", 'ROLLED_BACK'::"text"])))
