    CONSTRAINT "students_status_check" CHECK (("status" = ANY (ARRAY['ACTIVE'::"text", 'INACTIVE'::"text", 'PAUSED'::"text", 'GRADUATED'::"text", 'ARCHIVED'::"text"])))
);


