CREATE OR REPLACE VIEW "public"."migration_row_preview" WITH ("security_invoker"='true') AS
 SELECT "r"."id" AS "row_id",
    "r"."batch_id",
    "r"."status",
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "public"."migration_source_mappings" "m"
              WHERE (("m"."source_system" = "b"."source_system") AND ("m"."source_entity_type" = "r"."source_entity_type") AND ("m"."source_reference" = "r"."source_reference")))) THEN 'EXACT_MATCH'::"text"
            WHEN (EXISTS ( SELECT 1
               FROM "public"."students" "s"
              WHERE ("s"."student_code" = ("r"."normalized_payload" ->> 'student_code'::"text")))) THEN 'STRONG_MATCH'::"text"
            WHEN (EXISTS ( SELECT 1
               FROM "public"."students" "s"
              WHERE ("lower"("btrim"("s"."full_name")) = "lower"("btrim"(("r"."normalized_payload" ->> 'full_name'::"text")))))) THEN 'POSSIBLE_DUPLICATE'::"text"
            ELSE 'NO_MATCH'::"text"
        END AS "duplicate_status",
    ("r"."normalized_payload" ->> 'currency'::"text") AS "currency",
        CASE
            WHEN (("r"."status" = ANY (ARRAY['VALIDATED'::"text", 'READY'::"text"])) AND ("r"."validation_result" = '[]'::"jsonb") AND (NOT (EXISTS ( SELECT 1
               FROM "public"."migration_source_mappings" "m"
              WHERE (("m"."source_system" = "b"."source_system") AND ("m"."source_entity_type" = "r"."source_entity_type") AND ("m"."source_reference" = "r"."source_reference")))))) THEN 1
            ELSE 0
        END AS "expected_new_units",
        CASE
            WHEN (("r"."status" = ANY (ARRAY['VALIDATED'::"text", 'READY'::"text"])) AND ("r"."validation_result" = '[]'::"jsonb")) THEN (("r"."normalized_payload" ->> 'final_amount'::"text"))::numeric
            ELSE NULL::numeric
        END AS "expected_amount",
        CASE
            WHEN (("r"."status" = ANY (ARRAY['VALIDATED'::"text", 'READY'::"text"])) AND ("r"."validation_result" = '[]'::"jsonb")) THEN (("r"."normalized_payload" ->> 'opening_paid_amount'::"text"))::numeric
            ELSE NULL::numeric
        END AS "expected_paid",
        CASE
            WHEN (("r"."status" = ANY (ARRAY['VALIDATED'::"text", 'READY'::"text"])) AND ("r"."validation_result" = '[]'::"jsonb")) THEN (("r"."normalized_payload" ->> 'opening_outstanding'::"text"))::numeric
            ELSE NULL::numeric
        END AS "expected_outstanding"
   FROM ("public"."migration_batch_rows" "r"
     JOIN "public"."migration_batches" "b" ON (("b"."id" = "r"."batch_id")));


ALTER VIEW "public"."migration_row_preview" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."migration_dry_run_summary" WITH ("security_invoker"='true') AS
 SELECT "batch_id",
    "currency",
    "sum"("expected_new_units") AS "expected_students",
    "sum"("expected_new_units") AS "expected_enrollments",
    "sum"("expected_new_units") AS "expected_academic_baselines",
    "sum"("expected_new_units") AS "expected_tuition_terms",
    COALESCE("sum"("expected_amount") FILTER (WHERE ("expected_new_units" = 1)), (0)::numeric) AS "expected_new_amount",
    COALESCE("sum"("expected_paid") FILTER (WHERE ("expected_new_units" = 1)), (0)::numeric) AS "expected_new_paid",
    COALESCE("sum"("expected_outstanding") FILTER (WHERE ("expected_new_units" = 1)), (0)::numeric) AS "expected_new_outstanding",
    "count"(*) FILTER (WHERE ("duplicate_status" = 'EXACT_MATCH'::"text")) AS "exact_matches",
    "count"(*) FILTER (WHERE ("duplicate_status" = 'STRONG_MATCH'::"text")) AS "strong_matches",
    "count"(*) FILTER (WHERE ("duplicate_status" = 'POSSIBLE_DUPLICATE'::"text")) AS "possible_duplicates"
   FROM "public"."migration_row_preview"
  GROUP BY "batch_id", "currency";


ALTER VIEW "public"."migration_dry_run_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."migration_reconciliation" WITH ("security_invoker"='true') AS
 SELECT "r"."id" AS "row_id",
    "r"."batch_id",
    "r"."status",
    "r"."target_student_id",
    "r"."target_enrollment_id",
    "r"."target_tuition_id",
    "o"."currency",
    "o"."amount" AS "imported_amount",
    (COALESCE("s"."amount", (0)::numeric))::numeric(14,2) AS "imported_paid",
    (("o"."amount" - COALESCE("s"."amount", (0)::numeric)))::numeric(14,2) AS "imported_outstanding",
        CASE
            WHEN ("r"."status" = 'IMPORTED'::"text") THEN ("o"."amount" - (("r"."normalized_payload" ->> 'final_amount'::"text"))::numeric)
            ELSE NULL::numeric
        END AS "amount_difference",
        CASE
            WHEN ("r"."status" = 'IMPORTED'::"text") THEN (COALESCE("s"."amount", (0)::numeric) - (("r"."normalized_payload" ->> 'opening_paid_amount'::"text"))::numeric)
            ELSE NULL::numeric
        END AS "paid_difference",
        CASE
            WHEN ("r"."status" = 'IMPORTED'::"text") THEN (("o"."amount" - COALESCE("s"."amount", (0)::numeric)) - (("r"."normalized_payload" ->> 'opening_outstanding'::"text"))::numeric)
            ELSE NULL::numeric
        END AS "outstanding_difference"
   FROM (("public"."migration_batch_rows" "r"
     LEFT JOIN "public"."opening_receivables" "o" ON (("o"."tuition_id" = "r"."target_tuition_id")))
     LEFT JOIN "public"."opening_settlements" "s" ON (("s"."receivable_id" = "o"."id")));


ALTER VIEW "public"."migration_reconciliation" OWNER TO "postgres";


