    "cancelled_at" timestamp with time zone,
    "cancel_reason" "text",
    CONSTRAINT "operating_expense_record_actual_state" CHECK (((("status" = 'DRAFT'::"text") AND ("actual_amount" IS NULL) AND ("recorded_by" IS NULL) AND ("recorded_at" IS NULL) AND ("cancelled_by" IS NULL) AND ("cancelled_at" IS NULL) AND ("cancel_reason" IS NULL)) OR (("status" = 'RECORDED'::"text") AND ("actual_amount" IS NOT NULL) AND ("actual_amount" > (0)::numeric) AND ("actual_amount" <> 'NaN'::numeric) AND ("actual_amount" = "round"("actual_amount", 2)) AND (("currency" <> 'VND'::"text") OR ("actual_amount" = "trunc"("actual_amount"))) AND ("recorded_by" IS NOT NULL) AND ("recorded_at" IS NOT NULL) AND ("cancelled_by" IS NULL) AND ("cancelled_at" IS NULL) AND ("cancel_reason" IS NULL)) OR (("status" = 'CANCELLED'::"text") AND ("cancelled_by" IS NOT NULL) AND ("cancelled_at" IS NOT NULL) AND (("char_length"("btrim"("cancel_reason")) >= 1) AND ("char_length"("btrim"("cancel_reason")) <= 2000))))),
    CONSTRAINT "operating_expense_record_expected_scale" CHECK ((("expected_amount" IS NULL) OR (("expected_amount" = "round"("expected_amount", 2)) AND ("expected_amount" >= (0)::numeric) AND (("currency" <> 'VND'::"text") OR ("expected_amount" = "trunc"("expected_amount")))))),
    CONSTRAINT "operating_expense_records_currency_check" CHECK (("currency" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "operating_expense_records_due_date_check" CHECK ((("due_date" IS NULL) OR "isfinite"("due_date"))),
    CONSTRAINT "operating_expense_records_expense_date_check" CHECK ((("expense_date" IS NULL) OR "isfinite"("expense_date"))),
    CONSTRAINT "operating_expense_records_expense_month_check" CHECK (("isfinite"("expense_month") AND (EXTRACT(day FROM "expense_month") = (1)::numeric))),
    CONSTRAINT "operating_expense_records_note_check" CHECK ((("note" IS NULL) OR (("char_length"("btrim"("note")) >= 1) AND ("char_length"("btrim"("note")) <= 2000)))),
    CONSTRAINT "operating_expense_records_reference_check" CHECK ((("reference" IS NULL) OR (("char_length"("btrim"("reference")) >= 1) AND ("char_length"("btrim"("reference")) <= 200)))),
    CONSTRAINT "operating_expense_records_status_check" CHECK (("status" = ANY (ARRAY['DRAFT'::"text", 'RECORDED'::"text", 'CANCELLED'::"text"]))),
    CONSTRAINT "operating_expense_records_version_check" CHECK (("version" > 0))
);


