    "period_id" "uuid" NOT NULL,
    "status" "text" NOT NULL,
    "note" "text" NOT NULL,
    "actor_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "event_type" "text" DEFAULT 'LEGACY'::"text" NOT NULL,
    "override_type" "text",
    "override_reason" "text",
    "before_snapshot" "jsonb",
    "after_snapshot" "jsonb",
    CONSTRAINT "payroll_override_audit_required" CHECK (((("event_type" = 'EMERGENCY_OVERRIDE'::"text") AND ("override_type" = 'MAKER_CHECKER_EMERGENCY'::"text") AND ("override_type" IS NOT NULL) AND ("override_reason" IS NOT NULL) AND (("char_length"("btrim"("override_reason")) >= 1) AND ("char_length"("btrim"("override_reason")) <= 2000)) AND ("before_snapshot" IS NOT NULL) AND ("after_snapshot" IS NOT NULL)) OR (("event_type" <> 'EMERGENCY_OVERRIDE'::"text") AND ("override_type" IS NULL) AND ("override_reason" IS NULL))))
);


ALTER TABLE "public"."payroll_events" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."payroll_off_cycle_correction_runs" WITH ("security_invoker"='true') AS
 SELECT "id",
    "original_payroll_id",
    "currency",
    "delta" AS "correction_amount",
    "reason",
    "maker_user_id",
    "checker_user_id",
    "created_at",
    "approved_at",
    "posted_at",
    'FINALIZED'::"text" AS "status"
   FROM "public"."payroll_corrections"
  WHERE ("run_type" = 'OFF_CYCLE_CORRECTION'::"text");


ALTER VIEW "public"."payroll_off_cycle_correction_runs" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."payroll_period_actions_v2" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "period_id" "uuid" NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "component_code" "text" NOT NULL,
    "category" "text" NOT NULL,
    "source_type" "text" NOT NULL,
    "source_expense_claim_id" "uuid",
    "amount" numeric(16,2) NOT NULL,
    "currency" "text" NOT NULL,
    "reason" "text" NOT NULL,
    "status" "text" DEFAULT 'ACTIVE'::"text" NOT NULL,
    "request_key" "uuid" NOT NULL,
    "request_payload" "jsonb" NOT NULL,
    "source_snapshot" "jsonb",
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "cancelled_by" "uuid",
    "cancelled_at" timestamp with time zone,
    "cancel_reason" "text",
    "approved_by" "uuid",
    "approved_at" timestamp with time zone,
    "source_retroactive_claim_id" "uuid",
    CONSTRAINT "payroll_period_actions_v2_amount_check" CHECK ((("amount" > (0)::numeric) AND ("amount" <= 999999999999.99) AND ("amount" <> 'NaN'::numeric))),
    CONSTRAINT "payroll_period_actions_v2_approval_pair" CHECK (((("approved_by" IS NULL) AND ("approved_at" IS NULL)) OR (("approved_by" IS NOT NULL) AND ("approved_at" IS NOT NULL)))),
    CONSTRAINT "payroll_period_actions_v2_cancel_reason_check" CHECK ((("cancel_reason" IS NULL) OR (("char_length"("btrim"("cancel_reason")) >= 1) AND ("char_length"("btrim"("cancel_reason")) <= 2000)))),
    CONSTRAINT "payroll_period_actions_v2_cancel_state" CHECK (((("status" = 'ACTIVE'::"text") AND ("cancelled_by" IS NULL) AND ("cancelled_at" IS NULL) AND ("cancel_reason" IS NULL)) OR (("status" = 'CANCELLED'::"text") AND ("cancelled_by" IS NOT NULL) AND ("cancelled_at" IS NOT NULL) AND ("cancel_reason" IS NOT NULL)))),
    CONSTRAINT "payroll_period_actions_v2_category_check" CHECK (("category" = ANY (ARRAY['EARNING'::"text", 'REIMBURSEMENT'::"text"]))),
    CONSTRAINT "payroll_period_actions_v2_currency_check" CHECK (("currency" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "payroll_period_actions_v2_reason_check" CHECK ((("char_length"("btrim"("reason")) >= 1) AND ("char_length"("btrim"("reason")) <= 2000))),
    CONSTRAINT "payroll_period_actions_v2_source_shape" CHECK (((("source_type" = 'MANUAL_BONUS'::"text") AND ("component_code" = 'BONUS'::"text") AND ("category" = 'EARNING'::"text") AND ("source_expense_claim_id" IS NULL) AND ("source_retroactive_claim_id" IS NULL)) OR (("source_type" = 'EXPENSE_CLAIM'::"text") AND ("component_code" = 'TRAVEL_EXPENSE'::"text") AND ("category" = 'REIMBURSEMENT'::"text") AND ("source_expense_claim_id" IS NOT NULL) AND ("source_retroactive_claim_id" IS NULL) AND ("source_snapshot" IS NOT NULL)) OR (("source_type" = 'RETROACTIVE_PAY'::"text") AND ("component_code" = 'RETROACTIVE_PAY'::"text") AND ("category" = 'EARNING'::"text") AND ("source_expense_claim_id" IS NULL) AND ("source_retroactive_claim_id" IS NOT NULL) AND ("source_snapshot" IS NOT NULL)))),
    CONSTRAINT "payroll_period_actions_v2_source_type_check" CHECK (("source_type" = ANY (ARRAY['MANUAL_BONUS'::"text", 'EXPENSE_CLAIM'::"text", 'RETROACTIVE_PAY'::"text"]))),
    CONSTRAINT "payroll_period_actions_v2_status_check" CHECK (("status" = ANY (ARRAY['ACTIVE'::"text", 'CANCELLED'::"text"])))
);


ALTER TABLE "public"."payroll_period_actions_v2" OWNER TO "postgres";


COMMENT ON TABLE "public"."payroll_period_actions_v2" IS 'Period-specific Payroll V2 actions. BONUS is manual period earning; TRAVEL_EXPENSE is reimbursement posted from an APPROVED expense claim. APPROVED claim/posting does not prove payment.';



CREATE OR REPLACE VIEW "public"."payroll_period_summary" AS
SELECT
    NULL::"uuid" AS "id",
    NULL::"uuid" AS "branch_id",
    NULL::"date" AS "starts_on",
    NULL::"date" AS "ends_on",
    NULL::"text" AS "status",
    NULL::"text" AS "currency",
    NULL::bigint AS "teacher_count",
    NULL::numeric AS "gross_amount",
    NULL::numeric AS "monthly_total",
    NULL::numeric AS "hourly_total",
    NULL::numeric AS "adjustments";


ALTER VIEW "public"."payroll_period_summary" OWNER TO "postgres";


