CREATE TABLE IF NOT EXISTS "public"."registration_deposit_terms" (
    "application_id" "uuid" NOT NULL,
    "branch_id" "uuid" NOT NULL,
    "tuition_plan_id" "uuid" NOT NULL,
    "price_id" "uuid" NOT NULL,
    "tuition_amount" bigint NOT NULL,
    "deposit_due" bigint GENERATED ALWAYS AS ((("tuition_amount" + 1) / 2)) STORED,
    "currency" "text" DEFAULT 'VND'::"text" NOT NULL,
    "quoted_by" "uuid" NOT NULL,
    "quoted_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "list_amount" bigint NOT NULL,
    "discount_type" "text" DEFAULT 'NONE'::"text" NOT NULL,
    "discount_value" numeric(14,2) DEFAULT 0 NOT NULL,
    "discount_name" "text",
    "discount_amount" bigint DEFAULT 0 NOT NULL,
    "payment_option" "text" NOT NULL,
    "amount_due" bigint NOT NULL,
    CONSTRAINT "registration_deposit_terms_currency_check" CHECK (("currency" = 'VND'::"text")),
    CONSTRAINT "registration_deposit_terms_discount_check" CHECK ((("discount_type" = ANY (ARRAY['NONE'::"text", 'PERCENT'::"text", 'FIXED'::"text"])) AND ("discount_value" >= (0)::numeric) AND ("discount_amount" >= 0) AND ("list_amount" = ("tuition_amount" + "discount_amount")) AND ("list_amount" <= 100000000) AND (("discount_type" = 'NONE'::"text") OR (NULLIF("btrim"("discount_name"), ''::"text") IS NOT NULL)))),
    CONSTRAINT "registration_deposit_terms_payment_option_check" CHECK ((("payment_option" = ANY (ARRAY['DEPOSIT_50'::"text", 'FULL'::"text"])) AND ("amount_due" > 0) AND ((("payment_option" = 'DEPOSIT_50'::"text") AND ("amount_due" = "deposit_due")) OR (("payment_option" = 'FULL'::"text") AND ("amount_due" = "tuition_amount"))))),
    CONSTRAINT "registration_deposit_terms_tuition_amount_check" CHECK (("tuition_amount" > 0)),
    CONSTRAINT "registration_deposit_terms_tuition_amount_check1" CHECK (("tuition_amount" <= 100000000))
);


ALTER TABLE "public"."registration_deposit_terms" OWNER TO "postgres";


