CREATE TABLE IF NOT EXISTS "public"."staff_compensation_components" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "component_code" "text" NOT NULL,
    "branch_id" "uuid",
    "calculation_method" "text" NOT NULL,
    "amount" numeric(16,2),
    "rate" numeric(16,2),
    "percentage" numeric(9,4),
    "basis_component_code" "text",
    "currency" "text",
    "class_type" "text",
    "effective_from" "date" NOT NULL,
    "effective_to" "date",
    "status" "text" DEFAULT 'ACTIVE'::"text" NOT NULL,
    "reason" "text" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    CONSTRAINT "staff_combined_insurance_fixed_method" CHECK ((("component_code" <> 'SOCIAL_LABOR_INSURANCE'::"text") OR ("calculation_method" = 'FIXED_AMOUNT'::"text"))),
    CONSTRAINT "staff_compensation_class_type_shape" CHECK ((("class_type" IS NULL) OR ("calculation_method" = 'PER_SESSION'::"text"))),
    CONSTRAINT "staff_compensation_components_calculation_method_check" CHECK (("calculation_method" = ANY (ARRAY['FIXED_AMOUNT'::"text", 'PER_SESSION'::"text", 'PER_HOUR'::"text", 'PERCENTAGE'::"text"]))),
    CONSTRAINT "staff_compensation_components_check" CHECK ((("effective_to" IS NULL) OR ("isfinite"("effective_to") AND ("effective_to" >= "effective_from")))),
    CONSTRAINT "staff_compensation_components_class_type_check" CHECK ((("class_type" IS NULL) OR ("class_type" = ANY (ARRAY['ONE_ON_ONE'::"text", 'GROUP'::"text"])))),
    CONSTRAINT "staff_compensation_components_effective_from_check" CHECK ("isfinite"("effective_from")),
    CONSTRAINT "staff_compensation_components_no_fixed_pay" CHECK (("component_code" <> 'FIXED_PAY'::"text")),
    CONSTRAINT "staff_compensation_components_reason_check" CHECK ((("char_length"("btrim"("reason")) >= 1) AND ("char_length"("btrim"("reason")) <= 2000))),
    CONSTRAINT "staff_compensation_components_status_check" CHECK (("status" = ANY (ARRAY['ACTIVE'::"text", 'INACTIVE'::"text"]))),
    CONSTRAINT "staff_compensation_value_shape" CHECK (((("calculation_method" = 'FIXED_AMOUNT'::"text") AND ("amount" IS NOT NULL) AND ("amount" > (0)::numeric) AND ("amount" <> 'NaN'::numeric) AND ("rate" IS NULL) AND ("percentage" IS NULL) AND ("currency" ~ '^[A-Z]{3}$'::"text") AND ("basis_component_code" IS NULL)) OR (("calculation_method" = ANY (ARRAY['PER_SESSION'::"text", 'PER_HOUR'::"text"])) AND ("rate" IS NOT NULL) AND ("rate" > (0)::numeric) AND ("rate" <> 'NaN'::numeric) AND ("amount" IS NULL) AND ("percentage" IS NULL) AND ("currency" ~ '^[A-Z]{3}$'::"text") AND ("basis_component_code" IS NULL)) OR (("calculation_method" = 'PERCENTAGE'::"text") AND ("percentage" IS NOT NULL) AND ("percentage" > (0)::numeric) AND ("percentage" <= (100)::numeric) AND ("percentage" <> 'NaN'::numeric) AND ("amount" IS NULL) AND ("rate" IS NULL) AND ("currency" IS NULL) AND ("basis_component_code" IS NOT NULL)))),
    CONSTRAINT "staff_insurance_active_branch_required" CHECK ((("status" <> 'ACTIVE'::"text") OR ("component_code" <> ALL (ARRAY['SOCIAL_INSURANCE'::"text", 'LABOR_INSURANCE'::"text", 'SOCIAL_LABOR_INSURANCE'::"text"])) OR ("branch_id" IS NOT NULL)))
);


