CREATE OR REPLACE VIEW "public"."student_receivable_summary" WITH ("security_invoker"='true') AS
 SELECT "student_id",
    "currency",
    ("sum"("issued_invoice_count"))::bigint AS "issued_invoice_count",
    ("sum"("unpaid_invoice_count"))::bigint AS "unpaid_invoice_count",
    ("sum"("partially_paid_invoice_count"))::bigint AS "partially_paid_invoice_count",
    ("sum"("overdue_invoice_count"))::bigint AS "overdue_invoice_count",
    ("sum"("paid_invoice_count"))::bigint AS "paid_invoice_count",
    ("sum"("total_invoiced"))::numeric(14,2) AS "total_invoiced",
    ("sum"("total_paid"))::numeric(14,2) AS "total_paid",
    ("sum"("total_outstanding"))::numeric(14,2) AS "total_outstanding",
    ("sum"("total_overdue"))::numeric(14,2) AS "total_overdue"
   FROM ( SELECT "invoice_only_student_receivable_summary"."student_id",
            "invoice_only_student_receivable_summary"."currency",
            "invoice_only_student_receivable_summary"."issued_invoice_count",
            "invoice_only_student_receivable_summary"."unpaid_invoice_count",
            "invoice_only_student_receivable_summary"."partially_paid_invoice_count",
            "invoice_only_student_receivable_summary"."overdue_invoice_count",
            "invoice_only_student_receivable_summary"."paid_invoice_count",
            "invoice_only_student_receivable_summary"."total_invoiced",
            "invoice_only_student_receivable_summary"."total_paid",
            "invoice_only_student_receivable_summary"."total_outstanding",
            "invoice_only_student_receivable_summary"."total_overdue"
           FROM "public"."invoice_only_student_receivable_summary"
        UNION ALL
         SELECT "o"."student_id",
            "o"."currency",
            (0)::bigint AS "int8",
            (0)::bigint AS "int8",
            (0)::bigint AS "int8",
            (0)::bigint AS "int8",
            (0)::bigint AS "int8",
            (0)::numeric(14,2) AS "numeric",
            (0)::numeric(14,2) AS "numeric",
            "o"."outstanding_balance",
            (0)::numeric(14,2) AS "numeric"
           FROM "public"."opening_receivable_balances" "o"
          WHERE (NOT "o"."reversed")) "combined"
  GROUP BY "student_id", "currency";


ALTER VIEW "public"."student_receivable_summary" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."student_retention_alerts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "student_id" "uuid" NOT NULL,
    "enrollment_id" "uuid" NOT NULL,
    "branch_id" "uuid" NOT NULL,
    "class_id" "uuid" NOT NULL,
    "rule_code" "text" NOT NULL,
    "severity" "text" DEFAULT 'HIGH'::"text" NOT NULL,
    "status" "text" DEFAULT 'NEW'::"text" NOT NULL,
    "first_signal_on" "date" NOT NULL,
    "last_signal_on" "date" NOT NULL,
    "consecutive_absence_count" integer NOT NULL,
    "evidence_snapshot" "jsonb" NOT NULL,
    "owner_user_id" "uuid",
    "follow_up_on" "date",
    "latest_contact_channel" "text",
    "latest_note" "text",
    "resolution_code" "text",
    "detected_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "last_detected_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "resolved_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    CONSTRAINT "student_retention_alert_dates" CHECK (("first_signal_on" <= "last_signal_on")),
    CONSTRAINT "student_retention_alerts_consecutive_absence_count_check" CHECK (("consecutive_absence_count" >= 2)),
    CONSTRAINT "student_retention_alerts_latest_contact_channel_check" CHECK ((("latest_contact_channel" IS NULL) OR ("latest_contact_channel" = ANY (ARRAY['PHONE'::"text", 'ZALO'::"text", 'SMS'::"text", 'EMAIL'::"text", 'IN_PERSON'::"text", 'OTHER'::"text"])))),
    CONSTRAINT "student_retention_alerts_latest_note_check" CHECK ((("latest_note" IS NULL) OR (("char_length"("btrim"("latest_note")) >= 1) AND ("char_length"("btrim"("latest_note")) <= 4000)))),
    CONSTRAINT "student_retention_alerts_resolution_code_check" CHECK ((("resolution_code" IS NULL) OR ("resolution_code" = ANY (ARRAY['RETURNED_TO_CLASS'::"text", 'CONTINUING'::"text", 'TRANSFERRED'::"text", 'WITHDRAWN'::"text", 'FALSE_POSITIVE'::"text", 'OTHER'::"text"])))),
    CONSTRAINT "student_retention_alerts_rule_code_check" CHECK (("rule_code" = 'CONSECUTIVE_ABSENCE_2'::"text")),
    CONSTRAINT "student_retention_alerts_severity_check" CHECK (("severity" = ANY (ARRAY['MEDIUM'::"text", 'HIGH'::"text", 'CRITICAL'::"text"]))),
    CONSTRAINT "student_retention_alerts_status_check" CHECK (("status" = ANY (ARRAY['NEW'::"text", 'CONTACTED'::"text", 'FOLLOW_UP'::"text", 'RESOLVED'::"text", 'LOST'::"text", 'DISMISSED'::"text"]))),
    CONSTRAINT "student_retention_resolution_shape" CHECK (((("status" = ANY (ARRAY['RESOLVED'::"text", 'LOST'::"text", 'DISMISSED'::"text"])) AND ("resolved_at" IS NOT NULL)) OR (("status" <> ALL (ARRAY['RESOLVED'::"text", 'LOST'::"text", 'DISMISSED'::"text"])) AND ("resolved_at" IS NULL))))
);


ALTER TABLE "public"."student_retention_alerts" OWNER TO "postgres";


