CREATE OR REPLACE VIEW "public"."tuition_reminder_operations" WITH ("security_invoker"='true') AS
 SELECT "r"."id",
    "r"."enrollment_tuition_id",
    "r"."window_start",
    "r"."window_end",
    "r"."status",
    "r"."marked_at",
    "r"."reason",
    "et"."enrollment_id",
    "et"."tuition_plan_id",
    "et"."starts_on",
    "et"."effective_ends_on",
    "et"."plan_name_snapshot",
    "et"."branch_id_snapshot",
    "et"."branch_name_snapshot",
    "et"."amount",
    "et"."currency",
    "e"."student_id",
    "s"."full_name",
    "s"."student_code",
    "r"."event_code",
    "et"."duration_months_snapshot",
        CASE
            WHEN (("r"."event_code" = 'BALANCE_50_V1'::"text") AND ("et"."duration_months_snapshot" = 12)) THEN "r"."window_start"
            WHEN (("r"."event_code" = 'RENEWAL_V1'::"text") AND ("et"."duration_months_snapshot" = 3)) THEN ("r"."window_start" + 14)
            ELSE NULL::"date"
        END AS "red_on",
    "state"."reply_choice",
    "state"."submit_time" AS "reply_submit_time",
    "state"."needs_review" AS "reply_needs_review",
    "state"."contact_note",
    "state"."contact_noted_at",
    "note_author"."full_name" AS "contact_noted_by_name"
   FROM ((((("public"."tuition_reminders" "r"
     JOIN "public"."enrollment_tuition" "et" ON (("et"."id" = "r"."enrollment_tuition_id")))
     JOIN "public"."enrollments" "e" ON (("e"."id" = "et"."enrollment_id")))
     JOIN "public"."students" "s" ON (("s"."id" = "e"."student_id")))
     LEFT JOIN "public"."tuition_zalo_reply_states" "state" ON (("state"."reminder_id" = "r"."id")))
     LEFT JOIN "public"."profiles" "note_author" ON (("note_author"."id" = "state"."contact_noted_by")));


ALTER VIEW "public"."tuition_reminder_operations" OWNER TO "postgres";


