CREATE OR REPLACE VIEW "public"."payroll_period_summary" WITH ("security_invoker"='true') AS
 SELECT "p"."id",
    "p"."branch_id",
    "p"."starts_on",
    "p"."ends_on",
    "p"."status",
    "t"."currency",
    "count"("t"."id") AS "teacher_count",
    COALESCE("sum"("t"."gross_amount"), (0)::numeric) AS "gross_amount",
    COALESCE("sum"("t"."base_salary"), (0)::numeric) AS "monthly_total",
    COALESCE("sum"("t"."hourly_earnings"), (0)::numeric) AS "hourly_total",
    COALESCE("sum"("t"."adjustment_amount"), (0)::numeric) AS "adjustments"
   FROM ("public"."payroll_periods" "p"
     LEFT JOIN "public"."teacher_payrolls" "t" ON (("t"."period_id" = "p"."id")))
  GROUP BY "p"."id", "t"."currency";



