CREATE POLICY "trip_cost_read" ON "public"."payroll_trip_cost_breakdowns" FOR SELECT TO "authenticated" USING (("public"."account_is_active"() AND (EXISTS ( SELECT 1
   FROM (("public"."payroll_adjustments" "a"
     JOIN "public"."teacher_payrolls" "t" ON (("t"."id" = "a"."payroll_id")))
     JOIN "public"."payroll_periods" "p" ON (("p"."id" = "t"."period_id")))
  WHERE (("a"."id" = "payroll_trip_cost_breakdowns"."adjustment_id") AND ("public"."has_role"('SUPER_ADMIN'::"text") OR "public"."has_role_permission"('FINANCE'::"text", 'payroll.view'::"text", "t"."branch_id") OR (("p"."status" = ANY (ARRAY['APPROVED'::"text", 'FINALIZED'::"text"])) AND ("public"."can_read_employee_payroll"("t"."employee_id", "t"."branch_id") OR "public"."can_read_own_payroll"("t"."teacher_id", "t"."branch_id")))))))));



